--
-- Name: adjust_batch_stock_atomic("uuid", numeric, "text", "uuid", "text", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."adjust_batch_stock_atomic"("p_batch_id" "uuid", "p_quantity_change" numeric, "p_transaction_type" "text", "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_operation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("new_stock" numeric, "transaction_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch public.batches%ROWTYPE;
  v_transaction_id uuid;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(
    ARRAY['admin', 'accounts', 'warehouse', 'manager']
  ) THEN
    RAISE EXCEPTION 'Permission denied for stock adjustment';
  END IF;
  IF p_transaction_type IS DISTINCT FROM 'adjustment' THEN
    RAISE EXCEPTION 'Manual inventory entry supports Stock Adjustment only';
  END IF;
  IF COALESCE(p_quantity_change, 0) = 0 THEN
    RAISE EXCEPTION 'Stock adjustment cannot be zero';
  END IF;

  SELECT *
  INTO v_batch
  FROM public.batches
  WHERE id = p_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Batch not found';
  END IF;

  v_transaction_id := public.post_inventory_movement(
    p_operation_id,
    v_batch.product_id,
    v_batch.id,
    'adjustment',
    p_quantity_change,
    CURRENT_DATE,
    NULL,
    'stock_adjustment',
    p_reference_id,
    p_notes,
    COALESCE(p_created_by, auth.uid()),
    NULL,
    NULL
  );

  SELECT current_stock
  INTO new_stock
  FROM public.batches
  WHERE id = p_batch_id;

  transaction_id := v_transaction_id;
  RETURN NEXT;
END;
$$;


