--
-- Name: allocate_import_costs_to_batches("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."allocate_import_costs_to_batches"("p_container_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_container RECORD;
v_batch RECORD;
v_total_invoice_value DECIMAL(18,2);
v_total_import_cost DECIMAL(18,2);
v_linked_expenses_total DECIMAL(18,2);
v_linked_petty_cash_total DECIMAL(18,2);
v_broker_canonical_total DECIMAL(18,2);
v_allocation_percentage DECIMAL(10,6);
v_allocated_cost DECIMAL(18,2);
v_batches_allocated INTEGER := 0;
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot allocate import costs', v_role;
END IF;

SELECT * INTO v_container
FROM import_containers
WHERE id = p_container_id;

IF NOT FOUND THEN
RETURN json_build_object('success', false, 'error', 'Container not found');
END IF;

IF v_container.status != 'draft' THEN
RETURN json_build_object('success', false, 'error', 'Container already allocated or locked');
END IF;

-- Linked finance expenses (NULL = included, TRUE = included, FALSE = excluded)
-- For broker expenses, compute canonical accountingExpenseTotal in SQL
WITH canonical_expenses AS (
SELECT
fe.id,
fe.expense_category,
fe.amount,
fe.ppn_amount,
fe.stamp_duty_amount,
fe.broker_items,
CASE
WHEN fe.expense_category = 'import_broker' THEN
-- accountingExpenseTotal = brokerInvoiceAmount - headerPpn + sum(brokerLineExpenseBase) + stampDuty
-- brokerLineExpenseBase = brokerLineTotal - item.ppn_amount
-- brokerLineTotal = item.amount (when invoice_amount_authoritative) else amount != 0 ? amount : dpp + ppn
fe.amount - COALESCE(fe.ppn_amount, 0)
+ COALESCE((
SELECT SUM(
CASE
WHEN (item->>'invoice_amount_authoritative')::boolean = true
THEN (item->>'amount')::numeric
ELSE COALESCE(NULLIF((item->>'amount')::numeric, 0), (item->>'dpp_amount')::numeric + (item->>'ppn_amount')::numeric)
END
- COALESCE((item->>'ppn_amount')::numeric, 0)
)
FROM jsonb_array_elements(fe.broker_items) AS item
), 0)
+ COALESCE(fe.stamp_duty_amount, 0)
ELSE
COALESCE(fe.amount, 0)
END AS canonical_total
FROM finance_expenses fe
WHERE fe.import_container_id = p_container_id
AND fe.expense_category != 'pib_import'
AND COALESCE(fe.include_in_landed_cost, true) = true
)
SELECT COALESCE(SUM(canonical_total), 0) INTO v_linked_expenses_total
FROM canonical_expenses;

-- Linked petty cash (NULL = included, TRUE = included, FALSE = excluded)
SELECT COALESCE(SUM(amount), 0) INTO v_linked_petty_cash_total
FROM petty_cash_transactions
WHERE import_container_id = p_container_id
AND COALESCE(include_in_landed_cost, true) = true;

v_total_import_cost := v_linked_expenses_total + v_linked_petty_cash_total + COALESCE(v_container.other_import_costs, 0);

IF v_total_import_cost = 0 THEN
RETURN json_build_object('success', false, 'error', 'No import costs to allocate');
END IF;

SELECT COALESCE(SUM(import_price * import_quantity), 0) INTO v_total_invoice_value
FROM batches
WHERE import_container_id = p_container_id;

IF v_total_invoice_value = 0 THEN
RETURN json_build_object('success', false, 'error', 'No batches linked to this container');
END IF;

FOR v_batch IN
SELECT id, import_price, import_quantity, (import_price * import_quantity) as batch_invoice_value
FROM batches
WHERE import_container_id = p_container_id
AND COALESCE(cost_locked, false) = false
LOOP
v_allocation_percentage := (v_batch.batch_invoice_value / v_total_invoice_value) * 100;
v_allocated_cost := (v_total_import_cost * v_batch.batch_invoice_value) / v_total_invoice_value;

INSERT INTO import_container_allocations (
container_id, batch_id, batch_invoice_value,
allocation_percentage, allocated_cost, allocated_by
) VALUES (
p_container_id, v_batch.id, v_batch.batch_invoice_value,
v_allocation_percentage, v_allocated_cost, auth.uid()
)
ON CONFLICT (container_id, batch_id)
DO UPDATE SET
allocation_percentage = EXCLUDED.allocation_percentage,
allocated_cost = EXCLUDED.allocated_cost;

UPDATE batches
SET import_cost_allocated = v_allocated_cost,
final_landed_cost = import_price + v_allocated_cost,
cost_locked = true
WHERE id = v_batch.id;

v_batches_allocated := v_batches_allocated + 1;
END LOOP;

UPDATE import_containers
SET status = 'allocated',
locked_at = now(),
locked_by = auth.uid(),
allocated_expenses = v_total_import_cost
WHERE id = p_container_id;

RETURN json_build_object(
'success', true,
'batches_allocated', v_batches_allocated,
'total_cost', v_total_import_cost,
'linked_expenses_total', v_linked_expenses_total,
'linked_petty_cash_total', v_linked_petty_cash_total,
'other_import_costs', COALESCE(v_container.other_import_costs, 0),
'note', 'Canonical broker calculation; PIB excluded; NULL=included'
);
END;
$$;


--
-- Name: apply_advance_to_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."apply_advance_to_invoice"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r record; v_applied numeric := 0; v_remaining numeric; v_take numeric;
BEGIN
  IF NEW.sales_order_id IS NULL THEN RETURN NEW; END IF;
  FOR r IN SELECT id, receipt_voucher_id, allocated_amount
             FROM public.voucher_allocations
            WHERE sales_order_id = NEW.sales_order_id AND voucher_type = 'receipt'
            ORDER BY created_at, id
  LOOP
    v_remaining := NEW.total_amount - v_applied;
    EXIT WHEN v_remaining <= 0;
    v_take := LEAST(r.allocated_amount, v_remaining);
    IF v_take >= r.allocated_amount THEN
      DELETE FROM public.voucher_allocations WHERE id = r.id;
    ELSE
      UPDATE public.voucher_allocations SET allocated_amount = allocated_amount - v_take WHERE id = r.id;
    END IF;
    INSERT INTO public.voucher_allocations(voucher_type, receipt_voucher_id, sales_invoice_id, allocated_amount)
      VALUES ('receipt', r.receipt_voucher_id, NEW.id, v_take);
    v_applied := v_applied + v_take;
  END LOOP;
  IF v_applied > 0 THEN
    UPDATE public.sales_invoices
       SET paid_amount = v_applied,
           balance_amount = total_amount - v_applied,
           payment_status = CASE WHEN v_applied >= total_amount THEN 'paid' ELSE 'partial' END,
           updated_at = now()
     WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: apply_batch_receipt_weighted_average("uuid", numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."apply_batch_receipt_weighted_average"("p_batch_id" "uuid", "p_received_quantity" numeric, "p_receipt_unit_cost" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  b public.batches%ROWTYPE;
  prior_qty numeric;
  prior_cost numeric;
  new_cost numeric;
BEGIN
  SELECT * INTO b FROM public.batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR p_received_quantity <= 0 THEN RETURN; END IF;
  prior_qty := GREATEST(COALESCE(b.current_stock,0) - p_received_quantity, 0);
  prior_cost := COALESCE(NULLIF(b.landed_cost_per_unit,0), NULLIF(b.cost_per_unit,0), NULLIF(b.import_price,0), 0);
  new_cost := CASE WHEN prior_qty <= 0 THEN p_receipt_unit_cost
    ELSE ((prior_qty * prior_cost) + (p_received_quantity * p_receipt_unit_cost))
      / NULLIF(prior_qty + p_received_quantity,0) END;
  UPDATE public.batches
     SET cost_per_unit=round(new_cost,2), landed_cost_per_unit=round(new_cost,2), updated_at=now()
   WHERE id=p_batch_id AND COALESCE(cost_locked,false)=false;
END; $$;


--
-- Name: FUNCTION "apply_batch_receipt_weighted_average"("p_batch_id" "uuid", "p_received_quantity" numeric, "p_receipt_unit_cost" numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."apply_batch_receipt_weighted_average"("p_batch_id" "uuid", "p_received_quantity" numeric, "p_receipt_unit_cost" numeric) IS 'Future physical-batch moving weighted average; receipt layers remain separately auditable.';


--
-- Name: apply_import_costs_to_batches("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."apply_import_costs_to_batches"("p_header_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_item RECORD;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot apply import costs', v_role;
END IF;

FOR v_item IN
SELECT * FROM import_cost_items WHERE cost_header_id = p_header_id AND batch_id IS NOT NULL
LOOP
UPDATE batches
SET
cost_per_unit = v_item.final_landed_cost_per_unit,
updated_at = NOW()
WHERE id = v_item.batch_id;

INSERT INTO inventory_transactions (
product_id, batch_id, transaction_type, quantity, transaction_date,
reference_number, reference_type, reference_id, notes, created_by,
stock_before, stock_after
)
SELECT
v_item.product_id,
v_item.batch_id,
'cost_adjustment',
0,
CURRENT_DATE,
(SELECT cost_sheet_number FROM import_cost_headers WHERE id = p_header_id),
'import_cost',
p_header_id,
'Import cost allocation: Duty=' || v_item.allocated_duty ||
', PPN=' || v_item.allocated_ppn ||
', Freight=' || v_item.allocated_freight,
(SELECT created_by FROM import_cost_headers WHERE id = p_header_id),
(SELECT current_stock FROM batches WHERE id = v_item.batch_id),
(SELECT current_stock FROM batches WHERE id = v_item.batch_id);
END LOOP;
END;
$$;


--
-- Name: FUNCTION "apply_import_costs_to_batches"("p_header_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."apply_import_costs_to_batches"("p_header_id" "uuid") IS 'Updates batch cost_per_unit with allocated import costs (landed cost). Creates audit trail in inventory_transactions.';


--
-- Name: apply_receipt_allocation_rounding_adjustment("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."apply_receipt_allocation_rounding_adjustment"("p_invoice_id" "uuid", "p_receipt_voucher_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice record;
  v_allocated numeric(18,2);
  v_residual numeric(18,2);
  v_tolerance numeric(18,2);
  v_existing record;
  v_entry_id uuid;
  v_entry_number text;
  v_ar_account_id uuid;
  v_adjustment_account_id uuid;
  v_user_id uuid;
BEGIN
  SELECT *
  INTO v_invoice
  FROM public.sales_invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT COALESCE(rounding_tolerance_amount, 0)
  INTO v_tolerance
  FROM public.app_settings
  LIMIT 1;
  v_tolerance := COALESCE(v_tolerance, 0);

  SELECT *
  INTO v_existing
  FROM public.invoice_rounding_adjustments
  WHERE sales_invoice_id = p_invoice_id
     OR (p_receipt_voucher_id IS NOT NULL AND receipt_voucher_id = p_receipt_voucher_id)
  LIMIT 1;

  v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);
  v_residual := ROUND(COALESCE(v_invoice.total_amount, 0) - COALESCE(v_allocated, 0), 2);

  IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance THEN
    IF v_existing.id IS NOT NULL AND v_existing.adjustment_amount = v_residual THEN
      PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);
      RETURN;
    END IF;

    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;
    IF v_existing.id IS NOT NULL THEN
      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
    END IF;

    SELECT id INTO v_ar_account_id
    FROM public.chart_of_accounts
    WHERE code = '1120'
    LIMIT 1;

    IF v_residual > 0 THEN
      SELECT COALESCE(
        (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),
        (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)
      )
      INTO v_adjustment_account_id;
    ELSE
      SELECT COALESCE(
        (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),
        (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)
      )
      INTO v_adjustment_account_id;
    END IF;

    IF v_ar_account_id IS NULL OR v_adjustment_account_id IS NULL THEN
      RAISE EXCEPTION 'Missing account setup for invoice rounding adjustment';
    END IF;

    v_user_id := COALESCE(auth.uid(), v_invoice.created_by);
    v_entry_number := public.next_journal_entry_number();

    INSERT INTO public.journal_entries (
      entry_number, entry_date, source_module, reference_id, reference_number,
      description, total_debit, total_credit, is_posted, posted_by, created_by
    ) VALUES (
      v_entry_number,
      COALESCE(v_invoice.invoice_date, CURRENT_DATE),
      'sales_invoice_rounding',
      v_invoice.id,
      v_invoice.invoice_number,
      'Receipt allocation rounding adjustment: ' || v_invoice.invoice_number,
      ABS(v_residual),
      ABS(v_residual),
      true,
      v_user_id,
      v_user_id
    )
    RETURNING id INTO v_entry_id;

    IF v_residual > 0 THEN
      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
      VALUES
        (v_entry_id, 1, v_adjustment_account_id, 'Rounding write-off - ' || v_invoice.invoice_number, ABS(v_residual), 0, v_invoice.customer_id),
        (v_entry_id, 2, v_ar_account_id, 'A/R rounding clearance - ' || v_invoice.invoice_number, 0, ABS(v_residual), v_invoice.customer_id);
    ELSE
      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
      VALUES
        (v_entry_id, 1, v_ar_account_id, 'A/R rounding clearance - ' || v_invoice.invoice_number, ABS(v_residual), 0, v_invoice.customer_id),
        (v_entry_id, 2, v_adjustment_account_id, 'Rounding gain - ' || v_invoice.invoice_number, 0, ABS(v_residual), v_invoice.customer_id);
    END IF;

    INSERT INTO public.invoice_rounding_adjustments (
      receipt_voucher_id, sales_invoice_id, adjustment_amount, journal_entry_id, created_by
    ) VALUES (
      p_receipt_voucher_id, p_invoice_id, v_residual, v_entry_id, v_user_id
    );
  ELSE
    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;
    IF v_existing.id IS NOT NULL THEN
      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
    END IF;
  END IF;

  PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);
END;
$$;


--
-- Name: apply_salary_advances_to_expense("uuid", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."apply_salary_advances_to_expense"("p_salary_expense_id" "uuid", "p_apply" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_salary public.finance_expenses%ROWTYPE;
  v_staff_name text;
  v_remaining numeric;
  v_total numeric := 0;
  v_settlement jsonb;
  v_settlement_id uuid;
  v_advance record;
  v_advance_applied numeric;
  v_available numeric;
  v_to_apply numeric;
  v_currency text;
  v_application_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  PERFORM public._sec_check_finance_role();
  SELECT * INTO v_salary FROM public.finance_expenses WHERE id=p_salary_expense_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Salary expense not found'; END IF;
  IF v_salary.expense_category<>'salary' OR v_salary.staff_id IS NULL THEN
    RAISE EXCEPTION 'Salary advances require a Salary expense with a selected staff member';
  END IF;
  SELECT full_name INTO v_staff_name FROM public.finance_staff_master WHERE id=v_salary.staff_id;
  SELECT upper(COALESCE(v_salary.transaction_currency,v_salary.currency_code,'IDR')) INTO v_currency;

  SELECT greatest(v_salary.amount-COALESCE(v_salary.pph_amount,0)-COALESCE(sum(applied_amount),0),0)
    INTO v_remaining FROM public.salary_advance_applications WHERE salary_expense_id=p_salary_expense_id;
  v_remaining:=COALESCE(v_remaining,greatest(v_salary.amount-COALESCE(v_salary.pph_amount,0),0));
  IF NOT p_apply OR v_remaining<=0 THEN
    RETURN jsonb_build_object('applied',false,'total_applied',0,'remaining_salary',v_remaining);
  END IF;

  FOR v_advance IN
    SELECT pv.id,pv.voucher_number,pv.voucher_date,pv.amount
      FROM public.payment_vouchers pv
     WHERE pv.payment_purpose='salary_advance' AND pv.is_posted=true AND pv.staff_id=v_salary.staff_id
       AND NOT EXISTS(SELECT 1 FROM public.salary_advance_applications existing
         WHERE existing.advance_payment_voucher_id=pv.id AND existing.salary_expense_id=p_salary_expense_id)
     ORDER BY pv.voucher_date,pv.created_at,pv.id FOR UPDATE OF pv
  LOOP
    SELECT COALESCE(sum(applied_amount),0) INTO v_advance_applied
      FROM public.salary_advance_applications WHERE advance_payment_voucher_id=v_advance.id;
    v_available:=greatest(v_advance.amount-v_advance_applied,0);
    v_to_apply:=least(v_available,v_remaining-v_total);
    IF v_to_apply>0 THEN
      v_total:=v_total+v_to_apply;
      v_application_ids:=array_append(v_application_ids,v_advance.id);
    END IF;
    EXIT WHEN v_total>=v_remaining;
  END LOOP;
  IF v_total<=0 THEN RETURN jsonb_build_object('applied',false,'total_applied',0,'remaining_salary',v_remaining); END IF;

  v_settlement:=public.save_payment_voucher_command(
    p_voucher_id=>NULL,
    p_payload=>jsonb_build_object(
      'voucher_date',v_salary.expense_date,'staff_id',v_salary.staff_id,
      'payment_method','advance_adjustment','amount',v_total,'payment_currency',v_currency,
      'exchange_rate',CASE WHEN v_currency='IDR' THEN 1 ELSE COALESCE(v_salary.exchange_rate,1) END,
      'description','Salary Advance Recovery - '||COALESCE(v_salary.voucher_number,v_salary.id::text),
      'created_by',auth.uid(),'document_urls','[]'::jsonb),
    p_allocations=>jsonb_build_array(jsonb_build_object(
      'finance_expense_id',v_salary.id,'amount',v_total,'currency',v_currency)));
  v_settlement_id:=(v_settlement->>'id')::uuid;
  UPDATE public.payment_vouchers SET payment_purpose='salary_advance_settlement' WHERE id=v_settlement_id;
  PERFORM public.post_payment_voucher(v_settlement_id,auth.uid());

  v_remaining:=v_total;
  FOR v_advance IN
    SELECT pv.id,pv.amount FROM public.payment_vouchers pv WHERE pv.id=ANY(v_application_ids)
     ORDER BY pv.voucher_date,pv.created_at,pv.id
  LOOP
    SELECT COALESCE(sum(applied_amount),0) INTO v_advance_applied
      FROM public.salary_advance_applications WHERE advance_payment_voucher_id=v_advance.id;
    v_available:=greatest(v_advance.amount-v_advance_applied,0);
    v_to_apply:=least(v_available,v_remaining);
    IF v_to_apply>0 THEN
      INSERT INTO public.salary_advance_applications(
        advance_payment_voucher_id,salary_expense_id,settlement_payment_voucher_id,applied_amount)
      VALUES(v_advance.id,v_salary.id,v_settlement_id,v_to_apply);
      PERFORM public.refresh_salary_advance_status(v_advance.id);
      v_remaining:=v_remaining-v_to_apply;
    END IF;
    EXIT WHEN v_remaining<=0;
  END LOOP;
  RETURN jsonb_build_object(
    'applied',true,'total_applied',v_total,
    'remaining_salary',greatest(v_salary.amount-COALESCE(v_salary.pph_amount,0)-v_total,0),
    'settlement_payment_voucher_id',v_settlement_id,
    'settlement_payment_voucher_number',v_settlement->>'voucher_number');
END;
$$;


--
-- Name: approve_finance_expense("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."approve_finance_expense"("p_expense_id" "uuid", "p_approved_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public._sec_check_finance_role();
  UPDATE public.finance_expenses SET approval_status='approved',approved_by=COALESCE(p_approved_by,auth.uid()),approved_at=now(),rejection_reason=NULL
  WHERE id=p_expense_id AND approval_status IS DISTINCT FROM 'approved';
  IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=p_expense_id AND approval_status='approved') THEN
    RAISE EXCEPTION 'Expense not found';
  END IF;
  RETURN p_expense_id;
END $$;


--
-- Name: approve_purchase_invoice_for_receiving("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."approve_purchase_invoice_for_receiving"("p_purchase_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_status text;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','manager']) THEN RAISE EXCEPTION 'Permission denied'; END IF;
  SELECT receiving_approval_status INTO v_status FROM public.purchase_invoices WHERE id=p_purchase_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;
  IF v_status <> 'pending_approval' THEN RAISE EXCEPTION 'Purchase Invoice must be pending approval'; END IF;
  UPDATE public.purchase_invoices SET receiving_approval_status='approved', receiving_approved_at=now(), receiving_approved_by=auth.uid(), updated_at=now() WHERE id=p_purchase_invoice_id;
  RETURN jsonb_build_object('success',true,'status','approved');
END; $$;


--
-- Name: approve_sales_order_inventory_v1("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."approve_sales_order_inventory_v1"("p_so_id" "uuid", "p_approved_by" "uuid") RETURNS TABLE("success" boolean, "message" "text", "shortage_items" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_previous_context text;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(
    ARRAY['admin', 'accounts', 'manager', 'warehouse']
  ) THEN
    RAISE EXCEPTION 'Permission denied for Sales Order approval';
  END IF;

  v_previous_context := current_setting('app.canonical_reservation_engine', true);
  PERFORM set_config('app.canonical_reservation_engine', 'on', true);

  UPDATE public.sales_orders
  SET status = 'approved',
      approved_by = COALESCE(p_approved_by, auth.uid()),
      approved_at = now(),
      updated_at = now()
  WHERE id = p_so_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales Order not found';
  END IF;

  RETURN QUERY
  SELECT *
  FROM public.fn_reserve_stock_for_so_v2(p_so_id);

  PERFORM set_config(
    'app.canonical_reservation_engine',
    COALESCE(v_previous_context, ''),
    true
  );
END;
$$;


--
-- Name: approve_sales_order_product_reservation_v2("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."approve_sales_order_product_reservation_v2"("p_so_id" "uuid", "p_approved_by" "uuid") RETURNS TABLE("success" boolean, "message" "text", "shortage_items" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record;
  v_delivered numeric;
  v_item_required numeric;
  v_reserved numeric;
  v_shortage_qty numeric;
  v_shortage_list jsonb := '[]'::jsonb;
  v_has_shortage boolean := false;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'manager', 'warehouse'])
     AND current_setting('app.canonical_reservation_engine', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'Permission denied for SO product reservation approval';
  END IF;

  PERFORM 1 FROM public.sales_orders WHERE id = p_so_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales Order not found';
  END IF;

  PERFORM set_config('app.canonical_reservation_engine', 'on', true);

  UPDATE public.sales_orders
  SET approved_by = COALESCE(p_approved_by, auth.uid()),
      approved_at = COALESCE(approved_at, now())
  WHERE id = p_so_id;

  FOR r IN
    SELECT id, product_id, quantity
    FROM public.sales_order_items
    WHERE sales_order_id = p_so_id
    ORDER BY product_id, id
  LOOP
    v_reserved := public.reconcile_so_product_reservation_v2(r.id, 'SO approval/re-approval');

    SELECT COALESCE(sum(dci.quantity), 0) INTO v_delivered
    FROM public.delivery_challan_items dci
    JOIN public.delivery_challans dc ON dc.id = dci.challan_id
    WHERE dci.sales_order_item_id = r.id
      AND dc.approval_status = 'approved';

    v_item_required := GREATEST(r.quantity - v_delivered, 0);

    IF v_item_required > v_reserved THEN
      v_has_shortage := true;
      v_shortage_qty := v_item_required - v_reserved;
      v_shortage_list := v_shortage_list || jsonb_build_object(
        'product_id', r.product_id,
        'required_qty', r.quantity,
        'shortage_qty', v_shortage_qty
      );
    END IF;
  END LOOP;

  IF v_has_shortage THEN
    UPDATE public.sales_orders
    SET status = 'shortage',
        updated_at = now()
    WHERE id = p_so_id;

    PERFORM public.fn_create_import_requirements(p_so_id, v_shortage_list);

    RETURN QUERY
    SELECT false, 'Partial stock reserved - shortage exists.'::text, v_shortage_list;
  ELSE
    UPDATE public.sales_orders
    SET status = 'stock_reserved',
        updated_at = now()
    WHERE id = p_so_id;

    RETURN QUERY
    SELECT true, 'Stock fully reserved'::text, '[]'::jsonb;
  END IF;
END;
$$;


--
-- Name: archive_batch_inventory_v1("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."archive_batch_inventory_v1"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch public.batches%ROWTYPE;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(
    ARRAY['admin', 'accounts', 'warehouse', 'manager']
  ) THEN
    RAISE EXCEPTION 'Permission denied for batch archive';
  END IF;

  SELECT *
  INTO v_batch
  FROM public.batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'archived', false,
      'reason', 'Batch not found'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.stock_reservations
    WHERE batch_id = p_batch_id
      AND status = 'active'
  ) THEN
    RETURN jsonb_build_object(
      'archived', false,
      'reason', format(
        'Batch %s has active reservations and cannot be archived',
        v_batch.batch_number
      )
    );
  END IF;

  IF v_batch.current_stock <> 0 THEN
    RETURN jsonb_build_object(
      'archived', false,
      'reason', format(
        'Batch %s still has stock %s. Post a canonical adjustment to zero before archiving',
        v_batch.batch_number,
        v_batch.current_stock
      )
    );
  END IF;

  UPDATE public.batches
  SET is_active = false,
      updated_at = now()
  WHERE id = p_batch_id;

  RETURN jsonb_build_object(
    'archived', true,
    'batch_id', p_batch_id,
    'batch_number', v_batch.batch_number
  );
END;
$$;


--
-- Name: archive_old_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."archive_old_records"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_notifications_deleted integer := 0;
v_gmail_deleted integer := 0;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin') THEN
RAISE EXCEPTION 'Permission denied: only admin can archive old records';
END IF;

DELETE FROM notifications
WHERE is_read = true
AND created_at < now() - interval '90 days';
GET DIAGNOSTICS v_notifications_deleted = ROW_COUNT;

DELETE FROM notifications
WHERE is_read = false
AND created_at < now() - interval '180 days';

DELETE FROM gmail_processed_messages
WHERE created_at < now() - interval '60 days';
GET DIAGNOSTICS v_gmail_deleted = ROW_COUNT;

RETURN jsonb_build_object(
'notifications_deleted', v_notifications_deleted,
'gmail_processed_deleted', v_gmail_deleted,
'archived_at', now()
);
END;
$$;


--
-- Name: assert_posted_journal_balanced(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."assert_posted_journal_balanced"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_debit numeric;
  v_credit numeric;
BEGIN
  IF COALESCE(NEW.is_posted, false) IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(SUM(debit), 0), COALESCE(SUM(credit), 0)
    INTO v_debit, v_credit
    FROM public.journal_entry_lines
   WHERE journal_entry_id = NEW.id;

  IF abs(v_debit - v_credit) > 0.01 THEN
    RAISE EXCEPTION 'Posted journal % is out of balance: debit %, credit %',
      NEW.entry_number, v_debit, v_credit;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "assert_posted_journal_balanced"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."assert_posted_journal_balanced"() IS 'Deferred invariant: newly inserted or posted journals must have equal debit and credit totals.';


--
-- Name: assert_posted_journal_lines_balanced(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."assert_posted_journal_lines_balanced"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_je_id uuid := COALESCE(NEW.journal_entry_id, OLD.journal_entry_id);
  v_posted boolean;
  v_debit numeric;
  v_credit numeric;
  v_entry_number text;
BEGIN
  SELECT is_posted, entry_number INTO v_posted, v_entry_number
    FROM public.journal_entries WHERE id = v_je_id;
  IF COALESCE(v_posted, false) IS NOT TRUE THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  SELECT COALESCE(SUM(debit),0), COALESCE(SUM(credit),0)
    INTO v_debit, v_credit
    FROM public.journal_entry_lines WHERE journal_entry_id = v_je_id;
  IF abs(v_debit - v_credit) > 0.01 THEN
    RAISE EXCEPTION 'Posted journal % is out of balance: debit %, credit %', v_entry_number, v_debit, v_credit;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


--
-- Name: assign_faktur_pajak_number("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."assign_faktur_pajak_number"("p_sales_invoice_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_settings   organization_tax_settings%ROWTYPE;
  v_number     text;
  v_next       int;
  v_invoice    sales_invoices%ROWTYPE;
  v_lock_id    bigint;
  v_period_id  uuid;
  v_dpp        numeric(18,2);
  v_ppn        numeric(18,2);
BEGIN
  -- Serialize faktur-number issuance across concurrent callers
  v_lock_id := hashtext('faktur_pajak_seq');
  PERFORM pg_advisory_xact_lock(v_lock_id);

  SELECT * INTO v_settings FROM organization_tax_settings ORDER BY created_at LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization_tax_settings not configured — cannot issue Faktur Pajak';
  END IF;
  IF v_settings.pkp_status = false THEN
    RAISE EXCEPTION 'Organization is not PKP — cannot issue Faktur Pajak';
  END IF;

  SELECT * INTO v_invoice FROM sales_invoices WHERE id = p_sales_invoice_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales invoice % not found', p_sales_invoice_id;
  END IF;
  IF v_invoice.faktur_pajak_number IS NOT NULL AND v_invoice.faktur_pajak_number <> '' THEN
    -- Idempotent: return the existing number
    RETURN v_invoice.faktur_pajak_number;
  END IF;

  v_next := COALESCE(v_settings.faktur_current_number, 0) + 1;

  v_number := COALESCE(v_settings.faktur_prefix, '000') || '.' ||
              lpad(v_next::text, 8, '0') || '-' ||
              to_char(COALESCE(v_invoice.invoice_date, CURRENT_DATE), 'YY');

  UPDATE organization_tax_settings
    SET faktur_current_number = v_next, updated_at = now()
    WHERE id = v_settings.id;

  UPDATE sales_invoices
    SET faktur_pajak_number = v_number,
        updated_at = now()
    WHERE id = p_sales_invoice_id;

  -- Attribute invoice to its PPN tax_period (idempotent upsert)
  v_period_id := upsert_tax_period(
    EXTRACT(YEAR  FROM v_invoice.invoice_date)::int,
    EXTRACT(MONTH FROM v_invoice.invoice_date)::int,
    'PPN'
  );
  UPDATE sales_invoices SET tax_period_id = v_period_id WHERE id = p_sales_invoice_id;

  -- Derive DPP + PPN split from tax_amount (Indonesian PPN 11%)
  v_ppn := COALESCE(v_invoice.tax_amount, 0);
  v_dpp := GREATEST(COALESCE(v_invoice.total_amount, 0) - v_ppn, 0);

  INSERT INTO faktur_pajak
    (sales_invoice_id, tax_period_id, faktur_number, issue_date,
     customer_id, dpp_amount, ppn_amount, status, created_by)
  VALUES
    (p_sales_invoice_id, v_period_id, v_number,
     COALESCE(v_invoice.invoice_date, CURRENT_DATE),
     v_invoice.customer_id, v_dpp, v_ppn, 'generated', auth.uid())
  ON CONFLICT (sales_invoice_id) DO UPDATE SET
    faktur_number = EXCLUDED.faktur_number,
    tax_period_id = EXCLUDED.tax_period_id,
    dpp_amount    = EXCLUDED.dpp_amount,
    ppn_amount    = EXCLUDED.ppn_amount,
    updated_at    = now();

  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)
  VALUES (auth.uid(), 'faktur_pajak', 'insert', p_sales_invoice_id,
          jsonb_build_object('faktur_number', v_number, 'sales_invoice_id', p_sales_invoice_id));

  RETURN v_number;
END $$;


--
-- Name: audit_fund_transfer_repair_eligibility("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."audit_fund_transfer_repair_eligibility"("p_fund_transfer_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  t public.fund_transfers%ROWTYPE;
  j public.journal_entries%ROWTYPE;
  from_coa uuid;
  to_coa uuid;
  from_currency text;
  to_currency text;
  expected_rate numeric;
  candidate_count integer;
  line_count integer;
BEGIN
  SELECT * INTO t FROM public.fund_transfers WHERE id = p_fund_transfer_id;
  IF NOT FOUND THEN RETURN 'Fund Transfer record is missing'; END IF;
  IF t.status <> 'posted' THEN RETURN 'Fund Transfer is not posted'; END IF;
  IF t.journal_entry_id IS NULL THEN RETURN 'Posted Fund Transfer has no linked journal'; END IF;

  SELECT * INTO j FROM public.journal_entries WHERE id = t.journal_entry_id;
  IF NOT FOUND OR NOT COALESCE(j.is_posted, false) OR COALESCE(j.is_reversed, false)
     THEN RETURN 'Linked journal is missing, unposted, or reversed'; END IF;
  IF j.source_module NOT IN ('fund_transfer', 'fund_transfers')
     OR j.reference_id IS DISTINCT FROM t.id
     THEN RETURN 'Journal source relationship does not prove this Fund Transfer'; END IF;

  IF t.from_account_type = 'bank' THEN
    SELECT coa_id, upper(currency) INTO from_coa, from_currency
      FROM public.bank_accounts WHERE id = t.from_bank_account_id AND is_active;
  ELSIF t.from_account_type = 'petty_cash' THEN
    SELECT id, 'IDR' INTO from_coa, from_currency FROM public.chart_of_accounts
      WHERE code = '1102' AND is_active LIMIT 1;
  ELSE
    SELECT id, 'IDR' INTO from_coa, from_currency FROM public.chart_of_accounts
      WHERE code = '1101' AND is_active LIMIT 1;
  END IF;
  IF t.to_account_type = 'bank' THEN
    SELECT coa_id, upper(currency) INTO to_coa, to_currency
      FROM public.bank_accounts WHERE id = t.to_bank_account_id AND is_active;
  ELSIF t.to_account_type = 'petty_cash' THEN
    SELECT id, 'IDR' INTO to_coa, to_currency FROM public.chart_of_accounts
      WHERE code = '1102' AND is_active LIMIT 1;
  ELSE
    SELECT id, 'IDR' INTO to_coa, to_currency FROM public.chart_of_accounts
      WHERE code = '1101' AND is_active LIMIT 1;
  END IF;
  IF from_coa IS NULL OR to_coa IS NULL OR from_currency IS NULL OR to_currency IS NULL
     THEN RETURN 'Fund Transfer account or currency cannot be derived'; END IF;
  IF t.from_amount IS NULL OR t.to_amount IS NULL OR t.exchange_rate IS NULL
     THEN RETURN 'Fund Transfer is missing an amount or exchange rate'; END IF;

  expected_rate := CASE
    WHEN from_currency = to_currency THEN 1
    WHEN from_currency = 'IDR' AND t.to_amount > 0 THEN t.from_amount / t.to_amount
    WHEN to_currency = 'IDR' AND t.from_amount > 0 THEN t.to_amount / t.from_amount
  END;
  IF expected_rate IS NULL OR abs(t.exchange_rate - expected_rate) > 0.000001
     THEN RETURN 'Fund Transfer exchange rate is inconsistent with its stored amounts'; END IF;
  -- This is the known unsafe legacy shape: the USD source amount was stored
  -- in functional journal columns. Do not silently reinterpret posted values.
  IF from_currency = 'USD' AND to_currency = 'IDR'
     THEN RETURN 'Legacy USD-source transfer has a functional accounting inconsistency'; END IF;

  SELECT count(*) INTO line_count FROM public.journal_entry_lines WHERE journal_entry_id = j.id;
  IF line_count <> 2
     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id=j.id AND line_number=1 AND COALESCE(debit,0)>0 AND COALESCE(credit,0)=0)
     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id=j.id AND line_number=2 AND COALESCE(credit,0)>0 AND COALESCE(debit,0)=0)
     THEN RETURN 'Posted journal is not a safe two-line transfer'; END IF;
  IF abs(COALESCE(j.total_debit,0) - t.from_amount) > 0.01
     OR abs(COALESCE(j.total_credit,0) - t.from_amount) > 0.01
     OR EXISTS (SELECT 1 FROM public.journal_entry_lines l WHERE l.journal_entry_id=j.id
       AND ((l.line_number=1 AND abs(COALESCE(l.debit,0)-t.from_amount)>0.01)
         OR (l.line_number=2 AND abs(COALESCE(l.credit,0)-t.from_amount)>0.01)))
     THEN RETURN 'Posted journal debit/credit values do not match the Fund Transfer'; END IF;

  -- The Fund Transfer may name a statement line, but this audit never changes
  -- that row. A missing link is only eligible when there is no ambiguity; a
  -- multiple-match case is always left for manual review.
  IF t.from_account_type = 'bank' AND t.from_bank_statement_line_id IS NULL THEN
    SELECT count(*) INTO candidate_count FROM public.bank_statement_lines b
      WHERE b.bank_account_id=t.from_bank_account_id AND abs(b.transaction_date-t.transfer_date)<=8
        AND (COALESCE(b.debit_amount,0)=t.from_amount OR COALESCE(b.credit_amount,0)=t.from_amount);
    IF candidate_count > 1 THEN RETURN 'Multiple possible From Bank transactions; no link was guessed'; END IF;
  END IF;
  IF t.to_account_type = 'bank' AND t.to_bank_statement_line_id IS NULL THEN
    SELECT count(*) INTO candidate_count FROM public.bank_statement_lines b
      WHERE b.bank_account_id=t.to_bank_account_id AND abs(b.transaction_date-t.transfer_date)<=8
        AND (COALESCE(b.debit_amount,0)=t.to_amount OR COALESCE(b.credit_amount,0)=t.to_amount);
    IF candidate_count > 1 THEN RETURN 'Multiple possible To Bank transactions; no link was guessed'; END IF;
  END IF;

  -- Explicit links are audited for consistency but never updated.
  IF t.from_bank_statement_line_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.bank_statement_lines b
    WHERE b.id=t.from_bank_statement_line_id AND b.bank_account_id=t.from_bank_account_id
      AND COALESCE(b.debit_amount,0)=t.from_amount
  ) THEN RETURN 'From Bank statement link does not match the Fund Transfer source'; END IF;
  IF t.to_bank_statement_line_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.bank_statement_lines b
    WHERE b.id=t.to_bank_statement_line_id AND b.bank_account_id=t.to_bank_account_id
      AND COALESCE(b.credit_amount,0)=t.to_amount
  ) THEN RETURN 'To Bank statement link does not match the Fund Transfer source'; END IF;
  RETURN NULL;
END;
$$;


--
-- Name: audit_historical_repair_command(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."audit_historical_repair_command"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.audit_logs(table_name, action_type, record_id, old_values, new_values, user_id)
  VALUES ('finance_historical_repair_commands', 'insert', NEW.id, '{}'::jsonb,
          to_jsonb(NEW), NEW.requested_by);
  RETURN NEW;
END;
$$;


--
-- Name: audit_legacy_bank_reconciliation_source_documents("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."audit_legacy_bank_reconciliation_source_documents"("p_run_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_count integer;
DECLARE r record; v_capital_id uuid; v_voucher text;
BEGIN
  -- A posted bank receipt whose sole counter-entry is Owner Capital is already
  -- an explicit operator classification. Create only the missing native source
  -- document and point the existing journal to it; never repost or alter lines.
  FOR r IN
    SELECT je.id journal_id,je.entry_number,je.entry_date,je.description,je.transaction_currency,je.exchange_rate,
      b.id bank_line_id,b.bank_account_id,upper(COALESCE(b.currency,ba.currency,'IDR')) currency,b.credit_amount,upper(ba.currency) bank_currency
    FROM public.journal_entries je
    JOIN public.bank_statement_lines b ON b.id=je.reference_id AND b.matched_entry_id=je.id
    JOIN public.bank_accounts ba ON ba.id=b.bank_account_id
    WHERE je.source_module='bank_reconciliation' AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false
      AND (SELECT count(*) FROM public.journal_entry_lines x WHERE x.journal_entry_id=je.id)=2
      AND EXISTS(SELECT 1 FROM public.journal_entry_lines x JOIN public.chart_of_accounts c ON c.id=x.account_id
        WHERE x.journal_entry_id=je.id AND x.credit>0 AND c.code='3100')
      AND NOT EXISTS(SELECT 1 FROM public.capital_contributions cc WHERE cc.bank_statement_line_id=b.id)
  LOOP
    v_capital_id:=gen_random_uuid(); v_voucher:=public.next_capital_contribution_number(r.entry_date);
    PERFORM set_config('app.finance_metadata_repair','on',true);
    INSERT INTO public.capital_contributions(id,voucher_number,voucher_date,director_id,contribution_type,bank_account_id,amount,description,
      journal_entry_id,created_by,transaction_currency,functional_currency,exchange_rate,bank_account_currency,bank_statement_line_id)
    SELECT v_capital_id,v_voucher,r.entry_date,NULL,'bank_transfer',r.bank_account_id,r.credit_amount,r.description,r.journal_id,
      je.created_by,r.currency,'IDR',CASE WHEN r.currency='IDR' THEN 1 ELSE r.exchange_rate END,r.bank_currency,r.bank_line_id
    FROM public.journal_entries je WHERE je.id=r.journal_id;
    PERFORM set_config('app.finance_metadata_repair','off',true);
    UPDATE public.journal_entries SET source_module='capital_contribution',reference_id=v_capital_id,reference_number=v_voucher WHERE id=r.journal_id;
    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
    VALUES(p_run_id,'capital_contribution',v_capital_id,v_voucher,ARRAY['source document','source_module','reference_id','reference_number'],
      jsonb_build_object('journal_source_module','bank_reconciliation','journal_reference_id',r.bank_line_id),
      jsonb_build_object('journal_source_module','capital_contribution','journal_reference_id',v_capital_id,'bank_statement_line_id',r.bank_line_id),
      'The posted two-line bank receipt and sole Owner Capital counter-entry prove the missing Capital Contribution source document');
    IF r.currency='USD' AND r.exchange_rate IS NULL THEN
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required,status)
      VALUES(p_run_id,'capital_contribution',v_capital_id,v_voucher,ARRAY['exchange_rate'],
        'Legacy USD capital contribution has no authoritative historical exchange rate; accounting amounts were preserved unchanged',
        'Authoritative USD-to-IDR rate and rate source for the contribution date','manual_review');
    END IF;
  END LOOP;

  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required,status)
  SELECT p_run_id,'journal',je.id,je.entry_number,ARRAY['source_module','reference_id'],
    CASE WHEN coa.code='2220' THEN 'Legacy Bank Reconciliation Director/Owner Loan journal has no native Loan source document'
         ELSE 'Legacy Bank Reconciliation loan journal has no native Loan source document' END,
    'Counterparty name and type, loan terms, and accountant confirmation that this receipt opens a loan; then manually relink to the native Loan document',
    'manual_review'
  FROM public.journal_entries je
  JOIN public.journal_entry_lines jel ON jel.journal_entry_id=je.id AND jel.credit>0
  JOIN public.chart_of_accounts coa ON coa.id=jel.account_id AND coa.code IN('2210','2220')
  WHERE je.source_module='bank_reconciliation' AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false
    AND NOT EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e WHERE e.run_id=p_run_id AND e.document_type='journal' AND e.document_id=je.id);
  GET DIAGNOSTICS v_count=ROW_COUNT;
  UPDATE public.finance_historical_repair_runs SET
    total_records_scanned=(SELECT count(*) FROM public.finance_expenses)+(SELECT count(*) FROM public.receipt_vouchers)
      +(SELECT count(*) FROM public.payment_vouchers)+(SELECT count(*) FROM public.fund_transfers)
      +(SELECT count(*) FROM public.journal_entries)+(SELECT count(*) FROM public.bank_statement_lines)
      +(SELECT count(*) FROM public.loans)+(SELECT count(*) FROM public.loan_transactions)+(SELECT count(*) FROM public.capital_contributions),
    records_repaired=(SELECT count(DISTINCT (i.document_type,i.document_id)) FROM public.finance_historical_repair_items i WHERE i.run_id=p_run_id
      AND NOT EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e WHERE e.run_id=p_run_id AND e.status='manual_review'
        AND e.document_type=i.document_type AND e.document_id=i.document_id)),
    records_partially_repaired=(SELECT count(DISTINCT (i.document_type,i.document_id)) FROM public.finance_historical_repair_items i WHERE i.run_id=p_run_id
      AND EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e WHERE e.run_id=p_run_id AND e.status='manual_review' AND e.document_type=i.document_type AND e.document_id=i.document_id)),
    records_manual_review=(
    SELECT count(DISTINCT (document_type,document_id)) FROM public.finance_historical_repair_exceptions WHERE run_id=p_run_id AND status='manual_review'
  ) WHERE id=p_run_id;
  RETURN v_count;
END $$;


--
-- Name: auto_assign_product_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_assign_product_code"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
IF NEW.product_code IS NULL OR NEW.product_code = '' THEN
NEW.product_code := get_next_product_code();
END IF;
RETURN NEW;
END;
$$;


--
-- Name: auto_attribute_credit_note_tax_period(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_attribute_credit_note_tax_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_period_id uuid;
  v_year      int;
  v_month     int;
BEGIN
  IF NEW.tax_period_id IS NOT NULL THEN RETURN NEW; END IF;
  IF NEW.credit_note_date IS NULL THEN RETURN NEW; END IF;

  v_year  := EXTRACT(YEAR  FROM NEW.credit_note_date)::int;
  v_month := EXTRACT(MONTH FROM NEW.credit_note_date)::int;

  SELECT id INTO v_period_id FROM public.tax_periods
   WHERE fiscal_year = v_year AND period_month = v_month AND tax_type = 'PPN';
  IF v_period_id IS NULL THEN
    v_period_id := public.upsert_tax_period(v_year, v_month, 'PPN');
  END IF;
  NEW.tax_period_id := v_period_id;
  RETURN NEW;
END $$;


--
-- Name: auto_attribute_finance_expense_tax_period(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_attribute_finance_expense_tax_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_period_id uuid;
  v_year int;
  v_month int;
BEGIN
  IF NEW.tax_period_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  -- Fire whenever any PPN- or PPh-carrying column is populated, INCLUDING
  -- the PIB breakdown columns (previously overlooked).
  IF COALESCE(NEW.ppn_amount,     0) <= 0
     AND COALESCE(NEW.pph_amount, 0) <= 0
     AND COALESCE(NEW.pib_ppn_amount, 0) <= 0
     AND COALESCE(NEW.pib_pph_amount, 0) <= 0 THEN
    RETURN NEW;
  END IF;
  IF NEW.expense_date IS NULL THEN
    RETURN NEW;
  END IF;

  v_year  := EXTRACT(YEAR  FROM NEW.expense_date)::int;
  v_month := EXTRACT(MONTH FROM NEW.expense_date)::int;

  SELECT id INTO v_period_id
  FROM tax_periods
  WHERE fiscal_year = v_year AND period_month = v_month AND tax_type = 'PPN';

  IF v_period_id IS NULL THEN
    v_period_id := upsert_tax_period(v_year, v_month, 'PPN');
  END IF;

  NEW.tax_period_id := v_period_id;
  RETURN NEW;
END $$;


--
-- Name: auto_attribute_payment_voucher_tax_period(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_attribute_payment_voucher_tax_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_period_id uuid;
BEGIN
  -- Only act when PPh is present and tax_period_id not already set
  IF NEW.pph_amount IS NULL OR NEW.pph_amount = 0 THEN
    RETURN NEW;
  END IF;
  IF NEW.tax_period_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Resolve the PPh type from the tax_code
  DECLARE
    v_pph_type text;
  BEGIN
    SELECT tc.tax_type INTO v_pph_type
      FROM tax_codes tc WHERE tc.id = NEW.pph_code_id;
    IF v_pph_type IS NULL OR v_pph_type = 'PPN' THEN
      RETURN NEW; -- Not a PPh code — skip
    END IF;

    v_period_id := upsert_tax_period(
      EXTRACT(YEAR  FROM NEW.voucher_date)::int,
      EXTRACT(MONTH FROM NEW.voucher_date)::int,
      v_pph_type
    );
    NEW.tax_period_id := v_period_id;
  END;
  RETURN NEW;
END $$;


--
-- Name: auto_attribute_purchase_invoice_tax_period(); Type: FUNCTION; Schema: public; Owner: -
