  IF v_period_id IS NULL THEN
    v_period_id := upsert_tax_period(v_year, v_month, 'PPN');
  END IF;
  NEW.tax_period_id := v_period_id;
  RETURN NEW;
END $$;


--
-- Name: auto_attribute_sales_invoice_tax_period(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_attribute_sales_invoice_tax_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
