--
-- Name: auto_create_companion_pph_periods(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_create_companion_pph_periods"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.tax_type = 'PPN' THEN
    PERFORM upsert_tax_period(NEW.fiscal_year, NEW.period_month, 'PPh21');
    PERFORM upsert_tax_period(NEW.fiscal_year, NEW.period_month, 'PPh22');
    PERFORM upsert_tax_period(NEW.fiscal_year, NEW.period_month, 'PPh23');
    PERFORM upsert_tax_period(NEW.fiscal_year, NEW.period_month, 'PPh4(2)');
    PERFORM upsert_tax_period(NEW.fiscal_year, NEW.period_month, 'PPh_Unifikasi');
  END IF;
  RETURN NEW;
END $$;


--
-- Name: auto_create_followup("uuid", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_create_followup"("p_inquiry_id" "uuid", "p_action_type" "text", "p_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
rule_record RECORD;
new_reminder_id uuid;
due_date timestamptz;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts', 'sales', 'manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot create follow-ups', v_role;
END IF;

SELECT * INTO rule_record
FROM crm_automation_rules
WHERE is_active = true
AND trigger_on = 'action_performed'
AND trigger_action = p_action_type
AND auto_create_followup = true
ORDER BY priority DESC
LIMIT 1;

IF rule_record IS NOT NULL THEN
due_date := now() + (rule_record.followup_days_offset || ' days')::interval;

INSERT INTO crm_reminders (
inquiry_id, reminder_type, title, due_date, assigned_to, created_by
) VALUES (
p_inquiry_id, rule_record.followup_type, rule_record.followup_title,
due_date, p_user_id, p_user_id
) RETURNING id INTO new_reminder_id;

RETURN new_reminder_id;
END IF;

RETURN NULL;
END;
$$;


--
-- Name: auto_create_import_expenses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_create_import_expenses"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_expense_date DATE;
v_created_by UUID;
BEGIN
-- Use import date as expense date
v_expense_date := NEW.import_date;
v_created_by := COALESCE(NEW.created_by, auth.uid());

-- Only process if this is a new record or cost fields changed
-- NOTE: bpom_ski_fees and other_import_costs are EXCLUDED - they're calculated from expenses
IF (TG_OP = 'INSERT') OR 
(TG_OP = 'UPDATE' AND (
OLD.duty_bm IS DISTINCT FROM NEW.duty_bm OR
OLD.ppn_import IS DISTINCT FROM NEW.ppn_import OR
OLD.pph_import IS DISTINCT FROM NEW.pph_import OR
OLD.freight_charges IS DISTINCT FROM NEW.freight_charges OR
OLD.clearing_forwarding IS DISTINCT FROM NEW.clearing_forwarding OR
OLD.port_charges IS DISTINCT FROM NEW.port_charges OR
OLD.container_handling IS DISTINCT FROM NEW.container_handling OR
OLD.transportation IS DISTINCT FROM NEW.transportation OR
OLD.loading_import IS DISTINCT FROM NEW.loading_import
)) THEN

-- Delete old expense entries for this container (if update)
-- BUT ONLY delete expenses that are NOT linked to bank statements
-- AND NOT user-created bpom_ski_fees or other_import
IF TG_OP = 'UPDATE' THEN
DELETE FROM finance_expenses fe
WHERE fe.import_container_id = NEW.id
AND fe.expense_category NOT IN ('bpom_ski_fees', 'other_import')
-- Only delete if NOT referenced by bank_statement_lines
AND NOT EXISTS (
SELECT 1 
FROM bank_statement_lines bsl 
WHERE bsl.matched_expense_id = fe.id
);
END IF;

-- Create expense entry for BM (Duty) - only if not already reconciled
IF NEW.duty_bm > 0 AND NOT EXISTS (
SELECT 1 FROM finance_expenses fe
JOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id
WHERE fe.import_container_id = NEW.id 
AND fe.expense_category = 'duty_customs'
) THEN
INSERT INTO finance_expenses (
expense_category,
expense_type,
amount,
expense_date,
description,
import_container_id,
created_by
) VALUES (
'duty_customs',
'import',
NEW.duty_bm,
v_expense_date,
'BM (Duty) - Container ' || NEW.container_ref,
NEW.id,
v_created_by
);
END IF;

-- Create expense entry for PPN Import - only if not already reconciled
IF NEW.ppn_import > 0 AND NOT EXISTS (
SELECT 1 FROM finance_expenses fe
JOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id
WHERE fe.import_container_id = NEW.id 
AND fe.expense_category = 'ppn_import'
) THEN
INSERT INTO finance_expenses (
expense_category,
expense_type,
amount,
expense_date,
description,
import_container_id,
created_by
) VALUES (
'ppn_import',
'import',
NEW.ppn_import,
v_expense_date,
'PPN Import (11%) - Container ' || NEW.container_ref,
NEW.id,
v_created_by
);
END IF;

-- Create expense entry for PPh Import - only if not already reconciled
IF NEW.pph_import > 0 AND NOT EXISTS (
SELECT 1 FROM finance_expenses fe
JOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id
WHERE fe.import_container_id = NEW.id 
AND fe.expense_category = 'pph_import'
) THEN
INSERT INTO finance_expenses (
expense_category,
expense_type,
amount,
expense_date,
description,
import_container_id,
created_by
) VALUES (
'pph_import',
'import',
NEW.pph_import,
v_expense_date,
'PPh Import - Container ' || NEW.container_ref,
NEW.id,
v_created_by
);
END IF;

-- Create expense entry for Freight - only if not already reconciled
IF NEW.freight_charges > 0 AND NOT EXISTS (
SELECT 1 FROM finance_expenses fe
JOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id
WHERE fe.import_container_id = NEW.id 
AND fe.expense_category = 'freight_import'
) THEN
INSERT INTO finance_expenses (
expense_category,
expense_type,
amount,
expense_date,
description,
import_container_id,
created_by
) VALUES (
'freight_import',
'import',
NEW.freight_charges,
v_expense_date,
'Freight Charges - Container ' || NEW.container_ref,
NEW.id,
v_created_by
);
END IF;

-- Create expense entry for Clearing & Forwarding - only if not already reconciled
IF NEW.clearing_forwarding > 0 AND NOT EXISTS (
SELECT 1 FROM finance_expenses fe
JOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id
WHERE fe.import_container_id = NEW.id 
AND fe.expense_category = 'clearing_forwarding'
) THEN
INSERT INTO finance_expenses (
expense_category,
expense_type,
amount,
expense_date,
description,
import_container_id,
created_by
) VALUES (
'clearing_forwarding',
'import',
NEW.clearing_forwarding,
v_expense_date,
'Clearing & Forwarding - Container ' || NEW.container_ref,
NEW.id,
v_created_by
);
END IF;

-- Create expense entry for Port Charges - only if not already reconciled
IF NEW.port_charges > 0 AND NOT EXISTS (
SELECT 1 FROM finance_expenses fe
JOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id
WHERE fe.import_container_id = NEW.id 
AND fe.expense_category = 'port_charges'
) THEN
INSERT INTO finance_expenses (
expense_category,
expense_type,
amount,
expense_date,
description,
import_container_id,
created_by
) VALUES (
'port_charges',
'import',
NEW.port_charges,
v_expense_date,
'Port Charges - Container ' || NEW.container_ref,
NEW.id,
v_created_by
);
END IF;

-- Create expense entry for Container Handling - only if not already reconciled
IF NEW.container_handling > 0 AND NOT EXISTS (
SELECT 1 FROM finance_expenses fe
JOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id
WHERE fe.import_container_id = NEW.id 
AND fe.expense_category = 'container_handling'
) THEN
INSERT INTO finance_expenses (
expense_category,
expense_type,
amount,
expense_date,
description,
import_container_id,
created_by
) VALUES (
'container_handling',
'import',
NEW.container_handling,
v_expense_date,
'Container Handling - Container ' || NEW.container_ref,
NEW.id,
v_created_by
);
END IF;

-- Create expense entry for Transportation - only if not already reconciled
IF NEW.transportation > 0 AND NOT EXISTS (
SELECT 1 FROM finance_expenses fe
JOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id
WHERE fe.import_container_id = NEW.id 
AND fe.expense_category = 'transport_import'
) THEN
INSERT INTO finance_expenses (
expense_category,
expense_type,
amount,
expense_date,
description,
import_container_id,
created_by
) VALUES (
'transport_import',
'import',
NEW.transportation,
v_expense_date,
'Transportation - Container ' || NEW.container_ref,
NEW.id,
v_created_by
);
END IF;

-- Create expense entry for Loading/Unloading - only if not already reconciled
IF NEW.loading_import > 0 AND NOT EXISTS (
SELECT 1 FROM finance_expenses fe
JOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id
WHERE fe.import_container_id = NEW.id 
AND fe.expense_category = 'loading_import'
) THEN
INSERT INTO finance_expenses (
expense_category,
expense_type,
amount,
expense_date,
description,
import_container_id,
created_by
) VALUES (
'loading_import',
'import',
NEW.loading_import,
v_expense_date,
'Loading/Unloading - Container ' || NEW.container_ref,
NEW.id,
v_created_by
);
END IF;

-- NOTE: bpom_ski_fees and other_import expenses are NOT auto-created
-- They are user-entered and the container fields are calculated FROM them

END IF;

RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "auto_create_import_expenses"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."auto_create_import_expenses"() IS 'Automatically creates finance_expenses entries when import container costs are entered.
Each cost type (BM, PPN, PPh, Freight, etc.) creates a separate expense entry.
These expenses then flow to accounting via the auto_post_expense_accounting trigger.';


--
-- Name: auto_create_user_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_create_user_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      DECLARE
        v_username text;
      BEGIN
        v_username := COALESCE(
          NULLIF(TRIM(NEW.raw_user_meta_data->>'username'), ''),
          split_part(NEW.email, '@', 1)
        );
        INSERT INTO public.user_profiles (id, username, email, full_name, role, is_active)
        VALUES (
          NEW.id,
          v_username,
          NEW.email,
          COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),
          'sales',
          true
        )
        ON CONFLICT (id) DO NOTHING;
        RETURN NEW;
      END $$;


