--
-- Name: auto_generate_sales_order_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_generate_sales_order_tasks"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_item RECORD;
v_available_stock numeric;
v_has_shortage boolean := false;
v_all_items_sufficient boolean := true;
v_warehouse_users uuid[];
v_procurement_users uuid[];
v_task_deadline timestamptz;
BEGIN
-- Only run when status changes to approved
IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN

-- Get warehouse and procurement users
v_warehouse_users := get_users_by_role('warehouse');
v_procurement_users := get_users_by_role('procurement');

-- Check stock for all items in the order
FOR v_item IN
SELECT
soi.id,
soi.product_id,
soi.quantity,
soi.reserved_quantity,
p.product_name,
p.current_stock
FROM sales_order_items soi
JOIN products p ON p.id = soi.product_id
WHERE soi.sales_order_id = NEW.id
LOOP
-- Calculate available stock (current - already reserved)
v_available_stock := COALESCE(v_item.current_stock, 0);

-- Check if this item has shortage
IF v_available_stock < v_item.quantity THEN
v_has_shortage := true;
v_all_items_sufficient := false;

-- Create procurement task for shortage (ADVISORY ONLY - errors ignored)
BEGIN
v_task_deadline := now() + interval '7 days';

INSERT INTO tasks (
title,
description,
deadline,
priority,
status,
created_by,
assigned_users,
task_type,
task_mode,
task_origin,
sales_order_id,
customer_id,
product_id,
tags,
auto_priority,
system_metadata
)
SELECT
'Procurement Required: ' || v_item.product_name,
'Stock shortage detected. Required: ' || v_item.quantity || 
', Available: ' || v_available_stock || 
', Shortage: ' || (v_item.quantity - v_available_stock) || 
'. Please initiate procurement.',
v_task_deadline,
'high'::task_priority,
'to_do'::task_status,
(SELECT id FROM user_profiles WHERE role = 'admin' LIMIT 1),
v_procurement_users,
'system'::task_type_enum,
'advisory'::task_mode_enum,
'stock_shortage'::task_origin_enum,
NEW.id,
NEW.customer_id,
v_item.product_id,
ARRAY['procurement', 'stock-shortage', 'system-generated'],
true,
jsonb_build_object(
'stock_shortage_qty', v_item.quantity - v_available_stock,
'required_qty', v_item.quantity,
'available_qty', v_available_stock,
'product_id', v_item.product_id
)
;
EXCEPTION WHEN OTHERS THEN
-- Ignore errors - task creation is advisory only
RAISE NOTICE 'Advisory task creation failed (ignored): %', SQLERRM;
END;
END IF;
END LOOP;

-- If all items have sufficient stock, create dispatch task
IF v_all_items_sufficient AND v_warehouse_users IS NOT NULL AND array_length(v_warehouse_users, 1) > 0 THEN
BEGIN
-- Set deadline to 1 day before expected delivery
IF NEW.expected_delivery_date IS NOT NULL THEN
v_task_deadline := (NEW.expected_delivery_date - interval '1 day')::timestamptz;
ELSE
v_task_deadline := now() + interval '3 days';
END IF;

INSERT INTO tasks (
title,
description,
deadline,
priority,
status,
created_by,
assigned_users,
task_type,
task_mode,
task_origin,
sales_order_id,
customer_id,
tags,
auto_priority,
system_metadata
)
SELECT
'Prepare Dispatch for Sales Order ' || NEW.so_number,
'Stock is available. Prepare items for dispatch as per sales order requirements. Expected delivery: ' || 
COALESCE(NEW.expected_delivery_date::text, 'TBD'),
v_task_deadline,
calculate_task_priority(v_task_deadline),
'to_do'::task_status,
(SELECT id FROM user_profiles WHERE role = 'admin' LIMIT 1),
v_warehouse_users,
'system'::task_type_enum,
'advisory'::task_mode_enum,
'sales_order'::task_origin_enum,
NEW.id,
NEW.customer_id,
ARRAY['dispatch', 'warehouse', 'system-generated'],
true,
jsonb_build_object(
'so_number', NEW.so_number,
'expected_delivery_date', NEW.expected_delivery_date
)
;
EXCEPTION WHEN OTHERS THEN
-- Ignore errors - task creation is advisory only
RAISE NOTICE 'Advisory task creation failed (ignored): %', SQLERRM;
END;
END IF;

END IF;

-- Always return NEW to ensure sales order is not affected
RETURN NEW;
EXCEPTION WHEN OTHERS THEN
-- Catch-all: ensure sales order processing never fails due to task generation
RAISE NOTICE 'Sales order task generation failed (ignored): %', SQLERRM;
RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "auto_generate_sales_order_tasks"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."auto_generate_sales_order_tasks"() IS 'Advisory task generator for sales orders - errors do not block sales order processing';


--
-- Name: auto_generate_transaction_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_generate_transaction_hash"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
NEW.transaction_hash := generate_bank_transaction_hash(
NEW.bank_account_id,
NEW.transaction_date,
NEW.debit_amount,
NEW.credit_amount,
NEW.description,
NEW.running_balance,
NEW.upload_id
);
RETURN NEW;
END;
$$;


--
-- Name: auto_match_bank_statement_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_match_bank_statement_line"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.matched_petty_cash_id IS NOT NULL
     OR NEW.matched_expense_id IS NOT NULL
     OR NEW.matched_receipt_id IS NOT NULL
     OR NEW.matched_payment_id IS NOT NULL
     OR NEW.matched_fund_transfer_id IS NOT NULL
     OR NEW.matched_tax_payment_id IS NOT NULL
     OR NEW.matched_entry_id IS NOT NULL
     OR COALESCE(NEW.manually_unlinked, false) THEN
    RETURN NEW;
  END IF;

  NEW.reconciliation_status := COALESCE(NEW.reconciliation_status, 'unmatched');
  NEW.matching_status := COALESCE(NEW.matching_status, 'none');
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "auto_match_bank_statement_line"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."auto_match_bank_statement_line"() IS 'Conservative auto-match: auto-links only when exactly one native document candidate exists. Never chooses newest arbitrary candidate. Ambiguous same-date/same-amount rows remain Unmatched for deterministic/manual linking.';


--
-- Name: auto_match_bank_transactions_smart(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_match_bank_transactions_smart"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_line        RECORD;
v_matched_id  UUID;
v_match_type  TEXT;
v_match_count INTEGER;
v_role        text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot run auto-match', v_role;
END IF;

FOR v_line IN
SELECT * FROM bank_statement_lines
WHERE matching_status = 'none'
AND matched_expense_id IS NULL AND matched_receipt_id IS NULL
AND matched_petty_cash_id IS NULL AND matched_fund_transfer_id IS NULL
LOOP
v_matched_id := NULL; v_match_type := NULL;

IF v_line.debit_amount > 0 THEN
SELECT id INTO v_matched_id FROM finance_expenses
WHERE ABS(amount - v_line.debit_amount) < 0.01
AND ABS(EXTRACT(EPOCH FROM (expense_date - v_line.transaction_date)) / 86400) <= 3
AND id NOT IN (SELECT matched_expense_id FROM bank_statement_lines WHERE matching_status = 'confirmed' AND matched_expense_id IS NOT NULL)
ORDER BY ABS(EXTRACT(EPOCH FROM (expense_date - v_line.transaction_date))) LIMIT 1;

IF v_matched_id IS NOT NULL THEN
SELECT COUNT(*) INTO v_match_count FROM finance_expenses
WHERE ABS(amount - v_line.debit_amount) < 0.01
AND ABS(EXTRACT(EPOCH FROM (expense_date - v_line.transaction_date)) / 86400) <= 3
AND id NOT IN (SELECT matched_expense_id FROM bank_statement_lines WHERE matching_status = 'confirmed' AND matched_expense_id IS NOT NULL);
UPDATE bank_statement_lines
SET matched_expense_id = v_matched_id, matching_status = 'suggested',
reconciliation_status = CASE WHEN v_match_count > 1 THEN 'conflict' ELSE 'suggested' END,
notes = CASE WHEN v_match_count > 1 THEN 'Multiple possible matches - please verify' ELSE 'Auto-suggested match - needs confirmation' END
WHERE id = v_line.id;
CONTINUE;
END IF;

SELECT id INTO v_matched_id FROM petty_cash_transactions
WHERE transaction_type = 'expense' AND ABS(amount - v_line.debit_amount) < 0.01
AND ABS(EXTRACT(EPOCH FROM (transaction_date - v_line.transaction_date)) / 86400) <= 3
AND id NOT IN (SELECT matched_petty_cash_id FROM bank_statement_lines WHERE matching_status = 'confirmed' AND matched_petty_cash_id IS NOT NULL)
ORDER BY ABS(EXTRACT(EPOCH FROM (transaction_date - v_line.transaction_date))) LIMIT 1;

IF v_matched_id IS NOT NULL THEN
UPDATE bank_statement_lines
SET matched_petty_cash_id = v_matched_id, matching_status = 'suggested',
reconciliation_status = 'suggested', notes = 'Auto-suggested match - needs confirmation'
WHERE id = v_line.id;
CONTINUE;
END IF;
END IF;

IF v_line.credit_amount > 0 THEN
SELECT rv.id INTO v_matched_id FROM receipt_vouchers rv
WHERE ABS(rv.amount - v_line.credit_amount) < 0.01
AND ABS(EXTRACT(EPOCH FROM (rv.receipt_date - v_line.transaction_date)) / 86400) <= 3
AND rv.id NOT IN (SELECT matched_receipt_id FROM bank_statement_lines WHERE matching_status = 'confirmed' AND matched_receipt_id IS NOT NULL)
ORDER BY ABS(EXTRACT(EPOCH FROM (rv.receipt_date - v_line.transaction_date))) LIMIT 1;

IF v_matched_id IS NOT NULL THEN
UPDATE bank_statement_lines
SET matched_receipt_id = v_matched_id, matching_status = 'suggested',
reconciliation_status = 'suggested', notes = 'Auto-suggested match - needs confirmation'
WHERE id = v_line.id;
CONTINUE;
END IF;
END IF;
END LOOP;
END;
$$;


--
-- Name: auto_match_smart(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_match_smart"() RETURNS TABLE("matched_count" integer, "suggested_count" integer, "skipped_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_line public.bank_statement_lines%ROWTYPE;
  v_bank_amount numeric;
  v_direction text;
  v_bank_text text;
  v_candidates jsonb;
  v_candidate jsonb;
  v_candidate_count integer;
  v_expense public.finance_expenses%ROWTYPE;
  v_payload jsonb;
  v_matched integer := 0;
  v_suggested integer := 0;
  v_skipped integer := 0;
BEGIN
  PERFORM public._sec_check_finance_role();

  FOR v_line IN
    SELECT b.*
    FROM public.bank_statement_lines b
    WHERE b.reconciliation_status = 'unmatched'
      AND NOT COALESCE(b.manually_unlinked, false)
      AND b.matched_expense_id IS NULL
      AND b.matched_receipt_id IS NULL
      AND b.matched_payment_id IS NULL
      AND b.matched_petty_cash_id IS NULL
      AND b.matched_fund_transfer_id IS NULL
      AND b.matched_tax_payment_id IS NULL
      AND b.matched_entry_id IS NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.bank_statement_allocations a
        WHERE a.bank_statement_line_id = b.id
      )
    ORDER BY b.transaction_date, b.id
    FOR UPDATE SKIP LOCKED
  LOOP
    v_bank_amount := CASE
      WHEN COALESCE(v_line.credit_amount, 0) > 0 THEN v_line.credit_amount
      ELSE v_line.debit_amount
    END;
    v_direction := CASE
      WHEN COALESCE(v_line.credit_amount, 0) > 0 THEN 'credit'
      ELSE 'debit'
    END;
    v_bank_text := concat_ws(' ', v_line.reference, v_line.description);

    IF COALESCE(v_bank_amount, 0) <= 0.01 THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    -- First resolve documents which already have the authoritative bank leg:
    -- expenses, posted payment vouchers (including AP/Purchase allocations),
    -- receipts/sales, fund transfers, petty cash and tax payments all enter
    -- through vw_finance_document_settlements.
    WITH source_candidates AS MATERIALIZED (
      SELECT s.*,
             GREATEST(
               s.settlement_amount - COALESCE((
                 SELECT sum(a.allocation_amount)
                 FROM public.bank_statement_allocations a
                 WHERE a.document_type = s.document_type
                   AND a.document_id = s.document_id
                   AND a.journal_entry_id = s.journal_entry_id
               ), 0),
               0
             ) AS remaining_amount,
             concat_ws(
               ' ', s.document_number, je.reference_number, je.description,
               (SELECT string_agg(l.description, ' ' ORDER BY l.line_number)
                FROM public.journal_entry_lines l
                WHERE l.journal_entry_id = s.journal_entry_id)
             ) AS document_text
      FROM public.vw_finance_document_settlements s
      JOIN public.journal_entries je ON je.id = s.journal_entry_id
      WHERE s.bank_account_id = v_line.bank_account_id
        AND s.direction = v_direction
        AND abs(v_line.transaction_date - s.settlement_date) <= 7
    ), scored AS MATERIALIZED (
      SELECT c.*,
             public.finance_bank_match_text_score(v_bank_text, c.document_text) AS text_score,
             CASE
               WHEN length(regexp_replace(lower(COALESCE(c.document_number, '')), '[^a-z0-9]+', '', 'g')) >= 5
                AND position(
                  regexp_replace(lower(c.document_number), '[^a-z0-9]+', '', 'g')
                  IN regexp_replace(lower(v_bank_text), '[^a-z0-9]+', '', 'g')
                ) > 0 THEN 1
               WHEN public.finance_bank_match_text_score(v_bank_text, c.document_text) >= 2 THEN 2
               WHEN public.finance_bank_match_text_score(v_bank_text, c.document_text) >= 1
                AND v_line.transaction_date = c.settlement_date THEN 3
               ELSE NULL
             END AS match_tier
      FROM source_candidates c
      WHERE abs(c.remaining_amount - v_bank_amount) <= 1
    ), best AS (
      SELECT s.*
      FROM scored s
      WHERE s.match_tier IS NOT NULL
        AND s.match_tier = (SELECT min(match_tier) FROM scored WHERE match_tier IS NOT NULL)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(best) ORDER BY match_tier, settlement_date, document_type, document_id), '[]'::jsonb)
    INTO v_candidates
    FROM best;

    v_candidate_count := jsonb_array_length(v_candidates);
    IF v_candidate_count = 1 THEN
      v_candidate := v_candidates->0;
      BEGIN
        PERFORM public.link_bank_statement_line(
          v_line.id,
          v_candidate->>'document_type',
          (v_candidate->>'document_id')::uuid,
          'supplier',
          v_bank_amount
        );
        UPDATE public.bank_statement_lines
        SET notes = 'Canonical auto-match: existing bank journal; tier '
                    || (v_candidate->>'match_tier')
                    || ', text score ' || (v_candidate->>'text_score'),
            manually_unlinked = false
        WHERE id = v_line.id;
        v_matched := v_matched + 1;
        CONTINUE;
      EXCEPTION WHEN OTHERS THEN
        -- The subtransaction rolls back every attempted allocation/update for
        -- this line. Other independent lines may still be considered.
        v_skipped := v_skipped + 1;
        CONTINUE;
      END;
    ELSIF v_candidate_count > 1 THEN
      -- Equal-strength candidates are deliberately left fully unmatched.
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    -- A directly-recorded approved Expense can initially be an AP posting
    -- because no bank line was selected on entry. Only reclassify that same
    -- journal to the selected bank when a unique, exact remaining amount also
    -- has business-text evidence. The existing approved-expense atomic edit
    -- command preserves the journal identity and creates the allocation.
    IF v_direction = 'debit' THEN
      WITH expense_candidates AS MATERIALIZED (
        SELECT fe.id AS document_id,
               fe.voucher_number AS document_number,
               fe.expense_date AS settlement_date,
               je.id AS journal_entry_id,
               public.calculate_finance_expense_payable(fe.id)
                 - COALESCE(fe.paid_amount, 0) AS remaining_amount,
               concat_ws(
                 ' ', fe.voucher_number, fe.invoice_number, fe.payment_reference,
                 fe.description, ic.container_ref, supplier.company_name,
                 staff.full_name, je.reference_number,
                 je.description,
                 (SELECT string_agg(l.description, ' ' ORDER BY l.line_number)
                  FROM public.journal_entry_lines l
                  WHERE l.journal_entry_id = je.id)
               ) AS document_text
        FROM public.finance_expenses fe
        LEFT JOIN public.import_containers ic ON ic.id = fe.import_container_id
        LEFT JOIN public.suppliers supplier ON supplier.id = fe.supplier_id
        LEFT JOIN public.finance_staff_master staff ON staff.id = fe.staff_id
        JOIN LATERAL (
          SELECT j.*
          FROM public.journal_entries j
          WHERE j.source_module IN ('expense', 'expenses')
            AND (j.reference_id = fe.id OR j.reference_number = 'EXP-' || fe.id::text)
            AND j.is_posted
            AND NOT COALESCE(j.is_reversed, false)
          ORDER BY j.created_at DESC, j.id DESC
          LIMIT 1
        ) je ON true
        WHERE fe.approval_status = 'approved'
          AND fe.payment_method IS NULL
          AND fe.bank_account_id IS NULL
          AND COALESCE(fe.paid_amount, 0) <= 0.01
          AND COALESCE(fe.pph_paid_amount, 0) <= 0.01
          AND abs(v_line.transaction_date - fe.expense_date) <= 7
          AND NOT EXISTS (
            SELECT 1 FROM public.voucher_allocations va
            WHERE va.finance_expense_id = fe.id
          )
          AND NOT EXISTS (
            SELECT 1 FROM public.bank_statement_allocations a
            WHERE a.document_type = 'expense' AND a.document_id = fe.id
          )
      ), scored AS MATERIALIZED (
        SELECT c.*,
               public.finance_bank_match_text_score(v_bank_text, c.document_text) AS text_score,
               CASE
                 WHEN length(regexp_replace(lower(COALESCE(c.document_number, '')), '[^a-z0-9]+', '', 'g')) >= 5
                  AND position(
                    regexp_replace(lower(c.document_number), '[^a-z0-9]+', '', 'g')
                    IN regexp_replace(lower(v_bank_text), '[^a-z0-9]+', '', 'g')
                  ) > 0 THEN 1
                 WHEN public.finance_bank_match_text_score(v_bank_text, c.document_text) >= 2 THEN 2
                 WHEN public.finance_bank_match_text_score(v_bank_text, c.document_text) >= 1
                  AND v_line.transaction_date = c.settlement_date THEN 3
                 ELSE NULL
               END AS match_tier
        FROM expense_candidates c
        WHERE abs(c.remaining_amount - v_bank_amount) <= 1
      ), best AS (
        SELECT s.*
        FROM scored s
        WHERE s.match_tier IS NOT NULL
          AND s.match_tier = (SELECT min(match_tier) FROM scored WHERE match_tier IS NOT NULL)
      )
      SELECT COALESCE(jsonb_agg(to_jsonb(best) ORDER BY match_tier, settlement_date, document_id), '[]'::jsonb)
      INTO v_candidates
      FROM best;

      v_candidate_count := jsonb_array_length(v_candidates);
      IF v_candidate_count = 1 THEN
        v_candidate := v_candidates->0;
        SELECT * INTO v_expense
        FROM public.finance_expenses
        WHERE id = (v_candidate->>'document_id')::uuid
        FOR UPDATE;

        v_payload := to_jsonb(v_expense) || jsonb_build_object(
          'payment_method', 'bank_transfer',
          'bank_account_id', v_line.bank_account_id,
          'paid_by', 'bank',
          'payment_reference', COALESCE(NULLIF(v_line.reference, ''), v_expense.payment_reference),
          'transaction_currency', upper(COALESCE(v_line.currency, v_expense.transaction_currency, 'IDR')),
          'currency_code', upper(COALESCE(v_line.currency, v_expense.currency_code, 'IDR')),
          'functional_currency', 'IDR',
          'exchange_rate', CASE
            WHEN upper(COALESCE(v_line.currency, v_expense.transaction_currency, 'IDR')) = 'IDR' THEN 1
            ELSE v_expense.exchange_rate
          END
        );

        BEGIN
          PERFORM public.edit_approved_finance_expense_atomic(
            v_expense.id,
            v_payload,
            v_line.id,
            v_bank_amount
          );
          UPDATE public.bank_statement_lines
          SET notes = 'Canonical auto-match: unique existing Expense; tier '
                      || (v_candidate->>'match_tier')
                      || ', text score ' || (v_candidate->>'text_score'),
              manually_unlinked = false
          WHERE id = v_line.id;
          v_matched := v_matched + 1;
        EXCEPTION WHEN OTHERS THEN
          v_skipped := v_skipped + 1;
        END;
      ELSIF v_candidate_count > 1 THEN
        v_skipped := v_skipped + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_matched, v_suggested, v_skipped;
END;
$$;


--
-- Name: FUNCTION "auto_match_smart"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."auto_match_smart"() IS 'Canonical atomic matcher: unique bank-journal documents first; unique exact directly-recorded Expenses only with date/account/direction and business-text evidence. Ambiguity remains unmatched.';


--
-- Name: auto_match_smart_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_match_smart_legacy"() RETURNS TABLE("matched_count" integer, "suggested_count" integer, "skipped_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_line public.bank_statement_lines%rowtype;
  v_candidate record;
  v_amount numeric;
  v_direction text;
  v_score integer;
  v_matched integer:=0;
  v_suggested integer:=0;
  v_skipped integer:=0;
BEGIN
  PERFORM public._sec_check_finance_role();

  FOR v_line IN
    SELECT * FROM public.bank_statement_lines b
     WHERE b.reconciliation_status='unmatched'
       AND b.matched_expense_id IS NULL AND b.matched_receipt_id IS NULL
       AND b.matched_payment_id IS NULL AND b.matched_petty_cash_id IS NULL
       AND b.matched_fund_transfer_id IS NULL AND b.matched_tax_payment_id IS NULL
       AND b.matched_entry_id IS NULL
     ORDER BY b.transaction_date,b.id
  LOOP
    v_amount:=CASE WHEN COALESCE(v_line.credit_amount,0)>0
                   THEN v_line.credit_amount ELSE v_line.debit_amount END;
    v_direction:=CASE WHEN COALESCE(v_line.credit_amount,0)>0 THEN 'credit' ELSE 'debit' END;

    SELECT s.*,
           abs(s.settlement_amount-v_amount) amount_diff,
           abs(v_line.transaction_date::date-s.settlement_date) date_diff
      INTO v_candidate
      FROM public.vw_finance_document_settlements s
     WHERE s.bank_account_id=v_line.bank_account_id
       AND s.direction=v_direction
       AND abs(v_line.transaction_date::date-s.settlement_date)<=7
       AND abs(s.settlement_amount-v_amount)<=greatest(1,v_amount*0.05)
       AND NOT EXISTS (
         SELECT 1 FROM public.bank_statement_lines used
          WHERE used.id<>v_line.id AND used.matched_entry_id=s.journal_entry_id
            AND used.bank_account_id=s.bank_account_id
            AND (CASE WHEN COALESCE(used.credit_amount,0)>0 THEN 'credit' ELSE 'debit' END)=s.direction
       )
     ORDER BY abs(s.settlement_amount-v_amount),
              abs(v_line.transaction_date::date-s.settlement_date),s.document_type,s.document_id
     LIMIT 1;

    IF NOT FOUND THEN CONTINUE; END IF;
    v_score:=CASE
      WHEN v_candidate.amount_diff<0.01 THEN 70
      WHEN v_candidate.amount_diff<=100 THEN 55
      WHEN v_candidate.amount_diff<=1000 THEN 40
      ELSE 25 END
      + CASE WHEN v_candidate.date_diff=0 THEN 20
             WHEN v_candidate.date_diff<=1 THEN 15
             WHEN v_candidate.date_diff<=3 THEN 10 ELSE 5 END
      + 10; -- exact bank account and direction are mandatory above

    IF v_score<70 THEN CONTINUE; END IF;
    UPDATE public.bank_statement_lines SET
      matched_expense_id=CASE WHEN v_candidate.document_type='expense' THEN v_candidate.document_id ELSE NULL END,
      matched_receipt_id=CASE WHEN v_candidate.document_type='receipt' THEN v_candidate.document_id ELSE NULL END,
      matched_payment_id=CASE WHEN v_candidate.document_type='payment' THEN v_candidate.document_id ELSE NULL END,
      matched_fund_transfer_id=CASE WHEN v_candidate.document_type='fund_transfer' THEN v_candidate.document_id ELSE NULL END,
      matched_petty_cash_id=CASE WHEN v_candidate.document_type='petty_cash' THEN v_candidate.document_id ELSE NULL END,
      matched_tax_payment_id=CASE WHEN v_candidate.document_type='tax_payment' THEN v_candidate.document_id ELSE NULL END,
      matched_entry_id=v_candidate.journal_entry_id,
      reconciliation_status=CASE WHEN v_score>=85 THEN 'matched' ELSE 'needs_review' END,
      matching_status=CASE WHEN v_score>=85 THEN 'confirmed' ELSE 'suggested' END,
      matched_at=now(),matched_by=auth.uid(),manually_unlinked=false,
      notes='Canonical settlement auto-match (confidence: '||v_score||'%)'
    WHERE id=v_line.id;

    IF v_candidate.document_type='expense' THEN
      PERFORM public.recalculate_expense_payment_state(v_candidate.document_id);
    END IF;
    IF v_score>=85 THEN v_matched:=v_matched+1; ELSE v_suggested:=v_suggested+1; END IF;
  END LOOP;
  RETURN QUERY SELECT v_matched,v_suggested,v_skipped;
END;
$$;


--
-- Name: auto_post_expense_accounting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_post_expense_accounting"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_expense_account_id uuid;
  v_payment_account_id uuid;
  v_journal_id uuid;
  v_active_count integer;
  v_description text;
  v_credit_desc text;
  v_category_label text;
  v_bm_account_id uuid;
  v_ppn_account_id uuid;
  v_pph_account_id uuid;
  v_stamp_duty_account_id uuid;
  v_bank_charge_acc_id uuid;
  v_line_num integer;
  v_net_payment numeric(18,2);
  v_total numeric(18,2);
  v_bank_charges numeric(18,2);
BEGIN
  IF NEW.approval_status <> 'approved' THEN RETURN NEW; END IF;

  IF TG_OP='UPDATE' AND OLD.approval_status='approved' THEN
    IF ROW(
      OLD.amount,OLD.expense_category,OLD.expense_date,OLD.description,
      OLD.payment_method,OLD.bank_account_id,OLD.pib_bm_amount,OLD.pib_ppn_amount,
      OLD.pib_pph_amount,OLD.ppn_amount,OLD.pph_amount,OLD.stamp_duty_amount,
      OLD.fixed_asset_account_id,COALESCE(OLD.bank_charges_amount,0),
      OLD.transaction_currency,OLD.exchange_rate,OLD.supplier_id
    ) IS NOT DISTINCT FROM ROW(
      NEW.amount,NEW.expense_category,NEW.expense_date,NEW.description,
      NEW.payment_method,NEW.bank_account_id,NEW.pib_bm_amount,NEW.pib_ppn_amount,
      NEW.pib_pph_amount,NEW.ppn_amount,NEW.pph_amount,NEW.stamp_duty_amount,
      NEW.fixed_asset_account_id,COALESCE(NEW.bank_charges_amount,0),
      NEW.transaction_currency,NEW.exchange_rate,NEW.supplier_id
    ) THEN
      RETURN NEW;
    END IF;
  END IF;

  SELECT count(*), (array_agg(id ORDER BY created_at DESC,id DESC))[1]
    INTO v_active_count,v_journal_id
    FROM public.journal_entries
   WHERE source_module IN('expense','expenses')
     AND (reference_id=NEW.id OR reference_number='EXP-'||NEW.id::text)
     AND is_posted=true AND NOT COALESCE(is_reversed,false);

  IF v_active_count>1 THEN
    RAISE EXCEPTION 'Expense % has multiple active journals; edit is blocked',NEW.id;
  END IF;
  IF TG_OP='UPDATE' AND OLD.approval_status='approved' AND v_active_count<>1 THEN
    RAISE EXCEPTION 'Approved expense % must have exactly one active journal before edit',NEW.id;
  END IF;
  IF v_journal_id IS NOT NULL THEN
    PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;
    DELETE FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;
  END IF;

  IF NEW.payment_method='cash' THEN
    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;
  ELSIF NEW.payment_method='petty_cash' THEN
    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;
  ELSIF NEW.payment_method = 'bank_transfer' THEN
    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;
  ELSIF NEW.payment_method IS NOT NULL AND NEW.bank_account_id IS NOT NULL THEN
    SELECT coa_id INTO v_payment_account_id FROM public.bank_accounts WHERE id=NEW.bank_account_id;
  ELSIF NEW.payment_method IS NULL THEN
    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;
  END IF;
  IF v_payment_account_id IS NULL THEN
    RAISE EXCEPTION 'Cannot post expense %: the selected payment/AP account is not configured',NEW.id;
  END IF;

  IF NEW.expense_category='pib_import' THEN
    v_bm_account_id:=public.get_expense_account_id('duty_customs');
    v_ppn_account_id:=public.get_expense_account_id('ppn_import');
    v_pph_account_id:=public.get_expense_account_id('pph_import');
    IF COALESCE(NEW.pib_bm_amount,0)>0 AND v_bm_account_id IS NULL THEN RAISE EXCEPTION 'Import Duty account is missing'; END IF;
    IF COALESCE(NEW.pib_ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Import account is missing'; END IF;
    IF COALESCE(NEW.pib_pph_amount,0)>0 AND v_pph_account_id IS NULL THEN RAISE EXCEPTION 'PPh Import account is missing'; END IF;
    v_total:=NEW.amount;
    v_journal_id:=public.upsert_expense_journal_header_in_place(
      v_journal_id,NEW.id,NEW.expense_date,COALESCE(NEW.description,'PIB Import Payment'),
      'pib_import',v_total,NEW.created_by);
    v_line_num:=1;
    IF COALESCE(NEW.pib_bm_amount,0)>0 THEN
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)
      VALUES(v_journal_id,v_line_num,v_bm_account_id,NEW.pib_bm_amount,0,'PIB - Import Duty (BM) [landed cost]');
      v_line_num:=v_line_num+1;
    END IF;
    IF COALESCE(NEW.pib_ppn_amount,0)>0 THEN
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)
      VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.pib_ppn_amount,0,'PIB - PPN Import (Input VAT)');
      v_line_num:=v_line_num+1;
    END IF;
    IF COALESCE(NEW.pib_pph_amount,0)>0 THEN
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)
      VALUES(v_journal_id,v_line_num,v_pph_account_id,NEW.pib_pph_amount,0,'PIB - PPh 22 Dibayar Dimuka');
      v_line_num:=v_line_num+1;
    END IF;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)
    VALUES(v_journal_id,v_line_num,v_payment_account_id,0,NEW.amount,'PIB - Payment ['||COALESCE(NEW.description,'')||']');
    RETURN NEW;
  END IF;

  IF NEW.expense_category='fixed_asset' THEN
    v_expense_account_id:=NEW.fixed_asset_account_id;
    IF v_expense_account_id IS NULL THEN RAISE EXCEPTION 'A posting Fixed Asset account is required'; END IF;
    SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;
    IF COALESCE(NEW.ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Masukan account 1150 is missing'; END IF;
    v_description:=COALESCE(NEW.description,'Fixed Asset Purchase');
    v_total:=NEW.amount+COALESCE(NEW.ppn_amount,0);
    v_journal_id:=public.upsert_expense_journal_header_in_place(
      v_journal_id,NEW.id,NEW.expense_date,v_description,'fixed_asset',v_total,NEW.created_by);
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)
    VALUES(v_journal_id,1,v_expense_account_id,NEW.amount,0,v_description);
    v_line_num:=2;
    IF COALESCE(NEW.ppn_amount,0)>0 THEN
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)
      VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.ppn_amount,0,'PPN Masukan - '||v_description);
      v_line_num:=v_line_num+1;
    END IF;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)
    VALUES(v_journal_id,v_line_num,v_payment_account_id,0,v_total,v_description);
    RETURN NEW;
  END IF;

  v_expense_account_id:=CASE WHEN public.is_capitalizable_landed_cost_category(NEW.expense_category) THEN (SELECT id FROM public.chart_of_accounts WHERE code='1130' LIMIT 1) ELSE public.get_expense_account_id(NEW.expense_category) END;
  IF v_expense_account_id IS NULL THEN RAISE EXCEPTION 'No expense account is mapped for %',NEW.expense_category; END IF;
  v_category_label:=initcap(replace(NEW.expense_category,'_',' '));
  v_description:=COALESCE(NEW.description,NEW.expense_category);
  v_credit_desc:=COALESCE(substring(NEW.description FROM '^[^\n]+'),NEW.expense_category)||' ['||v_category_label||']';
  SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;
  SELECT id INTO v_pph_account_id FROM public.chart_of_accounts WHERE code='2132' LIMIT 1;
  SELECT id INTO v_stamp_duty_account_id FROM public.chart_of_accounts WHERE code='6950' LIMIT 1;
  IF COALESCE(NEW.ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Masukan account 1150 is missing'; END IF;
  IF COALESCE(NEW.pph_amount,0)>0 AND v_pph_account_id IS NULL THEN RAISE EXCEPTION 'PPh Payable account 2132 is missing'; END IF;
  IF COALESCE(NEW.stamp_duty_amount,0)>0 AND v_stamp_duty_account_id IS NULL THEN RAISE EXCEPTION 'Stamp Duty account 6950 is missing'; END IF;
  v_bank_charges:=CASE WHEN NEW.expense_category='utilities' THEN COALESCE(NEW.bank_charges_amount,0) ELSE 0 END;
  IF v_bank_charges>0 THEN
    v_bank_charge_acc_id:=public.get_expense_account_id('bank_charges');
    IF v_bank_charge_acc_id IS NULL THEN RAISE EXCEPTION 'Bank Charges account is missing'; END IF;
  END IF;
  v_net_payment:=NEW.amount+COALESCE(NEW.ppn_amount,0)-COALESCE(NEW.pph_amount,0)+COALESCE(NEW.stamp_duty_amount,0)+v_bank_charges;
  v_total:=NEW.amount+COALESCE(NEW.ppn_amount,0)+COALESCE(NEW.stamp_duty_amount,0)+v_bank_charges;
  v_journal_id:=public.upsert_expense_journal_header_in_place(
    v_journal_id,NEW.id,NEW.expense_date,v_description,NEW.expense_category,v_total,NEW.created_by);
  v_line_num:=1;
  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
  VALUES(v_journal_id,v_line_num,v_expense_account_id,NEW.amount,0,v_credit_desc,NEW.supplier_id);
  v_line_num:=v_line_num+1;
  IF COALESCE(NEW.ppn_amount,0)>0 THEN
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
    VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.ppn_amount,0,'PPN Masukan - '||v_description,NEW.supplier_id);
    v_line_num:=v_line_num+1;
  END IF;
  IF COALESCE(NEW.stamp_duty_amount,0)>0 THEN
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
    VALUES(v_journal_id,v_line_num,v_stamp_duty_account_id,NEW.stamp_duty_amount,0,'Bea Meterai - '||v_description,NEW.supplier_id);
    v_line_num:=v_line_num+1;
  END IF;
  IF v_bank_charges>0 THEN
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
    VALUES(v_journal_id,v_line_num,v_bank_charge_acc_id,v_bank_charges,0,'Bank charges ['||v_category_label||']',NEW.supplier_id);
    v_line_num:=v_line_num+1;
  END IF;
  IF COALESCE(NEW.pph_amount,0)>0 THEN
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
    VALUES(v_journal_id,v_line_num,v_pph_account_id,0,NEW.pph_amount,'PPh Ditahan - '||v_description,NEW.supplier_id);
    v_line_num:=v_line_num+1;
  END IF;
  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
  VALUES(v_journal_id,v_line_num,v_payment_account_id,0,v_net_payment,v_credit_desc,NEW.supplier_id);
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "auto_post_expense_accounting"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."auto_post_expense_accounting"() IS 'Auto-posts journal entries for finance_expenses.
UPDATE path: deletes ALL existing JEs for the expense (not just one) before recreating,
so pre-existing duplicates are always cleared.
pib_import: 4-line split (Dr BM/1130 inventory, Dr PPN Masukan/1150, Dr PPh22/1155, Cr Bank).
All other categories: standard 2-line (Dr expense account, Cr payment account).';


--
-- Name: auto_post_fund_transfer_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_post_fund_transfer_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_from_coa uuid; v_to_coa uuid; v_from_currency text; v_to_currency text;
  v_from numeric; v_to numeric; v_functional numeric; v_rate numeric;
  v_je uuid; v_entry text; v_desc text; v_bank_amount numeric;
BEGIN
  IF NEW.journal_entry_id IS NOT NULL THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.journal_entries WHERE reference_number=NEW.transfer_number
             AND source_module='fund_transfers') THEN
    SELECT id INTO v_je FROM public.journal_entries WHERE reference_number=NEW.transfer_number
      AND source_module='fund_transfers' ORDER BY created_at DESC LIMIT 1;
    UPDATE public.fund_transfers SET journal_entry_id=v_je WHERE id=NEW.id;
    RETURN NEW;
  END IF;

  IF NEW.from_account_type='bank' THEN
    SELECT coa_id,upper(currency) INTO v_from_coa,v_from_currency FROM public.bank_accounts WHERE id=NEW.from_bank_account_id;
  ELSIF NEW.from_account_type='petty_cash' THEN
    SELECT id,'IDR' INTO v_from_coa,v_from_currency FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;
  ELSE
    SELECT id,'IDR' INTO v_from_coa,v_from_currency FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;
  END IF;
  IF NEW.to_account_type='bank' THEN
    SELECT coa_id,upper(currency) INTO v_to_coa,v_to_currency FROM public.bank_accounts WHERE id=NEW.to_bank_account_id;
  ELSIF NEW.to_account_type='petty_cash' THEN
    SELECT id,'IDR' INTO v_to_coa,v_to_currency FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;
  ELSE
    SELECT id,'IDR' INTO v_to_coa,v_to_currency FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;
  END IF;
  IF v_from_coa IS NULL OR v_to_coa IS NULL THEN RAISE EXCEPTION 'Cannot determine transfer accounts'; END IF;
  v_from:=round(COALESCE(NEW.from_amount,NEW.amount),2);
  v_to:=round(COALESCE(NEW.to_amount,NEW.amount),2);
  IF v_from<=0 OR v_to<=0 THEN RAISE EXCEPTION 'Transfer amounts must be positive'; END IF;
  v_rate:=CASE WHEN v_from_currency=v_to_currency THEN 1 ELSE COALESCE(NEW.exchange_rate,v_to/v_from) END;
  IF v_rate<=0 THEN RAISE EXCEPTION 'Transfer exchange rate must be positive'; END IF;
  v_functional:=CASE WHEN v_from_currency='IDR' THEN v_from WHEN v_to_currency='IDR' THEN v_to ELSE v_from END;
  v_desc:='Fund Transfer '||NEW.transfer_number;
  IF v_from_currency<>v_to_currency THEN v_desc:=v_desc||' (FX: '||v_from_currency||' → '||v_to_currency||')'; END IF;
  IF NEW.description IS NOT NULL THEN v_desc:=v_desc||' - '||NEW.description; END IF;
  SELECT public.generate_journal_entry_number() INTO v_entry;
  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,
    description,total_debit,total_credit,is_posted,created_by,transaction_currency,functional_currency,exchange_rate)
  VALUES(v_entry,NEW.transfer_date,'fund_transfers',NEW.id,NEW.transfer_number,v_desc,v_functional,v_functional,true,NEW.created_by,
    CASE WHEN v_from_currency=v_to_currency THEN v_from_currency ELSE NULL END,'IDR',v_rate)
  RETURNING id INTO v_je;
  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,
    transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
  VALUES
    (v_je,1,v_to_coa,v_functional,0,'Transfer In: '||NEW.transfer_number,v_to_currency,v_to,0,'IDR',v_rate),
    (v_je,2,v_from_coa,0,v_functional,'Transfer Out: '||NEW.transfer_number,v_from_currency,0,v_from,'IDR',v_rate);
  UPDATE public.fund_transfers SET journal_entry_id=v_je,status='posted',posted_at=now(),posted_by=NEW.created_by WHERE id=NEW.id;

  IF NEW.from_bank_statement_line_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(debit_amount,0),credit_amount,0) INTO v_bank_amount FROM public.bank_statement_lines WHERE id=NEW.from_bank_statement_line_id FOR UPDATE;
    IF v_bank_amount IS NULL OR abs(v_bank_amount-v_from)>0.01 THEN RAISE EXCEPTION 'Transfer-out bank evidence amount mismatch'; END IF;
    INSERT INTO public.bank_statement_allocations(bank_statement_line_id,document_type,document_id,journal_entry_id,allocation_amount,payment_kind,created_by)
      VALUES(NEW.from_bank_statement_line_id,'fund_transfer',NEW.id,v_je,round(v_bank_amount,2),'supplier',NEW.created_by)
      ON CONFLICT (bank_statement_line_id,document_type,document_id,payment_kind) DO NOTHING;
    UPDATE public.bank_statement_lines SET matched_fund_transfer_id=NEW.id,matched_entry_id=v_je,reconciliation_status='matched',matched_at=now(),matched_by=NEW.created_by WHERE id=NEW.from_bank_statement_line_id;
  END IF;
  IF NEW.to_bank_statement_line_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(debit_amount,0),credit_amount,0) INTO v_bank_amount FROM public.bank_statement_lines WHERE id=NEW.to_bank_statement_line_id FOR UPDATE;
    IF v_bank_amount IS NULL OR abs(v_bank_amount-v_to)>0.01 THEN RAISE EXCEPTION 'Transfer-in bank evidence amount mismatch'; END IF;
    INSERT INTO public.bank_statement_allocations(bank_statement_line_id,document_type,document_id,journal_entry_id,allocation_amount,payment_kind,created_by)
      VALUES(NEW.to_bank_statement_line_id,'fund_transfer',NEW.id,v_je,round(v_bank_amount,2),'supplier',NEW.created_by)
      ON CONFLICT (bank_statement_line_id,document_type,document_id,payment_kind) DO NOTHING;
    UPDATE public.bank_statement_lines SET matched_fund_transfer_id=NEW.id,matched_entry_id=v_je,reconciliation_status='matched',matched_at=now(),matched_by=NEW.created_by WHERE id=NEW.to_bank_statement_line_id;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION "auto_post_fund_transfer_journal"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."auto_post_fund_transfer_journal"() IS 'Posts new transfers with functional IDR and explicit transaction-currency bank legs; creates canonical allocations only when evidenced bank lines are supplied.';


--
-- Name: auto_post_loan_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_post_loan_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_je_id uuid; v_bank_coa_id uuid; v_loan_coa_id uuid; v_description text;
  v_currency text; v_bank_currency text; v_rate numeric; v_functional_amount numeric;
BEGIN
  IF COALESCE(current_setting('app.finance_metadata_repair',true),'off')='on' THEN RETURN NEW; END IF;
  SELECT coa_id,upper(currency) INTO v_bank_coa_id,v_bank_currency
  FROM public.bank_accounts WHERE id=NEW.bank_account_id AND is_active=true;
  IF v_bank_coa_id IS NULL THEN RAISE EXCEPTION 'Loan bank account is missing or has no active GL account'; END IF;
  v_currency:=upper(COALESCE(NEW.transaction_currency,NEW.currency,v_bank_currency,'IDR'));
  v_rate:=CASE WHEN v_currency='IDR' THEN 1 ELSE NEW.exchange_rate END;
  IF v_currency NOT IN('IDR','USD') OR v_rate IS NULL OR v_rate<=0 OR (v_currency='USD' AND v_rate<=1) THEN
    RAISE EXCEPTION 'Loan currency or exchange rate is invalid';
  END IF;
  IF v_bank_currency<>v_currency THEN RAISE EXCEPTION 'Loan currency % does not match bank currency %',v_currency,v_bank_currency; END IF;
  v_loan_coa_id:=NEW.coa_id;
  IF v_loan_coa_id IS NULL THEN
    SELECT id INTO v_loan_coa_id FROM public.chart_of_accounts
    WHERE code=CASE WHEN NEW.loan_type='taken' THEN '2210' ELSE '1310' END
      AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1;
  END IF;
  IF v_loan_coa_id IS NULL THEN RAISE EXCEPTION 'Loan control account is not configured'; END IF;
  NEW.transaction_currency:=v_currency; NEW.currency:=v_currency; NEW.functional_currency:='IDR';
  NEW.bank_account_currency:=v_bank_currency; NEW.exchange_rate:=v_rate;
  NEW.outstanding_balance:=NEW.principal_amount;
  v_functional_amount:=round(NEW.principal_amount*v_rate,2);
  v_description:=COALESCE(NULLIF(NEW.description,''),CASE WHEN NEW.loan_type='taken' THEN 'Loan received from ' ELSE 'Loan given to ' END||NEW.counterparty_name);
  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,
    total_debit,total_credit,is_posted,posted_at,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
  VALUES(public.generate_journal_entry_number(),NEW.loan_date,'loans',NEW.id,NEW.loan_number,v_description,
    v_functional_amount,v_functional_amount,true,now(),NEW.created_by,NEW.created_by,v_currency,'IDR',v_rate,true)
  RETURNING id INTO v_je_id;
  IF NEW.loan_type='taken' THEN
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,
      transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
    VALUES(v_je_id,1,v_bank_coa_id,v_description,v_functional_amount,0,v_currency,NEW.principal_amount,0,'IDR',v_rate),
          (v_je_id,2,v_loan_coa_id,v_description,0,v_functional_amount,v_currency,0,NEW.principal_amount,'IDR',v_rate);
  ELSE
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,
      transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
    VALUES(v_je_id,1,v_loan_coa_id,v_description,v_functional_amount,0,v_currency,NEW.principal_amount,0,'IDR',v_rate),
          (v_je_id,2,v_bank_coa_id,v_description,0,v_functional_amount,v_currency,0,NEW.principal_amount,'IDR',v_rate);
  END IF;
  NEW.journal_entry_id:=v_je_id;
  RETURN NEW;
END $$;


--
-- Name: auto_post_loan_transaction_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_post_loan_transaction_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_loan public.loans%ROWTYPE; v_je_id uuid; v_bank_coa_id uuid; v_bank_currency text;
  v_loan_coa_id uuid; v_interest_coa_id uuid; v_currency text; v_rate numeric;
  v_amount numeric; v_principal numeric; v_interest numeric; v_description text; v_line integer:=0;
BEGIN
  IF COALESCE(current_setting('app.finance_metadata_repair',true),'off')='on' THEN RETURN NEW; END IF;
  SELECT * INTO v_loan FROM public.loans WHERE id=NEW.loan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Loan not found'; END IF;
  SELECT coa_id,upper(currency) INTO v_bank_coa_id,v_bank_currency FROM public.bank_accounts
    WHERE id=COALESCE(NEW.bank_account_id,v_loan.bank_account_id) AND is_active=true;
  IF v_bank_coa_id IS NULL THEN RAISE EXCEPTION 'Repayment bank account is missing or has no active GL account'; END IF;
  v_currency:=upper(COALESCE(NEW.transaction_currency,v_loan.transaction_currency,v_loan.currency,'IDR'));
  v_rate:=CASE WHEN v_currency='IDR' THEN 1 ELSE COALESCE(NEW.exchange_rate,v_loan.exchange_rate) END;
  IF v_currency<>upper(COALESCE(v_loan.transaction_currency,v_loan.currency)) OR v_currency<>v_bank_currency THEN
    RAISE EXCEPTION 'Repayment, loan and bank currencies must match';
  END IF;
  IF v_rate IS NULL OR v_rate<=0 OR (v_currency='USD' AND v_rate<=1) THEN RAISE EXCEPTION 'Repayment exchange rate is invalid'; END IF;
  IF NEW.transaction_type IN('repayment','interest_payment') AND NEW.principal_amount>v_loan.outstanding_balance THEN
    RAISE EXCEPTION 'Principal repayment exceeds outstanding balance';
  END IF;
  IF abs(NEW.amount-(NEW.principal_amount+NEW.interest_amount))>0.01 THEN RAISE EXCEPTION 'Principal plus interest must equal repayment amount'; END IF;
  v_loan_coa_id:=v_loan.coa_id;
  IF v_loan_coa_id IS NULL THEN SELECT id INTO v_loan_coa_id FROM public.chart_of_accounts WHERE code=CASE WHEN v_loan.loan_type='taken' THEN '2210' ELSE '1310' END AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1; END IF;
  v_interest_coa_id:=v_loan.interest_coa_id;
  IF v_interest_coa_id IS NULL THEN SELECT id INTO v_interest_coa_id FROM public.chart_of_accounts WHERE code=CASE WHEN v_loan.loan_type='taken' THEN '7200' ELSE '4920' END AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1; END IF;
  v_amount:=round(NEW.amount*v_rate,2); v_principal:=round(NEW.principal_amount*v_rate,2); v_interest:=round(NEW.interest_amount*v_rate,2);
  v_description:=COALESCE(NULLIF(NEW.description,''),'Loan repayment - '||v_loan.counterparty_name);
  NEW.transaction_currency:=v_currency; NEW.functional_currency:='IDR'; NEW.bank_account_currency:=v_bank_currency; NEW.exchange_rate:=v_rate; NEW.status:='posted';
  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,
    is_posted,posted_at,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
  VALUES(public.generate_journal_entry_number(),NEW.transaction_date,'loan_transactions',NEW.id,NEW.transaction_number,v_description,v_amount,v_amount,
    true,now(),NEW.created_by,NEW.created_by,v_currency,'IDR',v_rate,true) RETURNING id INTO v_je_id;
  IF v_loan.loan_type='taken' THEN
    IF NEW.principal_amount>0 THEN v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_loan_coa_id,v_description,v_principal,0,v_currency,NEW.principal_amount,0,'IDR',v_rate); END IF;
    IF NEW.interest_amount>0 THEN v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_interest_coa_id,v_description,v_interest,0,v_currency,NEW.interest_amount,0,'IDR',v_rate); END IF;
    v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_bank_coa_id,v_description,0,v_amount,v_currency,0,NEW.amount,'IDR',v_rate);
  ELSE
    v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_bank_coa_id,v_description,v_amount,0,v_currency,NEW.amount,0,'IDR',v_rate);
    IF NEW.principal_amount>0 THEN v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_loan_coa_id,v_description,0,v_principal,v_currency,0,NEW.principal_amount,'IDR',v_rate); END IF;
    IF NEW.interest_amount>0 THEN v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_interest_coa_id,v_description,0,v_interest,v_currency,0,NEW.interest_amount,'IDR',v_rate); END IF;
  END IF;
  NEW.journal_entry_id:=v_je_id;
  RETURN NEW;
END $$;


--
-- Name: auto_reconcile_tax_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_reconcile_tax_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tax_payment_id uuid;
  v_is_tax_je      boolean := false;
BEGIN
  IF NEW.is_matched = true
     AND (OLD.is_matched IS DISTINCT FROM NEW.is_matched)
     AND NEW.journal_entry_id IS NOT NULL
  THEN
    -- Only act on tax_payment JEs
    SELECT EXISTS (
      SELECT 1 FROM journal_entries
       WHERE id = NEW.journal_entry_id
         AND source_module = 'tax_payment'
    ) INTO v_is_tax_je;

    IF v_is_tax_je THEN
      SELECT id INTO v_tax_payment_id
        FROM tax_payments
       WHERE journal_entry_id = NEW.journal_entry_id
         AND status = 'posted';

      IF v_tax_payment_id IS NOT NULL THEN
        UPDATE tax_payments
           SET status = 'reconciled', updated_at = now()
         WHERE id = v_tax_payment_id;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: auto_reconcile_tax_payment_from_bsl(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_reconcile_tax_payment_from_bsl"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tax_payment_id uuid;
  v_is_tax_je      boolean := false;
BEGIN
  -- ── MATCH path ──────────────────────────────────────────────────────────
  -- Only fire when status flips to 'matched' AND matched_entry_id is set.
  -- Also guard that the matched_entry_id belongs to a tax_payment JE — this
  -- prevents the trigger from ever touching expense/receipt/petty-cash BSLs.
  IF NEW.reconciliation_status = 'matched'
     AND (OLD.reconciliation_status IS DISTINCT FROM NEW.reconciliation_status)
     AND NEW.matched_entry_id IS NOT NULL
  THEN
    SELECT EXISTS (
      SELECT 1 FROM journal_entries
       WHERE id = NEW.matched_entry_id
         AND source_module = 'tax_payment'
    ) INTO v_is_tax_je;

    IF v_is_tax_je THEN
      SELECT id INTO v_tax_payment_id
        FROM tax_payments
       WHERE journal_entry_id = NEW.matched_entry_id
         AND status IN ('posted', 'draft');

      IF v_tax_payment_id IS NOT NULL THEN
        UPDATE tax_payments
           SET status = 'reconciled', updated_at = now()
         WHERE id = v_tax_payment_id;
        -- Write typed FK for symmetry with other modules
        NEW.matched_tax_payment_id := v_tax_payment_id;
      END IF;
    END IF;
  END IF;

  -- ── UNMATCH path ─────────────────────────────────────────────────────────
  -- Only act when the line had a typed tax_payment FK and now loses it
  -- (or the status reverts from 'matched'). Never touch lines whose
  -- matched_tax_payment_id was never set.
  IF (NEW.reconciliation_status IS DISTINCT FROM 'matched'
      OR NEW.matched_entry_id IS NULL)
     AND OLD.matched_tax_payment_id IS NOT NULL
     AND NEW.matched_tax_payment_id IS NOT DISTINCT FROM OLD.matched_tax_payment_id
  THEN
    -- Verify the payment was actually reconciled (not already reset by delete_tax_payment)
    UPDATE tax_payments
       SET status = 'posted', updated_at = now()
     WHERE id = OLD.matched_tax_payment_id
       AND status = 'reconciled';

    NEW.matched_tax_payment_id := NULL;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: auto_snapshot_company_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_snapshot_company_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  NEW.company_snapshot := public.get_current_company_profile();
  IF NEW.company_snapshot IS NULL THEN
    RAISE EXCEPTION 'Cannot create document: no effective company profile exists';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "auto_snapshot_company_profile"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."auto_snapshot_company_profile"() IS 'Authoritative snapshot source for new documents. Always reads the effective company_profiles row and never changes existing snapshots.';


--
-- Name: auto_update_pipeline_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."auto_update_pipeline_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
-- If all requirements are fulfilled and status is 'in_progress', move to 'follow_up'
IF check_inquiry_requirements_fulfilled(NEW.id) AND NEW.pipeline_status = 'in_progress' THEN
NEW.pipeline_status := 'follow_up';
END IF;

-- If marking as lost, set lost_at timestamp
IF NEW.pipeline_status = 'lost' AND OLD.pipeline_status != 'lost' THEN
NEW.lost_at := now();
END IF;

RETURN NEW;
END;
$$;


--
-- Name: broker_reimbursement_expense_base("jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."broker_reimbursement_expense_base"("p_item" "jsonb") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT public.broker_reimbursement_line_total(p_item)
       - COALESCE((p_item->>'ppn_amount')::numeric, 0)
$$;


--
-- Name: broker_reimbursement_line_total("jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."broker_reimbursement_line_total"("p_item" "jsonb") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE
    WHEN COALESCE((p_item->>'invoice_amount_authoritative')::boolean, false)
      THEN COALESCE((p_item->>'amount')::numeric, 0)
    WHEN COALESCE((p_item->>'amount')::numeric, 0) <> 0
      THEN COALESCE((p_item->>'amount')::numeric, 0)
    ELSE COALESCE((p_item->>'dpp_amount')::numeric, 0)
       + COALESCE((p_item->>'ppn_amount')::numeric, 0)
  END
$$;


--
-- Name: bsl_recalc_expense_paid_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."bsl_recalc_expense_paid_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.matched_expense_id IS NOT NULL THEN
      PERFORM public.recalculate_expense_payment_state(OLD.matched_expense_id);
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.matched_expense_id IS NOT NULL THEN
      PERFORM public.recalculate_expense_payment_state(NEW.matched_expense_id);
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.matched_expense_id IS DISTINCT FROM OLD.matched_expense_id THEN
    IF OLD.matched_expense_id IS NOT NULL THEN
      PERFORM public.recalculate_expense_payment_state(OLD.matched_expense_id);
    END IF;
    IF NEW.matched_expense_id IS NOT NULL THEN
      PERFORM public.recalculate_expense_payment_state(NEW.matched_expense_id);
    END IF;
  ELSIF NEW.matched_expense_id IS NOT NULL
    AND (
      NEW.payment_kind IS DISTINCT FROM OLD.payment_kind
      OR NEW.debit_amount IS DISTINCT FROM OLD.debit_amount
      OR NEW.credit_amount IS DISTINCT FROM OLD.credit_amount
    ) THEN
    PERFORM public.recalculate_expense_payment_state(NEW.matched_expense_id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: bsl_sync_reconciliation_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."bsl_sync_reconciliation_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_has_allocation boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.bank_statement_allocations
    WHERE bank_statement_line_id = NEW.id
  ) INTO v_has_allocation;

  IF NEW.matched_expense_id IS NOT NULL
     OR NEW.matched_receipt_id IS NOT NULL
     OR NEW.matched_payment_id IS NOT NULL
     OR NEW.matched_fund_transfer_id IS NOT NULL
     OR NEW.matched_petty_cash_id IS NOT NULL
     OR NEW.matched_tax_payment_id IS NOT NULL
     OR NEW.matched_entry_id IS NOT NULL
     OR v_has_allocation THEN
    IF NEW.reconciliation_status IS NULL OR NEW.reconciliation_status = 'unmatched' THEN
      NEW.reconciliation_status := 'matched';
    END IF;
  ELSE
    NEW.reconciliation_status := 'unmatched';
    NEW.matching_status := 'none';
    NEW.matched_at := NULL;
    NEW.matched_by := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: ca_report_journal_lines("date", "date", "uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."ca_report_journal_lines"("p_date_from" "date", "p_date_to" "date", "p_account_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("journal_entry_id" "uuid", "entry_date" "date", "entry_number" "text", "source_module" "text", "reference_number" "text", "entry_description" "text", "line_account_id" "uuid", "line_number" integer, "debit" numeric, "credit" numeric, "line_description" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
SELECT
je.id            AS journal_entry_id,
je.entry_date,
je.entry_number,
je.source_module,
je.reference_number,
je.description   AS entry_description,
jel.account_id   AS line_account_id,
jel.line_number,
jel.debit,
jel.credit,
jel.description  AS line_description
FROM journal_entries je
JOIN journal_entry_lines jel ON jel.journal_entry_id = je.id
WHERE je.is_posted = true
AND (je.is_reversed = false OR je.is_reversed IS NULL)
AND je.entry_date >= p_date_from
AND je.entry_date <= p_date_to
AND (p_account_ids IS NULL OR jel.account_id = ANY(p_account_ids))
ORDER BY je.entry_date, je.entry_number, jel.line_number;
$$;


--
-- Name: calculate_balance_between_dates("uuid", "date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_balance_between_dates"("p_bank_account_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("net_change" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT
COALESCE(SUM(credit_amount), 0) - COALESCE(SUM(debit_amount), 0) AS net_change
FROM bank_statement_lines
WHERE bank_account_id = p_bank_account_id
AND transaction_date >= p_start_date
AND transaction_date < p_end_date;
END;
$$;


--
-- Name: calculate_container_landed_cost_pool("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_container_landed_cost_pool"("p_container_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_expenses numeric := 0; v_petty numeric := 0; v_other numeric := 0;
BEGIN
  SELECT COALESCE(other_import_costs,0) INTO v_other FROM import_containers WHERE id=p_container_id;
  SELECT COALESCE(SUM(CASE
    WHEN fe.expense_category='import_broker' THEN
      fe.amount-COALESCE(fe.ppn_amount,0)
      +COALESCE((SELECT SUM(
        CASE WHEN (x->>'invoice_amount_authoritative')::boolean=true THEN (x->>'amount')::numeric
             ELSE COALESCE(NULLIF((x->>'amount')::numeric,0),(x->>'dpp_amount')::numeric+COALESCE((x->>'ppn_amount')::numeric,0)) END
        -COALESCE((x->>'ppn_amount')::numeric,0)) FROM jsonb_array_elements(fe.broker_items) x),0)
      +COALESCE(fe.stamp_duty_amount,0)
    ELSE fe.amount END),0)
    INTO v_expenses
    FROM finance_expenses fe
   WHERE fe.import_container_id=p_container_id
     AND public.is_capitalizable_landed_cost_category(fe.expense_category)
     AND COALESCE(fe.include_in_landed_cost,true);
  SELECT COALESCE(SUM(amount),0) INTO v_petty FROM petty_cash_transactions
   WHERE import_container_id=p_container_id
     AND public.is_capitalizable_landed_cost_category(expense_category)
     AND COALESCE(include_in_landed_cost,true);
  RETURN v_expenses+v_petty+v_other;
END; $$;


--
-- Name: calculate_customs_broker_invoice("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_customs_broker_invoice"("p_expense_id" "uuid") RETURNS TABLE("reimbursement_total" numeric, "broker_invoice_amount" numeric, "expense_total" numeric, "recoverable_input_ppn" numeric, "pph23_withheld" numeric, "final_cash_payable" numeric, "line_totals" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE((SELECT SUM(public.broker_reimbursement_line_total(i))
      FROM jsonb_array_elements(COALESCE(fe.broker_items,'[]'::jsonb)) i),0),
    COALESCE(fe.amount,0),
    COALESCE(fe.amount,0)
      + COALESCE((SELECT SUM(public.broker_reimbursement_line_total(i))
        FROM jsonb_array_elements(COALESCE(fe.broker_items,'[]'::jsonb)) i),0)
      + COALESCE(fe.stamp_duty_amount,0),
    COALESCE(fe.ppn_amount,0) + COALESCE((SELECT SUM(COALESCE((i->>'ppn_amount')::numeric,0))
      FROM jsonb_array_elements(COALESCE(fe.broker_items,'[]'::jsonb)) i),0),
    COALESCE(fe.pph_amount,0),
    COALESCE(fe.amount,0)
      + COALESCE((SELECT SUM(public.broker_reimbursement_line_total(i))
        FROM jsonb_array_elements(COALESCE(fe.broker_items,'[]'::jsonb)) i),0)
      + COALESCE(fe.stamp_duty_amount,0)
      - COALESCE(fe.pph_amount,0),
    COALESCE((SELECT jsonb_agg(public.broker_reimbursement_line_total(i) ORDER BY ord)
      FROM jsonb_array_elements(COALESCE(fe.broker_items,'[]'::jsonb)) WITH ORDINALITY x(i,ord)),'[]'::jsonb)
  FROM finance_expenses fe
  WHERE fe.id = p_expense_id AND fe.expense_category = 'import_broker'
$$;


--
-- Name: calculate_expense_settlement_amount("text", numeric, numeric, numeric, numeric, numeric, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_expense_settlement_amount"("p_category" "text", "p_amount" numeric, "p_ppn" numeric, "p_pph" numeric, "p_stamp" numeric, "p_bank_charges" numeric, "p_broker_items" "jsonb") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE
    WHEN p_category='pib_import' THEN COALESCE(p_amount,0)
    WHEN p_category='import_broker' THEN COALESCE(p_amount,0)
      +COALESCE((SELECT sum(CASE
        WHEN item->>'amount' IS NOT NULL AND NULLIF(item->>'amount','')::numeric<>0
          THEN NULLIF(item->>'amount','')::numeric
        ELSE COALESCE(NULLIF(item->>'dpp_amount','')::numeric,0)
             +COALESCE(NULLIF(item->>'ppn_amount','')::numeric,0) END)
        FROM jsonb_array_elements(COALESCE(p_broker_items,'[]'::jsonb)) item),0)
      +COALESCE(p_stamp,0)-COALESCE(p_pph,0)
    ELSE COALESCE(p_amount,0)+COALESCE(p_ppn,0)-COALESCE(p_pph,0)+COALESCE(p_stamp,0)
      +CASE WHEN p_category='utilities' THEN COALESCE(p_bank_charges,0) ELSE 0 END
  END;
$$;


--
-- Name: calculate_finance_expense_payable("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_finance_expense_payable"("p_expense_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN fe.expense_category = 'import_broker'
      THEN COALESCE((SELECT c.final_cash_payable
                     FROM public.vw_customs_broker_accounting c
                    WHERE c.expense_id=fe.id),0)
    ELSE COALESCE(fe.amount,0)
       + COALESCE(fe.ppn_amount,0)
       - COALESCE(fe.pph_amount,0)
       + COALESCE(fe.stamp_duty_amount,0)
  END
  FROM public.finance_expenses fe
 WHERE fe.id=p_expense_id;
$$;


--
-- Name: calculate_import_cost_allocation("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_import_cost_allocation"("p_header_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_header RECORD;
v_item RECORD;
v_total_fob DECIMAL(18,2);
v_total_qty DECIMAL(18,3);
v_item_count INTEGER;
v_allocation_factor DECIMAL(10,6);
BEGIN
-- Get header details
SELECT * INTO v_header
FROM import_cost_headers
WHERE id = p_header_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Import cost header not found';
END IF;

-- Get totals for allocation base
SELECT 
SUM(total_fob_value),
SUM(quantity),
COUNT(*)
INTO v_total_fob, v_total_qty, v_item_count
FROM import_cost_items
WHERE cost_header_id = p_header_id;

-- Update each item based on allocation method
FOR v_item IN
SELECT * FROM import_cost_items WHERE cost_header_id = p_header_id
LOOP
-- Calculate allocation factor based on method
IF v_header.allocation_method = 'by_value' THEN
v_allocation_factor := v_item.total_fob_value / NULLIF(v_total_fob, 0);
ELSIF v_header.allocation_method = 'by_quantity' THEN
v_allocation_factor := v_item.quantity / NULLIF(v_total_qty, 0);
ELSIF v_header.allocation_method = 'equal' THEN
v_allocation_factor := 1.0 / NULLIF(v_item_count, 0);
ELSE
-- Manual allocation - skip auto-calculation
CONTINUE;
END IF;

-- Allocate costs proportionally
UPDATE import_cost_items
SET
allocated_duty = v_header.duty_amount * v_allocation_factor,
allocated_ppn = v_header.ppn_import_amount * v_allocation_factor,
allocated_pph = v_header.pph22_amount * v_allocation_factor,
allocated_freight = v_header.freight_amount * v_allocation_factor,
allocated_insurance = v_header.insurance_amount * v_allocation_factor,
allocated_clearing = v_header.clearing_amount * v_allocation_factor,
allocated_port = v_header.port_charges * v_allocation_factor,
allocated_other = v_header.other_charges * v_allocation_factor,
total_allocated_cost = (
v_header.duty_amount + v_header.ppn_import_amount + v_header.pph22_amount +
v_header.freight_amount + v_header.insurance_amount + v_header.clearing_amount +
v_header.port_charges + v_header.other_charges
) * v_allocation_factor,
final_landed_cost_per_unit = (
total_fob_value + 
(v_header.duty_amount + v_header.ppn_import_amount + v_header.pph22_amount +
v_header.freight_amount + v_header.insurance_amount + v_header.clearing_amount +
v_header.port_charges + v_header.other_charges) * v_allocation_factor
) / NULLIF(quantity, 0)
WHERE id = v_item.id;
END LOOP;

-- Update header status
UPDATE import_cost_headers
SET status = 'calculated'
WHERE id = p_header_id;

END;
$$;


--
-- Name: FUNCTION "calculate_import_cost_allocation"("p_header_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."calculate_import_cost_allocation"("p_header_id" "uuid") IS 'Calculates and allocates import costs to items based on selected allocation method (by_value, by_quantity, equal, manual)';


--
-- Name: calculate_rejection_financial_loss(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_rejection_financial_loss"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
NEW.financial_loss := NEW.quantity_rejected * NEW.unit_cost;
RETURN NEW;
END;
$$;


--
-- Name: calculate_rejection_financial_loss("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_rejection_financial_loss"("p_rejection_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_loss decimal;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts', 'warehouse', 'manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot calculate rejection financial loss', v_role;
END IF;

SELECT sr.quantity * b.purchase_price INTO v_loss
FROM stock_rejections sr
JOIN batches b ON b.id = sr.batch_id
WHERE sr.id = p_rejection_id;

RETURN COALESCE(v_loss, 0);
END;
$$;


--
-- Name: calculate_return_financial_impact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_return_financial_impact"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
total_impact decimal(15,2);
BEGIN
SELECT COALESCE(SUM(quantity_returned * unit_price), 0)
INTO total_impact
FROM material_return_items
WHERE return_id = NEW.id;

NEW.financial_impact := total_impact;

RETURN NEW;
END;
$$;


--
-- Name: calculate_return_financial_impact("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_return_financial_impact"("p_return_id" "uuid") RETURNS TABLE("total_value" numeric, "total_quantity" numeric, "product_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts', 'warehouse', 'manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot calculate return financial impact', v_role;
END IF;

RETURN QUERY
SELECT
SUM(mri.quantity_returned * mri.unit_price) AS total_value,
SUM(mri.quantity_returned) AS total_quantity,
COUNT(DISTINCT mri.product_id)::integer AS product_count
FROM material_return_items mri
WHERE mri.return_id = p_return_id;
END;
$$;


--
-- Name: calculate_staff_salary("uuid", "date", numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_staff_salary"("p_staff_id" "uuid", "p_salary_date" "date" DEFAULT CURRENT_DATE, "p_gross_override" numeric DEFAULT NULL::numeric, "p_pph21_override" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_staff public.finance_staff_master%rowtype;
  v_gross numeric;
  v_advance numeric;
  v_pph21 numeric;
  v_bpjs numeric:=0;
BEGIN
  PERFORM public._sec_check_finance_role();
  SELECT * INTO v_staff FROM public.finance_staff_master WHERE id=p_staff_id AND status='active';
  IF NOT FOUND THEN RAISE EXCEPTION 'Active staff member not found'; END IF;
  v_gross:=COALESCE(p_gross_override,v_staff.monthly_salary,0);
  IF v_gross<0 THEN RAISE EXCEPTION 'Gross salary cannot be negative'; END IF;
  SELECT COALESCE(sum(available_amount),0) INTO v_advance
    FROM public.get_outstanding_salary_advances(p_staff_id,COALESCE(p_salary_date,current_date));
  v_pph21:=CASE
    WHEN NOT v_staff.pph21_applicable THEN 0
    WHEN v_staff.pph21_method='percentage' THEN round(v_gross*v_staff.pph21_percentage/100,2)
    ELSE COALESCE(p_pph21_override,0) END;
  IF v_pph21<0 OR v_pph21>v_gross THEN RAISE EXCEPTION 'PPh21 must be between zero and gross salary'; END IF;
  v_advance:=least(v_advance,greatest(v_gross-v_pph21-v_bpjs,0));
  RETURN jsonb_build_object(
    'staff_id',v_staff.id,'monthly_salary',v_staff.monthly_salary,'salary_type',v_staff.salary_type,
    'gross_salary',v_gross,'outstanding_salary_advances',v_advance,
    'pph21_applicable',v_staff.pph21_applicable,'pph21_method',v_staff.pph21_method,
    'pph21_percentage',v_staff.pph21_percentage,'pph21_amount',v_pph21,
    'bpjs_amount',v_bpjs,'net_salary_payable',greatest(v_gross-v_advance-v_pph21-v_bpjs,0),
    'default_payment_method',v_staff.default_payment_method);
END;
$$;


--
-- Name: calculate_task_priority(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_task_priority"("task_deadline" timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
hours_until_deadline numeric;
BEGIN
hours_until_deadline := EXTRACT(EPOCH FROM (task_deadline - now())) / 3600;
IF hours_until_deadline < 0 THEN
RETURN 'urgent';
ELSIF hours_until_deadline < 24 THEN
RETURN 'urgent';
ELSIF hours_until_deadline < 48 THEN
RETURN 'high';
ELSIF hours_until_deadline < 168 THEN
RETURN 'medium';
ELSE
RETURN 'low';
END IF;
END;
$$;


--
-- Name: cancel_expense_posting("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cancel_expense_posting"("p_exp_id" "uuid", "p_cancelled_by" "uuid", "p_reason" "text" DEFAULT 'Posting cancelled by administrator'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_exp public.finance_expenses%ROWTYPE;
  v_je public.journal_entries%ROWTYPE;
  v_reversal_id uuid;
  v_period_status text;
  v_reversal_number text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_cancelled_by IS NULL OR p_cancelled_by <> auth.uid() THEN
    RAISE EXCEPTION 'Cancelled-by identity must match the authenticated user';
  END IF;
  IF btrim(COALESCE(p_reason, '')) = '' THEN
    RAISE EXCEPTION 'Cancellation reason is required';
  END IF;

  SELECT * INTO v_exp
  FROM public.finance_expenses
  WHERE id = p_exp_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense % not found', p_exp_id;
  END IF;
  IF v_exp.approval_status <> 'approved' THEN
    RAISE EXCEPTION 'Cannot cancel posting: expense % is not approved (current: %)',
      p_exp_id, v_exp.approval_status;
  END IF;

  SELECT * INTO v_je
  FROM public.journal_entries
  WHERE source_module IN ('expense', 'expenses')
    AND (reference_id = p_exp_id OR reference_number = 'EXP-' || p_exp_id::text)
    AND is_posted = true
    AND NOT COALESCE(is_reversed, false)
  ORDER BY created_at DESC, id DESC
  LIMIT 1
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No active journal entry found for expense %', p_exp_id;
  END IF;

  SELECT ap.status INTO v_period_status
  FROM public.accounting_periods ap
  WHERE ap.start_date <= v_je.entry_date AND ap.end_date >= v_je.entry_date
  ORDER BY ap.start_date DESC
  LIMIT 1;
  IF v_period_status IS NOT NULL AND v_period_status <> 'open' THEN
    RAISE EXCEPTION
      'Cannot cancel posting: the accounting period for % is closed. Contact your finance manager to reopen the period.',
      to_char(v_je.entry_date, 'FMMonth YYYY');
  END IF;

  IF COALESCE(v_exp.paid_amount, 0) > 0
     OR COALESCE(v_exp.pph_paid_amount, 0) > 0
     OR EXISTS (SELECT 1 FROM public.voucher_allocations va WHERE va.finance_expense_id = p_exp_id)
     OR EXISTS (SELECT 1 FROM public.bank_statement_allocations a
                WHERE (a.document_type = 'expense' AND a.document_id = p_exp_id)
                   OR a.journal_entry_id = v_je.id)
     OR EXISTS (SELECT 1 FROM public.bank_statement_lines b
                WHERE b.matched_expense_id = p_exp_id OR b.matched_entry_id = v_je.id)
     OR EXISTS (SELECT 1 FROM public.bank_reconciliation_items bri WHERE bri.journal_entry_id = v_je.id) THEN
    RAISE EXCEPTION
      'Cannot cancel posting for paid/settled expense %. Reverse or unlink its payment/bank allocation first.',
      COALESCE(v_exp.voucher_number, p_exp_id::text)
      USING ERRCODE = 'check_violation';
  END IF;

  v_reversal_number := public.generate_journal_entry_number();
  INSERT INTO public.journal_entries(
    entry_number, entry_date, period_id, source_module, reference_id,
    reference_number, description, total_debit, total_credit,
    is_posted, is_reversed, posted_by, posted_at, created_by,
    transaction_category, transaction_currency, functional_currency,
    exchange_rate, amounts_are_functional
  ) VALUES (
    v_reversal_number, v_je.entry_date, v_je.period_id, 'expense_cancellation', p_exp_id,
    'CANCEL-' || COALESCE(v_exp.voucher_number, p_exp_id::text),
    'Cancellation reversal of ' || v_je.entry_number || ': ' || p_reason,
    v_je.total_credit, v_je.total_debit,
    true, true, p_cancelled_by, now(), p_cancelled_by,
    v_je.transaction_category, v_je.transaction_currency, v_je.functional_currency,
    v_je.exchange_rate, v_je.amounts_are_functional
  ) RETURNING id INTO v_reversal_id;

  INSERT INTO public.journal_entry_lines(
    journal_entry_id, line_number, account_id, description,
    debit, credit, tax_code_id, customer_id, supplier_id, batch_id,
    transaction_currency, transaction_debit, transaction_credit,
    functional_currency, exchange_rate
  )
  SELECT v_reversal_id, l.line_number, l.account_id,
         'CANCEL: ' || COALESCE(l.description, ''),
         l.credit, l.debit, l.tax_code_id, l.customer_id, l.supplier_id, l.batch_id,
         l.transaction_currency, l.transaction_credit, l.transaction_debit,
         l.functional_currency, l.exchange_rate
  FROM public.journal_entry_lines l
  WHERE l.journal_entry_id = v_je.id
  ORDER BY l.line_number;

  IF NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_reversal_id) THEN
    RAISE EXCEPTION 'Cannot cancel empty journal entry %', v_je.id;
  END IF;

  UPDATE public.journal_entries
  SET is_reversed = true, reversed_by_id = v_reversal_id
  WHERE id = v_je.id AND NOT COALESCE(is_reversed, false);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense journal % was already reversed', v_je.id;
  END IF;

  INSERT INTO public.audit_logs(table_name, record_id, action_type, old_values, new_values, user_id)
  VALUES (
    'finance_expenses', p_exp_id, 'update',
    jsonb_build_object(
      '_action', 'CANCEL_POSTING',
      'journal_entry_id', v_je.id,
      'journal_entry_number', v_je.entry_number,
      'reversal_journal_id', v_reversal_id,
      'reversal_journal_number', v_reversal_number,
      'entry_date', v_je.entry_date,
      'amount', v_exp.amount,
      'expense_category', v_exp.expense_category,
      'approval_status', v_exp.approval_status,
      'reason', p_reason
    ),
    jsonb_build_object(
      'approval_status', 'cancelled',
      'cancelled_by', p_cancelled_by,
      'cancelled_at', now()
    ),
    p_cancelled_by
  );

  UPDATE public.finance_expenses
  SET approval_status = 'cancelled', approved_by = NULL, approved_at = NULL
  WHERE id = p_exp_id;

  IF EXISTS (
    SELECT 1 FROM public.journal_entries
    WHERE source_module IN ('expense', 'expenses')
      AND reference_id = p_exp_id AND is_posted AND NOT COALESCE(is_reversed, false)
  ) THEN
    RAISE EXCEPTION 'Expense % still has an active journal after cancellation', p_exp_id;
  END IF;
END;
$$;


--
-- Name: cancel_gl_posting("uuid", "uuid", "text", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cancel_gl_posting"("p_je_id" "uuid", "p_doc_id" "uuid", "p_table_name" "text", "p_cancelled_by" "uuid", "p_reason" "text", "p_extra_audit" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_je            journal_entries%ROWTYPE;
v_period_status TEXT;
BEGIN
IF auth.uid() IS NULL THEN
RAISE EXCEPTION 'Not authenticated';
END IF;

SELECT * INTO v_je FROM journal_entries WHERE id = p_je_id FOR UPDATE;
IF NOT FOUND THEN
RAISE EXCEPTION 'Journal entry % not found', p_je_id;
END IF;

SELECT ap.status INTO v_period_status
FROM accounting_periods ap
WHERE ap.start_date <= v_je.entry_date AND ap.end_date >= v_je.entry_date
ORDER BY ap.start_date DESC
LIMIT 1;

IF v_period_status IS NOT NULL AND v_period_status != 'open' THEN
RAISE EXCEPTION
'Cannot cancel posting: the accounting period for % is closed. Contact your finance manager to reopen the period.',
TO_CHAR(v_je.entry_date, 'FMMonth YYYY');
END IF;

DELETE FROM journal_entry_lines WHERE journal_entry_id = p_je_id;
DELETE FROM journal_entries      WHERE id              = p_je_id;

INSERT INTO audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)
VALUES (
p_table_name, p_doc_id, 'update',
p_extra_audit || jsonb_build_object(
'_action',              'CANCEL_POSTING',
'journal_entry_id',     p_je_id,
'journal_entry_number', v_je.entry_number,
'entry_date',           v_je.entry_date,
'reason',               p_reason
),
jsonb_build_object('cancelled_by', p_cancelled_by, 'cancelled_at', NOW()),
p_cancelled_by
);
END;
$$;


--
-- Name: cancel_payment_voucher_posting("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cancel_payment_voucher_posting"("p_pv_id" "uuid", "p_cancelled_by" "uuid", "p_reason" "text" DEFAULT 'Posting cancelled by administrator'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pv RECORD;
  v_je RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_pv FROM payment_vouchers WHERE id = p_pv_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_pv_id; END IF;
  IF NOT v_pv.is_posted THEN
    RAISE EXCEPTION 'Payment voucher % is not posted', COALESCE(v_pv.voucher_number, p_pv_id::TEXT);
  END IF;

  SELECT * INTO v_je FROM journal_entries WHERE id = v_pv.journal_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No journal entry found for payment voucher %', v_pv.voucher_number;
  END IF;

  -- Clear the FK reference FIRST so cancel_gl_posting can delete the JE row.
  -- (payment_vouchers.journal_entry_id has ON DELETE NO ACTION.)
  UPDATE payment_vouchers
  SET is_posted = FALSE, journal_entry_id = NULL
  WHERE id = p_pv_id;

  PERFORM cancel_gl_posting(
    v_je.id, p_pv_id, 'payment_vouchers', p_cancelled_by, p_reason,
    jsonb_build_object(
      'voucher_number', v_pv.voucher_number,
      'amount',         v_pv.amount,
      'is_posted',      TRUE
    )
  );
END;
$$;


--
-- Name: cancel_petty_cash_posting("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cancel_petty_cash_posting"("p_pct_id" "uuid", "p_cancelled_by" "uuid", "p_reason" "text" DEFAULT 'Posting cancelled by administrator'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pct record;
  v_je  record;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_pct
    FROM public.petty_cash_transactions
   WHERE id = p_pct_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Petty cash transaction % not found', p_pct_id;
  END IF;

  IF v_pct.fund_transfer_id IS NOT NULL THEN
    RAISE EXCEPTION 'Fund Transfer activity must be reversed from the Contra screen';
  END IF;

  IF v_pct.approval_status <> 'approved' THEN
    RAISE EXCEPTION
      'Cannot cancel posting: transaction % is not approved (current: %)',
      COALESCE(v_pct.transaction_number, p_pct_id::text),
      v_pct.approval_status;
  END IF;

  SELECT *
    INTO v_je
    FROM public.journal_entries
   WHERE reference_id = p_pct_id
     AND source_module = 'petty_cash'
   LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No journal entry found for %', COALESCE(v_pct.transaction_number, p_pct_id::text);
  END IF;

  PERFORM public.cancel_gl_posting(
    v_je.id,
    p_pct_id,
    'petty_cash_transactions',
    p_cancelled_by,
    p_reason,
    jsonb_build_object(
      'transaction_number', v_pct.transaction_number,
      'amount', v_pct.amount,
      'approval_status', 'approved'
    )
  );

  UPDATE public.bank_statement_lines
     SET matched_petty_cash_id = NULL,
         matched_entry_id = NULL,
         reconciliation_status = 'unmatched',
         matched_at = NULL,
         matched_by = NULL,
         notes = NULL
   WHERE matched_petty_cash_id = p_pct_id
      OR matched_entry_id = v_je.id;

  UPDATE public.petty_cash_transactions
     SET approval_status = 'pending_approval',
         approved_by = NULL,
         approved_at = NULL,
         bank_statement_line_id = NULL
   WHERE id = p_pct_id;
END;
$$;


--
-- Name: cancel_receipt_voucher_posting("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cancel_receipt_voucher_posting"("p_rv_id" "uuid", "p_cancelled_by" "uuid", "p_reason" "text" DEFAULT 'Posting cancelled by administrator'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rv RECORD;
  v_je RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_rv FROM receipt_vouchers WHERE id = p_rv_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id; END IF;
  IF NOT v_rv.is_posted THEN
    RAISE EXCEPTION 'Receipt voucher % is not posted', COALESCE(v_rv.voucher_number, p_rv_id::TEXT);
  END IF;

  SELECT * INTO v_je FROM journal_entries WHERE id = v_rv.journal_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No journal entry found for receipt voucher %', v_rv.voucher_number;
  END IF;

  -- Clear the FK reference FIRST so cancel_gl_posting can delete the JE row.
  UPDATE receipt_vouchers
  SET is_posted = FALSE, journal_entry_id = NULL
  WHERE id = p_rv_id;

  PERFORM cancel_gl_posting(
    v_je.id, p_rv_id, 'receipt_vouchers', p_cancelled_by, p_reason,
    jsonb_build_object(
      'voucher_number', v_rv.voucher_number,
      'amount',         v_rv.amount,
      'is_posted',      TRUE
    )
  );
END;
$$;


--
-- Name: check_approval_required("text", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_approval_required"("p_transaction_type" "text", "p_amount" numeric) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_threshold decimal;
BEGIN
IF auth.uid() IS NULL THEN
RAISE EXCEPTION 'Permission denied: must be authenticated';
END IF;

SELECT amount_threshold INTO v_threshold
FROM approval_thresholds
WHERE transaction_type = p_transaction_type
AND is_active = true
ORDER BY amount_threshold DESC
LIMIT 1;

IF v_threshold IS NULL THEN
RETURN false;
END IF;

RETURN p_amount >= v_threshold;
END;
$$;


--
-- Name: check_inquiry_requirements_fulfilled("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_inquiry_requirements_fulfilled"("inquiry_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
inquiry_record RECORD;
all_fulfilled boolean;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts', 'sales', 'manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot check inquiry requirements', v_role;
END IF;

SELECT * INTO inquiry_record FROM crm_inquiries WHERE id = inquiry_id;

IF NOT FOUND THEN
RETURN false;
END IF;

all_fulfilled := (
(NOT inquiry_record.price_required OR inquiry_record.price_sent_at IS NOT NULL) AND
(NOT inquiry_record.coa_required OR inquiry_record.coa_sent_at IS NOT NULL) AND
(NOT inquiry_record.sample_required OR inquiry_record.sample_sent_at IS NOT NULL) AND
(NOT inquiry_record.agency_letter_required OR inquiry_record.agency_letter_sent_at IS NOT NULL)
);

RETURN all_fulfilled;
END;
$$;


--
-- Name: bulk_email_campaigns; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."bulk_email_campaigns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "subject" "text" NOT NULL,
    "total_recipients" integer DEFAULT 0 NOT NULL,
    "sent_count" integer DEFAULT 0 NOT NULL,
    "failed_count" integer DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'in_progress'::"text" NOT NULL,
    "has_attachments" boolean DEFAULT false NOT NULL,
    "template_id" "uuid",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "created_by" "uuid" NOT NULL,
    "email_body" "text",
    "sender_name" "text",
    "attachments_context" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "processing_batch_size" integer DEFAULT 10 NOT NULL,
    "processing_delay_seconds" integer DEFAULT 30 NOT NULL,
    "next_run_at" timestamp with time zone,
    "worker_lock_until" timestamp with time zone,
    "worker_lock_id" "text",
    "worker_started_at" timestamp with time zone,
    "worker_finished_at" timestamp with time zone,
    "last_worker_error" "text",
    CONSTRAINT "bulk_email_campaigns_status_check" CHECK (("status" = ANY (ARRAY['in_progress'::"text", 'completed'::"text", 'partial'::"text", 'failed'::"text", 'paused'::"text", 'cancelled'::"text"])))
);


--
-- Name: claim_bulk_email_campaign("uuid", "text", integer, "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."claim_bulk_email_campaign"("p_campaign_id" "uuid", "p_execution_id" "text", "p_lock_seconds" integer DEFAULT 120, "p_owner_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."bulk_email_campaigns"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign public.bulk_email_campaigns;
BEGIN
  UPDATE public.bulk_email_campaigns
  SET
    worker_lock_until = now() + make_interval(secs => GREATEST(30, p_lock_seconds)),
    worker_lock_id = p_execution_id,
    worker_started_at = now(),
    last_worker_error = NULL
  WHERE id = p_campaign_id
    AND status = 'in_progress'
    AND (next_run_at IS NULL OR next_run_at <= now())
    AND (worker_lock_until IS NULL OR worker_lock_until < now())
    AND (p_owner_id IS NULL OR created_by = p_owner_id)
  RETURNING * INTO v_campaign;

  RETURN v_campaign;
END;
$$;


--
-- Name: bulk_email_recipients; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."bulk_email_recipients" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "campaign_id" "uuid" NOT NULL,
    "contact_id" "uuid",
    "company_name" "text" DEFAULT ''::"text" NOT NULL,
    "email" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "error_message" "text",
    "sent_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "send_order" integer,
    "attempt_number" integer DEFAULT 0 NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "http_status" integer,
    "edge_execution_id" "text",
    "provider_response" "jsonb",
    "error_code" "text",
    CONSTRAINT "bulk_email_recipients_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'sending'::"text", 'sent'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


--
-- Name: claim_bulk_email_recipients("uuid", integer, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."claim_bulk_email_recipients"("p_campaign_id" "uuid", "p_limit" integer, "p_execution_id" "text") RETURNS SETOF "public"."bulk_email_recipients"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
WITH stale AS (
UPDATE public.bulk_email_recipients
SET
status        = 'pending',
error_code    = 'STALE_SENDING_REQUEUED',
error_message = 'Recipient was stuck in sending state and was requeued.',
completed_at  = now()
WHERE campaign_id = p_campaign_id
AND status = 'sending'
AND started_at < now() - interval '5 minutes'
AND sent_at IS NULL
RETURNING id
),
picked AS (
SELECT r.id
FROM public.bulk_email_recipients r
WHERE r.campaign_id = p_campaign_id
AND r.status = 'pending'
ORDER BY r.send_order NULLS LAST, r.created_at, r.id
LIMIT GREATEST(1, p_limit)
FOR UPDATE SKIP LOCKED
)
UPDATE public.bulk_email_recipients r
SET
status         = 'sending',
attempt_number = r.attempt_number + 1,
started_at     = now(),
completed_at   = NULL,
http_status    = NULL,
edge_execution_id = p_execution_id,
provider_response = NULL,
error_code     = NULL,
error_message  = NULL
FROM picked
WHERE r.id = picked.id
RETURNING r.*;
END;
$$;


--
-- Name: clear_receipt_allocation_rounding_adjustment("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."clear_receipt_allocation_rounding_adjustment"("p_invoice_id" "uuid", "p_receipt_voucher_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing record;
BEGIN
  FOR v_existing IN
    SELECT *
    FROM public.invoice_rounding_adjustments
    WHERE sales_invoice_id = p_invoice_id
       OR (p_receipt_voucher_id IS NOT NULL AND receipt_voucher_id = p_receipt_voucher_id)
  LOOP
    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;

    DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
  END LOOP;

  PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);
END;
$$;


--
-- Name: close_tax_period("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."close_tax_period"("p_period_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_period                  tax_periods%ROWTYPE;
  v_missing_faktur          int;
  v_draft_sales             int;
  v_draft_purchase          int;
  v_unposted_je             int;
  v_unreconciled_payments   int;
  v_outstanding             numeric(18,2);
BEGIN
  IF NOT EXISTS (SELECT 1 FROM user_profiles
                 WHERE id = auth.uid() AND role IN ('admin','manager') AND is_active = true) THEN
    RAISE EXCEPTION 'Only admins/managers may close a tax period';
  END IF;

  SELECT * INTO v_period FROM tax_periods WHERE id = p_period_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tax period % not found', p_period_id;
  END IF;
  IF v_period.status = 'closed' THEN
    RAISE EXCEPTION 'Tax period already closed';
  END IF;

  -- Recompute snapshot before validating
  PERFORM compute_period_ppn(p_period_id);
  SELECT * INTO v_period FROM tax_periods WHERE id = p_period_id;

  -- 1. Missing Faktur Pajak (PPN only)
  IF v_period.tax_type = 'PPN' THEN
    SELECT COUNT(*) INTO v_missing_faktur
      FROM sales_invoices
     WHERE tax_period_id = p_period_id
       AND tax_amount > 0
       AND (faktur_pajak_number IS NULL OR faktur_pajak_number = '');
    IF v_missing_faktur > 0 THEN
      RAISE EXCEPTION 'Cannot close period: % sales invoice(s) missing Faktur Pajak number', v_missing_faktur;
    END IF;
  END IF;

  -- 2. No draft sales invoices attributed to this period
  BEGIN
    SELECT COUNT(*) INTO v_draft_sales
      FROM sales_invoices
     WHERE tax_period_id = p_period_id
       AND status = 'draft';
    IF v_draft_sales > 0 THEN
      RAISE EXCEPTION 'Cannot close period: % draft sales invoice(s) remain', v_draft_sales;
    END IF;
  EXCEPTION WHEN undefined_column THEN
    NULL;  -- sales_invoices.status may not be present in every branch
  END;

  -- 3. No draft purchase invoices attributed to this period
  BEGIN
    SELECT COUNT(*) INTO v_draft_purchase
      FROM purchase_invoices
     WHERE tax_period_id = p_period_id
       AND status = 'draft';
    IF v_draft_purchase > 0 THEN
      RAISE EXCEPTION 'Cannot close period: % draft purchase invoice(s) remain', v_draft_purchase;
    END IF;
  EXCEPTION WHEN undefined_column THEN
    NULL;
  END;

  -- 4. No unposted journal_entries referencing this period's source docs
  --    (any tax_payment JE where is_posted = false is a blocker)
  SELECT COUNT(*) INTO v_unposted_je
    FROM journal_entries je
    JOIN tax_payments txp ON txp.id = je.reference_id
   WHERE je.source_module = 'tax_payment'
     AND txp.tax_period_id = p_period_id
     AND je.is_posted = false;
  IF v_unposted_je > 0 THEN
    RAISE EXCEPTION 'Cannot close period: % unposted journal entries for tax payments', v_unposted_je;
  END IF;

  -- 5. No unreconciled tax_payments (must all be in status='reconciled')
  SELECT COUNT(*) INTO v_unreconciled_payments
    FROM tax_payments
   WHERE tax_period_id = p_period_id
     AND status IN ('draft','posted');
  IF v_unreconciled_payments > 0 THEN
    RAISE EXCEPTION 'Cannot close period: % unreconciled tax payment(s) remain (status draft or posted)', v_unreconciled_payments;
  END IF;

  -- 6. Zero outstanding payable
  SELECT outstanding_amount INTO v_outstanding
    FROM vw_outstanding_tax
   WHERE tax_period_id = p_period_id;
  IF COALESCE(v_outstanding, 0) > 0 THEN
    RAISE EXCEPTION 'Cannot close period: Rp % still outstanding. Record additional tax payments first.', v_outstanding;
  END IF;

  -- Flip status
  UPDATE tax_periods SET
    status    = 'closed',
    closed_at = now(),
    closed_by = auth.uid(),
    updated_at = now()
  WHERE id = p_period_id;

  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)
  VALUES (auth.uid(), 'tax_periods', 'update', p_period_id,
          jsonb_build_object(
            'action', 'close',
            'status', 'closed',
            'input_ppn_total',  v_period.input_ppn_total,
            'output_ppn_total', v_period.output_ppn_total,
            'net_ppn',          v_period.net_ppn,
            'pph_total',        v_period.pph_total
          ));
END $$;


--
-- Name: complete_import_cost_posting("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."complete_import_cost_posting"("p_header_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_je_id UUID;
v_result JSONB;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot post import costs', v_role;
END IF;

PERFORM calculate_import_cost_allocation(p_header_id);
PERFORM apply_import_costs_to_batches(p_header_id);
v_je_id := post_import_cost_journal(p_header_id);

UPDATE import_cost_headers
SET
status = 'posted',
journal_entry_id = v_je_id,
posted_by = auth.uid(),
posted_at = NOW()
WHERE id = p_header_id;

v_result := jsonb_build_object(
'success', true,
'message', 'Import costs calculated, allocated, and posted successfully',
'journal_entry_id', v_je_id,
'header_id', p_header_id
);

RETURN v_result;
END;
$$;


--
-- Name: FUNCTION "complete_import_cost_posting"("p_header_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."complete_import_cost_posting"("p_header_id" "uuid") IS 'Complete import cost posting workflow: calculates allocation, updates batches, posts accounting. Call this to finalize import costs.';


--
-- Name: compute_period_ppn("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."compute_period_ppn"("p_period_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_period public.tax_periods%rowtype; v_pph_total numeric(18,2);
BEGIN
  PERFORM public.compute_period_ppn_pre_posted_register(p_period_id);
  SELECT * INTO v_period FROM public.tax_periods WHERE id=p_period_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tax period % not found',p_period_id; END IF;
  IF v_period.tax_type='PPN' THEN RETURN; END IF;
  SELECT COALESCE((SELECT sum(fe.pph_amount) FROM public.finance_expenses fe LEFT JOIN public.tax_codes tc ON tc.id=fe.pph_code_id
    WHERE (fe.pph_tax_period_id=v_period.id OR (fe.pph_tax_period_id IS NULL AND extract(year from public.get_expense_pph_period_date(fe.id))::int=v_period.fiscal_year AND extract(month from public.get_expense_pph_period_date(fe.id))::int=v_period.period_month))
      AND fe.approval_status='approved' AND fe.pph_amount>0 AND coalesce(fe.expense_category,'') NOT IN ('pib_import','pph_import') AND (v_period.tax_type='PPh_Unifikasi' OR tc.tax_type=v_period.tax_type)),0)
    + COALESCE((SELECT sum(pv.pph_amount) FROM public.payment_vouchers pv LEFT JOIN public.tax_codes tc ON tc.id=pv.pph_code_id
    WHERE (pv.tax_period_id=v_period.id OR (pv.tax_period_id IS NULL AND extract(year from pv.voucher_date)::int=v_period.fiscal_year AND extract(month from pv.voucher_date)::int=v_period.period_month))
      AND coalesce(pv.is_posted,false) AND pv.pph_amount>0 AND (v_period.tax_type='PPh_Unifikasi' OR tc.tax_type=v_period.tax_type)),0)
    + CASE WHEN v_period.tax_type IN ('PPh22','PPh_Unifikasi') THEN COALESCE((SELECT sum(case when fe.expense_category='pib_import' then fe.pib_pph_amount else fe.amount end) FROM public.finance_expenses fe
    WHERE fe.expense_category IN ('pib_import','pph_import') AND (fe.pph_tax_period_id=v_period.id OR (fe.pph_tax_period_id IS NULL AND extract(year from public.get_expense_pph_period_date(fe.id))::int=v_period.fiscal_year AND extract(month from public.get_expense_pph_period_date(fe.id))::int=v_period.period_month)) AND fe.approval_status='approved'),0) ELSE 0 END
    + COALESCE((SELECT sum(tp.amount) FROM public.tax_payments tp
    WHERE tp.tax_period_id=v_period.id AND tp.tax_type=v_period.tax_type AND tp.historical_source_status='missing_source_verified'),0)
  INTO v_pph_total;
  UPDATE public.tax_periods SET pph_total=v_pph_total,updated_at=now() WHERE id=p_period_id;
END $$;


--
-- Name: compute_period_ppn_pre_posted_register("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."compute_period_ppn_pre_posted_register"("p_period_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_period       tax_periods%ROWTYPE;
  v_input        numeric(18,2);
  v_output_gross numeric(18,2);
  v_output_cn    numeric(18,2);
  v_output       numeric(18,2);
  v_prior_cf     numeric(18,2);
  v_pph_total    numeric(18,2);
BEGIN
  SELECT * INTO v_period FROM tax_periods WHERE id = p_period_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tax period % not found', p_period_id;
  END IF;

  IF v_period.tax_type = 'PPN' THEN
    -- INPUT PPN (unchanged): purchase_invoices + finance_expenses
    -- (regular ppn_amount excluding broker rows) + broker_items[i].ppn_amount
    -- + pib_ppn_amount.
    SELECT
      COALESCE((
        SELECT SUM(tax_amount) FROM purchase_invoices
         WHERE tax_period_id = p_period_id AND tax_amount > 0
      ), 0)
      +
      COALESCE((
        SELECT SUM(fe.ppn_amount)
          FROM finance_expenses fe
         WHERE fe.tax_period_id = p_period_id
           AND fe.ppn_amount > 0
           AND NOT EXISTS (
             SELECT 1
               FROM jsonb_array_elements(COALESCE(fe.broker_items, '[]'::jsonb)) item
              WHERE COALESCE((item->>'ppn_amount')::numeric, 0) > 0
           )
      ), 0)
      +
      COALESCE((
        SELECT SUM(COALESCE((item->>'ppn_amount')::numeric, 0))
          FROM finance_expenses fe
          CROSS JOIN LATERAL jsonb_array_elements(COALESCE(fe.broker_items, '[]'::jsonb)) item
         WHERE fe.tax_period_id = p_period_id
           AND COALESCE((item->>'ppn_amount')::numeric, 0) > 0
      ), 0)
      +
      COALESCE((
        SELECT SUM(pib_ppn_amount) FROM finance_expenses
         WHERE tax_period_id = p_period_id AND pib_ppn_amount > 0
      ), 0)
    INTO v_input;

    -- OUTPUT PPN = gross sales_invoices.tax_amount − approved credit notes.
    SELECT COALESCE(SUM(tax_amount), 0) INTO v_output_gross
      FROM sales_invoices
     WHERE tax_period_id = p_period_id AND tax_amount > 0;

    SELECT COALESCE(SUM(tax_amount), 0) INTO v_output_cn
      FROM credit_notes
     WHERE tax_period_id = p_period_id
       AND status = 'approved'
       AND tax_amount > 0;

    v_output := GREATEST(v_output_gross - v_output_cn, 0);

    SELECT COALESCE(carry_forward_out, 0) INTO v_prior_cf
      FROM tax_periods
     WHERE tax_type = 'PPN'
       AND (fiscal_year, period_month) < (v_period.fiscal_year, v_period.period_month)
     ORDER BY fiscal_year DESC, period_month DESC
     LIMIT 1;
    v_prior_cf := COALESCE(v_prior_cf, 0);

    UPDATE tax_periods SET
      input_ppn_total   = v_input,
      output_ppn_total  = v_output,
      carry_forward_in  = v_prior_cf,
      net_ppn           = GREATEST(v_output - v_input - v_prior_cf, 0),
      carry_forward_out = GREATEST(v_input + v_prior_cf - v_output, 0),
      updated_at        = now()
    WHERE id = p_period_id;

  ELSE
    -- PPh period. Three additive sources, all attributed by document date:
    --   (a) finance_expenses.pph_amount  — regular withholding on NON-import
    --       expenses (matched to the period's PPh type via tax_codes).
    --   (b) payment_vouchers.pph_amount  — withholding on vouchers.
    --   (c) IMPORT PPh 22 — pib_import.pib_pph_amount + pph_import.amount.
    --       Always PPh22, so only counted for PPh22 / PPh_Unifikasi periods.
    SELECT
      COALESCE((
        SELECT SUM(fe.pph_amount)
          FROM finance_expenses fe
          LEFT JOIN tax_codes tc ON tc.id = fe.pph_code_id
         WHERE EXTRACT(YEAR  FROM fe.expense_date)::int = v_period.fiscal_year
           AND EXTRACT(MONTH FROM fe.expense_date)::int = v_period.period_month
           AND fe.pph_amount > 0
           AND COALESCE(fe.expense_category, '') NOT IN ('pib_import', 'pph_import')
           AND (v_period.tax_type = 'PPh_Unifikasi' OR tc.tax_type = v_period.tax_type)
      ), 0)
      +
      COALESCE((
        SELECT SUM(pv.pph_amount)
          FROM payment_vouchers pv
          LEFT JOIN tax_codes tc ON tc.id = pv.pph_code_id
         WHERE EXTRACT(YEAR  FROM pv.voucher_date)::int = v_period.fiscal_year
           AND EXTRACT(MONTH FROM pv.voucher_date)::int = v_period.period_month
           AND pv.pph_amount > 0
           AND (v_period.tax_type = 'PPh_Unifikasi' OR tc.tax_type = v_period.tax_type)
      ), 0)
      +
      CASE WHEN v_period.tax_type IN ('PPh22', 'PPh_Unifikasi') THEN
        -- (c1) PIB single-document import: PPh 22 portion in pib_pph_amount
        COALESCE((
          SELECT SUM(fe.pib_pph_amount)
            FROM finance_expenses fe
           WHERE fe.expense_category = 'pib_import'
             AND EXTRACT(YEAR  FROM fe.expense_date)::int = v_period.fiscal_year
             AND EXTRACT(MONTH FROM fe.expense_date)::int = v_period.period_month
             AND COALESCE(fe.pib_pph_amount, 0) > 0
        ), 0)
        +
        -- (c2) Standalone import PPh 22 expense: whole amount is the tax
        COALESCE((
          SELECT SUM(fe.amount)
            FROM finance_expenses fe
           WHERE fe.expense_category = 'pph_import'
             AND EXTRACT(YEAR  FROM fe.expense_date)::int = v_period.fiscal_year
             AND EXTRACT(MONTH FROM fe.expense_date)::int = v_period.period_month
             AND COALESCE(fe.amount, 0) > 0
        ), 0)
      ELSE 0 END
    INTO v_pph_total;

    UPDATE tax_periods SET
      pph_total  = v_pph_total,
      updated_at = now()
    WHERE id = p_period_id;
  END IF;
END $$;


--
-- Name: compute_tax_due_dates("text", integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."compute_tax_due_dates"("p_tax_type" "text", "p_fiscal_year" integer, "p_period_month" integer) RETURNS TABLE("period_start" "date", "period_end" "date", "payment_due_date" "date", "filing_due_date" "date")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_start                 date;
  v_end                   date;
  v_cfg                   tax_calendar_config%ROWTYPE;
  v_offset_month_start    date;
BEGIN
  v_start := make_date(p_fiscal_year, p_period_month, 1);
  v_end   := (v_start + interval '1 month - 1 day')::date;

  SELECT * INTO v_cfg
  FROM tax_calendar_config
  WHERE tax_type = p_tax_type AND is_active = true;

  IF NOT FOUND THEN
    RETURN QUERY SELECT v_start, v_end, NULL::date, NULL::date;
    RETURN;
  END IF;

  v_offset_month_start := (v_start + (v_cfg.due_relative_month_offset || ' months')::interval)::date;

  RETURN QUERY SELECT
    v_start,
    v_end,
    CASE
      WHEN v_cfg.end_of_month_payment THEN
        ((v_offset_month_start + interval '1 month - 1 day')::date)
      WHEN v_cfg.payment_due_day IS NOT NULL THEN
        make_date(
          EXTRACT(YEAR  FROM v_offset_month_start)::int,
          EXTRACT(MONTH FROM v_offset_month_start)::int,
          LEAST(v_cfg.payment_due_day,
                EXTRACT(DAY FROM (v_offset_month_start + interval '1 month - 1 day'))::int)
        )
      ELSE NULL
    END,
    CASE
      WHEN v_cfg.filing_due_day IS NOT NULL THEN
        make_date(
          EXTRACT(YEAR  FROM v_offset_month_start)::int,
          EXTRACT(MONTH FROM v_offset_month_start)::int,
          LEAST(v_cfg.filing_due_day,
                EXTRACT(DAY FROM (v_offset_month_start + interval '1 month - 1 day'))::int)
        )
      WHEN v_cfg.end_of_month_payment THEN
        ((v_offset_month_start + interval '1 month - 1 day')::date)
      ELSE NULL
    END;
END $$;


--
-- Name: confirm_bank_match("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."confirm_bank_match"("p_bank_line_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_line              RECORD;
v_already_confirmed BOOLEAN;
v_role              text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot confirm bank matches', v_role;
END IF;

SELECT * INTO v_line FROM bank_statement_lines WHERE id = p_bank_line_id;
IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Bank line not found'); END IF;
IF v_line.matching_status = 'confirmed' THEN
RETURN jsonb_build_object('success', false, 'error', 'Match already confirmed');
END IF;

IF v_line.matched_expense_id IS NOT NULL THEN
SELECT EXISTS (
SELECT 1 FROM bank_statement_lines
WHERE matched_expense_id = v_line.matched_expense_id
AND matching_status = 'confirmed' AND id != p_bank_line_id
) INTO v_already_confirmed;
IF v_already_confirmed THEN
RETURN jsonb_build_object('success', false, 'error', 'This expense is already confirmed with another bank transaction');
END IF;
END IF;

IF v_line.matched_receipt_id IS NOT NULL THEN
SELECT EXISTS (
SELECT 1 FROM bank_statement_lines
WHERE matched_receipt_id = v_line.matched_receipt_id
AND matching_status = 'confirmed' AND id != p_bank_line_id
) INTO v_already_confirmed;
IF v_already_confirmed THEN
RETURN jsonb_build_object('success', false, 'error', 'This receipt is already confirmed with another bank transaction');
END IF;
END IF;

UPDATE bank_statement_lines
SET matching_status = 'confirmed', reconciliation_status = 'matched',
matched_at = now(), matched_by = p_user_id, notes = 'User confirmed match'
WHERE id = p_bank_line_id;

RETURN jsonb_build_object('success', true, 'message', 'Match confirmed successfully');
END;
$$;


--
-- Name: consume_so_product_reservation_v2("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."consume_so_product_reservation_v2"("p_dc_item_id" "uuid", "p_operation_id" "uuid", "p_actor" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v record; v_res public.so_product_reservations%ROWTYPE; v_tx uuid; v_after numeric;
BEGIN
  SELECT dci.*,dc.id dc_id,dc.sales_order_id,dc.challan_number,dc.challan_date INTO v
  FROM public.delivery_challan_items dci JOIN public.delivery_challans dc ON dc.id=dci.challan_id
  WHERE dci.id=p_dc_item_id FOR UPDATE OF dci,dc;
  IF NOT FOUND OR v.sales_order_item_id IS NULL THEN RAISE EXCEPTION 'DC item has no canonical SO item'; END IF;
  SELECT * INTO v_res FROM public.so_product_reservations
  WHERE sales_order_item_id=v.sales_order_item_id AND product_id=v.product_id AND status='active' FOR UPDATE;
  IF NOT FOUND OR v_res.reserved_quantity<v.quantity THEN RAISE EXCEPTION 'DC quantity exceeds remaining SO product reservation'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.batches b WHERE b.id=v.batch_id AND b.product_id=v.product_id
      AND b.is_active AND b.current_stock>=v.quantity AND (b.expiry_date IS NULL OR b.expiry_date>CURRENT_DATE)) THEN
    RAISE EXCEPTION 'Selected batch is invalid, expired, or has insufficient physical stock';
  END IF;
  IF EXISTS(SELECT 1 FROM public.dc_batch_allocations WHERE delivery_challan_item_id=v.id AND status='consumed') THEN
    RAISE EXCEPTION 'Delivery Challan item reservation is already consumed';
  END IF;
  v_tx:=public.post_inventory_movement(public.uuid_from_text('inventory-v2:dc:'||p_operation_id||':'||v.id),v.product_id,v.batch_id,
    'delivery_challan',-v.quantity,v.challan_date,v.challan_number,'delivery_challan',v.dc_id,
    'Product reservation consumed against DC batch',COALESCE(p_actor,auth.uid()),NULL,NULL);
  v_after:=v_res.reserved_quantity-v.quantity;
  UPDATE public.so_product_reservations SET reserved_quantity=v_after,
    status=CASE WHEN v_after=0 THEN 'consumed' ELSE 'active' END,closed_at=CASE WHEN v_after=0 THEN now() END,
    close_reason=CASE WHEN v_after=0 THEN 'Fully delivered' END,updated_at=now() WHERE id=v_res.id;
  INSERT INTO public.so_product_reservation_events(reservation_id,sales_order_id,sales_order_item_id,event_type,quantity_delta,quantity_after,delivery_challan_item_id,reason,actor_id)
  VALUES(v_res.id,v.sales_order_id,v.sales_order_item_id,'consumed',-v.quantity,v_after,v.id,'DC approval',COALESCE(p_actor,auth.uid()));
  INSERT INTO public.dc_batch_allocations(delivery_challan_id,delivery_challan_item_id,sales_order_item_id,reservation_id,product_id,batch_id,allocated_quantity,operation_id,inventory_transaction_id,created_by)
  VALUES(v.dc_id,v.id,v.sales_order_item_id,v_res.id,v.product_id,v.batch_id,v.quantity,p_operation_id,v_tx,COALESCE(p_actor,auth.uid()));
  RETURN v_tx;
END; $$;


--
-- Name: correct_customs_broker_reimbursement_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."correct_customs_broker_reimbursement_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_je uuid;
  v_expense_account uuid;
  v_ap_account uuid;
  v_cash_account uuid;
  v_item jsonb;
  v_supplier uuid;
  v_amount numeric;
  v_old_base numeric;
  v_delta numeric;
  v_balance numeric;
  v_debit numeric;
  v_credit numeric;
  v_line_no int;
  v_outstanding boolean := NEW.payment_method IS NULL OR NEW.payment_method = 'outstanding';
BEGIN
  IF NEW.expense_category <> 'import_broker' THEN RETURN NEW; END IF;

  SELECT id INTO v_je FROM journal_entries WHERE reference_number = 'EXP-' || NEW.id::text LIMIT 1;
  IF v_je IS NULL THEN RETURN NEW; END IF;
  -- The legacy expense trigger can leave its generic PPh narration behind;
  -- broker posting owns the PPh23 line and must not duplicate withholding.
  DELETE FROM journal_entry_lines
   WHERE journal_entry_id = v_je
     AND description LIKE 'PPh Ditahan - %';
  SELECT id INTO v_expense_account FROM chart_of_accounts WHERE code = '5300' LIMIT 1;
  SELECT id INTO v_ap_account FROM chart_of_accounts WHERE code = '2110' LIMIT 1;
  IF NEW.payment_method = 'cash' THEN
    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
  ELSIF NEW.payment_method = 'petty_cash' THEN
    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1102' LIMIT 1;
  ELSIF NEW.payment_method = 'bank_transfer' AND NEW.bank_account_id IS NOT NULL THEN
    SELECT coa_id INTO v_cash_account FROM bank_accounts WHERE id = NEW.bank_account_id;
  ELSE
    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items, '[]'::jsonb)) LOOP
    v_supplier := NULLIF(v_item->>'supplier_id', '')::uuid;
    v_old_base := CASE WHEN v_item->>'ppn_treatment' = 'included'
      THEN GREATEST(COALESCE((v_item->>'amount')::numeric,0) - COALESCE((v_item->>'ppn_amount')::numeric,0),0)
      ELSE COALESCE((v_item->>'amount')::numeric,0) END;
    v_delta := public.broker_reimbursement_expense_base(v_item) - v_old_base;
    IF v_delta = 0 THEN CONTINUE; END IF;

    SELECT COALESCE(max(line_number),0) + 1 INTO v_line_no
      FROM journal_entry_lines WHERE journal_entry_id = v_je;
    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
    VALUES(v_je,v_line_no,v_expense_account,'Reimbursement correction - DPP/PPN line total',v_delta,0,COALESCE(v_supplier,NEW.supplier_id));

    IF v_outstanding THEN
      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
      VALUES(v_je,v_line_no+1,v_ap_account,'A/P correction - reimbursement line total',0,v_delta,COALESCE(v_supplier,NEW.supplier_id));
    ELSE
      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
      VALUES(v_je,v_line_no+1,v_cash_account,'Cash correction - reimbursement line total',0,v_delta,NEW.supplier_id);
    END IF;
    UPDATE journal_entries
       SET total_debit = total_debit + v_delta,
           total_credit = total_credit + v_delta
     WHERE id = v_je;
  END LOOP;
  SELECT COALESCE(SUM(debit),0), COALESCE(SUM(credit),0)
    INTO v_debit, v_credit
    FROM journal_entry_lines WHERE journal_entry_id = v_je;
  v_balance := v_debit - v_credit;
  IF v_balance <> 0 THEN
    SELECT COALESCE(max(line_number),0) + 1 INTO v_line_no
      FROM journal_entry_lines WHERE journal_entry_id = v_je;
    IF v_balance > 0 THEN
      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
      VALUES(v_je,v_line_no, v_cash_account, 'Cash balancing - broker reimbursement total',0,v_balance,NEW.supplier_id);
    ELSE
      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
      VALUES(v_je,v_line_no, v_expense_account, 'Expense balancing - broker reimbursement total',-v_balance,0,NEW.supplier_id);
    END IF;
  END IF;
  UPDATE journal_entries je
     SET total_debit = totals.debit,
         total_credit = totals.credit
    FROM (
      SELECT COALESCE(SUM(debit),0) AS debit, COALESCE(SUM(credit),0) AS credit
        FROM journal_entry_lines WHERE journal_entry_id = v_je
    ) totals
   WHERE je.id = v_je;
  RETURN NEW;
END;
$$;


--
-- Name: create_batch_inventory_transaction("uuid", "uuid", "text", numeric, "date", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_batch_inventory_transaction"("p_product_id" "uuid", "p_batch_id" "uuid", "p_transaction_type" "text", "p_quantity" numeric, "p_transaction_date" "date", "p_notes" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts','warehouse') THEN
RAISE EXCEPTION 'Permission denied: role % cannot create inventory transactions', v_role;
END IF;

INSERT INTO inventory_transactions (
product_id, batch_id, transaction_type, quantity, transaction_date, notes
) VALUES (
p_product_id, p_batch_id, p_transaction_type, p_quantity, p_transaction_date, p_notes
);
END;
$$;


--
-- Name: fund_transfers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."fund_transfers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "transfer_number" "text" NOT NULL,
    "transfer_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "amount" numeric(15,2) NOT NULL,
    "from_account_type" "text" NOT NULL,
    "to_account_type" "text" NOT NULL,
    "from_bank_account_id" "uuid",
    "to_bank_account_id" "uuid",
    "description" "text",
    "journal_entry_id" "uuid",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" DEFAULT 'pending'::"text",
    "posted_at" timestamp with time zone,
    "posted_by" "uuid",
    "from_bank_statement_line_id" "uuid",
    "to_bank_statement_line_id" "uuid",
    "from_amount" numeric(15,2) NOT NULL,
    "to_amount" numeric(15,2) NOT NULL,
    "exchange_rate" numeric(15,6),
    "reversed_at" timestamp with time zone,
    "reversed_by" "uuid",
    CONSTRAINT "fund_transfers_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "fund_transfers_exchange_rate_check" CHECK ((("exchange_rate" IS NULL) OR ("exchange_rate" > (0)::numeric))),
    CONSTRAINT "fund_transfers_from_account_type_check" CHECK (("from_account_type" = ANY (ARRAY['petty_cash'::"text", 'cash_on_hand'::"text", 'bank'::"text"]))),
    CONSTRAINT "fund_transfers_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'posted'::"text", 'cancelled'::"text", 'reversed'::"text"]))),
    CONSTRAINT "fund_transfers_to_account_type_check" CHECK (("to_account_type" = ANY (ARRAY['petty_cash'::"text", 'cash_on_hand'::"text", 'bank'::"text"]))),
    CONSTRAINT "no_same_account_transfer" CHECK ((NOT (("from_account_type" = "to_account_type") AND (COALESCE("from_bank_account_id", '00000000-0000-0000-0000-000000000000'::"uuid") = COALESCE("to_bank_account_id", '00000000-0000-0000-0000-000000000000'::"uuid")))))
);


--
-- Name: TABLE "fund_transfers"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE "public"."fund_transfers" IS 'Records transfers between petty cash, cash on hand, and bank accounts. Does NOT auto-post journals - use post_fund_transfer_journal() function after verification.';


--
-- Name: COLUMN "fund_transfers"."from_bank_statement_line_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."fund_transfers"."from_bank_statement_line_id" IS 'Links to bank statement showing money OUT';


--
-- Name: COLUMN "fund_transfers"."to_bank_statement_line_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."fund_transfers"."to_bank_statement_line_id" IS 'Links to bank statement showing money IN';


--
-- Name: COLUMN "fund_transfers"."from_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."fund_transfers"."from_amount" IS 'Amount debited from source account (in source currency)';


--
-- Name: COLUMN "fund_transfers"."to_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."fund_transfers"."to_amount" IS 'Amount credited to destination account (in destination currency)';


--
-- Name: COLUMN "fund_transfers"."exchange_rate"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."fund_transfers"."exchange_rate" IS 'Exchange rate used for conversion (to_amount / from_amount)';


--
-- Name: create_fund_transfer_with_posting("date", numeric, numeric, "text", "text", "text", "uuid", "uuid", "uuid", "uuid", numeric, "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_fund_transfer_with_posting"("p_transfer_date" "date", "p_from_amount" numeric, "p_to_amount" numeric, "p_from_account_type" "text", "p_to_account_type" "text", "p_description" "text" DEFAULT NULL::"text", "p_from_bank_account_id" "uuid" DEFAULT NULL::"uuid", "p_to_bank_account_id" "uuid" DEFAULT NULL::"uuid", "p_from_bank_statement_line_id" "uuid" DEFAULT NULL::"uuid", "p_to_bank_statement_line_id" "uuid" DEFAULT NULL::"uuid", "p_exchange_rate" numeric DEFAULT NULL::numeric, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."fund_transfers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_transfer_number text;
  v_transfer public.fund_transfers;
BEGIN
  v_user_id := COALESCE(p_created_by, auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_transfer_number := public.generate_fund_transfer_number();

  INSERT INTO public.fund_transfers (
    transfer_number,
    transfer_date,
    amount,
    from_amount,
    to_amount,
    exchange_rate,
    from_account_type,
    to_account_type,
    from_bank_account_id,
    to_bank_account_id,
    from_bank_statement_line_id,
    to_bank_statement_line_id,
    description,
    created_by
  ) VALUES (
    v_transfer_number,
    p_transfer_date,
    p_from_amount,
    p_from_amount,
    p_to_amount,
    p_exchange_rate,
    p_from_account_type,
    p_to_account_type,
    CASE WHEN p_from_account_type = 'bank' THEN p_from_bank_account_id ELSE NULL END,
    CASE WHEN p_to_account_type = 'bank' THEN p_to_bank_account_id ELSE NULL END,
    p_from_bank_statement_line_id,
    p_to_bank_statement_line_id,
    NULLIF(p_description, ''),
    v_user_id
  )
  RETURNING * INTO v_transfer;

  RETURN v_transfer;
END;
$$;


--
-- Name: FUNCTION "create_fund_transfer_with_posting"("p_transfer_date" "date", "p_from_amount" numeric, "p_to_amount" numeric, "p_from_account_type" "text", "p_to_account_type" "text", "p_description" "text", "p_from_bank_account_id" "uuid", "p_to_bank_account_id" "uuid", "p_from_bank_statement_line_id" "uuid", "p_to_bank_statement_line_id" "uuid", "p_exchange_rate" numeric, "p_created_by" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."create_fund_transfer_with_posting"("p_transfer_date" "date", "p_from_amount" numeric, "p_to_amount" numeric, "p_from_account_type" "text", "p_to_account_type" "text", "p_description" "text", "p_from_bank_account_id" "uuid", "p_to_bank_account_id" "uuid", "p_from_bank_statement_line_id" "uuid", "p_to_bank_statement_line_id" "uuid", "p_exchange_rate" numeric, "p_created_by" "uuid") IS 'Creates fund_transfers and petty cash withdrawal (for to_account_type=petty_cash) in one transaction. Idempotent petty cash insertion uses the partial unique index on petty_cash_transactions(fund_transfer_id) where fund_transfer_id is not null.';


--
-- Name: create_purchase_invoice_from_po("uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_purchase_invoice_from_po"("p_purchase_order_id" "uuid", "p_invoice_data" "jsonb", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_po public.purchase_orders%ROWTYPE;
  v_result jsonb;
  v_invoice_id uuid;
  v_item jsonb;
  v_po_item public.purchase_order_items%ROWTYPE;
  v_ordinal integer := 0;
  v_invoice_item_id uuid;
BEGIN
  SELECT * INTO v_po
    FROM public.purchase_orders
   WHERE id = p_purchase_order_id
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Purchase Order not found';
  END IF;

  IF NULLIF(p_invoice_data->>'supplier_id', '')::uuid IS DISTINCT FROM v_po.supplier_id THEN
    RAISE EXCEPTION 'Purchase Invoice supplier must match the Purchase Order supplier';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))
  LOOP
    IF NULLIF(v_item->>'purchase_order_item_id', '') IS NULL THEN
      RAISE EXCEPTION 'Each PO invoice line requires purchase_order_item_id';
    END IF;
    SELECT * INTO v_po_item
      FROM public.purchase_order_items
     WHERE id = (v_item->>'purchase_order_item_id')::uuid
       AND po_id = p_purchase_order_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Purchase Invoice item is not a line of the selected Purchase Order';
    END IF;
    IF NULLIF(v_item->>'product_id', '')::uuid IS DISTINCT FROM v_po_item.product_id THEN
      RAISE EXCEPTION 'Purchase Invoice product does not match its Purchase Order line';
    END IF;
  END LOOP;

  v_result := public.save_purchase_invoice(NULL, p_invoice_data, p_items);
  v_invoice_id := (v_result->>'invoice_id')::uuid;

  UPDATE public.purchase_invoices
     SET purchase_order_id = p_purchase_order_id
   WHERE id = v_invoice_id;

  -- save_purchase_invoice inserts lines in JSON-array order. Match by the
  -- same stable creation ordering and persist each PO line link.
  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))
  LOOP
    v_ordinal := v_ordinal + 1;
    SELECT id INTO v_invoice_item_id
      FROM public.purchase_invoice_items
     WHERE purchase_invoice_id = v_invoice_id
     -- ctid reflects the insert order within this transaction (the existing
     -- save RPC does not expose a line number), so duplicate-product lines
     -- still map deterministically to the input array.
     ORDER BY ctid
     OFFSET v_ordinal - 1 LIMIT 1;
    IF v_invoice_item_id IS NOT NULL THEN
      UPDATE public.purchase_invoice_items
         SET purchase_order_item_id = (v_item->>'purchase_order_item_id')::uuid
       WHERE id = v_invoice_item_id;
    END IF;
  END LOOP;

  RETURN v_result || jsonb_build_object('purchase_order_id', p_purchase_order_id);
END;
$$;


--
-- Name: create_sales_invoice_atomic("jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_sales_invoice_atomic"("p_invoice" "jsonb", "p_items" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_invoice_id uuid;
  v_subtotal numeric := 0;
  v_tax numeric := 0;
  v_discount numeric := COALESCE((p_invoice->>'discount_amount')::numeric, 0);
  v_stamp numeric := COALESCE((p_invoice->>'stamp_duty_amount')::numeric, 0);
  v_total numeric;
  v_count integer := 0;
  v_item jsonb;
  v_product uuid;
  v_batch uuid;
  v_dc_item uuid;
  v_qty numeric;
  v_price numeric;
  v_rate numeric;
  v_dc record;
  v_linked_challans uuid[];
  v_invoice_so_id uuid := NULLIF(p_invoice->>'sales_order_id','')::uuid;
BEGIN
  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('admin','accounts','sales','manager','warehouse') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot create sales invoices', v_role;
  END IF;
  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Sales invoice requires at least one product line';
  END IF;
  IF NULLIF(p_invoice->>'invoice_number','') IS NULL OR NULLIF(p_invoice->>'customer_id','') IS NULL THEN
    RAISE EXCEPTION 'Invoice number and customer are required';
  END IF;
  IF EXISTS (SELECT 1 FROM public.sales_invoices WHERE invoice_number=p_invoice->>'invoice_number') THEN
    RAISE EXCEPTION 'Invoice number already exists';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_product := NULLIF(v_item->>'product_id','')::uuid;
    v_batch := NULLIF(v_item->>'batch_id','')::uuid;
    v_dc_item := NULLIF(v_item->>'delivery_challan_item_id','')::uuid;
    v_qty := (v_item->>'quantity')::numeric;
    v_price := (v_item->>'unit_price')::numeric;
    v_rate := COALESCE((v_item->>'tax_rate')::numeric, 0);
    IF v_product IS NULL OR v_dc_item IS NULL OR COALESCE(v_qty,0) <= 0 OR COALESCE(v_price,0) < 0 THEN
      RAISE EXCEPTION 'Every invoice line must have a source Delivery Challan item, product, quantity, and price';
    END IF;
    SELECT dci.product_id,dci.batch_id,dci.quantity,dc.customer_id,dc.approval_status,dc.sales_order_id
      INTO v_dc
    FROM public.delivery_challan_items dci
    JOIN public.delivery_challans dc ON dc.id=dci.challan_id
    WHERE dci.id=v_dc_item
    FOR SHARE;
    IF NOT FOUND OR v_dc.product_id IS DISTINCT FROM v_product OR v_dc.batch_id IS DISTINCT FROM v_batch
       OR v_dc.customer_id IS DISTINCT FROM (p_invoice->>'customer_id')::uuid
       OR v_dc.approval_status <> 'approved' THEN
      RAISE EXCEPTION 'Invoice line source Delivery Challan is invalid or not approved';
    END IF;
    IF v_invoice_so_id IS NOT NULL AND v_dc.sales_order_id IS DISTINCT FROM v_invoice_so_id THEN
      RAISE EXCEPTION 'Invoice Sales Order does not match its Delivery Challan source';
    END IF;
    IF v_qty > v_dc.quantity - COALESCE((SELECT sum(sii.quantity) FROM public.sales_invoice_items sii
      WHERE sii.delivery_challan_item_id=v_dc_item),0) THEN
      RAISE EXCEPTION 'Invoice quantity exceeds remaining Delivery Challan quantity';
    END IF;
    v_subtotal := v_subtotal + (v_qty * v_price);
    v_tax := v_tax + (v_qty * v_price * v_rate / 100);
    v_count := v_count + 1;
  END LOOP;
  v_total := v_subtotal + v_tax - v_discount + v_stamp;
  SELECT array_agg(DISTINCT dc.id) INTO v_linked_challans
  FROM public.delivery_challan_items dci
  JOIN public.delivery_challans dc ON dc.id=dci.challan_id
  WHERE dci.id IN (SELECT (value->>'delivery_challan_item_id')::uuid FROM jsonb_array_elements(p_items));
  IF p_invoice ? 'subtotal' AND abs(v_subtotal - (p_invoice->>'subtotal')::numeric) > 0.01
     OR p_invoice ? 'tax_amount' AND abs(v_tax - (p_invoice->>'tax_amount')::numeric) > 0.01
     OR p_invoice ? 'total_amount' AND abs(v_total - (p_invoice->>'total_amount')::numeric) > 0.01 THEN
    RAISE EXCEPTION 'Invoice totals do not match persisted product lines';
  END IF;

  INSERT INTO public.sales_invoices (
    invoice_number,customer_id,sales_order_id,invoice_date,due_date,discount_amount,
    delivery_challan_number,po_number,payment_terms_days,notes,subtotal,tax_amount,
    stamp_duty_amount,total_amount,payment_status,created_by,linked_challan_ids
  ) VALUES (
    p_invoice->>'invoice_number',(p_invoice->>'customer_id')::uuid,v_invoice_so_id,
    COALESCE((p_invoice->>'invoice_date')::date,CURRENT_DATE),(p_invoice->>'due_date')::date,v_discount,
    NULL,p_invoice->>'po_number',(p_invoice->>'payment_terms_days')::integer,p_invoice->>'notes',
    v_subtotal,v_tax,v_stamp,v_total,'pending',COALESCE(NULLIF(p_invoice->>'created_by','')::uuid,auth.uid()),
    COALESCE(v_linked_challans, CASE WHEN jsonb_typeof(p_invoice->'linked_challan_ids')='array' THEN
      ARRAY(SELECT jsonb_array_elements_text(p_invoice->'linked_challan_ids')::uuid) ELSE NULL END)
  ) RETURNING id INTO v_invoice_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO public.sales_invoice_items
      (invoice_id,product_id,batch_id,quantity,unit_price,tax_rate,delivery_challan_item_id)
    VALUES (v_invoice_id,(v_item->>'product_id')::uuid,NULLIF(v_item->>'batch_id','')::uuid,
      (v_item->>'quantity')::numeric,(v_item->>'unit_price')::numeric,
      COALESCE((v_item->>'tax_rate')::numeric,0),(v_item->>'delivery_challan_item_id')::uuid);
  END LOOP;

  IF (SELECT count(*) FROM public.sales_invoice_items WHERE invoice_id=v_invoice_id) <> v_count THEN
    RAISE EXCEPTION 'Invoice line count verification failed';
  END IF;
  RETURN v_invoice_id;
END;
$$;


--
-- Name: create_staff_account("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_staff_account"("p_staff_name" "text", "p_employee_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_coa_id UUID;
v_staff_id UUID;
v_next_code TEXT;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin') THEN
RAISE EXCEPTION 'Permission denied: only admin can create staff accounts';
END IF;

SELECT coa_account_id INTO v_coa_id
FROM staff_members
WHERE LOWER(staff_name) = LOWER(p_staff_name);

IF v_coa_id IS NOT NULL THEN
RETURN v_coa_id;
END IF;

SELECT '116' || LPAD((COUNT(*) + 1)::TEXT, 1, '0')
INTO v_next_code
FROM chart_of_accounts
WHERE code LIKE '116%' AND code != '1160';

INSERT INTO chart_of_accounts (code, name, account_type, is_active, description)
VALUES (
v_next_code,
p_staff_name || ' - Staff Advance',
'asset',
true,
'Staff advance account for ' || p_staff_name
)
RETURNING id INTO v_coa_id;

INSERT INTO staff_members (staff_name, coa_account_id, employee_id)
VALUES (p_staff_name, v_coa_id, p_employee_id)
RETURNING id INTO v_staff_id;

RETURN v_coa_id;
END;
$$;


--
-- Name: FUNCTION "create_staff_account"("p_staff_name" "text", "p_employee_id" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."create_staff_account"("p_staff_name" "text", "p_employee_id" "text") IS 'Creates staff account in COA and staff_members table';


--
-- Name: create_system_task("text", "text", timestamp with time zone, "text", "text", "uuid", "text", "text", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_system_task"("p_title" "text", "p_description" "text", "p_deadline" timestamp with time zone, "p_origin" "text", "p_reference_type" "text", "p_reference_id" "uuid", "p_assigned_role" "text", "p_priority" "text" DEFAULT NULL::"text", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_product_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_task_id uuid;
v_assigned_users uuid[];
v_auto_priority text;
v_creator_id uuid;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts', 'manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot create system tasks', v_role;
END IF;

v_assigned_users := get_users_by_role(p_assigned_role);
v_auto_priority  := COALESCE(p_priority, calculate_task_priority(p_deadline));

SELECT id INTO v_creator_id FROM user_profiles WHERE role = 'admin' AND is_active = true LIMIT 1;
IF v_creator_id IS NULL THEN
SELECT id INTO v_creator_id FROM user_profiles WHERE is_active = true LIMIT 1;
END IF;

INSERT INTO tasks (
title, description, deadline, priority, auto_priority, status,
task_type, task_mode, task_origin, reference_type, reference_id,
auto_assigned_role, assigned_users, customer_id, product_id, created_by, proof_required
) VALUES (
p_title, p_description, p_deadline, v_auto_priority::task_priority, v_auto_priority, 'to_do'::task_status,
'system', 'advisory', p_origin, p_reference_type, p_reference_id,
p_assigned_role, v_assigned_users, p_customer_id, p_product_id, v_creator_id, false
)
RETURNING id INTO v_task_id;

IF array_length(v_assigned_users, 1) > 0 THEN
INSERT INTO task_assignments (task_id, assigned_user_id, assigned_by)
SELECT v_task_id, unnest(v_assigned_users), v_creator_id;
END IF;

RETURN v_task_id;
END;
$$;


--
-- Name: create_system_task("text", "text", timestamp with time zone, "public"."task_priority", "uuid"[], "public"."task_origin_enum", "uuid", "uuid", "uuid", "text"[], "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_system_task"("p_title" "text", "p_description" "text", "p_deadline" timestamp with time zone, "p_priority" "public"."task_priority", "p_assigned_users" "uuid"[], "p_task_origin" "public"."task_origin_enum", "p_sales_order_id" "uuid" DEFAULT NULL::"uuid", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_tags" "text"[] DEFAULT ARRAY[]::"text"[], "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_task_id uuid;
v_system_user uuid;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts', 'manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot create system tasks', v_role;
END IF;

SELECT id INTO v_system_user FROM user_profiles WHERE role = 'admin' LIMIT 1;
IF v_system_user IS NULL THEN
v_system_user := auth.uid();
END IF;

INSERT INTO tasks (
title, description, deadline, priority, status, created_by, assigned_users,
task_type, task_mode, task_origin, sales_order_id, customer_id, product_id,
tags, auto_priority, system_metadata
) VALUES (
p_title, p_description, p_deadline, p_priority, 'to_do', v_system_user, p_assigned_users,
'system', 'advisory', p_task_origin, p_sales_order_id, p_customer_id, p_product_id,
array_append(p_tags, 'system-generated'), true, p_metadata
)
RETURNING id INTO v_task_id;

RETURN v_task_id;
END;
$$;


--
-- Name: create_task_status_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_task_status_history"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
IF (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status) THEN
INSERT INTO task_status_history (
task_id,
old_status,
new_status,
changed_by,
notes
) VALUES (
NEW.id,
OLD.status,
NEW.status,
NEW.updated_by,
'Status changed from ' || OLD.status || ' to ' || NEW.status
);
END IF;
RETURN NEW;
END;
$$;


--
-- Name: current_user_has_pricing_role("text"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."current_user_has_pricing_role"("allowed_roles" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM user_profiles
    WHERE id = auth.uid()
      AND is_active = true
      AND role = ANY(allowed_roles)
  );
$$;


--
-- Name: delete_batch_safe("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_batch_safe"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  v_result := public.archive_batch_inventory_v1(p_batch_id);
  RETURN jsonb_build_object(
    'deleted', false,
    'archived', COALESCE((v_result->>'archived')::boolean, false),
    'batch_id', v_result->>'batch_id',
    'batch_number', v_result->>'batch_number',
    'reason', COALESCE(
      v_result->>'reason',
      'Inventory V1 preserves batch and movement history; the batch was archived'
    )
  );
END;
$$;


--
-- Name: delete_company_profile("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_company_profile"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ref_count bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND role = 'admin') THEN
    RAISE EXCEPTION 'FORBIDDEN: Only admins may delete company profiles.';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.company_profiles WHERE id = p_id) THEN
    RAISE EXCEPTION 'NOT_FOUND: Company profile does not exist.';
  END IF;

  -- Setup Mode: skip the reference-count check. The trigger above also
  -- no-ops in this mode, so the DELETE proceeds cleanly.
  IF NOT public.is_setup_mode() THEN
    SELECT COALESCE(SUM(ref_count), 0) INTO v_ref_count
    FROM public.get_company_profile_reference_counts()
    WHERE profile_id = p_id;

    IF v_ref_count > 0 THEN
      RAISE EXCEPTION
        'PROFILE_REFERENCED: This Company Profile is already referenced by % business document(s) and cannot be deleted. Historical company identities must remain permanently available.',
        v_ref_count;
    END IF;
  END IF;

  DELETE FROM public.company_profiles WHERE id = p_id;
END;
$$;


--
-- Name: delete_expense_journal_entries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_expense_journal_entries"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
-- Delete journal entry lines first (foreign key)
DELETE FROM journal_entry_lines jel
WHERE jel.journal_entry_id IN (
SELECT je.id FROM journal_entries je
WHERE je.source_module IN ('expense', 'expenses')
AND je.reference_number = 'EXP-' || OLD.id::text
);

-- Delete journal entries for this expense
DELETE FROM journal_entries 
WHERE source_module IN ('expense', 'expenses')
AND reference_number = 'EXP-' || OLD.id::text;

RETURN OLD;
END;
$$;


--
-- Name: delete_expense_safe("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_expense_safe"("p_expense_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_expense public.finance_expenses%ROWTYPE;
  v_allocation_count integer;
  v_legacy_count integer;
BEGIN
  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();
  IF v_role NOT IN ('admin', 'accounts') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot delete expenses', v_role;
  END IF;

  SELECT * INTO v_expense
    FROM public.finance_expenses
   WHERE id = p_expense_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;

  SELECT count(*) INTO v_allocation_count
    FROM public.bank_statement_allocations
   WHERE document_type = 'expense'
     AND document_id = p_expense_id;

  -- Separate statement: allocation triggers may safely recalculate the still
  -- existing expense, then the source row and its journals are deleted.
  DELETE FROM public.bank_statement_allocations
   WHERE document_type = 'expense'
     AND document_id = p_expense_id;

  -- Release pre-allocation legacy links to this expense. Allocation-owned
  -- lines have already been rebuilt by sync_bank_line_from_allocation().
  WITH released AS (
    UPDATE public.bank_statement_lines b SET
      matched_expense_id = NULL,
      matched_entry_id = NULL,
      reconciliation_status = 'unmatched',
      matching_status = 'none',
      matched_at = NULL,
      matched_by = NULL,
      manually_unlinked = true
    WHERE b.matched_expense_id = p_expense_id
      AND NOT EXISTS (
        SELECT 1 FROM public.bank_statement_allocations a
         WHERE a.bank_statement_line_id = b.id
      )
    RETURNING 1
  ) SELECT count(*) INTO v_legacy_count FROM released;

  DELETE FROM public.finance_expenses WHERE id = p_expense_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;

  IF EXISTS (
    SELECT 1 FROM public.bank_statement_allocations
     WHERE document_type = 'expense' AND document_id = p_expense_id
  ) THEN
    RAISE EXCEPTION 'Expense delete left orphan bank allocations';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.bank_statement_lines WHERE matched_expense_id = p_expense_id
  ) THEN
    RAISE EXCEPTION 'Expense delete left orphan bank references';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'released_allocations', v_allocation_count,
    'released_legacy_lines', v_legacy_count
  );
END;
$$;


--
-- Name: delete_fund_transfer("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_fund_transfer"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_transfer             public.fund_transfers%ROWTYPE;
  v_je_ids               uuid[];
  v_period               record;
  v_dependency           record;
  v_orphan_count         integer;
BEGIN
  PERFORM public._sec_check_finance_role();

  IF p_id IS NULL THEN
    RAISE EXCEPTION 'Fund transfer id is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT *
    INTO v_transfer
    FROM public.fund_transfers
   WHERE id = p_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fund transfer % not found', p_id
      USING ERRCODE = 'no_data_found';
  END IF;

  IF v_transfer.status = 'posted' THEN
    RAISE EXCEPTION
      'Posted fund transfer % cannot be deleted. Reverse it first, then delete it while the accounting period is open.',
      v_transfer.transfer_number
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT ap.fiscal_year, ap.period_month, ap.status
    INTO v_period
    FROM public.accounting_periods ap
   WHERE ap.start_date <= v_transfer.transfer_date
     AND ap.end_date >= v_transfer.transfer_date
   ORDER BY ap.start_date DESC
   LIMIT 1;

  IF FOUND AND v_period.status <> 'open' THEN
    RAISE EXCEPTION
      'Cannot delete fund transfer %: accounting period %-% is %.',
      v_transfer.transfer_number,
      v_period.fiscal_year,
      lpad(v_period.period_month::text, 2, '0'),
      v_period.status
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT je.id), ARRAY[]::uuid[])
    INTO v_je_ids
    FROM public.journal_entries je
   WHERE je.source_module = 'fund_transfers'
     AND (
       je.reference_id = p_id
       OR je.reference_number IN (
         v_transfer.transfer_number,
         'REV-' || v_transfer.transfer_number
       )
     );

  FOR v_period IN
    SELECT DISTINCT
           ap.fiscal_year,
           ap.period_month,
           ap.status,
           je.entry_date
      FROM public.journal_entries je
      JOIN public.accounting_periods ap
        ON ap.start_date <= je.entry_date
       AND ap.end_date >= je.entry_date
     WHERE je.id = ANY(v_je_ids)
       AND ap.status <> 'open'
  LOOP
    RAISE EXCEPTION
      'Cannot delete fund transfer %: journal accounting period %-% for % is %.',
      v_transfer.transfer_number,
      v_period.fiscal_year,
      lpad(v_period.period_month::text, 2, '0'),
      v_period.entry_date,
      v_period.status
      USING ERRCODE = 'check_violation';
  END LOOP;

  IF EXISTS (
    SELECT 1
      FROM public.journal_entries je
     WHERE je.reversed_by_id = ANY(v_je_ids)
       AND NOT (je.id = ANY(v_je_ids))
  ) THEN
    RAISE EXCEPTION
      'Cannot delete fund transfer %: an unrelated journal entry depends on its reversal journal.',
      v_transfer.transfer_number
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  -- Refuse to let an unexpected ON DELETE action modify another document.
  -- Expected Contra, ledger, and reconciliation owners are cleaned below.
  FOR v_dependency IN
    SELECT c.conrelid::regclass AS relation_name,
           a.attname AS column_name
      FROM pg_catalog.pg_constraint c
      JOIN pg_catalog.pg_attribute a
        ON a.attrelid = c.conrelid
       AND a.attnum = c.conkey[1]
     WHERE c.contype = 'f'
       AND c.confrelid = 'public.journal_entries'::regclass
       AND array_length(c.conkey, 1) = 1
       AND NOT (
         (c.conrelid = 'public.journal_entry_lines'::regclass
          AND a.attname = 'journal_entry_id')
         OR (c.conrelid = 'public.fund_transfers'::regclass
             AND a.attname = 'journal_entry_id')
         OR (c.conrelid = 'public.bank_statement_lines'::regclass
             AND a.attname = 'matched_entry_id')
         OR (c.conrelid = 'public.bank_reconciliation_items'::regclass
             AND a.attname = 'journal_entry_id')
         OR (c.conrelid = 'public.journal_entries'::regclass
             AND a.attname = 'reversed_by_id')
       )
  LOOP
    EXECUTE format(
      'SELECT count(*) FROM %s WHERE %I = ANY($1)',
      v_dependency.relation_name,
      v_dependency.column_name
    )
    INTO v_orphan_count
    USING v_je_ids;

    IF v_orphan_count <> 0 THEN
      RAISE EXCEPTION
        'Cannot delete fund transfer %: % dependent record(s) in % still reference its journal entry.',
        v_transfer.transfer_number,
        v_orphan_count,
        v_dependency.relation_name
        USING ERRCODE = 'foreign_key_violation';
    END IF;
  END LOOP;

  -- Break the Fund Transfer -> Journal Entry FK cycle before deleting journals.
  UPDATE public.fund_transfers
     SET journal_entry_id = NULL
   WHERE id = p_id;

  -- Release only links owned by this Contra or one of its collected journals.
  UPDATE public.bank_statement_lines
     SET matched_fund_transfer_id = NULL,
         matched_entry_id = NULL,
         reconciliation_status = 'unmatched',
         matched_at = NULL,
         matched_by = NULL,
         notes = NULL
   WHERE matched_fund_transfer_id = p_id
      OR matched_entry_id = ANY(v_je_ids);

  UPDATE public.bank_reconciliation_items
     SET journal_entry_id = NULL,
         is_matched = false,
         matched_at = NULL
   WHERE journal_entry_id = ANY(v_je_ids);

  -- Petty Cash displays current Fund Transfers directly. This cleanup is only
  -- for legacy projection rows and cannot create or alter accounting.
  DELETE FROM public.petty_cash_transactions
   WHERE fund_transfer_id = p_id;

  UPDATE public.journal_entries
     SET is_reversed = false,
         reversed_by_id = NULL
   WHERE id = ANY(v_je_ids)
     AND reversed_by_id = ANY(v_je_ids);

  DELETE FROM public.journal_entry_lines
   WHERE journal_entry_id = ANY(v_je_ids);

  DELETE FROM public.journal_entries
   WHERE id = ANY(v_je_ids);

  DELETE FROM public.fund_transfers
   WHERE id = p_id;

  -- Every check runs before commit. Any failure rolls the entire deletion back.
  SELECT count(*)
    INTO v_orphan_count
    FROM public.fund_transfers
   WHERE id = p_id;
  IF v_orphan_count <> 0 THEN
    RAISE EXCEPTION
      'Delete failed: fund transfer % still exists. No changes were committed.',
      v_transfer.transfer_number
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  SELECT count(*)
    INTO v_orphan_count
    FROM public.journal_entries
   WHERE id = ANY(v_je_ids)
      OR (
        source_module = 'fund_transfers'
        AND (
          reference_id = p_id
          OR reference_number IN (
            v_transfer.transfer_number,
            'REV-' || v_transfer.transfer_number
          )
        )
      );
  IF v_orphan_count <> 0 THEN
    RAISE EXCEPTION
      'Delete failed: % related journal entries remain for fund transfer %. No changes were committed.',
      v_orphan_count,
      v_transfer.transfer_number
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  SELECT count(*)
    INTO v_orphan_count
    FROM public.journal_entry_lines
   WHERE journal_entry_id = ANY(v_je_ids);
  IF v_orphan_count <> 0 THEN
    RAISE EXCEPTION
      'Delete failed: % related ledger postings remain for fund transfer %. No changes were committed.',
      v_orphan_count,
      v_transfer.transfer_number
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  SELECT count(*)
    INTO v_orphan_count
    FROM public.petty_cash_transactions
   WHERE fund_transfer_id = p_id;
  IF v_orphan_count <> 0 THEN
    RAISE EXCEPTION
      'Delete failed: % related Petty Cash rows remain for fund transfer %. No changes were committed.',
      v_orphan_count,
      v_transfer.transfer_number
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  SELECT count(*)
    INTO v_orphan_count
    FROM public.bank_statement_lines
   WHERE matched_fund_transfer_id = p_id
      OR matched_entry_id = ANY(v_je_ids);
  IF v_orphan_count <> 0 THEN
    RAISE EXCEPTION
      'Delete failed: % Bank Reconciliation links remain for fund transfer %. No changes were committed.',
      v_orphan_count,
      v_transfer.transfer_number
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  SELECT count(*)
    INTO v_orphan_count
    FROM public.bank_reconciliation_items
   WHERE journal_entry_id = ANY(v_je_ids);
  IF v_orphan_count <> 0 THEN
    RAISE EXCEPTION
      'Delete failed: % Bank Reconciliation items remain for fund transfer %. No changes were committed.',
      v_orphan_count,
      v_transfer.transfer_number
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
END;
$_$;


--
-- Name: delete_payment_voucher_with_allocations("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_payment_voucher_with_allocations"("p_voucher_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
v_invoice_id uuid;
v_affected_invoice_ids uuid[];
BEGIN
SELECT COALESCE(array_agg(DISTINCT purchase_invoice_id), ARRAY[]::uuid[])
INTO v_affected_invoice_ids
FROM public.voucher_allocations
WHERE payment_voucher_id = p_voucher_id
AND purchase_invoice_id IS NOT NULL;

DELETE FROM public.voucher_allocations
WHERE payment_voucher_id = p_voucher_id;

DELETE FROM public.payment_vouchers
WHERE id = p_voucher_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Payment voucher % not found', p_voucher_id;
END IF;

FOR v_invoice_id IN SELECT DISTINCT unnest(v_affected_invoice_ids) LOOP
PERFORM public.recalculate_purchase_invoice_payment_state(v_invoice_id);
END LOOP;
END;
$$;


--
-- Name: delete_petty_cash_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_petty_cash_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.bank_statement_lines
     SET matched_petty_cash_id = NULL,
         matched_entry_id = NULL,
         reconciliation_status = 'unmatched',
         matched_at = NULL,
         matched_by = NULL,
         notes = NULL
   WHERE matched_petty_cash_id = OLD.id
      OR matched_entry_id IN (
        SELECT id
          FROM public.journal_entries
         WHERE source_module = 'petty_cash'
           AND reference_id = OLD.id
      );

  DELETE FROM public.journal_entry_lines
   WHERE journal_entry_id IN (
     SELECT id
       FROM public.journal_entries
      WHERE source_module = 'petty_cash'
        AND reference_id = OLD.id
   );

  DELETE FROM public.journal_entries
   WHERE source_module = 'petty_cash'
     AND reference_id = OLD.id;

  RETURN OLD;
END;
$$;


--
-- Name: FUNCTION "delete_petty_cash_journal"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."delete_petty_cash_journal"() IS 'Automatically deletes associated journal entries when petty cash transaction is deleted';


--
-- Name: delete_purchase_invoice("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_purchase_invoice"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice           purchase_invoices%ROWTYPE;
  v_je_ids            UUID[];
  v_affected_pvs      UUID[];
  v_original_je_id    UUID;
  v_orphan_pv_je_ids  UUID[];

  -- integrity-check counters
  v_orphan_pi         INT;
  v_orphan_items      INT;
  v_orphan_allocs     INT;
  v_orphan_jes        INT;
  v_orphan_je_lines   INT;
  v_orphan_bsl_pi     INT;
  v_orphan_bsl_pv     INT;
  v_orphan_batches    INT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_id IS NULL THEN
    RAISE EXCEPTION 'Purchase invoice id is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- (a) Lock the invoice row.
  SELECT * INTO v_invoice
    FROM public.purchase_invoices
   WHERE id = p_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Purchase invoice % not found', p_id USING ERRCODE = 'no_data_found';
  END IF;

  v_original_je_id := v_invoice.journal_entry_id;

  -- Collect every JE created by this invoice.
  SELECT COALESCE(array_agg(id), ARRAY[]::UUID[])
    INTO v_je_ids
    FROM public.journal_entries
   WHERE source_module = 'purchase_invoice'
     AND reference_id  = p_id;

  IF v_original_je_id IS NOT NULL
     AND NOT v_original_je_id = ANY (v_je_ids) THEN
    v_je_ids := array_append(v_je_ids, v_original_je_id);
  END IF;

  -- Payment vouchers that were paying THIS invoice.
  SELECT COALESCE(array_agg(DISTINCT payment_voucher_id), ARRAY[]::UUID[])
    INTO v_affected_pvs
    FROM public.voucher_allocations
   WHERE purchase_invoice_id = p_id
     AND payment_voucher_id IS NOT NULL;

  -- Drop the allocations pointing at this invoice.
  DELETE FROM public.voucher_allocations
   WHERE purchase_invoice_id = p_id;

  -- Identify PVs whose allocations are now empty and release their bank matches.
  IF array_length(v_affected_pvs, 1) IS NOT NULL THEN
    SELECT COALESCE(array_agg(pv.journal_entry_id), ARRAY[]::UUID[])
      INTO v_orphan_pv_je_ids
      FROM public.payment_vouchers pv
     WHERE pv.id = ANY (v_affected_pvs)
       AND pv.journal_entry_id IS NOT NULL
       AND NOT EXISTS (
             SELECT 1
               FROM public.voucher_allocations va
              WHERE va.payment_voucher_id = pv.id
           );

    IF array_length(v_orphan_pv_je_ids, 1) IS NOT NULL THEN
      UPDATE public.bank_statement_lines
         SET matched_entry_id        = NULL,
             matched_expense_id      = NULL,
             matched_receipt_id      = NULL,
             matched_petty_cash_id   = NULL,
             matched_fund_transfer_id= NULL,
             reconciliation_status   = 'unmatched',
             matched_at              = NULL,
             matched_by              = NULL
       WHERE matched_entry_id = ANY (v_orphan_pv_je_ids);
    END IF;
  END IF;

  -- Bank recon cleanup for the PI's OWN JEs (all typed FKs).
  IF array_length(v_je_ids, 1) IS NOT NULL THEN
    UPDATE public.bank_statement_lines
       SET matched_entry_id        = NULL,
           matched_expense_id      = NULL,
           matched_receipt_id      = NULL,
           matched_petty_cash_id   = NULL,
           matched_fund_transfer_id= NULL,
           reconciliation_status   = 'unmatched',
           matched_at              = NULL,
           matched_by              = NULL
     WHERE matched_entry_id = ANY (v_je_ids);
  END IF;

  -- Break invoice → JE FK before deleting the JE.
  IF v_original_je_id IS NOT NULL THEN
    UPDATE public.purchase_invoices
       SET journal_entry_id = NULL
     WHERE id = p_id;
  END IF;

  -- Delete JE lines then JE headers.
  IF array_length(v_je_ids, 1) IS NOT NULL THEN
    DELETE FROM public.journal_entry_lines
     WHERE journal_entry_id = ANY (v_je_ids);

    DELETE FROM public.journal_entries
     WHERE id = ANY (v_je_ids);
  END IF;

  -- Detach batches.
  UPDATE public.batches
     SET purchase_invoice_id = NULL
   WHERE purchase_invoice_id = p_id;

  -- Belt-and-braces items delete.
  DELETE FROM public.purchase_invoice_items
   WHERE purchase_invoice_id = p_id;

  -- Delete the invoice row.
  DELETE FROM public.purchase_invoices
   WHERE id = p_id;

  -- ═════════════════════════════════════════════════════════════════════
  -- INTEGRITY CHECKS
  --
  -- Every RAISE EXCEPTION below rolls back this transaction — the invoice
  -- stays, the JE stays, allocations stay. Better a visible failure than
  -- silent orphan state on the bank reconciliation screen.
  -- ═════════════════════════════════════════════════════════════════════

  SELECT COUNT(*) INTO v_orphan_pi
    FROM public.purchase_invoices
   WHERE id = p_id;
  IF v_orphan_pi <> 0 THEN
    RAISE EXCEPTION
      'delete_purchase_invoice(%): integrity check failed — purchase_invoices row still present (count=%). Rolling back.',
      p_id, v_orphan_pi
      USING ERRCODE = 'raise_exception';
  END IF;

  SELECT COUNT(*) INTO v_orphan_items
    FROM public.purchase_invoice_items
   WHERE purchase_invoice_id = p_id;
  IF v_orphan_items <> 0 THEN
    RAISE EXCEPTION
      'delete_purchase_invoice(%): integrity check failed — % orphan purchase_invoice_items remain. Rolling back.',
      p_id, v_orphan_items
      USING ERRCODE = 'raise_exception';
  END IF;

  SELECT COUNT(*) INTO v_orphan_allocs
    FROM public.voucher_allocations
   WHERE purchase_invoice_id = p_id;
  IF v_orphan_allocs <> 0 THEN
    RAISE EXCEPTION
      'delete_purchase_invoice(%): integrity check failed — % orphan voucher_allocations remain. Rolling back.',
      p_id, v_orphan_allocs
      USING ERRCODE = 'raise_exception';
  END IF;

  SELECT COUNT(*) INTO v_orphan_jes
    FROM public.journal_entries
   WHERE source_module = 'purchase_invoice'
     AND reference_id  = p_id;
  IF v_orphan_jes <> 0 THEN
    RAISE EXCEPTION
      'delete_purchase_invoice(%): integrity check failed — % orphan journal_entries (source_module=purchase_invoice) remain. Rolling back.',
      p_id, v_orphan_jes
      USING ERRCODE = 'raise_exception';
  END IF;

  IF array_length(v_je_ids, 1) IS NOT NULL THEN
    SELECT COUNT(*) INTO v_orphan_je_lines
      FROM public.journal_entry_lines
     WHERE journal_entry_id = ANY (v_je_ids);
    IF v_orphan_je_lines <> 0 THEN
      RAISE EXCEPTION
        'delete_purchase_invoice(%): integrity check failed — % orphan journal_entry_lines remain against deleted JEs. Rolling back.',
        p_id, v_orphan_je_lines
        USING ERRCODE = 'raise_exception';
    END IF;

    SELECT COUNT(*) INTO v_orphan_bsl_pi
      FROM public.bank_statement_lines
     WHERE matched_entry_id = ANY (v_je_ids);
    IF v_orphan_bsl_pi <> 0 THEN
      RAISE EXCEPTION
        'delete_purchase_invoice(%): integrity check failed — % bank_statement_lines still matched to deleted PI JEs. Rolling back.',
        p_id, v_orphan_bsl_pi
        USING ERRCODE = 'raise_exception';
    END IF;
  END IF;

  IF array_length(v_orphan_pv_je_ids, 1) IS NOT NULL THEN
    SELECT COUNT(*) INTO v_orphan_bsl_pv
      FROM public.bank_statement_lines
     WHERE matched_entry_id = ANY (v_orphan_pv_je_ids);
    IF v_orphan_bsl_pv <> 0 THEN
      RAISE EXCEPTION
        'delete_purchase_invoice(%): integrity check failed — % bank_statement_lines still matched to orphan PV JEs. Rolling back.',
        p_id, v_orphan_bsl_pv
        USING ERRCODE = 'raise_exception';
    END IF;
  END IF;

  SELECT COUNT(*) INTO v_orphan_batches
    FROM public.batches
   WHERE purchase_invoice_id = p_id;
  IF v_orphan_batches <> 0 THEN
    RAISE EXCEPTION
      'delete_purchase_invoice(%): integrity check failed — % batches still tagged to deleted invoice. Rolling back.',
      p_id, v_orphan_batches
      USING ERRCODE = 'raise_exception';
  END IF;

  -- ═════════════════════════════════════════════════════════════════════
  -- Audit trail — only reached when every check above passed.
  -- ═════════════════════════════════════════════════════════════════════
  BEGIN
    INSERT INTO public.audit_logs (
      table_name, record_id, action_type, old_values, new_values, user_id
    ) VALUES (
      'purchase_invoices',
      p_id,
      'delete',
      jsonb_build_object(
        'invoice_number',           v_invoice.invoice_number,
        'supplier_id',              v_invoice.supplier_id,
        'invoice_date',             v_invoice.invoice_date,
        'total_amount',             v_invoice.total_amount,
        'paid_amount',              v_invoice.paid_amount,
        'status',                   v_invoice.status,
        'journal_entry_ids',        to_jsonb(v_je_ids),
        'payment_voucher_ids',      to_jsonb(v_affected_pvs),
        'orphan_pv_je_ids_released',to_jsonb(v_orphan_pv_je_ids),
        'integrity_checks',         'passed'
      ),
      jsonb_build_object(
        '_action',      'DELETE_PURCHASE_INVOICE',
        'deleted_at',   NOW(),
        'deleted_by',   auth.uid()
      ),
      auth.uid()
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
END;
$$;


--
-- Name: FUNCTION "delete_purchase_invoice"("p_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."delete_purchase_invoice"("p_id" "uuid") IS 'Accounting-safe PI delete with post-cleanup integrity verification.
Removes PI + its JE + own allocations, releases bank-recon links on any
PV whose allocations dropped to zero, then re-queries every table it
touched. If ANY orphan row remains (invoice, items, allocations, JE,
JE lines, matched bank lines, or tagged batches), RAISE EXCEPTION rolls
back the whole transaction. PV rows and their JEs are preserved for
manual review.';


--
-- Name: delete_receipt_voucher_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_receipt_voucher_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_je_ids uuid[];
BEGIN
  -- Collect every JE posted by this RV. reference_number OR reference_id can
  -- carry the link depending on when the RV was posted; we look up both.
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
    INTO v_je_ids
    FROM public.journal_entries
   WHERE source_module = 'receipt'
     AND (reference_id = OLD.id
          OR (OLD.journal_entry_id IS NOT NULL AND id = OLD.journal_entry_id));

  IF array_length(v_je_ids, 1) IS NULL THEN
    RETURN OLD;
  END IF;

  -- Release BSL matches on matched_entry_id (matched_receipt_id already
  -- clears itself via ON DELETE SET NULL, but the untyped JE FK doesn't).
  -- Do NOT touch updated_at — the column is not present in every env.
  UPDATE public.bank_statement_lines
     SET matched_entry_id      = NULL,
         reconciliation_status = 'unmatched',
         matched_at            = NULL
   WHERE matched_entry_id = ANY (v_je_ids);

  -- bank_reconciliation_items.journal_entry_id has ON DELETE SET NULL
  -- (installed in 20260714150000), so no explicit unlink needed.

  DELETE FROM public.journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);
  DELETE FROM public.journal_entries     WHERE id = ANY (v_je_ids);

  RETURN OLD;
END;
$$;


--
-- Name: FUNCTION "delete_receipt_voucher_journal"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."delete_receipt_voucher_journal"() IS 'Cascade cleanup of journal_entries + journal_entry_lines when a receipt_voucher is deleted. Mirrors delete_petty_cash_journal from 20260619170000. Also releases matched_entry_id on bank_statement_lines so BSL never keeps a stale FK.';


--
-- Name: delete_tax_payment("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_tax_payment"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payment        tax_payments%ROWTYPE;
  v_period_status  text;
  v_je_ids         uuid[];
  v_file_urls      text[];

  v_orphan_pay     int;
  v_orphan_je      int;
  v_orphan_je_lines int;
  v_orphan_bsl     int;
  v_orphan_bri     int;
  v_orphan_files   int;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_id IS NULL THEN
    RAISE EXCEPTION 'Tax payment id is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- Lock the row
  SELECT * INTO v_payment
    FROM public.tax_payments
   WHERE id = p_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tax payment % not found', p_id USING ERRCODE = 'no_data_found';
  END IF;

  -- Refuse if the period is closed (unless service_role)
  IF current_setting('request.jwt.claim.role', true) <> 'service_role' THEN
    SELECT status INTO v_period_status FROM tax_periods WHERE id = v_payment.tax_period_id;
    IF v_period_status = 'closed' THEN
      RAISE EXCEPTION 'Tax period is closed; cannot delete tax payment. Reopen the period first.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Collect JEs owned by this tax payment
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
    INTO v_je_ids
    FROM public.journal_entries
   WHERE source_module = 'tax_payment'
     AND reference_id  = p_id;

  IF v_payment.journal_entry_id IS NOT NULL
     AND NOT v_payment.journal_entry_id = ANY (v_je_ids) THEN
    v_je_ids := array_append(v_je_ids, v_payment.journal_entry_id);
  END IF;

  -- Release bank_statement_lines matched to this payment.
  -- NOTE: bank_statement_lines has no updated_at column — do not write it.
  UPDATE public.bank_statement_lines
     SET matched_entry_id       = NULL,
         matched_tax_payment_id = NULL,
         reconciliation_status  = 'unmatched'
   WHERE (matched_tax_payment_id = p_id)
      OR (array_length(v_je_ids, 1) IS NOT NULL AND matched_entry_id = ANY (v_je_ids));

  -- Release bank_reconciliation_items entries
  IF array_length(v_je_ids, 1) IS NOT NULL THEN
    UPDATE public.bank_reconciliation_items
       SET is_matched = false,
           matched_at = NULL
     WHERE journal_entry_id = ANY (v_je_ids);
  END IF;

  -- Snapshot attachment paths BEFORE cascade-deleting the rows
  SELECT COALESCE(array_agg(file_url), ARRAY[]::text[])
    INTO v_file_urls
    FROM public.tax_payment_files
   WHERE tax_payment_id = p_id;

  DELETE FROM public.tax_payment_files WHERE tax_payment_id = p_id;

  -- Break FK from tax_payments → JE before deleting JE
  UPDATE public.tax_payments
     SET journal_entry_id = NULL
   WHERE id = p_id;

  IF array_length(v_je_ids, 1) IS NOT NULL THEN
    DELETE FROM public.journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);
    DELETE FROM public.journal_entries     WHERE id = ANY (v_je_ids);
  END IF;

  DELETE FROM public.tax_payments WHERE id = p_id;

  -- ═══ INTEGRITY CHECKS ═════════════════════════════════════════════════
  SELECT COUNT(*) INTO v_orphan_pay FROM public.tax_payments WHERE id = p_id;
  IF v_orphan_pay <> 0 THEN
    RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — tax_payments row still present. Rolling back.', p_id
      USING ERRCODE = 'raise_exception';
  END IF;

  SELECT COUNT(*) INTO v_orphan_je
    FROM public.journal_entries
   WHERE source_module = 'tax_payment' AND reference_id = p_id;
  IF v_orphan_je <> 0 THEN
    RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % orphan journal_entries (source=tax_payment) remain. Rolling back.', p_id, v_orphan_je
      USING ERRCODE = 'raise_exception';
  END IF;

  IF array_length(v_je_ids, 1) IS NOT NULL THEN
    SELECT COUNT(*) INTO v_orphan_je_lines
      FROM public.journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);
    IF v_orphan_je_lines <> 0 THEN
      RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % orphan journal_entry_lines remain. Rolling back.', p_id, v_orphan_je_lines
        USING ERRCODE = 'raise_exception';
    END IF;

    SELECT COUNT(*) INTO v_orphan_bsl
      FROM public.bank_statement_lines
     WHERE matched_entry_id = ANY (v_je_ids);
    IF v_orphan_bsl <> 0 THEN
      RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % bank_statement_lines still matched to deleted JE. Rolling back.', p_id, v_orphan_bsl
        USING ERRCODE = 'raise_exception';
    END IF;

    SELECT COUNT(*) INTO v_orphan_bri
      FROM public.bank_reconciliation_items
     WHERE journal_entry_id = ANY (v_je_ids) AND is_matched = true;
    IF v_orphan_bri <> 0 THEN
      RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % bank_reconciliation_items still matched to deleted JE. Rolling back.', p_id, v_orphan_bri
        USING ERRCODE = 'raise_exception';
    END IF;
  END IF;

  SELECT COUNT(*) INTO v_orphan_files FROM public.tax_payment_files WHERE tax_payment_id = p_id;
  IF v_orphan_files <> 0 THEN
    RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % orphan tax_payment_files remain. Rolling back.', p_id, v_orphan_files
      USING ERRCODE = 'raise_exception';
  END IF;

  -- Audit trail (best-effort — do not let audit failure abort the delete)
  BEGIN
    INSERT INTO public.audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)
    VALUES (
      'tax_payments', p_id, 'delete',
      jsonb_build_object(
        'tax_period_id',   v_payment.tax_period_id,
        'tax_type',        v_payment.tax_type,
        'amount',          v_payment.amount,
        'payment_date',    v_payment.payment_date,
        'status',          v_payment.status,
        'file_urls',       v_file_urls
      ),
      NULL,
      auth.uid()
    );
  EXCEPTION WHEN OTHERS THEN
    NULL; -- audit failure must not abort the delete
  END;
END $$;


--
-- Name: FUNCTION "delete_tax_payment"("p_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."delete_tax_payment"("p_id" "uuid") IS 'Accounting-safe tax payment delete. Reverses JE, releases bank recon match
(both typed FK and matched_entry_id), removes attachments, refuses on
closed periods, self-verifies orphan state, RAISE EXCEPTION rolls back on
any orphan. Storage bucket cleanup is client-side (file_urls returned in
audit_logs.old_values.file_urls_released).';


--
-- Name: describe_undo_reverse_bank_conflict("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."describe_undo_reverse_bank_conflict"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer       public.fund_transfers%ROWTYPE;
  v_line           record;
  v_allowed_je_ids uuid[];
  v_doc_type       text;
  v_doc_number     text;
  v_je_id          uuid;
  v_je_number      text;
  v_je_source      text;
  v_je_reference   text;
  v_linked_je_id   uuid;
BEGIN
  SELECT *
    INTO v_transfer
    FROM public.fund_transfers
   WHERE id = p_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
    INTO v_allowed_je_ids
    FROM public.journal_entries
   WHERE source_module = 'fund_transfers'
     AND (
       reference_id = p_id
       OR reference_number IN (
         v_transfer.transfer_number,
         'REV-' || v_transfer.transfer_number
       )
     );

  SELECT bsl.*, expected.link_side
    INTO v_line
    FROM (
      VALUES
        (v_transfer.from_bank_statement_line_id, 'source', 1),
        (v_transfer.to_bank_statement_line_id, 'destination', 2)
    ) AS expected(line_id, link_side, sort_order)
    JOIN public.bank_statement_lines bsl ON bsl.id = expected.line_id
   WHERE bsl.matched_expense_id IS NOT NULL
      OR bsl.matched_receipt_id IS NOT NULL
      OR bsl.matched_petty_cash_id IS NOT NULL
      OR bsl.matched_tax_payment_id IS NOT NULL
      OR (
        bsl.matched_fund_transfer_id IS NOT NULL
        AND bsl.matched_fund_transfer_id <> p_id
      )
      OR (
        bsl.matched_entry_id IS NOT NULL
        AND NOT (bsl.matched_entry_id = ANY(v_allowed_je_ids))
      )
   ORDER BY expected.sort_order
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_je_id := CASE
    WHEN v_line.matched_entry_id IS NOT NULL
     AND NOT (v_line.matched_entry_id = ANY(v_allowed_je_ids))
    THEN v_line.matched_entry_id
    ELSE NULL
  END;

  IF v_line.matched_expense_id IS NOT NULL THEN
    v_doc_type := 'Expense';
    SELECT voucher_number
      INTO v_doc_number
      FROM public.finance_expenses
     WHERE id = v_line.matched_expense_id;

    IF v_je_id IS NULL THEN
      SELECT id
        INTO v_je_id
        FROM public.journal_entries
       WHERE source_module = 'expenses'
         AND reference_id = v_line.matched_expense_id
       ORDER BY created_at DESC
       LIMIT 1;
    END IF;
  ELSIF v_line.matched_receipt_id IS NOT NULL THEN
    v_doc_type := 'Receipt Voucher';
    SELECT voucher_number, journal_entry_id
      INTO v_doc_number, v_linked_je_id
      FROM public.receipt_vouchers
     WHERE id = v_line.matched_receipt_id;
    v_je_id := COALESCE(v_je_id, v_linked_je_id);
  ELSIF v_line.matched_petty_cash_id IS NOT NULL THEN
    v_doc_type := 'Petty Cash Transaction';
    SELECT transaction_number
      INTO v_doc_number
      FROM public.petty_cash_transactions
     WHERE id = v_line.matched_petty_cash_id;

    IF v_je_id IS NULL THEN
      SELECT id
        INTO v_je_id
        FROM public.journal_entries
       WHERE source_module = 'petty_cash'
         AND reference_id = v_line.matched_petty_cash_id
       ORDER BY created_at DESC
       LIMIT 1;
    END IF;
  ELSIF v_line.matched_tax_payment_id IS NOT NULL THEN
    v_doc_type := 'Tax Payment';
    SELECT COALESCE(ntpn, billing_code, government_reference, id::text),
           journal_entry_id
      INTO v_doc_number, v_linked_je_id
      FROM public.tax_payments
     WHERE id = v_line.matched_tax_payment_id;
    v_je_id := COALESCE(v_je_id, v_linked_je_id);
  ELSIF v_line.matched_fund_transfer_id IS NOT NULL
        AND v_line.matched_fund_transfer_id <> p_id THEN
    v_doc_type := 'Contra Voucher';
    SELECT transfer_number, journal_entry_id
      INTO v_doc_number, v_linked_je_id
      FROM public.fund_transfers
     WHERE id = v_line.matched_fund_transfer_id;
    v_je_id := COALESCE(v_je_id, v_linked_je_id);
  END IF;

  IF v_je_id IS NOT NULL THEN
    SELECT entry_number, source_module, reference_number
      INTO v_je_number, v_je_source, v_je_reference
      FROM public.journal_entries
     WHERE id = v_je_id;

    v_doc_number := COALESCE(v_doc_number, v_je_reference);
    IF v_doc_type IS NULL THEN
      v_doc_type := CASE v_je_source
        WHEN 'payment' THEN 'Payment Voucher'
        WHEN 'payment_vouchers' THEN 'Payment Voucher'
        WHEN 'receipt' THEN 'Receipt Voucher'
        WHEN 'receipt_vouchers' THEN 'Receipt Voucher'
        WHEN 'fund_transfers' THEN 'Contra Voucher'
        WHEN 'petty_cash' THEN 'Petty Cash Transaction'
        WHEN 'expenses' THEN 'Expense'
        WHEN 'tax_payment' THEN 'Tax Payment'
        WHEN 'tax_payments' THEN 'Tax Payment'
        ELSE 'Journal Entry'
      END;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'kind', 'bank_reconciliation_conflict',
    'bank_statement_line_id', v_line.id,
    'bank_account_id', v_line.bank_account_id,
    'transaction_date', v_line.transaction_date,
    'amount', COALESCE(
      NULLIF(v_line.debit_amount, 0),
      NULLIF(v_line.credit_amount, 0),
      0
    ),
    'currency', COALESCE(
      (SELECT currency
         FROM public.bank_accounts
        WHERE id = v_line.bank_account_id),
      'IDR'
    ),
    'document_type', COALESCE(v_doc_type, 'Linked Transaction'),
    'document_number', COALESCE(v_doc_number, 'Unavailable'),
    'journal_entry_id', v_je_id,
    'journal_entry_number', v_je_number
  );
END;
$$;


--
-- Name: diagnose_bank_line_link("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."diagnose_bank_line_link"("p_bank_line_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bsl              bank_statement_lines%ROWTYPE;
  v_fk_type          text;
  v_fk_uuid          uuid;
  v_exists           boolean := false;
  v_target_row       jsonb;
  v_target_company   uuid;
  v_bsl_bank_company uuid;
  v_current_uid      uuid;
  v_current_role     text;
BEGIN
  v_current_uid := auth.uid();
  SELECT role INTO v_current_role FROM user_profiles WHERE id = v_current_uid;

  SELECT * INTO v_bsl FROM bank_statement_lines WHERE id = p_bank_line_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','bank_statement_line not found','id',p_bank_line_id);
  END IF;

  -- Pick the first populated FK (priority mirrors display code).
  IF v_bsl.matched_fund_transfer_id IS NOT NULL THEN
    v_fk_type := 'fund_transfer'; v_fk_uuid := v_bsl.matched_fund_transfer_id;
  ELSIF v_bsl.matched_expense_id IS NOT NULL THEN
    v_fk_type := 'expense'; v_fk_uuid := v_bsl.matched_expense_id;
  ELSIF v_bsl.matched_receipt_id IS NOT NULL THEN
    v_fk_type := 'receipt'; v_fk_uuid := v_bsl.matched_receipt_id;
  ELSIF v_bsl.matched_petty_cash_id IS NOT NULL THEN
    v_fk_type := 'petty_cash'; v_fk_uuid := v_bsl.matched_petty_cash_id;
  ELSIF v_bsl.matched_entry_id IS NOT NULL THEN
    v_fk_type := 'journal_entry'; v_fk_uuid := v_bsl.matched_entry_id;
  ELSE
    RETURN jsonb_build_object(
      'bank_statement_line_id', v_bsl.id,
      'root_cause','no_fk_populated',
      'reconciliation_status', v_bsl.reconciliation_status,
      'notes', v_bsl.notes
    );
  END IF;

  -- Existence + target-side scope + soft-delete probe.
  IF v_fk_type = 'fund_transfer' THEN
    SELECT to_jsonb(t.*) INTO v_target_row FROM fund_transfers t WHERE t.id = v_fk_uuid;
  ELSIF v_fk_type = 'expense' THEN
    SELECT to_jsonb(t.*) INTO v_target_row FROM finance_expenses t WHERE t.id = v_fk_uuid;
  ELSIF v_fk_type = 'receipt' THEN
    SELECT to_jsonb(t.*) INTO v_target_row FROM receipt_vouchers t WHERE t.id = v_fk_uuid;
  ELSIF v_fk_type = 'petty_cash' THEN
    SELECT to_jsonb(t.*) INTO v_target_row FROM petty_cash_transactions t WHERE t.id = v_fk_uuid;
  ELSIF v_fk_type = 'journal_entry' THEN
    SELECT to_jsonb(t.*) INTO v_target_row FROM journal_entries t WHERE t.id = v_fk_uuid;
  END IF;
  v_exists := (v_target_row IS NOT NULL);

  -- Extract company_id if present (some tables have it, some don't).
  IF v_exists AND v_target_row ? 'company_id' THEN
    v_target_company := (v_target_row->>'company_id')::uuid;
  END IF;
  -- Best-effort bsl-side company: derive via bank_accounts.company_id if present.
  BEGIN
    SELECT ba.company_id INTO v_bsl_bank_company
      FROM bank_accounts ba WHERE ba.id = v_bsl.bank_account_id;
  EXCEPTION WHEN undefined_column THEN
    v_bsl_bank_company := NULL;
  END;

  RETURN jsonb_build_object(
    'bank_statement_line_id',  v_bsl.id,
    'fk_type',                 v_fk_type,
    'fk_uuid',                 v_fk_uuid,
    'exists_in_db',            v_exists,
    'target_row',              v_target_row,
    'target_company_id',       v_target_company,
    'bsl_bank_company_id',     v_bsl_bank_company,
    'company_match',           CASE
                                 WHEN v_target_company IS NULL OR v_bsl_bank_company IS NULL THEN NULL
                                 ELSE (v_target_company = v_bsl_bank_company)
                               END,
    'current_user_id',         v_current_uid,
    'current_role',            v_current_role,
    'reconciliation_status',   v_bsl.reconciliation_status,
    'root_cause',              CASE
                                 WHEN NOT v_exists                        THEN 'dangling_fk_target_deleted'
                                 WHEN v_target_company IS NOT NULL AND v_bsl_bank_company IS NOT NULL
                                      AND v_target_company <> v_bsl_bank_company THEN 'company_mismatch'
                                 ELSE 'rls_masks_target_for_current_role'
                               END
  );
END $$;


--
-- Name: dismiss_system_task("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."dismiss_system_task"("p_task_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts','manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot dismiss system tasks', v_role;
END IF;

UPDATE tasks
SET dismissed_at = now(), dismissed_by = auth.uid(), dismissal_reason = p_reason,
status = 'completed'::task_status
WHERE id = p_task_id AND task_type = 'system' AND task_mode = 'advisory';
RETURN FOUND;
END;
$$;


--
-- Name: edit_approved_finance_expense_atomic("uuid", "jsonb", "uuid", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."edit_approved_finance_expense_atomic"("p_expense_id" "uuid", "p_payload" "jsonb", "p_bank_statement_line_id" "uuid" DEFAULT NULL::"uuid", "p_allocation_amount" numeric DEFAULT NULL::numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_exp public.finance_expenses%rowtype;
  v_journal_id uuid;
  v_journal_count integer;
  v_date date;
  v_bank_id uuid;
  v_bank_currency text;
  v_currency text;
  v_rate numeric;
  v_docs text[];
  v_allocation record;
  v_same_selected_count integer;
  v_selected_amount numeric;
  v_period_status text;
BEGIN
  PERFORM public._sec_check_finance_role();
  SELECT * INTO v_exp FROM public.finance_expenses WHERE id=p_expense_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;
  IF v_exp.approval_status<>'approved' THEN RAISE EXCEPTION 'Approved expense edit requires an approved expense'; END IF;

  SELECT count(*),(array_agg(id ORDER BY created_at DESC,id DESC))[1]
    INTO v_journal_count,v_journal_id
    FROM public.journal_entries
   WHERE source_module IN('expense','expenses')
     AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)
     AND is_posted=true AND NOT COALESCE(is_reversed,false);
  IF v_journal_count<>1 THEN RAISE EXCEPTION 'Approved expense must have exactly one active effective journal'; END IF;
  PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;

  SELECT ap.status INTO v_period_status
    FROM public.journal_entries je
    LEFT JOIN public.accounting_periods ap
      ON ap.start_date<=je.entry_date AND ap.end_date>=je.entry_date
   WHERE je.id=v_journal_id
   ORDER BY ap.start_date DESC LIMIT 1;
  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN
    RAISE EXCEPTION 'Cannot edit approved expense in a closed accounting period';
  END IF;

  IF COALESCE((p_payload->>'amount')::numeric,0)<=0 THEN RAISE EXCEPTION 'Expense amount must be greater than zero'; END IF;
  IF NULLIF(p_payload->>'expense_category','') IS NULL THEN RAISE EXCEPTION 'Expense category is required'; END IF;
  v_date:=COALESCE((p_payload->>'expense_date')::date,current_date);
  v_bank_id:=NULLIF(p_payload->>'bank_account_id','')::uuid;
  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=v_bank_id;
  v_currency:=upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''),v_bank_currency,'IDR'));
  v_rate:=COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric,0),CASE WHEN v_currency='IDR' THEN 1 END);
  IF v_currency NOT IN('IDR','USD') OR v_rate IS NULL OR v_rate<=0 THEN RAISE EXCEPTION 'Valid expense currency/rate is required'; END IF;
  IF v_bank_currency IS NOT NULL AND v_bank_currency<>v_currency THEN RAISE EXCEPTION 'Expense currency does not match selected bank currency'; END IF;
  IF NULLIF(p_payload->>'payment_method','') IS NOT NULL
     AND NULLIF(p_payload->>'payment_method','') NOT IN('cash','petty_cash')
     AND v_bank_id IS NULL THEN RAISE EXCEPTION 'Bank-paid expense requires a bank account'; END IF;
  IF NULLIF(p_payload->>'payment_method','') IN('cash','petty_cash')
     AND p_bank_statement_line_id IS NOT NULL THEN RAISE EXCEPTION 'Cash/petty-cash expense cannot create a bank allocation'; END IF;
  IF NULLIF(p_payload->>'payment_method','') IS NULL AND p_bank_statement_line_id IS NOT NULL THEN RAISE EXCEPTION 'Accrued expense cannot create a bank allocation'; END IF;
  SELECT ap.status INTO v_period_status
    FROM public.accounting_periods ap
   WHERE ap.start_date<=v_date AND ap.end_date>=v_date
   ORDER BY ap.start_date DESC LIMIT 1;
  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN
    RAISE EXCEPTION 'Cannot move approved expense into a closed accounting period';
  END IF;
  SELECT COALESCE(array_agg(value),ARRAY[]::text[]) INTO v_docs
    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls','[]'::jsonb));

  -- Preserve the edited bank mode through the legacy unlinked-payment normalizer.
  PERFORM set_config('app.expense_atomic_bank_link','on',true);

  UPDATE public.finance_expenses SET
    expense_category=p_payload->>'expense_category',expense_type=COALESCE(NULLIF(p_payload->>'expense_type',''),'admin'),
    amount=(p_payload->>'amount')::numeric,expense_date=v_date,description=NULLIF(p_payload->>'description',''),
    batch_id=NULLIF(p_payload->>'batch_id','')::uuid,import_container_id=NULLIF(p_payload->>'import_container_id','')::uuid,
    delivery_challan_id=NULLIF(p_payload->>'delivery_challan_id','')::uuid,
    payment_method=NULLIF(p_payload->>'payment_method',''),bank_account_id=v_bank_id,
    payment_reference=NULLIF(p_payload->>'payment_reference',''),paid_by=NULLIF(p_payload->>'paid_by',''),
    document_urls=NULLIF(v_docs,ARRAY[]::text[]),supplier_id=NULLIF(p_payload->>'supplier_id','')::uuid,
    staff_id=NULLIF(p_payload->>'staff_id','')::uuid,invoice_number=NULLIF(p_payload->>'invoice_number',''),
    due_date=NULLIF(p_payload->>'due_date','')::date,broker_items=NULLIF(p_payload->'broker_items','null'::jsonb),
    pib_bm_amount=NULLIF(p_payload->>'pib_bm_amount','')::numeric,pib_ppn_amount=NULLIF(p_payload->>'pib_ppn_amount','')::numeric,
    pib_pph_amount=NULLIF(p_payload->>'pib_pph_amount','')::numeric,ppn_amount=COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0),
    ppn_manual_override=COALESCE((p_payload->>'ppn_manual_override')::boolean,false),
    ppn_calc_mode=COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'),dpp_amount=NULLIF(p_payload->>'dpp_amount','')::numeric,
    ppn_rate=COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11),pph_amount=COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),
    pph_code_id=NULLIF(p_payload->>'pph_code_id','')::uuid,stamp_duty_amount=COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),
    fixed_asset_account_id=NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,
    bank_charges_amount=COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),
    currency_code=v_currency,transaction_currency=v_currency,functional_currency='IDR',exchange_rate=v_rate,
    bank_account_currency=COALESCE(v_bank_currency,v_currency),payment_currency=v_currency
  WHERE id=p_expense_id;

  -- The trigger must retain the header identity and rebuild only its lines.
  IF NOT EXISTS(
    SELECT 1 FROM public.journal_entries
     WHERE id=v_journal_id
       AND source_module IN('expense','expenses')
       AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)
       AND is_posted AND NOT COALESCE(is_reversed,false)
  ) THEN RAISE EXCEPTION 'Expense journal identity changed during edit'; END IF;
  IF (SELECT count(*) FROM public.journal_entries
       WHERE source_module IN('expense','expenses')
         AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)
         AND is_posted AND NOT COALESCE(is_reversed,false))<>1 THEN
    RAISE EXCEPTION 'Expense edit did not preserve exactly one active journal';
  END IF;

  SELECT count(*),max(allocation_amount)
    INTO v_same_selected_count,v_selected_amount
    FROM public.bank_statement_allocations
   WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind='supplier'
     AND bank_statement_line_id=p_bank_statement_line_id;

  IF p_bank_statement_line_id IS NOT NULL
     AND v_same_selected_count=0 THEN
    PERFORM public.link_bank_statement_line(
      p_bank_statement_line_id,'expense',p_expense_id,'supplier',p_allocation_amount);
  ELSIF p_bank_statement_line_id IS NOT NULL
     AND p_allocation_amount IS NOT NULL
     AND abs(COALESCE(v_selected_amount,0)-p_allocation_amount)>0.01 THEN
    RAISE EXCEPTION 'Change an existing bank allocation through unlink/relink so other payments remain intact';
  ELSE
    -- A no-op FK update deliberately re-runs all canonical allocation guards
    -- against the rebuilt journal/bank account. Any mismatch rolls back save.
    UPDATE public.bank_statement_allocations SET allocation_amount=allocation_amount WHERE document_type='expense' AND document_id=p_expense_id;
  END IF;

  UPDATE public.bank_statement_allocations SET allocation_amount=allocation_amount WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind<>'supplier';

  PERFORM public.recalculate_expense_payment_state(p_expense_id);
  RETURN p_expense_id;
END;
$$;


--
-- Name: edit_delivery_challan("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."edit_delivery_challan"("p_challan_id" "uuid", "p_new_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role       text;
  v_challan    record;
  v_item       jsonb;
  v_count      integer;
  v_product_id uuid;
  v_batch_id   uuid;
  v_new_qty    numeric;
BEGIN
  SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
  IF v_role NOT IN ('admin', 'accounts', 'warehouse', 'sales', 'manager') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot edit delivery challans', v_role;
  END IF;

  SELECT * INTO v_challan FROM delivery_challans WHERE id = p_challan_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Delivery challan not found');
  END IF;

  IF v_challan.approved_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot edit approved delivery challan');
  END IF;

  SELECT count(*) INTO v_count FROM jsonb_array_elements(p_new_items);
  IF v_count = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot save DC with no items');
  END IF;

  -- Suppress the INSERT trigger on delivery_challan_items (safety: DC is pending anyway,
  -- trigger now also guards against non-approved DCs, but be explicit)
  PERFORM set_config('app.skip_dc_item_trigger', 'true', true);

  -- Remove all existing items for this DC
  DELETE FROM delivery_challan_items WHERE challan_id = p_challan_id;

  -- Insert the new item list
  -- No reserved_stock manipulation needed: reservations are in stock_reservations
  -- linked to the SO, not the DC. trg_sync_batch_reserved_stock handles accuracy.
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_new_items)
  LOOP
    v_product_id := (v_item->>'product_id')::uuid;
    v_batch_id   := (v_item->>'batch_id')::uuid;
    v_new_qty    := (v_item->>'quantity')::numeric;

    INSERT INTO delivery_challan_items (
      challan_id, product_id, batch_id, quantity,
      pack_size, pack_type, number_of_packs
    ) VALUES (
      p_challan_id, v_product_id, v_batch_id, v_new_qty,
      NULLIF(v_item->>'pack_size', '')::numeric,
      NULLIF(v_item->>'pack_type', ''),
      NULLIF(v_item->>'number_of_packs', '')::integer
    );
  END LOOP;

  PERFORM set_config('app.skip_dc_item_trigger', 'false', true);

  RETURN jsonb_build_object('success', true, 'message', 'Delivery challan updated successfully');

EXCEPTION
  WHEN foreign_key_violation THEN
    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);
    RETURN jsonb_build_object('success', false, 'error', 'Invalid product or batch selection');
  WHEN OTHERS THEN
    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: effective_sales_cogs_unit_cost("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."effective_sales_cogs_unit_cost"("p_batch_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    NULLIF(b.landed_cost_per_unit, 0),
    NULLIF(b.import_price, 0),
    NULLIF(b.cost_per_unit, 0)
  )
  FROM public.batches b
  WHERE b.id = p_batch_id;
$$;


--
-- Name: FUNCTION "effective_sales_cogs_unit_cost"("p_batch_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."effective_sales_cogs_unit_cost"("p_batch_id" "uuid") IS 'Returns authoritative landed unit cost (for imports) or authoritative local purchase unit cost (for local goods)';


--
-- Name: enforce_expense_category_parent_nonposting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_expense_category_parent_nonposting"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.parent_id IS NOT NULL THEN
    UPDATE public.expense_categories
    SET is_posting_category=false, coa_account_id=NULL
    WHERE id=NEW.parent_id AND is_posting_category;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_final_quote_write_restriction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_final_quote_write_restriction"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  caller_role text;
BEGIN
  -- Look up the role of the current user
  SELECT role INTO caller_role
  FROM user_profiles
  WHERE id = auth.uid()
    AND is_active = true;

  -- Only admin/manager may write final quote fields
  IF caller_role NOT IN ('admin', 'manager') THEN
    -- Block if any final quote field is being changed from its current value
    IF (
      NEW.final_quote_price      IS DISTINCT FROM OLD.final_quote_price      OR
      NEW.final_quote_currency   IS DISTINCT FROM OLD.final_quote_currency   OR
      NEW.final_entered_by       IS DISTINCT FROM OLD.final_entered_by       OR
      NEW.final_entered_at       IS DISTINCT FROM OLD.final_entered_at
    ) THEN
      RAISE EXCEPTION
        'Permission denied: only admin or manager may update final quote fields. '
        'Your role (%) cannot change final_quote_price, final_quote_currency, '
        'final_entered_by, or final_entered_at.',
        COALESCE(caller_role, 'unknown');
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_fund_transfer_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_fund_transfer_role"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      BEGIN
        IF pg_trigger_depth() > 1 THEN RETURN COALESCE(NEW, OLD); END IF;
        PERFORM public._sec_check_finance_role();
        IF TG_OP = 'INSERT' AND auth.role() <> 'service_role' THEN
          NEW.created_by := COALESCE(auth.uid(), NEW.created_by);
        END IF;
        RETURN COALESCE(NEW, OLD);
      END $$;


--
-- Name: enforce_no_journal_only_bank_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_no_journal_only_bank_link"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.matched_entry_id IS NULL 
    OR NEW.matched_expense_id IS NOT NULL 
    OR NEW.matched_receipt_id IS NOT NULL
    OR NEW.matched_payment_id IS NOT NULL 
    OR NEW.matched_fund_transfer_id IS NOT NULL 
    OR NEW.matched_petty_cash_id IS NOT NULL 
    OR NEW.matched_tax_payment_id IS NOT NULL 
    OR EXISTS (
      SELECT 1 FROM public.bank_statement_allocations a 
      WHERE a.bank_statement_line_id = NEW.id
    )
  THEN 
    RETURN NEW; 
  END IF;

  PERFORM 1 FROM public.journal_entries je
  JOIN public.journal_entry_lines jel ON jel.journal_entry_id=je.id
  JOIN public.bank_accounts ba ON ba.coa_id=jel.account_id
  WHERE je.id=NEW.matched_entry_id AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false
    AND ba.id=NEW.bank_account_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Direct journal-to-bank reconciliation is not allowed. Use a supported Finance document.' USING ERRCODE='check_violation'; END IF;
  RETURN NEW;
END $$;


--
-- Name: enforce_sales_invoice_write_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_sales_invoice_write_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_paid_actual numeric;
BEGIN
  -- Cascading updates from other triggers (e.g. recalculate_invoice_payment_
  -- status on voucher_allocations) are trusted. pg_trigger_depth() > 1 means
  -- we're inside a nested trigger chain.
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;

  IF auth.role() = 'service_role' THEN RETURN NEW; END IF;

  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();

  IF v_role NOT IN ('admin','accounts') THEN
    IF NEW.payment_status IS DISTINCT FROM OLD.payment_status
       OR NEW.paid_amount    IS DISTINCT FROM OLD.paid_amount
       OR NEW.total_amount   IS DISTINCT FROM OLD.total_amount
       OR NEW.customer_id    IS DISTINCT FROM OLD.customer_id THEN
      RAISE EXCEPTION 'Sales/warehouse cannot modify invoice financial fields (payment_status, paid_amount, total_amount, customer_id)';
    END IF;
  END IF;

  IF NEW.payment_status = 'paid' AND NEW.payment_status IS DISTINCT FROM OLD.payment_status THEN
    SELECT COALESCE(SUM(allocated_amount), 0) INTO v_paid_actual
    FROM public.voucher_allocations
    WHERE sales_invoice_id = NEW.id;
    IF v_paid_actual < COALESCE(NEW.total_amount, 0) THEN
      RAISE EXCEPTION 'Cannot mark invoice paid: allocated payments (%) < total (%)', v_paid_actual, NEW.total_amount;
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: enforce_sales_order_column_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_sales_order_column_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      DECLARE
        v_role text;
      BEGIN
        IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
        IF auth.role() = 'service_role' THEN RETURN NEW; END IF;

        SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();

        -- Admins can do anything.
        IF v_role = 'admin' THEN RETURN NEW; END IF;

        -- Non-owners cannot mutate sensitive commercial columns.
        IF OLD.created_by IS NOT NULL AND OLD.created_by <> auth.uid() THEN
          IF NEW.customer_id  IS DISTINCT FROM OLD.customer_id
             OR NEW.total_amount IS DISTINCT FROM OLD.total_amount THEN
            RAISE EXCEPTION 'Only the SO owner or an admin may change customer_id / total_amount';
          END IF;
        END IF;

        RETURN NEW;
      END $$;


--
-- Name: enforce_tax_je_period_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_tax_je_period_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP IN ('UPDATE','DELETE') AND OLD.source_module = 'tax_payment' THEN
    SELECT tp.status INTO v_status
    FROM tax_payments txp
    JOIN tax_periods tp ON tp.id = txp.tax_period_id
    WHERE txp.id = OLD.reference_id;
    IF v_status = 'closed' THEN
      RAISE EXCEPTION 'Tax period is closed; cannot modify tax-payment journal entry'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END $$;


--
-- Name: enforce_tax_period_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_tax_period_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  IF (current_setting('request.jwt.claim.role', true) = 'service_role') THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'UPDATE' OR TG_OP = 'DELETE' THEN
    -- Check OLD row's period
    IF (COALESCE(OLD.tax_period_id, NULL) IS NOT NULL) THEN
      SELECT status INTO v_status FROM tax_periods WHERE id = OLD.tax_period_id;
      IF v_status = 'closed' THEN
        RAISE EXCEPTION 'Tax period is closed; cannot modify % on %',
          TG_OP, TG_TABLE_NAME
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    IF NEW.tax_period_id IS NOT NULL THEN
      SELECT status INTO v_status FROM tax_periods WHERE id = NEW.tax_period_id;
      IF v_status = 'closed' THEN
        RAISE EXCEPTION 'Tax period is closed; cannot assign new rows to it'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END $$;


--
-- Name: execute_historical_expense_cash_restatement("text", "text", "uuid", "uuid", numeric, "jsonb", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."execute_historical_expense_cash_restatement"("p_idempotency_key" "text", "p_document_type" "text", "p_document_id" "uuid", "p_bank_statement_line_id" "uuid", "p_allocation_amount" numeric, "p_expected" "jsonb", "p_payment_kind" "text", "p_operation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing public.finance_historical_repair_commands%rowtype;
  v_cmd uuid;
  v_exp public.finance_expenses%rowtype;
  v_source_je uuid;
  v_reversal_je uuid;
  v_new_je uuid;
  v_bank_amount numeric;
  v_is_debit boolean;
  v_bank_coa uuid;
  v_ap_coa uuid;
  v_charge_coa uuid;
  v_cash_credit numeric;
  v_cash_lines integer;
  v_advance numeric;
  v_charge numeric;
  v_remaining_ap numeric;
  v_entry text;
  v_line record;
  v_line_no integer;
  v_before jsonb;
  v_after jsonb;
  v_alloc public.bank_statement_allocations%rowtype;
  v_new_debit numeric;
  v_new_credit numeric;
  v_pv006 uuid;
  v_pv007 uuid;
  v_je0001 uuid;
  v_je0002 uuid;
BEGIN
  IF p_operation NOT IN (
      'restate_salary_net_of_advance',
      'restate_partial_supplier_cash',
      'restate_evidenced_bank_charge') THEN
    RAISE EXCEPTION 'Unsupported restatement operation';
  END IF;
  IF p_document_type <> 'expense' THEN
    RAISE EXCEPTION 'Restatement requires an expense';
  END IF;
  IF p_bank_statement_line_id IS NULL OR p_allocation_amount <= 0 THEN
    RAISE EXCEPTION 'Restatement requires bank evidence and a positive allocation';
  END IF;
  IF p_bank_statement_line_id = 'c4c4033b-f661-4574-8878-dc593ee4eb33'::uuid THEN
    RAISE EXCEPTION 'Protected split allocation must not be modified';
  END IF;
  IF p_bank_statement_line_id = '5edf43b4-976a-4537-b97d-58ccec4e3e78'::uuid THEN
    RAISE EXCEPTION 'USD deposit is out of scope';
  END IF;
  SELECT * INTO v_existing FROM public.finance_historical_repair_commands
   WHERE idempotency_key=p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object('idempotent',true,'command_id',v_existing.id,
      'allocation_id',v_existing.created_allocation_id,'before',v_existing.before_state,
      'after',v_existing.after_state);
  END IF;
  INSERT INTO public.finance_historical_repair_commands(
    idempotency_key,document_type,document_id,bank_statement_line_id,payment_kind,
    operation,requested_by,before_state,after_state,status)
  VALUES(p_idempotency_key,p_document_type,p_document_id,p_bank_statement_line_id,p_payment_kind,
    p_operation,auth.uid(),'{}','{}','committed') RETURNING id INTO v_cmd;
  PERFORM set_config('app.finance_historical_repair_command',v_cmd::text,true);
  PERFORM set_config('app.finance_historical_repair','on',true);
  PERFORM 1 FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Missing expense source'; END IF;
  SELECT * INTO v_exp FROM public.finance_expenses WHERE id=p_document_id;
  IF v_exp.voucher_number IN ('EXP/26-26/115','EXP/26-26/139') THEN
    RAISE EXCEPTION 'Protected expense must not be modified';
  END IF;
  IF v_exp.expense_date >= DATE '2026-08-01' THEN
    RAISE EXCEPTION 'August 2026 expenses are out of scope';
  END IF;
  PERFORM 1 FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Missing cash evidence'; END IF;
  SELECT COALESCE(NULLIF(debit_amount,0),credit_amount,0),
         COALESCE(debit_amount,0)>0,
         (SELECT ba.coa_id FROM public.bank_accounts ba WHERE ba.id=bank_statement_lines.bank_account_id)
    INTO v_bank_amount, v_is_debit, v_bank_coa
    FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id;
  IF (SELECT transaction_date FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id)
       >= DATE '2026-08-01' THEN
    RAISE EXCEPTION 'August 2026 bank lines are out of scope';
  END IF;
  IF v_bank_coa IS NULL THEN RAISE EXCEPTION 'Missing bank ledger account'; END IF;
  IF abs(p_allocation_amount-v_bank_amount)>0.01 THEN
    RAISE EXCEPTION 'Allocation must equal the actual bank amount';
  END IF;
  IF p_expected ? 'bank_amount' AND abs((p_expected->>'bank_amount')::numeric-v_bank_amount)>0.01 THEN
    RAISE EXCEPTION 'Unexpected bank amount';
  END IF;
  IF NOT v_is_debit THEN
    RAISE EXCEPTION 'Expected a bank debit cash event';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations
      WHERE bank_statement_line_id=p_bank_statement_line_id) THEN
    RAISE EXCEPTION 'Duplicate cash event';
  END IF;
  SELECT je.id INTO v_source_je
    FROM public.journal_entries je
   WHERE je.id=COALESCE((p_expected->>'journal_id')::uuid, je.id)
     AND je.source_module IN ('expense','expenses')
     AND je.is_posted AND NOT COALESCE(je.is_reversed,false)
     AND (je.reference_id=p_document_id OR je.reference_number='EXP-'||p_document_id::text)
   FOR UPDATE;
  IF v_source_je IS NULL THEN RAISE EXCEPTION 'Expected posted source journal is missing'; END IF;
  IF p_expected ? 'journal_id' AND v_source_je::text <> p_expected->>'journal_id' THEN
    RAISE EXCEPTION 'Unexpected source journal';
  END IF;
  IF p_expected ? 'entry_number' AND (SELECT entry_number FROM public.journal_entries WHERE id=v_source_je)
       <> p_expected->>'entry_number' THEN
    RAISE EXCEPTION 'Unexpected journal';
  END IF;
  PERFORM 1 FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE journal_entry_id=v_source_je) THEN
    RAISE EXCEPTION 'Duplicate cash event';
  END IF;
  SELECT count(*), COALESCE(sum(l.credit),0) INTO v_cash_lines, v_cash_credit
    FROM public.journal_entry_lines l
   WHERE l.journal_entry_id=v_source_je AND l.account_id=v_bank_coa AND l.credit>0;
  IF v_cash_lines<>1 THEN
    RAISE EXCEPTION 'Source journal is not a single bank-credit cash recognition';
  END IF;
  SELECT id INTO v_ap_coa FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;
  IF v_ap_coa IS NULL THEN RAISE EXCEPTION 'AP account 2110 is missing'; END IF;
  SELECT jsonb_build_object('source_journal_id',je.id,'entry_number',je.entry_number,
      'total_debit',je.total_debit,'total_credit',je.total_credit,
      'paid_amount',v_exp.paid_amount,'settlement_amount',v_exp.settlement_amount,
      'pph_paid_amount',v_exp.pph_paid_amount,
      'lines',(SELECT COALESCE(jsonb_agg(to_jsonb(l) ORDER BY l.line_number),'[]')
               FROM public.journal_entry_lines l WHERE l.journal_entry_id=je.id))
    INTO v_before FROM public.journal_entries je WHERE je.id=v_source_je;
  IF p_operation='restate_salary_net_of_advance' THEN
    IF v_exp.voucher_number <> 'EXP/26-26/124' OR v_exp.expense_category <> 'salary' THEN
      RAISE EXCEPTION 'Salary restatement evidence does not match EXP/26-26/124';
    END IF;
    IF abs(v_exp.amount-2500000)>0.01 THEN RAISE EXCEPTION 'Unexpected salary amount'; END IF;
    IF abs(v_cash_credit-2500000)>0.01 THEN RAISE EXCEPTION 'Unexpected salary bank credit'; END IF;
    IF abs(v_bank_amount-2000000)>0.01 THEN RAISE EXCEPTION 'Unexpected salary cash event'; END IF;
    SELECT COALESCE(sum(applied_amount),0) INTO v_advance
      FROM public.salary_advance_applications WHERE salary_expense_id=p_document_id;
    IF abs(v_advance-500000)>0.01 THEN RAISE EXCEPTION 'Salary advance application is not Rp500,000'; END IF;
    SELECT id INTO v_pv006 FROM public.payment_vouchers WHERE voucher_number='PV/26-26/006' FOR UPDATE;
    SELECT id INTO v_pv007 FROM public.payment_vouchers WHERE voucher_number='PV/26-26/007' FOR UPDATE;
    SELECT id INTO v_je0001 FROM public.journal_entries WHERE entry_number='JE2608-0001' FOR UPDATE;
    SELECT id INTO v_je0002 FROM public.journal_entries WHERE entry_number='JE2608-0002' FOR UPDATE;
    IF v_pv006 IS NULL OR v_pv007 IS NULL OR v_je0001 IS NULL OR v_je0002 IS NULL THEN
      RAISE EXCEPTION 'Salary advance voucher/journal evidence is missing';
    END IF;
    IF EXISTS (SELECT 1 FROM public.journal_entry_lines l JOIN public.chart_of_accounts c ON c.id=l.account_id
                WHERE l.journal_entry_id=v_je0001 AND NOT (
                  (c.code='1160' AND l.debit=500000) OR (c.code='111101' AND l.credit=500000))) THEN
      RAISE EXCEPTION 'PV/26-26/006 journal is not the expected advance cash event';
    END IF;
    IF EXISTS (SELECT 1 FROM public.journal_entry_lines l JOIN public.chart_of_accounts c ON c.id=l.account_id
                WHERE l.journal_entry_id=v_je0002 AND NOT (
                  (c.code='2110' AND l.debit=500000) OR (c.code='1160' AND l.credit=500000))) THEN
      RAISE EXCEPTION 'PV/26-26/007 journal is not the expected advance recovery';
    END IF;
    v_remaining_ap := 500000;
  ELSIF p_operation='restate_partial_supplier_cash' THEN
    IF v_exp.voucher_number <> 'EXP/26-26/034' THEN
      RAISE EXCEPTION 'Partial-payment restatement evidence does not match EXP/26-26/034';
    END IF;
    IF abs(v_exp.amount-7000000)>0.01 OR abs(COALESCE(v_exp.pph_amount,0)-140000)>0.01 THEN
      RAISE EXCEPTION 'Unexpected expense/PPh amounts';
    END IF;
    IF abs(COALESCE(v_exp.pph_paid_amount,0))>0.01 THEN
      RAISE EXCEPTION 'PPh already remitted; stopping';
    END IF;
    IF abs(v_cash_credit-6860000)>0.01 THEN RAISE EXCEPTION 'Unexpected journal bank credit'; END IF;
    IF abs(v_bank_amount-6820000)>0.01 THEN RAISE EXCEPTION 'Unexpected bank cash event'; END IF;
    v_remaining_ap := 40000;
  ELSIF p_operation='restate_evidenced_bank_charge' THEN
    v_charge := COALESCE(v_exp.bank_charges_amount,0);
    IF abs(v_charge-3000)>0.01 THEN RAISE EXCEPTION 'Evidence does not show a Rp3,000 bank charge'; END IF;
    IF abs(v_bank_amount - v_cash_credit - v_charge)>0.01 THEN
      RAISE EXCEPTION 'Bank debit is not journal cash plus the evidenced charge';
    END IF;
    v_charge_coa := public.get_expense_account_id('bank_charges');
    IF v_charge_coa IS NULL THEN RAISE EXCEPTION 'Bank-charge account is missing'; END IF;
    IF EXISTS (SELECT 1 FROM public.journal_entry_lines
                WHERE journal_entry_id=v_source_je AND account_id=v_charge_coa AND debit>0) THEN
      RAISE EXCEPTION 'Bank charge already journaled; stopping to avoid duplication';
    END IF;
    IF v_exp.amount IS NULL THEN RAISE EXCEPTION 'Missing Telkom/service amount'; END IF;
  END IF;
  v_entry:=public.generate_journal_entry_number();
  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,
    description,total_debit,total_credit,is_posted,posted_at,posted_by,created_by)
  SELECT v_entry,je.entry_date,'historical_repair',v_exp.id,'HR-REV-'||v_cmd::text,
    'Explicit reversal of incorrect cash recognition '||je.entry_number,je.total_credit,je.total_debit,
    true,now(),auth.uid(),auth.uid()
    FROM public.journal_entries je WHERE je.id=v_source_je RETURNING id INTO v_reversal_je;
  v_line_no:=1;
  FOR v_line IN SELECT * FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je ORDER BY line_number LOOP
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
    VALUES(v_reversal_je,v_line_no,v_line.account_id,v_line.credit,v_line.debit,
      'Historical reversal: '||COALESCE(v_line.description,''),v_line.supplier_id);
    v_line_no:=v_line_no+1;
  END LOOP;
  UPDATE public.journal_entries SET is_reversed=true, reversed_by_id=v_reversal_je WHERE id=v_source_je;
  v_entry:=public.generate_journal_entry_number();
  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,
    description,total_debit,total_credit,is_posted,posted_at,posted_by,created_by)
  SELECT v_entry,je.entry_date,'historical_repair',v_exp.id,'HR-CASH-'||v_cmd::text,
    'Historical cash restatement for '||v_exp.voucher_number,0,0,true,now(),auth.uid(),auth.uid()
    FROM public.journal_entries je WHERE je.id=v_source_je RETURNING id INTO v_new_je;
  v_line_no:=1;
  IF p_operation='restate_salary_net_of_advance' THEN
    FOR v_line IN SELECT * FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je ORDER BY line_number LOOP
      IF v_line.account_id=v_bank_coa AND v_line.credit>0 THEN CONTINUE; END IF;
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
      VALUES(v_new_je,v_line_no,v_line.account_id,v_line.debit,v_line.credit,
        'Salary restatement: '||COALESCE(v_line.description,''),v_line.supplier_id);
      v_line_no:=v_line_no+1;
    END LOOP;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)
    VALUES(v_new_je,v_line_no,v_ap_coa,0,500000,'Salary advance applied (AP until recovery)');
    v_line_no:=v_line_no+1;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)
    VALUES(v_new_je,v_line_no,v_bank_coa,0,2000000,'July salary cash settlement');
    UPDATE public.finance_expenses SET paid_amount=2000000 WHERE id=p_document_id;
  ELSIF p_operation='restate_partial_supplier_cash' THEN
    FOR v_line IN SELECT * FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je ORDER BY line_number LOOP
      IF v_line.account_id=v_bank_coa AND v_line.credit>0 THEN CONTINUE; END IF;
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
      VALUES(v_new_je,v_line_no,v_line.account_id,v_line.debit,v_line.credit,
        'Partial-cash restatement: '||COALESCE(v_line.description,''),v_line.supplier_id);
      v_line_no:=v_line_no+1;
    END LOOP;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
    VALUES(v_new_je,v_line_no,v_ap_coa,0,40000,'Remaining supplier payable',v_exp.supplier_id);
    v_line_no:=v_line_no+1;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
    VALUES(v_new_je,v_line_no,v_bank_coa,0,6820000,'Actual bank payment',v_exp.supplier_id);
    UPDATE public.finance_expenses SET paid_amount=6820000 WHERE id=p_document_id;
  ELSE
    FOR v_line IN SELECT * FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je ORDER BY line_number LOOP
      IF v_line.account_id=v_bank_coa AND v_line.credit>0 THEN
        INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
        VALUES(v_new_je,v_line_no,v_line.account_id,v_line.debit,v_line.credit+v_charge,
          'Service cash plus evidenced bank charge: '||COALESCE(v_line.description,''),v_line.supplier_id);
      ELSE
        INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
        VALUES(v_new_je,v_line_no,v_line.account_id,v_line.debit,v_line.credit,
          COALESCE(v_line.description,''),v_line.supplier_id);
      END IF;
      v_line_no:=v_line_no+1;
    END LOOP;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)
    VALUES(v_new_je,v_line_no,v_charge_coa,v_charge,0,'Evidenced bank charge');
    UPDATE public.finance_expenses SET paid_amount=v_bank_amount WHERE id=p_document_id;
  END IF;
  SELECT COALESCE(sum(debit),0), COALESCE(sum(credit),0) INTO v_new_debit, v_new_credit
    FROM public.journal_entry_lines WHERE journal_entry_id=v_new_je;
  IF abs(v_new_debit-v_new_credit)>0.01 THEN
    RAISE EXCEPTION 'Replacement journal is not balanced';
  END IF;
  UPDATE public.journal_entries SET total_debit=v_new_debit, total_credit=v_new_credit WHERE id=v_new_je;
  SELECT COALESCE(sum(credit),0) INTO v_cash_credit
    FROM public.journal_entry_lines
   WHERE journal_entry_id=v_new_je AND account_id=v_bank_coa;
  IF abs(v_cash_credit-v_bank_amount)>0.01 THEN
    RAISE EXCEPTION 'Replacement bank movement does not match the bank statement';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE journal_entry_id=v_new_je) THEN
    RAISE EXCEPTION 'Duplicate cash event';
  END IF;
  INSERT INTO public.bank_statement_allocations(
    bank_statement_line_id,document_type,document_id,journal_entry_id,
    allocation_amount,payment_kind,created_by)
  VALUES(p_bank_statement_line_id,'expense',p_document_id,v_new_je,
    round(p_allocation_amount,2),p_payment_kind,auth.uid())
  RETURNING * INTO v_alloc;
  IF p_operation='restate_salary_net_of_advance' THEN
    IF (SELECT is_reversed FROM public.journal_entries WHERE id=v_je0001)
       OR (SELECT is_reversed FROM public.journal_entries WHERE id=v_je0002) THEN
      RAISE EXCEPTION 'Advance journals were altered';
    END IF;
  END IF;
  SELECT jsonb_build_object(
      'source_journal_id',v_source_je,
      'reversal_journal_id',v_reversal_je,
      'replacement_journal_id',v_new_je,
      'allocation_id',v_alloc.id,
      'allocation_amount',v_alloc.allocation_amount,
      'bank_amount',v_bank_amount,
      'remaining_ap',v_remaining_ap,
      'paid_amount',(SELECT paid_amount FROM public.finance_expenses WHERE id=p_document_id)
    ) INTO v_after;
  UPDATE public.finance_historical_repair_commands
     SET before_state=v_before, after_state=v_after, created_allocation_id=v_alloc.id
   WHERE id=v_cmd;
  RETURN jsonb_build_object('idempotent',false,'command_id',v_cmd,'allocation_id',v_alloc.id,
    'before',v_before,'after',v_after);
END;
$$;


--
-- Name: execute_historical_finance_repair("text", "text", "uuid", "uuid", numeric, "jsonb", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."execute_historical_finance_repair"("p_idempotency_key" "text", "p_document_type" "text", "p_document_id" "uuid", "p_bank_statement_line_id" "uuid", "p_allocation_amount" numeric, "p_expected" "jsonb", "p_payment_kind" "text" DEFAULT 'supplier'::"text", "p_operation" "text" DEFAULT 'allocate_existing_cash_event'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing public.finance_historical_repair_commands%rowtype;
  v_cmd uuid; v_je uuid; v_source_je uuid; v_reversal_je uuid; v_ap_je uuid;
  v_source_amount numeric; v_settlement numeric; v_bank_amount numeric; v_bank_coa uuid; v_ap_coa uuid;
  v_cash_lines integer; v_cash_credit numeric; v_bank_gl_debit numeric; v_bank_gl_credit numeric;
  v_is_debit boolean; v_je_balanced boolean; v_acct_ccy text; v_line_ccy text; v_je_ccy text;
  v_before jsonb; v_after jsonb; v_je_before jsonb; v_alloc public.bank_statement_allocations%rowtype;
  v_entry text; v_line record; v_line_no integer;
BEGIN
  IF auth.role()<>'service_role' AND current_user NOT IN ('postgres','supabase_admin')
     AND NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id=auth.uid() AND is_active=true AND role='admin') THEN
    RAISE EXCEPTION 'Historical repair requires service_role or admin';
  END IF;
  IF NULLIF(trim(p_idempotency_key),'') IS NULL OR p_allocation_amount<=0 THEN
    RAISE EXCEPTION 'Idempotency key and positive allocation amount are required';
  END IF;
  SELECT * INTO v_existing FROM public.finance_historical_repair_commands WHERE idempotency_key=p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object('idempotent',true,'command_id',v_existing.id,'allocation_id',v_existing.created_allocation_id,'before',v_existing.before_state,'after',v_existing.after_state);
  END IF;
  IF p_payment_kind NOT IN ('supplier','pph23') THEN RAISE EXCEPTION 'Unsupported payment kind'; END IF;

  IF p_operation='reclassify_cash_recognition_to_ap' THEN
    IF p_document_type <> 'expense' OR p_bank_statement_line_id IS NOT NULL THEN
      RAISE EXCEPTION 'AP reclassification requires an expense and no bank evidence';
    END IF;
    INSERT INTO public.finance_historical_repair_commands(idempotency_key,document_type,document_id,bank_statement_line_id,payment_kind,operation,requested_by,before_state,after_state,status)
    VALUES(p_idempotency_key,p_document_type,p_document_id,NULL,p_payment_kind,p_operation,auth.uid(),'{}','{}','committed') RETURNING id INTO v_cmd;
    PERFORM set_config('app.finance_historical_repair_command',v_cmd::text,true);
    PERFORM set_config('app.finance_historical_repair','on',true);
    PERFORM 1 FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Missing expense source'; END IF;
    SELECT settlement_amount,paid_amount INTO v_settlement,v_source_amount FROM public.finance_expenses WHERE id=p_document_id;
    IF COALESCE(v_source_amount,0)<>0 THEN RAISE EXCEPTION 'Expense is not unpaid'; END IF;
    IF abs(COALESCE(v_settlement,0)-p_allocation_amount)>0.01 THEN RAISE EXCEPTION 'Settlement amount mismatch'; END IF;
    IF EXISTS (SELECT 1 FROM public.payment_vouchers pv WHERE pv.description ILIKE '%'||(SELECT voucher_number FROM public.finance_expenses WHERE id=p_document_id)||'%' OR pv.reference_number ILIKE '%'||(SELECT voucher_number FROM public.finance_expenses WHERE id=p_document_id)||'%') THEN
      RAISE EXCEPTION 'Payment voucher evidence exists'; END IF;
    IF EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE document_type='expense' AND document_id=p_document_id) THEN RAISE EXCEPTION 'Bank allocation already exists'; END IF;
    IF EXISTS (SELECT 1 FROM public.bank_statement_lines WHERE matched_expense_id=p_document_id OR matched_payment_id IN (SELECT id FROM public.payment_vouchers WHERE description ILIKE '%'||(SELECT voucher_number FROM public.finance_expenses WHERE id=p_document_id)||'%')) THEN
      RAISE EXCEPTION 'Bank payment evidence exists'; END IF;
    SELECT je.id,fe.settlement_amount INTO v_source_je,v_settlement FROM public.journal_entries je JOIN public.finance_expenses fe ON fe.id=je.reference_id
      WHERE fe.id=p_document_id AND je.entry_number=COALESCE(p_expected->>'entry_number',je.entry_number) AND je.source_module IN ('expense','expenses') AND je.is_posted AND NOT COALESCE(je.is_reversed,false) FOR UPDATE;
    IF v_source_je IS NULL THEN RAISE EXCEPTION 'Expected posted recognition journal is missing'; END IF;
    IF p_expected ? 'journal_id' AND p_expected->>'journal_id'<>v_source_je::text THEN RAISE EXCEPTION 'Unexpected source journal'; END IF;
    PERFORM 1 FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je FOR UPDATE;
    SELECT ba.coa_id INTO v_bank_coa FROM public.bank_accounts ba WHERE EXISTS (SELECT 1 FROM public.journal_entry_lines l WHERE l.journal_entry_id=v_source_je AND l.account_id=ba.coa_id AND l.credit>0);
    SELECT count(*),COALESCE(sum(l.credit),0) INTO v_cash_lines,v_cash_credit FROM public.journal_entry_lines l WHERE l.journal_entry_id=v_source_je AND l.account_id=v_bank_coa AND l.credit>0;
    IF v_bank_coa IS NULL OR v_cash_lines<>1 OR abs(v_cash_credit-p_allocation_amount)>0.01 THEN RAISE EXCEPTION 'Source journal is not the expected cash recognition'; END IF;
    SELECT id INTO v_ap_coa FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;
    IF v_ap_coa IS NULL THEN RAISE EXCEPTION 'AP account 2110 is missing'; END IF;
    SELECT jsonb_build_object('source_journal_id',je.id,'entry_number',je.entry_number,'total_debit',je.total_debit,'total_credit',je.total_credit,'lines',(SELECT COALESCE(jsonb_agg(to_jsonb(l) ORDER BY l.line_number),'[]') FROM public.journal_entry_lines l WHERE l.journal_entry_id=je.id)) INTO v_before FROM public.journal_entries je WHERE je.id=v_source_je;
    IF p_expected ? 'settlement_amount' AND abs((p_expected->>'settlement_amount')::numeric-v_settlement)>0.01 THEN RAISE EXCEPTION 'Unexpected settlement amount'; END IF;
    v_entry:=public.generate_journal_entry_number();
    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,posted_by,created_by)
    SELECT v_entry,je.entry_date,'historical_repair',je.reference_id,'HR-REV-'||v_cmd::text,'Explicit reversal of incorrect cash recognition '||je.entry_number,je.total_credit,je.total_debit,true,now(),auth.uid(),auth.uid() FROM public.journal_entries je WHERE je.id=v_source_je RETURNING id INTO v_reversal_je;
    v_line_no:=1;
    FOR v_line IN SELECT * FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je ORDER BY line_number LOOP
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
      VALUES(v_reversal_je,v_line_no,v_line.account_id,v_line.credit,v_line.debit,'Historical reversal: '||COALESCE(v_line.description,''),v_line.supplier_id);
      v_line_no:=v_line_no+1;
    END LOOP;
    UPDATE public.journal_entries SET is_reversed=true,reversed_by_id=v_reversal_je WHERE id=v_source_je;
    v_entry:=public.generate_journal_entry_number();
    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,posted_by,created_by)
    SELECT v_entry,je.entry_date,'historical_repair',je.reference_id,'HR-AP-'||v_cmd::text,'Correct AP recognition for '||fe.voucher_number,je.total_debit,je.total_debit,true,now(),auth.uid(),auth.uid()
      FROM public.journal_entries je JOIN public.finance_expenses fe ON fe.id=je.reference_id WHERE je.id=v_source_je RETURNING id INTO v_ap_je;
    v_line_no:=1;
    FOR v_line IN SELECT l.* FROM public.journal_entry_lines l WHERE l.journal_entry_id=v_source_je ORDER BY l.line_number LOOP
      IF v_line.account_id=v_bank_coa AND v_line.credit>0 THEN CONTINUE; END IF;
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
      VALUES(v_ap_je,v_line_no,v_line.account_id,v_line.debit,v_line.credit,'AP correction: '||COALESCE(v_line.description,''),v_line.supplier_id);
      v_line_no:=v_line_no+1;
    END LOOP;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)
    VALUES(v_ap_je,v_line_no,v_ap_coa,0,p_allocation_amount,'Supplier/AP payable',(SELECT supplier_id FROM public.finance_expenses WHERE id=p_document_id));
    SELECT jsonb_build_object('reversal_journal_id',v_reversal_je,'replacement_journal_id',v_ap_je,'source_journal_id',v_source_je,'allocation_id',NULL,'paid_amount',0,'settlement_amount',v_settlement,'bank_allocation_count',0) INTO v_after;
    UPDATE public.finance_historical_repair_commands SET before_state=v_before,after_state=v_after WHERE id=v_cmd;
    RETURN jsonb_build_object('idempotent',false,'command_id',v_cmd,'before',v_before,'after',v_after);
  END IF;

  IF p_operation<>'allocate_existing_cash_event' THEN RAISE EXCEPTION 'Unsupported historical repair operation'; END IF;
  IF p_document_type NOT IN ('expense','payment','receipt','tax_payment','fund_transfer','petty_cash','journal') THEN RAISE EXCEPTION 'Unsupported historical repair document'; END IF;
  IF p_bank_statement_line_id IS NULL THEN RAISE EXCEPTION 'Allocation repair requires bank statement evidence'; END IF;
  INSERT INTO public.finance_historical_repair_commands(idempotency_key,document_type,document_id,bank_statement_line_id,payment_kind,operation,requested_by,before_state,after_state,status)
  VALUES(p_idempotency_key,p_document_type,p_document_id,p_bank_statement_line_id,p_payment_kind,p_operation,auth.uid(),'{}','{}','committed') RETURNING id INTO v_cmd;
  PERFORM set_config('app.finance_historical_repair_command',v_cmd::text,true);
  PERFORM set_config('app.finance_historical_repair','on',true);
  PERFORM 1 FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Missing cash evidence'; END IF;
  SELECT COALESCE(NULLIF(debit_amount,0),credit_amount,0), COALESCE(debit_amount,0)>0, currency,
         (SELECT ba.currency FROM public.bank_accounts ba WHERE ba.id=bank_statement_lines.bank_account_id),
         (SELECT ba.coa_id FROM public.bank_accounts ba WHERE ba.id=bank_statement_lines.bank_account_id)
    INTO v_bank_amount, v_is_debit, v_line_ccy, v_acct_ccy, v_bank_coa FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id;
  IF v_bank_amount IS NULL OR abs(p_allocation_amount-v_bank_amount)>0.01 THEN RAISE EXCEPTION 'Amount mismatch'; END IF;
  IF p_expected ? 'bank_amount' AND abs((p_expected->>'bank_amount')::numeric-v_bank_amount)>0.01 THEN RAISE EXCEPTION 'Unexpected bank amount'; END IF;
  IF v_bank_coa IS NULL THEN RAISE EXCEPTION 'Missing bank ledger account'; END IF;
  IF COALESCE(v_line_ccy, v_acct_ccy) IS DISTINCT FROM v_acct_ccy AND COALESCE(v_line_ccy, v_acct_ccy) IS NOT NULL THEN RAISE EXCEPTION 'Currency mismatch'; END IF;
  IF p_document_type='expense' THEN
    PERFORM 1 FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Missing expense source'; END IF;
    SELECT je.id INTO v_je FROM public.journal_entries je WHERE je.id=COALESCE((p_expected->>'journal_id')::uuid, je.id) AND je.source_module IN ('expense','expenses') AND je.is_posted AND NOT COALESCE(je.is_reversed,false) AND (je.reference_id=p_document_id OR je.reference_number='EXP-'||p_document_id::text) FOR UPDATE;
  ELSIF p_document_type='receipt' THEN SELECT journal_entry_id, amount INTO v_je, v_source_amount FROM public.receipt_vouchers WHERE id=p_document_id AND is_posted FOR UPDATE;
  ELSIF p_document_type='payment' THEN SELECT journal_entry_id, amount INTO v_je, v_source_amount FROM public.payment_vouchers WHERE id=p_document_id AND is_posted FOR UPDATE;
  ELSIF p_document_type='tax_payment' THEN SELECT journal_entry_id, amount INTO v_je, v_source_amount FROM public.tax_payments WHERE id=p_document_id FOR UPDATE;
  ELSIF p_document_type='fund_transfer' THEN SELECT journal_entry_id INTO v_je FROM public.fund_transfers WHERE id=p_document_id FOR UPDATE;
  ELSIF p_document_type='petty_cash' THEN SELECT journal_entry_id INTO v_je FROM public.petty_cash_transactions WHERE id=p_document_id FOR UPDATE;
  ELSIF p_document_type='journal' THEN v_je := p_document_id; PERFORM 1 FROM public.journal_entries WHERE id=v_je FOR UPDATE;
  END IF;
  IF p_expected ? 'journal_id' AND (v_je IS NULL OR v_je::text <> p_expected->>'journal_id') THEN RAISE EXCEPTION 'Unexpected journal'; END IF;
  IF v_je IS NULL THEN RAISE EXCEPTION 'Missing posted source journal/evidence'; END IF;
  PERFORM 1 FROM public.journal_entries WHERE id=v_je AND is_posted AND NOT COALESCE(is_reversed,false) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Missing posted source journal/evidence'; END IF;
  IF p_expected ? 'entry_number' AND (SELECT entry_number FROM public.journal_entries WHERE id=v_je) <> p_expected->>'entry_number' THEN RAISE EXCEPTION 'Unexpected journal'; END IF;
  SELECT transaction_currency INTO v_je_ccy FROM public.journal_entries WHERE id=v_je;
  IF v_je_ccy IS NOT NULL AND v_acct_ccy IS NOT NULL AND v_je_ccy <> v_acct_ccy THEN RAISE EXCEPTION 'Currency mismatch'; END IF;
  PERFORM 1 FROM public.journal_entry_lines WHERE journal_entry_id=v_je FOR UPDATE;
  PERFORM 1 FROM public.bank_statement_allocations WHERE bank_statement_line_id=p_bank_statement_line_id FOR UPDATE;
  SELECT COALESCE(sum(debit),0), COALESCE(sum(credit),0) INTO v_bank_gl_debit, v_bank_gl_credit FROM public.journal_entry_lines WHERE journal_entry_id=v_je AND account_id=v_bank_coa;
  IF v_is_debit THEN
    IF abs(v_bank_gl_credit-v_bank_amount)>0.01 OR v_bank_gl_debit>0.01 THEN RAISE EXCEPTION 'Journal bank movement does not match bank statement'; END IF;
  ELSE
    IF abs(v_bank_gl_debit-v_bank_amount)>0.01 OR v_bank_gl_credit>0.01 THEN RAISE EXCEPTION 'Journal bank movement does not match bank statement'; END IF;
  END IF;
  SELECT abs(total_debit-total_credit)<0.01 INTO v_je_balanced FROM public.journal_entries WHERE id=v_je;
  IF NOT COALESCE(v_je_balanced,false) THEN RAISE EXCEPTION 'Journal is not balanced'; END IF;
  SELECT jsonb_build_object('journal_id',je.id,'entry_number',je.entry_number,'total_debit',je.total_debit,'total_credit',je.total_credit,'line_count',(SELECT count(*) FROM public.journal_entry_lines l WHERE l.journal_entry_id=je.id),'allocations',(SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') FROM public.bank_statement_allocations a WHERE a.journal_entry_id=je.id)) INTO v_before FROM public.journal_entries je WHERE je.id=v_je;
  v_je_before:=v_before;
  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE bank_statement_line_id=p_bank_statement_line_id AND document_type=p_document_type AND document_id=p_document_id AND payment_kind=p_payment_kind) THEN RAISE EXCEPTION 'Duplicate cash event'; END IF;
  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE journal_entry_id=v_je) THEN RAISE EXCEPTION 'Duplicate cash event'; END IF;
  INSERT INTO public.bank_statement_allocations(bank_statement_line_id,document_type,document_id,journal_entry_id,allocation_amount,payment_kind,created_by)
  VALUES(p_bank_statement_line_id,p_document_type,p_document_id,v_je,round(p_allocation_amount,2),p_payment_kind,auth.uid()) RETURNING * INTO v_alloc;
  SELECT jsonb_build_object('journal_id',je.id,'entry_number',je.entry_number,'total_debit',je.total_debit,'total_credit',je.total_credit,'line_count',(SELECT count(*) FROM public.journal_entry_lines l WHERE l.journal_entry_id=je.id),'allocation_id',v_alloc.id,'allocation_amount',v_alloc.allocation_amount) INTO v_after FROM public.journal_entries je WHERE je.id=v_je;
  IF v_after->>'journal_id'<>v_je_before->>'journal_id' OR v_after->>'total_debit'<>v_je_before->>'total_debit' OR v_after->>'total_credit'<>v_je_before->>'total_credit' OR v_after->>'line_count'<>v_je_before->>'line_count' THEN RAISE EXCEPTION 'Unexpected journal change'; END IF;
  UPDATE public.finance_historical_repair_commands SET before_state=v_before, after_state=v_after, created_allocation_id=v_alloc.id WHERE id=v_cmd;
  RETURN jsonb_build_object('idempotent',false,'command_id',v_cmd,'allocation_id',v_alloc.id,'before',v_before,'after',v_after);
END;
$$;


--
-- Name: FUNCTION "execute_historical_finance_repair"("p_idempotency_key" "text", "p_document_type" "text", "p_document_id" "uuid", "p_bank_statement_line_id" "uuid", "p_allocation_amount" numeric, "p_expected" "jsonb", "p_payment_kind" "text", "p_operation" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."execute_historical_finance_repair"("p_idempotency_key" "text", "p_document_type" "text", "p_document_id" "uuid", "p_bank_statement_line_id" "uuid", "p_allocation_amount" numeric, "p_expected" "jsonb", "p_payment_kind" "text", "p_operation" "text") IS 'Privileged, transaction-scoped, idempotent historical allocation or explicit cash correction. Existing recognition journals are immutable; no ordinary document sync path is called.';


--
-- Name: expense_explicit_replacement_journals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."expense_explicit_replacement_journals"() RETURNS TABLE("expense_id" "uuid", "journal_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  SELECT DISTINCT i.document_id, je.id
    FROM public.finance_historical_repair_items i
    JOIN public.journal_entries je
      ON je.id = CASE
        WHEN COALESCE(i.new_metadata ->> 'replacement_journal_id', '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        THEN (i.new_metadata ->> 'replacement_journal_id')::uuid
      END
   WHERE i.document_type IN ('expense', 'salary_advance_expense')
     AND COALESCE(i.new_metadata ->> 'replacement_journal_id', '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     AND je.source_module NOT IN ('expense', 'expenses')

  UNION

  SELECT fe.id, cash_restatement.id
    FROM public.finance_expenses fe
    JOIN public.journal_entries cash_restatement
      ON cash_restatement.reference_id = fe.id
     AND cash_restatement.source_module = 'historical_repair'
     AND cash_restatement.reference_number LIKE 'HR-CASH-%'
     AND cash_restatement.is_posted = true
     AND NOT COALESCE(cash_restatement.is_reversed, false)
   WHERE EXISTS (
     SELECT 1
       FROM public.journal_entries original
      WHERE original.source_module IN ('expense', 'expenses')
        AND original.is_posted = true
        AND COALESCE(original.is_reversed, false)
        AND (original.reference_id = fe.id
          OR (original.reference_id IS NULL
            AND original.reference_number = 'EXP-' || fe.id::text))
   );
$_$;


--
-- Name: expense_recognition_has_direct_bank_settlement("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."expense_recognition_has_direct_bank_settlement"("p_expense_id" "uuid", "p_recognition_journal_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM journal_entry_lines l
      JOIN bank_accounts ba ON ba.coa_id=l.account_id
     WHERE l.journal_entry_id=p_recognition_journal_id
       AND l.credit>0
       AND EXISTS (
         SELECT 1 FROM journal_entries j
          WHERE j.id=p_recognition_journal_id
            AND j.reference_id=p_expense_id
            AND j.source_module IN ('expense','expenses')
            AND j.is_posted AND NOT COALESCE(j.is_reversed,false)
       )
  );
$$;


--
-- Name: FUNCTION "expense_recognition_has_direct_bank_settlement"("p_expense_id" "uuid", "p_recognition_journal_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."expense_recognition_has_direct_bank_settlement"("p_expense_id" "uuid", "p_recognition_journal_id" "uuid") IS 'Detects legacy expense recognition journals that already credit a bank account; used to prevent duplicate settlement postings.';


--
-- Name: finance_bank_match_text_score("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."finance_bank_match_text_score"("p_bank_text" "text", "p_document_text" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  SELECT count(*)::integer
  FROM (
    SELECT DISTINCT token
    FROM unnest(tsvector_to_array(to_tsvector('simple', lower(COALESCE(p_document_text, ''))))) AS token
    WHERE length(token) >= 4
      AND token !~ '^[0-9]+$'
      AND token NOT IN (
        'bank', 'transfer', 'payment', 'paid', 'expense', 'expenses',
        'invoice', 'general', 'admin', 'amount', 'charge', 'charges'
      )
  ) document_tokens
  WHERE token = ANY (
    tsvector_to_array(to_tsvector('simple', lower(COALESCE(p_bank_text, ''))))
  );
$_$;


--
-- Name: finance_staff_master_sync_salary_gl(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."finance_staff_master_sync_salary_gl"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_coa public.chart_of_accounts%rowtype;
BEGIN
  IF NEW.default_gl_account_id IS NULL THEN
    SELECT * INTO v_coa FROM public.chart_of_accounts
     WHERE code = '6100' AND is_active AND NOT is_header LIMIT 1;
    IF NOT FOUND THEN RAISE EXCEPTION 'Canonical salary COA 6100 is missing or inactive'; END IF;
    NEW.default_gl_account_id := v_coa.id;
  ELSE
    SELECT * INTO v_coa FROM public.chart_of_accounts WHERE id = NEW.default_gl_account_id;
    IF NOT FOUND OR NOT v_coa.is_active OR v_coa.is_header OR lower(v_coa.account_type) <> 'expense' THEN
      RAISE EXCEPTION 'Staff salary GL must reference an active posting expense Chart of Account';
    END IF;
  END IF;
  NEW.default_gl_code := v_coa.code;
  NEW.default_gl_name := v_coa.name;
  RETURN NEW;
END $$;


--
-- Name: fn_auto_delete_import_requirements_on_cancel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_auto_delete_import_requirements_on_cancel"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
-- Delete import requirements if SO is cancelled or rejected
IF NEW.status IN ('cancelled', 'rejected') AND OLD.status NOT IN ('cancelled', 'rejected') THEN
DELETE FROM import_requirements
WHERE sales_order_id = NEW.id;
END IF;

RETURN NEW;
END;
$$;


--
-- Name: fn_auto_release_on_so_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_auto_release_on_so_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
IF NEW.status IN ('cancelled', 'rejected', 'delivered', 'closed')
AND OLD.status NOT IN ('cancelled', 'rejected', 'delivered', 'closed') THEN
PERFORM fn_release_reservation_by_so_id(NEW.id, NULL);
END IF;
RETURN NEW;
END;
$$;


--
-- Name: fn_auto_rereserve_on_batch_arrival(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_auto_rereserve_on_batch_arrival"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_so_id uuid;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.current_stock IS NOT DISTINCT FROM OLD.current_stock
       AND NEW.is_active IS NOT DISTINCT FROM OLD.is_active THEN
      RETURN NEW;
    END IF;
  END IF;

  -- When positive stock is added or a new active batch arrives with stock
  IF (TG_OP = 'INSERT' AND NEW.is_active AND NEW.current_stock > 0)
     OR (TG_OP = 'UPDATE' AND NEW.is_active AND NEW.current_stock > COALESCE(OLD.current_stock, 0)) THEN

    PERFORM set_config('app.canonical_reservation_engine', 'on', true);

    FOR v_so_id IN
      SELECT DISTINCT so.id
      FROM public.sales_orders so
      JOIN public.sales_order_items soi ON soi.sales_order_id = so.id
      WHERE soi.product_id = NEW.product_id
        AND so.status::text = 'shortage'
        AND NOT COALESCE(so.is_archived, false)
      ORDER BY so.id
    LOOP
      PERFORM public.approve_sales_order_product_reservation_v2(v_so_id, NULL);
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_calculate_import_priority("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_calculate_import_priority"("p_delivery_date" "date") RETURNS "public"."import_priority"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_days_until_delivery integer;
BEGIN
v_days_until_delivery := p_delivery_date - CURRENT_DATE;

IF v_days_until_delivery < 7 THEN
RETURN 'high'::import_priority;
ELSIF v_days_until_delivery <= 30 THEN
RETURN 'medium'::import_priority;
ELSE
RETURN 'low'::import_priority;
END IF;
END;
$$;


--
-- Name: fn_cancel_delivery_challan("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_cancel_delivery_challan"("p_dc_id" "uuid", "p_user" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  SELECT role INTO v_role FROM profiles WHERE id = COALESCE(auth.uid(), p_user);
  IF v_role IS NULL OR v_role NOT IN ('admin','accounts','warehouse','manager') THEN
    RAISE EXCEPTION 'Not authorized to cancel delivery challans';
  END IF;

  UPDATE delivery_challans
     SET approval_status   = 'cancelled',
         rejection_reason  = COALESCE(p_reason, rejection_reason),
         rejected_by       = COALESCE(p_user, auth.uid()),
         rejected_at       = now(),
         updated_at        = now()
   WHERE id = p_dc_id;
END;
$$;


--
-- Name: fn_cancel_sales_order("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_cancel_sales_order"("p_so_id" "uuid", "p_canceller_id" "uuid", "p_reason" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_status text;
BEGIN
  SELECT role INTO v_role
  FROM public.user_profiles
  WHERE id = auth.uid();

  IF v_role NOT IN ('admin', 'accounts', 'sales', 'manager') THEN
    RAISE EXCEPTION
      'Permission denied: role % cannot cancel sales orders', v_role;
  END IF;

  SELECT status::text INTO v_status
  FROM public.sales_orders
  WHERE id = p_so_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales Order not found';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.delivery_challans dc
    WHERE dc.sales_order_id = p_so_id
      AND dc.approval_status = 'approved'
  ) THEN
    RAISE EXCEPTION
      'Sales Order has an approved Delivery Challan; reverse/cancel the Delivery Challan before cancelling the order';
  END IF;

  DELETE FROM public.import_requirements
  WHERE sales_order_id = p_so_id;

  PERFORM public.fn_release_stock_reservations(
    p_so_id,
    'SO cancelled: ' || p_reason,
    p_canceller_id
  );

  UPDATE public.sales_orders
  SET status = 'cancelled',
      updated_at = now()
  WHERE id = p_so_id;

  RETURN true;
END;
$$;


--
-- Name: fn_check_product_availability("uuid", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_check_product_availability"("p_product_id" "uuid", "p_required_qty" numeric) RETURNS TABLE("batch_id" "uuid", "batch_number" "text", "expiry_date" "date", "free_stock" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT 
b.id,
b.batch_number,
b.expiry_date,
fn_get_free_stock(b.id) as free_stock
FROM batches b
WHERE b.product_id = p_product_id
AND b.current_stock > 0
AND fn_get_free_stock(b.id) > 0
ORDER BY b.expiry_date ASC, b.created_at ASC;
END;
$$;


--
-- Name: fn_close_pending_import_requirements_on_reservation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_close_pending_import_requirements_on_reservation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.status::text = 'shortage'
     AND NEW.status::text = 'stock_reserved' THEN
    UPDATE public.import_requirements ir
    SET status = 'cancelled',
        notes = COALESCE(ir.notes || ' | ', '') ||
          'Auto-cancelled: shortage resolved by stock reservation ' ||
          to_char(now(), 'YYYY-MM-DD'),
        updated_at = now()
    WHERE ir.sales_order_id = NEW.id
      AND ir.status::text = 'pending';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_create_import_requirements("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_create_import_requirements"("p_so_id" "uuid", "p_shortage_items" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_shortage      RECORD;
  v_customer_id   UUID;
  v_delivery_date DATE;
  v_priority      import_priority;
  v_existing_id   UUID;
BEGIN
  -- Get SO details
  SELECT customer_id, expected_delivery_date
  INTO v_customer_id, v_delivery_date
  FROM sales_orders
  WHERE id = p_so_id;

  -- Default delivery date if not set
  IF v_delivery_date IS NULL THEN
    v_delivery_date := CURRENT_DATE + INTERVAL '30 days';
  END IF;

  -- Calculate priority from delivery date
  v_priority := fn_calculate_import_priority(v_delivery_date);

  -- ── Step 0: Cancel requirements for products NO LONGER in this SO ────────
  -- This handles the product-change scenario (e.g. USP → EP):
  --   old product's requirement becomes orphaned → cancel it.
  -- Status check: only cancel active-phase requirements (not already cancelled/received).
  UPDATE import_requirements
  SET
    status = 'cancelled',
    notes  = COALESCE(notes || ' | ', '') || 'Product removed from SO on re-reservation ' || to_char(now(), 'YYYY-MM-DD')
  WHERE sales_order_id = p_so_id
    AND status NOT IN ('cancelled', 'received')
    AND product_id NOT IN (
      SELECT DISTINCT soi.product_id
      FROM sales_order_items soi
      WHERE soi.sales_order_id = p_so_id
    );

  -- ── Step 1: Upsert shortage requirements ─────────────────────────────────
  FOR v_shortage IN
    SELECT
      (item->>'product_id')::UUID  AS product_id,
      (item->>'required_qty')::NUMERIC AS required_qty,
      (item->>'shortage_qty')::NUMERIC AS shortage_qty
    FROM jsonb_array_elements(p_shortage_items) AS item
  LOOP
    -- Check for existing active requirement for this SO + product
    SELECT id INTO v_existing_id
    FROM import_requirements
    WHERE sales_order_id = p_so_id
      AND product_id = v_shortage.product_id
      AND status NOT IN ('cancelled', 'received')
    LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
      -- Update existing requirement with latest shortage quantities
      UPDATE import_requirements
      SET
        shortage_quantity     = v_shortage.shortage_qty,
        required_quantity     = v_shortage.required_qty,
        priority              = v_priority,
        required_delivery_date = v_delivery_date,
        updated_at            = now()
      WHERE id = v_existing_id;
    ELSE
      -- Insert new requirement
      INSERT INTO import_requirements (
        product_id,
        sales_order_id,
        customer_id,
        required_quantity,
        shortage_quantity,
        required_delivery_date,
        priority,
        status,
        ordered_qty,
        allocated_qty,
        received_qty,
        notes
      ) VALUES (
        v_shortage.product_id,
        p_so_id,
        v_customer_id,
        v_shortage.required_qty,
        v_shortage.shortage_qty,
        v_delivery_date,
        v_priority,
        'pending',
        0,
        0,
        0,
        'Auto-generated from SO shortage'
      );
    END IF;
  END LOOP;

  RETURN TRUE;
END;
$$;


--
-- Name: fn_get_free_stock("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_get_free_stock"("p_batch_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_current_stock numeric;
v_reserved_qty numeric;
v_free_stock numeric;
BEGIN
-- Get current stock from batches
SELECT current_stock INTO v_current_stock
FROM batches
WHERE id = p_batch_id;

IF v_current_stock IS NULL THEN
RETURN 0;
END IF;

-- Get total active reservations
SELECT COALESCE(SUM(reserved_quantity), 0) INTO v_reserved_qty
FROM stock_reservations
WHERE batch_id = p_batch_id
AND status = 'active';

v_free_stock := v_current_stock - v_reserved_qty;

RETURN GREATEST(v_free_stock, 0);
END;
$$;


--
-- Name: fn_get_import_requirements_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_get_import_requirements_summary"() RETURNS TABLE("product_id" "uuid", "product_name" "text", "total_shortage" numeric, "pending_orders" integer, "highest_priority" "public"."import_priority", "earliest_delivery_date" "date")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT 
ir.product_id,
p.product_name,
SUM(ir.shortage_quantity) as total_shortage,
COUNT(DISTINCT ir.sales_order_id)::integer as pending_orders,
MIN(ir.priority) as highest_priority,
MIN(ir.required_delivery_date) as earliest_delivery_date
FROM import_requirements ir
JOIN products p ON p.id = ir.product_id
WHERE ir.status = 'pending'
GROUP BY ir.product_id, p.product_name
ORDER BY MIN(ir.priority), MIN(ir.required_delivery_date);
END;
$$;


--
-- Name: fn_period_payment_source(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_period_payment_source"("p_liability" numeric, "p_txp" numeric, "p_imp" numeric) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE
    WHEN COALESCE(p_liability, 0) <= 0.01 THEN 'none'
    WHEN LEAST(p_liability, COALESCE(p_txp,0) + COALESCE(p_imp,0)) < p_liability - 0.01 THEN
      CASE WHEN COALESCE(p_txp,0) > 0 OR COALESCE(p_imp,0) > 0 THEN 'partial' ELSE 'unpaid' END
    WHEN COALESCE(p_txp,0) > 0 AND COALESCE(p_imp,0) > 0 THEN 'both'
    WHEN COALESCE(p_imp,0) > 0                            THEN 'pib_expense'
    ELSE 'tax_payment'
  END;
$$;


--
-- Name: fn_period_payment_status("text", numeric, "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_period_payment_status"("p_status" "text", "p_outstanding" numeric, "p_due" "date") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE
    WHEN p_status IN ('closed', 'filed')            THEN p_status
    WHEN COALESCE(p_outstanding, 0) <= 0.01         THEN 'paid'
    WHEN p_due IS NOT NULL AND p_due < CURRENT_DATE  THEN 'overdue'
    ELSE 'payment_pending'
  END;
$$;


--
-- Name: fn_pph_authoritative_source_total("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_pph_authoritative_source_total"("p_period_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH period AS (
    SELECT id, fiscal_year, period_month, tax_type, period_start, period_end
      FROM public.tax_periods
     WHERE id = p_period_id
       AND tax_type <> 'PPN'
  )
  SELECT COALESCE((
    SELECT SUM(fe.pph_amount)
      FROM period p
      JOIN public.finance_expenses fe
        ON (fe.pph_tax_period_id = p.id
            OR (fe.pph_tax_period_id IS NULL
                AND COALESCE(fe.due_date, fe.expense_date) BETWEEN p.period_start AND p.period_end))
      JOIN public.effective_expense_posting_state eps
        ON eps.expense_id = fe.id
       AND eps.effective_posting_state IN ('ACTIVE', 'REPLACED')
      LEFT JOIN public.tax_codes tc ON tc.id = fe.pph_code_id
     WHERE fe.approval_status = 'approved'
       AND fe.pph_amount > 0
       AND COALESCE(fe.expense_category, '') NOT IN ('pib_import', 'pph_import')
       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)
  ), 0)
  + COALESCE((
    SELECT SUM(pv.pph_amount)
      FROM period p
      JOIN public.payment_vouchers pv
        ON (pv.tax_period_id = p.id
            OR (pv.tax_period_id IS NULL AND pv.voucher_date BETWEEN p.period_start AND p.period_end))
      LEFT JOIN public.tax_codes tc ON tc.id = pv.pph_code_id
     WHERE COALESCE(pv.is_posted, false)
       AND pv.pph_amount > 0
       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)
  ), 0)
  + COALESCE((
    SELECT SUM(CASE WHEN fe.expense_category = 'pib_import'
                    THEN COALESCE(fe.pib_pph_amount, 0)
                    ELSE COALESCE(fe.amount, 0) END)
      FROM period p
      JOIN public.finance_expenses fe
        ON (fe.pph_tax_period_id = p.id
            OR (fe.pph_tax_period_id IS NULL
                AND COALESCE(fe.due_date, fe.expense_date) BETWEEN p.period_start AND p.period_end))
      JOIN public.effective_expense_posting_state eps
        ON eps.expense_id = fe.id
       AND eps.effective_posting_state IN ('ACTIVE', 'REPLACED')
     WHERE p.tax_type IN ('PPh22', 'PPh_Unifikasi')
       AND fe.approval_status = 'approved'
       AND fe.expense_category IN ('pib_import', 'pph_import')
  ), 0);
$$;


--
-- Name: fn_pph_payable_account_id("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_pph_payable_account_id"("p_tax_code_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT coa.id
    FROM chart_of_accounts coa
   WHERE coa.code = CASE (
     SELECT tc.tax_type FROM tax_codes tc WHERE tc.id = p_tax_code_id
   )
     WHEN 'PPh21'   THEN '2131'
     WHEN 'PPh22'   THEN '2137'
     WHEN 'PPh23'   THEN '2132'
     WHEN 'PPh4(2)' THEN '2138'
     ELSE '2132'
   END
   LIMIT 1;
$$;


--
-- Name: fn_recompute_so_delivered("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_recompute_so_delivered"("p_so_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  BEGIN
    PERFORM public.fn_recompute_so_status(p_so_id);
  END;
  $$;


--
-- Name: fn_recompute_so_status("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_recompute_so_status"("p_so_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  DECLARE
    v_ordered numeric := 0;
    v_delivered numeric := 0;
    v_invoiced numeric := 0;
  BEGIN
    IF p_so_id IS NULL THEN
      RETURN;
    END IF;

    WITH approved_by_product AS (
      SELECT
        dci.product_id,
        COALESCE(SUM(dci.quantity), 0)::numeric AS delivered_qty
      FROM delivery_challans dc
      JOIN delivery_challan_items dci ON dci.challan_id = dc.id
      WHERE dc.sales_order_id = p_so_id
        AND dc.approval_status = 'approved'
      GROUP BY dci.product_id
    ),
    ordered_items AS (
      SELECT
        soi.id,
        soi.product_id,
        soi.quantity,
        COALESCE(abp.delivered_qty, 0) AS delivered_qty,
        COALESCE(
          SUM(soi.quantity) OVER (
            PARTITION BY soi.product_id
            ORDER BY soi.created_at, soi.id
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
          ),
          0
        ) AS prior_qty
      FROM sales_order_items soi
      LEFT JOIN approved_by_product abp ON abp.product_id = soi.product_id
      WHERE soi.sales_order_id = p_so_id
    ),
    allocated AS (
      SELECT
        id,
        CASE
          WHEN delivered_qty - prior_qty <= 0 THEN 0
          WHEN delivered_qty - prior_qty >= quantity THEN quantity
          ELSE delivered_qty - prior_qty
        END AS delivered_quantity
      FROM ordered_items
    )
    UPDATE sales_order_items soi
       SET delivered_quantity = allocated.delivered_quantity
      FROM allocated
     WHERE soi.id = allocated.id;

    SELECT COALESCE(SUM(quantity), 0)
      INTO v_ordered
      FROM sales_order_items
     WHERE sales_order_id = p_so_id;

    SELECT COALESCE(SUM(dci.quantity), 0)
      INTO v_delivered
      FROM delivery_challans dc
      JOIN delivery_challan_items dci ON dci.challan_id = dc.id
     WHERE dc.sales_order_id = p_so_id
       AND dc.approval_status = 'approved';

    SELECT COALESCE(SUM(x.quantity), 0)
      INTO v_invoiced
      FROM (
        SELECT DISTINCT
          sii.id,
          sii.quantity
        FROM sales_invoice_items sii
        JOIN sales_invoices si ON si.id = sii.invoice_id
        LEFT JOIN delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id
        LEFT JOIN delivery_challans dc ON dc.id = dci.challan_id
        WHERE COALESCE(si.is_draft, false) = false
          AND si.invoice_number NOT ILIKE 'TEST-COGS-%'
          AND COALESCE(si.sales_order_id, dc.sales_order_id) = p_so_id
      ) x;

    UPDATE sales_orders
       SET status = CASE
                      WHEN v_ordered > 0 AND v_delivered >= v_ordered AND v_invoiced >= v_ordered
                        THEN 'closed'::sales_order_status
                      WHEN v_ordered > 0 AND v_delivered >= v_ordered
                        THEN 'delivered'::sales_order_status
                      WHEN v_delivered > 0
                        THEN 'partially_delivered'::sales_order_status
                      ELSE status
                    END,
           updated_at = now()
     WHERE id = p_so_id
       AND status NOT IN ('closed', 'cancelled', 'rejected');
  END;
  $$;


--
-- Name: fn_reject_delivery_challan("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_reject_delivery_challan"("p_dc_id" "uuid", "p_rejector_id" "uuid", "p_reason" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts','warehouse','manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot reject delivery challans', v_role;
END IF;

UPDATE delivery_challans
SET approval_status = 'rejected', rejection_reason = p_reason
WHERE id = p_dc_id;
RETURN true;
END;
$$;


--
-- Name: fn_reject_sales_order("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_reject_sales_order"("p_so_id" "uuid", "p_rejector_id" "uuid", "p_reason" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts','manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot reject sales orders', v_role;
END IF;

PERFORM fn_release_stock_reservations(p_so_id, 'SO rejected: ' || p_reason);
UPDATE sales_orders
SET status = 'rejected', rejected_by = p_rejector_id, rejected_at = now(),
rejection_reason = p_reason, updated_at = now()
WHERE id = p_so_id;
RETURN true;
END;
$$;


--
-- Name: fn_release_partial_reservation("uuid", "uuid", numeric, "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_release_partial_reservation"("p_so_id" "uuid", "p_product_id" "uuid", "p_qty" numeric, "p_released_by" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reservation record;
  v_remaining_qty numeric := p_qty;
  v_release_qty numeric;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(
    ARRAY['admin', 'accounts', 'manager', 'warehouse']
  ) THEN
    RAISE EXCEPTION 'Permission denied for partial reservation release';
  END IF;
  IF COALESCE(p_qty, 0) <= 0 THEN
    RAISE EXCEPTION 'Reservation release quantity must be positive';
  END IF;

  FOR v_reservation IN
    SELECT id, reserved_quantity
    FROM public.stock_reservations
    WHERE sales_order_id = p_so_id
      AND product_id = p_product_id
      AND status = 'active'
    ORDER BY reserved_at, id
    FOR UPDATE
  LOOP
    EXIT WHEN v_remaining_qty <= 0;
    v_release_qty := LEAST(v_remaining_qty, v_reservation.reserved_quantity);

    IF v_release_qty = v_reservation.reserved_quantity THEN
      UPDATE public.stock_reservations
      SET status = 'released',
          is_released = true,
          released_at = now(),
          released_by = COALESCE(p_released_by, auth.uid()),
          release_reason = 'Canonical partial reservation release'
      WHERE id = v_reservation.id;
    ELSE
      UPDATE public.stock_reservations
      SET reserved_quantity = reserved_quantity - v_release_qty
      WHERE id = v_reservation.id;
    END IF;

    v_remaining_qty := v_remaining_qty - v_release_qty;
  END LOOP;

  IF v_remaining_qty > 0 THEN
    RAISE EXCEPTION 'Reservation release exceeds active reserved quantity by %',
      v_remaining_qty;
  END IF;

  RETURN true;
END;
$$;


--
-- Name: fn_release_reservation_by_so_id("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_release_reservation_by_so_id"("p_so_id" "uuid", "p_released_by" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.inventory_v1_actor_allowed(
    ARRAY['admin', 'accounts', 'manager', 'warehouse']
  ) THEN
    RAISE EXCEPTION 'Permission denied for reservation release';
  END IF;

  UPDATE public.stock_reservations
  SET status = 'released',
      is_released = true,
      released_at = now(),
      released_by = COALESCE(p_released_by, auth.uid()),
      release_reason = COALESCE(
        release_reason,
        'Canonical Sales Order reservation release'
      )
  WHERE sales_order_id = p_so_id
    AND status = 'active';

  RETURN true;
END;
$$;


--
-- Name: fn_release_stock_reservations("uuid", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_release_stock_reservations"("p_so_id" "uuid", "p_reason" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_so_number   text;
  v_actor       uuid := COALESCE(p_user_id, auth.uid());
BEGIN
  SELECT so_number INTO v_so_number FROM sales_orders WHERE id = p_so_id;

  -- Emit an inventory_transactions release row per active reservation so
  -- Reports / drill-downs can trace the release event to a source doc.
  FOR v_reservation IN
    SELECT * FROM stock_reservations
    WHERE sales_order_id = p_so_id
      AND status = 'active'
  LOOP
    INSERT INTO inventory_transactions (
      product_id,
      batch_id,
      transaction_type,
      quantity,
      transaction_date,
      reference_number,
      notes,
      created_by
    ) VALUES (
      v_reservation.product_id,
      v_reservation.batch_id,
      'release_reservation',
      v_reservation.reserved_quantity,
      CURRENT_DATE,
      v_so_number,
      'Reservation released: ' || p_reason,
      v_actor
    );
  END LOOP;

  UPDATE stock_reservations
  SET status         = 'released',
      released_at    = now(),
      released_by    = v_actor,
      release_reason = p_reason
  WHERE sales_order_id = p_so_id
    AND status = 'active';

  RETURN true;
END;
$$;


