--
-- Name: fn_restore_reservation_on_dc_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_restore_reservation_on_dc_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_so_status text;
BEGIN
IF OLD.sales_order_id IS NOT NULL THEN
SELECT status::text INTO v_so_status FROM sales_orders WHERE id = OLD.sales_order_id;
IF v_so_status NOT IN ('delivered','closed','cancelled','rejected') THEN
PERFORM fn_reserve_stock_for_so_v2(OLD.sales_order_id);
END IF;
END IF;
RETURN OLD;
END;
$$;


--
-- Name: fn_safe_autolink_dc_to_so(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_safe_autolink_dc_to_so"() RETURNS TABLE("dc_id" "uuid", "linked_so_id" "uuid", "action" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
dc_rec          RECORD;
candidate_so_id uuid;
match_count     int;
v_role          text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts','manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot auto-link challans', v_role;
END IF;

FOR dc_rec IN
SELECT dc.id, dc.customer_id FROM delivery_challans dc
WHERE dc.sales_order_id IS NULL
AND (dc.review_status IS NULL OR dc.review_status != 'needs_review')
LOOP
SELECT COUNT(DISTINCT so.id) INTO match_count
FROM sales_orders so
WHERE so.customer_id = dc_rec.customer_id AND so.is_archived = false
AND so.status NOT IN ('draft','cancelled','rejected')
AND NOT EXISTS (
SELECT 1 FROM delivery_challan_items dci
WHERE dci.challan_id = dc_rec.id
AND NOT EXISTS (
SELECT 1 FROM sales_order_items soi
WHERE soi.sales_order_id = so.id AND soi.product_id = dci.product_id
AND soi.quantity >= dci.quantity
)
)
AND EXISTS (SELECT 1 FROM delivery_challan_items dci2 WHERE dci2.challan_id = dc_rec.id);

IF match_count = 1 THEN
SELECT so.id INTO candidate_so_id
FROM sales_orders so
WHERE so.customer_id = dc_rec.customer_id AND so.is_archived = false
AND so.status NOT IN ('draft','cancelled','rejected')
AND NOT EXISTS (
SELECT 1 FROM delivery_challan_items dci
WHERE dci.challan_id = dc_rec.id
AND NOT EXISTS (
SELECT 1 FROM sales_order_items soi
WHERE soi.sales_order_id = so.id AND soi.product_id = dci.product_id
AND soi.quantity >= dci.quantity
)
)
AND EXISTS (SELECT 1 FROM delivery_challan_items dci2 WHERE dci2.challan_id = dc_rec.id)
LIMIT 1;

UPDATE delivery_challans SET sales_order_id = candidate_so_id, updated_at = now()
WHERE id = dc_rec.id;
dc_id := dc_rec.id; linked_so_id := candidate_so_id; action := 'linked';
RETURN NEXT;
ELSE
UPDATE delivery_challans SET review_status = 'needs_review', updated_at = now()
WHERE id = dc_rec.id AND sales_order_id IS NULL;
dc_id := dc_rec.id; linked_so_id := NULL; action := 'needs_review';
RETURN NEXT;
END IF;
END LOOP;
END;
$$;


--
-- Name: fn_settled_import_pph22(integer, integer, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_settled_import_pph22"("p_year" integer, "p_month" integer, "p_tax_type" "text") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE WHEN p_tax_type IN ('PPh22', 'PPh_Unifikasi') THEN COALESCE((
    SELECT SUM(
      CASE WHEN fe.expense_category = 'pib_import' THEN COALESCE(fe.pib_pph_amount, 0)
           ELSE COALESCE(fe.amount, 0)          -- pph_import: whole amount is the tax
      END)
      FROM finance_expenses fe
     WHERE fe.expense_category IN ('pib_import', 'pph_import')
       AND EXTRACT(YEAR  FROM fe.expense_date)::int = p_year
       AND EXTRACT(MONTH FROM fe.expense_date)::int = p_month
       AND (COALESCE(fe.amount,0) - COALESCE(fe.paid_amount, 0)) <= 0.01   -- fully paid
       AND EXISTS (                                                        -- bank-reconciled
         SELECT 1 FROM bank_statement_lines bsl
          WHERE bsl.matched_expense_id = fe.id
            AND bsl.reconciliation_status IN ('matched', 'recorded'))
  ), 0) ELSE 0 END;
$$;


--
-- Name: fn_sync_import_requirements_on_so_edit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_sync_import_requirements_on_so_edit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- A draft/pending-approval SO is being edited by the application.  Its
  -- replacement lines are inserted immediately after this DELETE, so do not
  -- mutate procurement state in the middle of that replacement transaction.
  IF EXISTS (
    SELECT 1
    FROM public.sales_orders so
    WHERE so.id = OLD.sales_order_id
      AND so.status::text IN ('draft', 'pending_approval')
  ) THEN
    RETURN OLD;
  END IF;

  -- For a genuine line removal, cancel only when no line for that product
  -- remains on the SO.  This also handles duplicate lines safely.
  UPDATE public.import_requirements ir
  SET status = 'cancelled',
      notes = COALESCE(ir.notes || ' | ', '') ||
        'Product removed from SO ' || to_char(now(), 'YYYY-MM-DD')
  WHERE ir.sales_order_id = OLD.sales_order_id
    AND ir.product_id = OLD.product_id
    AND ir.status::text NOT IN ('cancelled', 'received')
    AND NOT EXISTS (
      SELECT 1
      FROM public.sales_order_items soi
      WHERE soi.sales_order_id = OLD.sales_order_id
        AND soi.product_id = OLD.product_id
    );

  RETURN OLD;
END;
$$;


