--
-- Name: fn_tax_period_payment_status("text", numeric, numeric, "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_tax_period_payment_status"("p_status" "text", "p_total" numeric, "p_paid" numeric, "p_due" "date") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
SELECT CASE WHEN coalesce(p_paid,0)>coalesce(p_total,0)+.01 THEN 'overpaid' WHEN coalesce(p_total,0)>.01 AND coalesce(p_paid,0)>=coalesce(p_total,0)-.01 THEN 'paid' WHEN coalesce(p_paid,0)>.01 THEN 'partial' ELSE 'open' END;
$$;


--
-- Name: generate_bank_transaction_hash("uuid", "date", numeric, numeric, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_bank_transaction_hash"("p_bank_account_id" "uuid", "p_transaction_date" "date", "p_debit_amount" numeric, "p_credit_amount" numeric, "p_description" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_normalized_desc TEXT;
v_hash_input TEXT;
BEGIN
-- Normalize description: lowercase, remove extra spaces, trim to 100 chars
v_normalized_desc := LOWER(TRIM(REGEXP_REPLACE(COALESCE(p_description, ''), '\s+', ' ', 'g')));
v_normalized_desc := LEFT(v_normalized_desc, 100);

-- Create hash input string
v_hash_input := p_bank_account_id::TEXT || '|' ||
p_transaction_date::TEXT || '|' ||
COALESCE(p_debit_amount, 0)::TEXT || '|' ||
COALESCE(p_credit_amount, 0)::TEXT || '|' ||
v_normalized_desc;

-- Return MD5 hash
RETURN md5(v_hash_input);
END;
$$;


--
-- Name: generate_bank_transaction_hash("uuid", "date", numeric, numeric, "text", numeric, "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_bank_transaction_hash"("p_bank_account_id" "uuid", "p_transaction_date" "date", "p_debit_amount" numeric, "p_credit_amount" numeric, "p_description" "text", "p_running_balance" numeric DEFAULT 0, "p_upload_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
v_normalized_desc TEXT;
v_hash_input TEXT;
BEGIN
v_normalized_desc := LOWER(TRIM(REGEXP_REPLACE(COALESCE(p_description, ''), '\s+', ' ', 'g')));
v_normalized_desc := LEFT(v_normalized_desc, 100);

v_hash_input := p_bank_account_id::TEXT || '|' ||
p_transaction_date::TEXT || '|' ||
COALESCE(p_debit_amount, 0)::TEXT || '|' ||
COALESCE(p_credit_amount, 0)::TEXT || '|' ||
v_normalized_desc || '|' ||
COALESCE(p_running_balance, 0)::TEXT;

-- If balance is 0 (not provided) and upload_id is given, use it to distinguish entries
IF COALESCE(p_running_balance, 0) = 0 AND p_upload_id IS NOT NULL THEN
v_hash_input := v_hash_input || '|' || p_upload_id::TEXT;
END IF;

RETURN md5(v_hash_input);
END;
$$;


