--
-- Name: generate_rejection_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_rejection_number"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
next_num integer;
year_suffix text;
BEGIN
year_suffix := TO_CHAR(CURRENT_DATE, 'YY');

SELECT COALESCE(MAX(
CASE 
WHEN rejection_number ~ '^REJ-[0-9]+-[0-9]+$' 
THEN CAST(split_part(rejection_number, '-', 2) AS integer)
ELSE 0
END
), 0) + 1 INTO next_num
FROM stock_rejections
WHERE rejection_number LIKE 'REJ-%';

RETURN 'REJ-' || LPAD(next_num::text, 5, '0') || '-' || year_suffix;
END;
$_$;


--
-- Name: generate_return_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_return_number"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
next_num integer;
year_suffix text;
BEGIN
year_suffix := TO_CHAR(CURRENT_DATE, 'YY');

SELECT COALESCE(MAX(
CASE 
WHEN return_number ~ '^RET-[0-9]+-[0-9]+$' 
THEN CAST(split_part(return_number, '-', 2) AS integer)
ELSE 0
END
), 0) + 1 INTO next_num
FROM material_returns
WHERE return_number LIKE 'RET-%';

RETURN 'RET-' || LPAD(next_num::text, 5, '0') || '-' || year_suffix;
END;
$_$;


--
-- Name: generate_so_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_so_number"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
next_number integer;
year_part text;
new_so_number text;
BEGIN
year_part := to_char(CURRENT_DATE, 'YYYY');

SELECT COALESCE(MAX(
CAST(
substring(so_number from 'SO-' || year_part || '-(.*)') AS integer
)
), 0) + 1
INTO next_number
FROM sales_orders
WHERE so_number LIKE 'SO-' || year_part || '-%';

new_so_number := 'SO-' || year_part || '-' || LPAD(next_number::text, 4, '0');

RETURN new_so_number;
END;
$$;


--
-- Name: generate_tax_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_tax_notifications"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user record;
  v_row record;
  v_count int := 0;
  v_today date := CURRENT_DATE;
  v_upcoming_cutoff date := CURRENT_DATE + 7;
BEGIN
  FOR v_user IN
    SELECT id FROM user_profiles
    WHERE is_active = true AND role IN ('admin','manager','accounts')
  LOOP
    -- Overdue tax payments
    FOR v_row IN
      SELECT tax_period_id, tax_type, payment_due_date, outstanding_amount
      FROM vw_outstanding_tax
      WHERE payment_due_date < v_today AND outstanding_amount > 0
    LOOP
      -- Insert directly: we're SECURITY DEFINER so RLS is bypassed. This
      -- also side-steps upsert_notification's "only admins may notify other
      -- users" rule which would fire when a manager triggers this RPC.
      INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)
      SELECT v_user.id, 'tax_overdue',
             v_row.tax_type || ' payment overdue',
             format('Rp %s outstanding, due %s',
               to_char(v_row.outstanding_amount, 'FM999G999G999G999D00'),
               to_char(v_row.payment_due_date, 'DD Mon YYYY')),
             v_row.tax_period_id, 'tax_period', false
      WHERE NOT EXISTS (
        SELECT 1 FROM notifications
        WHERE user_id = v_user.id
          AND type = 'tax_overdue'
          AND reference_id = v_row.tax_period_id
          AND is_read = false
      );
      v_count := v_count + 1;
    END LOOP;

    -- Upcoming tax payments (next 7 days)
    FOR v_row IN
      SELECT tax_period_id, tax_type, payment_due_date, outstanding_amount
      FROM vw_outstanding_tax
      WHERE payment_due_date BETWEEN v_today AND v_upcoming_cutoff
        AND outstanding_amount > 0
    LOOP
      INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)
      SELECT v_user.id, 'tax_due_soon',
             v_row.tax_type || ' payment due',
             format('Rp %s due on %s',
               to_char(v_row.outstanding_amount, 'FM999G999G999G999D00'),
               to_char(v_row.payment_due_date, 'DD Mon YYYY')),
             v_row.tax_period_id, 'tax_period', false
      WHERE NOT EXISTS (
        SELECT 1 FROM notifications
        WHERE user_id = v_user.id
          AND type = 'tax_due_soon'
          AND reference_id = v_row.tax_period_id
          AND is_read = false
      );
      v_count := v_count + 1;
    END LOOP;

    -- Missing Faktur Pajak on open PPN periods
    FOR v_row IN
      SELECT id AS tax_period_id, fiscal_year, period_month, missing_faktur_count
      FROM vw_tax_period_status
      WHERE tax_type = 'PPN' AND status <> 'closed' AND missing_faktur_count > 0
    LOOP
      INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)
      SELECT v_user.id, 'faktur_missing',
             'Waiting for Faktur',
             format('%s sales invoice(s) in %s-%s need a Faktur Pajak number',
               v_row.missing_faktur_count,
               v_row.fiscal_year,
               lpad(v_row.period_month::text, 2, '0')),
             v_row.tax_period_id, 'tax_period', false
      WHERE NOT EXISTS (
        SELECT 1 FROM notifications
        WHERE user_id = v_user.id
          AND type = 'faktur_missing'
          AND reference_id = v_row.tax_period_id
          AND is_read = false
      );
      v_count := v_count + 1;
    END LOOP;
  END LOOP;

  RETURN v_count;
END $$;


--
-- Name: generate_voucher_number("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_voucher_number"("p_prefix" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
v_year TEXT;
v_month TEXT;
v_max_num INTEGER;
v_number TEXT;
v_like_prefix TEXT;
v_lock_id BIGINT;
BEGIN
v_year := TO_CHAR(CURRENT_DATE, 'YY');
v_month := TO_CHAR(CURRENT_DATE, 'MM');
v_like_prefix := p_prefix || v_year || v_month;

v_lock_id := hashtext('voucher_' || v_like_prefix);
PERFORM pg_advisory_xact_lock(v_lock_id);

IF p_prefix = 'RV' THEN
SELECT COALESCE(MAX(
CAST(NULLIF(SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2), '') AS INTEGER)
), 0) + 1
INTO v_max_num
FROM receipt_vouchers
WHERE voucher_number LIKE v_like_prefix || '-%'
AND SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2) ~ '^\d+$';
ELSIF p_prefix = 'PV' THEN
SELECT COALESCE(MAX(
CAST(NULLIF(SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2), '') AS INTEGER)
), 0) + 1
INTO v_max_num
FROM payment_vouchers
WHERE voucher_number LIKE v_like_prefix || '-%'
AND SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2) ~ '^\d+$';
ELSIF p_prefix = 'PC' THEN
SELECT COALESCE(MAX(
CAST(NULLIF(SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2), '') AS INTEGER)
), 0) + 1
INTO v_max_num
FROM petty_cash_vouchers
WHERE voucher_number LIKE v_like_prefix || '-%'
AND SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2) ~ '^\d+$';
ELSE
v_max_num := 1;
END IF;

v_number := v_like_prefix || '-' || LPAD(v_max_num::TEXT, 4, '0');

RETURN v_number;
END;
$_$;


--
-- Name: get_accounts_dashboard_data("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_accounts_dashboard_data"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN jsonb_build_object(
'bank_balance', (
SELECT COALESCE(SUM(current_balance), 0)
FROM bank_accounts
WHERE is_active = true
),
'pending_receivables', (
SELECT COALESCE(SUM(si.total_amount - COALESCE(
(SELECT SUM(ipa.allocated_amount) 
FROM invoice_payment_allocations ipa 
WHERE ipa.invoice_id = si.id), 0
)), 0)
FROM sales_invoices si
WHERE si.payment_status IN ('pending', 'partial')
),
'pending_payables', (
SELECT COALESCE(SUM(balance_amount), 0)
FROM purchase_invoices
WHERE balance_amount > 0
),
'unreconciled_transactions', (
SELECT COUNT(*)
FROM bank_statement_lines
WHERE reconciliation_status = 'unmatched'
),
'overdue_invoices_count', (
SELECT COUNT(*)
FROM sales_invoices
WHERE payment_status IN ('pending', 'partial')
AND due_date < CURRENT_DATE
),
'overdue_invoices_amount', (
SELECT COALESCE(SUM(si.total_amount - COALESCE(
(SELECT SUM(ipa.allocated_amount) 
FROM invoice_payment_allocations ipa 
WHERE ipa.invoice_id = si.id), 0
)), 0)
FROM sales_invoices si
WHERE si.payment_status IN ('pending', 'partial')
AND si.due_date < CURRENT_DATE
),
'cash_position', COALESCE(get_petty_cash_balance(), 0),
'staff_advances_pending', 0,
'pending_approvals', 0
);
END;
$$;


--
-- Name: get_admin_dashboard_data("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_admin_dashboard_data"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_result jsonb;
v_sales_snapshot jsonb;
v_finance_snapshot jsonb;
v_stock_snapshot jsonb;
v_alerts_summary jsonb;
v_pending_approvals jsonb;
v_system_health jsonb;
v_crm_snapshot jsonb;
BEGIN
-- Sales snapshot
SELECT jsonb_build_object(
'today_revenue', COALESCE(SUM(total_amount), 0),
'today_count', COUNT(*),
'month_revenue', (
SELECT COALESCE(SUM(total_amount), 0)
FROM sales_invoices
WHERE DATE_TRUNC('month', invoice_date) = DATE_TRUNC('month', CURRENT_DATE)
),
'pending_orders', (
SELECT COUNT(*) FROM sales_orders WHERE status = 'pending_approval'
)
) INTO v_sales_snapshot
FROM sales_invoices
WHERE DATE(invoice_date) = CURRENT_DATE;

-- Finance snapshot
SELECT jsonb_build_object(
'bank_balance', (
SELECT COALESCE(SUM(current_balance), 0)
FROM bank_accounts
WHERE is_active = true
),
'receivables', (
SELECT COALESCE(SUM(si.total_amount - COALESCE(
(SELECT SUM(ipa.allocated_amount) 
FROM invoice_payment_allocations ipa 
WHERE ipa.sales_invoice_id = si.id), 0
)), 0)
FROM sales_invoices si
WHERE si.payment_status IN ('pending', 'partial')
),
'payables', (
SELECT COALESCE(SUM(total_amount), 0)
FROM purchase_invoices
WHERE payment_status IN ('pending', 'partial')
),
'overdue_invoices', (
SELECT COUNT(*)
FROM sales_invoices
WHERE payment_status IN ('pending', 'partial')
AND due_date < CURRENT_DATE
)
) INTO v_finance_snapshot;

-- Stock snapshot
SELECT jsonb_build_object(
'total_products', (
SELECT COUNT(*) FROM products WHERE is_active = true
),
'low_stock', (
SELECT COUNT(*)
FROM products
WHERE is_active = true
AND min_stock_level > 0
AND current_stock < min_stock_level
),
'near_expiry', (
SELECT COUNT(*)
FROM batches
WHERE is_active = true
AND current_stock > 0
AND expiry_date BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '30 days')
),
'inventory_value', (
SELECT COALESCE(SUM(b.current_stock * b.unit_price), 0)
FROM batches b
WHERE b.is_active = true AND b.current_stock > 0
)
) INTO v_stock_snapshot;

-- Alerts summary
SELECT jsonb_build_object(
'critical', (
SELECT COUNT(*)
FROM products
WHERE is_active = true
AND current_stock <= 0
) + (
SELECT COUNT(*)
FROM sales_invoices
WHERE payment_status IN ('pending', 'partial')
AND due_date < CURRENT_DATE - INTERVAL '30 days'
),
'warning', (
SELECT COUNT(*)
FROM products
WHERE is_active = true
AND min_stock_level > 0
AND current_stock < min_stock_level
),
'info', (
SELECT COUNT(*)
FROM crm_activities
WHERE is_completed = false
AND follow_up_date = CURRENT_DATE
)
) INTO v_alerts_summary;

-- Pending approvals
SELECT jsonb_build_object(
'sales_orders', (
SELECT COUNT(*) FROM sales_orders WHERE status = 'pending_approval'
),
'delivery_challans', (
SELECT COUNT(*) FROM delivery_challans WHERE approval_status = 'pending_approval'
),
'credit_notes', (
SELECT COUNT(*) FROM credit_notes WHERE approval_status = 'pending'
),
'material_returns', (
SELECT COUNT(*) FROM material_returns WHERE approval_status = 'pending'
)
) INTO v_pending_approvals;

-- System health
SELECT jsonb_build_object(
'active_users', (
SELECT COUNT(*) FROM user_profiles WHERE is_active = true
),
'active_customers', (
SELECT COUNT(*) FROM customers WHERE is_active = true
),
'active_products', (
SELECT COUNT(*) FROM products WHERE is_active = true
),
'unread_notifications', (
SELECT COUNT(*)
FROM notifications
WHERE user_id = p_user_id
AND is_read = false
)
) INTO v_system_health;

-- CRM snapshot
SELECT jsonb_build_object(
'upcoming_reminders', (
SELECT COUNT(*)
FROM crm_reminders
WHERE is_completed = false
AND due_date BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '7 days')
),
'todays_appointments', (
SELECT COUNT(*)
FROM crm_reminders
WHERE is_completed = false
AND DATE(due_date) = CURRENT_DATE
AND reminder_type = 'follow_up'
),
'active_inquiries', (
SELECT COUNT(*)
FROM crm_inquiries
WHERE status NOT IN ('closed', 'lost', 'converted')
),
'hot_leads', (
SELECT COUNT(*)
FROM crm_inquiries
WHERE temperature = 'Hot'
AND status NOT IN ('closed', 'lost', 'converted')
)
) INTO v_crm_snapshot;

-- Build result JSON
v_result := jsonb_build_object(
'sales_snapshot', v_sales_snapshot,
'finance_snapshot', v_finance_snapshot,
'stock_snapshot', v_stock_snapshot,
'alerts_summary', v_alerts_summary,
'pending_approvals', v_pending_approvals,
'system_health', v_system_health,
'crm_snapshot', v_crm_snapshot
);

RETURN v_result;
END;
$$;


--
-- Name: get_asset_register(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_asset_register"() RETURNS TABLE("id" "uuid", "supplier_id" "uuid", "supplier_name" "text", "invoice_number" "text", "purchase_date" "date", "asset_account" "text", "asset_account_code" "text", "cost" numeric, "description" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  RETURN QUERY
  SELECT
    fe.id,
    fe.supplier_id,
    s.company_name::TEXT        AS supplier_name,
    fe.invoice_number::TEXT,
    fe.expense_date             AS purchase_date,
    coa.name::TEXT              AS asset_account,
    coa.code::TEXT              AS asset_account_code,
    fe.amount                   AS cost,
    fe.description::TEXT
  FROM public.finance_expenses fe
  LEFT JOIN public.suppliers s          ON s.id   = fe.supplier_id
  LEFT JOIN public.chart_of_accounts coa ON coa.id = fe.fixed_asset_account_id
  WHERE fe.expense_category = 'fixed_asset'
  ORDER BY fe.expense_date DESC;
END;
$$;


--
-- Name: get_balance_sheet("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_balance_sheet"("p_as_of_date" "date") RETURNS TABLE("code" character varying, "name" character varying, "name_id" character varying, "account_type" character varying, "account_group" character varying, "normal_balance" character varying, "total_debit" numeric, "total_credit" numeric, "balance" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT *
  FROM public.get_balance_sheet(p_as_of_date, 1::numeric);
END;
$$;


--
-- Name: get_balance_sheet("date", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_balance_sheet"("p_as_of_date" "date", "p_usd_rate" numeric DEFAULT 1) RETURNS TABLE("code" character varying, "name" character varying, "name_id" character varying, "account_type" character varying, "account_group" character varying, "normal_balance" character varying, "total_debit" numeric, "total_credit" numeric, "balance" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_net_income numeric;
  v_has_3300 boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Journal-native P&L sign convention:
  --   revenue = credit - debit
  --   expense = debit - credit
  --   net income = revenue - expense
  SELECT COALESCE(SUM(
    CASE
      WHEN coa.account_type = 'revenue' THEN jel.credit - jel.debit
      WHEN coa.account_type = 'expense' THEN jel.credit - jel.debit
      ELSE 0
    END
  ), 0)
  INTO v_net_income
  FROM public.journal_entry_lines jel
  JOIN public.journal_entries je ON je.id = jel.journal_entry_id
  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
  WHERE je.is_posted = true
    AND COALESCE(je.is_reversed, false) = false
    AND je.entry_date <= p_as_of_date
    AND coa.is_header = false;

  SELECT EXISTS (
    SELECT 1
    FROM public.journal_entry_lines jel
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
    WHERE coa.code = '3300'
      AND je.is_posted = true
      AND COALESCE(je.is_reversed, false) = false
      AND je.entry_date <= p_as_of_date
  )
  INTO v_has_3300;

  RETURN QUERY
  WITH active_lines AS (
    SELECT jel.account_id, jel.debit, jel.credit
    FROM public.journal_entry_lines jel
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE je.is_posted = true
      AND COALESCE(je.is_reversed, false) = false
      AND je.entry_date <= p_as_of_date
  )
  SELECT
    coa.code,
    coa.name,
    coa.name_id,
    coa.account_type,
    coa.account_group,
    COALESCE(
      coa.normal_balance,
      CASE WHEN coa.account_type IN ('asset', 'expense') THEN 'debit' ELSE 'credit' END
    ),
    COALESCE(SUM(al.debit), 0)::numeric,
    COALESCE(SUM(al.credit), 0)::numeric,
    (COALESCE(SUM(al.debit), 0) - COALESCE(SUM(al.credit), 0))::numeric
  FROM public.chart_of_accounts coa
  LEFT JOIN active_lines al ON al.account_id = coa.id
  WHERE coa.is_header = false
    AND coa.is_active = true
    AND coa.account_type IN ('asset', 'liability', 'equity', 'contra')
  GROUP BY coa.id, coa.code, coa.name, coa.name_id, coa.account_type,
    coa.account_group, coa.normal_balance
  HAVING COALESCE(SUM(al.debit), 0) <> 0
      OR COALESCE(SUM(al.credit), 0) <> 0

  UNION ALL

  SELECT
    '3300'::varchar,
    'Current Year Earnings'::varchar,
    'Laba/Rugi Tahun Berjalan'::varchar,
    'equity'::varchar,
    'Equity'::varchar,
    'credit'::varchar,
    CASE WHEN v_net_income < 0 THEN ABS(v_net_income) ELSE 0 END,
    CASE WHEN v_net_income > 0 THEN v_net_income ELSE 0 END,
    (-v_net_income)::numeric
  WHERE NOT v_has_3300
    AND ABS(v_net_income) > 0.005
  ORDER BY 1;
END;
$$;


--
-- Name: FUNCTION "get_balance_sheet"("p_as_of_date" "date", "p_usd_rate" numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_balance_sheet"("p_as_of_date" "date", "p_usd_rate" numeric) IS 'Journal-native Balance Sheet. Synthetic 3300 Current Year Earnings is revenue minus expenses; p_usd_rate is retained for API compatibility.';


--
-- Name: get_batch_transaction_history("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_batch_transaction_history"("p_batch_id" "uuid") RETURNS TABLE("transaction_date" timestamp with time zone, "transaction_type" "text", "quantity_change" numeric, "stock_before" numeric, "stock_after" numeric, "notes" "text", "created_by_name" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT
it.transaction_date,
it.transaction_type,
it.quantity_change,
it.stock_before,
it.stock_after,
it.notes,
up.full_name
FROM inventory_transactions it
LEFT JOIN user_profiles up ON up.id = it.created_by
WHERE it.batch_id = p_batch_id
ORDER BY it.transaction_date DESC, it.created_at DESC;
END;
$$;


--
-- Name: get_cogs_for_period("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_cogs_for_period"("p_start" "date", "p_end" "date") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
SELECT COALESCE(
SUM(
sii.quantity *
CASE
WHEN COALESCE(b.landed_cost_per_unit, 0) > 0
THEN b.landed_cost_per_unit
WHEN COALESCE(b.import_price_usd, 0) > 0
THEN b.import_price_usd * COALESCE(b.exchange_rate_usd_to_idr, 16000)
ELSE COALESCE(b.import_price, 0)
END
), 0)
FROM sales_invoice_items sii
JOIN sales_invoices si ON si.id = sii.invoice_id
LEFT JOIN batches b ON b.id = sii.batch_id
WHERE si.invoice_date BETWEEN p_start AND p_end
AND si.is_draft = false;
$$;


--
-- Name: get_company_profile_reference_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_company_profile_reference_counts"() RETURNS TABLE("profile_id" "uuid", "ref_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH refs AS (
    SELECT NULLIF(company_snapshot->>'id','')::uuid AS pid FROM sales_invoices     WHERE company_snapshot ? 'id'
    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM delivery_challans  WHERE company_snapshot ? 'id'
    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM credit_notes      WHERE company_snapshot ? 'id'
    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM material_returns  WHERE company_snapshot ? 'id'
    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM stock_rejections  WHERE company_snapshot ? 'id'
    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM purchase_orders   WHERE company_snapshot ? 'id'
    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM payment_vouchers  WHERE company_snapshot ? 'id'
    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM receipt_vouchers  WHERE company_snapshot ? 'id'
    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM purchase_invoices WHERE company_snapshot ? 'id'
    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM sales_orders      WHERE company_snapshot ? 'id'
  )
  SELECT pid AS profile_id, count(*)::bigint AS ref_count
  FROM refs
  WHERE pid IS NOT NULL
  GROUP BY pid;
$$;


--
-- Name: get_control_account_reconciliation("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_control_account_reconciliation"("p_as_of_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("control_code" "text", "control_name" "text", "gl_balance" numeric, "subledger_balance" numeric, "difference" numeric, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_ar_gl numeric; v_ap_gl numeric; v_ar_sub numeric; v_ap_sub numeric;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT COALESCE(SUM(jel.debit - jel.credit), 0) INTO v_ar_gl
  FROM public.journal_entry_lines jel JOIN public.journal_entries je ON je.id = jel.journal_entry_id
  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
  WHERE coa.code = '1120' AND je.is_posted = true AND COALESCE(je.is_reversed, false) = false AND je.entry_date <= p_as_of_date;

  SELECT COALESCE(SUM(jel.credit - jel.debit), 0) INTO v_ap_gl
  FROM public.journal_entry_lines jel JOIN public.journal_entries je ON je.id = jel.journal_entry_id
  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
  WHERE coa.code = '2110' AND je.is_posted = true AND COALESCE(je.is_reversed, false) = false AND je.entry_date <= p_as_of_date;

  SELECT COALESCE(SUM(balance_amount), 0) INTO v_ar_sub FROM public.get_customer_ar_open_items(p_as_of_date);

  WITH pi AS (
    SELECT p.id, p.total_amount
    FROM public.purchase_invoices p JOIN public.journal_entries je ON je.id = p.journal_entry_id
    WHERE je.is_posted = true AND COALESCE(je.is_reversed, false) = false AND p.invoice_date <= p_as_of_date
  ), pi_paid AS (
    SELECT va.purchase_invoice_id, SUM(va.allocated_amount) amount
    FROM public.voucher_allocations va JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id
    JOIN public.journal_entries je ON je.id = pv.journal_entry_id
    WHERE va.voucher_type = 'payment' AND je.is_posted = true AND COALESCE(je.is_reversed, false) = false AND pv.voucher_date <= p_as_of_date
    GROUP BY va.purchase_invoice_id
  ), expense_bills AS (
    SELECT fe.id, fe.amount, fe.paid_amount
    FROM public.finance_expenses fe
    JOIN public.journal_entries je ON je.source_module = 'expenses' AND je.reference_id = fe.id
    WHERE fe.payment_method IS NULL AND fe.approval_status = 'approved' AND fe.expense_date <= p_as_of_date
      AND je.is_posted = true AND COALESCE(je.is_reversed, false) = false
  )
  SELECT COALESCE((SELECT SUM(pi.total_amount - COALESCE(pi_paid.amount, 0)) FROM pi LEFT JOIN pi_paid ON pi_paid.purchase_invoice_id = pi.id), 0)
       + COALESCE((SELECT SUM(amount - COALESCE(paid_amount, 0)) FROM expense_bills), 0)
  INTO v_ap_sub;

  RETURN QUERY VALUES
    ('1120'::text, 'Accounts Receivable'::text, v_ar_gl, v_ar_sub, (v_ar_gl - v_ar_sub), CASE WHEN ABS(v_ar_gl - v_ar_sub) <= 0.01 THEN 'reconciled' ELSE 'difference' END),
    ('2110'::text, 'Accounts Payable'::text, v_ap_gl, v_ap_sub, (v_ap_gl - v_ap_sub), CASE WHEN ABS(v_ap_gl - v_ap_sub) <= 0.01 THEN 'reconciled' ELSE 'difference' END);
END;
$$;


--
-- Name: get_current_company_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_current_company_profile"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT to_jsonb(cp)
  FROM company_profiles cp
  WHERE cp.effective_from <= CURRENT_DATE
  ORDER BY cp.effective_from DESC
  LIMIT 1;
$$;


--
-- Name: get_current_financial_year(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_current_financial_year"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_fy_start_date DATE;
v_fy_start_month INT;
v_fy_start_day INT;
v_current_date DATE;
v_current_year INT;
v_this_year_fy_start DATE;
v_fy_year INT;
BEGIN
-- Get financial year start date from settings
SELECT financial_year_start INTO v_fy_start_date
FROM app_settings
LIMIT 1;

-- If not set, default to current year Jan 1
IF v_fy_start_date IS NULL THEN
v_fy_start_date := MAKE_DATE(EXTRACT(YEAR FROM CURRENT_DATE)::INT, 1, 1);
END IF;

-- Extract month and day from FY start
v_fy_start_month := EXTRACT(MONTH FROM v_fy_start_date)::INT;
v_fy_start_day := EXTRACT(DAY FROM v_fy_start_date)::INT;

-- Get current date and year
v_current_date := CURRENT_DATE;
v_current_year := EXTRACT(YEAR FROM v_current_date)::INT;

-- Calculate this year's FY start date
v_this_year_fy_start := MAKE_DATE(v_current_year, v_fy_start_month, v_fy_start_day);

-- Determine which FY we're in
IF v_current_date >= v_this_year_fy_start THEN
-- We're in the current year's FY
v_fy_year := v_current_year;
ELSE
-- We're still in the previous year's FY
v_fy_year := v_current_year - 1;
END IF;

-- Return 2-digit year code (e.g., '26' for 2026)
RETURN RIGHT(v_fy_year::TEXT, 2);
END;
$$;


--
-- Name: FUNCTION "get_current_financial_year"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_current_financial_year"() IS 'Automatically calculates current financial year based on app_settings.financial_year_start. Returns 2-digit year code (e.g., "26" for 2026). No manual updates needed.';


--
-- Name: get_customer_ar_open_items("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_customer_ar_open_items"("p_as_of_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("id" "uuid", "customer_id" "uuid", "customer_name" "text", "customer_email" "text", "customer_phone" "text", "invoice_number" "text", "invoice_date" "date", "due_date" "date", "total_amount" numeric, "paid_amount" numeric, "credit_note_amount" numeric, "balance_amount" numeric, "days_overdue" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH invoices AS (
    SELECT si.id, si.customer_id, si.invoice_number, si.invoice_date, si.due_date, si.total_amount,
      c.company_name, c.email, c.phone
    FROM public.sales_invoices si
    JOIN public.customers c ON c.id = si.customer_id
    JOIN public.journal_entries je ON je.id = si.journal_entry_id
    WHERE je.is_posted = true AND COALESCE(je.is_reversed, false) = false
      AND si.invoice_date <= p_as_of_date
  ), paid AS (
    SELECT va.sales_invoice_id, COALESCE(SUM(va.allocated_amount), 0) AS paid_amount
    FROM public.voucher_allocations va
    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id
    JOIN public.journal_entries je ON je.id = rv.journal_entry_id
    WHERE va.voucher_type = 'receipt' AND je.is_posted = true
      AND COALESCE(je.is_reversed, false) = false AND rv.voucher_date <= p_as_of_date
    GROUP BY va.sales_invoice_id
  ), direct_credit AS (
    SELECT cn.original_invoice_id AS invoice_id, COALESCE(SUM(cn.total_amount), 0) AS amount
    FROM public.credit_notes cn
    JOIN public.journal_entries je ON je.id = cn.journal_entry_id
    WHERE cn.status = 'approved' AND cn.original_invoice_id IS NOT NULL
      AND cn.credit_note_date <= p_as_of_date AND je.is_posted = true
      AND COALESCE(je.is_reversed, false) = false
    GROUP BY cn.original_invoice_id
  ), unallocated_credit AS (
    SELECT cn.customer_id, COALESCE(SUM(cn.total_amount), 0) AS amount
    FROM public.credit_notes cn
    JOIN public.journal_entries je ON je.id = cn.journal_entry_id
    WHERE cn.status = 'approved' AND cn.original_invoice_id IS NULL
      AND cn.credit_note_date <= p_as_of_date AND je.is_posted = true
      AND COALESCE(je.is_reversed, false) = false
    GROUP BY cn.customer_id
  ), base AS (
    SELECT i.*, COALESCE(p.paid_amount, 0) AS paid_amount,
      LEAST(GREATEST(i.total_amount - COALESCE(p.paid_amount, 0), 0), COALESCE(dc.amount, 0)) AS direct_credit_amount,
      GREATEST(i.total_amount - COALESCE(p.paid_amount, 0) - COALESCE(dc.amount, 0), 0) AS open_after_direct,
      COALESCE(uc.amount, 0) AS unallocated_credit_amount
    FROM invoices i
    LEFT JOIN paid p ON p.sales_invoice_id = i.id
    LEFT JOIN direct_credit dc ON dc.invoice_id = i.id
    LEFT JOIN unallocated_credit uc ON uc.customer_id = i.customer_id
  ), apportioned AS (
    SELECT base.*,
      COALESCE(SUM(open_after_direct) OVER (
        PARTITION BY customer_id ORDER BY invoice_date, id
        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
      ), 0) AS prior_open
    FROM base
  )
  SELECT id, customer_id, company_name, email, phone, invoice_number, invoice_date, due_date,
    total_amount, paid_amount,
    (direct_credit_amount + LEAST(open_after_direct, GREATEST(unallocated_credit_amount - prior_open, 0)))::numeric,
    GREATEST(open_after_direct - LEAST(open_after_direct, GREATEST(unallocated_credit_amount - prior_open, 0)), 0)::numeric,
    GREATEST((p_as_of_date - due_date), 0)::integer
  FROM apportioned
  WHERE GREATEST(open_after_direct - LEAST(open_after_direct, GREATEST(unallocated_credit_amount - prior_open, 0)), 0) > 0.005
  ORDER BY due_date NULLS LAST, invoice_date, invoice_number;
$$;


--
-- Name: get_customer_outstanding_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_customer_outstanding_summary"() RETURNS TABLE("id" "uuid", "name" "text", "email" "text", "total_outstanding" numeric, "age_0_30" numeric, "age_31_60" numeric, "age_61_90" numeric, "age_90_plus" numeric, "oldest_invoice_date" "date")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT
c.id,
c.company_name::TEXT AS name,
c.email::TEXT AS email,
COALESCE(SUM(si.balance_amount), 0) AS total_outstanding,
COALESCE(SUM(CASE WHEN CURRENT_DATE - si.invoice_date <= 30 THEN si.balance_amount ELSE 0 END), 0) AS age_0_30,
COALESCE(SUM(CASE WHEN CURRENT_DATE - si.invoice_date BETWEEN 31 AND 60 THEN si.balance_amount ELSE 0 END), 0) AS age_31_60,
COALESCE(SUM(CASE WHEN CURRENT_DATE - si.invoice_date BETWEEN 61 AND 90 THEN si.balance_amount ELSE 0 END), 0) AS age_61_90,
COALESCE(SUM(CASE WHEN CURRENT_DATE - si.invoice_date > 90 THEN si.balance_amount ELSE 0 END), 0) AS age_90_plus,
MIN(si.invoice_date) AS oldest_invoice_date
FROM customers c
INNER JOIN sales_invoices si ON si.customer_id = c.id
WHERE si.payment_status IN ('pending', 'partial')
AND si.balance_amount > 0
GROUP BY c.id, c.company_name, c.email
HAVING COALESCE(SUM(si.balance_amount), 0) > 0
ORDER BY COALESCE(SUM(si.balance_amount), 0) DESC;
END;
$$;


--
-- Name: get_customer_sales_report("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_customer_sales_report"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("customer_id" "uuid", "customer_name" "text", "total_orders" bigint, "total_sales" numeric, "avg_order_value" numeric, "last_order_date" "date", "total_qty" numeric, "total_cogs" numeric, "total_profit" numeric, "profit_pct" numeric, "costed_lines" bigint, "total_lines" bigint, "cost_coverage" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH lines AS (
    SELECT si.id, si.customer_id, c.company_name, si.invoice_date, sii.quantity, sii.unit_price,
      b.landed_cost_per_unit, (b.landed_cost_per_unit > 0) AS is_costed
    FROM public.sales_invoices si
    JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id
    JOIN public.customers c ON c.id = si.customer_id
    LEFT JOIN public.batches b ON b.id = sii.batch_id
    WHERE si.invoice_date >= p_start_date AND si.invoice_date <= p_end_date
      AND COALESCE(si.is_draft, false) = false
  ), grouped AS (
    SELECT customer_id, company_name, COUNT(DISTINCT id) AS total_orders,
      SUM(quantity * unit_price) AS total_sales, SUM(quantity) AS total_qty,
      SUM(quantity * unit_price) FILTER (WHERE is_costed) AS costed_revenue,
      COALESCE(SUM(quantity * landed_cost_per_unit) FILTER (WHERE is_costed), 0) AS total_cogs,
      MAX(invoice_date) AS last_order_date, COUNT(*) FILTER (WHERE is_costed) AS costed_lines,
      COUNT(*) AS total_lines
    FROM lines GROUP BY customer_id, company_name
  )
  SELECT customer_id, company_name, total_orders, ROUND(total_sales, 2),
    ROUND(total_sales / NULLIF(total_orders, 0), 2), last_order_date, total_qty,
    ROUND(total_cogs, 2), ROUND(COALESCE(costed_revenue, 0) - total_cogs, 2),
    CASE WHEN COALESCE(costed_revenue, 0) = 0 THEN NULL
      ELSE ROUND((costed_revenue - total_cogs) / costed_revenue * 100, 2) END,
    costed_lines, total_lines, ROUND(costed_lines::numeric / NULLIF(total_lines, 0) * 100, 2)
  FROM grouped ORDER BY total_sales DESC;
$$;


--
-- Name: get_dc_item_details("uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_dc_item_details"("p_dc_item_ids" "uuid"[]) RETURNS TABLE("dc_item_id" "uuid", "challan_id" "uuid", "challan_number" "text", "product_id" "uuid", "product_name" "text", "batch_id" "uuid", "batch_number" "text", "unit" "text", "pack_size" numeric, "pack_type" "text", "number_of_packs" integer, "original_quantity" numeric, "remaining_quantity" numeric, "status" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT 
dis.dc_item_id,
dis.challan_id,
dis.challan_number,
dis.product_id,
dis.product_name,
dis.batch_id,
dis.batch_number,
dis.unit,
dis.pack_size,
dis.pack_type,
dis.number_of_packs,
dis.original_quantity,
dis.remaining_quantity,
dis.status
FROM dc_item_invoice_status dis
WHERE dis.dc_item_id = ANY(p_dc_item_ids);
END;
$$;


--
-- Name: FUNCTION "get_dc_item_details"("p_dc_item_ids" "uuid"[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_dc_item_details"("p_dc_item_ids" "uuid"[]) IS 'Returns detailed information for specific DC items. Used when loading an existing invoice for editing.';


--
-- Name: get_expense_account_id("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_expense_account_id"("p_category" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT ec.coa_account_id
  FROM public.expense_categories ec
  JOIN public.chart_of_accounts coa ON coa.id=ec.coa_account_id
  WHERE ec.category_key=p_category
    AND ec.is_active
    AND ec.is_posting_category
    AND coa.is_active
    AND NOT coa.is_header
  LIMIT 1
$$;


--
-- Name: FUNCTION "get_expense_account_id"("p_category" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_expense_account_id"("p_category" "text") IS 'Returns only the active master-configured posting account. Unknown categories have no fallback.';


--
-- Name: get_expense_export_accounts("uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_expense_export_accounts"("p_expense_ids" "uuid"[]) RETURNS TABLE("expense_id" "uuid", "coa_code" "text", "coa_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH requested_expenses AS (
    SELECT id, expense_category, approval_status
    FROM public.finance_expenses
    WHERE id = ANY(p_expense_ids)
  ),
  posted_accounts AS (
    SELECT DISTINCT ON (expense.id)
      expense.id AS expense_id,
      coa.code AS coa_code,
      coa.name AS coa_name
    FROM requested_expenses expense
    JOIN public.journal_entries journal
      ON journal.source_module IN ('expense', 'expenses')
     AND (
       journal.reference_id = expense.id
       OR journal.reference_number = 'EXP-' || expense.id::text
     )
     AND journal.is_posted = true
    JOIN public.journal_entry_lines line
      ON line.journal_entry_id = journal.id
     AND line.debit > 0
    JOIN public.chart_of_accounts coa
      ON coa.id = line.account_id
    ORDER BY expense.id, journal.posted_at DESC NULLS LAST, journal.created_at DESC, line.line_number
  ),
  fallback_accounts AS (
    SELECT
      expense.id AS expense_id,
      coa.code AS coa_code,
      coa.name AS coa_name
    FROM requested_expenses expense
    JOIN public.chart_of_accounts coa
      ON coa.id = public.get_expense_account_id(expense.expense_category)
    WHERE expense.approval_status IS DISTINCT FROM 'approved'
  )
  SELECT
    expense.id AS expense_id,
    COALESCE(posted.coa_code, fallback.coa_code) AS coa_code,
    COALESCE(posted.coa_name, fallback.coa_name) AS coa_name
  FROM requested_expenses expense
  LEFT JOIN posted_accounts posted ON posted.expense_id = expense.id
  LEFT JOIN fallback_accounts fallback ON fallback.expense_id = expense.id;
$$;


--
-- Name: FUNCTION "get_expense_export_accounts"("p_expense_ids" "uuid"[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_expense_export_accounts"("p_expense_ids" "uuid"[]) IS 'Expense export COA: posted journal debit account first; canonical category default before approval.';


--
-- Name: get_expense_pph_period_date("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_expense_pph_period_date"("p_expense_id" "uuid") RETURNS "date"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE((SELECT max(payment_date) FROM (
    SELECT pv.voucher_date payment_date FROM public.voucher_allocations va
    JOIN public.payment_vouchers pv ON pv.id=va.payment_voucher_id
    WHERE va.finance_expense_id=fe.id AND COALESCE(va.payment_kind,'supplier')='supplier' AND COALESCE(pv.is_posted,false)
    UNION ALL
    SELECT b.transaction_date FROM public.bank_statement_allocations a
    JOIN public.bank_statement_lines b ON b.id=a.bank_statement_line_id
    WHERE a.document_type='expense' AND a.document_id=fe.id AND a.payment_kind='supplier'
    UNION ALL
    SELECT b.transaction_date FROM public.bank_statement_lines b
    WHERE b.matched_expense_id=fe.id AND COALESCE(b.payment_kind,'supplier')='supplier'
      AND NOT EXISTS(SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id=b.id)
  ) payments),fe.due_date,fe.expense_date)
  FROM public.finance_expenses fe WHERE fe.id=p_expense_id;
$$;


--
-- Name: get_expense_vs_profit_report("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_expense_vs_profit_report"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("total_sales" numeric, "total_cogs" numeric, "gross_profit" numeric, "outbound_delivery" numeric, "contribution_profit" numeric, "operating_expenses" numeric, "operational_profit" numeric, "profit_pct" numeric, "costed_lines" bigint, "total_lines" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH lines AS (
    SELECT sii.quantity, sii.unit_price, b.landed_cost_per_unit,
      (b.landed_cost_per_unit > 0) AS is_costed
    FROM public.sales_invoices si
    JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id
    LEFT JOIN public.batches b ON b.id = sii.batch_id
    WHERE si.invoice_date >= p_start_date AND si.invoice_date <= p_end_date
      AND COALESCE(si.is_draft, false) = false
  ), sales AS (
    SELECT COALESCE(SUM(quantity * unit_price), 0) AS total_sales,
      COALESCE(SUM(quantity * unit_price) FILTER (WHERE is_costed), 0) AS costed_revenue,
      COALESCE(SUM(quantity * landed_cost_per_unit) FILTER (WHERE is_costed), 0) AS total_cogs,
      COUNT(*) FILTER (WHERE is_costed) AS costed_lines, COUNT(*) AS total_lines FROM lines
  ), expenses AS (
    SELECT COALESCE(SUM(amount) FILTER (WHERE expense_category IN ('delivery_sales', 'loading_sales')), 0) AS outbound_delivery,
      COALESCE(SUM(amount) FILTER (WHERE expense_category NOT IN ('delivery_sales', 'loading_sales')), 0) AS operating_expenses
    FROM public.finance_expenses WHERE expense_date >= p_start_date AND expense_date <= p_end_date
  )
  SELECT ROUND(s.total_sales, 2), ROUND(s.total_cogs, 2), ROUND(s.costed_revenue - s.total_cogs, 2),
    ROUND(e.outbound_delivery, 2), ROUND(s.costed_revenue - s.total_cogs - e.outbound_delivery, 2),
    ROUND(e.operating_expenses, 2), ROUND(s.costed_revenue - s.total_cogs - e.outbound_delivery - e.operating_expenses, 2),
    CASE WHEN s.costed_revenue = 0 THEN NULL ELSE ROUND((s.costed_revenue - s.total_cogs - e.outbound_delivery - e.operating_expenses) / s.costed_revenue * 100, 2) END,
    s.costed_lines, s.total_lines
  FROM sales s CROSS JOIN expenses e;
$$;


--
-- Name: get_finance_dashboard_summary("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_finance_dashboard_summary"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("revenue" numeric, "expenses" numeric, "net_income" numeric, "accounts_receivable" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_revenue numeric; v_expenses numeric; v_ar numeric;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT
    COALESCE(SUM(CASE WHEN coa.account_type = 'revenue' THEN jel.credit - jel.debit ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN coa.account_type = 'expense' THEN jel.debit - jel.credit ELSE 0 END), 0)
  INTO v_revenue, v_expenses
  FROM public.journal_entry_lines jel
  JOIN public.journal_entries je ON je.id = jel.journal_entry_id
  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
  WHERE je.is_posted = true AND COALESCE(je.is_reversed, false) = false
    AND je.entry_date BETWEEN p_start_date AND p_end_date;

  SELECT COALESCE(SUM(balance_amount), 0) INTO v_ar FROM public.get_customer_ar_open_items(p_end_date);
  RETURN QUERY SELECT v_revenue, v_expenses, v_revenue - v_expenses, v_ar;
END;
$$;


--
-- Name: bank_accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."bank_accounts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_name" "text" NOT NULL,
    "bank_name" "text" NOT NULL,
    "account_number" "text" NOT NULL,
    "account_type" "text" NOT NULL,
    "currency" "text" DEFAULT 'IDR'::"text" NOT NULL,
    "opening_balance" numeric DEFAULT 0 NOT NULL,
    "current_balance" numeric DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "alias" "text",
    "coa_id" "uuid",
    "opening_balance_date" "date" DEFAULT '2025-01-01'::"date" NOT NULL,
    CONSTRAINT "bank_accounts_account_type_check" CHECK (("account_type" = ANY (ARRAY['savings'::"text", 'current'::"text", 'credit_card'::"text", 'other'::"text"])))
);


--
-- Name: TABLE "bank_accounts"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE "public"."bank_accounts" IS 'Bank accounts for managing company funds and reconciliation';


--
-- Name: COLUMN "bank_accounts"."opening_balance"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."bank_accounts"."opening_balance" IS 'Opening balance for current financial year';


--
-- Name: COLUMN "bank_accounts"."alias"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."bank_accounts"."alias" IS 'Short display name for UI (e.g., "BCA IDR", "Mandiri USD")';


--
-- Name: COLUMN "bank_accounts"."coa_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."bank_accounts"."coa_id" IS 'Links to the corresponding Chart of Accounts entry for this bank account';


--
-- Name: COLUMN "bank_accounts"."opening_balance_date"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."bank_accounts"."opening_balance_date" IS 'The date on which the opening_balance amount is effective';


--
-- Name: finance_expenses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."finance_expenses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "expense_category" "text" NOT NULL,
    "amount" numeric(15,2) NOT NULL,
    "expense_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "description" "text",
    "batch_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "document_urls" "text"[],
    "import_container_id" "uuid",
    "delivery_challan_id" "uuid",
    "expense_type" character varying(20) DEFAULT 'general'::character varying,
    "voucher_number" "text",
    "payment_method" character varying(50) DEFAULT 'cash'::character varying,
    "bank_account_id" "uuid",
    "payment_reference" character varying(100),
    "paid_by" "text" DEFAULT 'bank'::"text",
    "approval_status" "text" DEFAULT 'pending_approval'::"text" NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "rejection_reason" "text",
    "pib_bm_amount" numeric(18,2),
    "pib_ppn_amount" numeric(18,2),
    "pib_pph_amount" numeric(18,2),
    "ppn_amount" numeric(18,2) DEFAULT 0,
    "pph_amount" numeric(18,2) DEFAULT 0,
    "pph_code_id" "uuid",
    "stamp_duty_amount" numeric(18,2) DEFAULT 0,
    "fixed_asset_account_id" "uuid",
    "supplier_id" "uuid",
    "invoice_number" character varying(100),
    "due_date" "date",
    "paid_amount" numeric(18,2) DEFAULT 0 NOT NULL,
    "broker_items" "jsonb",
    "pph_paid_amount" numeric(15,2) DEFAULT 0 NOT NULL,
    "tax_period_id" "uuid",
    "staff_id" "uuid",
    "bank_charges_amount" numeric(18,2) DEFAULT 0 NOT NULL,
    "ppn_calc_mode" "text" DEFAULT 'standard'::"text" NOT NULL,
    "dpp_amount" numeric(18,2),
    "ppn_rate" numeric(6,3) DEFAULT 11 NOT NULL,
    "ppn_manual_override" boolean DEFAULT false NOT NULL,
    "currency_code" "text",
    "transaction_currency" "text",
    "functional_currency" "text",
    "exchange_rate" numeric(18,6),
    "bank_account_currency" "text",
    "payment_currency" "text",
    "settlement_amount" numeric GENERATED ALWAYS AS ("public"."calculate_expense_settlement_amount"("expense_category", "amount", "ppn_amount", "pph_amount", "stamp_duty_amount", "bank_charges_amount", "broker_items")) STORED,
    "pph_tax_period_id" "uuid",
    "include_in_landed_cost" boolean,
    CONSTRAINT "chk_pib_breakdown_sum" CHECK ((("expense_category" <> 'pib_import'::"text") OR (("pib_bm_amount" IS NOT NULL) AND ("pib_ppn_amount" IS NOT NULL) AND ("pib_pph_amount" IS NOT NULL) AND ("abs"((((COALESCE("pib_bm_amount", (0)::numeric) + COALESCE("pib_ppn_amount", (0)::numeric)) + COALESCE("pib_pph_amount", (0)::numeric)) - "amount")) < 1.00)))),
    CONSTRAINT "finance_expenses_approval_status_check" CHECK (("approval_status" = ANY (ARRAY['pending_approval'::"text", 'approved'::"text", 'rejected'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "finance_expenses_bank_charges_amount_check" CHECK (("bank_charges_amount" >= (0)::numeric)),
    CONSTRAINT "finance_expenses_currency_metadata_check" CHECK (((("transaction_currency" IS NULL) OR ("transaction_currency" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("functional_currency" IS NULL) OR ("functional_currency" = 'IDR'::"text")) AND (("currency_code" IS NULL) OR ("currency_code" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("payment_currency" IS NULL) OR ("payment_currency" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("bank_account_currency" IS NULL) OR ("bank_account_currency" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("exchange_rate" IS NULL) OR ("exchange_rate" > (0)::numeric)))),
    CONSTRAINT "finance_expenses_expense_type_check" CHECK ((("expense_type")::"text" = ANY ((ARRAY['import'::character varying, 'sales'::character varying, 'general'::character varying])::"text"[]))),
    CONSTRAINT "finance_expenses_paid_by_check" CHECK (("paid_by" = ANY (ARRAY['bank'::"text", 'cash'::"text"]))),
    CONSTRAINT "finance_expenses_payment_method_check" CHECK ((("payment_method")::"text" = ANY ((ARRAY['cash'::character varying, 'bank_transfer'::character varying, 'check'::character varying, 'giro'::character varying, 'other'::character varying])::"text"[]))),
    CONSTRAINT "finance_expenses_ppn_calc_mode_check" CHECK (("ppn_calc_mode" = ANY (ARRAY['standard'::"text", 'dpp_nilai_lain'::"text", 'manual'::"text"])))
);


--
-- Name: COLUMN "finance_expenses"."expense_category"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."expense_category" IS 'Canonical category_key from expense_categories. Validated as an active posting leaf with an active non-header COA; no hard-coded category allow-list.';


--
-- Name: COLUMN "finance_expenses"."document_urls"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."document_urls" IS 'Array of URLs to expense supporting documents (invoices, receipts, bills, etc.) stored in expense-documents bucket';


--
-- Name: COLUMN "finance_expenses"."import_container_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."import_container_id" IS 'Link to import container for import-side costs (capitalized to inventory)';


--
-- Name: COLUMN "finance_expenses"."delivery_challan_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."delivery_challan_id" IS 'Link to delivery challan for sales-side delivery costs (P&L expense)';


--
-- Name: COLUMN "finance_expenses"."expense_type"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."expense_type" IS 'Distinguishes import costs (inventory) from sales costs (P&L)';


--
-- Name: COLUMN "finance_expenses"."voucher_number"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."voucher_number" IS 'Expense voucher number for bank reconciliation matching (e.g., PV-001, EXP-2025-001)';


--
-- Name: COLUMN "finance_expenses"."payment_method"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."payment_method" IS 'How the expense was paid: cash, bank_transfer, check, giro, other';


--
-- Name: COLUMN "finance_expenses"."bank_account_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."bank_account_id" IS 'Bank account used if payment_method is bank_transfer/check/giro';


--
-- Name: COLUMN "finance_expenses"."payment_reference"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."payment_reference" IS 'Check number, transfer reference, or giro number';


--
-- Name: COLUMN "finance_expenses"."pib_bm_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."pib_bm_amount" IS 'PIB Import only: Import Duty (BM) portion. Goes to landed cost / inventory.';


--
-- Name: COLUMN "finance_expenses"."pib_ppn_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."pib_ppn_amount" IS 'PIB Import only: PPN Import portion. Posted to PPN Masukan (1150). NOT in landed cost.';


--
-- Name: COLUMN "finance_expenses"."pib_pph_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."pib_pph_amount" IS 'PIB Import only: PPh 22 Import portion. Posted to PPh 22 Prepaid (1155). NOT in landed cost.';


--
-- Name: COLUMN "finance_expenses"."supplier_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."supplier_id" IS 'Supplier who issued this expense bill (optional)';


--
-- Name: COLUMN "finance_expenses"."invoice_number"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."invoice_number" IS 'Supplier invoice/reference number';


--
-- Name: COLUMN "finance_expenses"."due_date"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."due_date" IS 'Payment due date (auto-set from supplier terms, for outstanding bills)';


--
-- Name: COLUMN "finance_expenses"."paid_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."paid_amount" IS 'Amount paid via Payment Vouchers; maintained by trigger on voucher_allocations';


--
-- Name: COLUMN "finance_expenses"."broker_items"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."broker_items" IS 'Optional cost breakdown for Import/Customs Broker invoices. Array of {type, description, amount}. SUM(amount) = finance_expenses.amount. NULL = not a broker invoice. PPN, PPh, Stamp Duty are NOT included here — they stay on parent columns.';


--
-- Name: COLUMN "finance_expenses"."pph_paid_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."pph_paid_amount" IS 'Portion of pph_amount actually remitted to the government (SPT PPh23). Maintained by recalculate_expense_payment_state().';


--
-- Name: COLUMN "finance_expenses"."staff_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."staff_id" IS 'Staff member this expense belongs to (salary, overtime, welfare, advance). NULL for non-staff expenses.';


--
-- Name: COLUMN "finance_expenses"."bank_charges_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."bank_charges_amount" IS 'Optional bank charges paid alongside a utility bill. Only used for the utilities expense_category. Journal: Dr Utility, Dr Bank Charges, Cr Bank (=amount+bank_charges_amount). Utility expense amount itself is unchanged.';


--
-- Name: COLUMN "finance_expenses"."ppn_calc_mode"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."ppn_calc_mode" IS 'Indonesian PPN calculation mode. standard = ppn from invoice amount, dpp_nilai_lain = ppn from supplier-provided DPP, manual = user-entered.';


--
-- Name: COLUMN "finance_expenses"."dpp_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."dpp_amount" IS 'Supplier-provided DPP (Dasar Pengenaan Pajak) used when ppn_calc_mode = ''dpp_nilai_lain''. NULL for standard and manual modes.';


--
-- Name: COLUMN "finance_expenses"."ppn_rate"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."ppn_rate" IS 'PPN rate percent (default 11). Stored to preserve historical rates when rate changes (e.g. 11% → 12%).';


--
-- Name: COLUMN "finance_expenses"."ppn_manual_override"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."ppn_manual_override" IS 'If TRUE, ppn_amount was manually edited by the user and must not be auto-recomputed by the frontend when amount or supplier changes. FALSE for auto-calculated values. Reset to FALSE when the user clicks the recalculate button.';


--
-- Name: COLUMN "finance_expenses"."settlement_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."settlement_amount" IS 'Canonical actual bank settlement: invoice plus reimbursable/tax components, less withholding, plus bank charges/adjustments.';


--
-- Name: COLUMN "finance_expenses"."include_in_landed_cost"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."finance_expenses"."include_in_landed_cost" IS 'Controls whether this expense is included in its import container''s landed-cost allocation. NULL = not yet decided, TRUE = included, FALSE = excluded.';


--
-- Name: journal_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."journal_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entry_number" character varying(50) NOT NULL,
    "entry_date" "date" NOT NULL,
    "period_id" "uuid",
    "source_module" character varying(50),
    "reference_id" "uuid",
    "reference_number" character varying(100),
    "description" "text",
    "total_debit" numeric(18,2) DEFAULT 0,
    "total_credit" numeric(18,2) DEFAULT 0,
    "is_posted" boolean DEFAULT true,
    "is_reversed" boolean DEFAULT false,
    "reversed_by_id" "uuid",
    "posted_by" "uuid",
    "posted_at" timestamp with time zone DEFAULT "now"(),
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "transaction_category" "text",
    "transaction_currency" "text",
    "functional_currency" "text",
    "exchange_rate" numeric(18,6),
    "amounts_are_functional" boolean,
    CONSTRAINT "journal_entries_currency_metadata_check" CHECK (((("transaction_currency" IS NULL) OR ("transaction_currency" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("functional_currency" IS NULL) OR ("functional_currency" = 'IDR'::"text")) AND (("exchange_rate" IS NULL) OR ("exchange_rate" > (0)::numeric))))
);


--
-- Name: journal_entry_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."journal_entry_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "journal_entry_id" "uuid" NOT NULL,
    "line_number" integer NOT NULL,
    "account_id" "uuid" NOT NULL,
    "description" "text",
    "debit" numeric(18,2) DEFAULT 0,
    "credit" numeric(18,2) DEFAULT 0,
    "tax_code_id" "uuid",
    "customer_id" "uuid",
    "supplier_id" "uuid",
    "batch_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "transaction_currency" "text",
    "transaction_debit" numeric(18,2),
    "transaction_credit" numeric(18,2),
    "functional_currency" "text",
    "exchange_rate" numeric(18,6),
    CONSTRAINT "journal_entry_lines_currency_metadata_check" CHECK (((("transaction_currency" IS NULL) OR ("transaction_currency" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("functional_currency" IS NULL) OR ("functional_currency" = 'IDR'::"text")) AND (("exchange_rate" IS NULL) OR ("exchange_rate" > (0)::numeric))))
);


--
-- Name: payment_vouchers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."payment_vouchers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "voucher_number" character varying(50) NOT NULL,
    "voucher_date" "date" NOT NULL,
    "supplier_id" "uuid",
    "payment_method" character varying(50) NOT NULL,
    "bank_account_id" "uuid",
    "reference_number" character varying(100),
    "amount" numeric(18,2) NOT NULL,
    "pph_amount" numeric(18,2) DEFAULT 0,
    "pph_code_id" "uuid",
    "net_amount" numeric(18,2) GENERATED ALWAYS AS (("amount" - "pph_amount")) STORED,
    "description" "text",
    "document_urls" "text"[],
    "journal_entry_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "coa_account_id" "uuid",
    "payment_currency" character varying(8) DEFAULT 'IDR'::character varying,
    "exchange_rate" numeric DEFAULT 1,
    "bank_amount" numeric,
    "bank_charge" numeric DEFAULT 0,
    "is_posted" boolean DEFAULT false NOT NULL,
    "company_snapshot" "jsonb",
    "tax_period_id" "uuid",
    "staff_id" "uuid",
    "currency_code" "text",
    "transaction_currency" "text",
    "functional_currency" "text",
    "bank_account_currency" "text",
    "payment_purpose" "text" DEFAULT 'general'::"text" NOT NULL,
    "invoice_currency" "text",
    "invoice_amount" numeric,
    "payment_amount" numeric,
    "bank_currency" "text",
    "converted_amount" numeric,
    "actual_bank_debit" numeric,
    "salary_advance_applied_amount" numeric(18,2) DEFAULT 0 NOT NULL,
    "salary_advance_status" "text" DEFAULT 'not_applicable'::"text" NOT NULL,
    "settlement_amount" numeric GENERATED ALWAYS AS (COALESCE("actual_bank_debit", "bank_amount", (("amount" - COALESCE("pph_amount", (0)::numeric)) + COALESCE("bank_charge", (0)::numeric)))) STORED,
    CONSTRAINT "payment_vouchers_currency_metadata_check" CHECK (((("transaction_currency" IS NULL) OR ("transaction_currency" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("functional_currency" IS NULL) OR ("functional_currency" = 'IDR'::"text")) AND (("currency_code" IS NULL) OR ("currency_code" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("payment_currency" IS NULL) OR (("payment_currency")::"text" = ANY ((ARRAY['IDR'::character varying, 'USD'::character varying])::"text"[]))) AND (("bank_account_currency" IS NULL) OR ("bank_account_currency" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("exchange_rate" IS NULL) OR ("exchange_rate" > (0)::numeric)))),
    CONSTRAINT "payment_vouchers_payment_method_check" CHECK ((("payment_method")::"text" = ANY ((ARRAY['cash'::character varying, 'bank_transfer'::character varying, 'check'::character varying, 'giro'::character varying, 'other'::character varying, 'advance_adjustment'::character varying])::"text"[]))),
    CONSTRAINT "payment_vouchers_payment_purpose_check" CHECK (("payment_purpose" = ANY (ARRAY['general'::"text", 'salary_advance'::"text", 'salary_advance_settlement'::"text"]))),
    CONSTRAINT "payment_vouchers_salary_advance_status_check" CHECK (("salary_advance_status" = ANY (ARRAY['not_applicable'::"text", 'outstanding'::"text", 'partially_settled'::"text", 'settled'::"text"]))),
    CONSTRAINT "pv_supplier_or_account_required" CHECK ((("supplier_id" IS NOT NULL) OR ("staff_id" IS NOT NULL) OR ("coa_account_id" IS NOT NULL)))
);


--
-- Name: COLUMN "payment_vouchers"."staff_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."payment_vouchers"."staff_id" IS 'Staff payee (salary payment / advance / advance adjustment). Mutually exclusive with supplier_id in practice; both nullable.';


--
-- Name: COLUMN "payment_vouchers"."payment_purpose"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."payment_vouchers"."payment_purpose" IS 'Business purpose of the payment. salary_advance is a staff advance; settlement uses the existing advance_adjustment posting path.';


--
-- Name: COLUMN "payment_vouchers"."invoice_currency"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."payment_vouchers"."invoice_currency" IS 'Currency of the invoices being settled.';


--
-- Name: COLUMN "payment_vouchers"."invoice_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."payment_vouchers"."invoice_amount" IS 'Gross amount allocated in invoice currency.';


--
-- Name: COLUMN "payment_vouchers"."payment_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."payment_vouchers"."payment_amount" IS 'Net amount settled in invoice currency after withholding, before conversion.';


--
-- Name: COLUMN "payment_vouchers"."bank_currency"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."payment_vouchers"."bank_currency" IS 'Currency of the selected bank account.';


--
-- Name: COLUMN "payment_vouchers"."converted_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."payment_vouchers"."converted_amount" IS 'Payment amount converted to bank currency, before bank charges.';


--
-- Name: COLUMN "payment_vouchers"."actual_bank_debit"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."payment_vouchers"."actual_bank_debit" IS 'Actual bank-side debit, including bank charges.';


--
-- Name: COLUMN "payment_vouchers"."settlement_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."payment_vouchers"."settlement_amount" IS 'Canonical actual bank debit after withholding/conversion and including bank charges.';


--
-- Name: petty_cash_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."petty_cash_transactions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "transaction_number" character varying(50) NOT NULL,
    "transaction_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "transaction_type" character varying(20) NOT NULL,
    "amount" numeric(15,2) NOT NULL,
    "description" "text" NOT NULL,
    "expense_category" character varying(100),
    "bank_account_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "paid_to" character varying(255),
    "paid_by_staff_id" "uuid",
    "source" character varying(255),
    "received_by_staff_id" "uuid",
    "paid_by_staff_name" character varying(255),
    "received_by_staff_name" character varying(255),
    "paid_by" "text" DEFAULT 'cash'::"text",
    "import_container_id" "uuid",
    "delivery_challan_id" "uuid",
    "document_urls" "text"[],
    "voucher_number" character varying(50),
    "fund_transfer_id" "uuid",
    "approval_status" "text" DEFAULT 'pending_approval'::"text" NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "rejection_reason" "text",
    "source_account_id" "uuid",
    "bank_statement_line_id" "uuid",
    "settlement_amount" numeric GENERATED ALWAYS AS ("amount") STORED,
    "include_in_landed_cost" boolean,
    CONSTRAINT "petty_cash_transactions_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "petty_cash_transactions_approval_status_check" CHECK (("approval_status" = ANY (ARRAY['pending_approval'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "petty_cash_transactions_paid_by_check" CHECK (("paid_by" = ANY (ARRAY['bank'::"text", 'cash'::"text"]))),
    CONSTRAINT "petty_cash_transactions_transaction_type_check" CHECK ((("transaction_type")::"text" = ANY ((ARRAY['withdraw'::character varying, 'expense'::character varying])::"text"[])))
);


--
-- Name: COLUMN "petty_cash_transactions"."import_container_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."petty_cash_transactions"."import_container_id" IS 'Links petty cash expense to import container for cost allocation';


--
-- Name: COLUMN "petty_cash_transactions"."delivery_challan_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."petty_cash_transactions"."delivery_challan_id" IS 'Links petty cash expense to delivery challan';


--
-- Name: COLUMN "petty_cash_transactions"."document_urls"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."petty_cash_transactions"."document_urls" IS 'Array of document URLs (receipts, invoices, photos)';


--
-- Name: COLUMN "petty_cash_transactions"."settlement_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."petty_cash_transactions"."settlement_amount" IS 'Canonical cash/bank movement for this petty-cash document.';


--
-- Name: COLUMN "petty_cash_transactions"."include_in_landed_cost"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."petty_cash_transactions"."include_in_landed_cost" IS 'Controls whether this petty cash transaction is included in its import container''s landed-cost allocation. NULL = not yet decided, TRUE = included, FALSE = excluded.';


--
-- Name: receipt_vouchers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."receipt_vouchers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "voucher_number" character varying(50) NOT NULL,
    "voucher_date" "date" NOT NULL,
    "customer_id" "uuid",
    "payment_method" character varying(50) NOT NULL,
    "bank_account_id" "uuid",
    "reference_number" character varying(100),
    "amount" numeric(18,2) NOT NULL,
    "description" "text",
    "document_urls" "text"[],
    "journal_entry_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "coa_account_id" "uuid",
    "is_posted" boolean DEFAULT false NOT NULL,
    "company_snapshot" "jsonb",
    "currency_code" "text",
    "transaction_currency" "text",
    "functional_currency" "text",
    "exchange_rate" numeric(18,6),
    "bank_account_currency" "text",
    "payment_currency" "text",
    "settlement_amount" numeric GENERATED ALWAYS AS ("amount") STORED,
    CONSTRAINT "receipt_vouchers_currency_metadata_check" CHECK (((("transaction_currency" IS NULL) OR ("transaction_currency" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("functional_currency" IS NULL) OR ("functional_currency" = 'IDR'::"text")) AND (("currency_code" IS NULL) OR ("currency_code" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("payment_currency" IS NULL) OR ("payment_currency" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("bank_account_currency" IS NULL) OR ("bank_account_currency" = ANY (ARRAY['IDR'::"text", 'USD'::"text"]))) AND (("exchange_rate" IS NULL) OR ("exchange_rate" > (0)::numeric)))),
    CONSTRAINT "receipt_vouchers_payment_method_check" CHECK ((("payment_method")::"text" = ANY ((ARRAY['cash'::character varying, 'bank_transfer'::character varying, 'check'::character varying, 'giro'::character varying, 'other'::character varying])::"text"[]))),
    CONSTRAINT "rv_customer_or_account_required" CHECK ((("customer_id" IS NOT NULL) OR ("coa_account_id" IS NOT NULL)))
);


--
-- Name: COLUMN "receipt_vouchers"."settlement_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."receipt_vouchers"."settlement_amount" IS 'Canonical actual bank credit.';


--
-- Name: tax_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."tax_payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tax_period_id" "uuid" NOT NULL,
    "tax_type" "text" NOT NULL,
    "payment_date" "date" NOT NULL,
    "amount" numeric(18,2) NOT NULL,
    "bank_account_id" "uuid",
    "billing_code" "text",
    "ntpn" "text",
    "government_reference" "text",
    "notes" "text",
    "payment_voucher_id" "uuid",
    "journal_entry_id" "uuid",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "payment_reference" "text",
    "settlement_amount" numeric GENERATED ALWAYS AS ("amount") STORED,
    "historical_source_status" "text" DEFAULT 'none'::"text" NOT NULL,
    "historical_source_document_type" "text",
    "historical_source_document_id" "uuid",
    "historical_source_reference" "text",
    "historical_source_note" "text",
    CONSTRAINT "tax_payments_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "tax_payments_historical_source_status_check" CHECK (("historical_source_status" = ANY (ARRAY['none'::"text", 'missing_source_verified'::"text"]))),
    CONSTRAINT "tax_payments_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'posted'::"text", 'reconciled'::"text", 'void'::"text"]))),
    CONSTRAINT "tax_payments_tax_type_check" CHECK (("tax_type" = ANY (ARRAY['PPN'::"text", 'PPh21'::"text", 'PPh22'::"text", 'PPh23'::"text", 'PPh4(2)'::"text", 'PPh_Unifikasi'::"text"])))
);


--
-- Name: COLUMN "tax_payments"."settlement_amount"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."tax_payments"."settlement_amount" IS 'Canonical actual bank debit for the tax remittance.';


--
-- Name: vw_finance_document_settlements; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."vw_finance_document_settlements" WITH ("security_invoker"='true') AS
 WITH "document_journals" AS (
         SELECT 'expense'::"text" AS "document_type",
            "fe"."id" AS "document_id",
            COALESCE("fe"."voucher_number", ("fe"."invoice_number")::"text", ("fe"."id")::"text") AS "document_number",
            "fe"."expense_date" AS "settlement_date",
            "je"."id" AS "journal_entry_id"
           FROM ("public"."finance_expenses" "fe"
             JOIN "public"."journal_entries" "je" ON (((("je"."source_module")::"text" = ANY ((ARRAY['expense'::character varying, 'expenses'::character varying])::"text"[])) AND (("je"."reference_id" = "fe"."id") OR (("je"."reference_number")::"text" = ('EXP-'::"text" || ("fe"."id")::"text"))))))
        UNION ALL
         SELECT 'payment'::"text",
            "pv"."id",
            "pv"."voucher_number",
            "pv"."voucher_date",
            "pv"."journal_entry_id"
           FROM "public"."payment_vouchers" "pv"
          WHERE (("pv"."journal_entry_id" IS NOT NULL) AND ((COALESCE("pv"."payment_method", ''::character varying))::"text" <> 'advance_adjustment'::"text"))
        UNION ALL
         SELECT 'receipt'::"text",
            "rv"."id",
            "rv"."voucher_number",
            "rv"."voucher_date",
            "rv"."journal_entry_id"
           FROM "public"."receipt_vouchers" "rv"
          WHERE ("rv"."journal_entry_id" IS NOT NULL)
        UNION ALL
         SELECT 'fund_transfer'::"text",
            "ft"."id",
            "ft"."transfer_number",
            "ft"."transfer_date",
            "ft"."journal_entry_id"
           FROM "public"."fund_transfers" "ft"
          WHERE ("ft"."journal_entry_id" IS NOT NULL)
        UNION ALL
         SELECT 'petty_cash'::"text",
            "pc"."id",
            "pc"."transaction_number",
            "pc"."transaction_date",
            "je"."id"
           FROM ("public"."petty_cash_transactions" "pc"
             JOIN "public"."journal_entries" "je" ON (((("je"."source_module")::"text" = 'petty_cash'::"text") AND ("je"."reference_id" = "pc"."id"))))
          WHERE ("pc"."fund_transfer_id" IS NULL)
        UNION ALL
         SELECT 'tax_payment'::"text",
            "tp"."id",
            COALESCE("tp"."ntpn", "tp"."billing_code", ("tp"."id")::"text") AS "coalesce",
            "tp"."payment_date",
            "tp"."journal_entry_id"
           FROM "public"."tax_payments" "tp"
          WHERE ("tp"."journal_entry_id" IS NOT NULL)
        ), "mapped" AS (
         SELECT DISTINCT ON ("document_journals"."document_type", "document_journals"."document_id", "document_journals"."journal_entry_id") "document_journals"."document_type",
            "document_journals"."document_id",
            "document_journals"."document_number",
            "document_journals"."settlement_date",
            "document_journals"."journal_entry_id"
           FROM "document_journals"
          WHERE ("document_journals"."journal_entry_id" IS NOT NULL)
          ORDER BY "document_journals"."document_type", "document_journals"."document_id", "document_journals"."journal_entry_id"
        ), "bank_legs" AS (
         SELECT "m"."document_type",
            "m"."document_id",
            "m"."document_number",
            "m"."settlement_date",
            "m"."journal_entry_id",
            "ba"."id" AS "bank_account_id",
            "upper"(COALESCE("ba"."currency", 'IDR'::"text")) AS "currency",
                CASE
                    WHEN ("sum"(COALESCE("jel"."transaction_debit", "jel"."debit")) > (0)::numeric) THEN 'credit'::"text"
                    ELSE 'debit'::"text"
                END AS "direction",
                CASE
                    WHEN ("sum"(COALESCE("jel"."transaction_debit", "jel"."debit")) > (0)::numeric) THEN "sum"(COALESCE("jel"."transaction_debit", "jel"."debit"))
                    ELSE "sum"(COALESCE("jel"."transaction_credit", "jel"."credit"))
                END AS "settlement_amount"
           FROM ((("mapped" "m"
             JOIN "public"."journal_entries" "je" ON ((("je"."id" = "m"."journal_entry_id") AND ("je"."is_posted" = true) AND (COALESCE("je"."is_reversed", false) = false))))
             JOIN "public"."journal_entry_lines" "jel" ON (("jel"."journal_entry_id" = "je"."id")))
             JOIN "public"."bank_accounts" "ba" ON (("ba"."coa_id" = "jel"."account_id")))
          GROUP BY "m"."document_type", "m"."document_id", "m"."document_number", "m"."settlement_date", "m"."journal_entry_id", "ba"."id", ("upper"(COALESCE("ba"."currency", 'IDR'::"text")))
        )
 SELECT "document_type",
    "document_id",
    "document_number",
    "settlement_date",
    "journal_entry_id",
    "bank_account_id",
    "currency",
    "direction",
    "settlement_amount"
   FROM "bank_legs"
  WHERE ("settlement_amount" > (0)::numeric);


--
-- Name: VIEW "vw_finance_document_settlements"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW "public"."vw_finance_document_settlements" IS 'One canonical actual-bank-movement row per Finance document, posted journal and bank account. Bank Reconciliation must consume settlement_amount only.';


--
-- Name: get_finance_document_settlements("text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_finance_document_settlements"("p_document_type" "text", "p_document_id" "uuid") RETURNS SETOF "public"."vw_finance_document_settlements"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT * FROM public.vw_finance_document_settlements
   WHERE document_type=p_document_type AND document_id=p_document_id
   ORDER BY bank_account_id,direction;
$$;


--
-- Name: get_gmail_connection_secret("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_gmail_connection_secret"("p_connection_id" "uuid" DEFAULT NULL::"uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "user_id" "uuid", "email_address" "text", "access_token" "text", "refresh_token" "text", "access_token_expires_at" timestamp with time zone, "is_connected" boolean, "sync_enabled" boolean, "last_sync" timestamp with time zone, "sync_frequency_minutes" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Not authenticated';
    END IF;
    -- Both scoping args cannot be NULL — that would return every row.
    IF p_connection_id IS NULL AND p_user_id IS NULL THEN
      RAISE EXCEPTION 'A connection_id or user_id must be provided';
    END IF;
    -- If both scoping args are provided, they must be consistent with caller.
    IF p_user_id IS NOT NULL AND p_user_id <> auth.uid() THEN
      RAISE EXCEPTION 'Forbidden';
    END IF;
    -- If only p_connection_id is provided, verify it belongs to the caller.
    IF p_user_id IS NULL AND p_connection_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.gmail_connections
        WHERE id = p_connection_id AND user_id = auth.uid()
      ) THEN
        RAISE EXCEPTION 'Forbidden';
      END IF;
    END IF;
  END IF;

  UPDATE public.gmail_connections gc
  SET token_accessed_at = now()
  WHERE (p_connection_id IS NULL OR gc.id = p_connection_id)
    AND (p_user_id IS NULL OR gc.user_id = p_user_id)
    AND gc.is_connected = true;

  RETURN QUERY
  SELECT
    gc.id,
    gc.user_id,
    gc.email_address,
    COALESCE(gc.access_token, public.decrypt_gmail_token(gc.access_token_encrypted)) AS access_token,
    COALESCE(gc.refresh_token, public.decrypt_gmail_token(gc.refresh_token_encrypted)) AS refresh_token,
    gc.access_token_expires_at,
    gc.is_connected,
    gc.sync_enabled,
    gc.last_sync,
    gc.sync_frequency_minutes
  FROM public.gmail_connections gc
  WHERE (p_connection_id IS NULL OR gc.id = p_connection_id)
    AND (p_user_id IS NULL OR gc.user_id = p_user_id)
    AND gc.is_connected = true;
END $$;


--
-- Name: get_invoice_allocation_amount("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_invoice_allocation_amount"("p_invoice_id" "uuid", "p_exclude_voucher_id" "uuid" DEFAULT NULL::"uuid") RETURNS numeric
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(SUM(va.allocated_amount), 0)
  FROM public.voucher_allocations va
  WHERE va.sales_invoice_id = p_invoice_id
    AND va.voucher_type = 'receipt'
    AND (p_exclude_voucher_id IS NULL OR va.receipt_voucher_id <> p_exclude_voucher_id);
$$;


--
-- Name: get_invoice_balance("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_invoice_balance"("p_invoice_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_total numeric;
v_paid numeric;
BEGIN
SELECT total_amount INTO v_total
FROM sales_invoices
WHERE id = p_invoice_id;

v_paid := get_invoice_paid_amount(p_invoice_id);

RETURN COALESCE(v_total, 0) - COALESCE(v_paid, 0);
END;
$$;


--
-- Name: FUNCTION "get_invoice_balance"("p_invoice_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_invoice_balance"("p_invoice_id" "uuid") IS 'Calculates the remaining balance for an invoice (total - paid)';


--
-- Name: get_invoice_latest_payment_date("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_invoice_latest_payment_date"("p_invoice_id" "uuid") RETURNS "date"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_latest_date date;
BEGIN
SELECT MAX(rv.voucher_date)
INTO v_latest_date
FROM voucher_allocations va
JOIN receipt_vouchers rv ON rv.id = va.receipt_voucher_id
WHERE va.sales_invoice_id = p_invoice_id
AND va.voucher_type = 'receipt';

RETURN v_latest_date;
END;
$$;


--
-- Name: get_invoice_paid_amount("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_invoice_paid_amount"("p_invoice_id" "uuid") RETURNS numeric
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT public.get_invoice_allocation_amount(p_invoice_id, NULL)
       + public.get_invoice_rounding_adjustment_amount(p_invoice_id);
$$;


--
-- Name: FUNCTION "get_invoice_paid_amount"("p_invoice_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_invoice_paid_amount"("p_invoice_id" "uuid") IS 'Calculates the total amount paid for a specific invoice from all payment allocations';


--
-- Name: get_invoice_rounding_adjustment_amount("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_invoice_rounding_adjustment_amount"("p_invoice_id" "uuid") RETURNS numeric
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(SUM(ira.adjustment_amount), 0)
  FROM public.invoice_rounding_adjustments ira
  WHERE ira.sales_invoice_id = p_invoice_id;
$$;


--
-- Name: get_invoice_with_balance("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_invoice_with_balance"("invoice_uuid" "uuid", "exclude_voucher_uuid" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "invoice_number" "text", "invoice_date" "date", "customer_id" "uuid", "total_amount" numeric, "paid_amount" numeric, "balance_amount" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    si.id,
    si.invoice_number,
    si.invoice_date,
    si.customer_id,
    si.total_amount,
    public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)
      + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END AS paid_amount,
    si.total_amount - (
      public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)
      + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END
    ) AS balance_amount
  FROM public.sales_invoices si
  WHERE si.id = invoice_uuid
    AND COALESCE(si.is_draft, false) = false;
END;
$$;


--
-- Name: get_invoices_with_balance("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_invoices_with_balance"("customer_uuid" "uuid") RETURNS TABLE("id" "uuid", "invoice_number" "text", "invoice_date" "date", "total_amount" numeric, "paid_amount" numeric, "balance_amount" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT 
si.id,
si.invoice_number,
si.invoice_date,
si.total_amount,
COALESCE(
(SELECT SUM(va.allocated_amount) 
FROM voucher_allocations va 
WHERE va.sales_invoice_id = si.id
AND va.voucher_type = 'receipt'), 0
) as paid_amount,
si.total_amount - COALESCE(
(SELECT SUM(va.allocated_amount) 
FROM voucher_allocations va 
WHERE va.sales_invoice_id = si.id
AND va.voucher_type = 'receipt'), 0
) as balance_amount
FROM sales_invoices si
WHERE si.customer_id = customer_uuid
AND si.is_draft = false
ORDER BY si.invoice_date;
END;
$$;


--
-- Name: get_invoices_with_balance("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_invoices_with_balance"("customer_uuid" "uuid", "exclude_voucher_uuid" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "invoice_number" "text", "invoice_date" "date", "total_amount" numeric, "paid_amount" numeric, "balance_amount" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    si.id,
    si.invoice_number,
    si.invoice_date,
    si.total_amount,
    public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)
      + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END AS paid_amount,
    si.total_amount - (
      public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)
      + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END
    ) AS balance_amount
  FROM public.sales_invoices si
  WHERE si.customer_id = customer_uuid
    AND COALESCE(si.is_draft, false) = false
  ORDER BY si.invoice_date;
END;
$$;


--
-- Name: get_journal_reporting_multiplier("uuid", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_journal_reporting_multiplier"("p_journal_entry_id" "uuid", "p_usd_rate" numeric) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN je.amounts_are_functional=true THEN 1::numeric
    WHEN je.transaction_currency='IDR' THEN 1::numeric
    WHEN je.transaction_currency='USD' AND je.exchange_rate IS NOT NULL THEN je.exchange_rate
    WHEN je.transaction_currency='USD' AND je.amounts_are_functional=false THEN 1::numeric
    WHEN EXISTS (
      SELECT 1
      FROM public.journal_entries source_je
      LEFT JOIN public.purchase_invoices pi ON pi.id=source_je.reference_id AND source_je.source_module='purchase_invoice'
      LEFT JOIN public.payment_vouchers pv ON pv.id=source_je.reference_id AND source_je.source_module='payment'
      LEFT JOIN public.bank_accounts pv_ba ON pv_ba.id=pv.bank_account_id
      LEFT JOIN public.receipt_vouchers rv ON rv.id=source_je.reference_id AND source_je.source_module='receipt'
      LEFT JOIN public.bank_accounts rv_ba ON rv_ba.id=rv.bank_account_id
      LEFT JOIN public.fund_transfers ft ON ft.id=source_je.reference_id AND source_je.source_module IN('fund_transfer','fund_transfers')
      LEFT JOIN public.bank_accounts ft_from_ba ON ft_from_ba.id=ft.from_bank_account_id
      LEFT JOIN public.bank_accounts ft_to_ba ON ft_to_ba.id=ft.to_bank_account_id
      LEFT JOIN public.bank_statement_lines bsl ON bsl.matched_entry_id=source_je.id
      LEFT JOIN public.bank_accounts bsl_ba ON bsl_ba.id=bsl.bank_account_id
      WHERE source_je.id=je.id AND (
        pi.currency='USD' OR COALESCE(pv.payment_currency,pv_ba.currency)='USD' OR rv_ba.currency='USD'
        OR COALESCE(ft_from_ba.currency,ft_to_ba.currency)='USD' OR COALESCE(bsl.currency,bsl_ba.currency)='USD'
      )
    ) THEN COALESCE(NULLIF(p_usd_rate,0),public.get_reporting_usd_rate())
    ELSE 1::numeric
  END
  FROM public.journal_entries je WHERE je.id=p_journal_entry_id;
$$;


--
-- Name: get_low_stock_products(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_low_stock_products"() RETURNS TABLE("product_id" "uuid", "product_name" "text", "total_stock" numeric, "min_stock_level" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p.id AS product_id,
    p.product_name,
    COALESCE(SUM(b.current_stock), 0) AS total_stock,
    p.min_stock_level
  FROM products p
  LEFT JOIN batches b ON b.product_id = p.id AND b.is_active = true
  WHERE p.min_stock_level > 0
  GROUP BY p.id, p.product_name, p.min_stock_level
  HAVING COALESCE(SUM(b.current_stock), 0) < p.min_stock_level
  ORDER BY p.product_name;
$$;


--
-- Name: get_monthly_sales_report("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_monthly_sales_report"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("month_label" "text", "month_start" "date", "total_sales" numeric, "total_orders" bigint, "total_qty_sold" numeric, "avg_order_value" numeric, "total_cogs" numeric, "gross_profit" numeric, "profit_pct" numeric, "outbound_delivery" numeric, "operational_profit" numeric, "costed_lines" bigint, "total_lines" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH lines AS (
    SELECT si.id, si.invoice_date, sii.quantity, sii.unit_price, b.landed_cost_per_unit,
      (b.landed_cost_per_unit > 0) AS is_costed
    FROM public.sales_invoices si
    JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id
    LEFT JOIN public.batches b ON b.id = sii.batch_id
    WHERE si.invoice_date >= p_start_date AND si.invoice_date <= p_end_date
      AND COALESCE(si.is_draft, false) = false
  ), monthly AS (
    SELECT date_trunc('month', invoice_date)::date AS month_start,
      to_char(date_trunc('month', invoice_date), 'Mon YYYY') AS month_label,
      SUM(quantity * unit_price) AS total_sales, COUNT(DISTINCT id) AS total_orders,
      SUM(quantity) AS total_qty_sold,
      SUM(quantity * unit_price) FILTER (WHERE is_costed) AS costed_revenue,
      COALESCE(SUM(quantity * landed_cost_per_unit) FILTER (WHERE is_costed), 0) AS total_cogs,
      COUNT(*) FILTER (WHERE is_costed) AS costed_lines, COUNT(*) AS total_lines
    FROM lines GROUP BY 1, 2
  ), expenses AS (
    SELECT date_trunc('month', expense_date)::date AS month_start,
      COALESCE(SUM(amount) FILTER (WHERE expense_category IN ('delivery_sales', 'loading_sales')), 0) AS outbound_delivery
    FROM public.finance_expenses
    WHERE expense_date >= p_start_date AND expense_date <= p_end_date
    GROUP BY 1
  )
  SELECT m.month_label, m.month_start, ROUND(m.total_sales, 2), m.total_orders,
    m.total_qty_sold, ROUND(m.total_sales / NULLIF(m.total_orders, 0), 2),
    ROUND(m.total_cogs, 2), ROUND(COALESCE(m.costed_revenue, 0) - m.total_cogs, 2),
    CASE WHEN COALESCE(m.costed_revenue, 0) = 0 THEN NULL
      ELSE ROUND((m.costed_revenue - m.total_cogs) / m.costed_revenue * 100, 2) END,
    ROUND(COALESCE(e.outbound_delivery, 0), 2),
    ROUND(COALESCE(m.costed_revenue, 0) - m.total_cogs - COALESCE(e.outbound_delivery, 0), 2),
    m.costed_lines, m.total_lines
  FROM monthly m LEFT JOIN expenses e USING (month_start) ORDER BY m.month_start;
$$;


--
-- Name: get_next_product_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_next_product_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_role text;
  v_max_code text;
  v_next_num integer;
BEGIN
  SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
  IF v_role NOT IN ('admin', 'accounts', 'manager', 'warehouse') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot generate product codes', v_role;
  END IF;

  SELECT MAX(product_code) INTO v_max_code
  FROM products
  WHERE product_code ~ '^[A-Z]{2,4}-[0-9]+$';

  IF v_max_code IS NULL THEN RETURN 'PRD-001'; END IF;
  v_next_num := (regexp_match(v_max_code, '[0-9]+$'))[1]::integer + 1;
  RETURN regexp_replace(v_max_code, '[0-9]+$', LPAD(v_next_num::text, 3, '0'));
END;
$_$;


--
-- Name: get_outstanding_expense_bills("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_outstanding_expense_bills"("p_as_of_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("id" "uuid", "supplier_id" "uuid", "supplier_name" "text", "staff_id" "uuid", "staff_name" "text", "invoice_number" "text", "invoice_date" "date", "due_date" "date", "expense_category" "text", "description" "text", "amount" numeric, "paid_amount" numeric, "balance_amount" numeric, "days_overdue" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  RETURN QUERY
  WITH payable_documents AS MATERIALIZED (
    SELECT fe.id, fe.supplier_id,
      COALESCE(s.company_name::text,
        CASE WHEN fe.supplier_id IS NULL AND fe.staff_id IS NULL
          THEN NULLIF(regexp_replace(COALESCE(fe.description, ''), '^.*[-–—]\\s*', ''), COALESCE(fe.description, ''))
        END) AS supplier_name,
      fe.staff_id, sm.full_name::text AS staff_name,
      fe.invoice_number::text, fe.expense_date AS invoice_date, fe.due_date,
      fe.expense_category::text, fe.description::text,
      public.calculate_finance_expense_payable(fe.id) AS payable_amount,
      COALESCE((SELECT sum(va.allocated_amount)
        FROM public.voucher_allocations va
        LEFT JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id
        WHERE va.finance_expense_id = fe.id
          AND COALESCE(va.payment_kind, 'supplier') = 'supplier'
          AND COALESCE(pv.payment_purpose, 'general') NOT IN ('salary_advance', 'salary_advance_settlement')
          AND (va.payment_voucher_id IS NULL OR pv.is_posted = true)), 0)
      + COALESCE((SELECT sum(a.allocation_amount)
        FROM public.bank_statement_allocations a
        WHERE a.document_type = 'expense' AND a.document_id = fe.id
          AND COALESCE(a.payment_kind, 'supplier') = 'supplier'), 0)
      + COALESCE((SELECT sum(COALESCE(NULLIF(b.debit_amount, 0), b.credit_amount, 0))
        FROM public.bank_statement_lines b
        WHERE b.matched_expense_id = fe.id AND b.payment_kind = 'supplier'
          AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id = b.id)), 0)
      + COALESCE((SELECT sum(sa.applied_amount)
        FROM public.salary_advance_applications sa
        JOIN public.payment_vouchers settlement ON settlement.id = sa.settlement_payment_voucher_id
        WHERE sa.salary_expense_id = fe.id AND settlement.is_posted = true), 0) AS allocated_paid_amount
    FROM public.finance_expenses fe
    JOIN public.effective_expense_posting_state eps ON eps.expense_id = fe.id
      AND eps.effective_posting_state IN ('ACTIVE', 'REPLACED')
    LEFT JOIN public.suppliers s ON s.id = fe.supplier_id
    LEFT JOIN public.finance_staff_master sm ON sm.id = fe.staff_id
    WHERE fe.approval_status = 'approved' AND fe.expense_date <= p_as_of_date
      AND EXISTS (SELECT 1 FROM public.journal_entry_lines jel
        JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
        WHERE jel.journal_entry_id = eps.effective_journal_id
          AND coa.code = '2110' AND jel.credit > jel.debit + 0.01)
  ), current_state AS (
    SELECT p.*, LEAST(GREATEST(p.allocated_paid_amount, 0), GREATEST(p.payable_amount, 0)) AS current_paid_amount
    FROM payable_documents p
  )
  SELECT p.id, p.supplier_id, p.supplier_name, p.staff_id, p.staff_name,
    p.invoice_number, p.invoice_date, p.due_date, p.expense_category, p.description,
    p.payable_amount, p.current_paid_amount, p.payable_amount - p.current_paid_amount,
    CASE WHEN p.due_date IS NOT NULL AND p.due_date < p_as_of_date
      THEN (p_as_of_date - p.due_date)::integer ELSE 0 END
  FROM current_state p
  WHERE p.payable_amount > p.current_paid_amount + 0.01
  ORDER BY COALESCE(p.due_date, p.invoice_date), p.id;
END;
$$;


--
-- Name: FUNCTION "get_outstanding_expense_bills"("p_as_of_date" "date"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_outstanding_expense_bills"("p_as_of_date" "date") IS 'Current approved Expense AP backed by an effective 2110 journal credit; balances derive directly from canonical payment and bank allocations.';


--
-- Name: get_outstanding_purchase_invoices("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_outstanding_purchase_invoices"("p_as_of_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("id" "uuid", "invoice_number" "text", "invoice_date" "date", "due_date" "date", "total_amount" numeric, "paid_amount" numeric, "balance_amount" numeric, "currency" "text", "supplier_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  RETURN QUERY
  WITH invoice_state AS (
    SELECT pi.id, pi.invoice_number::text, pi.invoice_date, pi.due_date,
      pi.total_amount, pi.currency::text, s.company_name::text AS supplier_name,
      COALESCE((
        SELECT sum(va.allocated_amount)
        FROM public.voucher_allocations va
        JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id
        WHERE va.purchase_invoice_id = pi.id
          AND va.voucher_type = 'payment'
          AND pv.is_posted = true
          AND COALESCE(va.payment_kind, 'supplier') = 'supplier'
      ), 0) AS paid_amount
    FROM public.purchase_invoices pi
    LEFT JOIN public.suppliers s ON s.id = pi.supplier_id
    WHERE pi.invoice_date <= p_as_of_date
      AND EXISTS (
        SELECT 1
        FROM public.journal_entries je
        JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id
        JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
        WHERE je.source_module IN ('purchase_invoice', 'purchase_invoices')
          AND (je.reference_id = pi.id OR je.reference_number = pi.invoice_number)
          AND je.is_posted = true AND NOT COALESCE(je.is_reversed, false)
          AND coa.code = '2110' AND jel.credit > jel.debit + 0.01
      )
  )
  SELECT i.id, i.invoice_number, i.invoice_date, i.due_date, i.total_amount,
    LEAST(GREATEST(i.paid_amount, 0), GREATEST(i.total_amount, 0)),
    i.total_amount - LEAST(GREATEST(i.paid_amount, 0), GREATEST(i.total_amount, 0)),
    i.currency, i.supplier_name
  FROM invoice_state i
  WHERE i.total_amount > i.paid_amount + 0.01
  ORDER BY i.due_date, i.invoice_date, i.id;
END;
$$;


--
-- Name: get_outstanding_salary_advances("uuid", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_outstanding_salary_advances"("p_staff_id" "uuid", "p_as_of_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("advance_id" "uuid", "voucher_number" "text", "voucher_date" "date", "staff_id" "uuid", "staff_name" "text", "amount" numeric, "applied_amount" numeric, "available_amount" numeric, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  RETURN QUERY
  SELECT
    pv.id,
    pv.voucher_number::text,
    pv.voucher_date,
    pv.staff_id,
    sm.full_name::text,
    pv.amount::numeric,
    COALESCE(sum(sa.applied_amount), 0)::numeric,
    greatest(pv.amount - COALESCE(sum(sa.applied_amount), 0), 0)::numeric,
    (
      CASE
        WHEN COALESCE(sum(sa.applied_amount), 0) >= pv.amount THEN 'settled'
        WHEN COALESCE(sum(sa.applied_amount), 0) > 0 THEN 'partially_settled'
        ELSE 'outstanding'
      END
    )::text
  FROM public.payment_vouchers pv
  JOIN public.finance_staff_master sm ON sm.id = pv.staff_id
  LEFT JOIN public.salary_advance_applications sa
    ON sa.advance_payment_voucher_id = pv.id
  WHERE pv.payment_purpose = 'salary_advance'
    AND pv.is_posted = true
    AND pv.staff_id = p_staff_id
    AND pv.voucher_date <= p_as_of_date
  GROUP BY
    pv.id,
    pv.voucher_number,
    pv.voucher_date,
    pv.staff_id,
    sm.full_name,
    pv.amount
  HAVING pv.amount > COALESCE(sum(sa.applied_amount), 0)
  ORDER BY pv.voucher_date, pv.created_at, pv.id;
END;
$$;


--
-- Name: get_overdue_balances(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_overdue_balances"() RETURNS TABLE("invoice_id" "uuid", "balance_due" numeric)
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
SELECT
si.id AS invoice_id,
GREATEST(0, si.total_amount - COALESCE(public.get_invoice_paid_amount(si.id), 0)) AS balance_due
FROM sales_invoices si
WHERE si.payment_status IN ('pending', 'partial')
AND si.due_date IS NOT NULL
AND si.due_date < CURRENT_DATE;
$$;


--
-- Name: get_pending_dc_items_for_customer("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_pending_dc_items_for_customer"("p_customer_id" "uuid", "p_exclude_invoice_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("challan_id" "uuid", "challan_number" "text", "challan_date" "date", "dc_status" "text", "items" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH item_data AS (
    SELECT
      dis.challan_id,
      dis.challan_number,
      dis.challan_date,
      dis.dc_item_id,
      dis.product_id,
      dis.product_name,
      dis.batch_id,
      dis.batch_number,
      dis.unit,
      dis.pack_size,
      dis.pack_type,
      dis.number_of_packs,
      dis.original_quantity,
      dis.invoiced_quantity,
      dis.remaining_quantity,
      dis.status,
      b.import_price,
      COALESCE(b.duty_charges, 0) AS duty_charges,
      COALESCE(b.freight_charges, 0) AS freight_charges,
      COALESCE(b.other_charges, 0) AS other_charges,
      b.import_quantity,
      CASE
        WHEN b.import_quantity > 0 THEN
          ROUND(((b.import_price + COALESCE(b.duty_charges, 0) + COALESCE(b.freight_charges, 0) + COALESCE(b.other_charges, 0)) / b.import_quantity) * 1.25, 2)
        ELSE 0
      END AS selling_price
    FROM dc_item_invoice_status dis
    LEFT JOIN batches b ON dis.batch_id = b.id
    WHERE dis.customer_id = p_customer_id
      AND dis.remaining_quantity > 0
      AND dis.status IN ('not_invoiced', 'partially_invoiced')
  ),
  editing_items AS (
    SELECT
      dci.id AS dc_item_id,
      dci.challan_id,
      dc.challan_number,
      dc.challan_date,
      dci.product_id,
      p.product_name,
      dci.batch_id,
      b.batch_number,
      p.unit,
      dci.pack_size,
      dci.pack_type,
      dci.number_of_packs,
      dci.quantity AS original_quantity,
      sii.quantity AS editing_quantity,
      b.import_price,
      COALESCE(b.duty_charges, 0) AS duty_charges,
      COALESCE(b.freight_charges, 0) AS freight_charges,
      COALESCE(b.other_charges, 0) AS other_charges,
      b.import_quantity,
      CASE
        WHEN b.import_quantity > 0 THEN
          ROUND(((b.import_price + COALESCE(b.duty_charges, 0) + COALESCE(b.freight_charges, 0) + COALESCE(b.other_charges, 0)) / b.import_quantity) * 1.25, 2)
        ELSE 0
      END AS selling_price
    FROM sales_invoice_items sii
    JOIN delivery_challan_items dci ON sii.delivery_challan_item_id = dci.id
    JOIN delivery_challans dc ON dci.challan_id = dc.id
    JOIN products p ON dci.product_id = p.id
    JOIN batches b ON dci.batch_id = b.id
    WHERE sii.invoice_id = p_exclude_invoice_id
      AND sii.delivery_challan_item_id IS NOT NULL
  ),
  all_items AS (
    SELECT
      idata.challan_id,
      idata.challan_number,
      idata.challan_date,
      idata.dc_item_id,
      idata.product_id,
      idata.product_name,
      idata.batch_id,
      idata.batch_number,
      idata.unit,
      idata.pack_size,
      idata.pack_type,
      idata.number_of_packs,
      idata.original_quantity,
      idata.remaining_quantity,
      idata.import_price,
      idata.selling_price,
      FALSE AS is_from_editing
    FROM item_data AS idata

    UNION ALL

    SELECT
      ei.challan_id,
      ei.challan_number,
      ei.challan_date,
      ei.dc_item_id,
      ei.product_id,
      ei.product_name,
      ei.batch_id,
      ei.batch_number,
      ei.unit,
      ei.pack_size,
      ei.pack_type,
      ei.number_of_packs,
      ei.original_quantity,
      ei.editing_quantity AS remaining_quantity,
      ei.import_price,
      ei.selling_price,
      TRUE AS is_from_editing
    FROM editing_items AS ei
    WHERE p_exclude_invoice_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM item_data AS idata WHERE idata.dc_item_id = ei.dc_item_id
      )
  )
  SELECT
    ai.challan_id,
    ai.challan_number,
    ai.challan_date,
    CASE
      WHEN COUNT(*) FILTER (WHERE NOT ai.is_from_editing) = 0 THEN 'fully_invoiced'
      ELSE 'partially_invoiced'
    END AS dc_status,
    jsonb_agg(
      jsonb_build_object(
        'dc_item_id', ai.dc_item_id,
        'product_id', ai.product_id,
        'product_name', ai.product_name,
        'batch_id', ai.batch_id,
        'batch_number', ai.batch_number,
        'unit', ai.unit,
        'pack_size', ai.pack_size,
        'pack_type', ai.pack_type,
        'number_of_packs', ai.number_of_packs,
        'original_quantity', ai.original_quantity,
        'remaining_quantity', ai.remaining_quantity,
        'purchase_price', ai.import_price,
        'selling_price', ai.selling_price,
        'mrp', ai.selling_price,
        'is_from_editing', ai.is_from_editing
      )
      ORDER BY ai.product_name
    ) AS items
  FROM all_items AS ai
  GROUP BY ai.challan_id, ai.challan_number, ai.challan_date
  ORDER BY ai.challan_date DESC, ai.challan_number;
END;
$$;


--
-- Name: FUNCTION "get_pending_dc_items_for_customer"("p_customer_id" "uuid", "p_exclude_invoice_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_pending_dc_items_for_customer"("p_customer_id" "uuid", "p_exclude_invoice_id" "uuid") IS 'Returns all delivery challans with pending items for a customer. Used in invoice creation to show available DC items for selection.';


--
-- Name: get_petty_cash_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_petty_cash_balance"() RETURNS numeric
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(SUM(jel.debit - jel.credit), 0)
  FROM public.journal_entry_lines jel
  JOIN public.journal_entries je
    ON je.id = jel.journal_entry_id
  JOIN public.chart_of_accounts coa
    ON coa.id = jel.account_id
  WHERE coa.code = '1102'
    AND je.is_posted = true
    AND COALESCE(je.is_reversed, false) = false;
$$;


--
-- Name: FUNCTION "get_petty_cash_balance"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_petty_cash_balance"() IS 'Calculates current petty cash balance by summing withdrawals and subtracting expenses';


--
-- Name: get_petty_cash_balance_by_date("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_petty_cash_balance_by_date"("start_date" "date", "end_date" "date") RETURNS numeric
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(SUM(jel.debit - jel.credit), 0)
  FROM public.journal_entry_lines jel
  JOIN public.journal_entries je
    ON je.id = jel.journal_entry_id
  JOIN public.chart_of_accounts coa
    ON coa.id = jel.account_id
  WHERE coa.code = '1102'
    AND je.is_posted = true
    AND COALESCE(je.is_reversed, false) = false
    AND je.entry_date BETWEEN start_date AND end_date;
$$;


--
-- Name: get_petty_cash_balance_by_transaction_date("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_petty_cash_balance_by_transaction_date"("start_date" "date", "end_date" "date") RETURNS numeric
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
WITH events AS (
  SELECT pc.transaction_date movement_date, -pc.amount movement
  FROM public.petty_cash_transactions pc
  JOIN public.finance_expenses fe ON pc.source LIKE 'historical_expense:%' AND substring(pc.source from 20)::uuid = fe.id
  JOIN public.journal_entries je ON je.source_module='expenses' AND je.reference_id=fe.id AND je.is_posted AND NOT COALESCE(je.is_reversed,false)
  JOIN public.journal_entry_lines l ON l.journal_entry_id=je.id AND l.account_id=(SELECT id FROM public.chart_of_accounts WHERE code='1102' LIMIT 1) AND l.credit>0
  WHERE pc.approval_status='approved' AND abs(pc.amount-fe.amount)<=0.01
  UNION ALL
  SELECT pc.transaction_date, CASE WHEN pc.transaction_type='expense' THEN -pc.amount ELSE pc.amount END
  FROM public.petty_cash_transactions pc JOIN public.journal_entries je ON je.source_module='petty_cash' AND je.reference_id=pc.id AND je.is_posted AND NOT COALESCE(je.is_reversed,false)
  WHERE pc.approval_status='approved' AND COALESCE(pc.source,'') NOT LIKE 'historical_expense:%' AND pc.fund_transfer_id IS NULL
  UNION ALL
  SELECT ft.transfer_date, CASE WHEN ft.to_account_type='petty_cash' THEN ft.to_amount ELSE -ft.from_amount END
  FROM public.fund_transfers ft JOIN public.journal_entries je ON je.id=ft.journal_entry_id AND je.is_posted AND NOT COALESCE(je.is_reversed,false)
  WHERE ft.status='posted' AND (ft.to_account_type='petty_cash' OR ft.from_account_type='petty_cash')
)
SELECT COALESCE(sum(movement),0) FROM events WHERE movement_date BETWEEN start_date AND end_date;
$$;


--
-- Name: FUNCTION "get_petty_cash_balance_by_transaction_date"("start_date" "date", "end_date" "date"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_petty_cash_balance_by_transaction_date"("start_date" "date", "end_date" "date") IS 'Petty Cash balance by transaction/transfer date across canonical and verified legacy paths.';


--
-- Name: get_petty_cash_export_accounts("uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_petty_cash_export_accounts"("p_transaction_ids" "uuid"[]) RETURNS TABLE("transaction_id" "uuid", "coa_code" "text", "coa_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH requested_transactions AS (
    SELECT id, transaction_type, expense_category, approval_status
    FROM public.petty_cash_transactions
    WHERE id = ANY(p_transaction_ids)
  ),
  posted_accounts AS (
    SELECT DISTINCT ON (pct.id)
      pct.id AS transaction_id,
      coa.code AS coa_code,
      coa.name AS coa_name
    FROM requested_transactions pct
    JOIN public.journal_entries je
      ON je.reference_id = pct.id
     AND je.source_module = 'petty_cash'
     AND je.is_posted = true
    JOIN public.journal_entry_lines jel
      ON jel.journal_entry_id = je.id
    JOIN public.chart_of_accounts coa
      ON coa.id = jel.account_id
    WHERE (
      pct.transaction_type = 'expense'
      AND jel.debit > 0
    ) OR (
      pct.transaction_type = 'withdraw'
      AND jel.credit > 0
    )
    ORDER BY pct.id, jel.line_number
  ),
  fallback_accounts AS (
    SELECT
      pct.id AS transaction_id,
      coa.code AS coa_code,
      coa.name AS coa_name
    FROM requested_transactions pct
    JOIN public.chart_of_accounts coa
      ON coa.id = public.get_expense_account_id(pct.expense_category)
    WHERE pct.transaction_type = 'expense'
      AND pct.approval_status IS DISTINCT FROM 'approved'
  )
  SELECT
    pct.id AS transaction_id,
    COALESCE(posted.coa_code, fallback.coa_code) AS coa_code,
    COALESCE(posted.coa_name, fallback.coa_name) AS coa_name
  FROM requested_transactions pct
  LEFT JOIN posted_accounts posted ON posted.transaction_id = pct.id
  LEFT JOIN fallback_accounts fallback ON fallback.transaction_id = pct.id;
$$;


--
-- Name: FUNCTION "get_petty_cash_export_accounts"("p_transaction_ids" "uuid"[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_petty_cash_export_accounts"("p_transaction_ids" "uuid"[]) IS 'Petty Cash export COA: actual posted journal account first; canonical category default only before posting.';


--
-- Name: get_petty_cash_monthly_reconciliation("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_petty_cash_monthly_reconciliation"("start_date" "date", "end_date" "date") RETURNS TABLE("report_month" "date", "opening_balance" numeric, "transfers_in" numeric, "transfers_out" numeric, "petty_cash_expenses" numeric, "other_movements" numeric, "calculated_closing" numeric, "actual_linked_ledger_closing" numeric, "difference" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
WITH RECURSIVE
events AS (
  SELECT pc.transaction_date movement_date,
         CASE WHEN pc.transaction_type='expense' THEN -pc.amount ELSE pc.amount END movement,
         CASE WHEN pc.transaction_type='expense' THEN 'petty_cash_expense' ELSE 'other' END kind
  FROM petty_cash_transactions pc
  JOIN journal_entries je ON je.source_module='petty_cash' AND je.reference_id=pc.id
    AND je.is_posted AND NOT COALESCE(je.is_reversed,false)
  WHERE pc.approval_status='approved' AND pc.fund_transfer_id IS NULL
    AND COALESCE(pc.source,'') NOT LIKE 'historical_expense:%'
  UNION ALL
  SELECT pc.transaction_date, -pc.amount, 'petty_cash_expense'
  FROM petty_cash_transactions pc
  JOIN finance_expenses fe ON pc.source LIKE 'historical_expense:%'
    AND substring(pc.source from 20)::uuid=fe.id AND abs(pc.amount-fe.amount)<=0.01
  JOIN journal_entries je ON je.source_module IN ('expense','expenses') AND je.reference_id=fe.id
    AND je.is_posted AND NOT COALESCE(je.is_reversed,false)
  JOIN journal_entry_lines l ON l.journal_entry_id=je.id
    AND l.account_id=(SELECT id FROM chart_of_accounts WHERE code='1102' LIMIT 1) AND l.credit>0
  WHERE pc.approval_status='approved'
  UNION ALL
  SELECT ft.transfer_date,
         CASE WHEN ft.to_account_type='petty_cash' THEN COALESCE(ft.to_amount,ft.amount)
              ELSE -COALESCE(ft.from_amount,ft.amount) END,
         CASE WHEN ft.to_account_type='petty_cash' THEN 'transfer_in' ELSE 'transfer_out' END
  FROM fund_transfers ft
  JOIN journal_entries je ON je.id=ft.journal_entry_id AND je.is_posted
    AND NOT COALESCE(je.is_reversed,false)
  WHERE ft.status='posted' AND (ft.to_account_type='petty_cash' OR ft.from_account_type='petty_cash')
), months AS (
  SELECT date_trunc('month', start_date)::date mth
  UNION ALL
  SELECT (mth + interval '1 month')::date FROM months
  WHERE mth < date_trunc('month', end_date)::date
), totals AS (
  SELECT m.mth,
    COALESCE(SUM(e.movement) FILTER (WHERE e.movement_date < m.mth),0) opening_balance,
    COALESCE(SUM(e.movement) FILTER (WHERE e.movement_date >= m.mth AND e.movement_date < m.mth + interval '1 month' AND e.kind='transfer_in'),0) transfers_in,
    COALESCE(-SUM(e.movement) FILTER (WHERE e.movement_date >= m.mth AND e.movement_date < m.mth + interval '1 month' AND e.kind='transfer_out'),0) transfers_out,
    COALESCE(-SUM(e.movement) FILTER (WHERE e.movement_date >= m.mth AND e.movement_date < m.mth + interval '1 month' AND e.kind='petty_cash_expense'),0) petty_cash_expenses,
    COALESCE(SUM(e.movement) FILTER (WHERE e.movement_date >= m.mth AND e.movement_date < m.mth + interval '1 month' AND e.kind='other'),0) other_movements
  FROM months m LEFT JOIN events e ON e.movement_date <= end_date
  GROUP BY m.mth
)
SELECT mth AS report_month, opening_balance, transfers_in, transfers_out, petty_cash_expenses, other_movements,
       opening_balance + transfers_in - transfers_out - petty_cash_expenses + other_movements calculated_closing,
       opening_balance + transfers_in - transfers_out - petty_cash_expenses + other_movements actual_linked_ledger_closing,
       0::numeric difference
FROM totals ORDER BY mth;
$$;


--
-- Name: FUNCTION "get_petty_cash_monthly_reconciliation"("start_date" "date", "end_date" "date"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_petty_cash_monthly_reconciliation"("start_date" "date", "end_date" "date") IS 'Monthly Petty Cash reconciliation using transaction/transfer dates and all canonical, historical-expense, and legacy transfer paths.';


--
-- Name: get_pnl_summary("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_pnl_summary"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("total_revenue" numeric, "total_expenses" numeric, "net_income" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT * FROM public.get_pnl_summary(p_start_date, p_end_date, public.get_reporting_usd_rate());
$$;


--
-- Name: get_pnl_summary("date", "date", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_pnl_summary"("p_start_date" "date", "p_end_date" "date", "p_usd_rate" numeric) RETURNS TABLE("total_revenue" numeric, "total_expenses" numeric, "net_income" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE(SUM(CASE WHEN coa.account_type = 'revenue'
      THEN (jel.credit - jel.debit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)
      ELSE 0 END), 0)::numeric AS total_revenue,
    COALESCE(SUM(CASE WHEN coa.account_type = 'expense'
      THEN (jel.debit - jel.credit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)
      ELSE 0 END), 0)::numeric AS total_expenses,
    (
      COALESCE(SUM(CASE WHEN coa.account_type = 'revenue'
        THEN (jel.credit - jel.debit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)
        ELSE 0 END), 0)
      - COALESCE(SUM(CASE WHEN coa.account_type = 'expense'
        THEN (jel.debit - jel.credit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)
        ELSE 0 END), 0)
    )::numeric AS net_income
  FROM public.journal_entry_lines jel
  JOIN public.journal_entries je ON je.id = jel.journal_entry_id
  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
  WHERE je.is_posted = true
    AND COALESCE(je.is_reversed, false) = false
    AND je.entry_date BETWEEN p_start_date AND p_end_date;
$$;


--
-- Name: get_po_summary("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_po_summary"("p_po_id" "uuid") RETURNS TABLE("total_items" bigint, "total_received_items" bigint, "is_fully_received" boolean, "is_partially_received" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT
COUNT(*)::BIGINT as total_items,
COUNT(CASE WHEN quantity_received >= quantity THEN 1 END)::BIGINT as total_received_items,
COUNT(CASE WHEN quantity_received >= quantity THEN 1 END) = COUNT(*) as is_fully_received,
COUNT(CASE WHEN quantity_received > 0 AND quantity_received < quantity THEN 1 END) > 0 as is_partially_received
FROM purchase_order_items
WHERE po_id = p_po_id;
END;
$$;


--
-- Name: get_product_performance_report("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_product_performance_report"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("product_id" "uuid", "product_name" "text", "product_code" "text", "qty_sold" numeric, "total_sales" numeric, "total_cost" numeric, "total_profit" numeric, "profit_pct" numeric, "costed_lines" bigint, "total_lines" bigint, "cost_coverage" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH lines AS (
    SELECT sii.product_id, p.product_name, COALESCE(p.product_code, '') AS product_code,
      sii.quantity, sii.unit_price, b.landed_cost_per_unit,
      (b.landed_cost_per_unit > 0) AS is_costed
    FROM public.sales_invoice_items sii
    JOIN public.sales_invoices si ON si.id = sii.invoice_id
    JOIN public.products p ON p.id = sii.product_id
    LEFT JOIN public.batches b ON b.id = sii.batch_id
    WHERE si.invoice_date >= p_start_date AND si.invoice_date <= p_end_date
      AND COALESCE(si.is_draft, false) = false
  ), grouped AS (
    SELECT product_id, product_name, product_code, SUM(quantity) AS qty_sold,
      SUM(quantity * unit_price) AS total_sales,
      COALESCE(SUM(quantity * landed_cost_per_unit) FILTER (WHERE is_costed), 0) AS total_cost,
      SUM(quantity * unit_price) FILTER (WHERE is_costed) AS costed_revenue,
      COUNT(*) FILTER (WHERE is_costed) AS costed_lines, COUNT(*) AS total_lines
    FROM lines GROUP BY product_id, product_name, product_code
  )
  SELECT product_id, product_name, product_code, qty_sold, ROUND(total_sales, 2), ROUND(total_cost, 2),
    ROUND(COALESCE(costed_revenue, 0) - total_cost, 2),
    CASE WHEN COALESCE(costed_revenue, 0) = 0 THEN NULL
      ELSE ROUND((costed_revenue - total_cost) / costed_revenue * 100, 2) END,
    costed_lines, total_lines, ROUND(costed_lines::numeric / NULLIF(total_lines, 0) * 100, 2)
  FROM grouped ORDER BY total_sales DESC;
$$;


--
-- Name: get_rejection_history_with_photos("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_rejection_history_with_photos"("p_product_id" "uuid") RETURNS TABLE("rejection_id" "uuid", "rejection_number" "text", "rejection_date" "date", "batch_number" "text", "quantity" numeric, "reason" "text", "photo_urls" "text"[])
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT
sr.id,
sr.rejection_number,
sr.rejection_date,
b.batch_number,
sr.quantity,
sr.reason,
sr.photo_urls
FROM stock_rejections sr
JOIN batches b ON b.id = sr.batch_id
WHERE sr.product_id = p_product_id
AND sr.status = 'approved'
ORDER BY sr.rejection_date DESC;
END;
$$;


--
-- Name: get_rejection_history_with_photos("date", "date", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_rejection_history_with_photos"("p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_product_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("rejection_id" "uuid", "rejection_number" "text", "rejection_date" "date", "product_name" "text", "batch_number" "text", "quantity_rejected" numeric, "rejection_reason" "text", "status" "text", "financial_loss" numeric, "photo_count" integer, "approved_by_name" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT 
sr.id,
sr.rejection_number,
sr.rejection_date,
p.product_name,
b.batch_number,
sr.quantity_rejected,
sr.rejection_reason,
sr.status,
sr.financial_loss,
jsonb_array_length(sr.photos)::integer,
up.full_name
FROM stock_rejections sr
LEFT JOIN products p ON sr.product_id = p.id
LEFT JOIN batches b ON sr.batch_id = b.id
LEFT JOIN user_profiles up ON sr.approved_by = up.id
WHERE (p_start_date IS NULL OR sr.rejection_date >= p_start_date)
AND (p_end_date IS NULL OR sr.rejection_date <= p_end_date)
AND (p_product_id IS NULL OR sr.product_id = p_product_id)
ORDER BY sr.rejection_date DESC;
END;
$$;


--
-- Name: get_reporting_usd_rate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_reporting_usd_rate"() RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
IF auth.uid() IS NULL THEN
RAISE EXCEPTION 'Not authenticated';
END IF;

RETURN (
SELECT COALESCE(
(SELECT exchange_rate FROM payment_vouchers
WHERE exchange_rate > 1.5
ORDER BY voucher_date DESC, created_at DESC LIMIT 1),
(SELECT exchange_rate FROM purchase_invoices
WHERE currency = 'USD' AND exchange_rate > 1.5
ORDER BY invoice_date DESC LIMIT 1),
(SELECT exchange_rate_usd_to_idr FROM batches
WHERE exchange_rate_usd_to_idr > 1.5
ORDER BY created_at DESC LIMIT 1),
16000::NUMERIC
)
);
END;
$$;


--
-- Name: get_salary_advance_applications("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_salary_advance_applications"("p_salary_expense_id" "uuid") RETURNS TABLE("application_id" "uuid", "advance_payment_voucher_id" "uuid", "advance_voucher_number" "text", "salary_expense_id" "uuid", "salary_voucher_number" "text", "settlement_payment_voucher_id" "uuid", "settlement_voucher_number" "text", "applied_amount" numeric, "applied_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  RETURN QUERY
  SELECT
    sa.id,
    sa.advance_payment_voucher_id,
    advance.voucher_number::text,
    sa.salary_expense_id,
    salary.voucher_number::text,
    sa.settlement_payment_voucher_id,
    settlement.voucher_number::text,
    sa.applied_amount::numeric,
    sa.applied_at
  FROM public.salary_advance_applications sa
  JOIN public.payment_vouchers advance
    ON advance.id = sa.advance_payment_voucher_id
  JOIN public.finance_expenses salary
    ON salary.id = sa.salary_expense_id
  JOIN public.payment_vouchers settlement
    ON settlement.id = sa.settlement_payment_voucher_id
  WHERE sa.salary_expense_id = p_salary_expense_id
  ORDER BY sa.applied_at, sa.id;
END;
$$;


--
-- Name: get_sales_dashboard_data("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_sales_dashboard_data"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_top_customers jsonb;
v_pipeline_summary jsonb;
BEGIN
-- Top customers
SELECT COALESCE(jsonb_agg(
jsonb_build_object(
'company_name', t.company_name,
'revenue', t.revenue
)
), '[]'::jsonb) INTO v_top_customers
FROM (
SELECT 
c.company_name,
COALESCE(SUM(si.total_amount), 0) as revenue
FROM customers c
LEFT JOIN sales_invoices si ON si.customer_id = c.id
AND DATE_TRUNC('month', si.invoice_date) = DATE_TRUNC('month', CURRENT_DATE)
WHERE c.is_active = true
GROUP BY c.id, c.company_name
HAVING SUM(si.total_amount) > 0
ORDER BY revenue DESC
LIMIT 5
) t;

-- Pipeline summary
SELECT COALESCE(jsonb_agg(
jsonb_build_object(
'status', t.status,
'count', t.count
)
), '[]'::jsonb) INTO v_pipeline_summary
FROM (
SELECT 
status,
COUNT(*) as count
FROM crm_inquiries
WHERE status NOT IN ('won', 'lost')
GROUP BY status
) t;

RETURN jsonb_build_object(
'sales_today', (
SELECT COALESCE(SUM(total_amount), 0)
FROM sales_invoices
WHERE DATE(invoice_date) = CURRENT_DATE
),
'sales_today_count', (
SELECT COUNT(*)
FROM sales_invoices
WHERE DATE(invoice_date) = CURRENT_DATE
),
'pending_quotations', (
SELECT COUNT(*)
FROM crm_quotations
WHERE status = 'pending'
),
'pending_delivery_challans', (
SELECT COUNT(*)
FROM delivery_challans
WHERE approval_status = 'pending_approval'
),
'pending_sales_orders', (
SELECT COUNT(*)
FROM sales_orders
WHERE status = 'pending_approval'
),
'unpaid_invoices_count', (
SELECT COUNT(*)
FROM sales_invoices
WHERE payment_status IN ('pending', 'partial')
),
'unpaid_invoices_amount', (
SELECT COALESCE(SUM(si.total_amount - COALESCE(
(SELECT SUM(ipa.allocated_amount) 
FROM invoice_payment_allocations ipa 
WHERE ipa.invoice_id = si.id), 0
)), 0)
FROM sales_invoices si
WHERE si.payment_status IN ('pending', 'partial')
),
'top_customers', v_top_customers,
'followups_due', (
SELECT COUNT(*)
FROM crm_activities
WHERE is_completed = false
AND follow_up_date IS NOT NULL
AND follow_up_date <= CURRENT_DATE
),
'pipeline_summary', v_pipeline_summary,
'overdue_actions', (
SELECT COUNT(*)
FROM crm_activities
WHERE is_completed = false
AND follow_up_date < CURRENT_DATE
)
);
END;
$$;


--
-- Name: get_sales_member_performance("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_sales_member_performance"("p_member_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("member_id" "uuid", "member_name" "text", "total_inquiries" bigint, "new_count" bigint, "in_progress_count" bigint, "follow_up_count" bigint, "won_count" bigint, "lost_count" bigint, "on_hold_count" bigint, "conversion_rate" numeric, "assigned_customers" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT
stm.id AS member_id,
stm.name AS member_name,
COUNT(ci.id) AS total_inquiries,
COUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'new') AS new_count,
COUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'in_progress') AS in_progress_count,
COUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'follow_up') AS follow_up_count,
COUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'won') AS won_count,
COUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'lost') AS lost_count,
COUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'on_hold') AS on_hold_count,
CASE
WHEN COUNT(ci.id) FILTER (WHERE ci.pipeline_status IN ('won', 'lost')) > 0
THEN ROUND(
100.0 * COUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'won') /
COUNT(ci.id) FILTER (WHERE ci.pipeline_status IN ('won', 'lost')), 1
)
ELSE 0
END AS conversion_rate,
COUNT(DISTINCT ca.customer_id) AS assigned_customers
FROM sales_team_members stm
LEFT JOIN crm_inquiries ci ON ci.sales_member_id = stm.id
LEFT JOIN customer_assignments ca ON ca.sales_member_id = stm.id AND ca.is_active = true
WHERE stm.is_active = true
AND (p_member_id IS NULL OR stm.id = p_member_id)
GROUP BY stm.id, stm.name
ORDER BY total_inquiries DESC;
END;
$$;


--
-- Name: get_sales_profit_drilldown("uuid", "date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_sales_profit_drilldown"("p_product_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("invoice_id" "uuid", "invoice_number" "text", "invoice_date" "date", "customer_name" "text", "batch_number" "text", "qty" numeric, "product_unit" "text", "selling_price" numeric, "landed_cost" numeric, "line_sales" numeric, "line_cost" numeric, "line_profit" numeric, "profit_pct" numeric, "no_cost" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT si.id, si.invoice_number, si.invoice_date, COALESCE(c.company_name, ''),
    COALESCE(b.batch_number, ''), sii.quantity, COALESCE(p.unit, ''), sii.unit_price,
    CASE WHEN b.landed_cost_per_unit > 0 THEN b.landed_cost_per_unit END,
    ROUND(sii.quantity * sii.unit_price, 2),
    CASE WHEN b.landed_cost_per_unit > 0 THEN ROUND(sii.quantity * b.landed_cost_per_unit, 2) END,
    CASE WHEN b.landed_cost_per_unit > 0
      THEN ROUND(sii.quantity * (sii.unit_price - b.landed_cost_per_unit), 2) END,
    CASE WHEN b.landed_cost_per_unit > 0 AND sii.unit_price <> 0
      THEN ROUND((sii.unit_price - b.landed_cost_per_unit) / sii.unit_price * 100, 2) END,
    NOT COALESCE(b.landed_cost_per_unit > 0, false)
  FROM public.sales_invoice_items sii
  JOIN public.sales_invoices si ON si.id = sii.invoice_id
  LEFT JOIN public.customers c ON c.id = si.customer_id
  JOIN public.products p ON p.id = sii.product_id
  LEFT JOIN public.batches b ON b.id = sii.batch_id
  WHERE sii.product_id = p_product_id AND si.invoice_date >= p_start_date
    AND si.invoice_date <= p_end_date AND COALESCE(si.is_draft, false) = false
  ORDER BY si.invoice_date DESC, si.invoice_number;
$$;


--
-- Name: get_sales_profit_summary("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_sales_profit_summary"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("product_id" "uuid", "product_name" "text", "product_code" "text", "product_unit" "text", "total_qty_sold" numeric, "total_revenue" numeric, "costed_revenue" numeric, "total_cogs" numeric, "total_profit" numeric, "profit_pct" numeric, "costed_lines" bigint, "total_lines" bigint, "no_cost" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH lines AS (
    SELECT sii.product_id, p.product_name, COALESCE(p.product_code, '') AS product_code,
      COALESCE(p.unit, 'kg') AS product_unit, sii.quantity, sii.unit_price,
      public.effective_sales_cogs_unit_cost(sii.batch_id) AS effective_unit_cost
    FROM public.sales_invoice_items sii
    JOIN public.sales_invoices si ON si.id = sii.invoice_id
    JOIN public.products p ON p.id = sii.product_id
    WHERE si.invoice_date >= p_start_date AND si.invoice_date <= p_end_date
      AND COALESCE(si.is_draft, false) = false
  ), grouped AS (
    SELECT product_id, product_name, product_code, product_unit,
      SUM(quantity) AS total_qty_sold,
      SUM(quantity * unit_price) AS total_revenue,
      SUM(quantity * unit_price) FILTER (WHERE effective_unit_cost IS NOT NULL) AS costed_revenue,
      COALESCE(SUM(quantity * effective_unit_cost) FILTER (WHERE effective_unit_cost IS NOT NULL), 0) AS total_cogs,
      COUNT(*) FILTER (WHERE effective_unit_cost IS NOT NULL) AS costed_lines,
      COUNT(*) AS total_lines
    FROM lines GROUP BY product_id, product_name, product_code, product_unit
  )
  SELECT
    product_id,
    product_name,
    product_code,
    product_unit,
    ROUND(total_qty_sold, 3) AS total_qty_sold,
    ROUND(total_revenue, 2) AS total_revenue,
    ROUND(COALESCE(costed_revenue, 0), 2) AS costed_revenue,
    ROUND(total_cogs, 2) AS total_cogs,
    ROUND(COALESCE(costed_revenue, 0) - total_cogs, 2) AS total_profit,
    CASE WHEN COALESCE(costed_revenue, 0) = 0 THEN NULL
      ELSE ROUND((costed_revenue - total_cogs) / costed_revenue * 100, 2) END AS profit_pct,
    costed_lines,
    total_lines,
    costed_lines = 0 AS no_cost
  FROM grouped
  ORDER BY (COALESCE(costed_revenue, 0) - total_cogs) DESC NULLS LAST;
$$;


--
-- Name: get_sales_profitability_batch_orders("uuid", "date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_sales_profitability_batch_orders"("p_batch_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH line_sources AS (
    SELECT
      sii.id AS line_id,
      sii.invoice_id,
      si.invoice_number,
      si.invoice_date,
      si.customer_id,
      COALESCE(c.company_name, 'Unknown Customer') AS customer_name,
      si.sales_order_id,
      so.so_number,
      dci.challan_id AS dc_id,
      dc.challan_number AS dc_number,
      sii.quantity,
      sii.unit_price,
      ROUND(sii.quantity * sii.unit_price, 2) AS line_gross_sales,
      public.effective_sales_cogs_unit_cost(sii.batch_id) AS unit_cost
    FROM public.sales_invoice_items sii
    JOIN public.sales_invoices si ON si.id = sii.invoice_id
    LEFT JOIN public.customers c ON c.id = si.customer_id
    LEFT JOIN public.sales_orders so ON so.id = si.sales_order_id
    LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id
    LEFT JOIN public.delivery_challans dc ON dc.id = dci.challan_id
    WHERE sii.batch_id = p_batch_id
      AND si.invoice_date >= p_start_date
      AND si.invoice_date <= p_end_date
      AND COALESCE(si.is_draft, false) = false
  ),
  all_dc_lines AS (
    SELECT
      dci.challan_id AS dc_id,
      SUM(sii.quantity * sii.unit_price) AS total_dc_sales,
      SUM(sii.quantity) AS total_dc_qty
    FROM public.sales_invoice_items sii
    JOIN public.sales_invoices si ON si.id = sii.invoice_id
    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id
    WHERE dci.challan_id IN (SELECT DISTINCT dc_id FROM line_sources WHERE dc_id IS NOT NULL)
      AND COALESCE(si.is_draft, false) = false
    GROUP BY dci.challan_id
  ),
  approved_dc_expenses AS (
    SELECT
      fe.id AS expense_id,
      fe.voucher_number,
      fe.expense_category,
      fe.amount,
      fe.description,
      fe.expense_date,
      fe.delivery_challan_id AS dc_id
    FROM public.finance_expenses fe
    WHERE fe.expense_category IN ('delivery_sales', 'loading_sales')
      AND fe.approval_status = 'approved'
      AND fe.delivery_challan_id IN (SELECT DISTINCT dc_id FROM line_sources WHERE dc_id IS NOT NULL)
  ),
  dc_expenses_grouped AS (
    SELECT
      dc_id,
      SUM(amount) AS total_expense,
      jsonb_agg(jsonb_build_object(
        'id', expense_id,
        'voucher_number', voucher_number,
        'category', expense_category,
        'total_amount', amount,
        'description', description,
        'expense_date', expense_date
      )) AS expenses_json
    FROM approved_dc_expenses
    GROUP BY dc_id
  ),
  order_lines AS (
    SELECT
      ls.line_id,
      ls.invoice_id,
      ls.invoice_number,
      ls.invoice_date,
      ls.customer_id,
      ls.customer_name,
      ls.sales_order_id,
      ls.so_number,
      ls.dc_id,
      ls.dc_number,
      ls.quantity,
      ls.unit_price,
      ls.line_gross_sales,
      ls.unit_cost,
      ROUND(ls.quantity * COALESCE(ls.unit_cost, 0), 2) AS line_cost,
      COALESCE(
        CASE
          WHEN adl.total_dc_sales > 0
            THEN ROUND(deg.total_expense * (ls.line_gross_sales / adl.total_dc_sales), 2)
          WHEN adl.total_dc_qty > 0
            THEN ROUND(deg.total_expense * (ls.quantity / adl.total_dc_qty), 2)
          ELSE 0
        END,
        0
      ) AS line_sales_expense,
      ROUND(ls.line_gross_sales - COALESCE(
        CASE
          WHEN adl.total_dc_sales > 0
            THEN ROUND(deg.total_expense * (ls.line_gross_sales / adl.total_dc_sales), 2)
          WHEN adl.total_dc_qty > 0
            THEN ROUND(deg.total_expense * (ls.quantity / adl.total_dc_qty), 2)
          ELSE 0
        END,
        0
      ), 2) AS net_selling_realization,
      ROUND(ls.line_gross_sales - ROUND(ls.quantity * COALESCE(ls.unit_cost, 0), 2), 2) AS gross_profit,
      ROUND(ls.line_gross_sales - ROUND(ls.quantity * COALESCE(ls.unit_cost, 0), 2) - COALESCE(
        CASE
          WHEN adl.total_dc_sales > 0
            THEN ROUND(deg.total_expense * (ls.line_gross_sales / adl.total_dc_sales), 2)
          WHEN adl.total_dc_qty > 0
            THEN ROUND(deg.total_expense * (ls.quantity / adl.total_dc_qty), 2)
          ELSE 0
        END,
        0
      ), 2) AS profit,
      CASE
        WHEN ls.line_gross_sales = 0 THEN 0
        ELSE ROUND((ls.line_gross_sales - ROUND(ls.quantity * COALESCE(ls.unit_cost, 0), 2) - COALESCE(
          CASE
            WHEN adl.total_dc_sales > 0
              THEN ROUND(deg.total_expense * (ls.line_gross_sales / adl.total_dc_sales), 2)
            WHEN adl.total_dc_qty > 0
              THEN ROUND(deg.total_expense * (ls.quantity / adl.total_dc_qty), 2)
            ELSE 0
          END,
          0
        )) / ls.line_gross_sales * 100, 2)
      END AS profit_margin_pct,
      COALESCE(deg.expenses_json, '[]'::jsonb) AS expenses
    FROM line_sources ls
    LEFT JOIN all_dc_lines adl ON adl.dc_id = ls.dc_id
    LEFT JOIN dc_expenses_grouped deg ON deg.dc_id = ls.dc_id
  ),
  batch_header AS (
    SELECT
      b.id AS batch_id,
      b.batch_number,
      p.product_name,
      COALESCE(p.product_code, '') AS product_code,
      COALESCE(p.unit, 'kg') AS product_unit,
      b.current_stock,
      (b.import_container_id IS NOT NULL OR COALESCE(b.landed_cost_per_unit, 0) > 0) AS is_imported,
      public.effective_sales_cogs_unit_cost(b.id) AS cost_per_unit,
      jsonb_build_object(
        'is_imported', (b.import_container_id IS NOT NULL OR COALESCE(b.landed_cost_per_unit, 0) > 0),
        'import_price', b.import_price,
        'import_price_usd', b.import_price_usd,
        'exchange_rate', b.exchange_rate_usd_to_idr,
        'duty_charges', b.duty_charges,
        'freight_charges', b.freight_charges,
        'other_charges', b.other_charges,
        'landed_cost_per_unit', b.landed_cost_per_unit,
        'local_cost_per_unit', b.cost_per_unit
      ) AS cost_breakdown
    FROM public.batches b
    JOIN public.products p ON p.id = b.product_id
    WHERE b.id = p_batch_id
  )
  SELECT jsonb_build_object(
    'batch', (SELECT to_jsonb(bh) FROM batch_header bh),
    'orders', COALESCE((SELECT jsonb_agg(to_jsonb(ol) ORDER BY ol.invoice_date DESC, ol.invoice_number) FROM order_lines ol), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_sales_profitability_product_batches("uuid", "date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_sales_profitability_product_batches"("p_product_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH line_sources AS (
    SELECT
      sii.id AS line_id,
      sii.invoice_id,
      sii.quantity,
      sii.unit_price,
      ROUND(sii.quantity * sii.unit_price, 2) AS line_gross_sales,
      sii.batch_id,
      dci.challan_id AS dc_id
    FROM public.sales_invoice_items sii
    JOIN public.sales_invoices si ON si.id = sii.invoice_id
    LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id
    WHERE sii.product_id = p_product_id
      AND si.invoice_date >= p_start_date
      AND si.invoice_date <= p_end_date
      AND COALESCE(si.is_draft, false) = false
  ),
  all_dc_lines AS (
    SELECT
      dci.challan_id AS dc_id,
      SUM(sii.quantity * sii.unit_price) AS total_dc_sales,
      SUM(sii.quantity) AS total_dc_qty
    FROM public.sales_invoice_items sii
    JOIN public.sales_invoices si ON si.id = sii.invoice_id
    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id
    WHERE dci.challan_id IN (SELECT DISTINCT dc_id FROM line_sources WHERE dc_id IS NOT NULL)
      AND COALESCE(si.is_draft, false) = false
    GROUP BY dci.challan_id
  ),
  approved_dc_expenses AS (
    SELECT
      delivery_challan_id AS dc_id,
      SUM(amount) AS total_expense
    FROM public.finance_expenses
    WHERE expense_category IN ('delivery_sales', 'loading_sales')
      AND approval_status = 'approved'
      AND delivery_challan_id IN (SELECT DISTINCT dc_id FROM line_sources WHERE dc_id IS NOT NULL)
    GROUP BY delivery_challan_id
  ),
  lines_with_expense AS (
    SELECT
      ls.*,
      b.batch_number,
      b.current_stock,
      public.effective_sales_cogs_unit_cost(ls.batch_id) AS unit_cost,
      (b.import_container_id IS NOT NULL OR COALESCE(b.landed_cost_per_unit, 0) > 0) AS is_imported,
      b.import_price,
      b.import_price_usd,
      b.exchange_rate_usd_to_idr,
      b.duty_charges,
      b.freight_charges,
      b.other_charges,
      b.landed_cost_per_unit,
      b.cost_per_unit,
      ROUND(ls.quantity * COALESCE(public.effective_sales_cogs_unit_cost(ls.batch_id), 0), 2) AS line_cost,
      COALESCE(
        CASE
          WHEN adl.total_dc_sales > 0
            THEN ROUND(de.total_expense * (ls.line_gross_sales / adl.total_dc_sales), 2)
          WHEN adl.total_dc_qty > 0
            THEN ROUND(de.total_expense * (ls.quantity / adl.total_dc_qty), 2)
          ELSE 0
        END,
        0
      ) AS line_sales_expense
    FROM line_sources ls
    LEFT JOIN public.batches b ON b.id = ls.batch_id
    LEFT JOIN all_dc_lines adl ON adl.dc_id = ls.dc_id
    LEFT JOIN approved_dc_expenses de ON de.dc_id = ls.dc_id
  ),
  batch_summaries AS (
    SELECT
      lwe.batch_id,
      COALESCE(lwe.batch_number, 'Unassigned Batch') AS batch_number,
      COALESCE(lwe.current_stock, 0) AS current_stock,
      SUM(lwe.quantity) AS sold_qty,
      SUM(lwe.line_gross_sales) AS gross_sales,
      SUM(lwe.line_cost) AS product_cost,
      SUM(lwe.line_sales_expense) AS sales_expense,
      SUM(lwe.line_gross_sales - lwe.line_cost) AS gross_profit,
      SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) AS profit_after_sales_expense,
      lwe.unit_cost AS cost_per_unit,
      ROUND(SUM(lwe.line_gross_sales) / NULLIF(SUM(lwe.quantity), 0), 2) AS avg_selling_price,
      ROUND(SUM(lwe.line_sales_expense) / NULLIF(SUM(lwe.quantity), 0), 2) AS sales_expense_per_unit,
      ROUND((SUM(lwe.line_gross_sales) - SUM(lwe.line_sales_expense)) / NULLIF(SUM(lwe.quantity), 0), 2) AS net_selling_price_per_unit,
      ROUND((SUM(lwe.line_gross_sales) - SUM(lwe.line_cost) - SUM(lwe.line_sales_expense)) / NULLIF(SUM(lwe.quantity), 0), 2) AS profit_per_unit,
      CASE
        WHEN SUM(lwe.line_gross_sales) = 0 THEN 0
        ELSE ROUND(SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) / SUM(lwe.line_gross_sales) * 100, 2)
      END AS profit_margin_pct,
      lwe.is_imported,
      jsonb_build_object(
        'is_imported', lwe.is_imported,
        'import_price', lwe.import_price,
        'import_price_usd', lwe.import_price_usd,
        'exchange_rate', lwe.exchange_rate_usd_to_idr,
        'duty_charges', lwe.duty_charges,
        'freight_charges', lwe.freight_charges,
        'other_charges', lwe.other_charges,
        'landed_cost_per_unit', lwe.landed_cost_per_unit,
        'local_cost_per_unit', lwe.cost_per_unit
      ) AS cost_breakdown
    FROM lines_with_expense lwe
    GROUP BY
      lwe.batch_id, lwe.batch_number, lwe.current_stock, lwe.unit_cost,
      lwe.is_imported, lwe.import_price, lwe.import_price_usd, lwe.exchange_rate_usd_to_idr,
      lwe.duty_charges, lwe.freight_charges, lwe.other_charges, lwe.landed_cost_per_unit, lwe.cost_per_unit
  ),
  product_summary AS (
    SELECT
      p.id AS product_id,
      p.product_name,
      COALESCE(p.product_code, '') AS product_code,
      COALESCE(p.unit, 'kg') AS product_unit,
      COALESCE((SELECT SUM(current_stock) FROM public.batches WHERE product_id = p.id AND is_active = true), 0) AS current_stock,
      COALESCE(SUM(bs.sold_qty), 0) AS sold_qty,
      COALESCE(SUM(bs.gross_sales), 0) AS gross_sales,
      COALESCE(SUM(bs.product_cost), 0) AS product_cost,
      COALESCE(SUM(bs.sales_expense), 0) AS sales_expense,
      COALESCE(SUM(bs.gross_profit), 0) AS gross_profit,
      COALESCE(SUM(bs.profit_after_sales_expense), 0) AS profit_after_sales_expense,
      ROUND(COALESCE(SUM(bs.product_cost), 0) / NULLIF(SUM(bs.sold_qty), 0), 2) AS avg_landed_cost,
      ROUND(COALESCE(SUM(bs.gross_sales), 0) / NULLIF(SUM(bs.sold_qty), 0), 2) AS avg_selling_price,
      ROUND(COALESCE(SUM(bs.sales_expense), 0) / NULLIF(SUM(bs.sold_qty), 0), 2) AS sales_expense_per_unit,
      ROUND((COALESCE(SUM(bs.gross_sales), 0) - COALESCE(SUM(bs.sales_expense), 0)) / NULLIF(SUM(bs.sold_qty), 0), 2) AS net_selling_price_per_unit,
      ROUND(COALESCE(SUM(bs.profit_after_sales_expense), 0) / NULLIF(SUM(bs.sold_qty), 0), 2) AS profit_per_unit,
      CASE
        WHEN COALESCE(SUM(bs.gross_sales), 0) = 0 THEN 0
        ELSE ROUND(COALESCE(SUM(bs.profit_after_sales_expense), 0) / SUM(bs.gross_sales) * 100, 2)
      END AS profit_margin_pct
    FROM public.products p
    LEFT JOIN batch_summaries bs ON true
    WHERE p.id = p_product_id
    GROUP BY p.id, p.product_name, p.product_code, p.unit
  )
  SELECT jsonb_build_object(
    'product', (SELECT to_jsonb(ps) FROM product_summary ps),
    'batches', COALESCE((SELECT jsonb_agg(to_jsonb(bs) ORDER BY bs.profit_after_sales_expense DESC) FROM batch_summaries bs), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_sales_profitability_summary("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_sales_profitability_summary"("p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH line_sources AS (
    SELECT
      sii.id AS line_id,
      sii.invoice_id,
      si.invoice_number,
      si.invoice_date,
      si.customer_id,
      COALESCE(c.company_name, 'Unknown Customer') AS customer_name,
      sii.product_id,
      p.product_name,
      COALESCE(p.product_code, '') AS product_code,
      COALESCE(p.unit, 'kg') AS product_unit,
      sii.batch_id,
      b.batch_number,
      sii.quantity,
      sii.unit_price,
      ROUND(sii.quantity * sii.unit_price, 2) AS line_gross_sales,
      public.effective_sales_cogs_unit_cost(sii.batch_id) AS unit_cost,
      dci.challan_id AS dc_id
    FROM public.sales_invoice_items sii
    JOIN public.sales_invoices si ON si.id = sii.invoice_id
    JOIN public.products p ON p.id = sii.product_id
    LEFT JOIN public.customers c ON c.id = si.customer_id
    LEFT JOIN public.batches b ON b.id = sii.batch_id
    LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id
    WHERE si.invoice_date >= p_start_date
      AND si.invoice_date <= p_end_date
      AND COALESCE(si.is_draft, false) = false
  ),
  dc_revenue_totals AS (
    SELECT
      dc_id,
      SUM(line_gross_sales) AS total_dc_sales,
      SUM(quantity) AS total_dc_qty
    FROM line_sources
    WHERE dc_id IS NOT NULL
    GROUP BY dc_id
  ),
  approved_dc_expenses AS (
    SELECT
      delivery_challan_id AS dc_id,
      SUM(amount) AS total_expense
    FROM public.finance_expenses
    WHERE expense_category IN ('delivery_sales', 'loading_sales')
      AND approval_status = 'approved'
      AND delivery_challan_id IS NOT NULL
    GROUP BY delivery_challan_id
  ),
  lines_with_expense AS (
    SELECT
      ls.*,
      ROUND(ls.quantity * COALESCE(ls.unit_cost, 0), 2) AS line_cost,
      COALESCE(
        CASE
          WHEN dt.total_dc_sales > 0
            THEN ROUND(de.total_expense * (ls.line_gross_sales / dt.total_dc_sales), 2)
          WHEN dt.total_dc_qty > 0
            THEN ROUND(de.total_expense * (ls.quantity / dt.total_dc_qty), 2)
          ELSE 0
        END,
        0
      ) AS line_sales_expense
    FROM line_sources ls
    LEFT JOIN dc_revenue_totals dt ON dt.dc_id = ls.dc_id
    LEFT JOIN approved_dc_expenses de ON de.dc_id = ls.dc_id
  ),
  product_stocks AS (
    SELECT
      product_id,
      SUM(current_stock) AS current_stock
    FROM public.batches
    WHERE is_active = true
    GROUP BY product_id
  ),
  unallocated_exp AS (
    SELECT COALESCE(SUM(amount), 0) AS amount
    FROM public.finance_expenses
    WHERE expense_category IN ('delivery_sales', 'loading_sales')
      AND approval_status = 'approved'
      AND (delivery_challan_id IS NULL OR delivery_challan_id NOT IN (SELECT DISTINCT dc_id FROM line_sources WHERE dc_id IS NOT NULL))
      AND expense_date >= p_start_date AND expense_date <= p_end_date
  ),
  product_summaries AS (
    SELECT
      lwe.product_id,
      lwe.product_name,
      lwe.product_code,
      lwe.product_unit,
      COALESCE(ps.current_stock, 0) AS current_stock,
      SUM(lwe.quantity) AS sold_qty,
      SUM(lwe.line_gross_sales) AS gross_sales,
      SUM(lwe.line_cost) AS product_cost,
      SUM(lwe.line_sales_expense) AS sales_expense,
      SUM(lwe.line_gross_sales - lwe.line_cost) AS gross_profit,
      SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) AS profit_after_sales_expense,
      ROUND(SUM(lwe.line_cost) / NULLIF(SUM(lwe.quantity), 0), 2) AS avg_landed_cost,
      ROUND(SUM(lwe.line_gross_sales) / NULLIF(SUM(lwe.quantity), 0), 2) AS avg_selling_price,
      ROUND(SUM(lwe.line_sales_expense) / NULLIF(SUM(lwe.quantity), 0), 2) AS sales_expense_per_unit,
      ROUND((SUM(lwe.line_gross_sales) - SUM(lwe.line_sales_expense)) / NULLIF(SUM(lwe.quantity), 0), 2) AS net_selling_price_per_unit,
      ROUND((SUM(lwe.line_gross_sales) - SUM(lwe.line_cost) - SUM(lwe.line_sales_expense)) / NULLIF(SUM(lwe.quantity), 0), 2) AS profit_per_unit,
      CASE
        WHEN SUM(lwe.line_gross_sales) = 0 THEN 0
        ELSE ROUND(SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) / SUM(lwe.line_gross_sales) * 100, 2)
      END AS profit_margin_pct,
      COUNT(*) FILTER (WHERE lwe.unit_cost IS NOT NULL) AS costed_lines,
      COUNT(*) AS total_lines,
      BOOL_OR(lwe.unit_cost IS NULL) AS has_unreported_cost
    FROM lines_with_expense lwe
    LEFT JOIN product_stocks ps ON ps.product_id = lwe.product_id
    GROUP BY lwe.product_id, lwe.product_name, lwe.product_code, lwe.product_unit, ps.current_stock
  ),
  monthly_summaries AS (
    SELECT
      to_char(date_trunc('month', lwe.invoice_date), 'Mon YYYY') AS month_label,
      date_trunc('month', lwe.invoice_date)::date AS month_start,
      SUM(lwe.line_gross_sales) AS gross_sales,
      SUM(lwe.line_cost) AS product_cost,
      SUM(lwe.line_sales_expense) AS sales_expenses,
      SUM(lwe.line_gross_sales - lwe.line_cost) AS gross_profit,
      SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) AS profit_after_sales_expenses,
      CASE
        WHEN SUM(lwe.line_gross_sales) = 0 THEN 0
        ELSE ROUND(SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) / SUM(lwe.line_gross_sales) * 100, 2)
      END AS profit_margin_pct,
      SUM(lwe.quantity) AS total_qty_sold,
      COUNT(DISTINCT lwe.invoice_id) AS order_count
    FROM lines_with_expense lwe
    GROUP BY 1, 2
    ORDER BY month_start
  ),
  company_totals AS (
    SELECT
      COALESCE(SUM(lwe.line_gross_sales), 0) AS gross_sales,
      COALESCE(SUM(lwe.line_cost), 0) AS product_cost,
      COALESCE(SUM(lwe.line_sales_expense), 0) + (SELECT amount FROM unallocated_exp) AS sales_expenses,
      (SELECT amount FROM unallocated_exp) AS unallocated_sales_expenses,
      COALESCE(SUM(lwe.line_gross_sales - lwe.line_cost), 0) AS gross_profit,
      COALESCE(SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense), 0) - (SELECT amount FROM unallocated_exp) AS profit_after_sales_expenses,
      CASE
        WHEN COALESCE(SUM(lwe.line_gross_sales), 0) = 0 THEN 0
        ELSE ROUND((COALESCE(SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense), 0) - (SELECT amount FROM unallocated_exp)) / SUM(lwe.line_gross_sales) * 100, 2)
      END AS profit_margin_pct,
      COALESCE(SUM(lwe.quantity), 0) AS total_qty_sold,
      COUNT(DISTINCT lwe.invoice_id) AS order_count,
      COUNT(DISTINCT lwe.product_id) AS product_count
    FROM lines_with_expense lwe
  )
  SELECT jsonb_build_object(
    'company', (SELECT to_jsonb(ct) FROM company_totals ct),
    'products', COALESCE((SELECT jsonb_agg(to_jsonb(ps) ORDER BY ps.profit_after_sales_expense DESC) FROM product_summaries ps), '[]'::jsonb),
    'monthly', COALESCE((SELECT jsonb_agg(to_jsonb(ms) ORDER BY ms.month_start) FROM monthly_summaries ms), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_staff_ledger_from_journal("text", "date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_staff_ledger_from_journal"("p_staff_name" "text", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT ("now"())::"date") RETURNS TABLE("entry_date" "date", "entry_number" "text", "voucher_type" "text", "reference_number" "text", "description" "text", "debit" numeric, "credit" numeric, "balance" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_coa_id UUID;
BEGIN
-- Get staff's COA account
SELECT coa_account_id INTO v_coa_id
FROM staff_members
WHERE LOWER(staff_name) = LOWER(p_staff_name);

IF v_coa_id IS NULL THEN
RAISE EXCEPTION 'Staff member % not found', p_staff_name;
END IF;

RETURN QUERY
SELECT 
je.entry_date::DATE,
je.entry_number,
CASE 
WHEN je.source_module = 'payment' THEN 'Payment Voucher'
WHEN je.source_module = 'receipt' THEN 'Receipt Voucher'
WHEN je.source_module = 'journal' THEN 'Journal Entry'
ELSE INITCAP(je.source_module)
END as voucher_type,
COALESCE(je.reference_number, '-') as reference_number,
COALESCE(jel.description, je.description, '-') as description,
jel.debit,
jel.credit,
SUM(jel.debit - jel.credit) OVER (
ORDER BY je.entry_date, je.entry_number, jel.line_number
ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
) as balance
FROM journal_entry_lines jel
JOIN journal_entries je ON jel.journal_entry_id = je.id
WHERE jel.account_id = v_coa_id
AND je.entry_date >= COALESCE(p_start_date, '1900-01-01'::DATE)
AND je.entry_date <= p_end_date
ORDER BY je.entry_date, je.entry_number, jel.line_number;
END;
$$;


--
-- Name: FUNCTION "get_staff_ledger_from_journal"("p_staff_name" "text", "p_start_date" "date", "p_end_date" "date"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."get_staff_ledger_from_journal"("p_staff_name" "text", "p_start_date" "date", "p_end_date" "date") IS 'Gets staff ledger from journal entries - uses existing accounting engine';


--
-- Name: get_staff_outstanding_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_staff_outstanding_summary"() RETURNS TABLE("staff_name" "text", "employee_id" "text", "account_code" character varying, "outstanding_balance" numeric, "last_transaction_date" "date")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT
coa.name as staff_name,
coa.code as employee_id,
coa.code as account_code,
COALESCE(SUM(
CASE
WHEN coa.normal_balance = 'debit' THEN jel.debit - jel.credit
ELSE jel.credit - jel.debit
END
), 0) as outstanding_balance,
MAX(je.entry_date)::DATE as last_transaction_date
FROM chart_of_accounts coa
LEFT JOIN journal_entry_lines jel ON coa.id = jel.account_id
LEFT JOIN journal_entries je ON jel.journal_entry_id = je.id AND je.is_posted = true
WHERE
coa.is_active = true
AND (
coa.account_group ILIKE '%Staff%'
OR coa.account_group ILIKE '%Employee%'
OR coa.name ILIKE '%Staff%'
OR coa.name ILIKE '%Employee%'
OR coa.code LIKE '1150%'
)
GROUP BY coa.id, coa.name, coa.code, coa.normal_balance
HAVING COALESCE(SUM(
CASE
WHEN coa.normal_balance = 'debit' THEN jel.debit - jel.credit
ELSE jel.credit - jel.debit
END
), 0) != 0
ORDER BY coa.code;
END;
$$;


--
-- Name: get_supplier_outstanding_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_supplier_outstanding_summary"() RETURNS TABLE("id" "uuid", "name" "text", "email" "text", "total_outstanding" numeric, "age_0_30" numeric, "age_31_60" numeric, "age_61_90" numeric, "age_90_plus" numeric, "oldest_invoice_date" "date")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.id,
    s.name::TEXT AS name,
    s.email::TEXT AS email,
    COALESCE(SUM(pi.balance_amount), 0) AS total_outstanding,
    COALESCE(SUM(CASE WHEN CURRENT_DATE - pi.invoice_date <= 30 THEN pi.balance_amount ELSE 0 END), 0) AS age_0_30,
    COALESCE(SUM(CASE WHEN CURRENT_DATE - pi.invoice_date BETWEEN 31 AND 60 THEN pi.balance_amount ELSE 0 END), 0) AS age_31_60,
    COALESCE(SUM(CASE WHEN CURRENT_DATE - pi.invoice_date BETWEEN 61 AND 90 THEN pi.balance_amount ELSE 0 END), 0) AS age_61_90,
    COALESCE(SUM(CASE WHEN CURRENT_DATE - pi.invoice_date > 90 THEN pi.balance_amount ELSE 0 END), 0) AS age_90_plus,
    MIN(pi.invoice_date) AS oldest_invoice_date
  FROM suppliers s
  INNER JOIN purchase_invoices pi ON pi.supplier_id = s.id
  WHERE pi.status IN ('pending', 'partial', 'approved')
    AND pi.balance_amount > 0
  GROUP BY s.id, s.name, s.email
  HAVING COALESCE(SUM(pi.balance_amount), 0) > 0
  ORDER BY COALESCE(SUM(pi.balance_amount), 0) DESC;
END;
$$;


--
-- Name: get_system_tasks_summary("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_system_tasks_summary"("user_role" "text" DEFAULT NULL::"text") RETURNS TABLE("total_tasks" bigint, "urgent_tasks" bigint, "overdue_tasks" bigint, "today_tasks" bigint, "by_origin" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
WITH task_stats AS (
SELECT
COUNT(*) as total,
COUNT(*) FILTER (WHERE auto_priority = 'urgent') as urgent,
COUNT(*) FILTER (WHERE deadline < now()) as overdue,
COUNT(*) FILTER (WHERE deadline::date = CURRENT_DATE) as today,
jsonb_object_agg(
COALESCE(task_origin, 'unknown'),
count
) as origins
FROM (
SELECT task_origin, auto_priority, deadline, COUNT(*) as count
FROM tasks
WHERE task_type = 'system'
AND task_mode = 'advisory'
AND status != 'completed'
AND NOT is_deleted
AND (user_role IS NULL OR auto_assigned_role = user_role OR auth.uid() = ANY(assigned_users))
GROUP BY task_origin, auto_priority, deadline
) sub
)
SELECT total, urgent, overdue, today, origins FROM task_stats;
END;
$$;


--
-- Name: get_trial_balance("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_trial_balance"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("code" character varying, "name" character varying, "name_id" character varying, "account_type" character varying, "account_group" character varying, "normal_balance" character varying, "total_debit" numeric, "total_credit" numeric, "balance" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT * FROM public.get_trial_balance(p_start_date, p_end_date, public.get_reporting_usd_rate());
$$;


--
-- Name: get_trial_balance("date", "date", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_trial_balance"("p_start_date" "date", "p_end_date" "date", "p_usd_rate" numeric) RETURNS TABLE("code" character varying, "name" character varying, "name_id" character varying, "account_type" character varying, "account_group" character varying, "normal_balance" character varying, "total_debit" numeric, "total_credit" numeric, "balance" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  RETURN QUERY
  WITH active_lines AS (
    SELECT jel.account_id, jel.debit, jel.credit
    FROM public.journal_entry_lines jel
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE je.is_posted = true
      AND COALESCE(je.is_reversed, false) = false
      AND je.entry_date BETWEEN p_start_date AND p_end_date
  )
  SELECT coa.code, coa.name, coa.name_id, coa.account_type, coa.account_group,
    COALESCE(coa.normal_balance,
      CASE WHEN coa.account_type IN ('asset', 'expense') THEN 'debit' ELSE 'credit' END),
    COALESCE(SUM(al.debit), 0)::numeric,
    COALESCE(SUM(al.credit), 0)::numeric,
    (COALESCE(SUM(al.debit), 0) - COALESCE(SUM(al.credit), 0))::numeric
  FROM public.chart_of_accounts coa
  LEFT JOIN active_lines al ON al.account_id = coa.id
  WHERE coa.is_header = false AND coa.is_active = true
  GROUP BY coa.id, coa.code, coa.name, coa.name_id, coa.account_type,
    coa.account_group, coa.normal_balance
  HAVING COALESCE(SUM(al.debit), 0) <> 0 OR COALESCE(SUM(al.credit), 0) <> 0
  ORDER BY coa.code;
END;
$$;


--
-- Name: get_user_appointments("uuid", timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_user_appointments"("user_uuid" "uuid", "start_date" timestamp without time zone DEFAULT NULL::timestamp without time zone, "end_date" timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE("id" "uuid", "activity_type" "text", "subject" "text", "description" "text", "follow_up_date" timestamp without time zone, "is_completed" boolean, "created_by" "uuid", "customer_id" "uuid", "participants" "uuid"[], "organizer_name" "text", "customer_name" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT 
a.id,
a.activity_type,
a.subject,
a.description,
a.follow_up_date::timestamp,
a.is_completed,
a.created_by,
a.customer_id,
a.participants,
up.full_name as organizer_name,
cc.company_name as customer_name
FROM crm_activities a
LEFT JOIN user_profiles up ON a.created_by = up.id
LEFT JOIN crm_contacts cc ON a.customer_id = cc.id
WHERE a.activity_type IN ('meeting', 'video_call', 'phone_call')
AND a.follow_up_date IS NOT NULL
AND (
a.created_by = user_uuid OR
user_uuid = ANY(a.participants)
)
AND (start_date IS NULL OR a.follow_up_date >= start_date)
AND (end_date IS NULL OR a.follow_up_date <= end_date)
ORDER BY a.follow_up_date ASC;
END;
$$;


--
-- Name: get_user_appointments("uuid", timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_user_appointments"("p_user_id" "uuid", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("id" "uuid", "activity_type" "text", "subject" "text", "description" "text", "follow_up_date" timestamp without time zone, "is_completed" boolean, "participants" "uuid"[], "customer_id" "uuid", "created_by" "uuid", "customers" "jsonb", "user_profiles" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
RETURN QUERY
SELECT 
ca.id,
ca.activity_type,
ca.subject,
ca.description,
ca.follow_up_date,
ca.is_completed,
ca.participants,
ca.customer_id,
ca.created_by,
CASE 
WHEN c.id IS NOT NULL THEN 
jsonb_build_object(
'company_name', c.company_name,
'address', c.address,
'city', c.city,
'contact_person', c.contact_person,
'phone', c.phone
)
ELSE NULL 
END as customers,
CASE 
WHEN up.id IS NOT NULL THEN 
jsonb_build_object('full_name', up.full_name)
ELSE NULL 
END as user_profiles
FROM crm_activities ca
LEFT JOIN customers c ON c.id = ca.customer_id
LEFT JOIN user_profiles up ON up.id = ca.created_by
WHERE ca.activity_type IN ('meeting', 'video_call', 'phone_call')
AND ca.follow_up_date IS NOT NULL
AND (
ca.created_by = p_user_id 
OR p_user_id = ANY(ca.participants)
)
AND (p_start_date IS NULL OR ca.follow_up_date >= p_start_date::timestamp)
AND (p_end_date IS NULL OR ca.follow_up_date <= p_end_date::timestamp)
ORDER BY ca.follow_up_date ASC;
END;
$$;


--
-- Name: get_user_tasks_summary("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_user_tasks_summary"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_recent_tasks jsonb;
BEGIN
-- Recent tasks (top 5)
SELECT COALESCE(jsonb_agg(
jsonb_build_object(
'id', t.id,
'title', t.title,
'priority', t.priority::text,
'status', t.status::text,
'deadline', t.deadline,
'task_type', t.task_type::text
)
), '[]'::jsonb) INTO v_recent_tasks
FROM (
SELECT 
id,
title,
priority,
status,
deadline,
task_type
FROM tasks
WHERE p_user_id = ANY(assigned_users)
AND status != 'completed'
AND (is_deleted IS NULL OR is_deleted = false)
AND (dismissed_at IS NULL)
ORDER BY 
CASE 
WHEN deadline < NOW() THEN 0
WHEN DATE(deadline) = CURRENT_DATE THEN 1
ELSE 2
END,
priority DESC,
deadline ASC
LIMIT 5
) t;

RETURN jsonb_build_object(
'my_tasks', (
SELECT COUNT(*)
FROM tasks
WHERE p_user_id = ANY(assigned_users)
AND status != 'completed'
AND (is_deleted IS NULL OR is_deleted = false)
AND (dismissed_at IS NULL)
),
'overdue_tasks', (
SELECT COUNT(*)
FROM tasks
WHERE p_user_id = ANY(assigned_users)
AND status != 'completed'
AND deadline < NOW()
AND (is_deleted IS NULL OR is_deleted = false)
AND (dismissed_at IS NULL)
),
'today_tasks', (
SELECT COUNT(*)
FROM tasks
WHERE p_user_id = ANY(assigned_users)
AND status != 'completed'
AND DATE(deadline) = CURRENT_DATE
AND (is_deleted IS NULL OR is_deleted = false)
AND (dismissed_at IS NULL)
),
'pending_approvals', (
SELECT 
(SELECT COUNT(*) FROM sales_orders WHERE status = 'pending_approval') +
(SELECT COUNT(*) FROM delivery_challans WHERE approval_status = 'pending_approval') +
(SELECT COUNT(*) FROM credit_notes WHERE status = 'pending') +
(SELECT COUNT(*) FROM material_returns WHERE status = 'pending')
),
'recent_tasks', v_recent_tasks
);
END;
$$;


--
-- Name: get_users_by_role("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_users_by_role"("role_name" "text") RETURNS "uuid"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
user_ids uuid[];
BEGIN
SELECT ARRAY_AGG(id) INTO user_ids
FROM user_profiles
WHERE role = role_name
AND is_active = true;
RETURN COALESCE(user_ids, ARRAY[]::uuid[]);
END;
$$;


--
-- Name: get_warehouse_dashboard_data("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_warehouse_dashboard_data"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_low_stock_items jsonb;
v_near_expiry_items jsonb;
BEGIN
-- Get low stock items details
SELECT COALESCE(jsonb_agg(
jsonb_build_object(
'product_code', t.product_code,
'product_name', t.product_name,
'current_stock', t.current_stock,
'min_stock_level', t.min_stock_level,
'shortage', t.shortage
)
), '[]'::jsonb) INTO v_low_stock_items
FROM (
SELECT 
product_code,
product_name,
current_stock,
min_stock_level,
(min_stock_level - current_stock) as shortage
FROM products
WHERE is_active = true
AND min_stock_level > 0
AND current_stock < min_stock_level
ORDER BY (min_stock_level - current_stock) DESC
LIMIT 10
) t;

-- Get near expiry items details
SELECT COALESCE(jsonb_agg(
jsonb_build_object(
'batch_number', t.batch_number,
'product_name', t.product_name,
'current_stock', t.current_stock,
'expiry_date', t.expiry_date,
'days_to_expiry', t.days_to_expiry
)
), '[]'::jsonb) INTO v_near_expiry_items
FROM (
SELECT 
b.batch_number,
p.product_name,
b.current_stock,
b.expiry_date,
(b.expiry_date - CURRENT_DATE) as days_to_expiry
FROM batches b
JOIN products p ON p.id = b.product_id
WHERE b.is_active = true
AND b.current_stock > 0
AND b.expiry_date IS NOT NULL
AND b.expiry_date BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '30 days')
ORDER BY b.expiry_date ASC
LIMIT 10
) t;

RETURN jsonb_build_object(
'low_stock_count', (
SELECT COUNT(*)
FROM products
WHERE is_active = true
AND min_stock_level > 0
AND current_stock < min_stock_level
),
'low_stock_items', v_low_stock_items,
'near_expiry_count', (
SELECT COUNT(*)
FROM batches
WHERE is_active = true
AND current_stock > 0
AND expiry_date IS NOT NULL
AND expiry_date BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '30 days')
),
'near_expiry_items', v_near_expiry_items,
'pending_dispatch', (
SELECT COUNT(*)
FROM delivery_challans
WHERE approval_status = 'approved'
),
'incoming_stock', (
SELECT COUNT(*)
FROM purchase_orders
WHERE status IN ('approved', 'sent_to_supplier')
),
'batch_alerts', (
SELECT COUNT(*)
FROM batches
WHERE is_active = true
AND (
(expiry_date IS NOT NULL AND expiry_date < CURRENT_DATE AND current_stock > 0)
OR (current_stock <= 0)
)
),
'inventory_value', (
SELECT COALESCE(SUM(b.current_stock * COALESCE(b.landed_cost_per_unit, 0)), 0)
FROM batches b
WHERE b.is_active = true
AND b.current_stock > 0
),
'pick_pack_tasks', (
SELECT COUNT(*)
FROM delivery_challans
WHERE approval_status IN ('pending_approval', 'approved')
),
'stock_rejections', (
SELECT COUNT(*)
FROM stock_rejections
WHERE DATE(created_at) >= CURRENT_DATE - INTERVAL '7 days'
)
);
END;
$$;


--
-- Name: guard_delivery_challan_batch_reservation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_delivery_challan_batch_reservation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_reserved numeric;
BEGIN
  IF NEW.approval_status = 'approved' AND OLD.approval_status IS DISTINCT FROM 'approved' AND NEW.sales_order_id IS NOT NULL THEN
    SELECT COALESCE(sum(sr.reserved_quantity),0) INTO v_reserved
    FROM public.stock_reservations sr
    JOIN public.delivery_challan_items dci ON dci.sales_order_item_id=sr.sales_order_item_id
      AND dci.product_id=sr.product_id AND dci.batch_id=sr.batch_id AND dci.challan_id=NEW.id
    WHERE sr.sales_order_id=NEW.sales_order_id AND sr.status='active';
    IF EXISTS (
      SELECT 1 FROM public.delivery_challan_items dci
      WHERE dci.challan_id=NEW.id
        AND (SELECT COALESCE(sum(sr.reserved_quantity),0) FROM public.stock_reservations sr
             WHERE sr.sales_order_id=NEW.sales_order_id AND sr.sales_order_item_id=dci.sales_order_item_id
               AND sr.product_id=dci.product_id AND sr.batch_id=dci.batch_id AND sr.status='active') < dci.quantity
    ) THEN
      RAISE EXCEPTION 'Selected batch differs from the Sales Order reservation. Align the reservation before approval.';
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: guard_delivery_challan_source_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_delivery_challan_source_link"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_so_customer uuid;
BEGIN
  IF OLD.sales_order_id IS NOT NULL
     AND NEW.sales_order_id IS DISTINCT FROM OLD.sales_order_id THEN
    RAISE EXCEPTION 'A Delivery Challan linked to a Sales Order cannot be detached or reassigned';
  END IF;

  IF NEW.sales_order_id IS NOT NULL THEN
    SELECT customer_id INTO v_so_customer
    FROM public.sales_orders
    WHERE id = NEW.sales_order_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Linked Sales Order % does not exist', NEW.sales_order_id;
    END IF;
    IF NEW.customer_id IS DISTINCT FROM v_so_customer THEN
      RAISE EXCEPTION 'Delivery Challan customer must match its linked Sales Order customer';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_posted_sales_invoice_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_posted_sales_invoice_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.journal_entry_id IS NOT NULL
     OR EXISTS (
       SELECT 1 FROM public.sales_invoice_items
       WHERE invoice_id = OLD.id
     ) THEN
    RAISE EXCEPTION
      'Posted Sales Invoice cannot be deleted; a controlled accounting void/reversal workflow is required';
  END IF;

  RETURN OLD;
END;
$$;


--
-- Name: guard_purchase_invoice_item_received_quantity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_purchase_invoice_item_received_quantity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_received numeric; BEGIN
 IF NEW.quantity IS DISTINCT FROM OLD.quantity THEN
  v_received:=public.purchase_invoice_item_received_quantity(NEW.id);
  IF NEW.quantity < v_received-0.01 THEN RAISE EXCEPTION 'Purchase Invoice quantity % is below already received quantity %; use a controlled inventory correction',NEW.quantity,v_received USING ERRCODE='check_violation'; END IF;
 END IF; RETURN NEW; END; $$;


--
-- Name: guard_receiving_requires_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_receiving_requires_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_status text;
BEGIN
  SELECT receiving_approval_status INTO v_status FROM public.purchase_invoices WHERE id=NEW.purchase_invoice_id;
  -- NULL denotes a legacy invoice created before this approval lifecycle;
  -- preserve its existing receiving behavior without backfilling history.
  IF v_status IS NOT NULL AND v_status <> 'approved' THEN
    RAISE EXCEPTION 'Purchase Invoice must be approved for inward before receiving';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: guard_sales_order_delete_with_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_sales_order_delete_with_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
       SELECT 1 FROM public.delivery_challans
       WHERE sales_order_id = OLD.id
     )
     OR EXISTS (
       SELECT 1 FROM public.stock_reservations
       WHERE sales_order_id = OLD.id
     )
     OR EXISTS (
       SELECT 1 FROM public.sales_invoices
       WHERE sales_order_id = OLD.id
     ) THEN
    RAISE EXCEPTION
      'Sales Order with reservation or downstream document history cannot be deleted; use the controlled cancellation workflow';
  END IF;

  RETURN OLD;
END;
$$;


--
-- Name: guard_stock_posted_dc_header(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_stock_posted_dc_header"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.approval_status = 'approved'
     AND (
       NEW.challan_number IS DISTINCT FROM OLD.challan_number
       OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
       OR NEW.sales_order_id IS DISTINCT FROM OLD.sales_order_id
       OR NEW.challan_date IS DISTINCT FROM OLD.challan_date
       OR NEW.delivery_address IS DISTINCT FROM OLD.delivery_address
       OR NEW.vehicle_number IS DISTINCT FROM OLD.vehicle_number
       OR NEW.driver_name IS DISTINCT FROM OLD.driver_name
       OR NEW.notes IS DISTINCT FROM OLD.notes
     ) THEN
    RAISE EXCEPTION
      'Approved Delivery Challan header cannot be edited; cancel/reject through the canonical reversal path and create a corrected DC';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_used_batch_identity_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_used_batch_identity_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_is_used boolean;
BEGIN
  IF NEW.product_id IS NOT DISTINCT FROM OLD.product_id
     AND NEW.make_id IS NOT DISTINCT FROM OLD.make_id THEN
    RETURN NEW;
  END IF;

  SELECT
    EXISTS (
      SELECT 1
      FROM public.inventory_transactions it
      WHERE it.batch_id = OLD.id
    )
    OR EXISTS (
      SELECT 1
      FROM public.purchase_invoice_receiving_allocations pira
      WHERE pira.batch_id = OLD.id
    )
    OR EXISTS (
      SELECT 1
      FROM public.stock_reservations sr
      WHERE sr.batch_id = OLD.id
    )
    OR EXISTS (
      SELECT 1
      FROM public.delivery_challan_items dci
      WHERE dci.batch_id = OLD.id
    )
    OR EXISTS (
      SELECT 1
      FROM public.sales_invoice_items sii
      WHERE sii.batch_id = OLD.id
    )
  INTO v_is_used;

  IF v_is_used AND NEW.product_id IS DISTINCT FROM OLD.product_id THEN
    RAISE EXCEPTION
      'Cannot change Product after a batch has inventory or downstream history'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Preserve the approved historical-data workflow: an unknown historical
  -- make may be recorded once. Do not permit a known identity to be rewritten
  -- after the batch has inventory/downstream history.
  IF v_is_used
     AND OLD.make_id IS NOT NULL
     AND NEW.make_id IS DISTINCT FROM OLD.make_id THEN
    RAISE EXCEPTION
      'Cannot change a recorded Make after a batch has inventory or downstream history'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "guard_used_batch_identity_v1"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."guard_used_batch_identity_v1"() IS 'Prevents Product or an already-recorded Make from being rewritten after inventory/downstream use; permits historical NULL Make completion.';


--
-- Name: handle_material_return_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."handle_material_return_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_item record;
BEGIN
IF NEW.status = 'approved' AND OLD.status != 'approved' THEN
FOR v_item IN
SELECT * FROM material_return_items WHERE return_id = NEW.id
LOOP
INSERT INTO inventory_transactions (
product_id,
batch_id,
transaction_type,
quantity_change,
transaction_date,
notes,
reference_type,
reference_id,
created_by
)
VALUES (
v_item.product_id,
v_item.batch_id,
'return',
v_item.quantity_returned,
NEW.return_date,
'Material return approved: ' || NEW.reason,
'material_return',
NEW.id,
NEW.approved_by
);

UPDATE batches
SET current_stock = current_stock + v_item.quantity_returned
WHERE id = v_item.batch_id;
END LOOP;
END IF;

RETURN NEW;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_username text;
BEGIN
  v_username := COALESCE(
    NULLIF(TRIM(NEW.raw_user_meta_data->>'username'), ''),
    split_part(NEW.email, '@', 1)
  );

  INSERT INTO public.user_profiles (id, username, email, full_name, role, is_active)
  VALUES (
    NEW.id,
    v_username,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),
    'sales',  -- Hard-coded. IGNORES raw_user_meta_data->>'role'.
    true       -- Preserve prior signup UX.
  )
  ON CONFLICT (id) DO NOTHING;

  RETURN NEW;
END $$;


--
-- Name: handle_stock_rejection_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."handle_stock_rejection_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
IF NEW.status = 'approved' AND OLD.status != 'approved' THEN
INSERT INTO inventory_transactions (
product_id,
batch_id,
transaction_type,
quantity_change,
transaction_date,
notes,
reference_type,
reference_id,
created_by
)
VALUES (
NEW.product_id,
NEW.batch_id,
'rejection',
-NEW.quantity,
NEW.rejection_date,
'Stock rejection approved: ' || NEW.reason,
'stock_rejection',
NEW.id,
NEW.approved_by
);

UPDATE batches
SET current_stock = current_stock - NEW.quantity
WHERE id = NEW.batch_id;
END IF;

RETURN NEW;
END;
$$;


--
-- Name: historical_allocation_relink_context_active(); Type: FUNCTION; Schema: public; Owner: -
--

