--
-- Name: historical_repair_context_active(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."historical_repair_context_active"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(current_setting('app.finance_historical_repair','true'),'off')='on'
