--
-- Name: lookup_email_by_username("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."lookup_email_by_username"("p_username" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email TEXT;
BEGIN
  SELECT email INTO v_email
  FROM user_profiles
  WHERE lower(username) = lower(p_username)
    AND is_active = true;
  RETURN v_email;
END;
$$;


--
-- Name: lookup_login_email("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."lookup_login_email"("p_username" "text") RETURNS TABLE("email" "text", "is_active" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT up.email, up.is_active
  FROM public.user_profiles up
  WHERE lower(up.username) = lower(trim(p_username))
  LIMIT 1;
$$;


--
-- Name: manually_post_pending_fund_transfers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."manually_post_pending_fund_transfers"() RETURNS TABLE("transfer_num" "text", "post_status" "text", "post_message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_transfer RECORD;
v_from_account_id UUID;
v_to_account_id UUID;
v_from_currency TEXT;
v_to_currency TEXT;
v_journal_id UUID;
v_entry_number TEXT;
v_description TEXT;
v_from_amount NUMERIC;
v_to_amount NUMERIC;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot manually post fund transfers', v_role;
END IF;

FOR v_transfer IN
SELECT * FROM fund_transfers WHERE fund_transfers.status = 'pending' ORDER BY fund_transfers.created_at ASC
LOOP
BEGIN
SELECT generate_journal_entry_number() INTO v_entry_number;

IF v_transfer.from_account_type = 'petty_cash' THEN
SELECT id, 'IDR' INTO v_from_account_id, v_from_currency FROM chart_of_accounts WHERE code = '1102' LIMIT 1;
ELSIF v_transfer.from_account_type = 'cash_on_hand' THEN
SELECT id, 'IDR' INTO v_from_account_id, v_from_currency FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
ELSIF v_transfer.from_account_type = 'bank' THEN
SELECT coa_id, currency INTO v_from_account_id, v_from_currency FROM bank_accounts WHERE id = v_transfer.from_bank_account_id;
END IF;

IF v_transfer.to_account_type = 'petty_cash' THEN
SELECT id, 'IDR' INTO v_to_account_id, v_to_currency FROM chart_of_accounts WHERE code = '1102' LIMIT 1;
ELSIF v_transfer.to_account_type = 'cash_on_hand' THEN
SELECT id, 'IDR' INTO v_to_account_id, v_to_currency FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
ELSIF v_transfer.to_account_type = 'bank' THEN
SELECT coa_id, currency INTO v_to_account_id, v_to_currency FROM bank_accounts WHERE id = v_transfer.to_bank_account_id;
END IF;

IF v_from_account_id IS NULL OR v_to_account_id IS NULL THEN
transfer_num  := v_transfer.transfer_number;
post_status   := 'ERROR';
post_message  := 'Cannot determine chart of accounts';
RETURN NEXT;
CONTINUE;
END IF;

v_from_amount := v_transfer.from_amount;
v_to_amount   := v_transfer.to_amount;

v_description := 'Fund Transfer ' || v_transfer.transfer_number;
IF v_from_currency != v_to_currency THEN
v_description := v_description || ' (FX: ' || v_from_currency || ' → ' || v_to_currency || ')';
END IF;
IF v_transfer.description IS NOT NULL THEN
v_description := v_description || ' - ' || v_transfer.description;
END IF;

INSERT INTO journal_entries (
entry_number, entry_date, source_module, reference_id, reference_number,
description, total_debit, total_credit, is_posted, created_by
) VALUES (
v_entry_number, v_transfer.transfer_date, 'fund_transfers', v_transfer.id, v_transfer.transfer_number,
v_description, v_from_amount, v_from_amount, true, v_transfer.created_by
) RETURNING id INTO v_journal_id;

IF v_from_currency = v_to_currency THEN
INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
VALUES
(v_journal_id, 1, v_to_account_id,   v_from_amount, 0,             'Transfer In: '  || v_transfer.transfer_number),
(v_journal_id, 2, v_from_account_id, 0,             v_from_amount, 'Transfer Out: ' || v_transfer.transfer_number);
ELSE
INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
VALUES
(v_journal_id, 1, v_to_account_id,   v_from_amount, 0,
'Transfer In: '  || v_transfer.transfer_number || ' (' || v_to_currency   || ' ' || v_to_amount::TEXT   || ')'),
(v_journal_id, 2, v_from_account_id, 0,             v_from_amount,
'Transfer Out: ' || v_transfer.transfer_number || ' (' || v_from_currency || ' ' || v_from_amount::TEXT || ')');
END IF;

UPDATE fund_transfers
SET journal_entry_id = v_journal_id, status = 'posted', posted_at = now(), posted_by = v_transfer.created_by
WHERE id = v_transfer.id;

transfer_num := v_transfer.transfer_number;
post_status  := 'POSTED';
post_message := 'Successfully posted';
RETURN NEXT;

EXCEPTION WHEN OTHERS THEN
transfer_num := v_transfer.transfer_number;
post_status  := 'ERROR';
post_message := SQLERRM;
RETURN NEXT;
END;
END LOOP;
END;
$$;


--
-- Name: mark_requirement_sent("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mark_requirement_sent"("inquiry_id" "uuid", "requirement_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts','sales') THEN
RAISE EXCEPTION 'Permission denied: role % cannot mark requirements as sent', v_role;
END IF;

CASE requirement_type
WHEN 'price'         THEN UPDATE crm_inquiries SET price_sent_at = now() WHERE id = inquiry_id;
WHEN 'coa'           THEN UPDATE crm_inquiries SET coa_sent_at = now() WHERE id = inquiry_id;
WHEN 'sample'        THEN UPDATE crm_inquiries SET sample_sent_at = now() WHERE id = inquiry_id;
WHEN 'agency_letter' THEN UPDATE crm_inquiries SET agency_letter_sent_at = now() WHERE id = inquiry_id;
ELSE RAISE EXCEPTION 'Invalid requirement type: %', requirement_type;
END CASE;
END;
$$;


--
-- Name: mark_tax_payment_reconciled("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mark_tax_payment_reconciled"("p_tax_payment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE tax_payments
    SET status = 'reconciled', updated_at = now()
    WHERE id = p_tax_payment_id AND status = 'posted';

  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)
  VALUES (auth.uid(), 'tax_payments', 'update', p_tax_payment_id,
          jsonb_build_object('status','reconciled'));
END $$;


--
-- Name: move_expense_to_petty_cash("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."move_expense_to_petty_cash"("p_expense_id" "uuid", "p_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_expense          RECORD;
v_pc_number        TEXT;
v_petty_cash_tx_id UUID;
v_role             text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot move expenses to petty cash', v_role;
END IF;

SELECT * INTO v_expense FROM finance_expenses WHERE id = p_expense_id;
IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;
IF v_expense.petty_cash_transaction_id IS NOT NULL THEN
RAISE EXCEPTION 'Expense already linked to petty cash';
END IF;

SELECT 'PC-' || TO_CHAR(v_expense.expense_date, 'YYYYMMDD') || '-' ||
LPAD((COUNT(*) + 1)::TEXT, 4, '0')
INTO v_pc_number FROM petty_cash_transactions WHERE transaction_date = v_expense.expense_date;

INSERT INTO petty_cash_transactions (
transaction_number, transaction_date, transaction_type, amount, description,
expense_category, bank_account_id, created_by, source, paid_to, paid_by, finance_expense_id
) VALUES (
v_pc_number, v_expense.expense_date, 'expense', v_expense.amount, v_expense.description,
v_expense.expense_category, v_expense.bank_account_id, p_user_id,
'moved_from_tracker', v_expense.description, 'cash', v_expense.id
) RETURNING id INTO v_petty_cash_tx_id;

UPDATE finance_expenses
SET petty_cash_transaction_id = v_petty_cash_tx_id, payment_method = 'cash', paid_by = 'cash'
WHERE id = p_expense_id;

RETURN v_petty_cash_tx_id;
END;
$$;


--
-- Name: FUNCTION "move_expense_to_petty_cash"("p_expense_id" "uuid", "p_user_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."move_expense_to_petty_cash"("p_expense_id" "uuid", "p_user_id" "uuid") IS 'Moves an expense from finance_expenses to petty_cash_transactions. Creates link and updates payment method to cash (petty cash payments are recorded as cash).';


--
-- Name: move_expense_to_tracker("uuid", "uuid", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."move_expense_to_tracker"("p_petty_cash_id" "uuid", "p_bank_account_id" "uuid", "p_payment_method" "text", "p_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_pc_tx            RECORD;
v_expense_id       UUID;
v_finance_category TEXT;
v_role             text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot move petty cash to tracker', v_role;
END IF;

SELECT * INTO v_pc_tx FROM petty_cash_transactions
WHERE id = p_petty_cash_id AND transaction_type = 'expense';
IF NOT FOUND THEN RAISE EXCEPTION 'Petty cash expense not found'; END IF;

IF v_pc_tx.finance_expense_id IS NOT NULL THEN
UPDATE finance_expenses
SET payment_method = p_payment_method, bank_account_id = p_bank_account_id, paid_by = 'bank'
WHERE id = v_pc_tx.finance_expense_id RETURNING id INTO v_expense_id;
RETURN v_expense_id;
END IF;

v_finance_category := CASE
WHEN v_pc_tx.expense_category IN ('Office Supplies','Postage & Courier','Cleaning & Maintenance','Miscellaneous') THEN 'office_admin'
WHEN v_pc_tx.expense_category = 'Transportation' THEN 'delivery_sales'
WHEN v_pc_tx.expense_category = 'Utilities'      THEN 'utilities'
ELSE 'other'
END;

INSERT INTO finance_expenses (
expense_category, expense_type, amount, expense_date, description,
payment_method, bank_account_id, paid_by, created_by, petty_cash_transaction_id
) VALUES (
v_finance_category, 'admin', v_pc_tx.amount, v_pc_tx.transaction_date,
v_pc_tx.description || ' (Moved from Petty Cash: ' || v_pc_tx.transaction_number || ')',
p_payment_method, p_bank_account_id, 'bank', p_user_id, v_pc_tx.id
) RETURNING id INTO v_expense_id;

UPDATE petty_cash_transactions
SET finance_expense_id = v_expense_id, source = 'moved_to_tracker'
WHERE id = p_petty_cash_id;

RETURN v_expense_id;
END;
$$;


--
-- Name: FUNCTION "move_expense_to_tracker"("p_petty_cash_id" "uuid", "p_bank_account_id" "uuid", "p_payment_method" "text", "p_user_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."move_expense_to_tracker"("p_petty_cash_id" "uuid", "p_bank_account_id" "uuid", "p_payment_method" "text", "p_user_id" "uuid") IS 'Moves an expense from petty_cash_transactions to finance_expenses for bank reconciliation. Creates or updates finance_expenses entry.';


--
-- Name: next_capital_contribution_number("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."next_capital_contribution_number"("p_date" "date") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE v_prefix text := 'CC' || to_char(p_date,'YYMM'); v_seq integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('capital-contribution-number:' || v_prefix));
  SELECT COALESCE(max((regexp_match(voucher_number,'([0-9]+)$'))[1]::integer),0)+1 INTO v_seq
  FROM public.capital_contributions WHERE voucher_number LIKE v_prefix || '-%';
  RETURN v_prefix || '-' || lpad(v_seq::text,4,'0');
END $_$;


--
-- Name: next_expense_voucher_number("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."next_expense_voucher_number"("p_expense_date" "date") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_year text;
  v_prefix text;
  v_next int;
BEGIN
  IF p_expense_date IS NULL THEN
    RAISE EXCEPTION 'Expense date is required';
  END IF;

  v_year := to_char(p_expense_date, 'YY');
  v_prefix := 'EXP/' || v_year || '/';

  -- One lock covers both the canonical EXP/YY/NNN series and the preserved
  -- historical EXP/YY-YY/NNN series so their numeric suffixes cannot collide.
  PERFORM pg_advisory_xact_lock(hashtext('expense_voucher_' || v_year));

  SELECT COALESCE(MAX((regexp_match(voucher_number, '/([0-9]+)$'))[1]::int), 0) + 1
    INTO v_next
    FROM public.finance_expenses
   WHERE voucher_number LIKE v_prefix || '%'
      OR voucher_number LIKE 'EXP/' || v_year || '-' || v_year || '/%';

  RETURN v_prefix || lpad(v_next::text, 3, '0');
END;
$_$;


--
-- Name: next_journal_entry_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."next_journal_entry_number"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
v_prefix TEXT;
v_max_num INTEGER;
v_number TEXT;
v_lock_id BIGINT;
BEGIN
v_prefix := 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM');

v_lock_id := hashtext('je_number_' || v_prefix);
PERFORM pg_advisory_xact_lock(v_lock_id);

SELECT COALESCE(MAX(
CAST(NULLIF(SUBSTRING(entry_number FROM LENGTH(v_prefix) + 2), '') AS INTEGER)
), 0) + 1
INTO v_max_num
FROM journal_entries
WHERE entry_number LIKE v_prefix || '-%'
AND SUBSTRING(entry_number FROM LENGTH(v_prefix) + 2) ~ '^\d+$';

v_number := v_prefix || '-' || LPAD(v_max_num::TEXT, 4, '0');

RETURN v_number;
END;
$_$;


--
-- Name: next_loan_number("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."next_loan_number"("p_date" "date") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE v_prefix text := 'LN' || to_char(p_date,'YYMM'); v_seq integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('loan-number:' || v_prefix));
  SELECT COALESCE(max((regexp_match(loan_number,'([0-9]+)$'))[1]::integer),0)+1 INTO v_seq
  FROM public.loans WHERE loan_number LIKE v_prefix || '-%';
  RETURN v_prefix || '-' || lpad(v_seq::text,4,'0');
END $_$;


--
-- Name: next_loan_transaction_number("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."next_loan_transaction_number"("p_date" "date") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE v_prefix text := 'LP' || to_char(p_date,'YYMM'); v_seq integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('loan-transaction-number:' || v_prefix));
  SELECT COALESCE(max((regexp_match(transaction_number,'([0-9]+)$'))[1]::integer),0)+1 INTO v_seq
  FROM public.loan_transactions WHERE transaction_number LIKE v_prefix || '-%';
  RETURN v_prefix || '-' || lpad(v_seq::text,4,'0');
