--
-- Name: normalize_fund_transfer_exchange_rate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."normalize_fund_transfer_exchange_rate"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_from_currency text;
  v_to_currency text;
BEGIN
  v_from_currency:=CASE WHEN NEW.from_account_type='bank'
    THEN (SELECT upper(currency) FROM public.bank_accounts WHERE id=NEW.from_bank_account_id) ELSE 'IDR' END;
  v_to_currency:=CASE WHEN NEW.to_account_type='bank'
    THEN (SELECT upper(currency) FROM public.bank_accounts WHERE id=NEW.to_bank_account_id) ELSE 'IDR' END;
  IF v_from_currency='USD' AND v_to_currency='IDR' AND NEW.from_amount>0 THEN
    NEW.exchange_rate:=NEW.to_amount/NEW.from_amount;
  ELSIF v_from_currency='IDR' AND v_to_currency='USD' AND NEW.to_amount>0 THEN
    NEW.exchange_rate:=NEW.from_amount/NEW.to_amount;
  ELSIF v_from_currency='USD' AND v_to_currency='USD' THEN
    NEW.exchange_rate:=COALESCE(NULLIF(NEW.exchange_rate,0),public.get_reporting_usd_rate());
  ELSE
    NEW.exchange_rate:=1;
  END IF;
  IF NEW.exchange_rate IS NULL OR NEW.exchange_rate<=0 OR ((v_from_currency='USD' OR v_to_currency='USD') AND NEW.exchange_rate<=1) THEN
    RAISE EXCEPTION 'A valid USD-to-IDR exchange rate is required for this Fund Transfer';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: normalize_unlinked_expense_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."normalize_unlinked_expense_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF COALESCE(current_setting('app.finance_historical_repair', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF NEW.payment_method = 'bank_transfer'
     AND COALESCE(current_setting('app.expense_atomic_bank_link', true), 'off') <> 'on' THEN
    NEW.payment_method := NULL;
    NEW.bank_account_id := NULL;
    NEW.paid_by := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "normalize_unlinked_expense_payment"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."normalize_unlinked_expense_payment"() IS 'Prevents an unlinked bank_transfer expense from crediting Bank at recognition time; actual payment is posted by payment voucher/reconciliation.';


--
-- Name: notify_appointment_participants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."notify_appointment_participants"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
participant_id uuid;
appointment_time text;
notification_title text;
notification_message text;
BEGIN
-- Only process meeting-related activities
IF NEW.activity_type NOT IN ('meeting', 'video_call', 'phone_call') THEN
RETURN NEW;
END IF;

-- Only process if there's a follow_up_date (appointment date)
IF NEW.follow_up_date IS NULL THEN
RETURN NEW;
END IF;

-- Format appointment time
appointment_time := to_char(NEW.follow_up_date, 'Mon DD, YYYY at HH24:MI');

-- Set notification title based on operation
IF TG_OP = 'INSERT' THEN
notification_title := 'New Appointment';
ELSE
notification_title := 'Appointment Updated';
END IF;

-- Build notification message
notification_message := NEW.subject || ' - ' || appointment_time;

-- Send notification to each participant
IF NEW.participants IS NOT NULL AND array_length(NEW.participants, 1) > 0 THEN
FOREACH participant_id IN ARRAY NEW.participants
LOOP
INSERT INTO notifications (
user_id,
type,
title,
message,
reference_id,
reference_type,
is_read,
created_at
) VALUES (
participant_id,
'appointment',
notification_title,
notification_message,
NEW.id,
'crm_activity',
false,
now()
)
ON CONFLICT DO NOTHING;
END LOOP;
END IF;

RETURN NEW;
END;
$$;


