--
-- Name: petty_cash_resolved_tx_id("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."petty_cash_resolved_tx_id"("p_reference_id" "uuid", "p_reference_number" "text") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  SELECT COALESCE(
    p_reference_id,
    CASE
      WHEN p_reference_number ~ '^PC-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN SUBSTRING(p_reference_number FROM 4)::uuid
      ELSE NULL::uuid
    END
  )
$_$;


--
-- Name: post_batch_purchase_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_batch_purchase_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_je_id UUID;
v_je_number TEXT;
v_inventory_account_id UUID;
v_ap_account_id UUID;
v_ppn_account_id UUID;
v_purchase_value DECIMAL(18,2);
v_ppn_amount DECIMAL(18,2);
v_total_amount DECIMAL(18,2);
v_cost_per_unit DECIMAL(18,2);
BEGIN
-- Only post on insert for batches with supplier
IF TG_OP = 'INSERT' AND NEW.supplier_id IS NOT NULL THEN

-- Calculate cost per unit if not provided
v_cost_per_unit := COALESCE(NEW.cost_per_unit, 
CASE WHEN NEW.import_quantity > 0 
THEN NEW.import_price / NEW.import_quantity 
ELSE 0 
END);

-- Calculate purchase value
v_purchase_value := NEW.import_quantity * v_cost_per_unit;
v_ppn_amount := v_purchase_value * 0.11; -- 11% PPN
v_total_amount := v_purchase_value + v_ppn_amount;

-- Skip if amount is zero
IF v_total_amount <= 0 THEN
RETURN NEW;
END IF;

-- Get account IDs
SELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;
SELECT id INTO v_ap_account_id FROM chart_of_accounts WHERE code = '2110' LIMIT 1;
SELECT id INTO v_ppn_account_id FROM chart_of_accounts WHERE code = '1150' LIMIT 1;

IF v_inventory_account_id IS NULL OR v_ap_account_id IS NULL THEN
-- If accounts don't exist, skip accounting (don't fail the batch creation)
RETURN NEW;
END IF;

-- Generate journal entry number
v_je_number := 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '-' || LPAD((
SELECT COUNT(*) + 1 FROM journal_entries WHERE entry_number LIKE 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '%'
)::TEXT, 4, '0');

-- Create journal entry
INSERT INTO journal_entries (
entry_number, 
entry_date, 
source_module, 
reference_id, 
reference_number,
description, 
total_debit, 
total_credit, 
is_posted, 
posted_by
) VALUES (
v_je_number, 
NEW.import_date, 
'batch_purchase', 
NEW.id, 
NEW.batch_number,
'Goods Received - Batch: ' || NEW.batch_number,
v_total_amount, 
v_total_amount, 
true, 
NEW.created_by
) RETURNING id INTO v_je_id;

-- Debit: Inventory (purchase value)
INSERT INTO journal_entry_lines (
journal_entry_id, 
line_number, 
account_id, 
description, 
debit, 
credit, 
supplier_id,
batch_id
) VALUES (
v_je_id, 
1, 
v_inventory_account_id, 
'Inventory - Batch ' || NEW.batch_number, 
v_purchase_value, 
0, 
NEW.supplier_id,
NEW.id
);

-- Debit: PPN Input (if applicable)
IF v_ppn_amount > 0 AND v_ppn_account_id IS NOT NULL THEN
INSERT INTO journal_entry_lines (
journal_entry_id, 
line_number, 
account_id, 
description, 
debit, 
credit, 
supplier_id,
batch_id
) VALUES (
v_je_id, 
2, 
v_ppn_account_id, 
'PPN Input - Batch ' || NEW.batch_number, 
v_ppn_amount, 
0, 
NEW.supplier_id,
NEW.id
);
END IF;

-- Credit: Accounts Payable (total amount)
INSERT INTO journal_entry_lines (
journal_entry_id, 
line_number, 
account_id, 
description, 
debit, 
credit, 
supplier_id,
batch_id
) VALUES (
v_je_id, 
3, 
v_ap_account_id, 
'A/P - Batch ' || NEW.batch_number, 
0, 
v_total_amount, 
NEW.supplier_id,
NEW.id
);

END IF;

RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "post_batch_purchase_journal"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."post_batch_purchase_journal"() IS 'Posts batch purchase to accounting: Dr Inventory + Dr PPN Input, Cr Accounts Payable. Triggered when batch is created with supplier.';


--
-- Name: post_capital_contribution_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_capital_contribution_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_je_id uuid; v_bank_coa_id uuid; v_capital_account_id uuid; v_bank_currency text;
  v_currency text; v_rate numeric; v_functional_amount numeric; v_description text;
BEGIN
  IF COALESCE(current_setting('app.finance_metadata_repair',true),'off')='on' THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND OLD.journal_entry_id IS NOT NULL THEN RETURN NEW; END IF;
  SELECT coa_id,upper(currency) INTO v_bank_coa_id,v_bank_currency FROM public.bank_accounts WHERE id=NEW.bank_account_id AND is_active=true;
  IF v_bank_coa_id IS NULL THEN RAISE EXCEPTION 'Capital contribution bank account is missing or has no active GL account'; END IF;
  IF NEW.director_id IS NOT NULL THEN SELECT capital_account_id INTO v_capital_account_id FROM public.directors WHERE id=NEW.director_id; END IF;
  IF v_capital_account_id IS NULL THEN SELECT id INTO v_capital_account_id FROM public.chart_of_accounts WHERE code='3100' AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1; END IF;
  IF v_capital_account_id IS NULL THEN RAISE EXCEPTION 'Owner Capital account 3100 is not configured'; END IF;
  v_currency:=upper(COALESCE(NEW.transaction_currency,v_bank_currency,'IDR'));
  v_rate:=CASE WHEN v_currency='IDR' THEN 1 ELSE NEW.exchange_rate END;
  IF v_currency<>v_bank_currency OR v_rate IS NULL OR v_rate<=0 OR (v_currency='USD' AND v_rate<=1) THEN RAISE EXCEPTION 'Capital currency or exchange rate is invalid for the selected bank'; END IF;
  NEW.transaction_currency:=v_currency; NEW.functional_currency:='IDR'; NEW.bank_account_currency:=v_bank_currency; NEW.exchange_rate:=v_rate;
  v_functional_amount:=round(NEW.amount*v_rate,2); v_description:=COALESCE(NULLIF(NEW.description,''),'Capital Contribution: '||NEW.voucher_number);
  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,
    is_posted,posted_at,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
  VALUES(public.generate_journal_entry_number(),NEW.voucher_date,'capital_contribution',NEW.id,NEW.voucher_number,v_description,v_functional_amount,v_functional_amount,
    true,now(),NEW.created_by,NEW.created_by,v_currency,'IDR',v_rate,true) RETURNING id INTO v_je_id;
  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
  VALUES(v_je_id,1,v_bank_coa_id,v_description,v_functional_amount,0,v_currency,NEW.amount,0,'IDR',v_rate),
        (v_je_id,2,v_capital_account_id,v_description,0,v_functional_amount,v_currency,0,NEW.amount,'IDR',v_rate);
  NEW.journal_entry_id:=v_je_id;
  RETURN NEW;
END $$;


--
-- Name: post_credit_note_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_credit_note_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_should_post boolean := false;
BEGIN
  IF NEW.status = 'approved' AND NEW.journal_entry_id IS NULL THEN
    IF TG_OP = 'INSERT' THEN
      v_should_post := true;
    ELSIF TG_OP = 'UPDATE' AND (OLD.status IS DISTINCT FROM NEW.status) THEN
      v_should_post := true;
    END IF;
  END IF;

  IF v_should_post THEN
    NEW.journal_entry_id := public._post_credit_note_je(NEW);
  END IF;

  RETURN NEW;
END $$;


--
-- Name: post_customs_broker_accounting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_customs_broker_accounting"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_je uuid;
  v_expense_account uuid;
  v_ppn_account uuid;
  v_pph_account uuid;
  v_stamp_account uuid;
  v_cash_account uuid;
  v_ap_account uuid;
  v_line_no int := 1;
  v_expense numeric(18,2) := COALESCE(NEW.amount, 0);
  v_reimbursement numeric(18,2) := 0;
  v_reimbursement_ppn numeric(18,2) := 0;
  v_header_ppn numeric(18,2) := COALESCE(NEW.ppn_amount, 0);
  v_pph numeric(18,2) := COALESCE(NEW.pph_amount, 0);
  v_stamp numeric(18,2) := COALESCE(NEW.stamp_duty_amount, 0);
  v_total_ppn numeric(18,2);
  v_cash numeric(18,2);
  v_entry_number text;
  v_item jsonb;
  v_item_amount numeric(18,2);
  v_item_ppn numeric(18,2);
  v_item_supplier uuid;
  v_supplier_total numeric(18,2);
  v_is_outstanding boolean := NEW.payment_method IS NULL OR NEW.payment_method = 'outstanding';
BEGIN
  IF NEW.expense_category <> 'import_broker' THEN
    RETURN NEW;
  END IF;

  -- Replace the standard compatibility posting. The reference is unique to
  -- the source expense, so the final transaction has exactly one JE.
  DELETE FROM journal_entry_lines WHERE journal_entry_id IN
    (SELECT id FROM journal_entries WHERE reference_number = 'EXP-' || NEW.id::text);
  DELETE FROM journal_entries WHERE reference_number = 'EXP-' || NEW.id::text;

  SELECT id INTO v_expense_account FROM chart_of_accounts WHERE code = '5300' LIMIT 1;
  SELECT id INTO v_ppn_account FROM chart_of_accounts WHERE code = '1150' LIMIT 1;
  SELECT id INTO v_pph_account FROM chart_of_accounts WHERE code = '2132' LIMIT 1;
  SELECT id INTO v_stamp_account FROM chart_of_accounts WHERE code = '6950' LIMIT 1;
  SELECT id INTO v_ap_account FROM chart_of_accounts WHERE code = '2110' LIMIT 1;
  IF NEW.payment_method = 'cash' THEN
    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
  ELSIF NEW.payment_method = 'petty_cash' THEN
    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1102' LIMIT 1;
  ELSIF NEW.payment_method = 'bank_transfer' AND NEW.bank_account_id IS NOT NULL THEN
    SELECT coa_id INTO v_cash_account FROM bank_accounts WHERE id = NEW.bank_account_id;
  ELSE
    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
  END IF;

  IF v_expense_account IS NULL OR v_ppn_account IS NULL OR v_ap_account IS NULL THEN
    RAISE EXCEPTION 'Customs broker posting requires accounts 5300, 1150 and 2110';
  END IF;
  IF v_is_outstanding = false AND v_cash_account IS NULL THEN
    RAISE EXCEPTION 'Customs broker posting requires a cash/bank account';
  END IF;
  IF v_pph > 0 AND v_pph_account IS NULL THEN
    RAISE EXCEPTION 'Customs broker posting requires PPh23 payable account 2132';
  END IF;
  IF v_stamp > 0 AND v_stamp_account IS NULL THEN
    RAISE EXCEPTION 'Customs broker posting requires stamp duty account 6950';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items, '[]'::jsonb)) LOOP
    v_item_amount := COALESCE((v_item->>'amount')::numeric, 0);
    v_item_ppn := COALESCE((v_item->>'ppn_amount')::numeric, 0);
    -- An inclusive line stores the gross reimbursement amount; recoverable
    -- PPN is removed from expense. Excluded lines store the taxable amount.
    v_item_amount := CASE WHEN v_item->>'ppn_treatment' = 'included'
      THEN GREATEST(v_item_amount - v_item_ppn, 0) ELSE v_item_amount END;
    v_reimbursement := v_reimbursement + v_item_amount;
    v_reimbursement_ppn := v_reimbursement_ppn + v_item_ppn;
  END LOOP;
  v_expense := v_expense + v_reimbursement + v_stamp;
  v_total_ppn := v_header_ppn + v_reimbursement_ppn;
  v_cash := v_expense + v_total_ppn - v_pph;

  SELECT 'JE' || to_char(NEW.expense_date, 'YYMM') || '-' || lpad((
    COALESCE(max(CAST(substring(entry_number FROM '-([0-9]+)$') AS int)), 0) + 1
  )::text, 4, '0') INTO v_entry_number
  FROM journal_entries WHERE entry_number LIKE 'JE' || to_char(NEW.expense_date, 'YYMM') || '-%';

  INSERT INTO journal_entries(entry_number, entry_date, source_module, reference_id,
    reference_number, description, transaction_category, total_debit, total_credit,
    is_posted, posted_at, created_by)
  VALUES(v_entry_number, NEW.expense_date, 'expenses', NEW.id, 'EXP-' || NEW.id::text,
    COALESCE(NEW.description, 'Customs Broker Invoice'), 'import_broker',
    v_expense + v_total_ppn, v_expense + v_total_ppn, true, now(), NEW.created_by)
  RETURNING id INTO v_je;

  INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
  VALUES(v_je,v_line_no,v_expense_account,'Broker service expense',COALESCE(NEW.amount,0),0,NEW.supplier_id);
  v_line_no := v_line_no + 1;

  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items, '[]'::jsonb)) LOOP
    v_item_amount := COALESCE((v_item->>'amount')::numeric, 0);
    v_item_ppn := COALESCE((v_item->>'ppn_amount')::numeric, 0);
    v_item_supplier := NULLIF(v_item->>'supplier_id','')::uuid;
    v_item_amount := CASE WHEN v_item->>'ppn_treatment' = 'included'
      THEN GREATEST(v_item_amount - v_item_ppn, 0) ELSE v_item_amount END;
    IF v_item_amount > 0 THEN
      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
      VALUES(v_je,v_line_no,v_expense_account,'Reimbursement - ' || COALESCE(v_item->>'description','line'),v_item_amount,0,COALESCE(v_item_supplier,NEW.supplier_id));
      v_line_no := v_line_no + 1;
    END IF;
    IF v_item_ppn > 0 THEN
      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
      VALUES(v_je,v_line_no,v_ppn_account,'PPN Masukan - reimbursement',v_item_ppn,0,COALESCE(v_item_supplier,NEW.supplier_id));
      v_line_no := v_line_no + 1;
    END IF;
  END LOOP;

  IF v_header_ppn > 0 THEN
    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
    VALUES(v_je,v_line_no,v_ppn_account,'PPN Masukan - broker invoice',v_header_ppn,0,NEW.supplier_id);
    v_line_no := v_line_no + 1;
  END IF;
  IF v_stamp > 0 THEN
    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
    VALUES(v_je,v_line_no,v_stamp_account,'Bea Meterai',v_stamp,0,NEW.supplier_id);
    v_line_no := v_line_no + 1;
  END IF;
  IF v_pph > 0 THEN
    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
    VALUES(v_je,v_line_no,v_pph_account,'PPh23 Payable',0,v_pph,NEW.supplier_id);
    v_line_no := v_line_no + 1;
  END IF;

  IF v_is_outstanding THEN
    -- One AP credit per supplier: broker service and every reimbursement
    -- supplier remain independently visible in Supplier/Party Ledger.
    v_supplier_total := COALESCE(NEW.amount,0) + v_header_ppn + v_stamp - v_pph;
    IF v_supplier_total <> 0 THEN
      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
      VALUES(v_je,v_line_no,v_ap_account,'A/P - broker supplier',0,v_supplier_total,NEW.supplier_id);
      v_line_no := v_line_no + 1;
    END IF;
    FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items, '[]'::jsonb)) LOOP
      v_item_amount := COALESCE((v_item->>'amount')::numeric, 0);
      v_item_ppn := COALESCE((v_item->>'ppn_amount')::numeric, 0);
      v_item_supplier := NULLIF(v_item->>'supplier_id','')::uuid;
      v_item_amount := CASE WHEN v_item->>'ppn_treatment' = 'included' THEN GREATEST(v_item_amount-v_item_ppn,0) ELSE v_item_amount END;
      IF v_item_amount + v_item_ppn > 0 THEN
        INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
        VALUES(v_je,v_line_no,v_ap_account,'A/P - reimbursement supplier',0,v_item_amount+v_item_ppn,COALESCE(v_item_supplier,NEW.supplier_id));
        v_line_no := v_line_no + 1;
      END IF;
    END LOOP;
  ELSE
    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
    VALUES(v_je,v_line_no,v_cash_account,'Cash payment - customs broker',0,v_cash,NEW.supplier_id);
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: post_customs_broker_canonical(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_customs_broker_canonical"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
v_je uuid;
v_expense_account uuid;
v_ppn_account uuid;
v_pph_account uuid;
v_stamp_account uuid;
v_ap_account uuid;
v_cash_account uuid;
v_item jsonb;
v_supplier uuid;
v_line_total numeric;
v_line_ppn numeric;
v_line_no int := 1;
v_reimbursement numeric := 0;
v_expense_total numeric;
v_pph numeric := COALESCE(NEW.pph_amount,0);
v_credit_total numeric;
v_outstanding boolean := NEW.payment_method IS NULL OR NEW.payment_method IN ('outstanding','bank_transfer');
BEGIN
IF NEW.expense_category <> 'import_broker' THEN RETURN NEW; END IF;

-- Find the existing active journal (if any) so we can preserve its identity.
SELECT id INTO v_je
FROM public.journal_entries
WHERE source_module IN ('expense','expenses')
AND (reference_id = NEW.id OR reference_number = 'EXP-'||NEW.id::text)
AND is_posted = true
AND NOT COALESCE(is_reversed, false)
ORDER BY created_at DESC, id DESC
LIMIT 1;

-- Delete old lines (header is reused or replaced in-place).
IF v_je IS NOT NULL THEN
DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_je;
END IF;

SELECT id INTO v_expense_account FROM public.chart_of_accounts WHERE code='1130' LIMIT 1;
SELECT id INTO v_ppn_account      FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;
SELECT id INTO v_pph_account      FROM public.chart_of_accounts WHERE code='2132' LIMIT 1;
SELECT id INTO v_stamp_account     FROM public.chart_of_accounts WHERE code='1130' LIMIT 1;
SELECT id INTO v_ap_account        FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;

IF NEW.payment_method='cash' THEN
SELECT id INTO v_cash_account FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;
ELSIF NEW.payment_method='petty_cash' THEN
SELECT id INTO v_cash_account FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;
ELSIF NEW.payment_method='bank_transfer' AND NEW.bank_account_id IS NOT NULL THEN
SELECT coa_id INTO v_cash_account FROM public.bank_accounts WHERE id=NEW.bank_account_id;
ELSE
SELECT id INTO v_cash_account FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;
END IF;

FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items,'[]'::jsonb)) LOOP
v_reimbursement := v_reimbursement + public.broker_reimbursement_line_total(v_item);
END LOOP;

v_expense_total := COALESCE(NEW.amount,0) + v_reimbursement + COALESCE(NEW.stamp_duty_amount,0);
v_credit_total := v_expense_total;

-- Upsert the journal header in place (preserves ID if v_je is not null).
v_je := public.upsert_expense_journal_header_in_place(
v_je, NEW.id, NEW.expense_date,
COALESCE(NEW.description, 'Customs Broker Invoice'),
'import_broker', v_credit_total, NEW.created_by
);

v_line_total := COALESCE(NEW.amount,0) - COALESCE(NEW.ppn_amount,0);
IF v_line_total <> 0 THEN
INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
VALUES(v_je,v_line_no,v_expense_account,'Broker service expense',v_line_total,0,NEW.supplier_id);
v_line_no := v_line_no + 1;
END IF;

FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items,'[]'::jsonb)) LOOP
v_supplier := COALESCE(NULLIF(v_item->>'supplier_id','')::uuid, NEW.supplier_id);
v_line_total := public.broker_reimbursement_expense_base(v_item);
IF v_line_total <> 0 THEN
INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
VALUES(v_je,v_line_no,v_expense_account,'Reimbursement expense',v_line_total,0,v_supplier);
v_line_no := v_line_no + 1;
END IF;
END LOOP;

IF COALESCE(NEW.ppn_amount,0) > 0 THEN
INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
VALUES(v_je,v_line_no,v_ppn_account,'Recoverable PPN - broker invoice',NEW.ppn_amount,0,NEW.supplier_id);
v_line_no := v_line_no + 1;
END IF;

FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items,'[]'::jsonb)) LOOP
v_supplier := COALESCE(NULLIF(v_item->>'supplier_id','')::uuid, NEW.supplier_id);
v_line_ppn := COALESCE((v_item->>'ppn_amount')::numeric,0);
IF v_line_ppn > 0 THEN
INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
VALUES(v_je,v_line_no,v_ppn_account,'Recoverable PPN - reimbursement',v_line_ppn,0,v_supplier);
v_line_no := v_line_no + 1;
END IF;
END LOOP;

IF COALESCE(NEW.stamp_duty_amount,0) > 0 THEN
INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
VALUES(v_je,v_line_no,v_stamp_account,'Stamp duty',NEW.stamp_duty_amount,0,NEW.supplier_id);
v_line_no := v_line_no + 1;
END IF;

IF v_pph > 0 THEN
INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
VALUES(v_je,v_line_no,v_pph_account,'PPh23 withheld',0,v_pph,NEW.supplier_id);
v_line_no := v_line_no + 1;
END IF;

v_line_total := v_expense_total - v_pph;
IF v_line_total <> 0 THEN
INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
VALUES(v_je,v_line_no,
CASE WHEN v_outstanding THEN v_ap_account ELSE v_cash_account END,
CASE WHEN v_outstanding THEN 'Supplier payable - customs broker' ELSE 'Cash payment - customs broker' END,
0, v_line_total, NEW.supplier_id);
END IF;

RETURN NEW;
END;
$$;


--
-- Name: post_expense_to_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_expense_to_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_expense_account_id UUID;
  v_payment_account_id UUID;
  v_journal_id         UUID;
  v_entry_number       TEXT;
  v_category_label     TEXT;
  v_description        TEXT;
  v_credit_desc        TEXT;
  v_bm_account_id      UUID;
  v_ppn_account_id     UUID;
  v_pph_account_id     UUID;
  v_line_num           INTEGER;
BEGIN
  -- Idempotency guard: never double-post
  IF EXISTS (
    SELECT 1 FROM journal_entries
    WHERE reference_id = NEW.id AND source_module = 'expenses'
  ) THEN
    RETURN NEW;
  END IF;

  -- Resolve payment account
  IF NEW.payment_method = 'cash' THEN
    SELECT id INTO v_payment_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
  ELSIF NEW.payment_method = 'petty_cash' THEN
    SELECT id INTO v_payment_account_id FROM chart_of_accounts WHERE code = '1102' LIMIT 1;
  ELSIF NEW.payment_method = 'bank_transfer' AND NEW.bank_account_id IS NOT NULL THEN
    SELECT coa_id INTO v_payment_account_id FROM bank_accounts WHERE id = NEW.bank_account_id;
    IF v_payment_account_id IS NULL THEN
      SELECT id INTO v_payment_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;
    END IF;
  ELSIF NEW.payment_method IS NULL THEN
    SELECT id INTO v_payment_account_id FROM chart_of_accounts WHERE code = '2110' LIMIT 1;
  ELSE
    SELECT id INTO v_payment_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
  END IF;

  IF v_payment_account_id IS NULL THEN RETURN NEW; END IF;

  v_entry_number := next_journal_entry_number();

  -- PIB Import: multi-line split
  IF NEW.expense_category = 'pib_import' THEN
    v_bm_account_id  := get_expense_account_id('duty_customs');
    v_ppn_account_id := get_expense_account_id('ppn_import');
    v_pph_account_id := get_expense_account_id('pph_import');

    INSERT INTO journal_entries (
      entry_number, entry_date, source_module, reference_id, reference_number,
      description, transaction_category,
      total_debit, total_credit, is_posted, posted_at, created_by
    ) VALUES (
      v_entry_number, NEW.expense_date, 'expenses', NEW.id, 'EXP-' || NEW.id::text,
      COALESCE(NEW.description, 'PIB Import Payment'), 'pib_import',
      NEW.amount, NEW.amount, TRUE, NOW(), NEW.created_by
    ) RETURNING id INTO v_journal_id;

    v_line_num := 1;
    IF COALESCE(NEW.pib_bm_amount, 0) > 0 AND v_bm_account_id IS NOT NULL THEN
      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
      VALUES (v_journal_id, v_line_num, v_bm_account_id, NEW.pib_bm_amount, 0, 'PIB - Import Duty (BM)');
      v_line_num := v_line_num + 1;
    END IF;
    IF COALESCE(NEW.pib_ppn_amount, 0) > 0 AND v_ppn_account_id IS NOT NULL THEN
      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
      VALUES (v_journal_id, v_line_num, v_ppn_account_id, NEW.pib_ppn_amount, 0, 'PIB - PPN Import');
      v_line_num := v_line_num + 1;
    END IF;
    IF COALESCE(NEW.pib_pph_amount, 0) > 0 AND v_pph_account_id IS NOT NULL THEN
      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
      VALUES (v_journal_id, v_line_num, v_pph_account_id, NEW.pib_pph_amount, 0, 'PIB - PPh 22');
      v_line_num := v_line_num + 1;
    END IF;
    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
    VALUES (v_journal_id, v_line_num, v_payment_account_id, 0, NEW.amount, 'PIB - Bank payment');
    RETURN NEW;
  END IF;

  -- Standard 2-line expense
  v_expense_account_id := get_expense_account_id(NEW.expense_category);
  IF v_expense_account_id IS NULL THEN RETURN NEW; END IF;

  v_category_label := REPLACE(INITCAP(REPLACE(NEW.expense_category, '_', ' ')), ' ', ' ');
  v_description    := COALESCE(NEW.description, NEW.expense_category);
  v_credit_desc    := COALESCE(
    SUBSTRING(NEW.description FROM '^[^\n]+'), NEW.expense_category
  ) || ' [' || v_category_label || ']';

  INSERT INTO journal_entries (
    entry_number, entry_date, source_module, reference_id, reference_number,
    description, transaction_category,
    total_debit, total_credit, is_posted, posted_at, created_by
  ) VALUES (
    v_entry_number, NEW.expense_date, 'expenses', NEW.id, 'EXP-' || NEW.id::text,
    v_description, NEW.expense_category,
    NEW.amount, NEW.amount, TRUE, NOW(), NEW.created_by
  ) RETURNING id INTO v_journal_id;

  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
  VALUES (v_journal_id, 1, v_expense_account_id, NEW.amount, 0, v_credit_desc);
  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
  VALUES (v_journal_id, 2, v_payment_account_id, 0, NEW.amount, v_credit_desc);

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'post_expense_to_journal failed for %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


--
-- Name: post_fund_transfer_journal("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_fund_transfer_journal"("p_transfer_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public, pg_temp'
    AS $$
DECLARE
v_transfer        RECORD;
v_journal_id      UUID;
v_from_account_id UUID;
v_to_account_id   UUID;
v_description     TEXT;
v_role            text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot post fund transfer journals', v_role;
END IF;

SELECT * INTO v_transfer FROM fund_transfers WHERE id = p_transfer_id;
IF NOT FOUND THEN RAISE EXCEPTION 'Fund transfer not found'; END IF;
IF v_transfer.journal_entry_id IS NOT NULL THEN RETURN v_transfer.journal_entry_id; END IF;

SELECT id INTO v_journal_id FROM journal_entries
WHERE reference_number = v_transfer.transfer_number AND source_module = 'fund_transfers'
ORDER BY created_at DESC LIMIT 1;
IF v_journal_id IS NOT NULL THEN
UPDATE fund_transfers SET journal_entry_id = v_journal_id WHERE id = p_transfer_id;
RETURN v_journal_id;
END IF;

IF    v_transfer.from_account_type = 'petty_cash'   THEN SELECT id INTO v_from_account_id FROM chart_of_accounts WHERE code = '1102' LIMIT 1;
ELSIF v_transfer.from_account_type = 'cash_on_hand' THEN SELECT id INTO v_from_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
ELSIF v_transfer.from_account_type = 'bank'         THEN SELECT coa_id INTO v_from_account_id FROM bank_accounts WHERE id = v_transfer.from_bank_account_id;
END IF;

IF    v_transfer.to_account_type = 'petty_cash'   THEN SELECT id INTO v_to_account_id FROM chart_of_accounts WHERE code = '1102' LIMIT 1;
ELSIF v_transfer.to_account_type = 'cash_on_hand' THEN SELECT id INTO v_to_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
ELSIF v_transfer.to_account_type = 'bank'         THEN SELECT coa_id INTO v_to_account_id FROM bank_accounts WHERE id = v_transfer.to_bank_account_id;
END IF;

IF v_from_account_id IS NULL OR v_to_account_id IS NULL THEN
RAISE EXCEPTION 'Cannot determine chart of accounts for transfer';
END IF;

v_description := 'Fund Transfer ' || v_transfer.transfer_number;
IF v_transfer.description IS NOT NULL THEN
v_description := v_description || ' - ' || v_transfer.description;
END IF;

INSERT INTO journal_entries (
entry_date, source_module, reference_id, reference_number,
description, total_debit, total_credit, is_posted, created_by
) VALUES (
v_transfer.transfer_date, 'fund_transfers', v_transfer.id, v_transfer.transfer_number,
v_description, 0, 0, true, p_user_id
) RETURNING id INTO v_journal_id;

INSERT INTO journal_entry_lines (journal_entry_id, account_id, debit, credit, description)
VALUES
(v_journal_id, v_to_account_id,   v_transfer.amount, 0,                  'Transfer In'),
(v_journal_id, v_from_account_id, 0,                  v_transfer.amount, 'Transfer Out');

UPDATE fund_transfers SET journal_entry_id = v_journal_id WHERE id = p_transfer_id;
RETURN v_journal_id;
END;
$$;


--
-- Name: FUNCTION "post_fund_transfer_journal"("p_transfer_id" "uuid", "p_user_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."post_fund_transfer_journal"("p_transfer_id" "uuid", "p_user_id" "uuid") IS 'Manually posts journal entry for a fund transfer. Call this AFTER verifying the transfer is correct. Returns journal_entry_id.';


--
-- Name: post_grn_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_grn_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_je_id UUID;
v_je_number TEXT;
v_inventory_account_id UUID;
v_ap_account_id UUID;
v_ppn_account_id UUID;
BEGIN
-- Only post when status changes to 'posted' and no journal entry exists yet
IF TG_OP = 'UPDATE' 
AND NEW.status = 'posted' 
AND OLD.status = 'draft'
AND NEW.journal_entry_id IS NULL THEN

-- Get account IDs
SELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;
SELECT id INTO v_ap_account_id FROM chart_of_accounts WHERE code = '2110' LIMIT 1;
SELECT id INTO v_ppn_account_id FROM chart_of_accounts WHERE code = '1150' LIMIT 1; -- PPN Input

IF v_inventory_account_id IS NULL OR v_ap_account_id IS NULL THEN
-- If accounts don't exist, skip accounting (don't fail the GRN)
RETURN NEW;
END IF;

-- Generate journal entry number
v_je_number := 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '-' || LPAD((
SELECT COUNT(*) + 1 FROM journal_entries WHERE entry_number LIKE 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '%'
)::TEXT, 4, '0');

-- Create journal entry
INSERT INTO journal_entries (
entry_number, 
entry_date, 
source_module, 
reference_id, 
reference_number,
description, 
total_debit, 
total_credit, 
is_posted, 
posted_by
) VALUES (
v_je_number, 
NEW.grn_date, 
'goods_receipt_note', 
NEW.id, 
NEW.grn_number,
'GRN: ' || NEW.grn_number || ' - ' || (SELECT company_name FROM suppliers WHERE id = NEW.supplier_id),
NEW.total_amount, 
NEW.total_amount, 
true, 
NEW.posted_by
) RETURNING id INTO v_je_id;

-- Debit: Inventory (subtotal - before tax)
INSERT INTO journal_entry_lines (
journal_entry_id, 
line_number, 
account_id, 
description, 
debit, 
credit, 
supplier_id
) VALUES (
v_je_id, 
1, 
v_inventory_account_id, 
'Inventory - GRN ' || NEW.grn_number, 
NEW.subtotal, 
0, 
NEW.supplier_id
);

-- Debit: PPN Input (if applicable)
IF NEW.tax_amount > 0 AND v_ppn_account_id IS NOT NULL THEN
INSERT INTO journal_entry_lines (
journal_entry_id, 
line_number, 
account_id, 
description, 
debit, 
credit, 
supplier_id
) VALUES (
v_je_id, 
2, 
v_ppn_account_id, 
'PPN Input - GRN ' || NEW.grn_number, 
NEW.tax_amount, 
0, 
NEW.supplier_id
);
END IF;

-- Credit: Accounts Payable (total amount)
INSERT INTO journal_entry_lines (
journal_entry_id, 
line_number, 
account_id, 
description, 
debit, 
credit, 
supplier_id
) VALUES (
v_je_id, 
3, 
v_ap_account_id, 
'A/P - GRN ' || NEW.grn_number, 
0, 
NEW.total_amount, 
NEW.supplier_id
);

-- Link journal entry to GRN
NEW.journal_entry_id := v_je_id;
END IF;

RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "post_grn_journal"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."post_grn_journal"() IS 'Posts GRN to accounting: Dr Inventory + Dr PPN Input, Cr Accounts Payable. Triggered when GRN status changes to posted.';


--
-- Name: post_import_cost_journal("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_import_cost_journal"("p_header_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_header RECORD;
v_je_id UUID;
v_je_number TEXT;
v_inventory_account_id UUID;
v_clearing_account_id UUID;
v_total_cost DECIMAL(18,2);
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot post import cost journals', v_role;
END IF;

SELECT * INTO v_header FROM import_cost_headers WHERE id = p_header_id;
IF NOT FOUND THEN
RAISE EXCEPTION 'Import cost header not found';
END IF;

SELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;
SELECT id INTO v_clearing_account_id  FROM chart_of_accounts WHERE code = '2140' LIMIT 1;

IF v_inventory_account_id IS NULL OR v_clearing_account_id IS NULL THEN
RAISE EXCEPTION 'Required accounts not found (1130 Inventory or 2140 Customer Deposits)';
END IF;

v_total_cost := v_header.duty_amount + v_header.ppn_import_amount + v_header.pph22_amount +
v_header.freight_amount + v_header.insurance_amount + v_header.clearing_amount +
v_header.port_charges + v_header.other_charges;

IF v_total_cost <= 0 THEN
RAISE EXCEPTION 'Total allocated cost must be greater than zero';
END IF;

v_je_number := 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '-' || LPAD((
SELECT COUNT(*) + 1 FROM journal_entries WHERE entry_number LIKE 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '%'
)::TEXT, 4, '0');

INSERT INTO journal_entries (
entry_number, entry_date, source_module, reference_id, reference_number,
description, total_debit, total_credit, is_posted, posted_by
) VALUES (
v_je_number, v_header.import_date, 'import_cost', p_header_id, v_header.cost_sheet_number,
'Import Cost Allocation: ' || v_header.cost_sheet_number,
v_total_cost, v_total_cost, true, v_header.created_by
) RETURNING id INTO v_je_id;

INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)
VALUES
(v_je_id, 1, v_inventory_account_id, 'Import Costs - '    || v_header.cost_sheet_number, v_total_cost, 0,            v_header.supplier_id),
(v_je_id, 2, v_clearing_account_id,  'Import Clearing - ' || v_header.cost_sheet_number, 0,            v_total_cost, v_header.supplier_id);

RETURN v_je_id;
END;
$$;


--
-- Name: FUNCTION "post_import_cost_journal"("p_header_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."post_import_cost_journal"("p_header_id" "uuid") IS 'Posts import cost allocation to accounting: Dr Inventory, Cr Import Clearing Payable. Returns journal entry ID.';


--
-- Name: post_inventory_movement("uuid", "uuid", "uuid", "text", numeric, "date", "text", "text", "uuid", "text", "uuid", numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_inventory_movement"("p_operation_id" "uuid", "p_product_id" "uuid", "p_batch_id" "uuid", "p_transaction_type" "text", "p_quantity" numeric, "p_transaction_date" "date" DEFAULT CURRENT_DATE, "p_reference_number" "text" DEFAULT NULL::"text", "p_reference_type" "text" DEFAULT NULL::"text", "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_stock_before" numeric DEFAULT NULL::numeric, "p_stock_after" numeric DEFAULT NULL::numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing public.inventory_transactions%ROWTYPE;
  v_batch public.batches%ROWTYPE;
  v_transaction_id uuid;
  v_new_stock numeric;
  v_previous_context text;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'Canonical inventory posting requires operation_id';
  END IF;
  IF p_batch_id IS NULL OR p_product_id IS NULL THEN
    RAISE EXCEPTION 'Canonical inventory posting requires product_id and batch_id';
  END IF;
  IF COALESCE(p_quantity, 0) = 0 THEN
    RAISE EXCEPTION 'Canonical inventory posting quantity cannot be zero';
  END IF;
  IF p_transaction_type NOT IN (
    'purchase', 'delivery_challan', 'return', 'adjustment', 'rejection'
  ) THEN
    RAISE EXCEPTION 'Unsupported canonical inventory transaction type: %',
      p_transaction_type;
  END IF;

  SELECT *
  INTO v_existing
  FROM public.inventory_transactions
  WHERE operation_id = p_operation_id;

  IF FOUND THEN
    IF v_existing.batch_id IS DISTINCT FROM p_batch_id
       OR v_existing.product_id IS DISTINCT FROM p_product_id
       OR v_existing.transaction_type IS DISTINCT FROM p_transaction_type
       OR v_existing.quantity IS DISTINCT FROM p_quantity
       OR v_existing.reference_type IS DISTINCT FROM p_reference_type
       OR v_existing.reference_id IS DISTINCT FROM p_reference_id THEN
      RAISE EXCEPTION 'operation_id % was already used with different inventory values',
        p_operation_id;
    END IF;
    RETURN v_existing.id;
  END IF;

  SELECT *
  INTO v_batch
  FROM public.batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Batch not found: %', p_batch_id;
  END IF;
  IF v_batch.product_id IS DISTINCT FROM p_product_id THEN
    RAISE EXCEPTION 'Product % does not match batch % product %',
      p_product_id, p_batch_id, v_batch.product_id;
  END IF;

  IF p_transaction_type IN ('purchase', 'return') AND p_quantity <= 0 THEN
    RAISE EXCEPTION '% movement must be positive', p_transaction_type;
  END IF;
  IF p_transaction_type IN ('delivery_challan', 'rejection') AND p_quantity >= 0 THEN
    RAISE EXCEPTION '% movement must be negative', p_transaction_type;
  END IF;
  IF p_transaction_type = 'delivery_challan'
     AND v_batch.expiry_date IS NOT NULL
     AND v_batch.expiry_date <= COALESCE(p_transaction_date, CURRENT_DATE) THEN
    RAISE EXCEPTION 'Expired batch % cannot be delivered (expiry %)',
      v_batch.batch_number, v_batch.expiry_date;
  END IF;
  IF p_transaction_type = 'purchase'
     AND EXISTS (
       SELECT 1
       FROM public.inventory_transactions it
       WHERE it.batch_id = p_batch_id
         AND it.transaction_type = 'purchase'
     ) THEN
    RAISE EXCEPTION 'Batch % already has a Batch Creation movement',
      v_batch.batch_number;
  END IF;

  v_new_stock := v_batch.current_stock + p_quantity;
  IF v_new_stock < 0 THEN
    RAISE EXCEPTION 'Insufficient stock in batch %: current %, movement %, result %',
      v_batch.batch_number, v_batch.current_stock, p_quantity, v_new_stock;
  END IF;

  IF p_stock_before IS NOT NULL
     AND p_stock_before IS DISTINCT FROM v_batch.current_stock THEN
    RAISE EXCEPTION 'Stale stock_before for batch %: expected %, received %',
      v_batch.batch_number, v_batch.current_stock, p_stock_before;
  END IF;
  IF p_stock_after IS NOT NULL
     AND p_stock_after IS DISTINCT FROM v_new_stock THEN
    RAISE EXCEPTION 'Invalid stock_after for batch %: expected %, received %',
      v_batch.batch_number, v_new_stock, p_stock_after;
  END IF;

  v_previous_context := current_setting('app.canonical_stock_engine', true);
  PERFORM set_config('app.canonical_stock_engine', 'on', true);

  UPDATE public.batches
  SET current_stock = v_new_stock,
      updated_at = now()
  WHERE id = p_batch_id;

  INSERT INTO public.inventory_transactions (
    operation_id,
    product_id,
    batch_id,
    transaction_type,
    quantity,
    transaction_date,
    reference_number,
    reference_type,
    reference_id,
    notes,
    created_by,
    stock_before,
    stock_after,
    metadata
  )
  VALUES (
    p_operation_id,
    p_product_id,
    p_batch_id,
    p_transaction_type,
    p_quantity,
    COALESCE(p_transaction_date, CURRENT_DATE),
    p_reference_number,
    p_reference_type,
    p_reference_id,
    p_notes,
    COALESCE(p_created_by, auth.uid()),
    v_batch.current_stock,
    v_new_stock,
    jsonb_build_object(
      'canonical_engine_version', '1.0',
      'canonical_posted_at', clock_timestamp()
    )
  )
  RETURNING id INTO v_transaction_id;

  PERFORM set_config(
    'app.canonical_stock_engine',
    COALESCE(v_previous_context, ''),
    true
  );

  RETURN v_transaction_id;
END;
$$;


--
-- Name: post_payment_voucher("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_payment_voucher"("p_pv_id" "uuid", "p_posted_by" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pv record; v_je uuid; v_ap uuid; v_bank uuid; v_charge uuid; v_pph uuid; v_fx uuid;
  v_invoice_currency text; v_bank_currency text; v_rate numeric; v_gross numeric;
  v_payment numeric; v_converted numeric; v_pph_bank numeric; v_actual numeric; v_charge_amt numeric;
  v_expected numeric; v_fx_delta numeric; v_ap_debit numeric; v_total numeric; v_line int := 1; v_entry text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO v_pv FROM public.payment_vouchers WHERE id=p_pv_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found',p_pv_id; END IF;
  IF v_pv.is_posted THEN RAISE EXCEPTION 'Payment voucher % is already posted',v_pv.voucher_number; END IF;

  v_invoice_currency := upper(COALESCE(v_pv.invoice_currency,v_pv.transaction_currency,v_pv.payment_currency,'IDR'));
  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=v_pv.bank_account_id;
  v_bank_currency := COALESCE(v_bank_currency,v_pv.bank_currency,v_pv.payment_currency,'IDR');
  v_rate := CASE WHEN v_invoice_currency=v_bank_currency THEN 1 ELSE COALESCE(v_pv.exchange_rate,0) END;
  IF v_rate <= 0 THEN RAISE EXCEPTION 'Missing exchange rate for %',v_pv.voucher_number; END IF;

  v_gross := COALESCE(v_pv.invoice_amount,v_pv.amount,0);
  v_payment := COALESCE(v_pv.payment_amount,v_gross-COALESCE(v_pv.pph_amount,0));
  v_converted := COALESCE(v_pv.converted_amount,v_payment*v_rate);
  v_pph_bank := COALESCE(v_pv.pph_amount,0)*v_rate;
  v_charge_amt := COALESCE(v_pv.bank_charge,0);
  v_actual := COALESCE(v_pv.actual_bank_debit,v_pv.bank_amount,v_converted+v_charge_amt);
  v_expected := v_converted+v_charge_amt;
  v_fx_delta := v_actual-v_expected;
  v_ap_debit := v_gross*v_rate;

  IF v_pv.coa_account_id IS NOT NULL THEN
    v_ap := v_pv.coa_account_id;
  ELSE
    SELECT id INTO v_ap FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;
  END IF;
  IF v_pv.payment_method = 'advance_adjustment' OR v_pv.payment_purpose = 'salary_advance' THEN
    SELECT id INTO v_bank FROM public.chart_of_accounts WHERE code='1160' LIMIT 1;
  ELSE
    SELECT coa_id INTO v_bank FROM public.bank_accounts WHERE id=v_pv.bank_account_id;
    IF v_bank IS NULL THEN SELECT id INTO v_bank FROM public.chart_of_accounts WHERE code='1101' LIMIT 1; END IF;
  END IF;
  SELECT id INTO v_charge FROM public.chart_of_accounts WHERE code='7100' LIMIT 1;
  SELECT id INTO v_pph FROM public.chart_of_accounts WHERE code='2132' LIMIT 1;
  SELECT id INTO v_fx FROM public.chart_of_accounts WHERE code='7300' LIMIT 1;
  IF v_ap IS NULL OR v_bank IS NULL THEN RAISE EXCEPTION 'Required payment accounts are missing'; END IF;
  IF v_pph_bank > 0 AND v_pph IS NULL THEN RAISE EXCEPTION 'PPh payable account is missing'; END IF;

  v_total := v_ap_debit + v_charge_amt + GREATEST(v_fx_delta,0);
  v_entry := public.next_journal_entry_number();
  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_by)
  VALUES(v_entry,v_pv.voucher_date,'payment',v_pv.id,v_pv.voucher_number,'Payment Voucher: '||v_pv.voucher_number,v_total,v_total,true,p_posted_by)
  RETURNING id INTO v_je;

  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)
  VALUES(v_je,v_line,v_ap,'Payment - '||v_pv.voucher_number,v_ap_debit,0,v_invoice_currency,v_gross,0,v_rate,v_pv.supplier_id); v_line:=v_line+1;
  IF v_charge_amt>0 AND v_charge IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)
    VALUES(v_je,v_line,v_charge,'Bank Charge - '||v_pv.voucher_number,v_charge_amt,0,v_bank_currency,v_charge_amt,0,1,v_pv.supplier_id); v_line:=v_line+1;
  END IF;
  IF v_pph_bank>0 AND v_pph IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)
    VALUES(v_je,v_line,v_pph,'PPh Withholding - '||v_pv.voucher_number,0,v_pph_bank,v_bank_currency,0,v_pv.pph_amount,v_rate,v_pv.supplier_id); v_line:=v_line+1;
  END IF;
  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)
  VALUES(v_je,v_line,v_bank,CASE WHEN v_pv.payment_method='advance_adjustment' THEN 'Advance Adjustment - ' ELSE 'Bank Payment - ' END||v_pv.voucher_number,0,v_actual,v_bank_currency,0,v_actual,1,v_pv.supplier_id); v_line:=v_line+1;
  IF v_fx_delta>0 AND v_fx IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
    VALUES(v_je,v_line,v_fx,'FX loss - '||v_pv.voucher_number,v_fx_delta,0,v_pv.supplier_id);
  ELSIF v_fx_delta<0 AND v_fx IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)
    VALUES(v_je,v_line,v_fx,'FX gain - '||v_pv.voucher_number,0,abs(v_fx_delta),v_pv.supplier_id);
  END IF;
  UPDATE public.payment_vouchers SET is_posted=true,journal_entry_id=v_je WHERE id=p_pv_id;
  INSERT INTO public.audit_logs(table_name,record_id,action_type,old_values,new_values,user_id)
  VALUES('payment_vouchers',p_pv_id,'update',jsonb_build_object('is_posted',false),jsonb_build_object('is_posted',true,'journal_entry_id',v_je),p_posted_by);
END; $$;


--
-- Name: post_payment_voucher_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_payment_voucher_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
v_je_id UUID;
v_je_number TEXT;
v_credit_account_id UUID;
v_debit_account_id UUID;
v_pph_account_id UUID;
v_net_amount DECIMAL(18,2);
BEGIN
-- IDEMPOTENCY: Never create a second JE if one already exists
IF NEW.journal_entry_id IS NOT NULL THEN
RETURN NEW;
END IF;

-- Determine credit account (bank/cash paying out money)
IF NEW.bank_account_id IS NOT NULL THEN
SELECT coa_id INTO v_credit_account_id FROM bank_accounts WHERE id = NEW.bank_account_id;
ELSIF NEW.payment_method = 'cash' THEN
SELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
END IF;

IF v_credit_account_id IS NULL THEN
SELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;
END IF;

-- Determine debit account (A/P or custom)
IF NEW.coa_account_id IS NOT NULL THEN
v_debit_account_id := NEW.coa_account_id;
ELSE
SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '2110' LIMIT 1;
END IF;

SELECT id INTO v_pph_account_id FROM chart_of_accounts WHERE code = '2132' LIMIT 1;

IF v_credit_account_id IS NULL OR v_debit_account_id IS NULL THEN
RETURN NEW;
END IF;

v_net_amount := NEW.amount - COALESCE(NEW.pph_amount, 0);
v_je_number := next_journal_entry_number();

INSERT INTO journal_entries (
entry_number, entry_date, source_module, reference_id, reference_number,
description, total_debit, total_credit, is_posted, posted_by
) VALUES (
v_je_number, NEW.voucher_date, 'payment', NEW.id, NEW.voucher_number,
'Payment Voucher: ' || NEW.voucher_number,
NEW.amount, NEW.amount, true, NEW.created_by
) RETURNING id INTO v_je_id;

INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)
VALUES (v_je_id, 1, v_debit_account_id, 'Payment - ' || NEW.voucher_number, NEW.amount, 0, NEW.supplier_id);

IF COALESCE(NEW.pph_amount, 0) > 0 AND v_pph_account_id IS NOT NULL THEN
INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)
VALUES (v_je_id, 2, v_pph_account_id, 'PPh Withholding - ' || NEW.voucher_number, 0, NEW.pph_amount, NEW.supplier_id);
END IF;

INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)
VALUES (v_je_id, 3, v_credit_account_id, 'Cash Payment - ' || NEW.voucher_number, 0, v_net_amount, NEW.supplier_id);

NEW.journal_entry_id := v_je_id;
RETURN NEW;
END;
$$;


--
-- Name: post_petty_cash_to_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_petty_cash_to_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_journal_id UUID;
v_entry_number TEXT;
v_petty_cash_account_id UUID;
v_bank_account_coa_id UUID;
v_expense_account_id UUID;
v_line_num INT;
BEGIN
IF NEW.source IN ('moved_from_tracker', 'finance_expense', 'migrated_from_expenses') THEN
RETURN NEW;
END IF;

SELECT 'JE-' || TO_CHAR(NEW.transaction_date, 'YYYYMMDD') || '-' ||
LPAD((COUNT(*) + 1)::TEXT, 4, '0')
INTO v_entry_number
FROM journal_entries;

SELECT id INTO v_petty_cash_account_id
FROM chart_of_accounts
WHERE code = '1102' OR code LIKE '1-103%' OR LOWER(name) LIKE '%petty%cash%'
LIMIT 1;

IF v_petty_cash_account_id IS NULL THEN
INSERT INTO chart_of_accounts (code, name, account_type, is_active)
VALUES ('1102', 'Petty Cash', 'asset', true)
RETURNING id INTO v_petty_cash_account_id;
END IF;

IF NEW.transaction_type = 'withdraw' THEN
IF NEW.bank_account_id IS NOT NULL THEN
SELECT coa_id INTO v_bank_account_coa_id
FROM bank_accounts
WHERE id = NEW.bank_account_id;
END IF;

IF v_bank_account_coa_id IS NULL THEN
SELECT id INTO v_bank_account_coa_id
FROM chart_of_accounts
WHERE code LIKE '1-102%' OR LOWER(name) LIKE '%bank%'
ORDER BY code
LIMIT 1;
END IF;

INSERT INTO journal_entries (
entry_number, entry_date, source_module, reference_id, reference_number,
description, is_posted, created_by, posted_at
) VALUES (
v_entry_number, NEW.transaction_date, 'petty_cash', NEW.id, NEW.transaction_number,
'Petty cash withdrawal: ' || COALESCE(NEW.description, ''),
true, NEW.created_by, NOW()
) RETURNING id INTO v_journal_id;

v_line_num := 1;

INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
VALUES (v_journal_id, v_line_num, v_petty_cash_account_id, NEW.amount, 0, 'Cash withdrawal');

IF v_bank_account_coa_id IS NOT NULL THEN
v_line_num := v_line_num + 1;
INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
VALUES (v_journal_id, v_line_num, v_bank_account_coa_id, 0, NEW.amount, 'Transfer to petty cash');
END IF;

ELSIF NEW.transaction_type = 'expense' THEN
SELECT id INTO v_expense_account_id
FROM chart_of_accounts
WHERE account_type = 'expense'
AND (
CASE
WHEN NEW.expense_category = 'Office Supplies'        THEN LOWER(name) LIKE '%office%' OR code = '6-1010'
WHEN NEW.expense_category = 'Transportation'         THEN LOWER(name) LIKE '%transport%' OR code = '6-1020'
WHEN NEW.expense_category = 'Meals & Entertainment'  THEN LOWER(name) LIKE '%entertainment%' OR code = '6-1030'
WHEN NEW.expense_category = 'Postage & Courier'      THEN LOWER(name) LIKE '%postage%' OR code = '6-1040'
WHEN NEW.expense_category = 'Cleaning & Maintenance' THEN LOWER(name) LIKE '%maintenance%' OR code = '6-1050'
WHEN NEW.expense_category = 'Utilities'              THEN LOWER(name) LIKE '%utilities%' OR code = '6-1060'
ELSE code = '6-1090' OR LOWER(name) LIKE '%misc%'
END
)
ORDER BY code
LIMIT 1;

IF v_expense_account_id IS NULL THEN
SELECT id INTO v_expense_account_id
FROM chart_of_accounts
WHERE account_type = 'expense'
ORDER BY code
LIMIT 1;
END IF;

INSERT INTO journal_entries (
entry_number, entry_date, source_module, reference_id, reference_number,
description, is_posted, created_by, posted_at
) VALUES (
v_entry_number, NEW.transaction_date, 'petty_cash', NEW.id, NEW.transaction_number,
'Petty cash expense: ' || COALESCE(NEW.description, ''),
true, NEW.created_by, NOW()
) RETURNING id INTO v_journal_id;

v_line_num := 1;

IF v_expense_account_id IS NOT NULL THEN
INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
VALUES (v_journal_id, v_line_num, v_expense_account_id, NEW.amount, 0, COALESCE(NEW.expense_category, 'Petty cash expense'));
v_line_num := v_line_num + 1;
END IF;

INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)
VALUES (v_journal_id, v_line_num, v_petty_cash_account_id, 0, NEW.amount, 'Petty cash payment');
END IF;

RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "post_petty_cash_to_journal"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."post_petty_cash_to_journal"() IS 'Creates complete journal entries for petty cash transactions with both debit and credit lines';


--
-- Name: post_petty_cash_to_journal_fixed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_petty_cash_to_journal_fixed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_journal_id         uuid;
  v_petty_cash_account uuid;
  v_counter_account    uuid;
  v_expense_account    uuid;
  v_line_num           integer := 0;
  v_je_number          text;
  v_rows                integer;
BEGIN
  IF NEW.fund_transfer_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id
    INTO v_journal_id
    FROM public.journal_entries
   WHERE source_module = 'petty_cash'
     AND reference_id = NEW.id
   LIMIT 1;

  IF v_journal_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id
    INTO v_petty_cash_account
    FROM public.chart_of_accounts
   WHERE code = '1102'
     AND is_header = false
     AND is_active = true
   LIMIT 1;

  IF v_petty_cash_account IS NULL THEN
    RAISE EXCEPTION 'Cannot post petty cash %: active Petty Cash posting account is missing', NEW.id;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext('pc_je_number_' || to_char(NEW.transaction_date, 'YYYYMMDD'))
  );

  SELECT 'JE-' || to_char(NEW.transaction_date, 'YYYYMMDD') || '-' ||
         lpad((COALESCE(MAX((substring(entry_number FROM '[0-9]+$'))::integer), 0) + 1)::text, 4, '0')
    INTO v_je_number
    FROM public.journal_entries
   WHERE entry_date = NEW.transaction_date
     AND entry_number LIKE 'JE-' || to_char(NEW.transaction_date, 'YYYYMMDD') || '-%';

  INSERT INTO public.journal_entries (
    entry_number, entry_date, source_module, reference_id, reference_number,
    description, total_debit, total_credit, is_posted, created_by, posted_at
  ) VALUES (
    v_je_number, NEW.transaction_date, 'petty_cash', NEW.id, NEW.transaction_number,
    'Petty cash ' || NEW.transaction_type || ': ' || NEW.description,
    NEW.amount, NEW.amount, true, NEW.created_by, now()
  ) RETURNING id INTO v_journal_id;

  IF NEW.transaction_type = 'withdraw' THEN
    IF NEW.bank_account_id IS NOT NULL THEN
      SELECT coa_id
        INTO v_counter_account
        FROM public.bank_accounts
       WHERE id = NEW.bank_account_id;
    ELSE
      v_counter_account := NEW.source_account_id;
    END IF;

    IF v_counter_account IS NULL THEN
      RAISE EXCEPTION 'Cannot post petty cash inflow %: select a bank or offset GL account', NEW.id;
    END IF;

    IF v_counter_account = v_petty_cash_account THEN
      RAISE EXCEPTION 'Cannot post petty cash inflow %: offset account cannot be the Petty Cash posting account', NEW.id;
    END IF;

    INSERT INTO public.journal_entry_lines (
      journal_entry_id, line_number, account_id, debit, credit, description
    ) VALUES
      (v_journal_id, 1, v_petty_cash_account, NEW.amount, 0, 'Cash received into petty cash'),
      (v_journal_id, 2, v_counter_account, 0, NEW.amount, COALESCE(NULLIF(NEW.source, ''), 'Petty cash inflow source'));

  ELSIF NEW.transaction_type = 'expense' THEN
    -- This is the single canonical expense-category mapping.  It deliberately
    -- does not translate UI labels or embed account codes here.
    v_expense_account := public.get_expense_account_id(NEW.expense_category);

    IF v_expense_account IS NULL THEN
      RAISE EXCEPTION 'Cannot post petty cash expense %: no configured account for category %', NEW.id, NEW.expense_category;
    END IF;

    INSERT INTO public.journal_entry_lines (
      journal_entry_id, line_number, account_id, debit, credit, description
    ) VALUES
      (v_journal_id, 1, v_expense_account, NEW.amount, 0, COALESCE(NEW.expense_category, 'General expense')),
      (v_journal_id, 2, v_petty_cash_account, 0, NEW.amount, 'Cash expense');
  ELSE
    RAISE EXCEPTION 'Unsupported petty cash transaction type: %', NEW.transaction_type;
  END IF;

  IF NEW.bank_statement_line_id IS NOT NULL THEN
    UPDATE public.bank_statement_lines
       SET matched_petty_cash_id = NEW.id,
           matched_entry_id = v_journal_id,
           reconciliation_status = 'matched',
           matched_at = now(),
           matched_by = COALESCE(NEW.approved_by, NEW.created_by),
           manually_unlinked = false,
           notes = 'Linked to Petty Cash ' || NEW.transaction_number
     WHERE id = NEW.bank_statement_line_id
       AND bank_account_id = NEW.bank_account_id
       AND matched_expense_id IS NULL
       AND matched_receipt_id IS NULL
       AND matched_fund_transfer_id IS NULL
       AND matched_tax_payment_id IS NULL
       AND (matched_petty_cash_id IS NULL OR matched_petty_cash_id = NEW.id)
       AND (matched_entry_id IS NULL OR matched_entry_id = v_journal_id);

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Bank statement line % is unavailable or belongs to another bank account', NEW.bank_statement_line_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: post_purchase_invoice_item_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_purchase_invoice_item_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
v_invoice RECORD;
v_je_id UUID;
v_account_id UUID;
v_inventory_account_id UUID;
v_max_line INTEGER;
BEGIN
-- Get the parent invoice
SELECT * INTO v_invoice FROM purchase_invoices WHERE id = NEW.purchase_invoice_id;

-- If the invoice doesn't have a journal entry yet, it means the header trigger
-- didn't fire yet or failed. Don't post per-item yet — the header trigger handles bulk.
-- Only add to an EXISTING journal entry.
IF v_invoice.journal_entry_id IS NULL THEN
RETURN NEW;
END IF;

v_je_id := v_invoice.journal_entry_id;

-- Check if a line for this specific item already exists (idempotency)
IF EXISTS (
SELECT 1 FROM journal_entry_lines 
WHERE journal_entry_id = v_je_id 
AND debit > 0 
AND description LIKE '%' || LEFT(COALESCE(NEW.description, ''), 50) || '%'
AND debit = NEW.line_total
) THEN
RETURN NEW; -- Already posted
END IF;

-- Determine account
IF NEW.item_type = 'inventory' THEN
SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;
ELSIF NEW.item_type = 'fixed_asset' THEN
v_account_id := NEW.asset_account_id;
IF v_account_id IS NULL THEN
SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1200' LIMIT 1;
END IF;
ELSE
v_account_id := NEW.expense_account_id;
IF v_account_id IS NULL THEN
SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '5100' LIMIT 1;
END IF;
END IF;

IF v_account_id IS NULL THEN RETURN NEW; END IF;

-- Add debit line
SELECT COALESCE(MAX(line_number), 0) INTO v_max_line
FROM journal_entry_lines WHERE journal_entry_id = v_je_id;

INSERT INTO journal_entry_lines (
journal_entry_id, line_number, account_id, description,
debit, credit, supplier_id, batch_id
) VALUES (
v_je_id, v_max_line + 1, v_account_id,
COALESCE(LEFT(NEW.description, 100), 'Purchase Item'),
NEW.line_total, 0, v_invoice.supplier_id, NEW.batch_id
);

-- Update journal entry total_debit
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(SUM(debit), 0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;

RETURN NEW;
END;
$$;


--
-- Name: post_purchase_invoice_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_purchase_invoice_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_je_id uuid; v_ap uuid; v_ppn uuid; v_account uuid; v_line int := 1;
  v_item record; v_currency text := upper(coalesce(NEW.currency,'IDR'));
  v_rate numeric := case when v_currency='IDR' then 1 else coalesce(NEW.exchange_rate,0) end;
  v_items numeric := 0; v_tax numeric := coalesce(NEW.tax_amount,0);
  v_total numeric := coalesce(NEW.total_amount,0);
BEGIN
  IF NEW.journal_entry_id IS NOT NULL THEN RETURN NEW; END IF;
  IF NOT (TG_OP='INSERT' OR (TG_OP='UPDATE' AND OLD.journal_entry_id IS NULL AND NEW.status IN ('unpaid','partial','paid'))) THEN RETURN NEW; END IF;
  IF v_currency <> 'IDR' AND v_rate <= 1 THEN
    RAISE EXCEPTION 'Purchase invoice % requires a valid exchange rate', NEW.invoice_number;
  END IF;
  SELECT id INTO v_ap FROM chart_of_accounts WHERE code='2110' LIMIT 1;
  SELECT id INTO v_ppn FROM chart_of_accounts WHERE code='1150' LIMIT 1;
  IF v_ap IS NULL THEN RETURN NEW; END IF;
  SELECT coalesce(sum(line_total),0) INTO v_items FROM purchase_invoice_items WHERE purchase_invoice_id=NEW.id;
  IF EXISTS (SELECT 1 FROM purchase_invoice_items WHERE purchase_invoice_id=NEW.id)
     AND abs((v_items + v_tax) - v_total) > 0.01 THEN
    RAISE EXCEPTION 'Purchase invoice % totals do not reconcile: item lines + tax (%) != header total (%)', NEW.invoice_number, v_items + v_tax, v_total;
  END IF;
  INSERT INTO journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
  VALUES ('JE-'||to_char(NEW.invoice_date,'YYMM')||'-'||lpad(((select coalesce(max(cast(substring(entry_number from '(\\d+)$') as int)),0)+1 from journal_entries where entry_number like 'JE-'||to_char(NEW.invoice_date,'YYMM')||'-%'))::text,4,'0'),NEW.invoice_date,'purchase_invoice',NEW.id,NEW.invoice_number,'Purchase Invoice: '||NEW.invoice_number,v_total*v_rate,v_total*v_rate,true,NEW.created_by,NEW.created_by,v_currency,'IDR',v_rate,true) RETURNING id INTO v_je_id;
  FOR v_item IN SELECT * FROM purchase_invoice_items WHERE purchase_invoice_id=NEW.id ORDER BY id LOOP
    v_account := CASE WHEN v_item.item_type='inventory' THEN (select id from chart_of_accounts where code='1130' limit 1)
      WHEN v_item.item_type='fixed_asset' THEN coalesce(v_item.asset_account_id,(select id from chart_of_accounts where code='1200' limit 1))
      ELSE coalesce(v_item.expense_account_id,(select id from chart_of_accounts where code='5100' limit 1)) END;
    IF v_account IS NOT NULL THEN
      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id,batch_id,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
      VALUES(v_je_id,v_line,v_account,coalesce(left(v_item.description,100),'Purchase - '||NEW.invoice_number),v_item.line_total*v_rate,0,NEW.supplier_id,v_item.batch_id,v_currency,v_item.line_total,0,'IDR',v_rate); v_line:=v_line+1;
    END IF;
  END LOOP;
  IF v_tax > 0 AND v_ppn IS NOT NULL THEN
    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
    VALUES(v_je_id,v_line,v_ppn,'PPN Input - '||NEW.invoice_number,v_tax*v_rate,0,NEW.supplier_id,v_currency,v_tax,0,'IDR',v_rate); v_line:=v_line+1;
  END IF;
  INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
  VALUES(v_je_id,v_line,v_ap,'A/P - '||NEW.invoice_number,0,v_total*v_rate,NEW.supplier_id,v_currency,0,v_total,'IDR',v_rate);
  NEW.journal_entry_id:=v_je_id; RETURN NEW;
END; $_$;


--
-- Name: post_receipt_voucher("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_receipt_voucher"("p_rv_id" "uuid", "p_posted_by" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_rv                 RECORD;
v_je_id              UUID;
v_je_number          TEXT;
v_debit_account_id   UUID;
v_credit_account_id  UUID;
BEGIN
IF auth.uid() IS NULL THEN
RAISE EXCEPTION 'Not authenticated';
END IF;

SELECT * INTO v_rv FROM receipt_vouchers WHERE id = p_rv_id FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id; END IF;
IF v_rv.is_posted THEN RAISE EXCEPTION 'Receipt voucher % is already posted', v_rv.voucher_number; END IF;

IF v_rv.bank_account_id IS NOT NULL THEN
SELECT coa_id INTO v_debit_account_id FROM bank_accounts WHERE id = v_rv.bank_account_id;
ELSIF v_rv.payment_method = 'cash' THEN
SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
END IF;
IF v_debit_account_id IS NULL THEN
SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;
END IF;

IF v_rv.coa_account_id IS NOT NULL THEN
v_credit_account_id := v_rv.coa_account_id;
ELSE
SELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1120' LIMIT 1;
END IF;

IF v_debit_account_id IS NULL OR v_credit_account_id IS NULL THEN
RAISE EXCEPTION 'Cannot post: required chart of accounts entries missing';
END IF;

v_je_number := next_journal_entry_number();

INSERT INTO journal_entries (
entry_number, entry_date, source_module, reference_id, reference_number,
description, total_debit, total_credit, is_posted, posted_by
) VALUES (
v_je_number, v_rv.voucher_date, 'receipt', v_rv.id, v_rv.voucher_number,
'Receipt Voucher: ' || v_rv.voucher_number,
v_rv.amount, v_rv.amount, TRUE, p_posted_by
) RETURNING id INTO v_je_id;

INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
VALUES (v_je_id, 1, v_debit_account_id, 'Cash Receipt - ' || v_rv.voucher_number, v_rv.amount, 0, v_rv.customer_id);
INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
VALUES (v_je_id, 2, v_credit_account_id, 'Receipt - ' || v_rv.voucher_number, 0, v_rv.amount, v_rv.customer_id);

UPDATE receipt_vouchers
SET is_posted = TRUE, journal_entry_id = v_je_id
WHERE id = p_rv_id;

INSERT INTO audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)
VALUES (
'receipt_vouchers', p_rv_id, 'update',
jsonb_build_object('is_posted', FALSE),
jsonb_build_object('is_posted', TRUE, 'journal_entry_id', v_je_id, 'journal_entry_number', v_je_number, 'posted_by', p_posted_by),
p_posted_by
);
END;
$$;


--
-- Name: post_receipt_voucher_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_receipt_voucher_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
v_je_id UUID;
v_je_number TEXT;
v_debit_account_id UUID;
v_credit_account_id UUID;
BEGIN
-- IDEMPOTENCY: Never create a second JE if one already exists
IF NEW.journal_entry_id IS NOT NULL THEN
RETURN NEW;
END IF;

-- Determine debit account (bank/cash account receiving money)
IF NEW.bank_account_id IS NOT NULL THEN
SELECT coa_id INTO v_debit_account_id FROM bank_accounts WHERE id = NEW.bank_account_id;
ELSIF NEW.payment_method = 'cash' THEN
SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;
END IF;

IF v_debit_account_id IS NULL THEN
SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;
END IF;

-- Determine credit account (AR or custom)
IF NEW.coa_account_id IS NOT NULL THEN
v_credit_account_id := NEW.coa_account_id;
ELSE
SELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1120' LIMIT 1;
END IF;

IF v_debit_account_id IS NULL OR v_credit_account_id IS NULL THEN
RETURN NEW;
END IF;

v_je_number := next_journal_entry_number();

INSERT INTO journal_entries (
entry_number, entry_date, source_module, reference_id, reference_number,
description, total_debit, total_credit, is_posted, posted_by
) VALUES (
v_je_number, NEW.voucher_date, 'receipt', NEW.id, NEW.voucher_number,
'Receipt Voucher: ' || NEW.voucher_number,
NEW.amount, NEW.amount, true, NEW.created_by
) RETURNING id INTO v_je_id;

INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
VALUES (v_je_id, 1, v_debit_account_id, 'Cash Receipt - ' || NEW.voucher_number, NEW.amount, 0, NEW.customer_id);

INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
VALUES (v_je_id, 2, v_credit_account_id, 'Receipt - ' || NEW.voucher_number, 0, NEW.amount, NEW.customer_id);

NEW.journal_entry_id := v_je_id;
RETURN NEW;
END;
$$;


--
-- Name: post_sales_invoice_cogs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_sales_invoice_cogs"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing_cogs_je_id UUID;
  v_je_id UUID;
  v_je_number TEXT;
  v_cogs_account_id UUID;
  v_inventory_account_id UUID;
  v_item RECORD;
  v_total_cogs NUMERIC := 0;
BEGIN
  -- Only consider invoices that have already had their revenue JE posted.
  IF NEW.journal_entry_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Skip non-billable invoices (drafts, voids, cancellations).
  IF NEW.payment_status NOT IN ('pending', 'partial', 'paid') THEN
    RETURN NEW;
  END IF;

  -- Idempotency: never post a second COGS JE for the same invoice.
  SELECT id INTO v_existing_cogs_je_id
  FROM journal_entries
  WHERE source_module = 'sales_invoice_cogs'
    AND reference_id = NEW.id
  LIMIT 1;

  IF v_existing_cogs_je_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_cogs_account_id      FROM chart_of_accounts WHERE code = '5100' LIMIT 1;
  SELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;

  IF v_cogs_account_id IS NULL OR v_inventory_account_id IS NULL THEN
    RAISE EXCEPTION
      'post_sales_invoice_cogs: chart_of_accounts is missing 5100 (COGS) or 1130 (Inventory). Cannot post COGS for invoice %.',
      NEW.invoice_number;
  END IF;

  -- Compute COGS from items: landed_cost_per_unit -> import_price -> cost_per_unit -> 0
  FOR v_item IN
    SELECT
      sii.quantity,
      sii.batch_id,
      COALESCE(
        NULLIF(b.landed_cost_per_unit, 0),
        NULLIF(b.import_price, 0),
        NULLIF(b.cost_per_unit, 0),
        0
      ) AS effective_cost
    FROM sales_invoice_items sii
    LEFT JOIN batches b ON b.id = sii.batch_id
    WHERE sii.invoice_id = NEW.id
      AND sii.batch_id IS NOT NULL
  LOOP
    v_total_cogs := v_total_cogs + (COALESCE(v_item.quantity, 0) * v_item.effective_cost);
  END LOOP;

  -- No cost basis available. Nothing to post.
  IF v_total_cogs <= 0 THEN
    RETURN NEW;
  END IF;

  v_je_number := next_journal_entry_number();

  INSERT INTO journal_entries (
    entry_number, entry_date, source_module, reference_id, reference_number,
    description, total_debit, total_credit, is_posted, posted_by, created_by
  ) VALUES (
    v_je_number, NEW.invoice_date, 'sales_invoice_cogs', NEW.id, NEW.invoice_number,
    'COGS for Sales Invoice: ' || NEW.invoice_number,
    v_total_cogs, v_total_cogs, true, NEW.created_by, NEW.created_by
  )
  RETURNING id INTO v_je_id;

  -- Dr: COGS
  INSERT INTO journal_entry_lines (
    journal_entry_id, line_number, account_id, description, debit, credit, customer_id
  ) VALUES (
    v_je_id, 1, v_cogs_account_id, 'COGS - ' || NEW.invoice_number,
    v_total_cogs, 0, NEW.customer_id
  );

  -- Cr: Inventory
  INSERT INTO journal_entry_lines (
    journal_entry_id, line_number, account_id, description, debit, credit, customer_id
  ) VALUES (
    v_je_id, 2, v_inventory_account_id, 'Inventory - ' || NEW.invoice_number,
    0, v_total_cogs, NEW.customer_id
  );

  RETURN NEW;

EXCEPTION
  WHEN OTHERS THEN
    RAISE LOG 'post_sales_invoice_cogs failed for invoice %: %', NEW.id, SQLERRM;
    RAISE;
END;
$$;


--
-- Name: FUNCTION "post_sales_invoice_cogs"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."post_sales_invoice_cogs"() IS 'Posts the COGS portion of a sales invoice as a separate balanced JE (Dr 5100, Cr 1130). Fires as a DEFERRABLE INITIALLY DEFERRED constraint trigger so sales_invoice_items are guaranteed to exist at firing time. Cost basis: COALESCE(landed_cost_per_unit, cost_per_unit, 0). Idempotent: skips if a sales_invoice_cogs JE already exists for the invoice.';


--
-- Name: post_sales_invoice_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_sales_invoice_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_existing_je_id uuid;
  v_je_id uuid;
  v_je_number text;
  v_ar_account_id uuid;
  v_revenue_account_id uuid;
  v_tax_account_id uuid;
  v_bm_expense_id uuid;
  v_line_num integer := 1;
  v_total_debit numeric := 0;
  v_total_credit numeric := 0;
  v_stamp_duty numeric;
BEGIN
  IF current_setting('app.sales_invoice_rebuild', true) = 'true' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.journal_entry_id IS NULL
     AND OLD.journal_entry_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.journal_entry_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_existing_je_id
  FROM journal_entries
  WHERE source_module = 'sales_invoice' AND reference_id = NEW.id
  LIMIT 1;
  IF v_existing_je_id IS NOT NULL THEN
    NEW.journal_entry_id := v_existing_je_id;
    RETURN NEW;
  END IF;

  IF NEW.payment_status NOT IN ('pending', 'partial', 'paid') THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_ar_account_id FROM chart_of_accounts WHERE code = '1120' LIMIT 1;
  SELECT id INTO v_revenue_account_id FROM chart_of_accounts WHERE code = '4100' LIMIT 1;
  SELECT id INTO v_tax_account_id FROM chart_of_accounts WHERE code = '2130' LIMIT 1;
  SELECT id INTO v_bm_expense_id FROM chart_of_accounts WHERE code = '6950' LIMIT 1;
  IF v_ar_account_id IS NULL OR v_revenue_account_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_stamp_duty := COALESCE(NEW.stamp_duty_amount, 0);
  v_je_number := next_journal_entry_number();
  INSERT INTO journal_entries (
    entry_number, entry_date, source_module, reference_id, reference_number,
    description, total_debit, total_credit, is_posted, posted_by, created_by
  ) VALUES (
    v_je_number, NEW.invoice_date, 'sales_invoice', NEW.id, NEW.invoice_number,
    'Sales Invoice: ' || NEW.invoice_number,
    NEW.total_amount, NEW.total_amount, true, NEW.created_by, NEW.created_by
  ) RETURNING id INTO v_je_id;

  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
  VALUES (v_je_id, v_line_num, v_ar_account_id, 'A/R - ' || NEW.invoice_number, NEW.total_amount, 0, NEW.customer_id);
  v_line_num := v_line_num + 1;
  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
  VALUES (v_je_id, v_line_num, v_revenue_account_id, 'Sales - ' || NEW.invoice_number, 0, NEW.subtotal, NEW.customer_id);
  v_line_num := v_line_num + 1;
  IF COALESCE(NEW.tax_amount, 0) > 0 AND v_tax_account_id IS NOT NULL THEN
    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
    VALUES (v_je_id, v_line_num, v_tax_account_id, 'PPN - ' || NEW.invoice_number, 0, NEW.tax_amount, NEW.customer_id);
    v_line_num := v_line_num + 1;
  END IF;
  IF v_stamp_duty > 0 AND v_bm_expense_id IS NOT NULL THEN
    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
    VALUES (v_je_id, v_line_num, v_bm_expense_id, 'Bea Meterai (cost recovery) - ' || NEW.invoice_number, 0, v_stamp_duty, NEW.customer_id);
    v_line_num := v_line_num + 1;
  END IF;

  -- COGS is posted by the existing deferred post_sales_invoice_cogs()
  -- trigger. Keeping it out of this revenue journal avoids double posting.
  v_total_debit := COALESCE(NEW.total_amount, 0);
  v_total_credit := COALESCE(NEW.subtotal, 0) + COALESCE(NEW.tax_amount, 0) + v_stamp_duty;
  IF v_total_debit <> v_total_credit THEN
    RAISE EXCEPTION 'Journal not balanced: debit=% credit=%', v_total_debit, v_total_credit;
  END IF;
  NEW.journal_entry_id := v_je_id;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE LOG 'post_sales_invoice_journal failed for invoice %: %', NEW.id, SQLERRM;
  RAISE;
END;
$$;


--
-- Name: FUNCTION "post_sales_invoice_journal"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."post_sales_invoice_journal"() IS 'Sales invoice journal posting wrapper; preserves explicit NULL during atomic journal replacement.';


--
-- Name: post_sales_invoice_journal_impl(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_sales_invoice_journal_impl"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_existing_je_id       UUID;
  v_je_id                UUID;
  v_je_number            TEXT;
  v_ar_account_id        UUID;
  v_revenue_account_id   UUID;
  v_tax_account_id       UUID;
  v_bm_expense_id        UUID;   -- 6950 Bea Meterai Expense (cost recovery credit)
  v_cogs_account_id      UUID;
  v_inventory_account_id UUID;
  v_item                 RECORD;
  v_line_num             INTEGER := 1;
  v_total_cost           NUMERIC := 0;
  v_item_cost            NUMERIC;
  v_total_debit          NUMERIC := 0;
  v_total_credit         NUMERIC := 0;
  v_stamp_duty           NUMERIC;
BEGIN

  -- Strict idempotency: JE already set → skip
  IF NEW.journal_entry_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_existing_je_id
  FROM journal_entries
  WHERE source_module = 'sales_invoice'
    AND reference_id  = NEW.id
  LIMIT 1;

  IF v_existing_je_id IS NOT NULL THEN
    NEW.journal_entry_id := v_existing_je_id;
    RETURN NEW;
  END IF;

  IF NEW.payment_status NOT IN ('pending', 'partial', 'paid') THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_ar_account_id        FROM chart_of_accounts WHERE code = '1120' LIMIT 1;
  SELECT id INTO v_revenue_account_id   FROM chart_of_accounts WHERE code = '4100' LIMIT 1;
  SELECT id INTO v_tax_account_id       FROM chart_of_accounts WHERE code = '2130' LIMIT 1;
  SELECT id INTO v_bm_expense_id        FROM chart_of_accounts WHERE code = '6950' LIMIT 1;
  SELECT id INTO v_cogs_account_id      FROM chart_of_accounts WHERE code = '5100' LIMIT 1;
  SELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;

  IF v_ar_account_id IS NULL OR v_revenue_account_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_stamp_duty := COALESCE(NEW.stamp_duty_amount, 0);

  v_je_number := next_journal_entry_number();

  INSERT INTO journal_entries (
    entry_number, entry_date, source_module, reference_id, reference_number,
    description, total_debit, total_credit, is_posted, posted_by, created_by
  ) VALUES (
    v_je_number, NEW.invoice_date, 'sales_invoice', NEW.id, NEW.invoice_number,
    'Sales Invoice: ' || NEW.invoice_number,
    NEW.total_amount, NEW.total_amount, true, NEW.created_by, NEW.created_by
  ) RETURNING id INTO v_je_id;

  -- Dr: Accounts Receivable (full invoice total)
  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
  VALUES (v_je_id, v_line_num, v_ar_account_id, 'A/R - ' || NEW.invoice_number, NEW.total_amount, 0, NEW.customer_id);
  v_line_num := v_line_num + 1;

  -- Cr: Sales Revenue (subtotal)
  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
  VALUES (v_je_id, v_line_num, v_revenue_account_id, 'Sales - ' || NEW.invoice_number, 0, NEW.subtotal, NEW.customer_id);
  v_line_num := v_line_num + 1;

  -- Cr: PPN Output 2130 (if any)
  IF COALESCE(NEW.tax_amount, 0) > 0 AND v_tax_account_id IS NOT NULL THEN
    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
    VALUES (v_je_id, v_line_num, v_tax_account_id, 'PPN - ' || NEW.invoice_number, 0, NEW.tax_amount, NEW.customer_id);
    v_line_num := v_line_num + 1;
  END IF;

  -- Cr: Bea Meterai Expense 6950 (cost recovery — offsets original stamp purchase expense)
  -- When the customer reimburses stamp duty, we credit the same expense account
  -- that was debited when stamps were originally purchased. Net P&L effect =
  -- original purchase cost minus recoveries collected from customers.
  IF v_stamp_duty > 0 AND v_bm_expense_id IS NOT NULL THEN
    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
    VALUES (v_je_id, v_line_num, v_bm_expense_id,
            'Bea Meterai (cost recovery) - ' || NEW.invoice_number,
            0, v_stamp_duty, NEW.customer_id);
    v_line_num := v_line_num + 1;
  END IF;

  -- COGS entries (inventory cost of goods sold)
  IF v_cogs_account_id IS NOT NULL AND v_inventory_account_id IS NOT NULL THEN
    FOR v_item IN
      SELECT sii.quantity, b.cost_per_unit, b.id as batch_id
      FROM sales_invoice_items sii
      LEFT JOIN batches b ON b.id = sii.batch_id
      WHERE sii.invoice_id = NEW.id AND sii.batch_id IS NOT NULL
    LOOP
      v_item_cost  := COALESCE(v_item.cost_per_unit, 0) * v_item.quantity;
      v_total_cost := v_total_cost + v_item_cost;
    END LOOP;

    IF v_total_cost > 0 THEN
      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
      VALUES (v_je_id, v_line_num, v_cogs_account_id, 'COGS - ' || NEW.invoice_number, v_total_cost, 0, NEW.customer_id);
      v_line_num := v_line_num + 1;

      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
      VALUES (v_je_id, v_line_num, v_inventory_account_id, 'Inventory - ' || NEW.invoice_number, 0, v_total_cost, NEW.customer_id);
    END IF;
  END IF;

  -- Balance assertion:
  -- total_debit  = total_amount + cogs
  -- total_credit = subtotal + tax + stamp_duty + cogs
  --             = (subtotal + tax + stamp_duty) + cogs
  --             = total_amount + cogs  ✓
  v_total_debit  := COALESCE(NEW.total_amount, 0) + COALESCE(v_total_cost, 0);
  v_total_credit := COALESCE(NEW.subtotal, 0)
                 + COALESCE(NEW.tax_amount, 0)
                 + v_stamp_duty
                 + COALESCE(v_total_cost, 0);

  IF v_total_debit <> v_total_credit THEN
    RAISE EXCEPTION 'Journal not balanced: debit=% credit=%', v_total_debit, v_total_credit;
  END IF;

  NEW.journal_entry_id := v_je_id;
  RETURN NEW;

EXCEPTION
  WHEN OTHERS THEN
    RAISE LOG 'post_sales_invoice_journal failed for invoice %: %', NEW.id, SQLERRM;
    RAISE;
END;
$$;


--
-- Name: FUNCTION "post_sales_invoice_journal_impl"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."post_sales_invoice_journal_impl"() IS 'Posts the REVENUE portion of a sales invoice (Dr AR, Cr Sales, Cr PPN). COGS is posted separately by post_sales_invoice_cogs via a DEFERRABLE constraint trigger so child sales_invoice_items are guaranteed to exist.';


--
-- Name: prevent_active_customer_identity_duplicate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_active_customer_identity_duplicate"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_id text;
BEGIN
  IF COALESCE(NEW.is_active,true) THEN
    IF public.normalize_customer_identity(NEW.company_name) <> '' AND EXISTS (
      SELECT 1 FROM public.customers c WHERE c.id<>NEW.id AND COALESCE(c.is_active,true)
        AND public.normalize_customer_identity(c.company_name)=public.normalize_customer_identity(NEW.company_name)
    ) THEN RAISE EXCEPTION 'Possible existing customer found: exact normalized legal name already exists' USING ERRCODE='unique_violation'; END IF;
    v_id:=public.normalize_customer_tax_id(NEW.npwp);
    IF v_id<>'' AND EXISTS (
      SELECT 1 FROM public.customers c WHERE c.id<>NEW.id AND COALESCE(c.is_active,true)
        AND public.normalize_customer_tax_id(c.npwp)=v_id
    ) THEN RAISE EXCEPTION 'Possible existing customer found: NPWP/tax ID already exists' USING ERRCODE='unique_violation'; END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_active_fund_transfer_statement_reuse(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_active_fund_transfer_statement_reuse"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status IN ('cancelled', 'reversed') THEN RETURN NEW; END IF;
  IF NEW.from_bank_statement_line_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.fund_transfers ft
     WHERE ft.id <> NEW.id AND ft.status NOT IN ('cancelled', 'reversed')
       AND ft.from_bank_statement_line_id = NEW.from_bank_statement_line_id
  ) THEN
    RAISE EXCEPTION 'Active bank statement line is already used by another fund transfer';
  END IF;
  IF NEW.to_bank_statement_line_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.fund_transfers ft
     WHERE ft.id <> NEW.id AND ft.status NOT IN ('cancelled', 'reversed')
       AND ft.to_bank_statement_line_id = NEW.to_bank_statement_line_id
  ) THEN
    RAISE EXCEPTION 'Active bank statement line is already used by another fund transfer';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "prevent_active_fund_transfer_statement_reuse"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."prevent_active_fund_transfer_statement_reuse"() IS 'Prevents active fund transfers from reusing statement evidence owned by another active transfer; reversals release it.';


--
-- Name: prevent_deleting_allocated_finance_document(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_deleting_allocated_finance_document"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.bank_statement_allocations
     WHERE document_type = TG_ARGV[0]
       AND document_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'Document has bank reconciliation allocations. Use the canonical delete command so they can be released atomically.';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: prevent_empty_delivery_challans(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_empty_delivery_challans"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
-- Check if the DC has any items
IF NOT EXISTS (
SELECT 1 FROM delivery_challan_items
WHERE challan_id = OLD.challan_id
) THEN
-- If no items exist after delete, delete the DC
DELETE FROM delivery_challans WHERE id = OLD.challan_id;
END IF;

RETURN OLD;
END;
$$;


--
-- Name: prevent_header_account_posting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_header_account_posting"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_code TEXT;
  v_is_header BOOLEAN;
BEGIN
  SELECT code, is_header
    INTO v_code, v_is_header
    FROM chart_of_accounts
   WHERE id = NEW.account_id;

  IF COALESCE(v_is_header, false) THEN
    RAISE EXCEPTION
      'Journal lines cannot be posted to header account % — use a leaf account instead', v_code;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_linked_dc_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_linked_dc_deletion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invoice_number text;
  v_invoice_exists boolean;
BEGIN
  -- Check if this DC is linked to any invoice (cast UUID to text for array comparison)
  SELECT EXISTS (
    SELECT 1 
    FROM sales_invoices si
    WHERE OLD.id::text = ANY(si.linked_challan_ids)
  ) INTO v_invoice_exists;

  IF v_invoice_exists THEN
    -- Get the invoice number
    SELECT invoice_number INTO v_invoice_number
    FROM sales_invoices
    WHERE OLD.id::text = ANY(linked_challan_ids)
    LIMIT 1;

    RAISE EXCEPTION 'Cannot delete Delivery Challan %. It is linked to Invoice %. Please delete the invoice first or remove this DC from the invoice.',
      OLD.challan_number, v_invoice_number
      USING HINT = 'Delete or edit the invoice to unlink this Delivery Challan first.';
  END IF;

  RETURN OLD;
END;
$$;


--
-- Name: FUNCTION "prevent_linked_dc_deletion"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."prevent_linked_dc_deletion"() IS 'Prevents deletion of DCs that are linked to invoices';


--
-- Name: prevent_linked_invoice_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_linked_invoice_deletion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_dc_count integer;
BEGIN
-- Check if invoice is linked to any DCs
IF OLD.linked_challan_ids IS NOT NULL AND array_length(OLD.linked_challan_ids, 1) > 0 THEN
-- Get the number of DCs
v_dc_count := array_length(OLD.linked_challan_ids, 1);

RAISE EXCEPTION 'Cannot delete invoice %. It is linked to % Delivery Challan(s). Please delete or unlink the DCs first.',
OLD.invoice_number, v_dc_count
USING HINT = 'Delete the linked Delivery Challans or remove them from this invoice before deleting.';
END IF;

RETURN OLD;
END;
$$;


--
-- Name: FUNCTION "prevent_linked_invoice_deletion"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."prevent_linked_invoice_deletion"() IS 'Prevents deletion of invoices that are linked to DCs';


--
-- Name: prevent_multiple_bank_line_document_owners(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_multiple_bank_line_document_owners"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF num_nonnulls(NEW.matched_expense_id, NEW.matched_receipt_id,
                  NEW.matched_payment_id, NEW.matched_petty_cash_id,
                  NEW.matched_fund_transfer_id, NEW.matched_tax_payment_id) > 1 THEN
    RAISE EXCEPTION 'Bank statement line % cannot be linked to more than one source document', NEW.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_purchase_invoice_payment_overallocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_purchase_invoice_payment_overallocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_total numeric;
  v_existing numeric;
BEGIN
  IF NEW.voucher_type <> 'payment' OR NEW.purchase_invoice_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT total_amount INTO v_total
    FROM public.purchase_invoices
   WHERE id = NEW.purchase_invoice_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Purchase invoice % not found', NEW.purchase_invoice_id;
  END IF;

  SELECT COALESCE(SUM(allocated_amount), 0) INTO v_existing
    FROM public.voucher_allocations
   WHERE purchase_invoice_id = NEW.purchase_invoice_id
     AND voucher_type = 'payment'
     AND (TG_OP <> 'UPDATE' OR id <> NEW.id);

  IF v_existing + NEW.allocated_amount > COALESCE(v_total, 0) + 0.01 THEN
    RAISE EXCEPTION 'Payment allocation exceeds Purchase Invoice outstanding amount';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prevent_receipt_allocation_overpayment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_receipt_allocation_overpayment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_receipt_amount numeric;
  v_existing numeric;
BEGIN
  IF NEW.voucher_type <> 'receipt' OR NEW.receipt_voucher_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.sales_invoice_id IS NULL AND NEW.sales_order_id IS NULL THEN
    RAISE EXCEPTION 'Receipt allocation must reference a sales invoice or sales order';
  END IF;
  IF NEW.sales_invoice_id IS NOT NULL AND NEW.sales_order_id IS NOT NULL THEN
    RAISE EXCEPTION 'Receipt allocation cannot reference both a sales invoice and sales order';
  END IF;
  IF COALESCE(NEW.allocated_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Receipt allocation amount must be greater than zero';
  END IF;

  -- Lock the voucher while checking to make concurrent allocations safe.
  SELECT amount INTO v_receipt_amount
    FROM public.receipt_vouchers
   WHERE id = NEW.receipt_voucher_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt voucher % not found', NEW.receipt_voucher_id;
  END IF;

  SELECT COALESCE(sum(allocated_amount), 0) INTO v_existing
    FROM public.voucher_allocations
   WHERE receipt_voucher_id = NEW.receipt_voucher_id
     AND voucher_type = 'receipt'
     AND (TG_OP <> 'UPDATE' OR id <> NEW.id);
  IF v_existing + NEW.allocated_amount > COALESCE(v_receipt_amount, 0) + 0.01 THEN
    RAISE EXCEPTION 'Receipt allocations exceed receipt amount (%, attempted %) ',
      v_receipt_amount, v_existing + NEW.allocated_amount;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "prevent_receipt_allocation_overpayment"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."prevent_receipt_allocation_overpayment"() IS 'Prevents receipt allocations from exceeding voucher amount and enforces one target per allocation.';


--
-- Name: prevent_self_approval_expense(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_self_approval_expense"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      DECLARE
        v_role text;
      BEGIN
        IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
        IF auth.role() = 'service_role' THEN RETURN NEW; END IF;
        IF NEW.approval_status IS DISTINCT FROM OLD.approval_status
           AND NEW.approval_status = 'approved' THEN
          SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();
          IF v_role = 'accounts' AND OLD.created_by = auth.uid() THEN
            RAISE EXCEPTION 'You cannot approve your own expense entry';
          END IF;
          IF v_role NOT IN ('admin','accounts') THEN
            RAISE EXCEPTION 'Only admin/accounts can approve expenses';
          END IF;
          NEW.approved_by := auth.uid();
        END IF;
        RETURN NEW;
      END $$;


--
-- Name: prevent_self_approval_petty_cash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_self_approval_petty_cash"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      DECLARE
        v_role text;
      BEGIN
        IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
        IF auth.role() = 'service_role' THEN RETURN NEW; END IF;
        IF NEW.approval_status IS DISTINCT FROM OLD.approval_status
           AND NEW.approval_status = 'approved' THEN
          SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();
          IF v_role = 'accounts' AND OLD.created_by = auth.uid() THEN
