          NEW.approved_by := auth.uid();
        END IF;
        RETURN NEW;
      END $$;


--
-- Name: prevent_self_privilege_escalation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_self_privilege_escalation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_role text;
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
  IF auth.role() = 'service_role' THEN RETURN NEW; END IF;

  SELECT role INTO v_caller_role
  FROM public.user_profiles
  WHERE id = auth.uid();

  IF NEW.role IS DISTINCT FROM OLD.role THEN
    IF auth.uid() = OLD.id OR COALESCE(v_caller_role, '') <> 'admin' THEN
      RAISE EXCEPTION 'Role changes must be made by an admin via admin-update-user';
    END IF;
  END IF;

  IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN
    IF auth.uid() = OLD.id OR COALESCE(v_caller_role, '') <> 'admin' THEN
      RAISE EXCEPTION 'is_active changes must be made by an admin';
    END IF;
  END IF;

  IF NEW.username IS DISTINCT FROM OLD.username THEN
    IF auth.uid() = OLD.id AND COALESCE(v_caller_role, '') <> 'admin' THEN
      RAISE EXCEPTION 'Username changes must be made by an admin';
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: prevent_unsafe_settled_salary_edit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_unsafe_settled_salary_edit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.expense_category = 'salary'
     AND EXISTS (SELECT 1 FROM public.salary_advance_applications sa WHERE sa.salary_expense_id = OLD.id)
     AND (OLD.amount, OLD.staff_id, OLD.pph_amount, OLD.payment_method, OLD.bank_account_id)
         IS DISTINCT FROM (NEW.amount, NEW.staff_id, NEW.pph_amount, NEW.payment_method, NEW.bank_account_id) THEN
    RAISE EXCEPTION
      'Salary % has applied advances. Reverse or correct its settlement before changing gross, staff, withholding, payment method, or bank account.', OLD.voucher_number
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


