--
-- Name: preview_bank_statement_delete("uuid", "date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."preview_bank_statement_delete"("p_bank_account_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_bank_info JSON;
v_total_count INTEGER;
v_reconciled_count INTEGER;
v_unmatched_count INTEGER;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot preview bank statement deletions', v_role;
END IF;

SELECT json_build_object(
'account_name',   account_name,
'bank_name',      bank_name,
'account_number', account_number,
'currency',       currency
) INTO v_bank_info
FROM bank_accounts WHERE id = p_bank_account_id;

SELECT
COUNT(*),
COUNT(*) FILTER (WHERE reconciliation_status IN ('matched', 'recorded', 'suggested')),
COUNT(*) FILTER (WHERE reconciliation_status = 'unmatched')
INTO v_total_count, v_reconciled_count, v_unmatched_count
FROM bank_statement_lines
WHERE bank_account_id = p_bank_account_id
AND transaction_date >= p_start_date
AND transaction_date <= p_end_date;

RETURN json_build_object(
'bank_info',        v_bank_info,
'start_date',       p_start_date,
'end_date',         p_end_date,
'total_count',      v_total_count,
'reconciled_count', v_reconciled_count,
'unmatched_count',  v_unmatched_count,
'can_delete',       v_reconciled_count = 0 AND v_total_count > 0,
'warning', CASE
WHEN v_reconciled_count > 0 THEN 'Cannot delete: Contains ' || v_reconciled_count || ' reconciled transaction(s). Please unreconcile first.'
WHEN v_total_count = 0      THEN 'No transactions found in this date range'
ELSE NULL
END
);
END;
$$;


--
-- Name: product_available_to_promise("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."product_available_to_promise"("p_product_id" "uuid", "p_exclude_sales_order_item_id" "uuid" DEFAULT NULL::"uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT GREATEST(
    COALESCE((SELECT sum(b.current_stock) FROM public.batches b
      WHERE b.product_id=p_product_id AND b.is_active=true
        AND (b.expiry_date IS NULL OR b.expiry_date>CURRENT_DATE)),0)
    - COALESCE((SELECT sum(r.reserved_quantity) FROM public.so_product_reservations r
      WHERE r.product_id=p_product_id AND r.status='active'
        AND (p_exclude_sales_order_item_id IS NULL OR r.sales_order_item_id<>p_exclude_sales_order_item_id)),0)
    - COALESCE((SELECT sum(sr.reserved_quantity) FROM public.stock_reservations sr
      WHERE sr.product_id=p_product_id AND sr.status='active' AND NOT sr.is_released
        AND (p_exclude_sales_order_item_id IS NULL OR sr.sales_order_item_id<>p_exclude_sales_order_item_id)
        AND NOT EXISTS (SELECT 1 FROM public.so_product_reservations migrated
          WHERE sr.id=ANY(migrated.legacy_reservation_ids))),0),0);
$$;


--
-- Name: propagate_bank_line_amount_edit("uuid", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."propagate_bank_line_amount_edit"("p_line_id" "uuid", "p_new_amount" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_line record;
v_old_amount numeric;
v_doc_type text;
v_doc_id uuid;
v_je_id uuid;
BEGIN
SELECT * INTO v_line FROM bank_statement_lines WHERE id = p_line_id;
IF NOT FOUND THEN
RETURN jsonb_build_object('ok', false, 'error', 'Bank statement line not found');
END IF;

v_old_amount := COALESCE(v_line.debit_amount, 0) + COALESCE(v_line.credit_amount, 0);

-- Determine linked document type and ID
IF v_line.matched_expense_id IS NOT NULL THEN
v_doc_type := 'expense';
v_doc_id := v_line.matched_expense_id;
-- Update expense amount; trigger_auto_post_expense_accounting_update will:
-- 1. Check if amount actually changed (idempotency guard)
-- 2. Delete old journal entry
-- 3. Create new journal entry with correct amount
-- No double post possible — trigger deletes before inserting.
UPDATE finance_expenses SET amount = p_new_amount WHERE id = v_doc_id;

ELSIF v_line.matched_receipt_id IS NOT NULL THEN
v_doc_type := 'receipt_voucher';
v_doc_id := v_line.matched_receipt_id;
UPDATE receipt_vouchers SET amount = p_new_amount WHERE id = v_doc_id;
-- Find linked JE and update lines (no trigger re-posts on amount change)
SELECT journal_entry_id INTO v_je_id FROM receipt_vouchers WHERE id = v_doc_id;
IF v_je_id IS NOT NULL THEN
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;
END IF;

ELSIF v_line.matched_payment_id IS NOT NULL THEN
v_doc_type := 'payment_voucher';
v_doc_id := v_line.matched_payment_id;
UPDATE payment_vouchers SET amount = p_new_amount WHERE id = v_doc_id;
SELECT journal_entry_id INTO v_je_id FROM payment_vouchers WHERE id = v_doc_id;
IF v_je_id IS NOT NULL THEN
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;
END IF;

ELSIF v_line.matched_fund_transfer_id IS NOT NULL THEN
v_doc_type := 'fund_transfer';
v_doc_id := v_line.matched_fund_transfer_id;
UPDATE fund_transfers SET amount = p_new_amount WHERE id = v_doc_id;
-- Fund transfer only has INSERT trigger, so manually update JE lines
SELECT journal_entry_id INTO v_je_id FROM fund_transfers WHERE id = v_doc_id;
IF v_je_id IS NOT NULL THEN
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;
END IF;

ELSIF v_line.matched_petty_cash_id IS NOT NULL THEN
v_doc_type := 'petty_cash';
v_doc_id := v_line.matched_petty_cash_id;
-- Update petty cash amount
UPDATE petty_cash_transactions SET amount = p_new_amount WHERE id = v_doc_id;
-- trigger_post_petty_cash_on_approval only fires on approval_status change,
-- NOT on amount-only update. So find the linked JE manually and update lines.
SELECT id INTO v_je_id FROM journal_entries
WHERE reference_id = v_doc_id AND source_module = 'petty_cash'
LIMIT 1;
IF v_je_id IS NOT NULL THEN
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;
END IF;

ELSIF v_line.matched_tax_payment_id IS NOT NULL THEN
v_doc_type := 'tax_payment';
v_doc_id := v_line.matched_tax_payment_id;
UPDATE tax_payments SET amount = p_new_amount WHERE id = v_doc_id;
SELECT journal_entry_id INTO v_je_id FROM tax_payments WHERE id = v_doc_id;
IF v_je_id IS NOT NULL THEN
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;
END IF;

ELSIF v_line.matched_entry_id IS NOT NULL THEN
v_doc_type := 'journal_entry';
v_doc_id := v_line.matched_entry_id;
v_je_id := v_doc_id;
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;

ELSE
v_doc_type := 'none';
v_doc_id := NULL;
END IF;

RETURN jsonb_build_object(
'ok', true,
'doc_type', v_doc_type,
'doc_id', v_doc_id,
'old_amount', v_old_amount,
'new_amount', p_new_amount
);
END;
$$;


--
-- Name: protect_historical_company_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."protect_historical_company_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_ref_count bigint;
  v_target_id uuid;
BEGIN
  -- Setup Mode: skip every guard. Admins may edit / delete any profile.
  IF public.is_setup_mode() THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  v_target_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;

  SELECT COALESCE(SUM(ref_count), 0) INTO v_ref_count
  FROM public.get_company_profile_reference_counts()
  WHERE profile_id = v_target_id;

  IF v_ref_count > 0 THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION
        'PROFILE_REFERENCED: This Company Profile is referenced by % business document(s) and cannot be deleted. '
        'Historical company identities must remain permanently available.',
        v_ref_count;
    ELSIF TG_OP = 'UPDATE' THEN
      -- Tier 1: accounting-critical fields — immutable while referenced.
      -- company_logo_url, company_stamp_url, address, phone, email, website
      -- are intentionally excluded: they are branding/contact fields whose
      -- existing snapshot values are already frozen in historical documents.
      IF (NEW.company_name       IS DISTINCT FROM OLD.company_name       OR
          NEW.company_legal_name IS DISTINCT FROM OLD.company_legal_name OR
          NEW.company_tax_id     IS DISTINCT FROM OLD.company_tax_id     OR
          NEW.pbf_license        IS DISTINCT FROM OLD.pbf_license        OR
          NEW.cdob_certificate   IS DISTINCT FROM OLD.cdob_certificate   OR
          NEW.effective_from     IS DISTINCT FROM OLD.effective_from) THEN
        RAISE EXCEPTION
          'PROFILE_REFERENCED: This Company Profile is referenced by % business document(s). '
          'The fields company_name, legal_name, tax_id, licenses and effective_from cannot be '
          'changed because they appear on issued tax documents. '
          'Create a new profile version for future documents instead. '
          'Branding fields (logo, stamp, address, phone, email, website) may still be updated.',
          v_ref_count;
      END IF;
    END IF;
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: protect_posted_fund_transfer_accounting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."protect_posted_fund_transfer_accounting"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(current_setting('app.finance_historical_repair_relink',true),'off')='on' AND auth.role()='service_role' THEN
    RETURN NEW;
  END IF;
  IF COALESCE(current_setting('app.finance_historical_repair',true),'off')='on'
     AND NEW.exchange_rate IS DISTINCT FROM OLD.exchange_rate
     AND NEW.transfer_date IS NOT DISTINCT FROM OLD.transfer_date
     AND NEW.amount IS NOT DISTINCT FROM OLD.amount
     AND NEW.from_amount IS NOT DISTINCT FROM OLD.from_amount
     AND NEW.to_amount IS NOT DISTINCT FROM OLD.to_amount
     AND NEW.from_account_type IS NOT DISTINCT FROM OLD.from_account_type
     AND NEW.to_account_type IS NOT DISTINCT FROM OLD.to_account_type
     AND NEW.from_bank_account_id IS NOT DISTINCT FROM OLD.from_bank_account_id
     AND NEW.to_bank_account_id IS NOT DISTINCT FROM OLD.to_bank_account_id
     AND NEW.description IS NOT DISTINCT FROM OLD.description
     AND NEW.journal_entry_id IS NOT DISTINCT FROM OLD.journal_entry_id THEN
    RETURN NEW;
  END IF;
  IF OLD.status='posted' AND (
       NEW.transfer_date IS DISTINCT FROM OLD.transfer_date OR NEW.amount IS DISTINCT FROM OLD.amount
    OR NEW.from_amount IS DISTINCT FROM OLD.from_amount OR NEW.to_amount IS DISTINCT FROM OLD.to_amount
    OR NEW.exchange_rate IS DISTINCT FROM OLD.exchange_rate OR NEW.from_account_type IS DISTINCT FROM OLD.from_account_type
    OR NEW.to_account_type IS DISTINCT FROM OLD.to_account_type OR NEW.from_bank_account_id IS DISTINCT FROM OLD.from_bank_account_id
    OR NEW.to_bank_account_id IS DISTINCT FROM OLD.to_bank_account_id OR NEW.description IS DISTINCT FROM OLD.description
    OR NEW.journal_entry_id IS DISTINCT FROM OLD.journal_entry_id
  ) THEN
    RAISE EXCEPTION 'Posted Fund Transfer % is accounting-locked. Reverse it and create a replacement.',OLD.transfer_number;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: purchase_invoice_item_received_quantity("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."purchase_invoice_item_received_quantity"("p_item_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item public.purchase_invoice_items%ROWTYPE;
  v_batch public.batches%ROWTYPE;
  v_allocated numeric := 0;
  v_legacy_tx numeric := 0;
  v_legacy_batch_share numeric := 0;
  v_prior_claimed numeric := 0;
BEGIN
  SELECT * INTO v_item FROM public.purchase_invoice_items WHERE id = p_item_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  SELECT COALESCE(sum(received_quantity),0)
    INTO v_allocated
    FROM public.purchase_invoice_receiving_allocations
   WHERE purchase_invoice_item_id = p_item_id
     AND status = 'received';

  SELECT * INTO v_batch
    FROM public.batches b
   WHERE (v_item.batch_id IS NOT NULL AND b.id = v_item.batch_id)
      OR (v_item.batch_id IS NULL
          AND NULLIF(v_item.receiving_batch_number,'') IS NOT NULL
          AND b.product_id = v_item.product_id
          AND b.batch_number = v_item.receiving_batch_number)
   ORDER BY CASE WHEN v_item.batch_id IS NOT NULL AND b.id = v_item.batch_id THEN 0 ELSE 1 END,
            b.created_at
   LIMIT 1;

  /*
    Legacy purchase movements are authoritative when present. They are
    counted only once when a matching canonical allocation already owns the
    same operation.
  */
  SELECT COALESCE(sum(abs(it.quantity)),0)
    INTO v_legacy_tx
    FROM public.inventory_transactions it
    JOIN public.batches b ON b.id = it.batch_id
   WHERE it.transaction_type = 'purchase'
     AND it.quantity > 0
     AND NOT EXISTS (
       SELECT 1
         FROM public.purchase_invoice_receiving_allocations a
        WHERE a.purchase_invoice_item_id = p_item_id
          AND a.status = 'received'
          AND a.operation_id = it.operation_id
     )
     AND (
       it.reference_id = p_item_id
       OR (
         it.reference_id = v_item.purchase_invoice_id
         AND b.product_id = v_item.product_id
         AND ((v_item.batch_id IS NOT NULL AND b.id = v_item.batch_id)
           OR (NULLIF(v_item.receiving_batch_number,'') IS NOT NULL AND b.batch_number = v_item.receiving_batch_number))
       )
       OR (
         b.purchase_invoice_id = v_item.purchase_invoice_id
         AND b.product_id = v_item.product_id
         AND ((v_item.batch_id IS NOT NULL AND b.id = v_item.batch_id)
           OR (NULLIF(v_item.receiving_batch_number,'') IS NOT NULL AND b.batch_number = v_item.receiving_batch_number))
       )
       OR (
         it.reference_number = v_item.receiving_batch_number
         AND NULLIF(v_item.receiving_batch_number,'') IS NOT NULL
         AND b.purchase_invoice_id = v_item.purchase_invoice_id
         AND b.product_id = v_item.product_id
       )
     );

  /*
    Older batch imports can have the authoritative received quantity stored in
    batches.import_quantity without a purchase inventory_transaction. This is
    especially important when one physical batch was split across multiple PI
    lines. Allocate the batch's imported quantity deterministically across
    matching PI lines by line quantity/order, never above each PI line's own
    quantity. Only use this fallback when the item has no canonical receiving
    allocations; current canonical receipts remain authoritative.
  */
  IF v_allocated = 0 AND v_batch.id IS NOT NULL AND COALESCE(v_batch.import_quantity,0) > 0 THEN
    SELECT COALESCE(sum(x.quantity),0)
      INTO v_prior_claimed
      FROM public.purchase_invoice_items x
     WHERE x.item_type = 'inventory'
       AND x.product_id = v_item.product_id
       AND (x.batch_id = v_batch.id OR (x.batch_id IS NULL AND NULLIF(x.receiving_batch_number,'') IS NOT NULL AND x.receiving_batch_number = v_batch.batch_number))
       AND (x.created_at < v_item.created_at OR (x.created_at = v_item.created_at AND x.id::text < v_item.id::text));

    v_legacy_batch_share := GREATEST(0, LEAST(
      COALESCE(v_item.quantity,0),
      COALESCE(v_batch.import_quantity,0) - v_prior_claimed
    ));
  END IF;

  RETURN COALESCE(v_allocated,0) + GREATEST(COALESCE(v_legacy_tx,0), COALESCE(v_legacy_batch_share,0));
END;
$$;


--
-- Name: purchase_invoice_item_received_totals("uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."purchase_invoice_item_received_totals"("p_item_ids" "uuid"[]) RETURNS TABLE("purchase_invoice_item_id" "uuid", "received_quantity" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT i.id, public.purchase_invoice_item_received_quantity(i.id)
    FROM public.purchase_invoice_items i
   WHERE i.id = ANY(COALESCE(p_item_ids, ARRAY[]::uuid[]));
$$;


