--
-- Name: reallocate_container_costs("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reallocate_container_costs"("p_container_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  pool numeric := public.calculate_container_landed_cost_pool(p_container_id);
  total_qty numeric;
  l record;
  v_batch_id uuid;
  batch_cost numeric;
BEGIN
  SELECT COALESCE(sum(quantity),0) INTO total_qty
    FROM public.purchase_batch_cost_layers
   WHERE import_container_id=p_container_id;
  IF total_qty > 0 THEN
    FOR l IN SELECT * FROM public.purchase_batch_cost_layers
      WHERE import_container_id=p_container_id ORDER BY created_at,id FOR UPDATE LOOP
      UPDATE public.purchase_batch_cost_layers
             SET landed_cost_amount=round(pool * l.quantity / total_qty,2),
                 final_functional_unit_cost=round(l.functional_unit_cost + pool * l.quantity / total_qty / l.quantity,2)
       WHERE id=l.id;
    END LOOP;
    FOR v_batch_id IN SELECT DISTINCT pbl.batch_id FROM public.purchase_batch_cost_layers pbl
      WHERE import_container_id=p_container_id LOOP
      SELECT COALESCE(sum(quantity * final_functional_unit_cost) / NULLIF(sum(quantity),0),0)
        INTO batch_cost
        FROM public.purchase_batch_cost_layers pbl WHERE pbl.batch_id=v_batch_id;
      UPDATE public.batches SET cost_per_unit=round(batch_cost,2), landed_cost_per_unit=round(batch_cost,2), updated_at=now()
       WHERE id=v_batch_id AND COALESCE(cost_locked,false)=false;
    END LOOP;
    RETURN;
  END IF;
  SELECT COALESCE(sum(COALESCE(import_price,0)*COALESCE(import_quantity,0)),0)
    INTO total_qty FROM public.batches WHERE import_container_id=p_container_id;
  IF total_qty <= 0 THEN RETURN; END IF;
  FOR l IN SELECT id, import_price, import_quantity, duty_charges, freight_charges, other_charges
    FROM public.batches WHERE import_container_id=p_container_id AND COALESCE(cost_locked,false)=false LOOP
    batch_cost := pool * (COALESCE(l.import_price,0)*COALESCE(l.import_quantity,0)) / total_qty;
    UPDATE public.batches SET import_cost_allocated=round(batch_cost,2),
      final_landed_cost=round((COALESCE(l.import_price,0)+COALESCE(l.duty_charges,0))*COALESCE(l.import_quantity,0)+COALESCE(l.freight_charges,0)+COALESCE(l.other_charges,0)+batch_cost,2),
      landed_cost_per_unit=round(COALESCE(l.import_price,0)+COALESCE(l.duty_charges,0)+COALESCE(l.freight_charges,0)/NULLIF(l.import_quantity,0)+COALESCE(l.other_charges,0)/NULLIF(l.import_quantity,0)+batch_cost/NULLIF(l.import_quantity,0),2),
      cost_per_unit=round(COALESCE(l.import_price,0)+COALESCE(l.duty_charges,0)+COALESCE(l.freight_charges,0)/NULLIF(l.import_quantity,0)+COALESCE(l.other_charges,0)/NULLIF(l.import_quantity,0)+batch_cost/NULLIF(l.import_quantity,0),2), updated_at=now()
      WHERE id=l.id;
  END LOOP;
END; $$;


--
-- Name: FUNCTION "reallocate_container_costs"("p_container_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."reallocate_container_costs"("p_container_id" "uuid") IS 'Allocates container costs proportionally by QUANTITY (not value)';


--
-- Name: reallocate_on_batch_container_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reallocate_on_batch_container_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
-- If container assignment changed, reallocate costs for OLD container
IF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL 
AND (NEW.import_container_id IS NULL OR NEW.import_container_id != OLD.import_container_id) THEN
PERFORM reallocate_container_costs(OLD.import_container_id);
END IF;

-- Reallocate costs for NEW container
IF NEW.import_container_id IS NOT NULL THEN
PERFORM reallocate_container_costs(NEW.import_container_id);
END IF;

RETURN NEW;
END;
$$;


--
-- Name: reassign_tax_document_period("text", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reassign_tax_document_period"("p_source" "text", "p_document_id" "uuid", "p_tax_period_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_target public.tax_periods%ROWTYPE;
  v_old_period_id uuid;
  v_tax_type text;
  v_tax_code_id uuid;
BEGIN
  SELECT * INTO v_target
    FROM public.tax_periods
   WHERE id = p_tax_period_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tax period % not found', p_tax_period_id; END IF;
  IF v_target.status IN ('closed', 'filed') OR v_target.filing_status = 'filed' THEN
    RAISE EXCEPTION 'Tax period % is filed or closed and cannot be selected', p_tax_period_id;
  END IF;

  CASE p_source
    WHEN 'purchase_invoice' THEN
      SELECT tax_period_id INTO v_old_period_id FROM public.purchase_invoices WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice % not found', p_document_id; END IF;
      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Purchase invoices require a PPN tax period'; END IF;
    WHEN 'sales_invoice' THEN
      SELECT tax_period_id INTO v_old_period_id FROM public.sales_invoices WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Sales invoice % not found', p_document_id; END IF;
      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Sales invoices require a PPN tax period'; END IF;
    WHEN 'credit_note' THEN
      SELECT tax_period_id INTO v_old_period_id FROM public.credit_notes WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Credit note % not found', p_document_id; END IF;
      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Credit notes require a PPN tax period'; END IF;
    WHEN 'finance_expense_ppn' THEN
      SELECT tax_period_id INTO v_old_period_id FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Expense % not found', p_document_id; END IF;
      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Expenses require a PPN tax period for PPN reporting'; END IF;
    WHEN 'finance_expense_pph' THEN
      SELECT pph_tax_period_id, pph_code_id INTO v_old_period_id, v_tax_code_id
        FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Expense % not found', p_document_id; END IF;
      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id;
      IF v_tax_type IS NULL OR v_target.tax_type <> v_tax_type THEN RAISE EXCEPTION 'Expense PPh tax type must match the selected period'; END IF;
    WHEN 'payment_voucher' THEN
      SELECT tax_period_id, pph_code_id INTO v_old_period_id, v_tax_code_id
        FROM public.payment_vouchers WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_document_id; END IF;
      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id;
      IF v_tax_type IS NULL OR v_target.tax_type <> v_tax_type THEN RAISE EXCEPTION 'Payment voucher PPh tax type must match the selected period'; END IF;
    ELSE
      RAISE EXCEPTION 'Unsupported tax document source %', p_source;
  END CASE;

  IF v_old_period_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.tax_periods
     WHERE id=v_old_period_id AND (status IN ('closed', 'filed') OR filing_status='filed')
  ) THEN
    RAISE EXCEPTION 'The current tax period is filed or closed; reopen it before changing this document';
  END IF;

  CASE p_source
    WHEN 'purchase_invoice' THEN UPDATE public.purchase_invoices SET tax_period_id=p_tax_period_id WHERE id=p_document_id;
    WHEN 'sales_invoice' THEN
      UPDATE public.sales_invoices SET tax_period_id=p_tax_period_id WHERE id=p_document_id;
      UPDATE public.faktur_pajak SET tax_period_id=p_tax_period_id WHERE sales_invoice_id=p_document_id;
    WHEN 'credit_note' THEN UPDATE public.credit_notes SET tax_period_id=p_tax_period_id WHERE id=p_document_id;
    WHEN 'finance_expense_ppn' THEN UPDATE public.finance_expenses SET tax_period_id=p_tax_period_id WHERE id=p_document_id;
    WHEN 'finance_expense_pph' THEN UPDATE public.finance_expenses SET pph_tax_period_id=p_tax_period_id WHERE id=p_document_id;
    WHEN 'payment_voucher' THEN UPDATE public.payment_vouchers SET tax_period_id=p_tax_period_id WHERE id=p_document_id;
  END CASE;

  IF v_old_period_id IS NOT NULL THEN PERFORM public.compute_period_ppn(v_old_period_id); END IF;
  PERFORM public.compute_period_ppn(p_tax_period_id);
END;
$$;


--
-- Name: recalculate_expense_payment_state("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recalculate_expense_payment_state"("p_expense_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_supplier_paid numeric := 0;
  v_pph_paid numeric := 0;
  v_payable numeric := 0;
BEGIN
  IF public.historical_repair_context_active() THEN RETURN; END IF;

  SELECT COALESCE(sum(va.allocated_amount),0) INTO v_supplier_paid
    FROM public.voucher_allocations va
    LEFT JOIN public.payment_vouchers pv ON pv.id=va.payment_voucher_id
   WHERE va.finance_expense_id=p_expense_id
     AND COALESCE(va.payment_kind,'supplier')='supplier'
     AND COALESCE(pv.payment_purpose,'general') NOT IN ('salary_advance','salary_advance_settlement');
  SELECT v_supplier_paid+COALESCE(sum(allocation_amount),0) INTO v_supplier_paid
    FROM public.bank_statement_allocations
   WHERE document_type='expense' AND document_id=p_expense_id
     AND COALESCE(payment_kind,'supplier')='supplier';
  SELECT v_supplier_paid+COALESCE(sum(COALESCE(NULLIF(b.debit_amount,0),b.credit_amount,0)),0) INTO v_supplier_paid
    FROM public.bank_statement_lines b
   WHERE b.matched_expense_id=p_expense_id AND b.payment_kind='supplier'
     AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id=b.id);
  SELECT COALESCE(sum(allocated_amount),0) INTO v_pph_paid
    FROM public.voucher_allocations
   WHERE finance_expense_id=p_expense_id AND payment_kind='pph23';
  SELECT v_pph_paid+COALESCE(sum(allocation_amount),0) INTO v_pph_paid
    FROM public.bank_statement_allocations
   WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind='pph23';

  v_payable := COALESCE(public.calculate_finance_expense_payable(p_expense_id),0);
  UPDATE public.finance_expenses
     SET paid_amount=LEAST(GREATEST(v_supplier_paid,0),GREATEST(v_payable,0)),
         pph_paid_amount=GREATEST(v_pph_paid,0)
   WHERE id=p_expense_id;
END;
$$;


--
-- Name: recalculate_invoice_payment_from_allocations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recalculate_invoice_payment_from_allocations"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_invoice_id UUID;
v_total_paid numeric(15,2);
v_invoice_total numeric(15,2);
BEGIN
-- Determine which invoice to update
IF TG_OP = 'DELETE' THEN
v_invoice_id := OLD.invoice_id;
ELSE
v_invoice_id := NEW.invoice_id;
END IF;

-- Only proceed if we have an invoice_id
IF v_invoice_id IS NULL THEN
RETURN COALESCE(NEW, OLD);
END IF;

-- Calculate total paid from invoice_payment_allocations
SELECT COALESCE(SUM(allocated_amount), 0)
INTO v_total_paid
FROM invoice_payment_allocations
WHERE invoice_id = v_invoice_id;

-- Add payments from voucher_allocations
v_total_paid := v_total_paid + COALESCE(
(SELECT SUM(allocated_amount)
FROM voucher_allocations
WHERE sales_invoice_id = v_invoice_id
AND voucher_type = 'receipt'), 0
);

-- Get invoice total
SELECT total_amount INTO v_invoice_total
FROM sales_invoices
WHERE id = v_invoice_id;

-- Update the invoice
UPDATE sales_invoices
SET
paid_amount = v_total_paid,
payment_status = CASE
WHEN v_total_paid = 0 THEN 'pending'
WHEN v_total_paid >= v_invoice_total THEN 'paid'
WHEN v_total_paid > 0 AND v_total_paid < v_invoice_total THEN 'partial'
ELSE 'pending'
END
WHERE id = v_invoice_id;

RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: recalculate_invoice_payment_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recalculate_invoice_payment_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.sales_invoice_id IS NOT NULL THEN
    PERFORM public.apply_receipt_allocation_rounding_adjustment(NEW.sales_invoice_id, NEW.receipt_voucher_id);
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.sales_invoice_id IS NOT NULL THEN
      PERFORM public.apply_receipt_allocation_rounding_adjustment(NEW.sales_invoice_id, NEW.receipt_voucher_id);
    END IF;

    IF OLD.sales_invoice_id IS NOT NULL
       AND OLD.sales_invoice_id IS DISTINCT FROM NEW.sales_invoice_id THEN
      PERFORM public.clear_receipt_allocation_rounding_adjustment(OLD.sales_invoice_id, OLD.receipt_voucher_id);
    END IF;
  ELSIF TG_OP = 'DELETE' AND OLD.sales_invoice_id IS NOT NULL THEN
    PERFORM public.clear_receipt_allocation_rounding_adjustment(OLD.sales_invoice_id, OLD.receipt_voucher_id);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: recalculate_journal_entry_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recalculate_journal_entry_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_entry_id UUID;
v_total_debit NUMERIC;
v_total_credit NUMERIC;
BEGIN
-- Determine which journal entry to update
IF (TG_OP = 'DELETE') THEN
v_entry_id := OLD.journal_entry_id;
ELSE
v_entry_id := NEW.journal_entry_id;
END IF;

-- Calculate totals from all lines
SELECT 
COALESCE(SUM(debit), 0),
COALESCE(SUM(credit), 0)
INTO v_total_debit, v_total_credit
FROM journal_entry_lines
WHERE journal_entry_id = v_entry_id;

-- Update the journal entry totals
UPDATE journal_entries
SET 
total_debit = v_total_debit,
total_credit = v_total_credit
WHERE id = v_entry_id;

-- Return appropriate record
IF (TG_OP = 'DELETE') THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END;
$$;


--
-- Name: FUNCTION "recalculate_journal_entry_totals"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."recalculate_journal_entry_totals"() IS 'Automatically recalculates and updates journal entry totals when lines are added/modified/deleted - CRITICAL for accounting accuracy';


--
-- Name: recalculate_purchase_invoice_payment_state("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recalculate_purchase_invoice_payment_state"("p_purchase_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice record;
  v_total_paid numeric(18,2);
BEGIN
  IF p_purchase_invoice_id IS NULL THEN
    RETURN;
  END IF;

  SELECT id, total_amount
  INTO v_invoice
  FROM public.purchase_invoices
  WHERE id = p_purchase_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Only count allocations whose parent payment voucher is POSTED to GL.
  -- A saved-but-unposted PV is a draft: its allocations represent intent,
  -- not a completed payment. Was the sole diff vs. the previous version.
  SELECT COALESCE(SUM(va.allocated_amount), 0)
  INTO v_total_paid
  FROM public.voucher_allocations va
  JOIN public.payment_vouchers pv
    ON pv.id = va.payment_voucher_id
  WHERE va.purchase_invoice_id = p_purchase_invoice_id
    AND va.voucher_type = 'payment'
    AND pv.is_posted = TRUE;

  UPDATE public.purchase_invoices
  SET
    paid_amount = v_total_paid,
    status = CASE
      WHEN v_total_paid <= 0 THEN 'unpaid'
      WHEN v_total_paid >= COALESCE(v_invoice.total_amount, 0) THEN 'paid'
      ELSE 'partial'
    END
  WHERE id = p_purchase_invoice_id;
END;
$$;


--
-- Name: recalculate_sales_invoice_payment_state("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recalculate_sales_invoice_payment_state"("p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice record;
  v_allocated numeric(18,2);
  v_adjustment numeric(18,2);
  v_paid numeric(18,2);
BEGIN
  SELECT id, total_amount
  INTO v_invoice
  FROM public.sales_invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);
  v_adjustment := public.get_invoice_rounding_adjustment_amount(p_invoice_id);
  v_paid := v_allocated + v_adjustment;

  UPDATE public.sales_invoices
  SET
    paid_amount = v_paid,
    payment_status = CASE
      WHEN v_paid <= 0 THEN 'pending'
      WHEN v_paid >= v_invoice.total_amount THEN 'paid'
      ELSE 'partial'
    END
  WHERE id = p_invoice_id;
END;
$$;


--
-- Name: receive_purchase_invoice_item("uuid", "jsonb", numeric, "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."receive_purchase_invoice_item"("p_purchase_invoice_item_id" "uuid", "p_payload" "jsonb", "p_received_quantity" numeric, "p_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item public.purchase_invoice_items%ROWTYPE;
  v_invoice public.purchase_invoices%ROWTYPE;
  v_batch public.batches%ROWTYPE;
  v_batch_id uuid;
  v_existing numeric;
  v_allocation_id uuid;
  v_make_id uuid;
  v_container_id uuid;
  v_currency text;
  v_rate numeric;
  v_tx_unit numeric;
  v_func_unit numeric;
  v_existing_batch boolean := false;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','warehouse','manager']) THEN
    RAISE EXCEPTION 'Permission denied for inventory receiving';
  END IF;
  IF p_operation_id IS NULL OR p_received_quantity IS NULL OR p_received_quantity <= 0 THEN
    RAISE EXCEPTION 'A positive quantity and operation_id are required';
  END IF;
  SELECT * INTO v_item FROM public.purchase_invoice_items WHERE id=p_purchase_invoice_item_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice item not found'; END IF;
  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id=v_item.purchase_invoice_id;
  IF v_item.item_type <> 'inventory' OR v_item.product_id IS NULL
     OR NULLIF(p_payload->>'product_id','')::uuid IS DISTINCT FROM v_item.product_id THEN
    RAISE EXCEPTION 'Receiving requires the invoice inventory product';
  END IF;
  SELECT batch_id,id INTO v_batch_id,v_allocation_id
    FROM public.purchase_invoice_receiving_allocations WHERE operation_id=p_operation_id;
  IF FOUND THEN
    RETURN jsonb_build_object('success',true,'batch_id',v_batch_id,
      'allocation_id',v_allocation_id,'idempotent_retry',true);
  END IF;
  SELECT COALESCE(sum(received_quantity),0) INTO v_existing
    FROM public.purchase_invoice_receiving_allocations
   WHERE purchase_invoice_item_id=v_item.id AND status='received';
  IF v_existing+p_received_quantity > v_item.quantity THEN
    RAISE EXCEPTION 'Received quantity exceeds invoice line quantity';
  END IF;
  v_make_id := NULLIF(p_payload->>'make_id','')::uuid;
  v_container_id := NULLIF(p_payload->>'import_container_id','')::uuid;
  IF v_make_id IS NOT NULL AND NOT EXISTS
    (SELECT 1 FROM public.product_sources WHERE id=v_make_id AND product_id=v_item.product_id) THEN
    RAISE EXCEPTION 'Selected Make / Manufacturer does not belong to the invoice product';
  END IF;
  IF NULLIF(p_payload->>'batch_id','') IS NOT NULL THEN
    SELECT * INTO v_batch FROM public.batches WHERE id=(p_payload->>'batch_id')::uuid FOR UPDATE;
  ELSE
    SELECT * INTO v_batch FROM public.batches
     WHERE product_id=v_item.product_id AND batch_number=p_payload->>'batch_number'
       AND (make_id=v_make_id OR make_id IS NULL) AND coalesce(is_active,true)
     ORDER BY (make_id IS NULL),created_at LIMIT 1 FOR UPDATE;
  END IF;
  IF FOUND THEN
    v_existing_batch := true;
    IF v_batch.product_id IS DISTINCT FROM v_item.product_id THEN
      RAISE EXCEPTION 'Product does not match selected batch';
    END IF;
    IF v_batch.make_id IS NOT NULL AND v_batch.make_id IS DISTINCT FROM v_make_id THEN
      RAISE EXCEPTION 'Make does not match selected batch';
    END IF;
    IF NULLIF(p_payload->>'expiry_date','')::date IS NOT NULL
       AND v_batch.expiry_date IS NOT NULL
       AND NULLIF(p_payload->>'expiry_date','')::date IS DISTINCT FROM v_batch.expiry_date THEN
      RAISE EXCEPTION 'Expiry date conflicts with existing physical batch';
    END IF;
    PERFORM public.post_inventory_movement(p_operation_id,v_batch.product_id,v_batch.id,
      'adjustment',p_received_quantity,v_invoice.invoice_date,v_invoice.invoice_number,
      'purchase_invoice_receiving',v_invoice.id,
      'Purchase Invoice receiving into existing batch '||v_batch.batch_number,
      auth.uid(),v_batch.current_stock,v_batch.current_stock+p_received_quantity);
    UPDATE public.batches SET import_quantity=import_quantity+p_received_quantity,updated_at=now()
      WHERE id=v_batch.id;
    v_batch_id := v_batch.id;
  ELSE
    p_payload := jsonb_set(p_payload,'{import_quantity}',to_jsonb(p_received_quantity),true);
    p_payload := jsonb_set(p_payload,'{purchase_invoice_id}',to_jsonb(v_item.purchase_invoice_id),true);
    p_payload := jsonb_set(p_payload,'{supplier_id}',to_jsonb(v_invoice.supplier_id),true);
    SELECT (public.save_batch_inventory_v1(NULL,p_payload,p_operation_id)->>'batch_id')::uuid INTO v_batch_id;
  END IF;
  v_currency := upper(coalesce(v_invoice.currency,'IDR'));
  v_rate := CASE WHEN v_currency='IDR' THEN 1 ELSE coalesce(v_invoice.exchange_rate,0) END;
  IF v_rate<=0 THEN RAISE EXCEPTION 'Purchase invoice exchange rate is required'; END IF;
  v_tx_unit := coalesce(v_item.unit_price,0);
  v_func_unit := round(v_tx_unit*v_rate,2);
  INSERT INTO public.purchase_invoice_receiving_allocations(
    purchase_invoice_id,purchase_invoice_item_id,batch_id,received_quantity,
    operation_id,received_by,currency,exchange_rate,functional_unit_cost,
    functional_total_cost,import_container_id)
  VALUES(v_item.purchase_invoice_id,v_item.id,v_batch_id,p_received_quantity,
    p_operation_id,auth.uid(),v_currency,v_rate,v_func_unit,
    round(v_func_unit*p_received_quantity,2),v_container_id)
  RETURNING id INTO v_allocation_id;
  INSERT INTO public.purchase_batch_cost_layers(
    receiving_allocation_id,purchase_invoice_id,purchase_invoice_item_id,batch_id,
    import_container_id,quantity,currency,exchange_rate,transaction_unit_cost,
    functional_unit_cost,functional_total_cost,final_functional_unit_cost)
  VALUES(v_allocation_id,v_item.purchase_invoice_id,v_item.id,v_batch_id,v_container_id,
    p_received_quantity,v_currency,v_rate,v_tx_unit,v_func_unit,
    round(v_func_unit*p_received_quantity,2),v_func_unit);
  IF v_existing_batch THEN
    PERFORM public.apply_batch_receipt_weighted_average(v_batch_id,p_received_quantity,v_func_unit);
  END IF;
  RETURN jsonb_build_object('success',true,'batch_id',v_batch_id,'allocation_id',v_allocation_id);
END; $$;


--
-- Name: recompute_periods_for_date("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recompute_periods_for_date"("p_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_period_id uuid;
BEGIN
  IF p_date IS NULL THEN RETURN; END IF;
  FOR v_period_id IN
    SELECT id FROM tax_periods
     WHERE fiscal_year  = EXTRACT(YEAR  FROM p_date)::int
       AND period_month = EXTRACT(MONTH FROM p_date)::int
  LOOP
    PERFORM compute_period_ppn(v_period_id);
  END LOOP;
END $$;


--
-- Name: recompute_pph_periods_for_date("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recompute_pph_periods_for_date"("p_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tax_type text;
  v_period_id uuid;
BEGIN
  IF p_date IS NULL THEN
    RETURN;
  END IF;

  FOREACH v_tax_type IN ARRAY ARRAY['PPh21', 'PPh22', 'PPh23', 'PPh4(2)']::text[]
  LOOP
    v_period_id := public.upsert_tax_period(
      EXTRACT(YEAR FROM p_date)::int,
      EXTRACT(MONTH FROM p_date)::int,
      v_tax_type
    );
    PERFORM public.compute_period_ppn(v_period_id);
  END LOOP;

  -- Keep a legacy stored consolidated period synchronized when one exists.
  FOR v_period_id IN
    SELECT id
    FROM public.tax_periods
    WHERE fiscal_year = EXTRACT(YEAR FROM p_date)::int
      AND period_month = EXTRACT(MONTH FROM p_date)::int
      AND tax_type = 'PPh_Unifikasi'
  LOOP
    PERFORM public.compute_period_ppn(v_period_id);
  END LOOP;
END;
$$;


--
-- Name: recompute_price_request_counts("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recompute_price_request_counts"("p_pr_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
v_total    integer;
v_src_recv integer;
v_src_pend integer;
v_fq_ready integer;
v_fq_pend  integer;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'manager') THEN
RAISE EXCEPTION 'Permission denied: role % cannot recompute price request counts', v_role;
END IF;

SELECT
COUNT(*),
COUNT(*) FILTER (WHERE price_status = 'received'),
COUNT(*) FILTER (WHERE price_status IN ('pending', 'requested')),
COUNT(*) FILTER (WHERE final_quote_price IS NOT NULL),
COUNT(*) FILTER (WHERE price_status = 'received' AND final_quote_price IS NULL)
INTO v_total, v_src_recv, v_src_pend, v_fq_ready, v_fq_pend
FROM price_request_items
WHERE price_request_id = p_pr_id;

UPDATE price_requests
SET
total_products        = v_total,
source_price_received = v_src_recv,
source_price_pending  = v_src_pend,
final_quote_ready     = v_fq_ready,
final_quote_pending   = v_fq_pend,
updated_at            = now()
WHERE id = p_pr_id;
END;
$$;


--
-- Name: reconcile_so_product_reservation_v2("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reconcile_so_product_reservation_v2"("p_sales_order_item_id" "uuid", "p_reason" "text" DEFAULT 'SO state reconciliation'::"text") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item record;
  v_res public.so_product_reservations%ROWTYPE;
  v_delivered numeric;
  v_required numeric;
  v_delta numeric;
  v_atp numeric;
  v_grant numeric;
BEGIN
  SELECT soi.*, so.status::text AS so_status INTO v_item
  FROM public.sales_order_items soi
  JOIN public.sales_orders so ON so.id = soi.sales_order_id
  WHERE soi.id = p_sales_order_item_id
  FOR UPDATE OF soi, so;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales Order item not found';
  END IF;

  -- Serialize ATP decisions for the product
  PERFORM pg_advisory_xact_lock(hashtextextended(v_item.product_id::text, 0));

  SELECT COALESCE(sum(dci.quantity), 0) INTO v_delivered
  FROM public.delivery_challan_items dci
  JOIN public.delivery_challans dc ON dc.id = dci.challan_id
  WHERE dci.sales_order_item_id = v_item.id
    AND dc.approval_status = 'approved';

  IF v_delivered > v_item.quantity THEN
    RAISE EXCEPTION 'Delivered quantity exceeds ordered quantity';
  END IF;

  v_required := CASE
    WHEN v_item.so_status IN ('approved', 'stock_reserved', 'shortage', 'pending_delivery', 'partially_delivered')
      THEN v_item.quantity - v_delivered
    ELSE 0
  END;

  SELECT * INTO v_res
  FROM public.so_product_reservations
  WHERE sales_order_item_id = v_item.id
    AND status = 'active'
  FOR UPDATE;

  IF v_required = 0 THEN
    IF FOUND THEN
      UPDATE public.so_product_reservations
      SET reserved_quantity = 0,
          status = 'released',
          closed_at = now(),
          updated_at = now(),
          close_reason = p_reason
      WHERE id = v_res.id;

      INSERT INTO public.so_product_reservation_events(
        reservation_id, sales_order_id, sales_order_item_id, event_type,
        quantity_delta, quantity_after, reason, actor_id
      ) VALUES (
        v_res.id, v_item.sales_order_id, v_item.id, 'released',
        -v_res.reserved_quantity, 0, p_reason, auth.uid()
      );
    END IF;
    RETURN 0;
  END IF;

  -- Calculate available product ATP (excluding this SO item's existing active reservation if any)
  v_atp := public.product_available_to_promise(
    v_item.product_id,
    CASE WHEN v_res.id IS NOT NULL THEN v_item.id ELSE NULL END
  );

  -- Reserve what is physically available; unfulfilled quantity is handled as shortage
  v_grant := LEAST(v_required, GREATEST(COALESCE(v_atp, 0), 0));

  IF NOT FOUND THEN
    IF v_grant > 0 THEN
      INSERT INTO public.so_product_reservations(
        sales_order_id, sales_order_item_id, product_id, reserved_quantity, created_by
      ) VALUES (
        v_item.sales_order_id, v_item.id, v_item.product_id, v_grant, auth.uid()
      ) RETURNING * INTO v_res;

      INSERT INTO public.so_product_reservation_events(
        reservation_id, sales_order_id, sales_order_item_id, event_type,
        quantity_delta, quantity_after, reason, actor_id
      ) VALUES (
        v_res.id, v_item.sales_order_id, v_item.id, 'created',
        v_grant, v_grant, p_reason, auth.uid()
      );
    END IF;
  ELSE
    IF v_res.product_id <> v_item.product_id THEN
      RAISE EXCEPTION 'Cannot change product on an actively reserved SO item';
    END IF;

    IF v_grant = 0 THEN
      UPDATE public.so_product_reservations
      SET reserved_quantity = 0,
          status = 'released',
          closed_at = now(),
          updated_at = now(),
          close_reason = p_reason
      WHERE id = v_res.id;

      INSERT INTO public.so_product_reservation_events(
        reservation_id, sales_order_id, sales_order_item_id, event_type,
        quantity_delta, quantity_after, reason, actor_id
      ) VALUES (
        v_res.id, v_item.sales_order_id, v_item.id, 'released',
        -v_res.reserved_quantity, 0, p_reason, auth.uid()
      );
    ELSE
      v_delta := v_grant - v_res.reserved_quantity;
      IF v_delta <> 0 THEN
        UPDATE public.so_product_reservations
        SET reserved_quantity = v_grant,
            updated_at = now()
        WHERE id = v_res.id;

        INSERT INTO public.so_product_reservation_events(
          reservation_id, sales_order_id, sales_order_item_id, event_type,
          quantity_delta, quantity_after, reason, actor_id
        ) VALUES (
          v_res.id, v_item.sales_order_id, v_item.id,
          CASE WHEN v_delta > 0 THEN 'increased' ELSE 'decreased' END,
          v_delta, v_grant, p_reason, auth.uid()
        );
      END IF;
    END IF;
  END IF;

  RETURN v_grant;
END;
$$;


--
-- Name: record_batch_import_accounting_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."record_batch_import_accounting_entry"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_inventory_coa_id uuid;
v_payable_coa_id uuid;
v_total_cost numeric;
v_duty_amount numeric;
BEGIN
-- Only create accounting entry if batch has final landed cost
IF NEW.final_landed_cost IS NULL OR NEW.final_landed_cost = 0 THEN
RETURN NEW;
END IF;

-- Get COA IDs for Inventory and Accounts Payable
SELECT id INTO v_inventory_coa_id
FROM chart_of_accounts
WHERE account_code = '1140'
LIMIT 1;

SELECT id INTO v_payable_coa_id
FROM chart_of_accounts
WHERE account_code = '2110'
LIMIT 1;

-- Calculate total cost (this includes allocated container costs)
v_total_cost := NEW.final_landed_cost;

-- Calculate duty amount based on duty_percent if available
IF NEW.duty_percent IS NOT NULL AND NEW.duty_percent > 0 THEN
v_duty_amount := (NEW.import_price * NEW.duty_percent) / 100;
ELSE
v_duty_amount := 0;
END IF;

-- Create journal entry for inventory acquisition
-- DR: Inventory (includes base cost + allocated import expenses)
-- CR: Accounts Payable
INSERT INTO finance_journal_entries (
entry_date,
reference_type,
reference_id,
description,
total_amount,
created_by
)
VALUES (
NEW.import_date,
'batch_import',
NEW.id,
'Import of ' || (SELECT product_name FROM products WHERE id = NEW.product_id) || 
' - Batch ' || NEW.batch_number || 
CASE WHEN v_duty_amount > 0 THEN ' (incl. ' || ROUND(NEW.duty_percent, 2) || '% duty)' ELSE '' END,
v_total_cost,
NEW.created_by
)
RETURNING id INTO v_inventory_coa_id;  -- Reusing variable for journal entry ID

-- Debit: Inventory Asset
INSERT INTO finance_journal_entry_lines (
journal_entry_id,
coa_id,
debit,
credit,
description
)
VALUES (
v_inventory_coa_id,
(SELECT id FROM chart_of_accounts WHERE account_code = '1140' LIMIT 1),
v_total_cost,
0,
'Inventory - ' || NEW.batch_number
);

-- Credit: Accounts Payable
INSERT INTO finance_journal_entry_lines (
journal_entry_id,
coa_id,
debit,
credit,
description
)
VALUES (
v_inventory_coa_id,
v_payable_coa_id,
0,
v_total_cost,
'Payable - Import ' || NEW.batch_number
);

RETURN NEW;
END;
$$;


--
-- Name: record_tax_payment("uuid", "text", "date", numeric, "uuid", "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."record_tax_payment"("p_tax_period_id" "uuid", "p_tax_type" "text", "p_payment_date" "date", "p_amount" numeric, "p_bank_account_id" "uuid", "p_billing_code" "text" DEFAULT NULL::"text", "p_ntpn" "text" DEFAULT NULL::"text", "p_government_reference" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tp_id            uuid;
  v_je_id            uuid;
  v_je_number        text;
  v_period           tax_periods%ROWTYPE;
  v_payable_code     text;
  v_payable_acct_id  uuid;
  v_bank_acct_coa_id uuid;
  v_ref_number       text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Tax payment amount must be > 0';
  END IF;

  SELECT * INTO v_period FROM tax_periods WHERE id = p_tax_period_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tax period % not found', p_tax_period_id;
  END IF;
  IF v_period.status = 'closed' THEN
    RAISE EXCEPTION 'Cannot record tax payment on a closed period';
  END IF;
  IF v_period.tax_type <> p_tax_type THEN
    RAISE EXCEPTION 'Tax type mismatch: period is %, payment is %',
      v_period.tax_type, p_tax_type;
  END IF;

  -- Map tax type → payable account code
  v_payable_code := CASE p_tax_type
    WHEN 'PPN'      THEN '2130'
    WHEN 'PPh21'    THEN '2131'
    WHEN 'PPh22'    THEN '2137'
    WHEN 'PPh23'    THEN '2132'
    WHEN 'PPh4(2)'  THEN '2138'
    WHEN 'PPh_Unifikasi' THEN '2131'  -- treated as PPh 21 payable by default
    ELSE NULL
  END;

  IF v_payable_code IS NULL THEN
    RAISE EXCEPTION 'Unknown tax_type: %', p_tax_type;
  END IF;

  SELECT id INTO v_payable_acct_id FROM chart_of_accounts WHERE code = v_payable_code;
  IF v_payable_acct_id IS NULL THEN
    RAISE EXCEPTION 'Payable account % missing from Chart of Accounts', v_payable_code;
  END IF;

  -- Bank account → CoA account
  IF p_bank_account_id IS NULL THEN
    RAISE EXCEPTION 'Bank account is required for a tax payment';
  END IF;
  SELECT coa_id INTO v_bank_acct_coa_id FROM bank_accounts WHERE id = p_bank_account_id;
  IF v_bank_acct_coa_id IS NULL THEN
    -- Fallback to generic Bank BCA (1111) when bank_accounts.coa_id not wired
    SELECT id INTO v_bank_acct_coa_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;
  END IF;
  IF v_bank_acct_coa_id IS NULL THEN
    RAISE EXCEPTION 'Cannot resolve bank CoA account for tax payment';
  END IF;

  -- 1) Create tax_payments row (draft)
  INSERT INTO tax_payments
    (tax_period_id, tax_type, payment_date, amount,
     bank_account_id, billing_code, ntpn, government_reference, notes,
     status, created_by)
  VALUES
    (p_tax_period_id, p_tax_type, p_payment_date, p_amount,
     p_bank_account_id, p_billing_code, p_ntpn, p_government_reference, p_notes,
     'draft', auth.uid())
  RETURNING id INTO v_tp_id;

  v_ref_number := COALESCE(NULLIF(p_ntpn,''), NULLIF(p_billing_code,''),
                           'TAX-' || to_char(p_payment_date, 'YYMM') || '-' || substr(v_tp_id::text, 1, 8));

  -- 2) Post journal entry: Dr Tax Payable / Cr Bank
  v_je_number := next_journal_entry_number();

  INSERT INTO journal_entries
    (entry_number, entry_date, source_module, reference_id, reference_number,
     description, total_debit, total_credit, is_posted, posted_by)
  VALUES
    (v_je_number, p_payment_date, 'tax_payment', v_tp_id, v_ref_number,
     'Tax Payment ' || p_tax_type || ' — ' || v_ref_number,
     p_amount, p_amount, true, auth.uid())
  RETURNING id INTO v_je_id;

  INSERT INTO journal_entry_lines
    (journal_entry_id, line_number, account_id, description, debit, credit)
  VALUES
    (v_je_id, 1, v_payable_acct_id,
     p_tax_type || ' payment — ' || v_ref_number,
     p_amount, 0),
    (v_je_id, 2, v_bank_acct_coa_id,
     'Bank ' || p_tax_type || ' payment — ' || v_ref_number,
     0, p_amount);

  -- 3) Link back and mark posted
  UPDATE tax_payments SET
    journal_entry_id = v_je_id,
    status           = 'posted',
    updated_at       = now()
  WHERE id = v_tp_id;

  -- 4) Nudge the period status if it was open
  UPDATE tax_periods SET
    status = CASE WHEN status = 'open' THEN 'payment_pending' ELSE status END,
    updated_at = now()
  WHERE id = p_tax_period_id;

  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)
  VALUES (auth.uid(), 'tax_payments', 'insert', v_tp_id,
          jsonb_build_object(
            'tax_period_id', p_tax_period_id,
            'tax_type',      p_tax_type,
            'amount',        p_amount,
            'journal_entry_id', v_je_id
          ));

  RETURN v_tp_id;
END $$;


--
-- Name: record_tax_payment("uuid", "text", "date", numeric, "uuid", "text", "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."record_tax_payment"("p_tax_period_id" "uuid", "p_tax_type" "text", "p_payment_date" "date", "p_amount" numeric, "p_bank_account_id" "uuid", "p_billing_code" "text" DEFAULT NULL::"text", "p_ntpn" "text" DEFAULT NULL::"text", "p_government_reference" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_payment_reference" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tp_id            uuid;
  v_je_id            uuid;
  v_je_number        text;
  v_period           tax_periods%ROWTYPE;
  v_payable_code     text;
  v_payable_acct_id  uuid;
  v_bank_acct_coa_id uuid;
  v_ref_number       text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Tax payment amount must be > 0';
  END IF;

  SELECT * INTO v_period FROM tax_periods WHERE id = p_tax_period_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tax period % not found', p_tax_period_id;
  END IF;
  IF v_period.status = 'closed' THEN
    RAISE EXCEPTION 'Cannot record tax payment on a closed period';
  END IF;
  IF v_period.tax_type <> p_tax_type THEN
    RAISE EXCEPTION 'Tax type mismatch: period is %, payment is %',
      v_period.tax_type, p_tax_type;
  END IF;

  v_payable_code := CASE p_tax_type
    WHEN 'PPN'      THEN '2130'
    WHEN 'PPh21'    THEN '2131'
    WHEN 'PPh22'    THEN '2137'
    WHEN 'PPh23'    THEN '2132'
    WHEN 'PPh4(2)'  THEN '2138'
    WHEN 'PPh_Unifikasi' THEN '2131'
    ELSE NULL
  END;

  IF v_payable_code IS NULL THEN
    RAISE EXCEPTION 'Unknown tax_type: %', p_tax_type;
  END IF;

  SELECT id INTO v_payable_acct_id FROM chart_of_accounts WHERE code = v_payable_code;
  IF v_payable_acct_id IS NULL THEN
    RAISE EXCEPTION 'Payable account % missing from Chart of Accounts', v_payable_code;
  END IF;

  IF p_bank_account_id IS NULL THEN
    RAISE EXCEPTION 'Bank account is required for a tax payment';
  END IF;
  SELECT coa_id INTO v_bank_acct_coa_id FROM bank_accounts WHERE id = p_bank_account_id;
  IF v_bank_acct_coa_id IS NULL THEN
    SELECT id INTO v_bank_acct_coa_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;
  END IF;
  IF v_bank_acct_coa_id IS NULL THEN
    RAISE EXCEPTION 'Cannot resolve bank CoA account for tax payment';
  END IF;

  INSERT INTO tax_payments
    (tax_period_id, tax_type, payment_date, amount,
     bank_account_id, billing_code, ntpn, government_reference,
     payment_reference, notes,
     status, created_by)
  VALUES
    (p_tax_period_id, p_tax_type, p_payment_date, p_amount,
     p_bank_account_id, p_billing_code, p_ntpn, p_government_reference,
     p_payment_reference, p_notes,
     'draft', auth.uid())
  RETURNING id INTO v_tp_id;

  v_ref_number := COALESCE(
    NULLIF(p_ntpn, ''),
    NULLIF(p_billing_code, ''),
    NULLIF(p_payment_reference, ''),
    'TAX-' || to_char(p_payment_date, 'YYMM') || '-' || substr(v_tp_id::text, 1, 8)
  );

  v_je_number := next_journal_entry_number();

  INSERT INTO journal_entries
    (entry_number, entry_date, source_module, reference_id, reference_number,
     description, total_debit, total_credit, is_posted, posted_by)
  VALUES
    (v_je_number, p_payment_date, 'tax_payment', v_tp_id, v_ref_number,
     'Tax Payment ' || p_tax_type || ' — ' || v_ref_number,
     p_amount, p_amount, true, auth.uid())
  RETURNING id INTO v_je_id;

  INSERT INTO journal_entry_lines
    (journal_entry_id, line_number, account_id, description, debit, credit)
  VALUES
    (v_je_id, 1, v_payable_acct_id,
     p_tax_type || ' payment — ' || v_ref_number, p_amount, 0),
    (v_je_id, 2, v_bank_acct_coa_id,
     'Bank ' || p_tax_type || ' payment — ' || v_ref_number, 0, p_amount);

  UPDATE tax_payments SET
    journal_entry_id = v_je_id,
    status = 'posted',
    updated_at = now()
  WHERE id = v_tp_id;

  UPDATE tax_periods SET
    status = CASE WHEN status = 'open' THEN 'payment_pending' ELSE status END,
    updated_at = now()
  WHERE id = p_tax_period_id;

  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)
  VALUES (auth.uid(), 'tax_payments', 'insert', v_tp_id,
          jsonb_build_object(
            'tax_period_id',     p_tax_period_id,
            'tax_type',          p_tax_type,
            'amount',            p_amount,
            'journal_entry_id',  v_je_id,
            'payment_reference', p_payment_reference,
            'billing_code',      p_billing_code,
            'ntpn',              p_ntpn
          ));

  RETURN v_tp_id;
END $$;


--
-- Name: refresh_bank_statement_allocation_status("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refresh_bank_statement_allocation_status"("p_bank_line_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_total numeric;
  v_allocated numeric;
  v_existing_status text;
  v_existing_matching_status text;
  v_fund_transfer uuid;
  v_conflict boolean := false;
  v_matching_status text;
BEGIN
  SELECT COALESCE(NULLIF(debit_amount, 0), credit_amount, 0),
         reconciliation_status, matching_status, matched_fund_transfer_id
    INTO v_total, v_existing_status, v_existing_matching_status, v_fund_transfer
    FROM public.bank_statement_lines
   WHERE id = p_bank_line_id
   FOR UPDATE;

  SELECT COALESCE(sum(allocation_amount), 0)
    INTO v_allocated
    FROM public.bank_statement_allocations
   WHERE bank_statement_line_id = p_bank_line_id;

  IF v_allocated > 0.01 AND v_allocated >= v_total - 0.01
     AND v_fund_transfer IS NOT NULL
     AND public.historical_allocation_relink_context_active()
     AND EXISTS (
       SELECT 1
         FROM public.bank_statement_lines other
        WHERE other.id <> p_bank_line_id
          AND other.matched_fund_transfer_id = v_fund_transfer
          AND other.matching_status = 'confirmed'
     ) THEN
    v_conflict := true;
  END IF;

  v_matching_status := CASE
    WHEN v_allocated <= 0.01 THEN 'none'
    WHEN v_conflict AND v_existing_matching_status <> 'confirmed' THEN 'suggested'
    ELSE 'confirmed'
  END;

  UPDATE public.bank_statement_lines
     SET reconciliation_status = CASE
           WHEN v_allocated <= 0.01 THEN 'unmatched'
           WHEN v_allocated < v_total - 0.01 THEN 'partially_reconciled'
           ELSE 'matched'
         END,
         matching_status = v_matching_status,
         matched_at = CASE WHEN v_allocated <= 0.01 THEN NULL ELSE COALESCE(matched_at, now()) END,
         matched_by = CASE WHEN v_allocated <= 0.01 THEN NULL ELSE COALESCE(matched_by, auth.uid()) END,
         manually_unlinked = true
   WHERE id = p_bank_line_id;
END;
$$;


--
-- Name: refresh_bulk_email_campaign_counts("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refresh_bulk_email_campaign_counts"("p_campaign_id" "uuid") RETURNS TABLE("sent_count" integer, "failed_count" integer, "pending_count" integer, "sending_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH counts AS (
    SELECT
      count(*) FILTER (WHERE status = 'sent')::integer AS sent_count,
      count(*) FILTER (WHERE status = 'failed')::integer AS failed_count,
      count(*) FILTER (WHERE status = 'pending')::integer AS pending_count,
      count(*) FILTER (WHERE status = 'sending')::integer AS sending_count
    FROM public.bulk_email_recipients
    WHERE campaign_id = p_campaign_id
  )
  UPDATE public.bulk_email_campaigns c
  SET
    sent_count = counts.sent_count,
    failed_count = counts.failed_count
  FROM counts
  WHERE c.id = p_campaign_id
  RETURNING counts.sent_count, counts.failed_count, counts.pending_count, counts.sending_count;
END;
$$;


--
-- Name: refresh_salary_advance_status("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refresh_salary_advance_status"("p_advance_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_amount numeric;
  v_applied numeric;
BEGIN
  SELECT amount INTO v_amount
  FROM public.payment_vouchers
  WHERE id = p_advance_id AND payment_purpose = 'salary_advance';
  IF NOT FOUND THEN RETURN; END IF;

  SELECT COALESCE(sum(applied_amount), 0) INTO v_applied
  FROM public.salary_advance_applications
  WHERE advance_payment_voucher_id = p_advance_id;

  UPDATE public.payment_vouchers
  SET salary_advance_applied_amount = v_applied,
      salary_advance_status = CASE
        WHEN v_applied >= v_amount THEN 'settled'
        WHEN v_applied > 0 THEN 'partially_settled'
        ELSE 'outstanding'
      END
  WHERE id = p_advance_id;
END;
$$;


--
-- Name: reject_purchase_invoice_inward("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reject_purchase_invoice_inward"("p_purchase_invoice_id" "uuid", "p_purchase_invoice_item_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_status text;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','warehouse','manager']) THEN RAISE EXCEPTION 'Permission denied'; END IF;
  IF p_reason IS NULL OR length(trim(p_reason))=0 THEN RAISE EXCEPTION 'Rejection reason is required'; END IF;
  SELECT receiving_approval_status INTO v_status FROM public.purchase_invoices WHERE id=p_purchase_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;
  IF v_status <> 'approved' THEN RAISE EXCEPTION 'Only approved Purchase Invoices can be rejected at inward'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.purchase_invoice_items WHERE id=p_purchase_invoice_item_id AND purchase_invoice_id=p_purchase_invoice_id AND item_type='inventory') THEN
    RAISE EXCEPTION 'Purchase Invoice item does not belong to this invoice';
  END IF;
  INSERT INTO public.purchase_invoice_inward_rejections(purchase_invoice_id,purchase_invoice_item_id,reason,rejected_by) VALUES (p_purchase_invoice_id,p_purchase_invoice_item_id,trim(p_reason),auth.uid());
  UPDATE public.purchase_invoices SET receiving_approval_status='rejected', receiving_rejection_reason=trim(p_reason), updated_at=now() WHERE id=p_purchase_invoice_id;
  RETURN jsonb_build_object('success',true,'status','rejected');
END; $$;


--
-- Name: release_so_product_reservations_v2("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."release_so_product_reservations_v2"("p_so_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r public.so_product_reservations%ROWTYPE;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','manager','warehouse','sales'])
     AND current_setting('app.canonical_reservation_engine',true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'Permission denied for reservation release';
  END IF;
  FOR r IN SELECT * FROM public.so_product_reservations WHERE sales_order_id=p_so_id AND status='active' ORDER BY id FOR UPDATE LOOP
    UPDATE public.so_product_reservations SET reserved_quantity=0,status='released',closed_at=now(),updated_at=now(),close_reason=p_reason WHERE id=r.id;
    INSERT INTO public.so_product_reservation_events(reservation_id,sales_order_id,sales_order_item_id,event_type,quantity_delta,quantity_after,reason,actor_id)
    VALUES(r.id,r.sales_order_id,r.sales_order_item_id,'released',-r.reserved_quantity,0,p_reason,auth.uid());
  END LOOP;
END; $$;


--
-- Name: relink_historical_bank_allocation("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."relink_historical_bank_allocation"("p_allocation_id" "uuid", "p_replacement_journal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_alloc public.bank_statement_allocations%rowtype;
  v_old public.journal_entries%rowtype;
  v_new public.journal_entries%rowtype;
  v_before_amount numeric;
BEGIN
  IF current_user NOT IN ('postgres', 'supabase_admin')
     AND auth.role() <> 'service_role'
     AND NOT EXISTS (
       SELECT 1 FROM public.user_profiles
        WHERE id = auth.uid() AND is_active = true AND role = 'admin'
     ) THEN
    RAISE EXCEPTION 'Historical allocation relink requires admin or service_role';
  END IF;

  SELECT * INTO v_alloc
    FROM public.bank_statement_allocations
   WHERE id = p_allocation_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Allocation not found'; END IF;

  SELECT * INTO v_old FROM public.journal_entries WHERE id = v_alloc.journal_entry_id FOR UPDATE;
  SELECT * INTO v_new FROM public.journal_entries WHERE id = p_replacement_journal_id FOR UPDATE;
  IF v_old.id IS NULL OR NOT v_old.is_reversed THEN
    RAISE EXCEPTION 'Source journal must be reversed';
  END IF;
  IF v_new.id IS NULL OR NOT v_new.is_posted OR v_new.is_reversed THEN
    RAISE EXCEPTION 'Replacement journal must be posted and not reversed';
  END IF;
  IF v_old.reference_id IS DISTINCT FROM v_new.reference_id
     AND NOT EXISTS (
       SELECT 1 FROM public.fund_transfers ft_old
       JOIN public.fund_transfers ft_new ON ft_new.id = ft_old.id
       WHERE ft_old.journal_entry_id = v_old.id AND ft_new.journal_entry_id = v_new.id
     ) THEN
    RAISE EXCEPTION 'Journals do not belong to the same underlying transaction';
  END IF;
  IF v_alloc.journal_entry_id = v_new.id THEN
    RETURN jsonb_build_object('idempotent', true, 'allocation_id', v_alloc.id,
      'journal_entry_id', v_new.id, 'allocation_amount', v_alloc.allocation_amount);
  END IF;

  v_before_amount := v_alloc.allocation_amount;
  PERFORM set_config('app.historical_allocation_relink', 'on', true);
  UPDATE public.bank_statement_allocations
     SET journal_entry_id = v_new.id
   WHERE id = v_alloc.id;

  IF (SELECT allocation_amount FROM public.bank_statement_allocations WHERE id = v_alloc.id) <> v_before_amount THEN
    RAISE EXCEPTION 'Allocation amount changed';
  END IF;

  RETURN jsonb_build_object('idempotent', false, 'allocation_id', v_alloc.id,
    'old_journal_entry_id', v_old.id, 'new_journal_entry_id', v_new.id,
    'allocation_amount', v_before_amount);
END;
$$;


--
-- Name: reopen_tax_period("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reopen_tax_period"("p_period_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reopen reason is required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM user_profiles
                 WHERE id = auth.uid() AND role = 'admin' AND is_active = true) THEN
    RAISE EXCEPTION 'Only admins may reopen a closed tax period';
  END IF;

  UPDATE tax_periods SET
    status         = 'reopened',
    reopen_reason  = p_reason,
    reopened_at    = now(),
    reopened_by    = auth.uid(),
    updated_at     = now()
  WHERE id = p_period_id AND status = 'closed';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Period % is not in closed state', p_period_id;
  END IF;

  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)
  VALUES (auth.uid(), 'tax_periods', 'update', p_period_id,
          jsonb_build_object('action','reopen','reason',p_reason));
END $$;


--
-- Name: repair_all_posted_fund_transfers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."repair_all_posted_fund_transfers"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  t record;
  eligibility text;
  result jsonb;
  scanned integer := 0;
  repaired integer := 0;
  skipped integer := 0;
  skipped_details jsonb := '[]'::jsonb;
BEGIN
  PERFORM public._sec_check_finance_role();
  FOR t IN SELECT id, transfer_number FROM public.fund_transfers WHERE status='posted' ORDER BY transfer_date, transfer_number LOOP
    scanned := scanned + 1;
    eligibility := public.audit_fund_transfer_repair_eligibility(t.id);
    IF eligibility IS NOT NULL THEN
      skipped := skipped + 1;
      skipped_details := skipped_details || jsonb_build_array(jsonb_build_object(
        'fund_transfer_id', t.id, 'transfer_number', t.transfer_number, 'reason', eligibility));
      CONTINUE;
    END IF;
    SELECT public.repair_posted_fund_transfer_from_source(t.id) INTO result;
    IF COALESCE((result->>'repaired')::boolean, false) THEN
      repaired := repaired + 1;
      IF NOT EXISTS (
        SELECT 1 FROM public.audit_logs a
        WHERE a.table_name='fund_transfers' AND a.record_id=t.id
          AND a.new_values->>'validation_rerun'='true'
      ) THEN
        INSERT INTO public.audit_logs(table_name, action_type, record_id, old_values, new_values, changed_fields)
        VALUES ('fund_transfers', 'update', t.id,
          jsonb_build_object('event','batch_repair','transfer_number',t.transfer_number),
          jsonb_build_object('event','batch_repair','repair_result',result,'validation_rerun',true),
          COALESCE(ARRAY(SELECT jsonb_array_elements_text(result->'repaired_fields')), ARRAY[]::text[]));
      END IF;
    ELSE
      skipped := skipped + 1;
      skipped_details := skipped_details || jsonb_build_array(jsonb_build_object(
        'fund_transfer_id', t.id, 'transfer_number', t.transfer_number,
        'reason', COALESCE(result->>'reason', 'Repair did not pass validation')));
    END IF;
  END LOOP;
  RETURN jsonb_build_object('total_scanned', scanned, 'automatically_repaired', repaired,
    'skipped', skipped, 'skipped_details', skipped_details);
END;
$$;


--
-- Name: repair_historical_usd_idr_transfer_fx("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."repair_historical_usd_idr_transfer_fx"("p_cutoff" "date" DEFAULT '2026-08-01'::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r record; l record; v_reversal uuid; v_corrected uuid; v_entry text; v_line int; v_run uuid; v_repaired int:=0; v_skipped int:=0; v_exception int:=0; BEGIN
  PERFORM set_config('app.finance_historical_repair','on',true);
  PERFORM set_config('app.finance_historical_repair_relink','on',true);
  INSERT INTO public.finance_historical_repair_runs(notes) VALUES ('Controlled historical USD→IDR fund-transfer FX correction before cutoff '||p_cutoff::text) RETURNING id INTO v_run;
  FOR r IN
    SELECT ft.id, ft.transfer_number, ft.transfer_date, ft.from_amount, ft.to_amount, ft.exchange_rate, ft.journal_entry_id,
           je.entry_number, je.total_debit, je.total_credit,
           fba.coa_id from_coa, fba.currency from_currency, tba.coa_id to_coa, tba.currency to_currency,
           fs.id from_stmt, ts.id to_stmt, fs.debit_amount from_debit, fs.credit_amount from_credit, fs.currency from_stmt_currency,
           ts.debit_amount to_debit, ts.credit_amount to_credit, ts.currency to_stmt_currency
    FROM public.fund_transfers ft
    JOIN public.bank_accounts fba ON fba.id=ft.from_bank_account_id
    JOIN public.bank_accounts tba ON tba.id=ft.to_bank_account_id
    JOIN public.journal_entries je ON je.id=ft.journal_entry_id
    JOIN public.bank_statement_lines fs ON fs.id=ft.from_bank_statement_line_id
    JOIN public.bank_statement_lines ts ON ts.id=ft.to_bank_statement_line_id
    WHERE ft.status='posted' AND ft.transfer_date < p_cutoff AND fba.currency='USD' AND tba.currency='IDR'
      AND fs.currency='USD' AND ts.currency='IDR'
      AND abs(fs.debit_amount-ft.from_amount)<0.01 AND abs(fs.credit_amount)<0.01
      AND abs(ts.credit_amount-ft.to_amount)<0.01 AND abs(ts.debit_amount)<0.01
      AND NOT COALESCE(je.is_reversed,false)
    ORDER BY ft.transfer_date, ft.transfer_number
    FOR UPDATE OF ft,je,fs,ts
  LOOP
    IF abs(r.total_debit-r.to_amount)<0.01 AND abs(r.total_credit-r.to_amount)<0.01 THEN v_skipped:=v_skipped+1; CONTINUE; END IF;
    IF NOT (abs(r.total_debit-r.from_amount)<0.01 AND abs(r.total_credit-r.from_amount)<0.01) THEN
      v_exception:=v_exception+1;
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal_amounts'],'Journal amount does not match either the USD source amount or evidenced IDR destination amount','Accountant review of the original journal and bank evidence');
      CONTINUE;
    END IF;
    v_entry:=public.generate_journal_entry_number();
    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
    VALUES(v_entry,r.transfer_date,'historical_repair',r.id,'HR-REV-'||r.transfer_number,'Reversal of legacy USD-source functional posting '||r.entry_number,r.total_credit,r.total_debit,true,now(),'IDR','IDR',r.exchange_rate,true)
    RETURNING id INTO v_reversal;
    v_line:=1;
    FOR l IN SELECT jl.* FROM public.journal_entry_lines jl WHERE jl.journal_entry_id=r.journal_entry_id ORDER BY jl.line_number LOOP
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
      VALUES(v_reversal,v_line,l.account_id,l.credit,l.debit,'Historical FX reversal: '||COALESCE(l.description,''),l.supplier_id,l.transaction_currency,l.transaction_credit,l.transaction_debit,l.functional_currency,l.exchange_rate);
      v_line:=v_line+1;
    END LOOP;
    UPDATE public.journal_entries SET is_reversed=true,reversed_by_id=v_reversal WHERE id=r.journal_entry_id;
    v_entry:=public.generate_journal_entry_number();
    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
    VALUES(v_entry,r.transfer_date,'historical_repair',r.id,'HR-FX-'||r.transfer_number,'Corrected USD→IDR fund transfer '||r.transfer_number,r.to_amount,r.to_amount,true,now(),'IDR','IDR',r.exchange_rate,true)
    RETURNING id INTO v_corrected;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
    VALUES(v_corrected,1,r.to_coa,r.to_amount,0,'Corrected transfer into IDR bank','IDR',r.to_amount,0,'IDR',1);
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
    VALUES(v_corrected,2,r.from_coa,0,r.to_amount,'Corrected transfer out of USD bank','USD',0,r.from_amount,'IDR',r.exchange_rate);
    UPDATE public.fund_transfers SET journal_entry_id=v_corrected WHERE id=r.id;
    UPDATE public.bank_statement_lines SET matched_entry_id=v_corrected, reconciliation_status='matched' WHERE id IN(r.from_stmt,r.to_stmt);
    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
    VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal_entry','bank matched_entry_id'],jsonb_build_object('journal_entry_id',r.journal_entry_id,'entry_number',r.entry_number,'total',r.total_debit),jsonb_build_object('reversal_journal_id',v_reversal,'replacement_journal_id',v_corrected,'replacement_entry_number',v_entry,'functional_idr',r.to_amount,'transaction_usd',r.from_amount,'rate',r.exchange_rate),'Both bank statement sides prove the USD source amount, IDR destination amount, and historical FX rate');
    v_repaired:=v_repaired+1;
  END LOOP;
  UPDATE public.finance_historical_repair_runs SET completed_at=now(),total_records_scanned=v_repaired+v_skipped+v_exception,records_repaired=v_repaired,records_manual_review=v_exception,records_skipped=v_skipped WHERE id=v_run;
  RETURN jsonb_build_object('run_id',v_run,'repaired',v_repaired,'skipped_already_correct',v_skipped,'manual_review',v_exception,'cutoff',p_cutoff);
END $$;


--
-- Name: repair_posted_fund_transfer_from_source("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."repair_posted_fund_transfer_from_source"("p_fund_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_transfer public.fund_transfers%ROWTYPE;
  v_journal public.journal_entries%ROWTYPE;
  v_from_coa uuid;
  v_to_coa uuid;
  v_from_currency text;
  v_to_currency text;
  v_journal_currency text;
  v_expected_rate numeric;
  v_before_lines jsonb;
  v_after_lines jsonb;
  v_repaired_fields text[] := ARRAY[]::text[];
  v_possible_bank_transactions integer;
  v_validation_failures integer;
  v_live_validation_failures integer;
  v_validation_passed boolean;
BEGIN
  PERFORM public._sec_check_finance_role();
  PERFORM set_config('app.finance_historical_repair', 'on', true);
  PERFORM set_config('app.finance_metadata_repair', 'on', true);

  SELECT * INTO v_transfer
  FROM public.fund_transfers
  WHERE id = p_fund_transfer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fund Transfer not found';
  END IF;
  IF v_transfer.status <> 'posted' OR v_transfer.journal_entry_id IS NULL THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer is not posted with an existing journal');
  END IF;

  SELECT * INTO v_journal
  FROM public.journal_entries
  WHERE id = v_transfer.journal_entry_id
  FOR UPDATE;

  IF NOT FOUND OR NOT COALESCE(v_journal.is_posted, false) OR COALESCE(v_journal.is_reversed, false) THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer journal is not an active posted journal');
  END IF;
  IF v_journal.source_module NOT IN ('fund_transfer', 'fund_transfers')
     OR v_journal.reference_id IS DISTINCT FROM v_transfer.id THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer and journal do not prove an authoritative relationship');
  END IF;

  IF v_transfer.from_account_type = 'bank' THEN
    SELECT coa_id, upper(currency) INTO v_from_coa, v_from_currency
    FROM public.bank_accounts WHERE id = v_transfer.from_bank_account_id AND is_active;
  ELSIF v_transfer.from_account_type = 'petty_cash' THEN
    SELECT id, 'IDR' INTO v_from_coa, v_from_currency FROM public.chart_of_accounts WHERE code = '1102' AND is_active LIMIT 1;
  ELSIF v_transfer.from_account_type = 'cash_on_hand' THEN
    SELECT id, 'IDR' INTO v_from_coa, v_from_currency FROM public.chart_of_accounts WHERE code = '1101' AND is_active LIMIT 1;
  END IF;

  IF v_transfer.to_account_type = 'bank' THEN
    SELECT coa_id, upper(currency) INTO v_to_coa, v_to_currency
    FROM public.bank_accounts WHERE id = v_transfer.to_bank_account_id AND is_active;
  ELSIF v_transfer.to_account_type = 'petty_cash' THEN
    SELECT id, 'IDR' INTO v_to_coa, v_to_currency FROM public.chart_of_accounts WHERE code = '1102' AND is_active LIMIT 1;
  ELSIF v_transfer.to_account_type = 'cash_on_hand' THEN
    SELECT id, 'IDR' INTO v_to_coa, v_to_currency FROM public.chart_of_accounts WHERE code = '1101' AND is_active LIMIT 1;
  END IF;

  IF v_from_coa IS NULL OR v_to_coa IS NULL OR v_from_currency IS NULL OR v_to_currency IS NULL THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer source does not contain complete active account and currency information');
  END IF;
  IF v_transfer.from_amount IS NULL OR v_transfer.to_amount IS NULL OR v_transfer.exchange_rate IS NULL THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer source is missing an amount or exchange rate');
  END IF;

  v_expected_rate := CASE
    WHEN v_from_currency = v_to_currency THEN 1
    WHEN v_from_currency = 'IDR' AND v_transfer.to_amount > 0 THEN v_transfer.from_amount / v_transfer.to_amount
    WHEN v_to_currency = 'IDR' AND v_transfer.from_amount > 0 THEN v_transfer.to_amount / v_transfer.from_amount
  END;
  IF v_expected_rate IS NULL OR abs(v_transfer.exchange_rate - v_expected_rate) > 0.000001 THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer exchange rate is not internally consistent with its stored amounts');
  END IF;
  IF (SELECT count(*) FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id) <> 2
     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id AND line_number = 1 AND COALESCE(debit, 0) > 0 AND COALESCE(credit, 0) = 0)
     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id AND line_number = 2 AND COALESCE(credit, 0) > 0 AND COALESCE(debit, 0) = 0) THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Existing journal lines are not a safe two-line transfer journal');
  END IF;
  IF abs(COALESCE(v_journal.total_debit, 0) - COALESCE(v_transfer.from_amount, 0)) > 0.01
     OR abs(COALESCE(v_journal.total_credit, 0) - COALESCE(v_transfer.from_amount, 0)) > 0.01
     OR EXISTS (
       SELECT 1 FROM public.journal_entry_lines l
       WHERE l.journal_entry_id = v_journal.id
         AND ((l.line_number = 1 AND abs(COALESCE(l.debit, 0) - v_transfer.from_amount) > 0.01)
           OR (l.line_number = 2 AND abs(COALESCE(l.credit, 0) - v_transfer.from_amount) > 0.01))
     ) THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Existing posted journal amounts do not match the Fund Transfer source');
  END IF;

  -- No bank transaction is inferred or relinked. If the source document does
  -- not name a line, explicitly refuse to guess, especially when candidates
  -- are ambiguous. The accountant can resolve the missing source information.
  IF v_transfer.from_bank_statement_line_id IS NULL AND v_transfer.from_account_type = 'bank' THEN
    SELECT count(*) INTO v_possible_bank_transactions
    FROM public.bank_statement_lines b
    WHERE b.bank_account_id = v_transfer.from_bank_account_id
      AND abs(b.transaction_date - v_transfer.transfer_date) <= 8
      AND (COALESCE(b.debit_amount, 0) = v_transfer.from_amount OR COALESCE(b.credit_amount, 0) = v_transfer.from_amount);
    IF v_possible_bank_transactions > 1 THEN
      RETURN jsonb_build_object('repaired', false, 'reason', 'Multiple possible From Bank transactions exist; no bank link was guessed');
    END IF;
  END IF;
  IF v_transfer.to_bank_statement_line_id IS NULL AND v_transfer.to_account_type = 'bank' THEN
    SELECT count(*) INTO v_possible_bank_transactions
    FROM public.bank_statement_lines b
    WHERE b.bank_account_id = v_transfer.to_bank_account_id
      AND abs(b.transaction_date - v_transfer.transfer_date) <= 8
      AND (COALESCE(b.debit_amount, 0) = v_transfer.to_amount OR COALESCE(b.credit_amount, 0) = v_transfer.to_amount);
    IF v_possible_bank_transactions > 1 THEN
      RETURN jsonb_build_object('repaired', false, 'reason', 'Multiple possible To Bank transactions exist; no bank link was guessed');
    END IF;
  END IF;

  SELECT jsonb_agg(jsonb_build_object('id', id, 'debit', debit, 'credit', credit) ORDER BY id)
  INTO v_before_lines FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id;

  v_journal_currency := CASE WHEN v_from_currency = v_to_currency THEN v_from_currency ELSE 'IDR' END;
  UPDATE public.journal_entries
  SET source_module = 'fund_transfers', reference_id = v_transfer.id,
      reference_number = v_transfer.transfer_number, transaction_currency = v_journal_currency,
      functional_currency = 'IDR', exchange_rate = v_transfer.exchange_rate,
      amounts_are_functional = true
  WHERE id = v_journal.id
    AND (source_module IS DISTINCT FROM 'fund_transfers' OR reference_id IS DISTINCT FROM v_transfer.id
      OR reference_number IS DISTINCT FROM v_transfer.transfer_number OR transaction_currency IS DISTINCT FROM v_journal_currency
      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM v_transfer.exchange_rate
      OR amounts_are_functional IS DISTINCT FROM true);
  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_metadata'); END IF;

  UPDATE public.journal_entry_lines
  SET account_id = v_to_coa, transaction_currency = v_to_currency,
      functional_currency = 'IDR', exchange_rate = CASE WHEN v_to_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END
  WHERE journal_entry_id = v_journal.id AND line_number = 1
    AND (account_id IS DISTINCT FROM v_to_coa OR transaction_currency IS DISTINCT FROM v_to_currency
      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM CASE WHEN v_to_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END);
  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_debit_line_metadata'); END IF;

  UPDATE public.journal_entry_lines
  SET account_id = v_from_coa, transaction_currency = v_from_currency,
      functional_currency = 'IDR', exchange_rate = CASE WHEN v_from_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END
  WHERE journal_entry_id = v_journal.id AND line_number = 2
    AND (account_id IS DISTINCT FROM v_from_coa OR transaction_currency IS DISTINCT FROM v_from_currency
      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM CASE WHEN v_from_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END);
  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_credit_line_metadata'); END IF;

  SELECT jsonb_agg(jsonb_build_object('id', id, 'debit', debit, 'credit', credit) ORDER BY id)
  INTO v_after_lines FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id;
  IF v_before_lines IS DISTINCT FROM v_after_lines THEN
    RAISE EXCEPTION 'Fund Transfer repair cancelled because a debit or credit value changed';
  END IF;

  -- The existing validation projections are live views. Read them after the
  -- metadata updates; resolve the false-positive only when they are clean.
  SELECT count(*) INTO v_validation_failures
  FROM public.finance_historical_repair_verification_failures f
  WHERE f.document_type = 'fund_transfer' AND f.database_id = v_transfer.id;
  SELECT count(*) INTO v_live_validation_failures
  FROM public.finance_live_verification_failures f
  WHERE f.document_type = 'fund_transfer' AND f.document_id = v_transfer.id;
  v_validation_failures := v_validation_failures + v_live_validation_failures;
  v_validation_passed := v_validation_failures = 0;
  IF v_validation_passed THEN
    UPDATE public.finance_historical_repair_exceptions
    SET status = 'resolved'
    WHERE status = 'manual_review' AND document_type = 'fund_transfer' AND document_id = v_transfer.id;
  END IF;

  -- A no-op retry produces no second audit mutation. The first successful
  -- call records the exact derived fields changed and immutable line values.
  IF COALESCE(array_length(v_repaired_fields, 1), 0) > 0 THEN
    INSERT INTO public.audit_logs(table_name, action_type, record_id, old_values, new_values, changed_fields)
    VALUES ('fund_transfers', 'update', v_transfer.id,
      jsonb_build_object('journal_entry_id', v_journal.id, 'journal_lines', v_before_lines),
      jsonb_build_object('journal_entry_id', v_journal.id, 'journal_lines', v_after_lines,
        'validation_rerun', true, 'validation_passed', v_validation_passed),
      v_repaired_fields);
  END IF;

  IF NOT v_validation_passed THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Derived data still fails the existing Finance validation', 'validation_failures', v_validation_failures);
  END IF;

  RETURN jsonb_build_object('repaired', true, 'repaired_fields', v_repaired_fields,
    'validation_rerun', true, 'journal_entry_id', v_journal.id);
END;
$$;


--
-- Name: reset_bank_statement_on_expense_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reset_bank_statement_on_expense_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
-- When matched_expense_id is set to NULL, reset the reconciliation status
IF OLD.matched_expense_id IS NOT NULL AND NEW.matched_expense_id IS NULL THEN
NEW.reconciliation_status := 'unmatched';
NEW.matched_at := NULL;
NEW.matched_by := NULL;
END IF;

RETURN NEW;
END;
$$;


--
-- Name: reset_receiving_approval_on_invoice_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reset_receiving_approval_on_invoice_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.receiving_approval_status = 'approved' AND (
    NEW.supplier_id IS DISTINCT FROM OLD.supplier_id OR
    NEW.invoice_date IS DISTINCT FROM OLD.invoice_date OR
    NEW.total_amount IS DISTINCT FROM OLD.total_amount OR
    NEW.currency IS DISTINCT FROM OLD.currency OR
    NEW.document_urls IS DISTINCT FROM OLD.document_urls OR
    NEW.notes IS DISTINCT FROM OLD.notes
  ) THEN
    NEW.receiving_approval_status := 'pending_approval';
    NEW.receiving_rejection_reason := NULL;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: reset_receiving_approval_on_item_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reset_receiving_approval_on_item_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE v_invoice_id uuid := COALESCE(NEW.purchase_invoice_id, OLD.purchase_invoice_id);
BEGIN
  UPDATE public.purchase_invoices
     SET receiving_approval_status='pending_approval', receiving_rejection_reason=NULL, updated_at=now()
   WHERE id=v_invoice_id AND receiving_approval_status='approved';
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END; $$;


--
-- Name: resolve_bank_allocation_document("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."resolve_bank_allocation_document"("p_journal_entry_id" "uuid") RETURNS TABLE("document_type" "text", "document_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_module text;
  v_reference uuid;
BEGIN
  SELECT lower(COALESCE(source_module,'')), reference_id
    INTO v_module, v_reference
    FROM public.journal_entries
   WHERE id = p_journal_entry_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_module IN ('payment','payments','payment_voucher')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.payment_vouchers WHERE id=v_reference) THEN
    document_type := 'payment'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module IN ('receipt','receipts','receipt_voucher')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.receipt_vouchers WHERE id=v_reference) THEN
    document_type := 'receipt'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module IN ('expense','expenses','expense_payment')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.finance_expenses WHERE id=v_reference) THEN
    document_type := 'expense'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module IN ('fund_transfer','fund_transfers')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.fund_transfers WHERE id=v_reference) THEN
    document_type := 'fund_transfer'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module IN ('tax_payment','tax_payments')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.tax_payments WHERE id=v_reference) THEN
    document_type := 'tax_payment'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module IN ('petty_cash','petty_cash_transaction')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.petty_cash_transactions WHERE id=v_reference) THEN
    document_type := 'petty_cash'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module = 'historical_repair' AND v_reference IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.finance_expenses WHERE id=v_reference) THEN
      document_type := 'expense'; document_id := v_reference; RETURN NEXT; RETURN;
    ELSIF EXISTS (SELECT 1 FROM public.payment_vouchers WHERE id=v_reference) THEN
      document_type := 'payment'; document_id := v_reference; RETURN NEXT; RETURN;
    ELSIF EXISTS (SELECT 1 FROM public.receipt_vouchers WHERE id=v_reference) THEN
      document_type := 'receipt'; document_id := v_reference; RETURN NEXT; RETURN;
    ELSIF EXISTS (SELECT 1 FROM public.fund_transfers WHERE id=v_reference) THEN
      document_type := 'fund_transfer'; document_id := v_reference; RETURN NEXT; RETURN;
    ELSIF EXISTS (SELECT 1 FROM public.tax_payments WHERE id=v_reference) THEN
      document_type := 'tax_payment'; document_id := v_reference; RETURN NEXT; RETURN;
    ELSIF EXISTS (SELECT 1 FROM public.petty_cash_transactions WHERE id=v_reference) THEN
      document_type := 'petty_cash'; document_id := v_reference; RETURN NEXT; RETURN;
    END IF;
  END IF;

  document_type := 'journal';
  document_id := p_journal_entry_id;
  RETURN NEXT;
END;
$$;


--
-- Name: effective_expense_posting_state; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."effective_expense_posting_state" WITH ("security_invoker"='true') AS
 WITH "original_journals" AS (
         SELECT "fe"."id" AS "expense_id",
            "je"."id",
            "je"."entry_number",
            "je"."entry_date",
            "je"."created_at",
            "je"."is_reversed",
            "je"."reversed_by_id"
           FROM ("public"."finance_expenses" "fe"
             JOIN "public"."journal_entries" "je" ON ((("je"."is_posted" = true) AND (("je"."source_module")::"text" = ANY ((ARRAY['expense'::character varying, 'expenses'::character varying])::"text"[])) AND (("je"."reference_id" = "fe"."id") OR (("je"."reference_id" IS NULL) AND (("je"."reference_number")::"text" = ('EXP-'::"text" || ("fe"."id")::"text")))))))
        ), "explicit_replacement_ids" AS (
         SELECT "expense_explicit_replacement_journals"."expense_id",
            "expense_explicit_replacement_journals"."journal_id"
           FROM "public"."expense_explicit_replacement_journals"() "expense_explicit_replacement_journals"("expense_id", "journal_id")
        ), "replacement_candidates" AS (
         SELECT "eri"."expense_id",
            "je"."id",
            "je"."entry_number",
            "je"."entry_date",
            "je"."reference_number",
            "je"."source_module",
            "je"."created_at"
           FROM ("explicit_replacement_ids" "eri"
             JOIN "public"."journal_entries" "je" ON (("je"."id" = "eri"."journal_id")))
          WHERE (("je"."is_posted" = true) AND (NOT COALESCE("je"."is_reversed", false)))
        UNION
         SELECT "fe"."id",
            "je"."id",
            "je"."entry_number",
            "je"."entry_date",
            "je"."reference_number",
            "je"."source_module",
            "je"."created_at"
           FROM ("public"."finance_expenses" "fe"
             JOIN "public"."journal_entries" "je" ON ((("je"."reference_id" = "fe"."id") AND ("je"."is_posted" = true) AND (NOT COALESCE("je"."is_reversed", false)) AND ((("je"."source_module")::"text" = 'historical_salary_advance_repair'::"text") OR ((("je"."source_module")::"text" = 'historical_repair'::"text") AND (("je"."reference_number")::"text" ~~ 'HR-AP-%'::"text"))))))
        ), "original_rollup" AS (
         SELECT "original_journals"."expense_id",
            ("count"(*) FILTER (WHERE (NOT COALESCE("original_journals"."is_reversed", false))))::integer AS "active_original_count",
            ("count"(*) FILTER (WHERE COALESCE("original_journals"."is_reversed", false)))::integer AS "reversed_original_count",
            ("array_agg"("original_journals"."id" ORDER BY "original_journals"."created_at" DESC, "original_journals"."id" DESC) FILTER (WHERE (NOT COALESCE("original_journals"."is_reversed", false))))[1] AS "active_journal_id",
            ("array_agg"("original_journals"."entry_number" ORDER BY "original_journals"."created_at" DESC, "original_journals"."id" DESC) FILTER (WHERE (NOT COALESCE("original_journals"."is_reversed", false))))[1] AS "active_journal_number",
            ("array_agg"("original_journals"."entry_date" ORDER BY "original_journals"."created_at" DESC, "original_journals"."id" DESC) FILTER (WHERE (NOT COALESCE("original_journals"."is_reversed", false))))[1] AS "active_journal_date",
            ("array_agg"("original_journals"."id" ORDER BY "original_journals"."created_at" DESC, "original_journals"."id" DESC) FILTER (WHERE COALESCE("original_journals"."is_reversed", false)))[1] AS "original_journal_id",
            ("array_agg"("original_journals"."entry_number" ORDER BY "original_journals"."created_at" DESC, "original_journals"."id" DESC) FILTER (WHERE COALESCE("original_journals"."is_reversed", false)))[1] AS "original_journal_number",
            ("array_agg"("original_journals"."reversed_by_id" ORDER BY "original_journals"."created_at" DESC, "original_journals"."id" DESC) FILTER (WHERE (COALESCE("original_journals"."is_reversed", false) AND ("original_journals"."reversed_by_id" IS NOT NULL))))[1] AS "reversal_journal_id"
           FROM "original_journals"
          GROUP BY "original_journals"."expense_id"
        ), "replacement_rollup" AS (
         SELECT "replacement_candidates"."expense_id",
            ("count"(*))::integer AS "active_replacement_count",
            ("array_agg"("replacement_candidates"."id" ORDER BY "replacement_candidates"."created_at" DESC, "replacement_candidates"."id" DESC))[1] AS "replacement_journal_id",
            ("array_agg"("replacement_candidates"."entry_number" ORDER BY "replacement_candidates"."created_at" DESC, "replacement_candidates"."id" DESC))[1] AS "replacement_journal_number",
            ("array_agg"("replacement_candidates"."entry_date" ORDER BY "replacement_candidates"."created_at" DESC, "replacement_candidates"."id" DESC))[1] AS "replacement_journal_date",
            ("array_agg"("replacement_candidates"."reference_number" ORDER BY "replacement_candidates"."created_at" DESC, "replacement_candidates"."id" DESC))[1] AS "replacement_reference",
            ("array_agg"("replacement_candidates"."source_module" ORDER BY "replacement_candidates"."created_at" DESC, "replacement_candidates"."id" DESC))[1] AS "replacement_source_module"
           FROM "replacement_candidates"
          GROUP BY "replacement_candidates"."expense_id"
        ), "resolved" AS (
         SELECT "fe"."id" AS "expense_id",
            "fe"."voucher_number",
            "fe"."approval_status" AS "document_approval_status",
            COALESCE("o"."active_original_count", 0) AS "active_original_count",
            COALESCE("o"."reversed_original_count", 0) AS "reversed_original_count",
            COALESCE("r"."active_replacement_count", 0) AS "active_replacement_count",
            "o"."active_journal_id",
            "o"."active_journal_number",
            "o"."active_journal_date",
            "o"."original_journal_id",
            "o"."original_journal_number",
            "o"."reversal_journal_id",
            "r"."replacement_journal_id",
            "r"."replacement_journal_number",
            "r"."replacement_journal_date",
            "r"."replacement_reference",
            "r"."replacement_source_module"
           FROM (("public"."finance_expenses" "fe"
             LEFT JOIN "original_rollup" "o" ON (("o"."expense_id" = "fe"."id")))
             LEFT JOIN "replacement_rollup" "r" ON (("r"."expense_id" = "fe"."id")))
        )
 SELECT "expense_id",
    "voucher_number",
    "document_approval_status",
    "active_original_count",
    "reversed_original_count",
    "active_replacement_count",
    "active_journal_id",
    "active_journal_number",
    "active_journal_date",
    "original_journal_id",
    "original_journal_number",
    "reversal_journal_id",
    "replacement_journal_id",
    "replacement_journal_number",
    "replacement_journal_date",
    "replacement_reference",
    "replacement_source_module",
        CASE
            WHEN ("active_original_count" > 1) THEN 'AMBIGUOUS'::"text"
            WHEN ("active_replacement_count" > 1) THEN 'AMBIGUOUS'::"text"
            WHEN (("active_original_count" > 0) AND ("active_replacement_count" > 0)) THEN 'AMBIGUOUS'::"text"
            WHEN (("document_approval_status" <> 'approved'::"text") AND (("active_original_count" > 0) OR ("active_replacement_count" > 0))) THEN 'AMBIGUOUS'::"text"
            WHEN ("active_original_count" = 1) THEN 'ACTIVE'::"text"
            WHEN (("reversed_original_count" > 0) AND ("active_replacement_count" = 1)) THEN 'REPLACED'::"text"
            WHEN (("reversed_original_count" > 0) AND ("active_replacement_count" = 0)) THEN 'REVERSED'::"text"
            WHEN ("document_approval_status" = 'rejected'::"text") THEN 'REJECTED'::"text"
            WHEN ("document_approval_status" = 'pending_approval'::"text") THEN 'PENDING'::"text"
            ELSE 'AMBIGUOUS'::"text"
        END AS "effective_posting_state",
    COALESCE("active_journal_id", "replacement_journal_id") AS "effective_journal_id",
    COALESCE("active_journal_number", "replacement_journal_number") AS "effective_journal_number",
    COALESCE("active_journal_date", "replacement_journal_date") AS "effective_journal_date",
        CASE
            WHEN ("active_original_count" > 1) THEN 'multiple_active_original_journals'::"text"
            WHEN ("active_replacement_count" > 1) THEN 'multiple_active_replacement_journals'::"text"
            WHEN (("active_original_count" > 0) AND ("active_replacement_count" > 0)) THEN 'active_original_and_replacement_coexist'::"text"
            WHEN (("document_approval_status" = 'approved'::"text") AND ("active_original_count" = 0) AND ("reversed_original_count" = 0) AND ("active_replacement_count" = 0)) THEN 'approved_without_posted_journal_evidence'::"text"
            WHEN (("document_approval_status" = 'rejected'::"text") AND (("active_original_count" > 0) OR ("active_replacement_count" > 0))) THEN 'rejected_with_active_accounting_path'::"text"
            ELSE NULL::"text"
        END AS "ambiguity_reason"
   FROM "resolved" "x";


--
-- Name: VIEW "effective_expense_posting_state"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW "public"."effective_expense_posting_state" IS 'Canonical read-only expense lifecycle. ACTIVE uses the original journal; REPLACED uses an explicit/known full repair journal; REVERSED has no effective journal.';


--
-- Name: resolve_effective_expense_posting_state("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."resolve_effective_expense_posting_state"("p_expense_id" "uuid") RETURNS SETOF "public"."effective_expense_posting_state"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT s.*
  FROM public.effective_expense_posting_state s
  WHERE s.expense_id = p_expense_id;
$$;


--
-- Name: reverse_credit_note_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reverse_credit_note_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_je_ids uuid[];
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.journal_entry_id IS NULL THEN
      RETURN OLD;
    END IF;

    SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
      INTO v_je_ids
      FROM journal_entries
     WHERE source_module IN ('credit_note', 'credit_note_cogs')
       AND reference_id  = OLD.id;

    IF array_length(v_je_ids, 1) IS NOT NULL THEN
      -- Do not touch bank_statement_lines.updated_at — the column is not
      -- present in every environment (two conflicting CREATE TABLE
      -- IF NOT EXISTS definitions exist in the migration history).
      -- matched_at = NULL is the authoritative recon-reset timestamp.
      UPDATE bank_statement_lines
         SET matched_entry_id      = NULL,
             reconciliation_status = 'unmatched',
             matched_at            = NULL
       WHERE matched_entry_id = ANY (v_je_ids);
      -- bank_reconciliation_items.journal_entry_id has ON DELETE SET NULL
      -- (installed in 20260714150000), so the JE DELETE clears it too.

      DELETE FROM journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);
      DELETE FROM journal_entries     WHERE id = ANY (v_je_ids);
    END IF;
    RETURN OLD;
  END IF;

  -- UPDATE: only reverse if status leaves 'approved'
  IF TG_OP = 'UPDATE'
     AND OLD.status = 'approved'
     AND NEW.status IS DISTINCT FROM 'approved'
     AND OLD.journal_entry_id IS NOT NULL THEN

    SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
      INTO v_je_ids
      FROM journal_entries
     WHERE source_module IN ('credit_note', 'credit_note_cogs')
       AND reference_id  = OLD.id;

    IF array_length(v_je_ids, 1) IS NOT NULL THEN
      -- Do not touch bank_statement_lines.updated_at — the column is not
      -- present in every environment (two conflicting CREATE TABLE
      -- IF NOT EXISTS definitions exist in the migration history).
      -- matched_at = NULL is the authoritative recon-reset timestamp.
      UPDATE bank_statement_lines
         SET matched_entry_id      = NULL,
             reconciliation_status = 'unmatched',
             matched_at            = NULL
       WHERE matched_entry_id = ANY (v_je_ids);

      DELETE FROM journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);
      DELETE FROM journal_entries     WHERE id = ANY (v_je_ids);
    END IF;

    NEW.journal_entry_id := NULL;
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: reverse_fund_transfer("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reverse_fund_transfer"("p_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row                    public.fund_transfers%ROWTYPE;
  v_original_je_id         uuid;
  v_new_je_id              uuid;
  v_new_je_number          text;
  v_existing_reversal      public.journal_entries%ROWTYPE;
  v_period_status          text;
BEGIN
  SELECT *
    INTO v_row
    FROM public.fund_transfers
   WHERE id = p_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fund transfer % not found', p_id
      USING ERRCODE = 'no_data_found';
  END IF;

  IF v_row.status <> 'posted' THEN
    RAISE EXCEPTION 'Only posted fund transfers can be reversed (current status: %)', v_row.status
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT id
    INTO v_original_je_id
    FROM public.journal_entries
   WHERE source_module = 'fund_transfers'
     AND reference_id = p_id
     AND reference_number = v_row.transfer_number
   ORDER BY created_at ASC
   LIMIT 1
   FOR UPDATE;

  IF v_original_je_id IS NULL THEN
    RAISE EXCEPTION 'Original journal entry for fund transfer % not found', v_row.transfer_number
      USING ERRCODE = 'no_data_found';
  END IF;

  v_new_je_number := 'REV-' || v_row.transfer_number;

  SELECT *
    INTO v_existing_reversal
    FROM public.journal_entries
   WHERE source_module = 'fund_transfers'
     AND reference_id = p_id
     AND reference_number = v_new_je_number
   LIMIT 1
   FOR UPDATE;

  IF v_existing_reversal.id IS NOT NULL THEN
    IF COALESCE(v_existing_reversal.is_posted, false)
       OR NOT COALESCE(v_existing_reversal.is_reversed, false) THEN
      RAISE EXCEPTION 'Cannot reverse %: its preserved reversal journal is already active or inconsistent',
        v_row.transfer_number USING ERRCODE = 'integrity_constraint_violation';
    END IF;

    IF EXISTS (
      (
        SELECT line_number, account_id, debit, credit
          FROM public.journal_entry_lines
         WHERE journal_entry_id = v_original_je_id
        EXCEPT ALL
        SELECT line_number, account_id, credit, debit
          FROM public.journal_entry_lines
         WHERE journal_entry_id = v_existing_reversal.id
      )
      UNION ALL
      (
        SELECT line_number, account_id, debit, credit
          FROM public.journal_entry_lines
         WHERE journal_entry_id = v_existing_reversal.id
        EXCEPT ALL
        SELECT line_number, account_id, credit, debit
          FROM public.journal_entry_lines
         WHERE journal_entry_id = v_original_je_id
      )
    ) THEN
      RAISE EXCEPTION 'Cannot reverse %: its preserved reversal journal no longer matches the original',
        v_row.transfer_number USING ERRCODE = 'integrity_constraint_violation';
    END IF;

    SELECT status
      INTO v_period_status
      FROM public.accounting_periods
     WHERE start_date <= v_existing_reversal.entry_date
       AND end_date >= v_existing_reversal.entry_date
     ORDER BY start_date DESC
     LIMIT 1;

    IF v_period_status IS NOT NULL AND v_period_status <> 'open' THEN
      RAISE EXCEPTION
        'Cannot reverse %: the preserved reversal period for % is %',
        v_row.transfer_number,
        to_char(v_existing_reversal.entry_date, 'FMMonth YYYY'),
        v_period_status USING ERRCODE = 'check_violation';
    END IF;

    UPDATE public.journal_entries
       SET is_posted = true,
           is_reversed = false
     WHERE id = v_existing_reversal.id;

    UPDATE public.journal_entries
       SET is_reversed = true,
           reversed_by_id = v_existing_reversal.id
     WHERE id = v_original_je_id;

    UPDATE public.fund_transfers
       SET status = 'reversed',
           reversed_at = now(),
           reversed_by = auth.uid()
     WHERE id = p_id;

    RETURN v_existing_reversal.id;
  END IF;

  INSERT INTO public.journal_entries (
    entry_number,
    entry_date,
    description,
    source_module,
    reference_id,
    reference_number,
    is_posted,
    created_by
  )
  SELECT
    v_new_je_number,
    CURRENT_DATE,
    'Reversal of ' || COALESCE(je.description, je.entry_number),
    'fund_transfers',
    p_id,
    v_new_je_number,
    true,
    auth.uid()
  FROM public.journal_entries je
  WHERE je.id = v_original_je_id
  RETURNING id INTO v_new_je_id;

  UPDATE public.journal_entries
     SET is_reversed = true,
         reversed_by_id = v_new_je_id
   WHERE id = v_original_je_id;

  INSERT INTO public.journal_entry_lines (
    journal_entry_id,
    line_number,
    account_id,
    description,
    debit,
    credit
  )
  SELECT
    v_new_je_id,
    line_number,
    account_id,
    'REV: ' || COALESCE(description, ''),
    credit,
    debit
  FROM public.journal_entry_lines
  WHERE journal_entry_id = v_original_je_id;

  UPDATE public.fund_transfers
     SET status = 'reversed',
         reversed_at = now(),
         reversed_by = auth.uid()
   WHERE id = p_id;

  RETURN v_new_je_id;
END;
$$;


--
-- Name: run_deterministic_finance_historical_repair(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."run_deterministic_finance_historical_repair"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_run uuid;
  r record;
  v_number text;
  v_je uuid;
  v_scanned bigint:=0;
BEGIN
  -- Read by sync_expense_journal_currency_and_state(). Metadata repair may
  -- fire document triggers, but must never convert or rewrite old JE amounts.
  PERFORM set_config('app.finance_historical_repair','on',true);
  INSERT INTO public.finance_historical_repair_runs(notes)
  VALUES('Deterministic metadata/link repair. Accounting amounts are immutable.') RETURNING id INTO v_run;

  SELECT COUNT(*) INTO v_scanned FROM (
    SELECT id FROM public.finance_expenses UNION ALL SELECT id FROM public.receipt_vouchers
    UNION ALL SELECT id FROM public.payment_vouchers UNION ALL SELECT id FROM public.fund_transfers
    UNION ALL SELECT id FROM public.journal_entries UNION ALL SELECT id FROM public.bank_statement_lines
  ) s;

  -- Missing expense voucher numbers: chronological ordering is deterministic;
  -- numbering is metadata and does not alter accounting values.
  FOR r IN SELECT * FROM public.finance_expenses WHERE voucher_number IS NULL OR btrim(voucher_number)='' ORDER BY expense_date,created_at,id FOR UPDATE LOOP
    v_number:=public.next_expense_voucher_number(r.expense_date);
    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
    VALUES(v_run,'expense',r.id,v_number,ARRAY['voucher_number'],jsonb_build_object('voucher_number',r.voucher_number),jsonb_build_object('voucher_number',v_number),'Legacy Bank Reconciliation expense omitted native voucher numbering');
    UPDATE public.finance_expenses SET voucher_number=v_number WHERE id=r.id;
  END LOOP;

  FOR r IN SELECT * FROM public.receipt_vouchers WHERE voucher_number IS NULL OR btrim(voucher_number)='' ORDER BY voucher_date,created_at,id FOR UPDATE LOOP
    v_number:=public.next_receipt_voucher_number(r.voucher_date);
    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
    VALUES(v_run,'receipt',r.id,v_number,ARRAY['voucher_number'],jsonb_build_object('voucher_number',r.voucher_number),jsonb_build_object('voucher_number',v_number),'Missing receipt number repaired by the native atomic numbering engine');
    UPDATE public.receipt_vouchers SET voucher_number=v_number WHERE id=r.id;
  END LOOP;

  FOR r IN SELECT * FROM public.payment_vouchers WHERE voucher_number IS NULL OR btrim(voucher_number)='' ORDER BY voucher_date,created_at,id FOR UPDATE LOOP
    v_number:=public.next_payment_voucher_number(r.voucher_date);
    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
    VALUES(v_run,'payment',r.id,v_number,ARRAY['voucher_number'],jsonb_build_object('voucher_number',r.voucher_number),jsonb_build_object('voucher_number',v_number),'Missing payment number repaired by the native atomic numbering engine');
    UPDATE public.payment_vouchers SET voucher_number=v_number WHERE id=r.id;
  END LOOP;

  -- Fund Transfer source metadata is deterministic when IDR is one side. The
  -- old poster's GL values are already functional only when IDR is the source;
  -- USD-source legacy postings are exceptions because correcting them would
  -- change posted accounting values.
  FOR r IN
    SELECT ft.id,ft.transfer_number,ft.status,ft.from_amount,ft.to_amount,ft.exchange_rate,ft.journal_entry_id,
      CASE WHEN ft.from_account_type='bank' THEN upper(fba.currency) ELSE 'IDR' END AS from_currency,
      CASE WHEN ft.to_account_type='bank' THEN upper(tba.currency) ELSE 'IDR' END AS to_currency,
      CASE
        WHEN (CASE WHEN ft.from_account_type='bank' THEN upper(fba.currency) ELSE 'IDR' END)='IDR'
         AND (CASE WHEN ft.to_account_type='bank' THEN upper(tba.currency) ELSE 'IDR' END)='IDR' THEN 1
        WHEN (CASE WHEN ft.from_account_type='bank' THEN upper(fba.currency) ELSE 'IDR' END)='IDR' AND ft.to_amount>0 THEN ft.from_amount/ft.to_amount
        WHEN (CASE WHEN ft.to_account_type='bank' THEN upper(tba.currency) ELSE 'IDR' END)='IDR' AND ft.from_amount>0 THEN ft.to_amount/ft.from_amount
      END AS expected_rate
    FROM public.fund_transfers ft
    LEFT JOIN public.bank_accounts fba ON fba.id=ft.from_bank_account_id
    LEFT JOIN public.bank_accounts tba ON tba.id=ft.to_bank_account_id
  LOOP
    IF r.status='posted' AND r.journal_entry_id IS NULL THEN
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal_entry_id'],
        'Posted Fund Transfer has no linked Journal Entry','Correct active Journal Entry or accountant-authorised reversal/reposting');
    END IF;
    IF r.from_currency IS NULL OR r.to_currency IS NULL OR r.from_currency NOT IN('IDR','USD') OR r.to_currency NOT IN('IDR','USD') THEN
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['from_currency','to_currency'],
        'Fund Transfer account relationships do not prove supported currencies','Correct source and destination account currencies');
    END IF;
    IF r.expected_rate IS NOT NULL AND (r.exchange_rate IS NULL OR abs(r.exchange_rate-r.expected_rate)>0.000001) THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['exchange_rate'],
        jsonb_build_object('exchange_rate',r.exchange_rate),jsonb_build_object('exchange_rate',r.expected_rate),
        'Stored IDR and USD side amounts prove the USD-to-IDR Fund Transfer rate');
      UPDATE public.fund_transfers SET exchange_rate=r.expected_rate WHERE id=r.id;
    END IF;
    IF r.journal_entry_id IS NOT NULL AND r.from_currency='IDR' AND r.to_currency IN('IDR','USD')
       AND (r.to_currency='USD' OR abs(r.from_amount-r.to_amount)<=0.01) THEN
      IF EXISTS(SELECT 1 FROM public.journal_entries je LEFT JOIN public.journal_entry_lines l ON l.journal_entry_id=je.id
        WHERE je.id=r.journal_entry_id AND (je.transaction_currency IS NULL OR je.functional_currency IS NULL
          OR je.amounts_are_functional IS NULL OR l.transaction_currency IS NULL OR l.transaction_debit IS NULL
          OR l.transaction_credit IS NULL OR l.functional_currency IS NULL OR l.exchange_rate IS NULL)) THEN
        INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
        VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal currency metadata','journal line transaction metadata'],
          jsonb_build_object('journal_entry_id',r.journal_entry_id),
          jsonb_build_object('from_currency',r.from_currency,'to_currency',r.to_currency,'exchange_rate',COALESCE(r.expected_rate,1)),
          'IDR-source legacy Contra already stores functional IDR GL values; source amounts prove line transaction metadata');
        UPDATE public.journal_entry_lines SET
          transaction_currency=COALESCE(transaction_currency,CASE WHEN line_number=1 THEN r.to_currency ELSE r.from_currency END),
          transaction_debit=COALESCE(transaction_debit,CASE WHEN line_number=1 THEN r.to_amount ELSE 0 END),
          transaction_credit=COALESCE(transaction_credit,CASE WHEN line_number=2 THEN r.from_amount ELSE 0 END),
          functional_currency=COALESCE(functional_currency,'IDR'),
          exchange_rate=COALESCE(exchange_rate,CASE WHEN line_number=1 AND r.to_currency='USD' THEN r.expected_rate ELSE 1 END)
        WHERE journal_entry_id=r.journal_entry_id AND line_number IN(1,2);
        UPDATE public.journal_entries SET transaction_currency=COALESCE(transaction_currency,CASE WHEN r.from_currency=r.to_currency THEN r.from_currency ELSE 'IDR' END),
          functional_currency=COALESCE(functional_currency,'IDR'),exchange_rate=COALESCE(exchange_rate,COALESCE(r.expected_rate,1)),
          amounts_are_functional=COALESCE(amounts_are_functional,true)
        WHERE id=r.journal_entry_id;
      END IF;
    ELSIF r.journal_entry_id IS NOT NULL AND r.from_currency='USD' THEN
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal functional debit/credit','journal currency metadata'],
        'Legacy USD-source Contra stored the USD source amount in functional GL columns; posted values were not rewritten',
        'Accountant approval of the historical USD-to-IDR rate and a controlled correcting/reversal entry');
    END IF;
  END LOOP;

  -- Expense bank/currency metadata only when exactly one linked bank account is
  -- provable. IDR rate is certain; USD rate is never guessed.
  FOR r IN
    SELECT fe.id,fe.voucher_number,fe.bank_account_id,fe.payment_method,fe.transaction_currency,fe.currency_code,
      fe.functional_currency,fe.bank_account_currency,fe.payment_currency,fe.exchange_rate,
      (array_agg(DISTINCT bsl.bank_account_id))[1] AS linked_bank_id,min(upper(COALESCE(bsl.currency,ba.currency))) AS linked_currency,
      count(DISTINCT bsl.bank_account_id) AS bank_count
    FROM public.finance_expenses fe LEFT JOIN public.bank_statement_lines bsl ON bsl.matched_expense_id=fe.id
    LEFT JOIN public.bank_accounts ba ON ba.id=bsl.bank_account_id
    GROUP BY fe.id HAVING count(bsl.id)>0
  LOOP
    IF r.bank_count=1 THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      SELECT v_run,'expense',r.id,r.voucher_number,
        ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NULL THEN 'bank_account_id' END,
          CASE WHEN r.transaction_currency IS NULL THEN 'transaction_currency' END,
          CASE WHEN r.currency_code IS NULL THEN 'currency_code' END,
          CASE WHEN r.functional_currency IS NULL THEN 'functional_currency' END,
          CASE WHEN r.bank_account_currency IS NULL THEN 'bank_account_currency' END,
          CASE WHEN r.payment_currency IS NULL THEN 'payment_currency' END,
          CASE WHEN r.linked_currency='IDR' AND r.exchange_rate IS NULL THEN 'exchange_rate' END],NULL),
        jsonb_build_object('bank_account_id',r.bank_account_id,'transaction_currency',r.transaction_currency,
          'currency_code',r.currency_code,'functional_currency',r.functional_currency,
          'bank_account_currency',r.bank_account_currency,'payment_currency',r.payment_currency,'exchange_rate',r.exchange_rate),
        jsonb_build_object('bank_account_id',COALESCE(r.bank_account_id,r.linked_bank_id),
          'transaction_currency',COALESCE(r.transaction_currency,r.linked_currency),
          'currency_code',COALESCE(r.currency_code,r.linked_currency),'functional_currency',COALESCE(r.functional_currency,'IDR'),
          'bank_account_currency',COALESCE(r.bank_account_currency,r.linked_currency),
          'payment_currency',COALESCE(r.payment_currency,r.linked_currency),
          'exchange_rate',COALESCE(r.exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)),
        'Unique reconciliation line proves bank account and transaction currency'
      WHERE r.bank_account_id IS NULL OR r.transaction_currency IS NULL OR r.currency_code IS NULL
         OR r.functional_currency IS NULL OR r.bank_account_currency IS NULL OR r.payment_currency IS NULL
         OR (r.linked_currency='IDR' AND r.exchange_rate IS NULL);
      UPDATE public.finance_expenses SET bank_account_id=COALESCE(bank_account_id,r.linked_bank_id),
        currency_code=COALESCE(currency_code,r.linked_currency),transaction_currency=COALESCE(transaction_currency,r.linked_currency),
        functional_currency=COALESCE(functional_currency,'IDR'),bank_account_currency=COALESCE(bank_account_currency,r.linked_currency),
        payment_currency=COALESCE(payment_currency,r.linked_currency),exchange_rate=COALESCE(exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)
      WHERE id=r.id;
      IF r.linked_currency='USD' AND r.exchange_rate IS NULL THEN
        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
        VALUES(v_run,'expense',r.id,r.voucher_number,ARRAY['exchange_rate'],'USD currency is certain but no historical transaction-date rate is stored','Authoritative USD-to-IDR rate and rate source/date');
      END IF;
      IF (r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id)
         OR (r.transaction_currency IS NOT NULL AND upper(r.transaction_currency)<>r.linked_currency) THEN
        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
        VALUES(v_run,'expense',r.id,r.voucher_number,
          ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id THEN 'bank_account_id' END,
            CASE WHEN r.transaction_currency IS NOT NULL AND upper(r.transaction_currency)<>r.linked_currency THEN 'transaction_currency' END],NULL),
          'Stored expense metadata conflicts with its unique reconciliation bank line; neither side was overwritten',
          'Accountant confirmation of the correct bank account and transaction currency');
      END IF;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'expense',r.id,r.voucher_number,ARRAY['bank_account_id','transaction_currency'],'More than one linked bank account; no single relationship is certain','Correct paying bank account and transaction currency');
    END IF;
  END LOOP;

  -- IDR source rows have a certain functional rate of 1.
  INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
  SELECT v_run,'expense',id,voucher_number,
    ARRAY_REMOVE(ARRAY[CASE WHEN exchange_rate IS NULL THEN 'exchange_rate' END,CASE WHEN functional_currency IS NULL THEN 'functional_currency' END],NULL),
    jsonb_build_object('exchange_rate',exchange_rate,'functional_currency',functional_currency),
    jsonb_build_object('exchange_rate',COALESCE(exchange_rate,1),'functional_currency',COALESCE(functional_currency,'IDR')),
    'IDR functional rate and functional currency are deterministic'
  FROM public.finance_expenses WHERE transaction_currency='IDR' AND (exchange_rate IS NULL OR functional_currency IS NULL);
  UPDATE public.finance_expenses SET exchange_rate=COALESCE(exchange_rate,1),functional_currency=COALESCE(functional_currency,'IDR')
  WHERE transaction_currency='IDR' AND (exchange_rate IS NULL OR functional_currency IS NULL);

  -- Duplicate historical numbers are never silently renumbered because the
  -- correct legal document number cannot be inferred.
  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'expense',fe.id,fe.voucher_number,ARRAY['voucher_number'],
    'Voucher number is duplicated; renumbering legal history is not deterministic',
    'Accountant-approved canonical number for every duplicated document'
  FROM public.finance_expenses fe JOIN (
    SELECT voucher_number FROM public.finance_expenses WHERE voucher_number IS NOT NULL
    GROUP BY voucher_number HAVING count(*)>1
  ) d USING(voucher_number);

  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'receipt',rv.id,rv.voucher_number,ARRAY['voucher_number'],
    'Voucher number is duplicated; legal history cannot be renumbered deterministically',
    'Accountant-approved canonical number for every duplicated receipt'
  FROM public.receipt_vouchers rv JOIN (
    SELECT voucher_number FROM public.receipt_vouchers WHERE voucher_number IS NOT NULL
    GROUP BY voucher_number HAVING count(*)>1
  ) d USING(voucher_number);

  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'payment',pv.id,pv.voucher_number,ARRAY['voucher_number'],
    'Voucher number is duplicated; legal history cannot be renumbered deterministically',
    'Accountant-approved canonical number for every duplicated payment'
  FROM public.payment_vouchers pv JOIN (
    SELECT voucher_number FROM public.payment_vouchers WHERE voucher_number IS NOT NULL
    GROUP BY voucher_number HAVING count(*)>1
  ) d USING(voucher_number);

  -- Deterministic source identity repairs.
  FOR r IN SELECT id,entry_number,reference_number,reference_id FROM public.journal_entries
    WHERE source_module='expenses' AND reference_id IS NULL AND reference_number LIKE 'EXP-%' LOOP
    BEGIN
      IF EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=substring(r.reference_number from 5)::uuid) THEN
        INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
        VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['reference_id'],jsonb_build_object('reference_id',NULL),
          jsonb_build_object('reference_id',substring(r.reference_number from 5)::uuid),'EXP UUID reference deterministically identifies source expense');
        UPDATE public.journal_entries SET reference_id=substring(r.reference_number from 5)::uuid WHERE id=r.id;
      END IF;
    EXCEPTION WHEN invalid_text_representation THEN
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['reference_id'],'Expense reference number does not contain a valid UUID','Correct source expense database ID');
    END;
  END LOOP;

  -- Canonical JE links from typed document links.
  FOR r IN SELECT bsl.id,bsl.reference,bsl.matched_entry_id,
      COALESCE(rv.journal_entry_id,pv.journal_entry_id,ft.journal_entry_id,tp.journal_entry_id,je_exp.id,je_pc.id) AS resolved_je
    FROM public.bank_statement_lines bsl
    LEFT JOIN public.receipt_vouchers rv ON rv.id=bsl.matched_receipt_id
    LEFT JOIN public.payment_vouchers pv ON pv.id=bsl.matched_payment_id
    LEFT JOIN public.fund_transfers ft ON ft.id=bsl.matched_fund_transfer_id
    LEFT JOIN public.tax_payments tp ON tp.id=bsl.matched_tax_payment_id
    LEFT JOIN LATERAL(SELECT id FROM public.journal_entries WHERE source_module='expenses'
      AND (reference_id=bsl.matched_expense_id OR reference_number='EXP-'||bsl.matched_expense_id::text)
      AND is_posted=true AND COALESCE(is_reversed,false)=false ORDER BY created_at DESC LIMIT 1) je_exp ON true
    LEFT JOIN LATERAL(SELECT id FROM public.journal_entries WHERE source_module='petty_cash' AND reference_id=bsl.matched_petty_cash_id AND is_posted=true AND COALESCE(is_reversed,false)=false ORDER BY created_at DESC LIMIT 1) je_pc ON true
    WHERE bsl.matched_entry_id IS NULL AND (bsl.matched_expense_id IS NOT NULL OR bsl.matched_receipt_id IS NOT NULL OR bsl.matched_payment_id IS NOT NULL OR bsl.matched_fund_transfer_id IS NOT NULL OR bsl.matched_petty_cash_id IS NOT NULL OR bsl.matched_tax_payment_id IS NOT NULL)
  LOOP
    IF r.resolved_je IS NOT NULL THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      VALUES(v_run,'bank_reconciliation',r.id,r.reference,ARRAY['matched_entry_id'],jsonb_build_object('matched_entry_id',NULL),jsonb_build_object('matched_entry_id',r.resolved_je),'Typed document link resolves one active journal');
      UPDATE public.bank_statement_lines SET matched_entry_id=r.resolved_je WHERE id=r.id;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'bank_reconciliation',r.id,r.reference,ARRAY['matched_entry_id'],'Linked document has no provable active journal','Post or identify the correct source document journal');
    END IF;
  END LOOP;

  -- Recover missing typed document links from an existing canonical JE only
  -- when exactly one source document owns that JE.
  FOR r IN
    WITH untyped AS (
      SELECT b.* FROM public.bank_statement_lines b
      WHERE b.matched_entry_id IS NOT NULL AND b.matched_expense_id IS NULL
        AND b.matched_receipt_id IS NULL AND b.matched_payment_id IS NULL
        AND b.matched_fund_transfer_id IS NULL AND b.matched_petty_cash_id IS NULL
        AND b.matched_tax_payment_id IS NULL
    ), candidates AS (
      SELECT b.id,b.reference,'expense'::text AS source_type,fe.id AS source_id
      FROM untyped b JOIN public.journal_entries je ON je.id=b.matched_entry_id
      JOIN public.finance_expenses fe ON je.source_module='expenses'
        AND (je.reference_id=fe.id OR je.reference_number='EXP-'||fe.id::text)
      UNION ALL
      SELECT b.id,b.reference,'receipt',rv.id FROM untyped b JOIN public.receipt_vouchers rv ON rv.journal_entry_id=b.matched_entry_id
      UNION ALL
      SELECT b.id,b.reference,'payment',pv.id FROM untyped b JOIN public.payment_vouchers pv ON pv.journal_entry_id=b.matched_entry_id
      UNION ALL
      SELECT b.id,b.reference,'fund_transfer',ft.id FROM untyped b JOIN public.fund_transfers ft ON ft.journal_entry_id=b.matched_entry_id
      UNION ALL
      SELECT b.id,b.reference,'petty_cash',pc.id FROM untyped b JOIN public.journal_entries je ON je.id=b.matched_entry_id
        JOIN public.petty_cash_transactions pc ON je.source_module='petty_cash' AND je.reference_id=pc.id
      UNION ALL
      SELECT b.id,b.reference,'tax_payment',tp.id FROM untyped b JOIN public.tax_payments tp ON tp.journal_entry_id=b.matched_entry_id
    )
    SELECT id,reference,(array_agg(source_type ORDER BY source_type))[1] AS source_type,
      (array_agg(source_id ORDER BY source_type))[1] AS source_id,count(*) AS candidate_count
    FROM candidates GROUP BY id,reference
  LOOP
    IF r.candidate_count=1 THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      VALUES(v_run,'bank_reconciliation',r.id,r.reference,ARRAY['typed document link'],
        jsonb_build_object('typed_document_id',NULL),jsonb_build_object('document_type',r.source_type,'document_id',r.source_id),
        'Existing Journal Entry is owned by exactly one native Finance document');
      UPDATE public.bank_statement_lines SET
        matched_expense_id=CASE WHEN r.source_type='expense' THEN r.source_id ELSE matched_expense_id END,
        matched_receipt_id=CASE WHEN r.source_type='receipt' THEN r.source_id ELSE matched_receipt_id END,
        matched_payment_id=CASE WHEN r.source_type='payment' THEN r.source_id ELSE matched_payment_id END,
        matched_fund_transfer_id=CASE WHEN r.source_type='fund_transfer' THEN r.source_id ELSE matched_fund_transfer_id END,
        matched_petty_cash_id=CASE WHEN r.source_type='petty_cash' THEN r.source_id ELSE matched_petty_cash_id END,
        matched_tax_payment_id=CASE WHEN r.source_type='tax_payment' THEN r.source_id ELSE matched_tax_payment_id END
      WHERE id=r.id;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'bank_reconciliation',r.id,r.reference,ARRAY['typed document link'],
        'Journal Entry is owned by more than one possible native document','Accountant selection of the source document represented by this bank line');
    END IF;
  END LOOP;

  -- Legacy bank-reconciliation JEs stored the bank-statement amount directly
  -- in debit/credit. A single linked statement currency proves the transaction
  -- currency. IDR also proves rate=1 and functional values. For USD, the rate
  -- and functional values are unknown: preserve every amount and raise an
  -- exception instead of pretending the values are IDR.
  FOR r IN
    SELECT je.id,je.entry_number,je.transaction_currency,je.functional_currency,je.exchange_rate,je.amounts_are_functional,
      min(upper(COALESCE(bsl.currency,ba.currency))) AS proven_currency,
      count(DISTINCT upper(COALESCE(bsl.currency,ba.currency))) AS currency_count,
      bool_or(jel.transaction_currency IS NULL OR jel.transaction_debit IS NULL OR jel.transaction_credit IS NULL
        OR jel.functional_currency IS NULL OR (upper(COALESCE(bsl.currency,ba.currency))='IDR' AND jel.exchange_rate IS NULL)) AS line_metadata_missing
    FROM public.journal_entries je
    JOIN public.bank_statement_lines bsl ON bsl.matched_entry_id=je.id
    JOIN public.journal_entry_lines jel ON jel.journal_entry_id=je.id
    LEFT JOIN public.bank_accounts ba ON ba.id=bsl.bank_account_id
    WHERE je.source_module='bank_reconciliation'
    GROUP BY je.id
  LOOP
    IF r.currency_count=1 AND r.proven_currency IN ('IDR','USD') THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      SELECT v_run,'journal',r.id,r.entry_number,
        ARRAY_REMOVE(ARRAY[CASE WHEN r.transaction_currency IS NULL THEN 'transaction_currency' END,
          CASE WHEN r.functional_currency IS NULL THEN 'functional_currency' END,
          CASE WHEN r.proven_currency='IDR' AND r.exchange_rate IS NULL THEN 'exchange_rate' END,
          CASE WHEN r.amounts_are_functional IS NULL THEN 'amounts_are_functional' END,
          CASE WHEN r.line_metadata_missing THEN 'journal_lines.currency_and_transaction_metadata' END],NULL),
        jsonb_build_object('transaction_currency',r.transaction_currency,'functional_currency',r.functional_currency,
          'exchange_rate',r.exchange_rate,'amounts_are_functional',r.amounts_are_functional,
          'journal_lines_metadata_missing',r.line_metadata_missing),
        jsonb_build_object('transaction_currency',COALESCE(r.transaction_currency,r.proven_currency),
          'functional_currency','IDR','exchange_rate',COALESCE(r.exchange_rate,CASE WHEN r.proven_currency='IDR' THEN 1 END),
          'amounts_are_functional',r.proven_currency='IDR'),
        'Exactly one linked bank-statement currency proves journal transaction currency'
      WHERE r.transaction_currency IS NULL OR r.functional_currency IS NULL OR r.amounts_are_functional IS NULL
         OR r.line_metadata_missing OR (r.proven_currency='IDR' AND r.exchange_rate IS NULL);

      UPDATE public.journal_entries SET
        transaction_currency=COALESCE(transaction_currency,r.proven_currency),functional_currency=COALESCE(functional_currency,'IDR'),
        exchange_rate=COALESCE(exchange_rate,CASE WHEN r.proven_currency='IDR' THEN 1 END),
        amounts_are_functional=COALESCE(amounts_are_functional,CASE WHEN r.proven_currency='IDR' THEN true ELSE false END)
      WHERE id=r.id;
      UPDATE public.journal_entry_lines SET
        transaction_currency=COALESCE(transaction_currency,r.proven_currency),
        transaction_debit=COALESCE(transaction_debit,debit),transaction_credit=COALESCE(transaction_credit,credit),
        functional_currency=COALESCE(functional_currency,'IDR'),
        exchange_rate=COALESCE(exchange_rate,CASE WHEN r.proven_currency='IDR' THEN 1 END)
      WHERE journal_entry_id=r.id;

      IF r.proven_currency='USD' AND r.exchange_rate IS NULL THEN
        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
        VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['exchange_rate','functional debit/credit values'],
          'USD transaction currency is proven, but no authoritative historical rate is stored; posted amounts were preserved',
          'Authoritative USD-to-IDR rate and rate source/date; accountant approval before functional values are corrected');
      END IF;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['transaction_currency','exchange_rate'],
        'Linked bank statements do not prove exactly one currency','Correct transaction currency and authoritative historical exchange rate');
    END IF;
  END LOOP;

  -- Native receipt metadata is repairable only from its own unique typed bank
  -- reconciliation link. This does not post, unpost, or alter the receipt.
  FOR r IN
    SELECT rv.id,rv.voucher_number,rv.bank_account_id,rv.payment_method,rv.transaction_currency,rv.currency_code,
      rv.functional_currency,rv.bank_account_currency,rv.payment_currency,rv.exchange_rate,
      (array_agg(DISTINCT bsl.bank_account_id))[1] AS linked_bank_id,min(upper(COALESCE(bsl.currency,ba.currency))) AS linked_currency,
      count(DISTINCT bsl.bank_account_id) AS bank_count
    FROM public.receipt_vouchers rv
    JOIN public.bank_statement_lines bsl ON bsl.matched_receipt_id=rv.id
    LEFT JOIN public.bank_accounts ba ON ba.id=bsl.bank_account_id
    GROUP BY rv.id
  LOOP
    IF r.bank_count=1 AND r.linked_currency IN ('IDR','USD') THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      SELECT v_run,'receipt',r.id,r.voucher_number,
        ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NULL THEN 'bank_account_id' END,
          CASE WHEN r.transaction_currency IS NULL THEN 'transaction_currency' END,
          CASE WHEN r.currency_code IS NULL THEN 'currency_code' END,
          CASE WHEN r.functional_currency IS NULL THEN 'functional_currency' END,
          CASE WHEN r.bank_account_currency IS NULL THEN 'bank_account_currency' END,
          CASE WHEN r.payment_currency IS NULL THEN 'payment_currency' END,
          CASE WHEN r.linked_currency='IDR' AND r.exchange_rate IS NULL THEN 'exchange_rate' END],NULL),
        jsonb_build_object('bank_account_id',r.bank_account_id,'transaction_currency',r.transaction_currency,
          'currency_code',r.currency_code,'functional_currency',r.functional_currency,
          'bank_account_currency',r.bank_account_currency,'payment_currency',r.payment_currency,'exchange_rate',r.exchange_rate),
        jsonb_build_object('bank_account_id',COALESCE(r.bank_account_id,r.linked_bank_id),
          'transaction_currency',COALESCE(r.transaction_currency,r.linked_currency),
          'currency_code',COALESCE(r.currency_code,r.linked_currency),'functional_currency',COALESCE(r.functional_currency,'IDR'),
          'bank_account_currency',COALESCE(r.bank_account_currency,r.linked_currency),
          'payment_currency',COALESCE(r.payment_currency,r.linked_currency),
          'exchange_rate',COALESCE(r.exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)),
        'Unique typed reconciliation link proves receipt bank and currency'
      WHERE r.bank_account_id IS NULL OR r.transaction_currency IS NULL OR r.currency_code IS NULL
         OR r.functional_currency IS NULL OR r.bank_account_currency IS NULL OR r.payment_currency IS NULL
         OR (r.linked_currency='IDR' AND r.exchange_rate IS NULL);
      UPDATE public.receipt_vouchers SET bank_account_id=COALESCE(bank_account_id,r.linked_bank_id),
        currency_code=COALESCE(currency_code,r.linked_currency),
        transaction_currency=COALESCE(transaction_currency,r.linked_currency),functional_currency=COALESCE(functional_currency,'IDR'),
        bank_account_currency=COALESCE(bank_account_currency,r.linked_currency),payment_currency=COALESCE(payment_currency,r.linked_currency),
        exchange_rate=COALESCE(exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)
      WHERE id=r.id;
      IF r.linked_currency='USD' AND r.exchange_rate IS NULL THEN
        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
        VALUES(v_run,'receipt',r.id,r.voucher_number,ARRAY['exchange_rate'],'USD receipt has no stored historical rate','Authoritative USD-to-IDR rate and rate source/date');
      END IF;
      IF (r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id)
         OR (r.transaction_currency IS NOT NULL AND upper(r.transaction_currency)<>r.linked_currency) THEN
        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
        VALUES(v_run,'receipt',r.id,r.voucher_number,
          ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id THEN 'bank_account_id' END,
            CASE WHEN r.transaction_currency IS NOT NULL AND upper(r.transaction_currency)<>r.linked_currency THEN 'transaction_currency' END],NULL),
          'Stored receipt metadata conflicts with its unique reconciliation bank line; neither side was overwritten',
          'Accountant confirmation of the correct receiving bank and transaction currency');
      END IF;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'receipt',r.id,r.voucher_number,ARRAY['bank_account_id','transaction_currency'],'Typed links do not prove one bank account','Correct receiving bank account and transaction currency');
    END IF;
  END LOOP;

  -- Payment voucher links now use the same typed-FK contract as every other
  -- Finance document. Existing payment amounts and rates are retained.
  FOR r IN
    SELECT pv.id,pv.voucher_number,pv.bank_account_id,pv.payment_method,pv.payment_currency,pv.transaction_currency,
      pv.currency_code,pv.functional_currency,pv.bank_account_currency,pv.exchange_rate,
      (array_agg(DISTINCT bsl.bank_account_id))[1] AS linked_bank_id,
      min(upper(COALESCE(bsl.currency,ba.currency))) AS linked_currency,
      count(DISTINCT bsl.bank_account_id) AS bank_count
    FROM public.payment_vouchers pv
    JOIN public.bank_statement_lines bsl ON bsl.matched_payment_id=pv.id
    LEFT JOIN public.bank_accounts ba ON ba.id=bsl.bank_account_id
    GROUP BY pv.id
  LOOP
    IF r.bank_count=1 AND r.linked_currency IN ('IDR','USD') THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      SELECT v_run,'payment',r.id,r.voucher_number,
        ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NULL THEN 'bank_account_id' END,
          CASE WHEN r.payment_currency IS NULL THEN 'payment_currency' END,
          CASE WHEN r.transaction_currency IS NULL THEN 'transaction_currency' END,
          CASE WHEN r.currency_code IS NULL THEN 'currency_code' END,
          CASE WHEN r.functional_currency IS NULL THEN 'functional_currency' END,
          CASE WHEN r.bank_account_currency IS NULL THEN 'bank_account_currency' END,
          CASE WHEN r.linked_currency='IDR' AND r.exchange_rate IS NULL THEN 'exchange_rate' END],NULL),
        jsonb_build_object('bank_account_id',r.bank_account_id,'payment_currency',r.payment_currency,
          'transaction_currency',r.transaction_currency,'currency_code',r.currency_code,
          'functional_currency',r.functional_currency,'bank_account_currency',r.bank_account_currency,'exchange_rate',r.exchange_rate),
        jsonb_build_object('bank_account_id',COALESCE(r.bank_account_id,r.linked_bank_id),
          'payment_currency',COALESCE(r.payment_currency,r.linked_currency),
          'transaction_currency',COALESCE(r.transaction_currency,r.linked_currency),
          'currency_code',COALESCE(r.currency_code,r.linked_currency),'functional_currency',COALESCE(r.functional_currency,'IDR'),
          'bank_account_currency',COALESCE(r.bank_account_currency,r.linked_currency),
          'exchange_rate',COALESCE(r.exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)),
        'Unique typed reconciliation link proves payment bank and currency'
      WHERE r.bank_account_id IS NULL OR r.payment_currency IS NULL OR r.transaction_currency IS NULL
         OR r.currency_code IS NULL OR r.functional_currency IS NULL OR r.bank_account_currency IS NULL
         OR (r.linked_currency='IDR' AND r.exchange_rate IS NULL);
      UPDATE public.payment_vouchers SET bank_account_id=COALESCE(bank_account_id,r.linked_bank_id),
        payment_currency=COALESCE(payment_currency,r.linked_currency),currency_code=COALESCE(currency_code,r.linked_currency),
        transaction_currency=COALESCE(transaction_currency,r.linked_currency),functional_currency=COALESCE(functional_currency,'IDR'),
        bank_account_currency=COALESCE(bank_account_currency,r.linked_currency),
        exchange_rate=COALESCE(exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)
      WHERE id=r.id;
      IF r.linked_currency='USD' AND r.exchange_rate IS NULL THEN
        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
        VALUES(v_run,'payment',r.id,r.voucher_number,ARRAY['exchange_rate'],'USD payment has no stored historical rate','Authoritative USD-to-IDR rate and rate source/date');
      END IF;
      IF (r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id)
         OR (r.payment_currency IS NOT NULL AND upper(r.payment_currency)<>r.linked_currency) THEN
        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
        VALUES(v_run,'payment',r.id,r.voucher_number,
          ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id THEN 'bank_account_id' END,
            CASE WHEN r.payment_currency IS NOT NULL AND upper(r.payment_currency)<>r.linked_currency THEN 'payment_currency' END],NULL),
          'Stored payment metadata conflicts with its unique reconciliation bank line; neither side was overwritten',
          'Accountant confirmation of the correct paying bank and payment currency');
      END IF;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'payment',r.id,r.voucher_number,ARRAY['bank_account_id','transaction_currency'],'Journal links do not prove one bank account','Correct paying bank account and transaction currency');
    END IF;
  END LOOP;

  -- Restore missing native document-to-journal links only when exactly one
  -- active JE identifies the document by source_module + reference_id.
  FOR r IN
    SELECT rv.id,rv.voucher_number,(array_agg(je.id ORDER BY je.created_at))[1] AS resolved_je,count(je.id) AS je_count
    FROM public.receipt_vouchers rv JOIN public.journal_entries je
      ON je.source_module='receipt' AND je.reference_id=rv.id AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false
    WHERE rv.journal_entry_id IS NULL GROUP BY rv.id
  LOOP
    IF r.je_count=1 THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      VALUES(v_run,'receipt',r.id,r.voucher_number,ARRAY['journal_entry_id'],jsonb_build_object('journal_entry_id',NULL),jsonb_build_object('journal_entry_id',r.resolved_je),'One active native receipt journal proves the missing link');
      UPDATE public.receipt_vouchers SET journal_entry_id=r.resolved_je WHERE id=r.id;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'receipt',r.id,r.voucher_number,ARRAY['journal_entry_id'],'More than one active receipt journal identifies this document','Accountant selection of the canonical active journal');
    END IF;
  END LOOP;

  FOR r IN
    SELECT pv.id,pv.voucher_number,(array_agg(je.id ORDER BY je.created_at))[1] AS resolved_je,count(je.id) AS je_count
    FROM public.payment_vouchers pv JOIN public.journal_entries je
      ON je.source_module='payment' AND je.reference_id=pv.id AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false
    WHERE pv.journal_entry_id IS NULL GROUP BY pv.id
  LOOP
    IF r.je_count=1 THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      VALUES(v_run,'payment',r.id,r.voucher_number,ARRAY['journal_entry_id'],jsonb_build_object('journal_entry_id',NULL),jsonb_build_object('journal_entry_id',r.resolved_je),'One active native payment journal proves the missing link');
      UPDATE public.payment_vouchers SET journal_entry_id=r.resolved_je WHERE id=r.id;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'payment',r.id,r.voucher_number,ARRAY['journal_entry_id'],'More than one active payment journal identifies this document','Accountant selection of the canonical active journal');
    END IF;
  END LOOP;

  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'receipt',rv.id,rv.voucher_number,ARRAY['journal_entry_id'],
    'Posted receipt has no uniquely identifiable active journal','Correct active Journal Entry or accountant-authorised reposting'
  FROM public.receipt_vouchers rv
  WHERE rv.is_posted=true AND rv.journal_entry_id IS NULL
    AND NOT EXISTS(SELECT 1 FROM public.journal_entries je WHERE je.source_module='receipt' AND je.reference_id=rv.id
      AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false);

  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'payment',pv.id,pv.voucher_number,ARRAY['journal_entry_id'],
    'Posted payment has no uniquely identifiable active journal','Correct active Journal Entry or accountant-authorised reposting'
  FROM public.payment_vouchers pv
  WHERE pv.is_posted=true AND pv.journal_entry_id IS NULL
    AND NOT EXISTS(SELECT 1 FROM public.journal_entries je WHERE je.source_module='payment' AND je.reference_id=pv.id
      AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false);

  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'expense',fe.id,fe.voucher_number,ARRAY['active journal'],
    CASE WHEN count(je.id)=0 THEN 'Approved expense has no active journal' ELSE 'Approved expense has more than one active journal' END,
    CASE WHEN count(je.id)=0 THEN 'Accountant-authorised posting through the native Expense workflow' ELSE 'Accountant selection/reversal of duplicate active journals' END
  FROM public.finance_expenses fe
  LEFT JOIN public.journal_entries je ON je.source_module='expenses'
    AND (je.reference_id=fe.id OR je.reference_number='EXP-'||fe.id::text)
    AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false
  WHERE fe.approval_status='approved'
  GROUP BY fe.id HAVING count(je.id)<>1;

  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'bank_reconciliation',b.id,b.reference,ARRAY['document link','journal link'],
    'Bank line is marked matched/recorded but has no document or Journal Entry link',
    'Correct source document or reset the line to Unmatched'
  FROM public.bank_statement_lines b
  WHERE b.reconciliation_status IN('matched','recorded') AND b.matched_entry_id IS NULL
    AND b.matched_expense_id IS NULL AND b.matched_receipt_id IS NULL AND b.matched_payment_id IS NULL
    AND b.matched_fund_transfer_id IS NULL AND b.matched_petty_cash_id IS NULL AND b.matched_tax_payment_id IS NULL;

  -- If a document already owns a journal but the reverse source ID is absent,
  -- the FK itself proves reference_id. Mismatches are exceptions, never fixed.
  FOR r IN
    SELECT je.id,je.entry_number,je.source_module,je.reference_id,rv.id AS source_id
    FROM public.receipt_vouchers rv JOIN public.journal_entries je ON je.id=rv.journal_entry_id
    WHERE (je.source_module IS NULL OR je.source_module='receipt')
      AND (je.source_module IS NULL OR je.reference_id IS NULL OR je.reference_id<>rv.id)
  LOOP
    IF (r.reference_id IS NULL OR r.reference_id=r.source_id) AND (r.source_module IS NULL OR r.source_module='receipt') THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      VALUES(v_run,'journal',r.id,r.entry_number,
        ARRAY_REMOVE(ARRAY[CASE WHEN r.source_module IS NULL THEN 'source_module' END,
          CASE WHEN r.reference_id IS NULL THEN 'reference_id' END],NULL),
        jsonb_build_object('source_module',r.source_module,'reference_id',r.reference_id),
        jsonb_build_object('source_module','receipt','reference_id',r.source_id),'Receipt journal_entry_id proves reverse source identity');
      UPDATE public.journal_entries SET source_module=COALESCE(source_module,'receipt'),reference_id=r.source_id WHERE id=r.id;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['reference_id'],'Journal source ID conflicts with owning receipt','Accountant confirmation of the correct source document');
    END IF;
  END LOOP;

  FOR r IN
    SELECT je.id,je.entry_number,je.source_module,je.reference_id,pv.id AS source_id
    FROM public.payment_vouchers pv JOIN public.journal_entries je ON je.id=pv.journal_entry_id
    WHERE (je.source_module IS NULL OR je.source_module='payment')
      AND (je.source_module IS NULL OR je.reference_id IS NULL OR je.reference_id<>pv.id)
  LOOP
    IF (r.reference_id IS NULL OR r.reference_id=r.source_id) AND (r.source_module IS NULL OR r.source_module='payment') THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      VALUES(v_run,'journal',r.id,r.entry_number,
        ARRAY_REMOVE(ARRAY[CASE WHEN r.source_module IS NULL THEN 'source_module' END,
          CASE WHEN r.reference_id IS NULL THEN 'reference_id' END],NULL),
        jsonb_build_object('source_module',r.source_module,'reference_id',r.reference_id),
        jsonb_build_object('source_module','payment','reference_id',r.source_id),'Payment journal_entry_id proves reverse source identity');
      UPDATE public.journal_entries SET source_module=COALESCE(source_module,'payment'),reference_id=r.source_id WHERE id=r.id;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['reference_id'],'Journal source ID conflicts with owning payment','Accountant confirmation of the correct source document');
    END IF;
  END LOOP;

  -- Director Loan correction is safe only when narration explicitly proves it.
  FOR r IN SELECT je.id,je.entry_number,jel.id AS line_id,jel.account_id
    FROM public.journal_entries je JOIN public.journal_entry_lines jel ON jel.journal_entry_id=je.id
    JOIN public.chart_of_accounts coa ON coa.id=jel.account_id
    WHERE je.source_module='bank_reconciliation' AND coa.code='2210' AND jel.credit>0
      AND lower(COALESCE(je.description,'')) ~ '(director|owner) loan' LOOP
    IF EXISTS(SELECT 1 FROM public.chart_of_accounts WHERE code='2220' AND is_active=true AND COALESCE(is_header,false)=false) THEN
      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
      SELECT v_run,'journal',r.id,r.entry_number,ARRAY['credit_account_id'],jsonb_build_object('account_id',r.account_id),jsonb_build_object('account_id',id),'Narration explicitly identifies Director/Owner Loan; native mapping is 2220'
      FROM public.chart_of_accounts WHERE code='2220' AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1;
      UPDATE public.journal_entry_lines SET account_id=(SELECT id FROM public.chart_of_accounts WHERE code='2220' AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1) WHERE id=r.line_id;
    ELSE
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['credit_account_id'],'Director/Owner Loan is certain but account 2220 is unavailable','Activate/create the approved posting account 2220');
    END IF;
  END LOOP;

  -- Explicit exceptions for unresolved metadata; never guess.
  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'expense',id,voucher_number,
    ARRAY_REMOVE(ARRAY[CASE WHEN transaction_currency IS NULL THEN 'transaction_currency' END,
      CASE WHEN functional_currency IS NULL THEN 'functional_currency' END,CASE WHEN currency_code IS NULL THEN 'currency_code' END,
      CASE WHEN exchange_rate IS NULL THEN 'exchange_rate' END,CASE WHEN payment_method IS NULL THEN 'payment_method' END,
      CASE WHEN bank_account_id IS NULL AND payment_method='bank_transfer' THEN 'bank_account_id' END],NULL),
    'No unique authoritative relationship exists in stored data','Transaction currency, historical exchange rate with source/date, exact payment method, and/or paying bank account'
  FROM public.finance_expenses
  WHERE transaction_currency IS NULL OR functional_currency IS NULL OR currency_code IS NULL OR exchange_rate IS NULL
     OR payment_method IS NULL OR (bank_account_id IS NULL AND payment_method='bank_transfer');

  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'receipt',id,voucher_number,
    ARRAY_REMOVE(ARRAY[CASE WHEN transaction_currency IS NULL THEN 'transaction_currency' END,
      CASE WHEN functional_currency IS NULL THEN 'functional_currency' END,CASE WHEN currency_code IS NULL THEN 'currency_code' END,
      CASE WHEN exchange_rate IS NULL THEN 'exchange_rate' END,
      CASE WHEN payment_method IS NULL THEN 'payment_method' END,
      CASE WHEN bank_account_id IS NULL AND payment_method='bank_transfer' THEN 'bank_account_id' END],NULL),
    'No unique authoritative relationship exists in stored receipt data',
    'Transaction currency, historical rate with source/date, exact payment method, and/or receiving bank account'
  FROM public.receipt_vouchers
  WHERE transaction_currency IS NULL OR functional_currency IS NULL OR currency_code IS NULL OR exchange_rate IS NULL
     OR payment_method IS NULL OR (bank_account_id IS NULL AND payment_method='bank_transfer');

  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'payment',id,voucher_number,
    ARRAY_REMOVE(ARRAY[CASE WHEN transaction_currency IS NULL THEN 'transaction_currency' END,
      CASE WHEN functional_currency IS NULL THEN 'functional_currency' END,CASE WHEN currency_code IS NULL THEN 'currency_code' END,
      CASE WHEN exchange_rate IS NULL THEN 'exchange_rate' END,
      CASE WHEN payment_method IS NULL THEN 'payment_method' END,
      CASE WHEN bank_account_id IS NULL AND payment_method='bank_transfer' THEN 'bank_account_id' END],NULL),
    'No unique authoritative relationship exists in stored payment data',
    'Transaction currency, historical rate with source/date, exact payment method, and/or paying bank account'
  FROM public.payment_vouchers
  WHERE transaction_currency IS NULL OR functional_currency IS NULL OR currency_code IS NULL OR exchange_rate IS NULL
     OR payment_method IS NULL OR (bank_account_id IS NULL AND payment_method='bank_transfer');

  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
  SELECT v_run,'journal',id,entry_number,
    ARRAY_REMOVE(ARRAY[CASE WHEN source_module IS NULL THEN 'source_module' END,
      CASE WHEN source_module='bank_reconciliation' AND transaction_currency IS NULL THEN 'transaction_currency' END,
      CASE WHEN source_module='bank_reconciliation' AND transaction_currency='USD' AND exchange_rate IS NULL THEN 'exchange_rate' END],NULL),
    'Journal metadata cannot be derived from a unique stored source relationship',
    'Correct source module/document and/or authoritative historical currency rate'
  FROM public.journal_entries
  WHERE source_module IS NULL OR (source_module='bank_reconciliation' AND (transaction_currency IS NULL OR (transaction_currency='USD' AND exchange_rate IS NULL)));

  -- Classify every remaining scanned row as an explicit, reasoned skip so the
  -- run totals reconcile exactly to the scan population.
  INSERT INTO public.finance_historical_repair_exceptions(
    run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required,status)
  SELECT v_run,c.document_type,c.document_id,c.document_number,ARRAY[]::text[],
    'No missing or inconsistent deterministic metadata was found','None','skipped'
  FROM (
    SELECT 'expense'::text document_type,id document_id,voucher_number::text document_number FROM public.finance_expenses
    UNION ALL SELECT 'receipt',id,voucher_number::text FROM public.receipt_vouchers
    UNION ALL SELECT 'payment',id,voucher_number::text FROM public.payment_vouchers
    UNION ALL SELECT 'fund_transfer',id,transfer_number::text FROM public.fund_transfers
    UNION ALL SELECT 'journal',id,entry_number::text FROM public.journal_entries
    UNION ALL SELECT 'bank_reconciliation',id,reference::text FROM public.bank_statement_lines
  ) c
  WHERE NOT EXISTS(SELECT 1 FROM public.finance_historical_repair_items i
    WHERE i.run_id=v_run AND i.document_type=c.document_type AND i.document_id=c.document_id)
    AND NOT EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e
    WHERE e.run_id=v_run AND e.document_type=c.document_type AND e.document_id=c.document_id);

  UPDATE public.finance_historical_repair_runs SET completed_at=now(),total_records_scanned=v_scanned,
    records_repaired=(SELECT count(DISTINCT (i.document_type,i.document_id))
      FROM public.finance_historical_repair_items i WHERE i.run_id=v_run
        AND NOT EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e
          WHERE e.run_id=v_run AND e.status='manual_review' AND e.document_type=i.document_type AND e.document_id=i.document_id)),
    records_partially_repaired=(SELECT count(DISTINCT (i.document_type,i.document_id))
      FROM public.finance_historical_repair_items i WHERE i.run_id=v_run
        AND EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e
          WHERE e.run_id=v_run AND e.status='manual_review' AND e.document_type=i.document_type AND e.document_id=i.document_id)),
    records_manual_review=(SELECT count(DISTINCT (document_type,document_id)) FROM public.finance_historical_repair_exceptions WHERE run_id=v_run AND status='manual_review'),
    records_skipped=(SELECT count(DISTINCT (document_type,document_id)) FROM public.finance_historical_repair_exceptions WHERE run_id=v_run AND status='skipped')
  WHERE id=v_run;
  RETURN v_run;
END;
$$;


--
-- Name: safe_delete_bank_statement_lines("uuid", "date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."safe_delete_bank_statement_lines"("p_bank_account_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_total_count      INTEGER;
v_reconciled_count INTEGER;
v_deletable_count  INTEGER;
v_deleted_count    INTEGER;
v_role             text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot delete bank statement lines', v_role;
END IF;

SELECT COUNT(*) INTO v_total_count FROM bank_statement_lines
WHERE bank_account_id = p_bank_account_id
AND transaction_date BETWEEN p_start_date AND p_end_date;

SELECT COUNT(*) INTO v_reconciled_count FROM bank_statement_lines
WHERE bank_account_id = p_bank_account_id
AND transaction_date BETWEEN p_start_date AND p_end_date
AND reconciliation_status IN ('matched','recorded','suggested');

v_deletable_count := v_total_count - v_reconciled_count;

IF v_reconciled_count > 0 THEN
RETURN json_build_object(
'success', false,
'error', 'Cannot delete: ' || v_reconciled_count || ' transaction(s) are reconciled',
'total_count', v_total_count, 'reconciled_count', v_reconciled_count,
'deletable_count', v_deletable_count, 'deleted_count', 0
);
END IF;

DELETE FROM bank_statement_lines
WHERE bank_account_id = p_bank_account_id
AND transaction_date BETWEEN p_start_date AND p_end_date
AND reconciliation_status = 'unmatched';
GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

RETURN json_build_object(
'success', true, 'total_count', v_total_count, 'reconciled_count', v_reconciled_count,
'deletable_count', v_deletable_count, 'deleted_count', v_deleted_count
);
END;
$$;


--
-- Name: save_and_link_finance_expense_atomic("uuid", "jsonb", "uuid", numeric, "uuid", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_and_link_finance_expense_atomic"("p_expense_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_bank_statement_line_id" "uuid" DEFAULT NULL::"uuid", "p_allocation_amount" numeric DEFAULT NULL::numeric, "p_approved_by" "uuid" DEFAULT NULL::"uuid", "p_apply_salary_advances" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_expense_id uuid;
  v_journal_id uuid;
  v_journal_count integer;
  v_allocation_count integer;
BEGIN
  PERFORM public._sec_check_finance_role();

  IF p_bank_statement_line_id IS NULL THEN
    RAISE EXCEPTION 'A bank statement line is required for atomic expense linking';
  END IF;

  -- Serialize concurrent attempts against both the source document and bank
  -- line before any document or accounting write is made.
  PERFORM 1
    FROM public.bank_statement_lines
   WHERE id = p_bank_statement_line_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line not found'; END IF;

  IF p_expense_id IS NOT NULL THEN
    PERFORM 1 FROM public.finance_expenses WHERE id = p_expense_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;
    IF EXISTS (
      SELECT 1 FROM public.finance_expenses
       WHERE id = p_expense_id AND approval_status = 'approved'
    ) THEN
      RAISE EXCEPTION 'Approved expenses must use the canonical approved-edit command';
    END IF;
  END IF;

  -- Existing document command: a new/unlinked expense remains pending until
  -- the approval call below. Any later failure rolls this insert/update back.
  -- The selected statement makes this a controlled bank-linked save.
  PERFORM set_config('app.expense_atomic_bank_link','on',true);
  v_expense_id := public.save_finance_expense(p_expense_id, p_payload);

  IF p_apply_salary_advances THEN
    PERFORM public.apply_salary_advances_to_expense(v_expense_id, true);
  END IF;

  -- Existing approval command invokes the one canonical expense journal
  -- builder through trigger_auto_post_expense_accounting.
  PERFORM public.approve_finance_expense(
    v_expense_id,
    COALESCE(p_approved_by, auth.uid())
  );

  SELECT count(*), (array_agg(id ORDER BY created_at DESC, id DESC))[1]
    INTO v_journal_count, v_journal_id
    FROM public.journal_entries
   WHERE source_module IN ('expense', 'expenses')
     AND (
       reference_id = v_expense_id
       OR reference_number = 'EXP-' || v_expense_id::text
     )
     AND is_posted = true
     AND NOT COALESCE(is_reversed, false);
  IF v_journal_count <> 1 THEN
    RAISE EXCEPTION 'Expense bank link requires exactly one active effective journal';
  END IF;

  -- Existing canonical link command validates bank account, currency, amount,
  -- journal bank side, split-allocation capacity, and duplicate allocation.
  PERFORM public.link_bank_statement_line(
    p_bank_statement_line_id,
    'expense',
    v_expense_id,
    'supplier',
    p_allocation_amount
  );

  SELECT count(*) INTO v_allocation_count
    FROM public.bank_statement_allocations
   WHERE bank_statement_line_id = p_bank_statement_line_id
     AND document_type = 'expense'
     AND document_id = v_expense_id
     AND payment_kind = 'supplier'
     AND journal_entry_id = v_journal_id;
  IF v_allocation_count <> 1 THEN
    RAISE EXCEPTION 'Expense bank link did not preserve exactly one canonical allocation';
  END IF;

  PERFORM public.recalculate_expense_payment_state(v_expense_id);
  RETURN v_expense_id;
END;
$$;


--
-- Name: save_bank_linked_finance_journal("uuid", "text", "text", "text", "text", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_bank_linked_finance_journal"("p_bank_line_id" "uuid", "p_description" "text", "p_counter_account_code" "text", "p_bank_side" "text", "p_transaction_currency" "text", "p_exchange_rate" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_line public.bank_statement_lines%ROWTYPE; v_bank_coa uuid; v_counter_coa uuid;
  v_amount numeric; v_journal uuid; v_lines jsonb; v_result jsonb;
BEGIN
  PERFORM public._sec_check_finance_role();
  SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=p_bank_line_id FOR UPDATE;
  IF NOT FOUND OR v_line.matched_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Bank statement line is missing or already linked'; END IF;
  SELECT coa_id INTO v_bank_coa FROM public.bank_accounts WHERE id=v_line.bank_account_id AND is_active=true AND upper(currency)=upper(p_transaction_currency);
  SELECT id INTO v_counter_coa FROM public.chart_of_accounts WHERE code=p_counter_account_code AND is_active=true AND COALESCE(is_header,false)=false;
  IF v_bank_coa IS NULL OR v_counter_coa IS NULL THEN RAISE EXCEPTION 'Bank or counter account is not configured'; END IF;
  IF p_bank_side='debit' THEN v_amount:=COALESCE(v_line.credit_amount,0);
  ELSIF p_bank_side='credit' THEN v_amount:=COALESCE(v_line.debit_amount,0);
  ELSE RAISE EXCEPTION 'Bank side must be debit or credit'; END IF;
  IF v_amount<=0 THEN RAISE EXCEPTION 'Bank statement direction does not match this journal action'; END IF;
  v_lines:=CASE WHEN p_bank_side='debit' THEN jsonb_build_array(
      jsonb_build_object('account_id',v_bank_coa,'description',p_description,'debit',v_amount,'credit',0),
      jsonb_build_object('account_id',v_counter_coa,'description',p_description,'debit',0,'credit',v_amount))
    ELSE jsonb_build_array(
      jsonb_build_object('account_id',v_counter_coa,'description',p_description,'debit',v_amount,'credit',0),
      jsonb_build_object('account_id',v_bank_coa,'description',p_description,'debit',0,'credit',v_amount)) END;
  v_journal:=public.save_finance_journal(NULL,v_line.transaction_date,p_description,v_lines,upper(p_transaction_currency),p_exchange_rate);
  v_result:=public.link_bank_statement_line(p_bank_line_id,'journal',v_journal,'supplier');
  RETURN jsonb_build_object('document_id',v_journal,'journal_entry_id',v_journal,'link',v_result);
END $$;


--
-- Name: save_batch_inventory_v1("uuid", "jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_batch_inventory_v1"("p_batch_id" "uuid", "p_payload" "jsonb", "p_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch public.batches%ROWTYPE;
  v_existing_batch_id uuid;
  v_actor uuid := auth.uid();
  v_delta numeric;
  v_previous_context text;
  v_unit_price numeric;
  v_is_local boolean;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse', 'manager']) THEN
    RAISE EXCEPTION 'Permission denied for canonical batch save';
  END IF;
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'operation_id is required';
  END IF;
  IF p_batch_id IS NULL AND NULLIF(p_payload->>'make_id', '') IS NULL THEN
    RAISE EXCEPTION 'Make / Manufacturer is required for new inventory batches';
  END IF;
  IF NULLIF(p_payload->>'make_id', '') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.product_sources
        WHERE id = (p_payload->>'make_id')::uuid
          AND product_id = (p_payload->>'product_id')::uuid
     ) THEN
    RAISE EXCEPTION 'Selected Make / Manufacturer does not belong to the selected product';
  END IF;

  v_unit_price := COALESCE((p_payload->>'import_price')::numeric, 0);
  v_is_local := NULLIF(p_payload->>'import_container_id', '') IS NULL;

  IF p_batch_id IS NULL THEN
    SELECT batch_id INTO v_existing_batch_id
      FROM public.inventory_transactions
     WHERE operation_id = p_operation_id AND transaction_type = 'purchase';
    IF FOUND THEN
      RETURN jsonb_build_object('success', true, 'batch_id', v_existing_batch_id, 'idempotent_retry', true);
    END IF;

    v_previous_context := current_setting('app.canonical_stock_engine', true);
    PERFORM set_config('app.canonical_stock_engine', 'on', true);
    INSERT INTO public.batches (
      batch_number, product_id, make_id, import_container_id, import_date,
      import_quantity, current_stock, packaging_details, import_price,
      import_price_usd, exchange_rate_usd_to_idr, duty_percent, duty_charges,
      duty_charge_type, freight_charges, freight_charge_type, other_charges,
      other_charge_type, expiry_date, is_active, created_by,
      cost_per_unit, landed_cost_per_unit, final_landed_cost, import_price_per_unit
    ) VALUES (
      p_payload->>'batch_number', (p_payload->>'product_id')::uuid,
      NULLIF(p_payload->>'make_id', '')::uuid,
      NULLIF(p_payload->>'import_container_id', '')::uuid,
      (p_payload->>'import_date')::date, (p_payload->>'import_quantity')::numeric,
      0, NULLIF(p_payload->>'packaging_details', ''),
      v_unit_price,
      NULLIF(p_payload->>'import_price_usd', '')::numeric,
      NULLIF(p_payload->>'exchange_rate_usd_to_idr', '')::numeric,
      COALESCE(NULLIF(p_payload->>'duty_percent', '')::numeric, 0),
      COALESCE(NULLIF(p_payload->>'duty_charges', '')::numeric, 0),
      COALESCE(NULLIF(p_payload->>'duty_charge_type', ''), 'fixed'),
      COALESCE(NULLIF(p_payload->>'freight_charges', '')::numeric, 0),
      COALESCE(NULLIF(p_payload->>'freight_charge_type', ''), 'fixed'),
      COALESCE(NULLIF(p_payload->>'other_charges', '')::numeric, 0),
      COALESCE(NULLIF(p_payload->>'other_charge_type', ''), 'fixed'),
      NULLIF(p_payload->>'expiry_date', '')::date, true, v_actor,
      v_unit_price,
      CASE WHEN v_is_local THEN v_unit_price ELSE 0 END,
      CASE WHEN v_is_local THEN v_unit_price * (p_payload->>'import_quantity')::numeric ELSE 0 END,
      v_unit_price
    ) RETURNING * INTO v_batch;
    PERFORM set_config('app.canonical_stock_engine', COALESCE(v_previous_context, ''), true);
    PERFORM public.post_inventory_movement(
      p_operation_id, v_batch.product_id, v_batch.id, 'purchase',
      v_batch.import_quantity, v_batch.import_date, v_batch.batch_number,
      'batch_creation', v_batch.id, 'Canonical Batch Creation: ' || v_batch.batch_number,
      v_actor, 0, v_batch.import_quantity
    );
    RETURN jsonb_build_object('success', true, 'batch_id', v_batch.id);
  END IF;

  SELECT * INTO v_batch FROM public.batches WHERE id = p_batch_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Batch not found'; END IF;
  IF (p_payload->>'product_id')::uuid IS DISTINCT FROM v_batch.product_id
     AND EXISTS (SELECT 1 FROM public.inventory_transactions WHERE batch_id = p_batch_id AND transaction_type <> 'purchase') THEN
    RAISE EXCEPTION 'Cannot change product after batch stock movement exists';
  END IF;

  v_delta := (p_payload->>'import_quantity')::numeric - v_batch.import_quantity;
  UPDATE public.batches SET
    batch_number = p_payload->>'batch_number', product_id = (p_payload->>'product_id')::uuid,
    make_id = NULLIF(p_payload->>'make_id', '')::uuid,
    import_container_id = NULLIF(p_payload->>'import_container_id', '')::uuid,
    import_date = (p_payload->>'import_date')::date, import_quantity = (p_payload->>'import_quantity')::numeric,
    packaging_details = NULLIF(p_payload->>'packaging_details', ''),
    import_price = COALESCE((p_payload->>'import_price')::numeric, import_price),
    import_price_usd = NULLIF(p_payload->>'import_price_usd', '')::numeric,
    exchange_rate_usd_to_idr = NULLIF(p_payload->>'exchange_rate_usd_to_idr', '')::numeric,
    duty_percent = COALESCE(NULLIF(p_payload->>'duty_percent', '')::numeric, 0),
    duty_charges = COALESCE(NULLIF(p_payload->>'duty_charges', '')::numeric, 0),
    duty_charge_type = COALESCE(NULLIF(p_payload->>'duty_charge_type', ''), duty_charge_type),
    freight_charges = COALESCE(NULLIF(p_payload->>'freight_charges', '')::numeric, 0),
    freight_charge_type = COALESCE(NULLIF(p_payload->>'freight_charge_type', ''), freight_charge_type),
    other_charges = COALESCE(NULLIF(p_payload->>'other_charges', '')::numeric, 0),
    other_charge_type = COALESCE(NULLIF(p_payload->>'other_charge_type', ''), other_charge_type),
    expiry_date = NULLIF(p_payload->>'expiry_date', '')::date,
    cost_per_unit = CASE
      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL
        THEN COALESCE((p_payload->>'import_price')::numeric, import_price)
      ELSE cost_per_unit
    END,
    landed_cost_per_unit = CASE
      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL
        THEN COALESCE((p_payload->>'import_price')::numeric, import_price)
      ELSE landed_cost_per_unit
    END,
    final_landed_cost = CASE
      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL
        THEN COALESCE((p_payload->>'import_price')::numeric, import_price) * (p_payload->>'import_quantity')::numeric
      ELSE final_landed_cost
    END,
    import_price_per_unit = COALESCE((p_payload->>'import_price')::numeric, import_price),
    updated_at = now()
  WHERE id = p_batch_id;

  IF v_delta <> 0 THEN
    PERFORM public.post_inventory_movement(
      p_operation_id, (p_payload->>'product_id')::uuid, p_batch_id, 'adjustment',
      v_delta, CURRENT_DATE, p_payload->>'batch_number', 'batch_edit', p_batch_id,
      format('Canonical Batch Edit quantity correction: %s to %s', v_batch.import_quantity, (p_payload->>'import_quantity')::numeric),
      v_actor, v_batch.current_stock, v_batch.current_stock + v_delta
    );
  END IF;
  RETURN jsonb_build_object('success', true, 'batch_id', p_batch_id);
END;
$$;


--
-- Name: save_finance_capital_contribution("jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_finance_capital_contribution"("p_payload" "jsonb", "p_bank_statement_line_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid:=gen_random_uuid(); v_number text; v_je uuid; v_line public.bank_statement_lines%ROWTYPE; v_amount numeric; v_date date;
BEGIN
  PERFORM public._sec_check_finance_role();
  v_date:=(p_payload->>'voucher_date')::date; v_amount:=(p_payload->>'amount')::numeric;
  IF v_amount<=0 THEN RAISE EXCEPTION 'Capital contribution amount must be positive'; END IF;
  IF p_bank_statement_line_id IS NOT NULL THEN
    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id FOR UPDATE;
    IF NOT FOUND OR COALESCE(v_line.credit_amount,0)<>v_amount OR v_line.bank_account_id<>(p_payload->>'bank_account_id')::uuid THEN RAISE EXCEPTION 'Bank statement line does not exactly match this capital contribution'; END IF;
    IF v_line.matched_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Bank statement line is already linked'; END IF;
  END IF;
  v_number:=public.next_capital_contribution_number(v_date);
  INSERT INTO public.capital_contributions(id,voucher_number,voucher_date,director_id,contribution_type,bank_account_id,amount,description,created_by,
    transaction_currency,functional_currency,exchange_rate,bank_account_currency,bank_statement_line_id)
  VALUES(v_id,v_number,v_date,NULL,'bank_transfer',(p_payload->>'bank_account_id')::uuid,v_amount,COALESCE(p_payload->>'description',''),
    COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),upper(p_payload->>'transaction_currency'),'IDR',(p_payload->>'exchange_rate')::numeric,
    upper(p_payload->>'transaction_currency'),p_bank_statement_line_id) RETURNING journal_entry_id INTO v_je;
  IF p_bank_statement_line_id IS NOT NULL THEN PERFORM public._link_native_bank_document(p_bank_statement_line_id,v_je,'Capital Contribution - '||v_number); END IF;
  RETURN jsonb_build_object('id',v_id,'voucher_number',v_number,'journal_entry_id',v_je);
END $$;


--
-- Name: save_finance_exception_corrections("jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_finance_exception_corrections"("p_corrections" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  c jsonb;
  v_document_type text;
  v_document_id uuid;
  v_exception_id bigint;
  v_reason text;
  v_journal_id uuid;
  v_line_id uuid;
  v_account_id uuid;
  v_bank_id uuid;
  v_bank_coa_id uuid;
  v_bank_currency text;
  v_tax_code_id uuid;
  v_tax_type text;
  v_exchange_rate numeric;
  v_before_lines jsonb;
  v_after_lines jsonb;
  v_resolved boolean := false;
  v_saved integer := 0;
  v_resolved_count integer := 0;
BEGIN
  PERFORM public._sec_check_finance_role();
  IF jsonb_typeof(p_corrections) <> 'array' OR jsonb_array_length(p_corrections)=0 THEN
    RAISE EXCEPTION 'Select at least one correction before saving';
  END IF;

  -- Existing source triggers read these flags. Metadata corrections must never
  -- regenerate journals or recalculate historical debit/credit values.
  PERFORM set_config('app.finance_historical_repair','on',true);
  PERFORM set_config('app.finance_metadata_repair','on',true);

  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections)
  LOOP
    v_document_type := c->>'document_type';
    v_document_id := (c->>'document_id')::uuid;
    v_exception_id := NULLIF(c->>'exception_id','')::bigint;
    v_line_id := NULLIF(c->>'journal_line_id','')::uuid;
    v_bank_id := NULLIF(c->>'bank_account_id','')::uuid;
    v_tax_code_id := NULLIF(c->>'tax_code_id','')::uuid;
    v_exchange_rate := NULLIF(c->>'exchange_rate','')::numeric;
    v_resolved := false;

    IF v_exception_id IS NOT NULL THEN
      SELECT reason INTO v_reason
      FROM public.finance_historical_repair_exceptions
      WHERE id=v_exception_id AND document_type=v_document_type
        AND document_id=v_document_id AND status='manual_review'
      FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'This exception is no longer open'; END IF;
    ELSE
      v_reason := 'Live Finance verification failure';
      IF NOT EXISTS (
        SELECT 1 FROM public.finance_exception_correction_dashboard d
        WHERE d.document_type=v_document_type AND d.document_id=v_document_id
          AND d.status='Verification failed'
      ) THEN RAISE EXCEPTION 'This verification failure is no longer open'; END IF;
    END IF;

    SELECT CASE v_document_type
      WHEN 'journal' THEN v_document_id
      WHEN 'receipt' THEN (SELECT journal_entry_id FROM public.receipt_vouchers WHERE id=v_document_id)
      WHEN 'payment' THEN (SELECT journal_entry_id FROM public.payment_vouchers WHERE id=v_document_id)
      WHEN 'fund_transfer' THEN (SELECT journal_entry_id FROM public.fund_transfers WHERE id=v_document_id)
      WHEN 'loan' THEN (SELECT journal_entry_id FROM public.loans WHERE id=v_document_id)
      WHEN 'loan_transaction' THEN (SELECT journal_entry_id FROM public.loan_transactions WHERE id=v_document_id)
      WHEN 'loan_repayment' THEN (SELECT journal_entry_id FROM public.loan_transactions WHERE id=v_document_id)
      WHEN 'capital_contribution' THEN (SELECT journal_entry_id FROM public.capital_contributions WHERE id=v_document_id)
      WHEN 'tax_payment' THEN (SELECT journal_entry_id FROM public.tax_payments WHERE id=v_document_id)
      WHEN 'sales_invoice' THEN (SELECT journal_entry_id FROM public.sales_invoices WHERE id=v_document_id)
      WHEN 'purchase_invoice' THEN (SELECT journal_entry_id FROM public.purchase_invoices WHERE id=v_document_id)
      WHEN 'bank_reconciliation' THEN (SELECT matched_entry_id FROM public.bank_statement_lines WHERE id=v_document_id)
      WHEN 'expense' THEN (SELECT id FROM public.journal_entries j WHERE j.source_module IN('expense','expenses')
        AND (j.reference_id=v_document_id OR j.reference_number='EXP-'||v_document_id::text)
        AND COALESCE(j.is_reversed,false)=false ORDER BY j.is_posted DESC,j.created_at DESC LIMIT 1)
      WHEN 'petty_cash' THEN (SELECT id FROM public.journal_entries j WHERE j.source_module='petty_cash'
        AND j.reference_id=v_document_id AND COALESCE(j.is_reversed,false)=false ORDER BY j.is_posted DESC,j.created_at DESC LIMIT 1)
    END INTO v_journal_id;

    IF v_journal_id IS NOT NULL THEN
      SELECT jsonb_agg(jsonb_build_object('id',id,'debit',debit,'credit',credit) ORDER BY id)
      INTO v_before_lines FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;
    END IF;

    IF v_bank_id IS NOT NULL THEN
      SELECT ba.coa_id,upper(ba.currency) INTO v_bank_coa_id,v_bank_currency
      FROM public.bank_accounts ba JOIN public.chart_of_accounts coa ON coa.id=ba.coa_id
      WHERE ba.id=v_bank_id AND ba.is_active=true AND coa.is_active=true AND COALESCE(coa.is_header,false)=false;
      IF v_bank_coa_id IS NULL THEN RAISE EXCEPTION 'Selected bank has no active posting account'; END IF;
    END IF;

    v_account_id := COALESCE(NULLIF(c->>'account_id','')::uuid,
      NULLIF(c->>'loan_account_id','')::uuid,
      NULLIF(c->>'capital_account_id','')::uuid,
      CASE WHEN v_bank_id IS NOT NULL THEN v_bank_coa_id END);
    IF v_account_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.chart_of_accounts WHERE id=v_account_id AND is_active=true AND COALESCE(is_header,false)=false
    ) THEN RAISE EXCEPTION 'Selected account is not an active posting account'; END IF;

    IF v_tax_code_id IS NOT NULL THEN
      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id AND is_active=true;
      IF v_tax_type IS NULL THEN RAISE EXCEPTION 'Selected tax category is not active'; END IF;
    END IF;

    -- Source metadata. Every assignment is to an existing row; no insert,
    -- delete, posting, numbering, date, narration, or amount field is allowed.
    IF v_document_type='expense' THEN
      UPDATE public.finance_expenses SET
        expense_category=COALESCE(NULLIF(c->>'expense_category',''),expense_category),
        payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),
        bank_account_id=COALESCE(v_bank_id,bank_account_id),
        pph_code_id=COALESCE(v_tax_code_id,pph_code_id),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),
        currency_code=COALESCE(v_bank_currency,currency_code),
        payment_currency=COALESCE(v_bank_currency,payment_currency),
        bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),
        functional_currency=COALESCE(functional_currency,'IDR')
      WHERE id=v_document_id;
    ELSIF v_document_type='receipt' THEN
      UPDATE public.receipt_vouchers SET payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),
        bank_account_id=COALESCE(v_bank_id,bank_account_id),exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency_code=COALESCE(v_bank_currency,currency_code),
        payment_currency=COALESCE(v_bank_currency,payment_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),
        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;
    ELSIF v_document_type='payment' THEN
      UPDATE public.payment_vouchers SET payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),
        bank_account_id=COALESCE(v_bank_id,bank_account_id),pph_code_id=COALESCE(v_tax_code_id,pph_code_id),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency_code=COALESCE(v_bank_currency,currency_code),
        payment_currency=COALESCE(v_bank_currency,payment_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),
        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;
    ELSIF v_document_type='loan' THEN
      UPDATE public.loans SET bank_account_id=COALESCE(v_bank_id,bank_account_id),
        coa_id=COALESCE(NULLIF(c->>'loan_account_id','')::uuid,coa_id),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency=COALESCE(v_bank_currency,currency),
        bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),functional_currency=COALESCE(functional_currency,'IDR')
      WHERE id=v_document_id;
    ELSIF v_document_type IN ('loan_transaction','loan_repayment') THEN
      UPDATE public.loan_transactions SET bank_account_id=COALESCE(v_bank_id,bank_account_id),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),
        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;
    ELSIF v_document_type='capital_contribution' THEN
      UPDATE public.capital_contributions SET bank_account_id=COALESCE(v_bank_id,bank_account_id),
        contribution_type=COALESCE(NULLIF(c->>'expense_category',''),contribution_type),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),
        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;
    ELSIF v_document_type='petty_cash' THEN
      UPDATE public.petty_cash_transactions SET expense_category=COALESCE(NULLIF(c->>'expense_category',''),expense_category),
        bank_account_id=COALESCE(v_bank_id,bank_account_id) WHERE id=v_document_id;
    ELSIF v_document_type='tax_payment' THEN
      UPDATE public.tax_payments SET bank_account_id=COALESCE(v_bank_id,bank_account_id),
        tax_type=COALESCE(v_tax_type,tax_type) WHERE id=v_document_id;
    ELSIF v_document_type='sales_invoice' AND NULLIF(c->>'faktur_pajak_number','') IS NOT NULL THEN
      UPDATE public.sales_invoices SET faktur_pajak_number=c->>'faktur_pajak_number' WHERE id=v_document_id;
    ELSIF v_document_type='purchase_invoice' AND NULLIF(c->>'faktur_pajak_number','') IS NOT NULL THEN
      UPDATE public.purchase_invoices SET faktur_pajak_number=c->>'faktur_pajak_number' WHERE id=v_document_id;
    ELSIF v_document_type='bank_reconciliation' AND NULLIF(c->>'payment_type','') IS NOT NULL THEN
      UPDATE public.bank_statement_lines SET payment_kind=c->>'payment_type' WHERE id=v_document_id;
    END IF;

    IF v_journal_id IS NOT NULL THEN
      UPDATE public.journal_entries SET
        source_module=COALESCE(NULLIF(c->>'document_classification',''),source_module),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),
        functional_currency=COALESCE(functional_currency,'IDR'),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        amounts_are_functional=COALESCE(amounts_are_functional,true)
      WHERE id=v_journal_id;
    END IF;

    IF v_account_id IS NOT NULL THEN
      IF v_line_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.journal_entry_lines WHERE id=v_line_id AND journal_entry_id=v_journal_id
      ) THEN RAISE EXCEPTION 'The account line can no longer be identified safely'; END IF;
      UPDATE public.journal_entry_lines SET account_id=v_account_id WHERE id=v_line_id;
    END IF;

    IF v_journal_id IS NOT NULL THEN
      SELECT jsonb_agg(jsonb_build_object('id',id,'debit',debit,'credit',credit) ORDER BY id)
      INTO v_after_lines FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;
      IF v_before_lines IS DISTINCT FROM v_after_lines THEN
        RAISE EXCEPTION 'Correction cancelled because a debit or credit value changed';
      END IF;
    END IF;

    -- Resolve only when the specific historical problem is now disproved.
    IF v_reason ILIKE '%missing Faktur Pajak%' THEN
      v_resolved := EXISTS(SELECT 1 FROM public.sales_invoices WHERE id=v_document_id AND NULLIF(btrim(faktur_pajak_number),'') IS NOT NULL)
        OR EXISTS(SELECT 1 FROM public.purchase_invoices WHERE id=v_document_id AND NULLIF(btrim(faktur_pajak_number),'') IS NOT NULL);
    ELSIF v_reason ILIKE '%no historical transaction-date rate%' OR v_reason ILIKE '%no authoritative historical rate%' THEN
      v_resolved := v_exchange_rate IS NOT NULL AND v_exchange_rate>0;
    ELSIF v_reason ILIKE '%does not use the Expense bank account%' OR v_reason ILIKE '%does not post to this bank account%' THEN
      v_resolved := EXISTS(SELECT 1 FROM public.journal_entry_lines jl JOIN public.bank_accounts ba ON ba.coa_id=jl.account_id
        WHERE jl.journal_entry_id=v_journal_id AND ba.id=COALESCE(v_bank_id,(SELECT bank_account_id FROM public.bank_statement_lines WHERE id=v_document_id)));
    ELSIF v_reason ILIKE 'No unique authoritative relationship%' THEN
      IF v_document_type='expense' THEN v_resolved := EXISTS(SELECT 1 FROM public.finance_expenses x WHERE x.id=v_document_id
        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL
        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL));
      ELSIF v_document_type='receipt' THEN v_resolved := EXISTS(SELECT 1 FROM public.receipt_vouchers x WHERE x.id=v_document_id
        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL
        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL));
      ELSIF v_document_type='payment' THEN v_resolved := EXISTS(SELECT 1 FROM public.payment_vouchers x WHERE x.id=v_document_id
        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL
        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL)); END IF;
    ELSIF v_reason ILIKE '%metadata conflicts%' THEN
      v_resolved := v_bank_id IS NOT NULL;
    ELSIF v_reason ILIKE '%Journal metadata cannot be derived%' THEN
      v_resolved := EXISTS(SELECT 1 FROM public.journal_entries WHERE id=v_journal_id AND source_module IS NOT NULL
        AND transaction_currency IS NOT NULL AND functional_currency IS NOT NULL
        AND (transaction_currency='IDR' OR exchange_rate IS NOT NULL));
    END IF;

    IF v_exception_id IS NOT NULL AND v_resolved THEN
      UPDATE public.finance_historical_repair_exceptions SET status='resolved' WHERE id=v_exception_id;
      v_resolved_count := v_resolved_count + 1;
    END IF;

    INSERT INTO public.audit_logs(table_name,action_type,record_id,old_values,new_values,changed_fields)
    VALUES('finance_exception_correction_dashboard','update',v_document_id,
      jsonb_build_object('exception_id',v_exception_id,'journal_lines',v_before_lines),
      jsonb_build_object('correction',c,'journal_lines',v_after_lines,'resolved',v_resolved),
      ARRAY['finance_metadata','account_classification','exception_status']);
    v_saved := v_saved + 1;
  END LOOP;

  RETURN jsonb_build_object('saved',v_saved,'resolved',v_resolved_count,'refresh_required',true);
END;
$$;


--
-- Name: save_finance_exception_corrections_v2("jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_finance_exception_corrections_v2"("p_corrections" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  c jsonb;
  v_type text;
  v_id uuid;
  v_exception bigint;
  v_journal uuid;
  v_line uuid;
  v_supplier uuid;
  v_customer uuid;
  v_from_bank uuid;
  v_to_bank uuid;
  v_from_old uuid;
  v_to_old uuid;
  v_from_old_coa uuid;
  v_to_old_coa uuid;
  v_from_new_coa uuid;
  v_to_new_coa uuid;
  v_from_alias text;
  v_to_alias text;
  v_from_currency text;
  v_to_currency text;
  v_link_type text;
  v_link_id uuid;
  v_result jsonb;
  v_resolved_ids jsonb := '[]'::jsonb;
BEGIN
  PERFORM public._sec_check_finance_role();
  IF jsonb_typeof(p_corrections)<>'array' OR jsonb_array_length(p_corrections)=0 THEN
    RAISE EXCEPTION 'Select at least one correction before saving';
  END IF;
  PERFORM set_config('app.finance_historical_repair','on',true);
  PERFORM set_config('app.finance_metadata_repair','on',true);

  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections) LOOP
    v_type:=c->>'document_type';
    v_id:=(c->>'document_id')::uuid;
    v_exception:=NULLIF(c->>'exception_id','')::bigint;
    v_journal:=NULLIF(c->>'journal_entry_id','')::uuid;
    v_line:=NULLIF(c->>'journal_line_id','')::uuid;
    v_supplier:=NULLIF(c->>'supplier_id','')::uuid;
    v_customer:=NULLIF(c->>'customer_id','')::uuid;
    v_from_bank:=NULLIF(c->>'from_bank_account_id','')::uuid;
    v_to_bank:=NULLIF(c->>'to_bank_account_id','')::uuid;
    v_link_type:=NULLIF(c->>'linked_document_type','');
    v_link_id:=NULLIF(c->>'linked_document_id','')::uuid;

    IF NOT EXISTS (SELECT 1 FROM public.finance_exception_correction_dashboard x WHERE x.document_type=v_type AND x.document_id=v_id) THEN
      RAISE EXCEPTION 'This exception is no longer open';
    END IF;
    IF v_supplier IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.suppliers WHERE id=v_supplier AND COALESCE(is_active,true)) THEN
      RAISE EXCEPTION 'Selected supplier is not active';
    END IF;
    IF v_customer IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customers WHERE id=v_customer) THEN
      RAISE EXCEPTION 'Selected customer does not exist';
    END IF;

    IF v_type='expense' THEN
      UPDATE public.finance_expenses SET
        expense_type=COALESCE(NULLIF(c->>'expense_subcategory',''),expense_type),
        supplier_id=COALESCE(v_supplier,supplier_id),
        payment_reference=COALESCE(NULLIF(c->>'reference',''),payment_reference)
      WHERE id=v_id;
    ELSIF v_type='receipt' THEN
      UPDATE public.receipt_vouchers SET customer_id=COALESCE(v_customer,customer_id),
        reference_number=COALESCE(NULLIF(c->>'reference',''),reference_number) WHERE id=v_id;
    ELSIF v_type='payment' THEN
      UPDATE public.payment_vouchers SET supplier_id=COALESCE(v_supplier,supplier_id),
        reference_number=COALESCE(NULLIF(c->>'reference',''),reference_number) WHERE id=v_id;
    ELSIF v_type='loan' THEN
      UPDATE public.loans SET loan_type=COALESCE(NULLIF(c->>'finance_classification',''),loan_type) WHERE id=v_id;
    ELSIF v_type='capital_contribution' THEN
      UPDATE public.capital_contributions SET contribution_type=COALESCE(NULLIF(c->>'finance_classification',''),contribution_type) WHERE id=v_id;
    END IF;

    IF v_line IS NOT NULL THEN
      UPDATE public.journal_entry_lines SET
        supplier_id=COALESCE(v_supplier,supplier_id),customer_id=COALESCE(v_customer,customer_id)
      WHERE id=v_line AND journal_entry_id=v_journal;
    END IF;

    IF v_type='fund_transfer' AND (v_from_bank IS NOT NULL OR v_to_bank IS NOT NULL) THEN
      SELECT from_bank_account_id,to_bank_account_id,journal_entry_id INTO v_from_old,v_to_old,v_journal
      FROM public.fund_transfers WHERE id=v_id FOR UPDATE;
      v_from_bank:=COALESCE(v_from_bank,v_from_old);
      v_to_bank:=COALESCE(v_to_bank,v_to_old);
      IF v_from_bank=v_to_bank THEN RAISE EXCEPTION 'From Bank and To Bank must be different'; END IF;
      SELECT coa_id,COALESCE(alias,account_name,bank_name),upper(currency) INTO v_from_new_coa,v_from_alias,v_from_currency
        FROM public.bank_accounts WHERE id=v_from_bank AND is_active;
      SELECT coa_id,COALESCE(alias,account_name,bank_name),upper(currency) INTO v_to_new_coa,v_to_alias,v_to_currency
        FROM public.bank_accounts WHERE id=v_to_bank AND is_active;
      SELECT coa_id INTO v_from_old_coa FROM public.bank_accounts WHERE id=v_from_old;
      SELECT coa_id INTO v_to_old_coa FROM public.bank_accounts WHERE id=v_to_old;
      IF v_from_new_coa IS NULL OR v_to_new_coa IS NULL THEN RAISE EXCEPTION 'Both transfer banks need active Bank Master posting accounts'; END IF;
      UPDATE public.journal_entry_lines SET account_id=v_from_new_coa
        WHERE journal_entry_id=v_journal AND account_id=v_from_old_coa AND COALESCE(credit,0)>0;
      UPDATE public.journal_entry_lines SET account_id=v_to_new_coa
        WHERE journal_entry_id=v_journal AND account_id=v_to_old_coa AND COALESCE(debit,0)>0;
      UPDATE public.fund_transfers SET from_bank_account_id=v_from_bank,to_bank_account_id=v_to_bank WHERE id=v_id;
    END IF;

    IF v_type='bank_reconciliation' AND v_link_id IS NOT NULL THEN
      IF v_link_type IS NULL THEN RAISE EXCEPTION 'Select the linked document type'; END IF;
      PERFORM public.link_bank_statement_line(v_id,v_link_type,v_link_id,COALESCE(NULLIF(c->>'payment_type',''),'supplier'));
    END IF;
  END LOOP;

  -- Existing RPC owns GL classification, bank master mapping, tax/currency
  -- metadata, balance protection, audit logging and reason-specific verification.
  v_result:=public.save_finance_exception_corrections(p_corrections);

  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections) LOOP
    v_exception:=NULLIF(c->>'exception_id','')::bigint;
    IF v_exception IS NOT NULL AND COALESCE((c->>'confirm_resolved')::boolean,false)
       AND EXISTS (
         SELECT 1 FROM jsonb_each_text(c) x
         WHERE x.key IN ('expense_category','expense_subcategory','account_id','bank_account_id','from_bank_account_id',
           'to_bank_account_id','loan_account_id','capital_account_id','tax_code_id','payment_type','document_classification',
           'exchange_rate','faktur_pajak_number','supplier_id','customer_id','reference','finance_classification','linked_document_id')
           AND NULLIF(x.value,'') IS NOT NULL
       ) THEN
      UPDATE public.finance_historical_repair_exceptions SET status='resolved'
      WHERE id=v_exception AND status='manual_review';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.finance_exception_correction_dashboard x
      WHERE x.document_type=c->>'document_type' AND x.document_id=(c->>'document_id')::uuid
    ) THEN v_resolved_ids:=v_resolved_ids || jsonb_build_array(c->>'row_id'); END IF;
  END LOOP;

  RETURN v_result || jsonb_build_object('resolved_row_ids',v_resolved_ids,'verification_refreshed',true);
END;
$$;


--
-- Name: save_finance_expense("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_finance_expense"("p_expense_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_date date := COALESCE((p_payload->>'expense_date')::date, current_date);
  v_bank_id uuid := NULLIF(p_payload->>'bank_account_id', '')::uuid;
  v_bank_currency text;
  v_currency text;
  v_rate numeric;
  v_docs text[];
BEGIN
  PERFORM public._sec_check_finance_role();
  IF COALESCE((p_payload->>'amount')::numeric, 0) <= 0 THEN
    RAISE EXCEPTION 'Expense amount must be greater than zero';
  END IF;
  IF NULLIF(p_payload->>'expense_category', '') IS NULL THEN
    RAISE EXCEPTION 'Expense category is required';
  END IF;

  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id = v_bank_id;
  v_currency := upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''), v_bank_currency, 'IDR'));
  IF v_currency NOT IN ('IDR','USD') THEN RAISE EXCEPTION 'Unsupported expense currency %', v_currency; END IF;
  v_rate := COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric, 0), CASE WHEN v_currency = 'IDR' THEN 1 ELSE NULL END);
  IF v_rate IS NULL OR v_rate <= 0 THEN
    RAISE EXCEPTION 'A positive exchange rate is required for % expenses', v_currency;
  END IF;
  IF v_bank_currency IS NOT NULL AND v_bank_currency <> v_currency THEN
    RAISE EXCEPTION 'Expense currency % does not match selected bank currency %', v_currency, v_bank_currency;
  END IF;

  SELECT COALESCE(array_agg(value), ARRAY[]::text[]) INTO v_docs
    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls', '[]'::jsonb));

  IF p_expense_id IS NULL THEN
    INSERT INTO public.finance_expenses (
      voucher_number, expense_category, expense_type, amount, expense_date, description,
      batch_id, import_container_id, delivery_challan_id, payment_method, bank_account_id,
      payment_reference, paid_by, document_urls, supplier_id, staff_id, invoice_number,
      due_date, broker_items, pib_bm_amount, pib_ppn_amount, pib_pph_amount, ppn_amount,
      ppn_manual_override, ppn_calc_mode, dpp_amount, ppn_rate, pph_amount, pph_code_id,
      stamp_duty_amount, fixed_asset_account_id, bank_charges_amount, approval_status,
      created_by, currency_code, transaction_currency, functional_currency, exchange_rate,
      bank_account_currency, payment_currency
    ) VALUES (
      public.next_expense_voucher_number(v_date), p_payload->>'expense_category',
      COALESCE(NULLIF(p_payload->>'expense_type',''), 'admin'), (p_payload->>'amount')::numeric,
      v_date, NULLIF(p_payload->>'description',''), NULLIF(p_payload->>'batch_id','')::uuid,
      NULLIF(p_payload->>'import_container_id','')::uuid, NULLIF(p_payload->>'delivery_challan_id','')::uuid,
      NULLIF(p_payload->>'payment_method',''), v_bank_id, NULLIF(p_payload->>'payment_reference',''),
      NULLIF(p_payload->>'paid_by',''), NULLIF(v_docs, ARRAY[]::text[]),
      NULLIF(p_payload->>'supplier_id','')::uuid, NULLIF(p_payload->>'staff_id','')::uuid,
      NULLIF(p_payload->>'invoice_number',''), NULLIF(p_payload->>'due_date','')::date,
      NULLIF(p_payload->'broker_items','null'::jsonb), NULLIF(p_payload->>'pib_bm_amount','')::numeric,
      NULLIF(p_payload->>'pib_ppn_amount','')::numeric, NULLIF(p_payload->>'pib_pph_amount','')::numeric,
      COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0), COALESCE((p_payload->>'ppn_manual_override')::boolean,false),
      COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'), NULLIF(p_payload->>'dpp_amount','')::numeric,
      COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11), COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),
      NULLIF(p_payload->>'pph_code_id','')::uuid, COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),
      NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,
      COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),
      COALESCE(NULLIF(p_payload->>'approval_status',''),'pending_approval'),
      COALESCE(NULLIF(p_payload->>'created_by','')::uuid, auth.uid()),
      v_currency, v_currency, 'IDR', v_rate, COALESCE(v_bank_currency,v_currency), v_currency
    ) RETURNING id INTO v_id;
  ELSE
    IF EXISTS (SELECT 1 FROM public.finance_expenses WHERE id=p_expense_id AND approval_status='approved') THEN
      RAISE EXCEPTION 'This expense is posted. Cancel Posting first to make changes.';
    END IF;
    UPDATE public.finance_expenses SET
      expense_category=p_payload->>'expense_category', expense_type=COALESCE(NULLIF(p_payload->>'expense_type',''),'admin'),
      amount=(p_payload->>'amount')::numeric, expense_date=v_date, description=NULLIF(p_payload->>'description',''),
      batch_id=NULLIF(p_payload->>'batch_id','')::uuid, import_container_id=NULLIF(p_payload->>'import_container_id','')::uuid,
      delivery_challan_id=NULLIF(p_payload->>'delivery_challan_id','')::uuid,
      payment_method=NULLIF(p_payload->>'payment_method',''), bank_account_id=v_bank_id,
      payment_reference=NULLIF(p_payload->>'payment_reference',''), paid_by=NULLIF(p_payload->>'paid_by',''),
      document_urls=NULLIF(v_docs,ARRAY[]::text[]), supplier_id=NULLIF(p_payload->>'supplier_id','')::uuid,
      staff_id=NULLIF(p_payload->>'staff_id','')::uuid, invoice_number=NULLIF(p_payload->>'invoice_number',''),
      due_date=NULLIF(p_payload->>'due_date','')::date, broker_items=NULLIF(p_payload->'broker_items','null'::jsonb),
      pib_bm_amount=NULLIF(p_payload->>'pib_bm_amount','')::numeric,
      pib_ppn_amount=NULLIF(p_payload->>'pib_ppn_amount','')::numeric,
      pib_pph_amount=NULLIF(p_payload->>'pib_pph_amount','')::numeric,
      ppn_amount=COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0),
      ppn_manual_override=COALESCE((p_payload->>'ppn_manual_override')::boolean,false),
      ppn_calc_mode=COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'),
      dpp_amount=NULLIF(p_payload->>'dpp_amount','')::numeric, ppn_rate=COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11),
      pph_amount=COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0), pph_code_id=NULLIF(p_payload->>'pph_code_id','')::uuid,
      stamp_duty_amount=COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),
      fixed_asset_account_id=NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,
      bank_charges_amount=COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),
      currency_code=v_currency, transaction_currency=v_currency, functional_currency='IDR', exchange_rate=v_rate,
      bank_account_currency=COALESCE(v_bank_currency,v_currency), payment_currency=v_currency
    WHERE id=p_expense_id RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: save_finance_journal("uuid", "date", "text", "jsonb", "text", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_finance_journal"("p_entry_id" "uuid" DEFAULT NULL::"uuid", "p_entry_date" "date" DEFAULT CURRENT_DATE, "p_description" "text" DEFAULT NULL::"text", "p_lines" "jsonb" DEFAULT '[]'::"jsonb", "p_transaction_currency" "text" DEFAULT 'IDR'::"text", "p_exchange_rate" numeric DEFAULT 1) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_line jsonb;
  v_dr numeric:=0;
  v_cr numeric:=0;
  v_factor numeric;
  v_num text;
  v_i int:=0;
BEGIN
  PERFORM public._sec_check_finance_role();
  p_transaction_currency:=upper(COALESCE(p_transaction_currency,'IDR'));
  IF p_transaction_currency NOT IN ('IDR','USD') THEN RAISE EXCEPTION 'Unsupported journal currency'; END IF;
  IF p_exchange_rate IS NULL OR p_exchange_rate<=0 OR (p_transaction_currency='USD' AND p_exchange_rate<=1) THEN
    RAISE EXCEPTION 'A valid exchange rate is required';
  END IF;
  v_factor:=CASE WHEN p_transaction_currency='IDR' THEN 1 ELSE p_exchange_rate END;
  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    v_dr:=v_dr+COALESCE((v_line->>'debit')::numeric,0);
    v_cr:=v_cr+COALESCE((v_line->>'credit')::numeric,0);
  END LOOP;
  IF v_dr<=0 OR abs(v_dr-v_cr)>0.01 THEN RAISE EXCEPTION 'Journal must be balanced and greater than zero'; END IF;

  IF p_entry_id IS NULL THEN
    v_num:=public.generate_journal_entry_number();
    INSERT INTO public.journal_entries(entry_number,entry_date,description,source_module,total_debit,total_credit,
      is_posted,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
    VALUES(v_num,p_entry_date,NULLIF(p_description,''),'manual',round(v_dr*v_factor,2),round(v_cr*v_factor,2),
      true,auth.uid(),auth.uid(),p_transaction_currency,'IDR',v_factor,true)
    RETURNING id INTO v_id;
  ELSE
    IF NOT EXISTS(SELECT 1 FROM public.journal_entries WHERE id=p_entry_id AND source_module='manual') THEN
      RAISE EXCEPTION 'Only manual journals can be edited';
    END IF;
    v_id:=p_entry_id;
    UPDATE public.journal_entries SET entry_date=p_entry_date,description=NULLIF(p_description,''),
      total_debit=round(v_dr*v_factor,2),total_credit=round(v_cr*v_factor,2),transaction_currency=p_transaction_currency,
      functional_currency='IDR',exchange_rate=v_factor,amounts_are_functional=true WHERE id=v_id;
    DELETE FROM public.journal_entry_lines WHERE journal_entry_id=v_id;
  END IF;
  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    IF COALESCE((v_line->>'debit')::numeric,0)>0 OR COALESCE((v_line->>'credit')::numeric,0)>0 THEN
      v_i:=v_i+1;
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,
        transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
      VALUES(v_id,v_i,(v_line->>'account_id')::uuid,NULLIF(v_line->>'description',''),
        round(COALESCE((v_line->>'debit')::numeric,0)*v_factor,2),
        round(COALESCE((v_line->>'credit')::numeric,0)*v_factor,2),p_transaction_currency,
        COALESCE((v_line->>'debit')::numeric,0),COALESCE((v_line->>'credit')::numeric,0),'IDR',v_factor);
    END IF;
  END LOOP;
  RETURN v_id;
END;
$$;


--
-- Name: save_finance_loan("jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_finance_loan"("p_payload" "jsonb", "p_bank_statement_line_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid := gen_random_uuid();
  v_number text;
  v_je uuid;
  v_coa uuid;
  v_line public.bank_statement_lines%ROWTYPE;
  v_amount numeric;
  v_date date;
BEGIN
  PERFORM public._sec_check_finance_role();
  v_date := (p_payload->>'loan_date')::date;
  v_amount := (p_payload->>'principal_amount')::numeric;

  IF NULLIF(trim(p_payload->>'counterparty_name'), '') IS NULL OR v_amount <= 0 THEN
    RAISE EXCEPTION 'Loan counterparty and positive principal are required';
  END IF;

  IF p_payload->>'liability_kind' = 'director_owner' THEN
    -- The UI supplies the existing liability ledger ID selected from the COA.
    -- Do not resolve a code or manufacture a Director/Owner account here.
    SELECT id INTO v_coa
    FROM public.chart_of_accounts
    WHERE id = NULLIF(p_payload->>'liability_account_id', '')::uuid
      AND is_active = true
      AND COALESCE(is_header, false) = false
      AND lower(account_type) = 'liability';
    IF v_coa IS NULL THEN
      RAISE EXCEPTION 'Select an existing active Director/Owner liability ledger';
    END IF;
    -- When the installation has an existing Director master, ensure its
    -- configured loan ledger is exactly the selected COA. Older ledgers with
    -- no master record remain supported without creating one.
    IF NULLIF(p_payload->>'director_id', '') IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.directors d
      WHERE d.id = (p_payload->>'director_id')::uuid
        AND d.is_active = true
        AND COALESCE(d.is_deprecated, false) = false
        AND d.loan_account_id = v_coa
    ) THEN
      RAISE EXCEPTION 'Selected Director/Owner is not configured for this loan ledger';
    END IF;
  ELSE
    -- Existing ordinary-loan behaviour is intentionally unchanged.
    SELECT id INTO v_coa
    FROM public.chart_of_accounts
    WHERE code = '2210' AND is_active = true AND COALESCE(is_header, false) = false
    LIMIT 1;
    IF v_coa IS NULL THEN
      RAISE EXCEPTION 'Required loan liability account is not configured';
    END IF;
  END IF;

  IF p_bank_statement_line_id IS NOT NULL THEN
    SELECT * INTO v_line
    FROM public.bank_statement_lines
    WHERE id = p_bank_statement_line_id
    FOR UPDATE;

    IF NOT FOUND
      OR COALESCE(v_line.credit_amount, 0) <> v_amount
      OR v_line.bank_account_id <> (p_payload->>'bank_account_id')::uuid THEN
      RAISE EXCEPTION 'Bank statement line does not exactly match this loan';
    END IF;
    IF v_line.matched_entry_id IS NOT NULL THEN
      RAISE EXCEPTION 'Bank statement line is already linked';
    END IF;
  END IF;

  v_number := public.next_loan_number(v_date);
  INSERT INTO public.loans(
    id, loan_number, loan_type, counterparty_name, counterparty_type,
    principal_amount, interest_rate, loan_date, bank_account_id, coa_id,
    currency, transaction_currency, functional_currency, exchange_rate,
    bank_account_currency, description, created_by, bank_statement_line_id
  )
  VALUES (
    v_id, v_number, 'taken', trim(p_payload->>'counterparty_name'),
    COALESCE(NULLIF(p_payload->>'counterparty_type', ''), 'person'),
    v_amount, 0, v_date, (p_payload->>'bank_account_id')::uuid, v_coa,
    upper(p_payload->>'transaction_currency'), upper(p_payload->>'transaction_currency'),
    'IDR', (p_payload->>'exchange_rate')::numeric,
    upper(p_payload->>'transaction_currency'), COALESCE(p_payload->>'description', ''),
    COALESCE(NULLIF(p_payload->>'created_by', '')::uuid, auth.uid()),
    p_bank_statement_line_id
  )
  RETURNING journal_entry_id INTO v_je;

  IF p_bank_statement_line_id IS NOT NULL THEN
    PERFORM public._link_native_bank_document(
      p_bank_statement_line_id,
      v_je,
      'Loan - ' || v_number
    );
  END IF;

  RETURN jsonb_build_object('id', v_id, 'loan_number', v_number, 'journal_entry_id', v_je);
END;
$$;


--
-- Name: save_finance_loan_repayment("jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_finance_loan_repayment"("p_payload" "jsonb", "p_bank_statement_line_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid:=gen_random_uuid(); v_number text; v_je uuid; v_line public.bank_statement_lines%ROWTYPE; v_amount numeric; v_date date;
BEGIN
  PERFORM public._sec_check_finance_role();
  v_date:=(p_payload->>'transaction_date')::date; v_amount:=COALESCE((p_payload->>'principal_amount')::numeric,0)+COALESCE((p_payload->>'interest_amount')::numeric,0);
  IF p_bank_statement_line_id IS NOT NULL THEN
    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id FOR UPDATE;
    IF NOT FOUND OR COALESCE(v_line.debit_amount,0)<>v_amount OR v_line.bank_account_id<>(p_payload->>'bank_account_id')::uuid THEN RAISE EXCEPTION 'Bank statement line does not exactly match this repayment'; END IF;
    IF v_line.matched_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Bank statement line is already linked'; END IF;
  END IF;
  v_number:=public.next_loan_transaction_number(v_date);
  INSERT INTO public.loan_transactions(id,transaction_number,loan_id,transaction_type,transaction_date,amount,principal_amount,interest_amount,
    bank_account_id,bank_statement_line_id,description,created_by,transaction_currency,functional_currency,exchange_rate,bank_account_currency)
  VALUES(v_id,v_number,(p_payload->>'loan_id')::uuid,'repayment',v_date,v_amount,(p_payload->>'principal_amount')::numeric,
    COALESCE((p_payload->>'interest_amount')::numeric,0),(p_payload->>'bank_account_id')::uuid,p_bank_statement_line_id,
    COALESCE(p_payload->>'description',''),COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),upper(p_payload->>'transaction_currency'),'IDR',
    (p_payload->>'exchange_rate')::numeric,upper(p_payload->>'transaction_currency')) RETURNING journal_entry_id INTO v_je;
  IF p_bank_statement_line_id IS NOT NULL THEN PERFORM public._link_native_bank_document(p_bank_statement_line_id,v_je,'Loan Repayment - '||v_number); END IF;
  RETURN jsonb_build_object('id',v_id,'transaction_number',v_number,'journal_entry_id',v_je);
END $$;


--
-- Name: save_payment_voucher("date", "uuid", "text", "uuid", "text", numeric, numeric, "uuid", "text", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_payment_voucher"("p_voucher_date" "date", "p_supplier_id" "uuid", "p_payment_method" "text", "p_bank_account_id" "uuid", "p_reference_number" "text", "p_amount" numeric, "p_pph_amount" numeric, "p_pph_code_id" "uuid", "p_description" "text", "p_created_by" "uuid", "p_allocations" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
v_voucher_number text;
BEGIN
v_voucher_number := public.generate_voucher_number('PV');

RETURN public.save_payment_voucher_with_allocations(
NULL,
v_voucher_number,
p_voucher_date,
p_supplier_id,
p_payment_method,
p_bank_account_id,
p_reference_number,
p_amount,
p_pph_amount,
p_pph_code_id,
p_description,
'IDR',
1,
NULL,
0,
p_created_by,
p_allocations
);
END;
$$;


--
-- Name: save_payment_voucher_command("uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_payment_voucher_command"("p_voucher_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_allocations" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_number text;
  v_id uuid;
  v_date date := (p_payload->>'voucher_date')::date;
  v_payment_currency text := upper(COALESCE(NULLIF(p_payload->>'payment_currency',''),'IDR'));
  v_invoice_currency text := upper(COALESCE(
    NULLIF(p_payload->>'invoice_currency',''),
    NULLIF((SELECT COALESCE(a->>'currency',a->>'allocated_currency')
            FROM jsonb_array_elements(COALESCE(p_allocations,'[]'::jsonb)) a
            WHERE COALESCE(a->>'currency',a->>'allocated_currency') IS NOT NULL LIMIT 1),''),
    v_payment_currency));
  v_bank_currency text;
  v_rate numeric := COALESCE(NULLIF(p_payload->>'exchange_rate','')::numeric,1);
  v_invoice_amount numeric := COALESCE(NULLIF(p_payload->>'invoice_amount','')::numeric,
    NULLIF(p_payload->>'amount','')::numeric,0);
  v_payment_amount numeric := COALESCE(NULLIF(p_payload->>'payment_amount','')::numeric,
    v_invoice_amount-COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0));
  v_converted numeric;
  v_actual numeric;
  v_bank_charge numeric := COALESCE(NULLIF(p_payload->>'bank_charge','')::numeric,0);
  v_docs text[];
BEGIN
  PERFORM public._sec_check_finance_role();
  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts
   WHERE id=NULLIF(p_payload->>'bank_account_id','')::uuid;
  v_bank_currency:=COALESCE(v_bank_currency,v_payment_currency);
  IF v_payment_currency NOT IN('IDR','USD') OR v_invoice_currency NOT IN('IDR','USD')
     OR v_bank_currency NOT IN('IDR','USD') OR v_rate<=0 THEN
    RAISE EXCEPTION 'Payment currencies or exchange rate are invalid';
  END IF;
  v_converted:=COALESCE(NULLIF(p_payload->>'converted_amount','')::numeric,
    v_payment_amount*CASE WHEN v_invoice_currency=v_bank_currency THEN 1 ELSE v_rate END);
  v_actual:=COALESCE(NULLIF(p_payload->>'actual_bank_debit','')::numeric,
    NULLIF(p_payload->>'bank_amount','')::numeric,v_converted+v_bank_charge);
  IF v_actual<=0 AND v_invoice_amount>0 THEN RAISE EXCEPTION 'Actual bank debit must be positive'; END IF;
  SELECT COALESCE(array_agg(value),ARRAY[]::text[]) INTO v_docs
    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls','[]'::jsonb));

  SELECT voucher_number INTO v_number FROM public.payment_vouchers WHERE id=p_voucher_id;
  v_number:=COALESCE(v_number,public.next_payment_voucher_number(v_date));
  v_id:=public.save_payment_voucher_with_allocations(
    p_voucher_id=>p_voucher_id,p_voucher_number=>v_number,p_voucher_date=>v_date,
    p_supplier_id=>NULLIF(p_payload->>'supplier_id','')::uuid,
    p_payment_method=>p_payload->>'payment_method',
    p_bank_account_id=>NULLIF(p_payload->>'bank_account_id','')::uuid,
    p_reference_number=>NULLIF(p_payload->>'reference_number',''),p_amount=>v_invoice_amount,
    p_pph_amount=>COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),
    p_pph_code_id=>NULLIF(p_payload->>'pph_code_id','')::uuid,
    p_description=>NULLIF(p_payload->>'description',''),
    p_payment_currency=>v_payment_currency,p_exchange_rate=>v_rate,
    p_bank_amount=>v_actual,p_bank_charge=>v_bank_charge,
    p_created_by=>COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),
    p_allocations=>p_allocations,p_staff_id=>NULLIF(p_payload->>'staff_id','')::uuid);
  UPDATE public.payment_vouchers SET
    invoice_currency=v_invoice_currency,invoice_amount=v_invoice_amount,
    payment_amount=v_payment_amount,payment_currency=v_payment_currency,
    transaction_currency=v_invoice_currency,functional_currency='IDR',
    exchange_rate=v_rate,bank_currency=v_bank_currency,
    bank_account_currency=v_bank_currency,converted_amount=v_converted,
    actual_bank_debit=v_actual,bank_amount=v_actual,
    document_urls=NULLIF(v_docs,ARRAY[]::text[])
  WHERE id=v_id;
  RETURN jsonb_build_object('id',v_id,'voucher_number',v_number);
END;
$$;


--
-- Name: save_payment_voucher_with_allocations("uuid", "text", "date", "uuid", "text", "uuid", "text", numeric, numeric, "uuid", "text", "text", numeric, numeric, numeric, "uuid", "jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_payment_voucher_with_allocations"("p_voucher_id" "uuid" DEFAULT NULL::"uuid", "p_voucher_number" "text" DEFAULT NULL::"text", "p_voucher_date" "date" DEFAULT NULL::"date", "p_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_payment_method" "text" DEFAULT NULL::"text", "p_bank_account_id" "uuid" DEFAULT NULL::"uuid", "p_reference_number" "text" DEFAULT NULL::"text", "p_amount" numeric DEFAULT 0, "p_pph_amount" numeric DEFAULT 0, "p_pph_code_id" "uuid" DEFAULT NULL::"uuid", "p_description" "text" DEFAULT NULL::"text", "p_payment_currency" "text" DEFAULT 'IDR'::"text", "p_exchange_rate" numeric DEFAULT 1, "p_bank_amount" numeric DEFAULT NULL::numeric, "p_bank_charge" numeric DEFAULT 0, "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_allocations" "jsonb" DEFAULT '[]'::"jsonb", "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_voucher_id    UUID;
  v_alloc         JSONB;
  v_invoice_id    UUID;
  v_expense_id    UUID;
  v_alloc_amount  NUMERIC;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_supplier_id IS NULL AND p_staff_id IS NULL THEN
    RAISE EXCEPTION 'Payment voucher needs a payee: supplier or staff';
  END IF;

  -- ── Create or update the voucher header ──
  IF p_voucher_id IS NULL THEN
    INSERT INTO payment_vouchers (
      voucher_number, voucher_date, supplier_id, staff_id, payment_method,
      bank_account_id, reference_number, amount, pph_amount, pph_code_id,
      description, payment_currency, exchange_rate,
      bank_amount, bank_charge, created_by
    ) VALUES (
      p_voucher_number, p_voucher_date, p_supplier_id, p_staff_id, p_payment_method,
      p_bank_account_id, p_reference_number, p_amount, p_pph_amount, p_pph_code_id,
      p_description, p_payment_currency, p_exchange_rate,
      p_bank_amount, p_bank_charge, p_created_by
    ) RETURNING id INTO v_voucher_id;
  ELSE
    v_voucher_id := p_voucher_id;

    IF EXISTS (SELECT 1 FROM payment_vouchers WHERE id = v_voucher_id AND is_posted = TRUE) THEN
      RAISE EXCEPTION 'Cannot edit: % is posted. Cancel Posting first to make changes.', p_voucher_number;
    END IF;

    UPDATE payment_vouchers SET
      voucher_date      = p_voucher_date,
      supplier_id       = p_supplier_id,
      staff_id          = p_staff_id,
      payment_method    = p_payment_method,
      bank_account_id   = p_bank_account_id,
      reference_number  = p_reference_number,
      amount            = p_amount,
      pph_amount        = p_pph_amount,
      pph_code_id       = p_pph_code_id,
      description       = p_description,
      payment_currency  = p_payment_currency,
      exchange_rate     = p_exchange_rate,
      bank_amount       = p_bank_amount,
      bank_charge       = p_bank_charge,
      updated_at        = NOW()
    WHERE id = v_voucher_id;
  END IF;

  -- ── Replace all allocations ──
  DELETE FROM voucher_allocations WHERE payment_voucher_id = v_voucher_id;

  FOR v_alloc IN SELECT value FROM jsonb_array_elements(p_allocations) AS value
  LOOP
    v_alloc_amount := COALESCE((v_alloc->>'amount')::NUMERIC, 0);
    IF v_alloc_amount <= 0 THEN
      CONTINUE;
    END IF;

    v_invoice_id := NULLIF(v_alloc->>'invoice_id', '')::UUID;
    v_expense_id := NULLIF(v_alloc->>'finance_expense_id', '')::UUID;

    IF v_invoice_id IS NOT NULL THEN
      INSERT INTO voucher_allocations (
        payment_voucher_id, purchase_invoice_id,
        allocated_amount, allocated_currency, voucher_type
      ) VALUES (
        v_voucher_id, v_invoice_id, v_alloc_amount,
        COALESCE(v_alloc->>'currency', 'IDR'), 'payment'
      );
    ELSIF v_expense_id IS NOT NULL THEN
      INSERT INTO voucher_allocations (
        payment_voucher_id, finance_expense_id,
        allocated_amount, allocated_currency, voucher_type
      ) VALUES (
        v_voucher_id, v_expense_id, v_alloc_amount,
        COALESCE(v_alloc->>'currency', 'IDR'), 'payment'
      );
      -- paid_amount on finance_expenses updated by trg_sync_expense_payment_state
    END IF;
  END LOOP;

  RETURN v_voucher_id;
END;
$$;


--
-- Name: save_payment_voucher_with_purpose("uuid", "jsonb", "jsonb", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_payment_voucher_with_purpose"("p_voucher_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_allocations" "jsonb" DEFAULT '[]'::"jsonb", "p_payment_purpose" "text" DEFAULT 'general'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_id uuid;
BEGIN
  PERFORM public._sec_check_finance_role();

  IF p_payment_purpose NOT IN (
    'general',
    'salary_advance',
    'salary_advance_settlement'
  ) THEN
    RAISE EXCEPTION 'Unsupported payment purpose %', p_payment_purpose;
  END IF;

  v_result := public.save_payment_voucher_command(
    p_voucher_id,
    p_payload,
    p_allocations
  );
  v_id := (v_result->>'id')::uuid;

  UPDATE public.payment_vouchers
     SET payment_purpose = p_payment_purpose,
         salary_advance_status = CASE p_payment_purpose
           WHEN 'salary_advance' THEN 'outstanding'
           ELSE 'not_applicable'
         END
   WHERE id = v_id;

  RETURN v_result;
END;
$$;


--
-- Name: save_purchase_invoice("uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_purchase_invoice"("p_invoice_id" "uuid", "p_invoice_data" "jsonb", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  DECLARE
    v_invoice_id        UUID;
    v_je_id             UUID;
    v_je_number         TEXT;
    v_ap_account_id     UUID;
    v_ppn_account_id    UUID;
    v_bm_account_id     UUID;
    v_account_id        UUID;
    v_item              JSONB;
    v_line_number       INTEGER;
    v_invoice_date      DATE;
    v_invoice_number    TEXT;
    v_supplier_id       UUID;
    v_total_amount      NUMERIC(15,2);
    v_tax_amount        NUMERIC(15,2);
    v_stamp_duty_amount NUMERIC(15,2);
    v_created_by        UUID;
    v_item_type         TEXT;
    v_line_total        NUMERIC(15,2);
    v_item_id           UUID;
    v_po_id             UUID;
    v_currency          TEXT;
    v_rate              NUMERIC;
  BEGIN
    v_created_by        := auth.uid();
    v_invoice_date      := (p_invoice_data->>'invoice_date')::DATE;
    v_invoice_number    := p_invoice_data->>'invoice_number';
    v_total_amount      := (p_invoice_data->>'total_amount')::NUMERIC(15,2);
    v_tax_amount        := COALESCE((p_invoice_data->>'tax_amount')::NUMERIC(15,2), 0);
    v_stamp_duty_amount := COALESCE((p_invoice_data->>'stamp_duty_amount')::NUMERIC(15,2), 0);
    v_supplier_id       := (p_invoice_data->>'supplier_id')::UUID;
    v_po_id             := NULLIF(p_invoice_data->>'purchase_order_id', '')::UUID;
    v_currency := upper(coalesce(p_invoice_data->>'currency', 'IDR'));
    v_rate := CASE WHEN v_currency = 'IDR' THEN 1 ELSE NULLIF((p_invoice_data->>'exchange_rate')::NUMERIC, 0) END;
    IF v_currency <> 'IDR' AND (v_rate IS NULL OR v_rate <= 1) THEN
      RAISE EXCEPTION 'Purchase invoice % requires a valid exchange rate greater than 1', v_invoice_number;
    END IF;

    SELECT id INTO v_ap_account_id  FROM chart_of_accounts WHERE code = '2110' LIMIT 1;
    SELECT id INTO v_ppn_account_id FROM chart_of_accounts WHERE code = '1150' LIMIT 1;
    SELECT id INTO v_bm_account_id  FROM chart_of_accounts WHERE code = '6950' LIMIT 1;

    IF v_ap_account_id IS NULL THEN
      RAISE EXCEPTION 'A/P account (code 2110) not found in chart of accounts';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtext('je_number_' || TO_CHAR(v_invoice_date, 'YYMM')));

    IF p_invoice_id IS NULL THEN
      -- ── CREATE path ──────────────────────────────────────────────────────────

      v_je_number := 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-' || LPAD((
        SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM '(\d+)$') AS INTEGER)), 0) + 1
        FROM journal_entries
        WHERE entry_number LIKE 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-%'
      )::TEXT, 4, '0');

      INSERT INTO journal_entries (
        entry_number, entry_date, source_module, reference_id, reference_number,
        description, total_debit, total_credit, is_posted, posted_by, created_by
      ) VALUES (
        v_je_number, v_invoice_date, 'purchase_invoice', gen_random_uuid(), v_invoice_number,
        'Purchase Invoice: ' || v_invoice_number,
        0, v_total_amount * v_rate, TRUE, v_created_by, v_created_by
      ) RETURNING id INTO v_je_id;

      INSERT INTO purchase_invoices (
        invoice_number, supplier_id, invoice_date, due_date,
        currency, exchange_rate, subtotal, tax_amount, stamp_duty_amount, total_amount,
        paid_amount, status,
        faktur_pajak_number, notes, document_urls,
        requires_faktur_pajak, purchase_type,
        purchase_order_id,
        journal_entry_id, created_by
      ) VALUES (
        v_invoice_number,
        v_supplier_id,
        v_invoice_date,
        NULLIF(p_invoice_data->>'due_date', '')::DATE,
        COALESCE(p_invoice_data->>'currency', 'IDR'),
        COALESCE((p_invoice_data->>'exchange_rate')::NUMERIC, 1),
        COALESCE((p_invoice_data->>'subtotal')::NUMERIC, 0),
        v_tax_amount,
        v_stamp_duty_amount,
        v_total_amount,
        0,
        'unpaid',
        NULLIF(p_invoice_data->>'faktur_pajak_number', ''),
        NULLIF(p_invoice_data->>'notes', ''),
        CASE
          WHEN p_invoice_data -> 'document_urls' IS NOT NULL
            AND jsonb_array_length(p_invoice_data -> 'document_urls') > 0
          THEN ARRAY(SELECT jsonb_array_elements_text(p_invoice_data -> 'document_urls'))
          ELSE NULL
        END,
        COALESCE((p_invoice_data->>'requires_faktur_pajak')::BOOLEAN, FALSE),
        COALESCE(p_invoice_data->>'purchase_type', 'inventory'),
        v_po_id,
        v_je_id,
        v_created_by
      ) RETURNING id INTO v_invoice_id;

      UPDATE journal_entries SET reference_id = v_invoice_id WHERE id = v_je_id;

    ELSE
      -- ── EDIT path ──────────────────────────────────────────────────────────

      v_invoice_id := p_invoice_id;

      SELECT journal_entry_id INTO v_je_id
      FROM purchase_invoices WHERE id = v_invoice_id;

      UPDATE purchase_invoices SET
        invoice_number        = v_invoice_number,
        supplier_id           = v_supplier_id,
        invoice_date          = v_invoice_date,
        due_date              = NULLIF(p_invoice_data->>'due_date', '')::DATE,
        currency              = COALESCE(p_invoice_data->>'currency', 'IDR'),
        exchange_rate         = COALESCE((p_invoice_data->>'exchange_rate')::NUMERIC, 1),
        subtotal              = COALESCE((p_invoice_data->>'subtotal')::NUMERIC, 0),
        tax_amount            = v_tax_amount,
        stamp_duty_amount     = v_stamp_duty_amount,
        total_amount          = v_total_amount,
        faktur_pajak_number   = NULLIF(p_invoice_data->>'faktur_pajak_number', ''),
        notes                 = NULLIF(p_invoice_data->>'notes', ''),
        document_urls         = CASE
                                  WHEN p_invoice_data -> 'document_urls' IS NOT NULL
                                    AND jsonb_array_length(p_invoice_data -> 'document_urls') > 0
                                  THEN ARRAY(SELECT jsonb_array_elements_text(p_invoice_data -> 'document_urls'))
                                  ELSE NULL
                                END,
        requires_faktur_pajak = COALESCE((p_invoice_data->>'requires_faktur_pajak')::BOOLEAN, FALSE),
        purchase_type         = COALESCE(p_invoice_data->>'purchase_type', 'inventory'),
        purchase_order_id     = v_po_id,
        updated_at            = NOW()
      WHERE id = v_invoice_id;

      IF EXISTS (
        SELECT 1 FROM purchase_invoice_items i 
        WHERE i.purchase_invoice_id = v_invoice_id 
          AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) x 
            WHERE NULLIF(x->>'id','')::uuid = i.id
          ) 
          AND (
            EXISTS (SELECT 1 FROM purchase_invoice_receiving_allocations a WHERE a.purchase_invoice_item_id = i.id) 
            OR i.batch_id IS NOT NULL
          )
      ) THEN 
        RAISE EXCEPTION 'Cannot remove invoice line with receiving or inventory history'; 
      END IF;

      DELETE FROM purchase_invoice_items i 
      WHERE i.purchase_invoice_id = v_invoice_id 
        AND NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) x 
          WHERE NULLIF(x->>'id','')::uuid = i.id
        );

      IF v_je_id IS NOT NULL THEN
        DELETE FROM journal_entry_lines WHERE journal_entry_id = v_je_id;
        UPDATE journal_entries SET
          entry_date       = v_invoice_date,
          reference_number = v_invoice_number,
          description      = 'Purchase Invoice: ' || v_invoice_number,
          total_debit      = 0,
          total_credit     = v_total_amount * v_rate
        WHERE id = v_je_id;
      ELSE
        v_je_number := 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-' || LPAD((
          SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM '(\d+)$') AS INTEGER)), 0) + 1
          FROM journal_entries
          WHERE entry_number LIKE 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-%'
        )::TEXT, 4, '0');

        INSERT INTO journal_entries (
          entry_number, entry_date, source_module, reference_id, reference_number,
          description, total_debit, total_credit, is_posted, posted_by, created_by
        ) VALUES (
          v_je_number, v_invoice_date, 'purchase_invoice', v_invoice_id, v_invoice_number,
          'Purchase Invoice: ' || v_invoice_number,
          0, v_total_amount * v_rate, TRUE, v_created_by, v_created_by
        ) RETURNING id INTO v_je_id;

        UPDATE purchase_invoices SET journal_entry_id = v_je_id WHERE id = v_invoice_id;
      END IF;
    END IF;

    -- ── Insert/Update items and build JE debit lines ───────────────────────────
    v_line_number := 1;

    FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))
    LOOP
      v_item_type  := v_item->>'item_type';
      v_line_total := COALESCE((v_item->>'line_total')::NUMERIC(15,2), 0);
      v_item_id    := NULLIF(v_item->>'id', '')::UUID;

      IF v_item_id IS NOT NULL AND EXISTS (SELECT 1 FROM purchase_invoice_items WHERE id = v_item_id AND purchase_invoice_id = v_invoice_id) THEN
        UPDATE purchase_invoice_items SET 
          item_type                     = v_item_type, 
          product_id                    = NULLIF(v_item->>'product_id','')::UUID, 
          description                   = v_item->>'description', 
          quantity                      = COALESCE((v_item->>'quantity')::NUMERIC, 1), 
          unit                          = v_item->>'unit', 
          unit_price                    = COALESCE((v_item->>'unit_price')::NUMERIC, 0), 
          discount_percent              = (v_item->>'discount_percent')::NUMERIC, 
          line_total                    = v_line_total, 
          tax_amount                    = (v_item->>'tax_amount')::NUMERIC, 
          expense_account_id            = NULLIF(v_item->>'expense_account_id','')::UUID, 
          asset_account_id              = NULLIF(v_item->>'asset_account_id','')::UUID, 
          purchase_order_item_id        = NULLIF(v_item->>'purchase_order_item_id','')::UUID, 
          receiving_make_id             = NULLIF(v_item->>'receiving_make_id','')::UUID, 
          receiving_batch_number        = NULLIF(v_item->>'receiving_batch_number',''), 
          receiving_expiry_date         = NULLIF(v_item->>'receiving_expiry_date','')::DATE, 
          receiving_import_container_id = NULLIF(v_item->>'receiving_import_container_id','')::UUID, 
          receiving_notes               = NULLIF(v_item->>'receiving_notes','') 
        WHERE id = v_item_id;
      ELSE
        INSERT INTO purchase_invoice_items (
          purchase_invoice_id, item_type, product_id, description,
          quantity, unit, unit_price, discount_percent, line_total,
          tax_amount, expense_account_id, asset_account_id,
          purchase_order_item_id, receiving_make_id, receiving_batch_number,
          receiving_expiry_date, receiving_import_container_id, receiving_notes
        ) VALUES (
          v_invoice_id,
          v_item_type,
          NULLIF(v_item->>'product_id', '')::UUID,
          v_item->>'description',
          COALESCE((v_item->>'quantity')::NUMERIC, 1),
          v_item->>'unit',
          COALESCE((v_item->>'unit_price')::NUMERIC, 0),
          (v_item->>'discount_percent')::NUMERIC,
          v_line_total,
          (v_item->>'tax_amount')::NUMERIC,
          NULLIF(v_item->>'expense_account_id', '')::UUID,
          NULLIF(v_item->>'asset_account_id',   '')::UUID,
          NULLIF(v_item->>'purchase_order_item_id', '')::UUID,
          NULLIF(v_item->>'receiving_make_id', '')::UUID,
          NULLIF(v_item->>'receiving_batch_number', ''),
          NULLIF(v_item->>'receiving_expiry_date', '')::DATE,
          NULLIF(v_item->>'receiving_import_container_id', '')::UUID,
          NULLIF(v_item->>'receiving_notes', '')
        );
      END IF;

      IF v_item_type = 'inventory' THEN
        SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;
      ELSIF v_item_type = 'fixed_asset' THEN
        v_account_id := NULLIF(v_item->>'asset_account_id', '')::UUID;
        IF v_account_id IS NULL THEN
          SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1200' LIMIT 1;
        END IF;
      ELSE
        v_account_id := NULLIF(v_item->>'expense_account_id', '')::UUID;
        IF v_account_id IS NULL THEN
          SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '5100' LIMIT 1;
        END IF;
      END IF;

      IF v_account_id IS NOT NULL AND v_line_total <> 0 THEN
        INSERT INTO journal_entry_lines (
          journal_entry_id, line_number, account_id, description,
          debit, credit, supplier_id
        ) VALUES (
          v_je_id, v_line_number, v_account_id,
          COALESCE(LEFT(v_item->>'description', 100), 'Purchase Item'),
          v_line_total * v_rate, 0, v_supplier_id
        );
        v_line_number := v_line_number + 1;
      END IF;
    END LOOP;

    -- PPN Input debit line (DR 1150)
    IF v_tax_amount > 0 AND v_ppn_account_id IS NOT NULL THEN
      INSERT INTO journal_entry_lines (
        journal_entry_id, line_number, account_id, description,
        debit, credit, supplier_id
      ) VALUES (
        v_je_id, v_line_number, v_ppn_account_id,
        'PPN Input - ' || v_invoice_number,
        v_tax_amount * v_rate, 0, v_supplier_id
      );
      v_line_number := v_line_number + 1;
    END IF;

    -- Stamp Duty debit line (DR 6950 Bea Meterai Expense)
    IF v_stamp_duty_amount > 0 AND v_bm_account_id IS NOT NULL THEN
      INSERT INTO journal_entry_lines (
        journal_entry_id, line_number, account_id, description,
        debit, credit, supplier_id
      ) VALUES (
        v_je_id, v_line_number, v_bm_account_id,
        'Bea Meterai - ' || v_invoice_number,
        v_stamp_duty_amount * v_rate, 0, v_supplier_id
      );
      v_line_number := v_line_number + 1;
    END IF;

    -- A/P credit line (total_amount = subtotal + ppn + stamp_duty)
    INSERT INTO journal_entry_lines (
      journal_entry_id, line_number, account_id, description,
      debit, credit, supplier_id
    ) VALUES (
      v_je_id, v_line_number, v_ap_account_id,
      'A/P - ' || v_invoice_number,
      0, v_total_amount * v_rate, v_supplier_id
    );

    UPDATE journal_entries SET transaction_currency=v_currency, functional_currency='IDR', exchange_rate=v_rate, amounts_are_functional=true WHERE id=v_je_id;
    UPDATE journal_entry_lines SET transaction_currency=v_currency, exchange_rate=v_rate, transaction_debit=CASE WHEN debit>0 THEN round(debit / v_rate, 2) ELSE 0 END, transaction_credit=CASE WHEN credit>0 THEN round(credit / v_rate, 2) ELSE 0 END WHERE journal_entry_id=v_je_id;

    -- Reconcile JE totals from actual inserted lines
    UPDATE journal_entries SET
      total_debit  = (SELECT COALESCE(SUM(debit),  0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
      total_credit = (SELECT COALESCE(SUM(credit), 0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
    WHERE id = v_je_id;

    RETURN jsonb_build_object(
      'invoice_id',       v_invoice_id,
      'journal_entry_id', v_je_id
    );
  END;
$_$;


--
-- Name: save_purchase_invoice_with_receiving_details("uuid", "uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_purchase_invoice_with_receiving_details"("p_invoice_id" "uuid", "p_purchase_order_id" "uuid", "p_invoice_data" "jsonb", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_data jsonb:=coalesce(p_invoice_data,'{}'::jsonb); v_items jsonb:='[]'::jsonb; v_item jsonb; v_old public.purchase_invoice_items%rowtype; v_po uuid; v_result jsonb; v_id uuid; v_rate numeric; v_ccy text;
BEGIN
  IF p_invoice_id IS NOT NULL AND nullif(v_data->>'purchase_order_id','') IS NULL THEN SELECT purchase_order_id INTO v_po FROM purchase_invoices WHERE id=p_invoice_id; IF v_po IS NOT NULL THEN v_data:=jsonb_set(v_data,'{purchase_order_id}',to_jsonb(v_po),true); END IF; ELSIF p_invoice_id IS NULL AND p_purchase_order_id IS NOT NULL AND nullif(v_data->>'purchase_order_id','') IS NULL THEN v_data:=jsonb_set(v_data,'{purchase_order_id}',to_jsonb(p_purchase_order_id),true); END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) LOOP
    IF p_invoice_id IS NOT NULL AND nullif(v_item->>'id','') IS NOT NULL THEN SELECT * INTO v_old FROM purchase_invoice_items WHERE id=(v_item->>'id')::uuid AND purchase_invoice_id=p_invoice_id; IF FOUND THEN
      IF nullif(v_item->>'purchase_order_item_id','') IS NULL AND v_old.purchase_order_item_id IS NOT NULL THEN v_item:=jsonb_set(v_item,'{purchase_order_item_id}',to_jsonb(v_old.purchase_order_item_id),true); END IF;
      IF nullif(v_item->>'receiving_make_id','') IS NULL AND v_old.receiving_make_id IS NOT NULL THEN v_item:=jsonb_set(v_item,'{receiving_make_id}',to_jsonb(v_old.receiving_make_id),true); END IF;
      IF nullif(v_item->>'receiving_batch_number','') IS NULL AND v_old.receiving_batch_number IS NOT NULL THEN v_item:=jsonb_set(v_item,'{receiving_batch_number}',to_jsonb(v_old.receiving_batch_number),true); END IF;
      IF nullif(v_item->>'receiving_expiry_date','') IS NULL AND v_old.receiving_expiry_date IS NOT NULL THEN v_item:=jsonb_set(v_item,'{receiving_expiry_date}',to_jsonb(v_old.receiving_expiry_date),true); END IF;
      IF nullif(v_item->>'receiving_import_container_id','') IS NULL AND v_old.receiving_import_container_id IS NOT NULL THEN v_item:=jsonb_set(v_item,'{receiving_import_container_id}',to_jsonb(v_old.receiving_import_container_id),true); END IF;
      IF nullif(v_item->>'receiving_notes','') IS NULL AND v_old.receiving_notes IS NOT NULL THEN v_item:=jsonb_set(v_item,'{receiving_notes}',to_jsonb(v_old.receiving_notes),true); END IF;
    END IF; END IF; v_items:=v_items||jsonb_build_array(v_item);
  END LOOP;
  v_result:=CASE WHEN p_invoice_id IS NOT NULL THEN save_purchase_invoice(p_invoice_id,v_data,v_items) WHEN p_purchase_order_id IS NOT NULL THEN create_purchase_invoice_from_po(p_purchase_order_id,v_data,v_items) ELSE save_purchase_invoice(NULL,v_data,v_items) END;
  v_id:=(v_result->>'invoice_id')::uuid; SELECT upper(currency),exchange_rate INTO v_ccy,v_rate FROM purchase_invoices WHERE id=v_id; RETURN v_result;
END; $$;


--
-- Name: save_receipt_voucher_with_allocations("uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_receipt_voucher_with_allocations"("p_receipt_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_allocations" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_alloc jsonb;
  v_bank_currency text;
  v_currency text;
  v_rate numeric;
BEGIN
  PERFORM public._sec_check_finance_role();
  IF NULLIF(p_payload->>'customer_id','') IS NULL THEN RAISE EXCEPTION 'Customer is required'; END IF;
  IF COALESCE((p_payload->>'amount')::numeric,0) <= 0 THEN RAISE EXCEPTION 'Receipt amount must be greater than zero'; END IF;
  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=NULLIF(p_payload->>'bank_account_id','')::uuid;
  v_currency := upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''),v_bank_currency,'IDR'));
  v_rate := COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric,0),CASE WHEN v_currency='IDR' THEN 1 ELSE NULL END);
  IF v_rate IS NULL OR v_rate<=0 OR (v_currency='USD' AND v_rate<=1) THEN
    RAISE EXCEPTION 'A valid exchange rate is required for % receipts',v_currency;
  END IF;
  IF v_bank_currency IS NOT NULL AND v_bank_currency<>v_currency THEN
    RAISE EXCEPTION 'Receipt currency % does not match selected bank currency %',v_currency,v_bank_currency;
  END IF;

  IF p_receipt_id IS NULL THEN
    INSERT INTO public.receipt_vouchers(
      voucher_number,voucher_date,customer_id,payment_method,bank_account_id,reference_number,
      amount,description,created_by,currency_code,transaction_currency,functional_currency,
      exchange_rate,bank_account_currency,payment_currency
    ) VALUES (
      public.next_receipt_voucher_number((p_payload->>'voucher_date')::date),(p_payload->>'voucher_date')::date,
      (p_payload->>'customer_id')::uuid,p_payload->>'payment_method',NULLIF(p_payload->>'bank_account_id','')::uuid,
      NULLIF(p_payload->>'reference_number',''),(p_payload->>'amount')::numeric,NULLIF(p_payload->>'description',''),
      COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),v_currency,v_currency,'IDR',v_rate,
      COALESCE(v_bank_currency,v_currency),v_currency
    ) RETURNING id INTO v_id;
  ELSE
    IF EXISTS (SELECT 1 FROM public.receipt_vouchers WHERE id=p_receipt_id AND is_posted=true) THEN
      RAISE EXCEPTION 'Cannot edit a posted receipt voucher. Cancel posting first.';
    END IF;
    UPDATE public.receipt_vouchers SET
      voucher_date=(p_payload->>'voucher_date')::date,customer_id=(p_payload->>'customer_id')::uuid,
      payment_method=p_payload->>'payment_method',bank_account_id=NULLIF(p_payload->>'bank_account_id','')::uuid,
      reference_number=NULLIF(p_payload->>'reference_number',''),amount=(p_payload->>'amount')::numeric,
      description=NULLIF(p_payload->>'description',''),currency_code=v_currency,transaction_currency=v_currency,
      functional_currency='IDR',exchange_rate=v_rate,bank_account_currency=COALESCE(v_bank_currency,v_currency),
      payment_currency=v_currency,updated_at=now()
    WHERE id=p_receipt_id RETURNING id INTO v_id;
    DELETE FROM public.voucher_allocations WHERE receipt_voucher_id=v_id;
  END IF;
  FOR v_alloc IN SELECT value FROM jsonb_array_elements(COALESCE(p_allocations,'[]'::jsonb)) LOOP
    IF COALESCE((v_alloc->>'amount')::numeric,0) > 0 THEN
      INSERT INTO public.voucher_allocations(voucher_type,receipt_voucher_id,sales_invoice_id,sales_order_id,allocated_amount)
      VALUES('receipt',v_id,NULLIF(v_alloc->>'sales_invoice_id','')::uuid,
        NULLIF(v_alloc->>'sales_order_id','')::uuid,(v_alloc->>'amount')::numeric);
    END IF;
  END LOOP;
  RETURN v_id;
END;
$$;


