--
-- Name: submit_purchase_invoice_for_receiving("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."submit_purchase_invoice_for_receiving"("p_purchase_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_invoice public.purchase_invoices%ROWTYPE;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','manager']) THEN RAISE EXCEPTION 'Permission denied'; END IF;
  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id = p_purchase_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;
  IF v_invoice.status = 'cancelled' THEN RAISE EXCEPTION 'Cancelled Purchase Invoice cannot be submitted'; END IF;
  UPDATE public.purchase_invoices SET receiving_approval_status='pending_approval', receiving_submitted_at=now(), receiving_submitted_by=auth.uid(), receiving_rejection_reason=NULL, updated_at=now() WHERE id=p_purchase_invoice_id;
  RETURN jsonb_build_object('success',true,'status','pending_approval');
END; $$;


--
-- Name: sync_bank_allocation_document_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_bank_allocation_document_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_type text;
  v_document uuid;
BEGIN
  IF NEW.journal_entry_id IS NULL THEN
    RAISE EXCEPTION 'Bank allocation requires a journal target';
  END IF;

  SELECT r.document_type, r.document_id
    INTO v_type, v_document
    FROM public.resolve_bank_allocation_document(NEW.journal_entry_id) r
   LIMIT 1;
  IF v_type IS NULL THEN
    RAISE EXCEPTION 'Journal target % does not exist', NEW.journal_entry_id;
  END IF;

  -- This runs for inserts and for any metadata/journal-target update.  It
  -- makes a journal relink atomic with the document identity change, so a bank
  -- line can never point at a payment journal while retaining an expense id.
  NEW.document_type := v_type;
  NEW.document_id := v_document;
  RETURN NEW;
END;
$$;


--
-- Name: sync_bank_line_allocation_owner("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_bank_line_allocation_owner"("p_bank_line_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count integer;
  v_only public.bank_statement_allocations%ROWTYPE;
BEGIN
  SELECT count(*) INTO v_count
    FROM public.bank_statement_allocations
   WHERE bank_statement_line_id = p_bank_line_id;

  IF v_count = 1 THEN
    SELECT * INTO v_only
      FROM public.bank_statement_allocations
     WHERE bank_statement_line_id = p_bank_line_id;
    UPDATE public.bank_statement_lines SET
      matched_expense_id = CASE 
        WHEN v_only.document_type = 'expense' 
          AND NOT EXISTS (
            SELECT 1 FROM public.bank_statement_lines b 
            WHERE b.matched_expense_id = v_only.document_id 
              AND b.matching_status = 'confirmed' 
              AND b.id <> p_bank_line_id
          ) 
        THEN v_only.document_id 
      END,
      matched_receipt_id = CASE WHEN v_only.document_type = 'receipt' THEN v_only.document_id END,
      matched_payment_id = CASE WHEN v_only.document_type = 'payment' THEN v_only.document_id END,
      matched_fund_transfer_id = CASE WHEN v_only.document_type = 'fund_transfer' THEN v_only.document_id END,
      matched_petty_cash_id = CASE WHEN v_only.document_type = 'petty_cash' THEN v_only.document_id END,
      matched_tax_payment_id = CASE WHEN v_only.document_type = 'tax_payment' THEN v_only.document_id END,
      matched_entry_id = v_only.journal_entry_id,
      payment_kind = v_only.payment_kind
    WHERE id = p_bank_line_id;
  ELSE
    UPDATE public.bank_statement_lines SET
      matched_expense_id = NULL,
      matched_receipt_id = NULL,
      matched_payment_id = NULL,
      matched_fund_transfer_id = NULL,
      matched_petty_cash_id = NULL,
      matched_tax_payment_id = NULL,
      matched_entry_id = NULL
    WHERE id = p_bank_line_id;
  END IF;
END;
$$;


--
-- Name: sync_bank_line_from_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_bank_line_from_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old_line uuid;
  v_new_line uuid;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    v_old_line := OLD.bank_statement_line_id;
    PERFORM public.sync_bank_line_allocation_owner(v_old_line);
    PERFORM public.refresh_bank_statement_allocation_status(v_old_line);
    IF NOT public.historical_repair_context_active() THEN
      IF OLD.document_type = 'expense' AND EXISTS (
        SELECT 1 FROM public.finance_expenses WHERE id = OLD.document_id
      ) THEN
        PERFORM public.recalculate_expense_payment_state(OLD.document_id);
      ELSIF OLD.document_type = 'tax_payment' THEN
        UPDATE public.tax_payments SET status = 'posted' WHERE id = OLD.document_id
          AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE document_type = 'tax_payment' AND document_id = OLD.document_id);
      END IF;
    END IF;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    v_new_line := NEW.bank_statement_line_id;
    IF v_new_line IS DISTINCT FROM v_old_line THEN
      PERFORM public.sync_bank_line_allocation_owner(v_new_line);
      PERFORM public.refresh_bank_statement_allocation_status(v_new_line);
    END IF;
    IF NOT public.historical_repair_context_active() THEN
      IF NEW.document_type = 'expense' AND EXISTS (SELECT 1 FROM public.finance_expenses WHERE id = NEW.document_id) THEN
        PERFORM public.recalculate_expense_payment_state(NEW.document_id);
      ELSIF NEW.document_type = 'tax_payment' THEN
        UPDATE public.tax_payments SET status = 'reconciled' WHERE id = NEW.document_id;
      END IF;
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sync_expense_from_bank_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_expense_from_bank_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_old_expense uuid; v_new_expense uuid; v_old_date date; v_new_date date; v_fallback date;
BEGIN
  IF public.historical_repair_context_active() THEN RETURN COALESCE(NEW, OLD); END IF;
  IF TG_OP IN ('UPDATE','DELETE') AND OLD.document_type='expense' THEN
    v_old_expense:=OLD.document_id;
    SELECT transaction_date INTO v_old_date FROM public.bank_statement_lines WHERE id=OLD.bank_statement_line_id;
    PERFORM public.recalculate_expense_payment_state(v_old_expense);
    IF EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=v_old_expense AND (COALESCE(pph_amount,0)>0 OR COALESCE(pib_pph_amount,0)>0 OR expense_category='pph_import')) THEN
      PERFORM public.recompute_pph_periods_for_date(v_old_date);
      PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_old_expense));
      SELECT COALESCE(due_date,expense_date) INTO v_fallback FROM public.finance_expenses WHERE id=v_old_expense;
      PERFORM public.recompute_pph_periods_for_date(v_fallback);
    END IF;
  END IF;
  IF TG_OP IN ('INSERT','UPDATE') AND NEW.document_type='expense' THEN
    v_new_expense:=NEW.document_id;
    SELECT transaction_date INTO v_new_date FROM public.bank_statement_lines WHERE id=NEW.bank_statement_line_id;
    PERFORM public.recalculate_expense_payment_state(v_new_expense);
    IF EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=v_new_expense AND (COALESCE(pph_amount,0)>0 OR COALESCE(pib_pph_amount,0)>0 OR expense_category='pph_import')) THEN
      PERFORM public.recompute_pph_periods_for_date(v_new_date);
      PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_new_expense));
      SELECT COALESCE(due_date,expense_date) INTO v_fallback FROM public.finance_expenses WHERE id=v_new_expense;
      PERFORM public.recompute_pph_periods_for_date(v_fallback);
    END IF;
  END IF;
  RETURN COALESCE(NEW,OLD);
END;
$$;


--
-- Name: sync_expense_journal_currency_and_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_expense_journal_currency_and_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_je uuid;
  v_currency text:=upper(COALESCE(NEW.transaction_currency,NEW.currency_code,'IDR'));
  v_rate numeric:=CASE WHEN upper(COALESCE(NEW.transaction_currency,NEW.currency_code,'IDR'))='IDR'
    THEN 1 ELSE NEW.exchange_rate END;
BEGIN
  IF NEW.approval_status IS DISTINCT FROM 'approved' THEN
    IF OLD.approval_status='approved' AND EXISTS(
      SELECT 1 FROM public.journal_entries WHERE source_module IN('expense','expenses')
        AND (reference_id=NEW.id OR reference_number='EXP-'||NEW.id::text)
        AND COALESCE(is_reversed,false)=false
    ) THEN
      RAISE EXCEPTION 'Use Cancel Posting so the journal removal is period-checked and audited';
    END IF;
    RETURN NEW;
  END IF;
  IF COALESCE(current_setting('app.finance_historical_repair',true),'off')='on' THEN RETURN NEW; END IF;

  SELECT id INTO v_je
    FROM public.journal_entries
   WHERE source_module='expenses'
     AND (reference_id=NEW.id OR reference_number='EXP-'||NEW.id::text)
     AND is_posted=true AND COALESCE(is_reversed,false)=false
   ORDER BY created_at DESC LIMIT 1;
  IF v_je IS NULL THEN
    RAISE EXCEPTION 'Approved expense % has no active journal entry',NEW.id;
  END IF;
  IF v_currency NOT IN ('IDR','USD') OR v_rate IS NULL OR v_rate<=0 THEN
    RAISE EXCEPTION 'Approved expense % has invalid currency metadata',NEW.id;
  END IF;

  -- Metadata-only historical repair must never rewrite accounting history.
  IF COALESCE(current_setting('app.finance_historical_repair',true),'off') <> 'on' THEN
    UPDATE public.journal_entry_lines
       SET transaction_currency=v_currency,
           transaction_debit=COALESCE(transaction_debit,debit),
           transaction_credit=COALESCE(transaction_credit,credit),
           functional_currency='IDR',exchange_rate=v_rate,
           debit=round(COALESCE(transaction_debit,debit)*v_rate,2),
           credit=round(COALESCE(transaction_credit,credit)*v_rate,2)
     WHERE journal_entry_id=v_je;
    UPDATE public.journal_entries je
       SET transaction_currency=v_currency,functional_currency='IDR',exchange_rate=v_rate,
           amounts_are_functional=true,
           total_debit=(SELECT COALESCE(sum(debit),0) FROM public.journal_entry_lines WHERE journal_entry_id=v_je),
           total_credit=(SELECT COALESCE(sum(credit),0) FROM public.journal_entry_lines WHERE journal_entry_id=v_je)
     WHERE je.id=v_je;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_expense_payment_state_from_allocations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_expense_payment_state_from_allocations"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- On INSERT or UPDATE, recalculate for the new expense
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.finance_expense_id IS NOT NULL THEN
    PERFORM public.recalculate_expense_payment_state(NEW.finance_expense_id);
  END IF;

  -- On UPDATE or DELETE, recalculate for the old expense (if different)
  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.finance_expense_id IS NOT NULL THEN
    IF TG_OP = 'DELETE'
       OR OLD.finance_expense_id IS DISTINCT FROM NEW.finance_expense_id
       OR OLD.allocated_amount   IS DISTINCT FROM NEW.allocated_amount
       OR OLD.voucher_type       IS DISTINCT FROM NEW.voucher_type
    THEN
      PERFORM public.recalculate_expense_payment_state(OLD.finance_expense_id);
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sync_fund_transfer_journal_currency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_fund_transfer_journal_currency"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_from_currency text;
  v_to_currency text;
  v_rate numeric;
  v_functional numeric;
BEGIN
  IF NEW.journal_entry_id IS NULL OR NEW.status<>'posted' THEN RETURN NEW; END IF;
  IF COALESCE(current_setting('app.finance_historical_repair',true),'off')='on' THEN RETURN NEW; END IF;
  v_from_currency:=CASE WHEN NEW.from_account_type='bank'
    THEN (SELECT upper(currency) FROM public.bank_accounts WHERE id=NEW.from_bank_account_id) ELSE 'IDR' END;
  v_to_currency:=CASE WHEN NEW.to_account_type='bank'
    THEN (SELECT upper(currency) FROM public.bank_accounts WHERE id=NEW.to_bank_account_id) ELSE 'IDR' END;
  IF v_from_currency NOT IN('IDR','USD') OR v_to_currency NOT IN('IDR','USD') THEN
    RAISE EXCEPTION 'Unsupported Fund Transfer currency';
  END IF;
  IF v_from_currency='IDR' AND v_to_currency='IDR' THEN
    IF abs(NEW.from_amount-NEW.to_amount)>0.01 THEN RAISE EXCEPTION 'IDR Fund Transfer amounts must match'; END IF;
    v_rate:=1; v_functional:=NEW.from_amount;
  ELSIF v_from_currency='IDR' AND v_to_currency='USD' THEN
    IF NEW.to_amount<=0 THEN RAISE EXCEPTION 'USD destination amount is required'; END IF;
    v_rate:=NEW.from_amount/NEW.to_amount; v_functional:=NEW.from_amount;
  ELSIF v_from_currency='USD' AND v_to_currency='IDR' THEN
    IF NEW.from_amount<=0 THEN RAISE EXCEPTION 'USD source amount is required'; END IF;
    v_rate:=NEW.to_amount/NEW.from_amount; v_functional:=NEW.to_amount;
  ELSE
    IF abs(NEW.from_amount-NEW.to_amount)>0.01 THEN RAISE EXCEPTION 'Same-currency USD Fund Transfer amounts must match'; END IF;
    v_rate:=COALESCE(NULLIF(NEW.exchange_rate,0),public.get_reporting_usd_rate());
    IF v_rate<=1 THEN v_rate:=public.get_reporting_usd_rate(); END IF;
    IF v_rate IS NULL OR v_rate<=1 THEN RAISE EXCEPTION 'A valid USD-to-IDR rate is required'; END IF;
    v_functional:=NEW.from_amount*v_rate;
  END IF;
  IF v_rate IS NULL OR v_rate<=0 THEN RAISE EXCEPTION 'Invalid Fund Transfer exchange rate'; END IF;

  UPDATE public.journal_entry_lines SET
    debit=CASE WHEN line_number=1 THEN round(v_functional,2) ELSE 0 END,
    credit=CASE WHEN line_number=2 THEN round(v_functional,2) ELSE 0 END,
    transaction_currency=CASE WHEN line_number=1 THEN v_to_currency ELSE v_from_currency END,
    transaction_debit=CASE WHEN line_number=1 THEN NEW.to_amount ELSE 0 END,
    transaction_credit=CASE WHEN line_number=2 THEN NEW.from_amount ELSE 0 END,
    functional_currency='IDR',
    exchange_rate=CASE
      WHEN line_number=1 AND v_to_currency='USD' THEN v_rate
      WHEN line_number=2 AND v_from_currency='USD' THEN v_rate
      ELSE 1 END
  WHERE journal_entry_id=NEW.journal_entry_id AND line_number IN(1,2);
  UPDATE public.journal_entries SET transaction_currency=CASE WHEN v_from_currency=v_to_currency THEN v_from_currency ELSE 'IDR' END,
    functional_currency='IDR',exchange_rate=v_rate,amounts_are_functional=true,
    total_debit=round(v_functional,2),total_credit=round(v_functional,2)
  WHERE id=NEW.journal_entry_id;
  RETURN NEW;
END;
$$;


--
-- Name: sync_payment_journal_currency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_payment_journal_currency"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice_currency text:=upper(COALESCE(NEW.invoice_currency,NEW.transaction_currency,NEW.currency_code,'IDR'));
  v_rate numeric:=COALESCE(NEW.exchange_rate,1);
BEGIN
  IF COALESCE(NEW.is_posted,false)=false OR NEW.journal_entry_id IS NULL THEN RETURN NEW; END IF;
  IF COALESCE(current_setting('app.finance_historical_repair',true),'off')='on' THEN RETURN NEW; END IF;
  IF v_invoice_currency NOT IN('IDR','USD') OR v_rate<=0 THEN
    RAISE EXCEPTION 'Posted payment has invalid currency metadata';
  END IF;

  -- The canonical poster owns the numerical amounts. Fill metadata only.
  UPDATE public.journal_entry_lines
     SET transaction_currency=COALESCE(transaction_currency,v_invoice_currency),
         transaction_debit=COALESCE(transaction_debit,
           CASE WHEN COALESCE(exchange_rate,1)>0 THEN debit/COALESCE(exchange_rate,1) ELSE debit END),
         transaction_credit=COALESCE(transaction_credit,
           CASE WHEN COALESCE(exchange_rate,1)>0 THEN credit/COALESCE(exchange_rate,1) ELSE credit END),
         functional_currency='IDR',
         exchange_rate=COALESCE(exchange_rate,CASE WHEN v_invoice_currency='USD' THEN v_rate ELSE 1 END)
   WHERE journal_entry_id=NEW.journal_entry_id;

  UPDATE public.journal_entries SET
    transaction_currency=v_invoice_currency,functional_currency='IDR',exchange_rate=v_rate,
    amounts_are_functional=true,
    total_debit=(SELECT COALESCE(sum(debit),0) FROM public.journal_entry_lines WHERE journal_entry_id=NEW.journal_entry_id),
    total_credit=(SELECT COALESCE(sum(credit),0) FROM public.journal_entry_lines WHERE journal_entry_id=NEW.journal_entry_id)
  WHERE id=NEW.journal_entry_id;
  RETURN NEW;
END;
$$;


--
-- Name: sync_pi_state_on_pv_posting_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_pi_state_on_pv_posting_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice_id uuid;
BEGIN
  IF COALESCE(OLD.is_posted, FALSE) IS DISTINCT FROM COALESCE(NEW.is_posted, FALSE) THEN
    FOR v_invoice_id IN
      SELECT DISTINCT purchase_invoice_id
      FROM public.voucher_allocations
      WHERE payment_voucher_id = NEW.id
        AND voucher_type = 'payment'
        AND purchase_invoice_id IS NOT NULL
    LOOP
      PERFORM public.recalculate_purchase_invoice_payment_state(v_invoice_id);
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_purchase_invoice_payment_state_from_allocations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_purchase_invoice_payment_state_from_allocations"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.purchase_invoice_id IS NOT NULL THEN
PERFORM public.recalculate_purchase_invoice_payment_state(NEW.purchase_invoice_id);
END IF;

IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.purchase_invoice_id IS NOT NULL THEN
IF TG_OP = 'DELETE'
OR OLD.purchase_invoice_id IS DISTINCT FROM NEW.purchase_invoice_id
OR OLD.allocated_amount IS DISTINCT FROM NEW.allocated_amount
OR OLD.voucher_type IS DISTINCT FROM NEW.voucher_type THEN
PERFORM public.recalculate_purchase_invoice_payment_state(OLD.purchase_invoice_id);
END IF;
END IF;

RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sync_receipt_journal_currency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_receipt_journal_currency"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_currency text:=upper(COALESCE(NEW.transaction_currency,NEW.currency_code,'IDR'));
  v_rate numeric:=CASE WHEN upper(COALESCE(NEW.transaction_currency,NEW.currency_code,'IDR'))='IDR' THEN 1 ELSE NEW.exchange_rate END;
BEGIN
  IF COALESCE(NEW.is_posted,false)=false OR NEW.journal_entry_id IS NULL THEN RETURN NEW; END IF;
  IF COALESCE(current_setting('app.finance_historical_repair',true),'off')='on' THEN RETURN NEW; END IF;
  IF v_currency NOT IN('IDR','USD') OR v_rate IS NULL OR v_rate<=0 THEN RAISE EXCEPTION 'Posted receipt has invalid currency metadata'; END IF;
  UPDATE public.journal_entry_lines SET transaction_currency=v_currency,
    transaction_debit=COALESCE(transaction_debit,debit),transaction_credit=COALESCE(transaction_credit,credit),
    functional_currency='IDR',exchange_rate=v_rate,
    debit=round(COALESCE(transaction_debit,debit)*v_rate,2),credit=round(COALESCE(transaction_credit,credit)*v_rate,2)
  WHERE journal_entry_id=NEW.journal_entry_id;
  UPDATE public.journal_entries SET transaction_currency=v_currency,functional_currency='IDR',exchange_rate=v_rate,
    amounts_are_functional=true,
    total_debit=(SELECT COALESCE(sum(debit),0) FROM public.journal_entry_lines WHERE journal_entry_id=NEW.journal_entry_id),
    total_credit=(SELECT COALESCE(sum(credit),0) FROM public.journal_entry_lines WHERE journal_entry_id=NEW.journal_entry_id)
  WHERE id=NEW.journal_entry_id;
  RETURN NEW;
END $$;


--
-- Name: sync_sales_invoice_balance_cache(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_sales_invoice_balance_cache"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.paid_amount := GREATEST(COALESCE(NEW.paid_amount, 0), 0);
  IF NEW.paid_amount > COALESCE(NEW.total_amount, 0) + 0.01 THEN
    RAISE EXCEPTION 'Invoice paid amount cannot exceed total amount';
  END IF;
  NEW.balance_amount := GREATEST(COALESCE(NEW.total_amount, 0) - NEW.paid_amount, 0);
  RETURN NEW;
END;
$$;


--
-- Name: sync_sole_allocation_from_legacy_unlink(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_sole_allocation_from_legacy_unlink"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_allocation_id uuid;
BEGIN
  IF OLD.matched_expense_id IS NOT NULL AND NEW.matched_expense_id IS NULL
     AND (SELECT count(*) FROM public.bank_statement_allocations WHERE bank_statement_line_id=NEW.id)=1 THEN
    SELECT id INTO v_allocation_id
    FROM public.bank_statement_allocations
    WHERE bank_statement_line_id=NEW.id
      AND document_type='expense' AND document_id=OLD.matched_expense_id
    LIMIT 1;
    IF v_allocation_id IS NOT NULL THEN
      DELETE FROM public.bank_statement_allocations WHERE id=v_allocation_id;
      PERFORM public.recalculate_expense_payment_state(OLD.matched_expense_id);
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: tg_touch_finance_master_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."tg_touch_finance_master_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: track_stock_levels_in_transaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."track_stock_levels_in_transaction"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
NEW.stock_before := (
SELECT current_stock
FROM batches
WHERE id = NEW.batch_id
);

NEW.stock_after := NEW.stock_before + NEW.quantity;

RETURN NEW;
END;
$$;


--
-- Name: trg_auto_release_reservation_on_dc_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_auto_release_reservation_on_dc_item"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_so_id          uuid;
  v_dc_status      text;
  v_reservation    RECORD;
  v_remaining_qty  numeric;
  v_release_qty    numeric;
BEGIN
  -- Only release reservations when the DC is already approved.
  -- During DC CREATE (pending_approval) or EDIT (pending), items are inserted
  -- but reservations must NOT be released — stock has not been physically dispatched.
  -- The canonical release path is trg_dc_approval_deduct_stock (UPDATE trigger).
  SELECT approval_status::text, sales_order_id
    INTO v_dc_status, v_so_id
  FROM delivery_challans
  WHERE id = NEW.challan_id;

  IF v_dc_status IS DISTINCT FROM 'approved' THEN
    RETURN NEW;
  END IF;

  IF v_so_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_remaining_qty := NEW.quantity;

  -- Release active reservations for this SO + product, any batch, FIFO
  FOR v_reservation IN
    SELECT id, reserved_quantity
    FROM stock_reservations
    WHERE sales_order_id = v_so_id
      AND product_id     = NEW.product_id
      AND status         = 'active'
    ORDER BY reserved_at ASC
  LOOP
    EXIT WHEN v_remaining_qty <= 0;
    v_release_qty := LEAST(v_remaining_qty, v_reservation.reserved_quantity);

    IF v_release_qty >= v_reservation.reserved_quantity THEN
      UPDATE stock_reservations
      SET status = 'released', is_released = true, released_at = now()
      WHERE id = v_reservation.id;
    ELSE
      UPDATE stock_reservations
      SET reserved_quantity = reserved_quantity - v_release_qty
      WHERE id = v_reservation.id;
    END IF;

    v_remaining_qty := v_remaining_qty - v_release_qty;
  END LOOP;

  -- If all reservations for this SO are gone, mark SO delivered
  IF NOT EXISTS (
    SELECT 1 FROM stock_reservations
    WHERE sales_order_id = v_so_id
      AND status = 'active'
  ) THEN
    UPDATE sales_orders
    SET status = 'delivered'::sales_order_status, updated_at = now()
    WHERE id = v_so_id
      AND status NOT IN (
        'delivered'::sales_order_status,
        'closed'::sales_order_status,
        'cancelled'::sales_order_status,
        'rejected'::sales_order_status
      );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_create_batch_from_grn(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_create_batch_from_grn"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_grn_record RECORD;
v_batch_id UUID;
v_batch_number TEXT;
BEGIN
-- Only process when GRN status changes to 'posted'
IF TG_OP = 'UPDATE' AND NEW.status = 'posted' AND OLD.status = 'draft' THEN

-- Get GRN details
SELECT grn_number, supplier_id, grn_date, created_by
INTO v_grn_record
FROM goods_receipt_notes WHERE id = NEW.id;

-- Process each GRN item
FOR v_grn_record IN
SELECT * FROM goods_receipt_items WHERE grn_id = NEW.id
LOOP
-- Generate batch number if not provided
IF v_grn_record.batch_number IS NULL OR v_grn_record.batch_number = '' THEN
v_batch_number := 'BATCH-' || TO_CHAR(NOW(), 'YYMMDD') || '-' || LPAD((
SELECT COUNT(*) + 1 FROM batches WHERE batch_number LIKE 'BATCH-' || TO_CHAR(NOW(), 'YYMMDD') || '%'
)::TEXT, 4, '0');
ELSE
v_batch_number := v_grn_record.batch_number;
END IF;

-- Create batch
INSERT INTO batches (
product_id,
supplier_id,
batch_number,
purchase_date,
expiry_date,
manufacture_date,
quantity_purchased,
current_stock,
cost_per_unit,
currency,
created_by
) VALUES (
v_grn_record.product_id,
NEW.supplier_id,
v_batch_number,
NEW.grn_date,
v_grn_record.expiry_date,
v_grn_record.manufacture_date,
v_grn_record.quantity_received,
v_grn_record.quantity_received,
v_grn_record.unit_cost,
NEW.currency,
NEW.created_by
)
RETURNING id INTO v_batch_id;

-- Update GRN item with batch_id
UPDATE goods_receipt_items
SET batch_id = v_batch_id
WHERE id = v_grn_record.id;

-- Create inventory transaction
INSERT INTO inventory_transactions (
product_id,
batch_id,
transaction_type,
quantity,
transaction_date,
reference_number,
reference_type,
reference_id,
notes,
created_by,
stock_before,
stock_after
) VALUES (
v_grn_record.product_id,
v_batch_id,
'purchase',
v_grn_record.quantity_received,
NEW.grn_date,
NEW.grn_number,
'goods_receipt_note',
NEW.id,
'GRN: ' || NEW.grn_number,
NEW.created_by,
0,
v_grn_record.quantity_received
);
END LOOP;

-- Update PO received quantities if PO is linked
IF NEW.po_id IS NOT NULL THEN
UPDATE purchase_order_items poi
SET quantity_received = quantity_received + gri.quantity_received
FROM goods_receipt_items gri
WHERE poi.id = gri.po_item_id
AND gri.grn_id = NEW.id;

-- Update PO status
UPDATE purchase_orders po
SET status = CASE
WHEN (SELECT SUM(quantity_received) FROM purchase_order_items WHERE po_id = po.id) >= 
(SELECT SUM(quantity) FROM purchase_order_items WHERE po_id = po.id) THEN 'received'
WHEN (SELECT SUM(quantity_received) FROM purchase_order_items WHERE po_id = po.id) > 0 THEN 'partially_received'
ELSE po.status
END
WHERE po.id = NEW.po_id;
END IF;

-- Set posted timestamp
NEW.posted_at := NOW();
NEW.posted_by := auth.uid();
END IF;

RETURN NEW;
END;
$$;


--
-- Name: trg_credit_note_inventory_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_credit_note_inventory_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item record;
BEGIN
  IF NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved' THEN
    IF EXISTS (
      SELECT 1
      FROM public.inventory_transactions
      WHERE reference_type = 'credit_note_reversal'
        AND reference_id = NEW.id
        AND metadata->>'canonical_engine_version' = '1.0'
    ) THEN
      RAISE EXCEPTION 'Reversed Credit Note cannot be re-approved; create a new Credit Note';
    END IF;

    FOR v_item IN
      SELECT *
      FROM public.credit_note_items
      WHERE credit_note_id = NEW.id
      ORDER BY id
    LOOP
      PERFORM public.post_inventory_movement(
        public.uuid_from_text('inventory-v1:credit-note:' || NEW.id || ':' || v_item.id),
        v_item.product_id,
        v_item.batch_id,
        'return',
        v_item.quantity,
        NEW.credit_note_date,
        NEW.credit_note_number,
        'credit_note',
        NEW.id,
        'Canonical Credit Note return: ' || NEW.credit_note_number,
        NEW.approved_by,
        NULL,
        NULL
      );
    END LOOP;
  ELSIF OLD.status = 'approved' AND NEW.status IS DISTINCT FROM 'approved' THEN
    FOR v_item IN
      SELECT *
      FROM public.credit_note_items
      WHERE credit_note_id = NEW.id
      ORDER BY id
    LOOP
      PERFORM public.post_inventory_movement(
        public.uuid_from_text(
          'inventory-v1:credit-note-reversal:' || NEW.id || ':' || v_item.id
        ),
        v_item.product_id,
        v_item.batch_id,
        'adjustment',
        -v_item.quantity,
        CURRENT_DATE,
        NEW.credit_note_number,
        'credit_note_reversal',
        NEW.id,
        'Canonical Credit Note reversal: ' || NEW.credit_note_number,
        COALESCE(NEW.approved_by, auth.uid()),
        NULL,
        NULL
      );
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_credit_note_item_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_credit_note_item_inventory"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_credit_note_number text;
v_user_id uuid;
BEGIN
IF TG_OP = 'INSERT' THEN
-- Get credit note details
SELECT cn.credit_note_number, cn.created_by
INTO v_credit_note_number, v_user_id
FROM credit_notes cn
WHERE cn.id = NEW.credit_note_id;

-- Create inventory transaction to ADD stock back (positive quantity)
INSERT INTO inventory_transactions (
product_id,
batch_id,
transaction_type,
quantity,
transaction_date,
reference_number,
notes,
created_by
) VALUES (
NEW.product_id,
NEW.batch_id,
'return',
NEW.quantity,  -- Positive to add stock back
(SELECT credit_note_date FROM credit_notes WHERE id = NEW.credit_note_id),
v_credit_note_number,
'Credit note (return): ' || v_credit_note_number,
v_user_id
);

RETURN NEW;

ELSIF TG_OP = 'DELETE' THEN
-- Get credit note number
SELECT cn.credit_note_number
INTO v_credit_note_number
FROM credit_notes cn
WHERE cn.id = OLD.credit_note_id;

-- Reverse the return by deducting stock again
INSERT INTO inventory_transactions (
product_id,
batch_id,
transaction_type,
quantity,
transaction_date,
reference_number,
notes,
created_by
) VALUES (
OLD.product_id,
OLD.batch_id,
'adjustment',
-OLD.quantity,  -- Negative to remove stock
CURRENT_DATE,
v_credit_note_number,
'Reversed credit note from deleted item',
auth.uid()
);

RETURN OLD;
END IF;
END;
$$;


--
-- Name: FUNCTION "trg_credit_note_item_inventory"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."trg_credit_note_item_inventory"() IS 'Handles inventory transactions for credit notes (adds stock back)';


--
-- Name: trg_credit_note_item_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_credit_note_item_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_credit_note_number text;
v_user_id uuid;
v_current_stock numeric;
v_old_status text;
v_new_status text;
BEGIN
IF TG_OP = 'UPDATE' THEN
-- Get old and new status
SELECT status INTO v_old_status
FROM credit_notes WHERE id = OLD.credit_note_id;

SELECT status INTO v_new_status
FROM credit_notes WHERE id = NEW.credit_note_id;

-- Only act when status changes to 'approved'
IF v_new_status = 'approved' AND v_old_status != 'approved' THEN
-- Get credit note details
SELECT credit_note_number, created_by
INTO v_credit_note_number, v_user_id
FROM credit_notes WHERE id = NEW.credit_note_id;

-- Get current stock
SELECT current_stock INTO v_current_stock
FROM batches WHERE id = NEW.batch_id;

-- DIRECTLY UPDATE BATCH STOCK (add back)
UPDATE batches
SET current_stock = current_stock + NEW.quantity
WHERE id = NEW.batch_id;

-- Log transaction
INSERT INTO inventory_transactions (
product_id, batch_id, transaction_type, quantity,
transaction_date, reference_number, reference_type, reference_id,
notes, created_by, stock_before, stock_after
) VALUES (
NEW.product_id, NEW.batch_id, 'return', NEW.quantity,
CURRENT_DATE, v_credit_note_number, 'credit_note_item', NEW.id,
'Credit note approved (return): ' || v_credit_note_number, v_user_id,
v_current_stock, v_current_stock + NEW.quantity
);
END IF;
END IF;

RETURN NEW;
END;
$$;


--
-- Name: trg_dc_approval_deduct_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_dc_approval_deduct_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item record;
BEGIN
  IF NEW.approval_status = 'approved'
     AND OLD.approval_status IS DISTINCT FROM 'approved' THEN
    IF NEW.approval_operation_id IS NULL THEN
      RAISE EXCEPTION 'approval_operation_id is required for DC approval';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.inventory_transactions
      WHERE reference_type = 'delivery_challan_reversal'
        AND reference_id = NEW.id
        AND metadata->>'canonical_engine_version' = '1.0'
    ) THEN
      RAISE EXCEPTION 'Reversed Delivery Challan cannot be re-approved; create a new DC';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.delivery_challan_items
      WHERE challan_id = NEW.id
    ) THEN
      RAISE EXCEPTION 'Cannot approve Delivery Challan % without items',
        NEW.challan_number;
    END IF;

    FOR v_item IN
      SELECT *
      FROM public.delivery_challan_items
      WHERE challan_id = NEW.id
      ORDER BY id
    LOOP
      PERFORM public.inventory_v1_consume_reservation(
        NEW.sales_order_id,
        v_item.product_id,
        v_item.batch_id,
        v_item.quantity,
        NEW.approved_by
      );

      PERFORM public.post_inventory_movement(
        public.uuid_from_text(
          'inventory-v1:dc:' || NEW.approval_operation_id || ':' || v_item.id
        ),
        v_item.product_id,
        v_item.batch_id,
        'delivery_challan',
        -v_item.quantity,
        NEW.challan_date,
        NEW.challan_number,
        'delivery_challan',
        NEW.id,
        'Canonical Delivery Challan approval: ' || NEW.challan_number,
        NEW.approved_by,
        NULL,
        NULL
      );
    END LOOP;

    IF NEW.sales_order_id IS NOT NULL THEN
      PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_dc_approval_product_reservation_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_dc_approval_product_reservation_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r record;
BEGIN
  IF NEW.approval_status='approved'
     AND OLD.approval_status IN ('rejected','cancelled') THEN
    RAISE EXCEPTION 'Reversed Delivery Challan cannot be re-approved; create a new Delivery Challan';
  END IF;

  IF NEW.approval_status='approved'
     AND OLD.approval_status IS DISTINCT FROM 'approved' THEN
    IF NEW.approval_operation_id IS NULL THEN
      RAISE EXCEPTION 'approval_operation_id is required';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.delivery_challan_items WHERE challan_id=NEW.id) THEN
      RAISE EXCEPTION 'Cannot approve Delivery Challan % without items',NEW.challan_number;
    END IF;
    FOR r IN
      SELECT id FROM public.delivery_challan_items WHERE challan_id=NEW.id ORDER BY id
    LOOP
      PERFORM public.consume_so_product_reservation_v2(
        r.id,NEW.approval_operation_id,NEW.approved_by
      );
    END LOOP;
    PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_dc_approval_recompute_so(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_dc_approval_recompute_so"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.approval_status = 'approved'
     AND (OLD.approval_status IS DISTINCT FROM 'approved')
     AND NEW.sales_order_id IS NOT NULL THEN
    PERFORM fn_recompute_so_delivered(NEW.sales_order_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_dc_approval_validate_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_dc_approval_validate_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_item RECORD;
v_available_stock numeric;
v_product_name text;
v_batch_number text;
v_unit text;
BEGIN
-- Only validate when status changes to 'approved'
IF NEW.approval_status = 'approved' AND (OLD.approval_status IS NULL OR OLD.approval_status != 'approved') THEN

-- Check stock for all items
FOR v_item IN
SELECT dci.*, p.product_name, p.unit, b.batch_number, b.current_stock, b.reserved_stock
FROM delivery_challan_items dci
JOIN products p ON dci.product_id = p.id
JOIN batches b ON dci.batch_id = b.id
WHERE dci.challan_id = NEW.id
LOOP
-- Calculate available stock
v_available_stock := v_item.current_stock;

-- Check if enough stock
IF v_available_stock < v_item.quantity THEN
RAISE EXCEPTION 'Insufficient stock for batch %!

Product: %
Batch: %
Available: % %
Requested: % %

Please reduce quantity or select a different batch.',
v_item.batch_number,
v_item.product_name,
v_item.batch_number,
v_available_stock,
COALESCE(v_item.unit, 'units'),
v_item.quantity,
COALESCE(v_item.unit, 'units');
END IF;
END LOOP;

END IF;

RETURN NEW;
END;
$$;


--
-- Name: trg_dc_cancellation_release_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_dc_cancellation_release_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item          RECORD;
  v_current_stock numeric;
  v_was_approved  boolean;
BEGIN
  IF NEW.approval_status <> 'cancelled' THEN
    RETURN NEW;
  END IF;
  IF OLD.approval_status = 'cancelled' THEN
    RETURN NEW;
  END IF;

  v_was_approved := (OLD.approval_status = 'approved');

  IF v_was_approved THEN
    -- DC was approved → stock was deducted → reverse the deduction
    FOR v_item IN
      SELECT * FROM delivery_challan_items WHERE challan_id = NEW.id
    LOOP
      SELECT current_stock INTO v_current_stock FROM batches WHERE id = v_item.batch_id;

      UPDATE batches
         SET current_stock = current_stock + v_item.quantity,
             updated_at = now()
       WHERE id = v_item.batch_id;

      INSERT INTO inventory_transactions (
        product_id, batch_id, transaction_type, quantity,
        transaction_date, reference_number, reference_type, reference_id,
        notes, created_by, stock_before, stock_after
      ) VALUES (
        v_item.product_id, v_item.batch_id, 'adjustment', v_item.quantity,
        CURRENT_DATE, NEW.challan_number, 'dc_cancelled', NEW.id,
        'Reversed delivery from cancelled (previously approved) DC: ' || NEW.challan_number,
        COALESCE(NEW.rejected_by, NEW.approved_by),
        v_current_stock, v_current_stock + v_item.quantity
      );
    END LOOP;
  END IF;
  -- Non-approved DC: reservation is still active (correct); no stock was deducted.
  -- No action needed on batches.reserved_stock.

  IF NEW.sales_order_id IS NOT NULL THEN
    PERFORM fn_recompute_so_delivered(NEW.sales_order_id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_dc_rejection_release_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_dc_rejection_release_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item          RECORD;
  v_current_stock numeric;
  v_was_approved  boolean;
BEGIN
  IF NEW.approval_status <> 'rejected' THEN
    RETURN NEW;
  END IF;
  IF OLD.approval_status = 'rejected' THEN
    RETURN NEW;
  END IF;

  v_was_approved := (OLD.approval_status = 'approved');

  IF v_was_approved THEN
    -- DC was approved → stock was deducted → reverse the deduction
    FOR v_item IN
      SELECT * FROM delivery_challan_items WHERE challan_id = NEW.id
    LOOP
      SELECT current_stock INTO v_current_stock FROM batches WHERE id = v_item.batch_id;

      UPDATE batches
         SET current_stock = current_stock + v_item.quantity,
             updated_at = now()
       WHERE id = v_item.batch_id;

      INSERT INTO inventory_transactions (
        product_id, batch_id, transaction_type, quantity,
        transaction_date, reference_number, reference_type, reference_id,
        notes, created_by, stock_before, stock_after
      ) VALUES (
        v_item.product_id, v_item.batch_id, 'adjustment', v_item.quantity,
        CURRENT_DATE, NEW.challan_number, 'dc_rejected', NEW.id,
        'Reversed delivery from rejected (previously approved) DC: ' || NEW.challan_number,
        COALESCE(NEW.rejected_by, NEW.approved_by),
        v_current_stock, v_current_stock + v_item.quantity
      );
    END LOOP;
  END IF;
  -- Non-approved DC: reservation is still active (correct); no stock was deducted.
  -- No action needed on batches.reserved_stock — trg_sync_batch_reserved_stock
  -- keeps it accurate from stock_reservations.

  -- Re-evaluate SO delivered quantity and status either way
  IF NEW.sales_order_id IS NOT NULL THEN
    PERFORM fn_recompute_so_delivered(NEW.sales_order_id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_dc_reverse_inventory_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_dc_reverse_inventory_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item record;
BEGIN
  IF OLD.approval_status = 'approved'
     AND NEW.approval_status IN ('rejected', 'cancelled') THEN
    IF EXISTS (
      SELECT 1
      FROM public.sales_invoice_items sii
      JOIN public.delivery_challan_items dci
        ON dci.id = sii.delivery_challan_item_id
      WHERE dci.challan_id = NEW.id
    ) THEN
      RAISE EXCEPTION
        'Approved Delivery Challan already invoiced; reverse the invoice before cancelling';
    END IF;

    FOR v_item IN
      SELECT *
      FROM public.delivery_challan_items
      WHERE challan_id = NEW.id
      ORDER BY id
    LOOP
      PERFORM public.post_inventory_movement(
        public.uuid_from_text(
          'inventory-v1:dc-reversal:' || NEW.id || ':' || v_item.id || ':' ||
          NEW.approval_status
        ),
        v_item.product_id,
        v_item.batch_id,
        'adjustment',
        v_item.quantity,
        CURRENT_DATE,
        NEW.challan_number,
        'delivery_challan_reversal',
        NEW.id,
        'Canonical reversal of DC ' || NEW.challan_number ||
          ' (' || NEW.approval_status || ')',
        COALESCE(NEW.rejected_by, NEW.approved_by, auth.uid()),
        NULL,
        NULL
      );
    END LOOP;

    IF NEW.sales_order_id IS NOT NULL THEN
      PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);
      PERFORM public.fn_reserve_stock_for_so_v2(NEW.sales_order_id);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_dc_reverse_product_reservation_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_dc_reverse_product_reservation_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r record;
BEGIN
  IF OLD.approval_status='approved' AND NEW.approval_status IN ('rejected','cancelled') THEN
    IF EXISTS(SELECT 1 FROM public.sales_invoice_items sii JOIN public.delivery_challan_items dci ON dci.id=sii.delivery_challan_item_id WHERE dci.challan_id=NEW.id)
      THEN RAISE EXCEPTION 'Approved Delivery Challan already invoiced; reverse invoice first'; END IF;
    FOR r IN SELECT dci.*,a.id allocation_id FROM public.delivery_challan_items dci
      JOIN public.dc_batch_allocations a ON a.delivery_challan_item_id=dci.id AND a.status='consumed'
      WHERE dci.challan_id=NEW.id ORDER BY dci.id FOR UPDATE OF a LOOP
      PERFORM public.post_inventory_movement(public.uuid_from_text('inventory-v2:dc-reversal:'||NEW.id||':'||r.id),r.product_id,r.batch_id,
        'adjustment',r.quantity,CURRENT_DATE,NEW.challan_number,'delivery_challan_reversal',NEW.id,
        'Reversal of product-reservation DC batch allocation',COALESCE(NEW.rejected_by,auth.uid()),NULL,NULL);
      UPDATE public.dc_batch_allocations SET status='reversed',reversed_at=now(),reversal_reason=NEW.approval_status WHERE id=r.allocation_id;
    END LOOP;
    PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);
    FOR r IN SELECT DISTINCT sales_order_item_id FROM public.delivery_challan_items WHERE challan_id=NEW.id LOOP
      PERFORM public.reconcile_so_product_reservation_v2(r.sales_order_item_id,'DC reversal');
    END LOOP;
  END IF;
  RETURN NEW;
END; $$;


