--
-- Name: trg_material_return_inventory_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_material_return_inventory_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item record;
  v_is_stocked boolean;
  v_was_stocked boolean;
BEGIN
  v_is_stocked := NEW.status IN ('approved', 'completed') AND NEW.restocked = true;
  v_was_stocked := OLD.status IN ('approved', 'completed') AND OLD.restocked = true;

  IF v_is_stocked AND NOT v_was_stocked THEN
    IF EXISTS (
      SELECT 1
      FROM public.inventory_transactions
      WHERE reference_type = 'material_return_reversal'
        AND reference_id = NEW.id
        AND metadata->>'canonical_engine_version' = '1.0'
    ) THEN
      RAISE EXCEPTION 'Reversed Material Return cannot be re-approved; create a new return';
    END IF;

    FOR v_item IN
      SELECT *
      FROM public.material_return_items
      WHERE return_id = NEW.id
        AND disposition = 'restock'
        AND batch_id IS NOT NULL
      ORDER BY id
    LOOP
      PERFORM public.post_inventory_movement(
        public.uuid_from_text('inventory-v1:material-return:' || NEW.id || ':' || v_item.id),
        v_item.product_id,
        v_item.batch_id,
        'return',
        v_item.quantity_returned,
        NEW.return_date,
        NEW.return_number,
        'material_return',
        NEW.id,
        'Canonical Material Return: ' || NEW.return_number,
        NEW.approved_by,
        NULL,
        NULL
      );
    END LOOP;
  ELSIF v_was_stocked AND NOT v_is_stocked THEN
    FOR v_item IN
      SELECT *
      FROM public.material_return_items
      WHERE return_id = NEW.id
        AND disposition = 'restock'
        AND batch_id IS NOT NULL
      ORDER BY id
    LOOP
      PERFORM public.post_inventory_movement(
        public.uuid_from_text(
          'inventory-v1:material-return-reversal:' || NEW.id || ':' || v_item.id
        ),
        v_item.product_id,
        v_item.batch_id,
        'adjustment',
        -v_item.quantity_returned,
        CURRENT_DATE,
        NEW.return_number,
        'material_return_reversal',
        NEW.id,
        'Canonical Material Return reversal: ' || NEW.return_number,
        COALESCE(NEW.approved_by, auth.uid()),
        NULL,
        NULL
      );
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_material_return_item_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_material_return_item_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_return_number text;
v_user_id uuid;
v_current_stock numeric;
v_old_status text;
v_return_status text;
BEGIN
IF TG_OP = 'UPDATE' THEN
-- Get return status
SELECT status INTO v_return_status
FROM material_returns WHERE id = NEW.return_id;

-- Only act when material return is approved
IF v_return_status = 'approved' THEN
-- Check if this item's disposition changed to restock/pending
IF NEW.disposition IN ('restock', 'pending') AND 
(OLD.disposition IS NULL OR OLD.disposition NOT IN ('restock', 'pending')) THEN

-- Get return details
SELECT return_number, created_by
INTO v_return_number, v_user_id
FROM material_returns WHERE id = NEW.return_id;

-- Get current stock
SELECT current_stock INTO v_current_stock
FROM batches WHERE id = NEW.batch_id;

-- DIRECTLY UPDATE BATCH STOCK (add back)
UPDATE batches
SET current_stock = current_stock + NEW.quantity_returned
WHERE id = NEW.batch_id;

-- Log transaction
INSERT INTO inventory_transactions (
product_id, batch_id, transaction_type, quantity,
transaction_date, reference_number, reference_type, reference_id,
notes, created_by, stock_before, stock_after
) VALUES (
NEW.product_id, NEW.batch_id, 'return', NEW.quantity_returned,
CURRENT_DATE, v_return_number, 'material_return_item', NEW.id,
'Material return approved (restock): ' || v_return_number, v_user_id,
v_current_stock, v_current_stock + NEW.quantity_returned
);
END IF;
END IF;
END IF;

RETURN NEW;
END;
$$;


--
-- Name: trg_recompute_from_credit_note(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_recompute_from_credit_note"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM recompute_periods_for_date(OLD.credit_note_date);
  ELSE
    PERFORM recompute_periods_for_date(NEW.credit_note_date);
    IF TG_OP = 'UPDATE'
       AND (NEW.credit_note_date IS DISTINCT FROM OLD.credit_note_date) THEN
      PERFORM recompute_periods_for_date(OLD.credit_note_date);
    END IF;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: trg_recompute_from_expense(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_recompute_from_expense"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF COALESCE(OLD.pph_amount, 0) > 0
       OR COALESCE(OLD.pib_pph_amount, 0) > 0
       OR OLD.expense_category = 'pph_import' THEN
      PERFORM public.recompute_pph_periods_for_date(COALESCE(OLD.due_date, OLD.expense_date));
    END IF;
  ELSE
    IF COALESCE(NEW.pph_amount, 0) > 0
       OR COALESCE(NEW.pib_pph_amount, 0) > 0
       OR NEW.expense_category = 'pph_import' THEN
      PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(NEW.id));
    END IF;
    IF TG_OP = 'UPDATE' THEN
      IF COALESCE(OLD.pph_amount, 0) > 0
         OR COALESCE(OLD.pib_pph_amount, 0) > 0
         OR OLD.expense_category = 'pph_import' THEN
        PERFORM public.recompute_pph_periods_for_date(COALESCE(OLD.due_date, OLD.expense_date));
        PERFORM public.recompute_pph_periods_for_date(OLD.expense_date);
      END IF;
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


