--
-- Name: trg_recompute_pph_from_bank_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_recompute_pph_from_bank_line"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_expense_id uuid;
  v_date date;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.matched_expense_id IS NOT NULL THEN
    v_expense_id := OLD.matched_expense_id;
    PERFORM 1 FROM public.finance_expenses fe
    WHERE fe.id = v_expense_id
      AND (COALESCE(fe.pph_amount, 0) > 0 OR COALESCE(fe.pib_pph_amount, 0) > 0 OR fe.expense_category = 'pph_import');
    IF NOT FOUND THEN
      v_expense_id := NULL;
    END IF;
  END IF;
  IF TG_OP IN ('UPDATE', 'DELETE') AND v_expense_id IS NOT NULL THEN
    PERFORM public.recompute_pph_periods_for_date(OLD.transaction_date);
    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));
    SELECT COALESCE(due_date, expense_date) INTO v_date FROM public.finance_expenses WHERE id = v_expense_id;
    PERFORM public.recompute_pph_periods_for_date(v_date);
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.matched_expense_id IS NOT NULL THEN
    v_expense_id := NEW.matched_expense_id;
    PERFORM 1 FROM public.finance_expenses fe
    WHERE fe.id = v_expense_id
      AND (COALESCE(fe.pph_amount, 0) > 0 OR COALESCE(fe.pib_pph_amount, 0) > 0 OR fe.expense_category = 'pph_import');
    IF NOT FOUND THEN
      v_expense_id := NULL;
    END IF;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') AND v_expense_id IS NOT NULL THEN
    PERFORM public.recompute_pph_periods_for_date(NEW.transaction_date);
    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));
    SELECT COALESCE(due_date, expense_date) INTO v_date FROM public.finance_expenses WHERE id = v_expense_id;
    PERFORM public.recompute_pph_periods_for_date(v_date);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: trg_recompute_pph_from_voucher_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_recompute_pph_from_voucher_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_expense_id uuid;
  v_voucher_id uuid;
  v_date date;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.finance_expense_id IS NOT NULL THEN
    v_expense_id := OLD.finance_expense_id;
    PERFORM 1 FROM public.finance_expenses fe
    WHERE fe.id = v_expense_id
      AND (COALESCE(fe.pph_amount, 0) > 0 OR COALESCE(fe.pib_pph_amount, 0) > 0 OR fe.expense_category = 'pph_import');
    IF NOT FOUND THEN
      v_expense_id := NULL;
    END IF;
  END IF;
  IF TG_OP IN ('UPDATE', 'DELETE') AND v_expense_id IS NOT NULL THEN
    v_voucher_id := OLD.payment_voucher_id;
    SELECT voucher_date INTO v_date FROM public.payment_vouchers WHERE id = v_voucher_id;
    PERFORM public.recompute_pph_periods_for_date(v_date);
    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));
    SELECT COALESCE(due_date, expense_date) INTO v_date FROM public.finance_expenses WHERE id = v_expense_id;
    PERFORM public.recompute_pph_periods_for_date(v_date);
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.finance_expense_id IS NOT NULL THEN
    v_expense_id := NEW.finance_expense_id;
    PERFORM 1 FROM public.finance_expenses fe
    WHERE fe.id = v_expense_id
      AND (COALESCE(fe.pph_amount, 0) > 0 OR COALESCE(fe.pib_pph_amount, 0) > 0 OR fe.expense_category = 'pph_import');
    IF NOT FOUND THEN
      v_expense_id := NULL;
    END IF;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') AND v_expense_id IS NOT NULL THEN
    v_voucher_id := NEW.payment_voucher_id;
    SELECT voucher_date INTO v_date FROM public.payment_vouchers WHERE id = v_voucher_id;
    PERFORM public.recompute_pph_periods_for_date(v_date);
    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));
    SELECT COALESCE(due_date, expense_date) INTO v_date FROM public.finance_expenses WHERE id = v_expense_id;
    PERFORM public.recompute_pph_periods_for_date(v_date);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: trg_recompute_tax_from_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_recompute_tax_from_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_source_module text := CASE WHEN TG_OP = 'DELETE' THEN OLD.source_module ELSE NEW.source_module END;
  v_reference_id uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.reference_id ELSE NEW.reference_id END;
  v_entry_date date := CASE WHEN TG_OP = 'DELETE' THEN OLD.entry_date ELSE NEW.entry_date END;
  v_source_date date;
BEGIN
  IF v_reference_id IS NULL THEN RETURN NULL; END IF;

  IF v_source_module IN ('expense', 'expenses') THEN
    SELECT expense_date INTO v_source_date FROM public.finance_expenses WHERE id = v_reference_id;
  ELSIF v_source_module IN ('payment', 'payments', 'payment_voucher') THEN
    SELECT voucher_date INTO v_source_date FROM public.payment_vouchers WHERE id = v_reference_id;
  ELSE
    RETURN NULL;
  END IF;

  PERFORM public.recompute_periods_for_date(COALESCE(v_source_date, v_entry_date));

  IF TG_OP = 'UPDATE' AND OLD.entry_date IS DISTINCT FROM NEW.entry_date THEN
    PERFORM public.recompute_periods_for_date(OLD.entry_date);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: trg_reconcile_active_so_item_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_reconcile_active_so_item_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_status text;
BEGIN
  IF TG_OP='DELETE' THEN
    IF EXISTS(SELECT 1 FROM public.so_product_reservations WHERE sales_order_item_id=OLD.id) THEN
      RAISE EXCEPTION 'Sales Order item has reservation history and cannot be deleted; cancel/void the order or adjust quantity';
    END IF;
    RETURN OLD;
  END IF;
  SELECT status::text INTO v_status FROM public.sales_orders WHERE id=NEW.sales_order_id;
  IF v_status IN ('approved','stock_reserved','pending_delivery','partially_delivered') THEN
    PERFORM public.reconcile_so_product_reservation_v2(NEW.id,'Approved SO item changed');
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: trg_release_so_product_reservation_status_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_release_so_product_reservation_status_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status::text IN ('rejected','cancelled','closed','delivered')
     AND OLD.status::text IS DISTINCT FROM NEW.status::text THEN
    PERFORM public.release_so_product_reservations_v2(NEW.id,'SO status changed to '||NEW.status::text);
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: trg_sales_invoice_item_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_sales_invoice_item_inventory"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_dc_item public.delivery_challan_items%ROWTYPE;
  v_dc_status text;
  v_invoiced_quantity numeric;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  IF NEW.delivery_challan_item_id IS NULL THEN
    RAISE EXCEPTION 'Sales Invoice item must reference an approved Delivery Challan item';
  END IF;

  SELECT dci.*
  INTO v_dc_item
  FROM public.delivery_challan_items dci
  WHERE dci.id = NEW.delivery_challan_item_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales Invoice item references a missing Delivery Challan item';
  END IF;

  SELECT dc.approval_status::text
  INTO v_dc_status
  FROM public.delivery_challans dc
  WHERE dc.id = v_dc_item.challan_id;

  IF NOT FOUND OR v_dc_status <> 'approved' THEN
    RAISE EXCEPTION 'Sales Invoice item references a non-approved Delivery Challan item';
  END IF;
  IF NEW.product_id IS DISTINCT FROM v_dc_item.product_id
     OR NEW.batch_id IS DISTINCT FROM v_dc_item.batch_id THEN
    RAISE EXCEPTION 'Sales Invoice product/batch must match its Delivery Challan item';
  END IF;

  SELECT COALESCE(SUM(sii.quantity), 0)
  INTO v_invoiced_quantity
  FROM public.sales_invoice_items sii
  WHERE sii.delivery_challan_item_id = NEW.delivery_challan_item_id
    AND sii.id IS DISTINCT FROM NEW.id;

  IF v_invoiced_quantity + NEW.quantity > v_dc_item.quantity THEN
    RAISE EXCEPTION 'Sales Invoice quantity exceeds approved Delivery Challan quantity';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "trg_sales_invoice_item_inventory"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."trg_sales_invoice_item_inventory"() IS 'Bulletproof invoice inventory management. Directly updates batch stock for manual items only. DC items skip stock changes.';


