--
-- Name: trg_stock_rejection_approved(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_stock_rejection_approved"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_current_stock numeric;
BEGIN
IF TG_OP = 'UPDATE' AND NEW.status = 'approved' AND OLD.status != 'approved' THEN
-- Get current stock
SELECT current_stock INTO v_current_stock
FROM batches WHERE id = NEW.batch_id;

-- DIRECTLY UPDATE BATCH STOCK (deduct)
UPDATE batches
SET current_stock = current_stock - NEW.quantity_rejected
WHERE id = NEW.batch_id;

-- Log transaction
INSERT INTO inventory_transactions (
product_id, batch_id, transaction_type, quantity,
transaction_date, reference_number, reference_type, reference_id,
notes, created_by, stock_before, stock_after
) VALUES (
NEW.product_id, NEW.batch_id, 'adjustment', -NEW.quantity_rejected,
NEW.rejection_date, NEW.rejection_number, 'stock_rejection', NEW.id,
'Stock rejection approved: ' || NEW.rejection_reason, NEW.created_by,
v_current_stock, v_current_stock - NEW.quantity_rejected
);
END IF;

RETURN NEW;
END;
$$;


--
-- Name: trg_stock_rejection_inventory_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_stock_rejection_inventory_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status IN ('approved', 'disposed')
     AND OLD.status NOT IN ('approved', 'disposed') THEN
    IF EXISTS (
      SELECT 1
      FROM public.inventory_transactions
      WHERE reference_type = 'stock_rejection_reversal'
        AND reference_id = NEW.id
        AND metadata->>'canonical_engine_version' = '1.0'
    ) THEN
      RAISE EXCEPTION 'Reversed Stock Rejection cannot be re-approved; create a new rejection';
    END IF;

    PERFORM public.post_inventory_movement(
      public.uuid_from_text('inventory-v1:stock-rejection:' || NEW.id),
      NEW.product_id,
      NEW.batch_id,
      'rejection',
      -NEW.quantity_rejected,
      NEW.rejection_date,
      NEW.rejection_number,
      'stock_rejection',
      NEW.id,
      'Canonical Stock Rejection: ' || NEW.rejection_number,
      NEW.approved_by,
      NULL,
      NULL
    );
  ELSIF OLD.status IN ('approved', 'disposed')
        AND NEW.status NOT IN ('approved', 'disposed') THEN
    PERFORM public.post_inventory_movement(
      public.uuid_from_text('inventory-v1:stock-rejection-reversal:' || NEW.id),
      NEW.product_id,
      NEW.batch_id,
      'adjustment',
      NEW.quantity_rejected,
      CURRENT_DATE,
      NEW.rejection_number,
      'stock_rejection_reversal',
      NEW.id,
      'Canonical Stock Rejection reversal: ' || NEW.rejection_number,
      COALESCE(NEW.approved_by, auth.uid()),
      NULL,
      NULL
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_sync_batch_reserved_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_sync_batch_reserved_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
-- Recalculate reserved_stock from actual active reservations
UPDATE batches
SET reserved_stock = COALESCE((
SELECT SUM(reserved_quantity)
FROM stock_reservations
WHERE batch_id = batches.id AND status = 'active'
), 0)
WHERE id = COALESCE(NEW.batch_id, OLD.batch_id);

RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: trg_sync_expense_pph_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_sync_expense_pph_account"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_journal_id uuid;
  v_line_number integer;
BEGIN
  IF NEW.expense_category = 'import_broker' THEN
    RETURN NEW;
  END IF;
  IF COALESCE(NEW.pph_amount, 0) <= 0 THEN
    RETURN NEW;
  END IF;

  v_account_id := fn_pph_payable_account_id(NEW.pph_code_id);
  IF v_account_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_journal_id
    FROM journal_entries
   WHERE reference_id = NEW.id
     AND source_module = 'expenses'
   ORDER BY created_at DESC
   LIMIT 1;
  IF v_journal_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM journal_entry_lines
     WHERE journal_entry_id = v_journal_id
       AND debit = 0
       AND description ILIKE 'PPh Ditahan%'
  ) THEN
    UPDATE journal_entry_lines
       SET account_id = v_account_id
     WHERE journal_entry_id = v_journal_id
       AND debit = 0
       AND description ILIKE 'PPh Ditahan%';
  ELSE
    UPDATE journal_entry_lines
       SET credit = credit - NEW.pph_amount
     WHERE id = (
       SELECT id FROM journal_entry_lines
        WHERE journal_entry_id = v_journal_id
          AND credit >= NEW.pph_amount
        ORDER BY credit DESC, line_number DESC
        LIMIT 1
     );

    SELECT COALESCE(MAX(line_number), 0) + 1 INTO v_line_number
      FROM journal_entry_lines
     WHERE journal_entry_id = v_journal_id;

    INSERT INTO journal_entry_lines
      (journal_entry_id, line_number, account_id, debit, credit, description)
    VALUES
      (v_journal_id, v_line_number, v_account_id, 0, NEW.pph_amount,
       'PPh Ditahan - ' || COALESCE(NEW.description, NEW.voucher_number, 'Expense'));
  END IF;

  UPDATE journal_entries
     SET total_debit = (SELECT COALESCE(SUM(debit), 0) FROM journal_entry_lines WHERE journal_entry_id = v_journal_id),
         total_credit = (SELECT COALESCE(SUM(credit), 0) FROM journal_entry_lines WHERE journal_entry_id = v_journal_id)
   WHERE id = v_journal_id;
  RETURN NEW;
END;
$$;


