-- Name: trigger_reallocate_on_batch_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trigger_reallocate_on_batch_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
IF OLD.import_container_id IS NOT NULL THEN
PERFORM reallocate_container_costs(OLD.import_container_id);
END IF;
RETURN OLD;
END;
$$;


