-- Name: trigger_reallocate_on_container_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trigger_reallocate_on_container_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
