-- Name: trigger_recalc_batches_on_container_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trigger_recalc_batches_on_container_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
IF NEW.id IS NOT NULL THEN
PERFORM public.reallocate_container_costs(NEW.id);
