-- Name: trigger_recalc_batches_on_petty_cash_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trigger_recalc_batches_on_petty_cash_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_container_id uuid;
BEGIN
v_container_id := COALESCE(NEW.import_container_id, OLD.import_container_id);

IF v_container_id IS NOT NULL THEN
PERFORM public.reallocate_container_costs(v_container_id);
END IF;

IF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL
AND NEW.import_container_id IS DISTINCT FROM OLD.import_container_id THEN
PERFORM public.reallocate_container_costs(OLD.import_container_id);
END IF;

RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: trigger_sales_order_approved_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trigger_sales_order_approved_task"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_task_id uuid;
v_event_id uuid;
v_customer_name text;
v_has_shortage boolean;
BEGIN
IF NEW.status IN ('approved', 'stock_reserved') AND OLD.status != NEW.status THEN
SELECT company_name INTO v_customer_name FROM customers WHERE id = NEW.customer_id;
SELECT EXISTS(SELECT 1 FROM import_requirements WHERE sales_order_id = NEW.id) INTO v_has_shortage;

INSERT INTO system_task_events (event_type, event_source, entity_type, entity_id, event_data)
VALUES ('sales_order_approved', 'sales_orders', 'sales_order', NEW.id, jsonb_build_object(
'so_number', NEW.so_number, 'customer_id', NEW.customer_id,
'customer_name', v_customer_name, 'has_shortage', v_has_shortage
)) RETURNING id INTO v_event_id;

IF NEW.status = 'stock_reserved' AND NOT v_has_shortage THEN
v_task_id := create_system_task(
p_title := 'Prepare Dispatch for SO ' || NEW.so_number,
p_description := 'Stock is reserved for ' || v_customer_name || '. Prepare delivery challan and arrange dispatch.' ||
CASE WHEN NEW.expected_delivery_date IS NOT NULL
THEN E'\n\nExpected Delivery: ' || NEW.expected_delivery_date::text ELSE '' END,
p_deadline := COALESCE(NEW.expected_delivery_date::timestamptz, now() + interval '3 days'),
p_origin := 'sales_order_approved',
p_reference_type := 'sales_order',
p_reference_id := NEW.id,
p_assigned_role := 'warehouse',
p_customer_id := NEW.customer_id
);
UPDATE system_task_events SET task_id = v_task_id, task_created = true, processed_at = now() WHERE id = v_event_id;
END IF;
END IF;
RETURN NEW;
EXCEPTION WHEN OTHERS THEN
IF v_event_id IS NOT NULL THEN
UPDATE system_task_events SET error_message = SQLERRM, processed_at = now() WHERE id = v_event_id;
END IF;
RETURN NEW;
END;
$$;


--
-- Name: trigger_stock_shortage_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trigger_stock_shortage_task"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_task_id uuid;
v_event_id uuid;
v_product_name text;
v_customer_name text;
v_so_number text;
BEGIN
IF TG_OP = 'INSERT' THEN
SELECT product_name INTO v_product_name FROM products WHERE id = NEW.product_id;
SELECT company_name INTO v_customer_name FROM customers WHERE id = NEW.customer_id;
IF NEW.sales_order_id IS NOT NULL THEN
SELECT so_number INTO v_so_number FROM sales_orders WHERE id = NEW.sales_order_id;
END IF;

INSERT INTO system_task_events (event_type, event_source, entity_type, entity_id, event_data)
VALUES ('import_requirement_created', 'import_requirements', 'import_requirement', NEW.id, jsonb_build_object(
'product_id', NEW.product_id, 'product_name', v_product_name,
'shortage_quantity', NEW.shortage_quantity, 'sales_order_id', NEW.sales_order_id, 'so_number', v_so_number
)) RETURNING id INTO v_event_id;

v_task_id := create_system_task(
p_title := 'Procurement Required: ' || v_product_name,
p_description := 'Stock shortage detected. Required: ' || NEW.required_quantity::text || ' units' || E'\n' ||
'Shortage: ' || NEW.shortage_quantity::text || ' units' ||
CASE WHEN v_so_number IS NOT NULL
THEN E'\n\nFor Sales Order: ' || v_so_number || ' (' || v_customer_name || ')' ELSE '' END ||
CASE WHEN NEW.required_delivery_date IS NOT NULL
THEN E'\n\nRequired by: ' || NEW.required_delivery_date::text ELSE '' END,
p_deadline := COALESCE(NEW.required_delivery_date::timestamptz - interval '30 days', now() + interval '7 days'),
p_origin := 'sales_order_shortage',
p_reference_type := 'sales_order',
p_reference_id := NEW.sales_order_id,
p_assigned_role := 'admin',
p_priority := NEW.priority::text,
p_customer_id := NEW.customer_id,
p_product_id := NEW.product_id
);
UPDATE system_task_events SET task_id = v_task_id, task_created = true, processed_at = now() WHERE id = v_event_id;
END IF;
RETURN NEW;
EXCEPTION WHEN OTHERS THEN
IF v_event_id IS NOT NULL THEN
UPDATE system_task_events SET error_message = SQLERRM, processed_at = now() WHERE id = v_event_id;
END IF;
RETURN NEW;
END;
$$;


--
-- Name: undo_reverse_fund_transfer("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."undo_reverse_fund_transfer"("p_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_message  text;
  v_conflict jsonb;
BEGIN
  BEGIN
    RETURN public.undo_reverse_fund_transfer_core(p_id, p_reason);
  EXCEPTION WHEN integrity_constraint_violation THEN
    GET STACKED DIAGNOSTICS v_message = MESSAGE_TEXT;

    IF v_message LIKE
       'Cannot undo reversal: the % bank statement line is now linked to another transaction' THEN
      v_conflict := public.describe_undo_reverse_bank_conflict(p_id);
      IF v_conflict IS NOT NULL THEN
        RAISE EXCEPTION '%', v_message
          USING
            ERRCODE = 'integrity_constraint_violation',
            DETAIL = v_conflict::text;
      END IF;
    END IF;

    RAISE;
  END;
END;
$$;


--
-- Name: undo_reverse_fund_transfer_core("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."undo_reverse_fund_transfer_core"("p_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id             uuid := auth.uid();
  v_role                text;
  v_user_active         boolean;
  v_transfer            public.fund_transfers%ROWTYPE;
  v_original_je         public.journal_entries%ROWTYPE;
  v_reversal_je         public.journal_entries%ROWTYPE;
  v_related_je_count    integer;
  v_active_je_count     integer;
  v_period_status       text;
  v_bank_link           record;
  v_bank_line           public.bank_statement_lines%ROWTYPE;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, is_active
    INTO v_role, v_user_active
    FROM public.user_profiles
   WHERE id = v_user_id;

  IF NOT FOUND OR NOT COALESCE(v_user_active, false)
     OR v_role NOT IN ('admin', 'accounts') THEN
    RAISE EXCEPTION 'Permission denied: only active admin or accounts users can undo a Contra reversal'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT *
    INTO v_transfer
    FROM public.fund_transfers
   WHERE id = p_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fund transfer % not found', p_id
      USING ERRCODE = 'no_data_found';
  END IF;

  IF v_transfer.status <> 'reversed' THEN
    RAISE EXCEPTION
      'Undo Reverse is unavailable for % because its status is %; the reversal may already have been undone',
      v_transfer.transfer_number, v_transfer.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_transfer.journal_entry_id IS NOT NULL THEN
    SELECT *
      INTO v_original_je
      FROM public.journal_entries
     WHERE id = v_transfer.journal_entry_id
     FOR UPDATE;
  END IF;

  IF v_original_je.id IS NULL THEN
    SELECT *
      INTO v_original_je
      FROM public.journal_entries
     WHERE source_module = 'fund_transfers'
       AND reference_id = p_id
       AND reference_number = v_transfer.transfer_number
     ORDER BY created_at ASC
     LIMIT 1
     FOR UPDATE;
  END IF;

  IF v_original_je.id IS NULL THEN
    RAISE EXCEPTION 'Cannot undo reversal: original journal for % was not found',
      v_transfer.transfer_number USING ERRCODE = 'no_data_found';
  END IF;

  IF v_original_je.source_module <> 'fund_transfers'
     OR v_original_je.reference_id IS DISTINCT FROM p_id
     OR v_original_je.reference_number IS DISTINCT FROM v_transfer.transfer_number THEN
    RAISE EXCEPTION 'Cannot undo reversal: the original journal link for % is inconsistent',
      v_transfer.transfer_number USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF NOT COALESCE(v_original_je.is_posted, false)
     OR NOT COALESCE(v_original_je.is_reversed, false)
     OR v_original_je.reversed_by_id IS NULL THEN
    RAISE EXCEPTION 'Cannot undo reversal: original journal % is not in the expected reversed state',
      v_original_je.entry_number USING ERRCODE = 'check_violation';
  END IF;

  SELECT *
    INTO v_reversal_je
    FROM public.journal_entries
   WHERE id = v_original_je.reversed_by_id
   FOR UPDATE;

  IF v_reversal_je.id IS NULL THEN
    RAISE EXCEPTION 'Cannot undo reversal: reversing journal for % was not found',
      v_transfer.transfer_number USING ERRCODE = 'no_data_found';
  END IF;

  IF v_reversal_je.source_module <> 'fund_transfers'
     OR v_reversal_je.reference_id IS DISTINCT FROM p_id
     OR v_reversal_je.reference_number IS DISTINCT FROM ('REV-' || v_transfer.transfer_number)
     OR NOT COALESCE(v_reversal_je.is_posted, false)
     OR COALESCE(v_reversal_je.is_reversed, false) THEN
    RAISE EXCEPTION 'Cannot undo reversal: reversing journal % is not active or is linked inconsistently',
      v_reversal_je.entry_number USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  SELECT COUNT(*)
    INTO v_related_je_count
    FROM public.journal_entries
   WHERE source_module = 'fund_transfers'
     AND (
       reference_id = p_id
       OR reference_number IN (
         v_transfer.transfer_number,
         'REV-' || v_transfer.transfer_number
       )
     );

  IF v_related_je_count <> 2 THEN
    RAISE EXCEPTION
      'Cannot undo reversal: expected exactly two journals for %, found %',
      v_transfer.transfer_number, v_related_je_count
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.journal_entry_lines
     WHERE journal_entry_id = v_original_je.id
  ) OR NOT EXISTS (
    SELECT 1 FROM public.journal_entry_lines
     WHERE journal_entry_id = v_reversal_je.id
  ) THEN
    RAISE EXCEPTION 'Cannot undo reversal: original or reversing journal has no ledger lines'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF EXISTS (
    (
      SELECT line_number, account_id, debit, credit
        FROM public.journal_entry_lines
       WHERE journal_entry_id = v_original_je.id
      EXCEPT ALL
      SELECT line_number, account_id, credit, debit
        FROM public.journal_entry_lines
       WHERE journal_entry_id = v_reversal_je.id
    )
    UNION ALL
    (
      SELECT line_number, account_id, debit, credit
        FROM public.journal_entry_lines
       WHERE journal_entry_id = v_reversal_je.id
      EXCEPT ALL
      SELECT line_number, account_id, credit, debit
        FROM public.journal_entry_lines
       WHERE journal_entry_id = v_original_je.id
    )
  ) THEN
    RAISE EXCEPTION 'Cannot undo reversal: journal % is no longer the exact inverse of %',
      v_reversal_je.entry_number, v_original_je.entry_number
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  SELECT status
    INTO v_period_status
    FROM public.accounting_periods
   WHERE start_date <= v_original_je.entry_date
     AND end_date >= v_original_je.entry_date
   ORDER BY start_date DESC
   LIMIT 1;

  IF v_period_status IS NOT NULL AND v_period_status <> 'open' THEN
    RAISE EXCEPTION
      'Cannot undo reversal: the original accounting period for % is %',
      to_char(v_original_je.entry_date, 'FMMonth YYYY'), v_period_status
      USING ERRCODE = 'check_violation';
  END IF;

  v_period_status := NULL;
  SELECT status
    INTO v_period_status
    FROM public.accounting_periods
   WHERE start_date <= v_reversal_je.entry_date
     AND end_date >= v_reversal_je.entry_date
   ORDER BY start_date DESC
   LIMIT 1;

  IF v_period_status IS NOT NULL AND v_period_status <> 'open' THEN
    RAISE EXCEPTION
      'Cannot undo reversal: the reversal accounting period for % is %',
      to_char(v_reversal_je.entry_date, 'FMMonth YYYY'), v_period_status
      USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.bank_statement_lines
     WHERE matched_fund_transfer_id = p_id
       AND id IS DISTINCT FROM v_transfer.from_bank_statement_line_id
       AND id IS DISTINCT FROM v_transfer.to_bank_statement_line_id
  ) THEN
    RAISE EXCEPTION
      'Cannot undo reversal: an unexpected bank statement line is linked to %',
      v_transfer.transfer_number USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.bank_statement_lines
     WHERE matched_entry_id = v_reversal_je.id
       AND id IS DISTINCT FROM v_transfer.from_bank_statement_line_id
       AND id IS DISTINCT FROM v_transfer.to_bank_statement_line_id
  ) THEN
    RAISE EXCEPTION
      'Cannot undo reversal: the reversing journal has a later bank reconciliation dependency'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  FOR v_bank_link IN
    SELECT *
      FROM (
        VALUES
          (
            v_transfer.from_bank_statement_line_id,
            CASE WHEN v_transfer.from_account_type = 'bank'
                 THEN v_transfer.from_bank_account_id ELSE NULL END,
            'source'
          ),
          (
            v_transfer.to_bank_statement_line_id,
            CASE WHEN v_transfer.to_account_type = 'bank'
                 THEN v_transfer.to_bank_account_id ELSE NULL END,
            'destination'
          )
      ) AS expected(line_id, bank_account_id, link_side)
     WHERE line_id IS NOT NULL
  LOOP
    SELECT *
      INTO v_bank_line
      FROM public.bank_statement_lines
     WHERE id = v_bank_link.line_id
     FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION
        'Cannot undo reversal: the % bank statement line no longer exists',
        v_bank_link.link_side USING ERRCODE = 'no_data_found';
    END IF;

    IF v_bank_link.bank_account_id IS NULL
       OR v_bank_line.bank_account_id IS DISTINCT FROM v_bank_link.bank_account_id THEN
      RAISE EXCEPTION
        'Cannot undo reversal: the % bank statement line belongs to a different bank account',
        v_bank_link.link_side USING ERRCODE = 'integrity_constraint_violation';
    END IF;

    IF v_bank_line.matched_expense_id IS NOT NULL
       OR v_bank_line.matched_receipt_id IS NOT NULL
       OR v_bank_line.matched_petty_cash_id IS NOT NULL
       OR v_bank_line.matched_tax_payment_id IS NOT NULL
       OR (
         v_bank_line.matched_fund_transfer_id IS NOT NULL
         AND v_bank_line.matched_fund_transfer_id <> p_id
       )
       OR (
         v_bank_line.matched_entry_id IS NOT NULL
         AND v_bank_line.matched_entry_id NOT IN (v_original_je.id, v_reversal_je.id)
       ) THEN
      RAISE EXCEPTION
        'Cannot undo reversal: the % bank statement line is now linked to another transaction',
        v_bank_link.link_side USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END LOOP;

  UPDATE public.journal_entries
     SET is_posted = false,
         is_reversed = true
   WHERE id = v_reversal_je.id;

  UPDATE public.journal_entries
     SET is_posted = true,
         is_reversed = false,
         reversed_by_id = NULL
   WHERE id = v_original_je.id;

  UPDATE public.fund_transfers
     SET status = 'posted',
         journal_entry_id = v_original_je.id,
         reversed_at = NULL,
         reversed_by = NULL
   WHERE id = p_id;

  FOR v_bank_link IN
    SELECT *
      FROM (
        VALUES
          (v_transfer.from_bank_statement_line_id, 'source'),
          (v_transfer.to_bank_statement_line_id, 'destination')
      ) AS expected(line_id, link_side)
     WHERE line_id IS NOT NULL
  LOOP
    UPDATE public.bank_statement_lines
       SET matched_fund_transfer_id = p_id,
           matched_entry_id = v_original_je.id,
           reconciliation_status = 'matched',
           matched_at = now(),
           matched_by = v_user_id,
           manually_unlinked = false,
           notes = 'Linked to Fund Transfer ' || v_transfer.transfer_number
     WHERE id = v_bank_link.line_id;
  END LOOP;

  SELECT COUNT(*)
    INTO v_active_je_count
    FROM public.journal_entries
   WHERE source_module = 'fund_transfers'
     AND reference_id = p_id
     AND is_posted = true
     AND COALESCE(is_reversed, false) = false;

  IF v_active_je_count <> 1 THEN
    RAISE EXCEPTION
      'Undo Reverse aborted: expected one active journal for %, found %',
      v_transfer.transfer_number, v_active_je_count
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  INSERT INTO public.audit_logs (
    table_name,
    record_id,
    action_type,
    old_values,
    new_values,
    user_id
  ) VALUES (
    'fund_transfers',
    p_id,
    'update',
    jsonb_build_object(
      '_action', 'UNDO_REVERSE',
      'status', 'reversed',
      'reversed_at', v_transfer.reversed_at,
      'reversed_by', v_transfer.reversed_by,
      'original_journal_id', v_original_je.id,
      'original_journal_number', v_original_je.entry_number,
      'reversal_journal_id', v_reversal_je.id,
      'reversal_reference', v_reversal_je.entry_number,
      'reason', NULLIF(BTRIM(p_reason), '')
    ),
    jsonb_build_object(
      'status', 'posted',
      'active_journal_id', v_original_je.id,
      'voided_reversal_journal_id', v_reversal_je.id,
      'undone_by', v_user_id,
      'undone_at', now()
    ),
    v_user_id
  );

  RETURN v_original_je.id;
END;
$$;


--
-- Name: unlink_expense_from_bank_statement("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."unlink_expense_from_bank_statement"("p_bank_statement_line_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot unlink bank statement entries', v_role;
END IF;

UPDATE bank_statement_lines
SET matched_expense_id = NULL, reconciliation_status = 'unmatched',
matched_at = NULL, matched_by = NULL, notes = NULL
WHERE id = p_bank_statement_line_id;
IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line not found'; END IF;
END;
$$;


--
-- Name: unlink_finance_expense_bank_atomic("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."unlink_finance_expense_bank_atomic"("p_expense_id" "uuid", "p_reason" "text" DEFAULT 'Bank statement link removed by user'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_expense public.finance_expenses%ROWTYPE;
  v_allocation record;
  v_released integer := 0;
BEGIN
  PERFORM public._sec_check_finance_role();
  IF btrim(COALESCE(p_reason, '')) = '' THEN
    RAISE EXCEPTION 'An unlink reason is required';
  END IF;

  SELECT * INTO v_expense
  FROM public.finance_expenses
  WHERE id = p_expense_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense not found';
  END IF;
  IF v_expense.approval_status <> 'approved' THEN
    RAISE EXCEPTION 'Only an active posted expense can be unlinked through this workflow';
  END IF;

  FOR v_allocation IN
    SELECT id
    FROM public.bank_statement_allocations
    WHERE document_type = 'expense'
      AND document_id = p_expense_id
    ORDER BY id
    FOR UPDATE
  LOOP
    PERFORM public.unmatch_bank_statement_allocation(v_allocation.id);
    v_released := v_released + 1;
  END LOOP;
  IF v_released = 0 THEN
    RAISE EXCEPTION 'Expense has no canonical bank allocation to unlink';
  END IF;

  PERFORM public.recalculate_expense_payment_state(p_expense_id);
  PERFORM public.cancel_expense_posting(p_expense_id, auth.uid(), p_reason);

  IF EXISTS (
    SELECT 1 FROM public.bank_statement_allocations
    WHERE document_type = 'expense' AND document_id = p_expense_id
  ) THEN
    RAISE EXCEPTION 'Expense unlink left a bank allocation behind';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.journal_entries
    WHERE source_module IN ('expense', 'expenses')
      AND (reference_id = p_expense_id OR reference_number = 'EXP-' || p_expense_id::text)
      AND is_posted AND NOT COALESCE(is_reversed, false)
  ) THEN
    RAISE EXCEPTION 'Expense unlink left an active journal behind';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.finance_expenses
    WHERE id = p_expense_id AND approval_status = 'cancelled'
  ) THEN
    RAISE EXCEPTION 'Expense unlink did not cancel the document';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'expense_id', p_expense_id,
    'released_allocations', v_released
  );
END;
$$;


--
-- Name: unmatch_bank_line("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."unmatch_bank_line"("p_bank_line_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_allocation_id uuid;
BEGIN
  PERFORM public._sec_check_finance_role();
  PERFORM 1 FROM public.bank_statement_lines WHERE id = p_bank_line_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank statement line not found';
  END IF;

  FOR v_allocation_id IN
    SELECT id
    FROM public.bank_statement_allocations
    WHERE bank_statement_line_id = p_bank_line_id
    ORDER BY id
    FOR UPDATE
  LOOP
    PERFORM public.unmatch_bank_statement_allocation(v_allocation_id);
  END LOOP;

  UPDATE public.bank_statement_lines
  SET matched_expense_id = NULL,
      matched_receipt_id = NULL,
      matched_payment_id = NULL,
      matched_fund_transfer_id = NULL,
      matched_petty_cash_id = NULL,
      matched_tax_payment_id = NULL,
      matched_entry_id = NULL,
      matching_status = 'none',
      reconciliation_status = 'unmatched',
      matched_at = NULL,
      matched_by = NULL,
      notes = NULL,
      manually_unlinked = true,
      payment_kind = 'supplier'
  WHERE id = p_bank_line_id;

  RETURN jsonb_build_object('success', true, 'bank_line_id', p_bank_line_id);
END;
$$;


--
-- Name: unmatch_bank_statement_allocation("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."unmatch_bank_statement_allocation"("p_allocation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_a public.bank_statement_allocations%rowtype; v_payment_je public.journal_entries%rowtype;
  v_reversal_id uuid; v_reversal_number text; v_period_status text;
BEGIN
  PERFORM public._sec_check_finance_role();
  SELECT * INTO v_a FROM public.bank_statement_allocations WHERE id=p_allocation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank allocation not found'; END IF;
  SELECT * INTO v_payment_je FROM public.journal_entries
   WHERE id=v_a.journal_entry_id AND source_module='expense_payment'
     AND reference_number='EXP-PAY-'||p_allocation_id::text
     AND is_posted AND NOT COALESCE(is_reversed,false) FOR UPDATE;
  IF FOUND THEN
    SELECT status INTO v_period_status FROM public.accounting_periods
     WHERE start_date<=v_payment_je.entry_date AND end_date>=v_payment_je.entry_date
     ORDER BY start_date DESC LIMIT 1;
    IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN
      RAISE EXCEPTION 'Cannot unlink expense payment in a closed accounting period';
    END IF;
    v_reversal_number:=public.next_journal_entry_number();
    INSERT INTO public.journal_entries(entry_number,entry_date,period_id,source_module,reference_id,
      reference_number,description,total_debit,total_credit,is_posted,is_reversed,posted_by,posted_at,created_by,
      transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
    VALUES(v_reversal_number,v_payment_je.entry_date,v_payment_je.period_id,'expense_payment_reversal',v_a.document_id,
      'REV-EXP-PAY-'||p_allocation_id::text,'Reversal of '||v_payment_je.entry_number,
      v_payment_je.total_credit,v_payment_je.total_debit,true,true,auth.uid(),now(),auth.uid(),
      v_payment_je.transaction_currency,v_payment_je.functional_currency,v_payment_je.exchange_rate,v_payment_je.amounts_are_functional)
    RETURNING id INTO v_reversal_id;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,
      tax_code_id,customer_id,supplier_id,batch_id,transaction_currency,transaction_debit,transaction_credit,
      functional_currency,exchange_rate)
    SELECT v_reversal_id,line_number,account_id,'REVERSAL: '||COALESCE(description,''),credit,debit,
      tax_code_id,customer_id,supplier_id,batch_id,transaction_currency,transaction_credit,transaction_debit,
      functional_currency,exchange_rate
      FROM public.journal_entry_lines WHERE journal_entry_id=v_payment_je.id ORDER BY line_number;
    UPDATE public.journal_entries SET is_reversed=true,reversed_by_id=v_reversal_id
     WHERE id=v_payment_je.id;
  END IF;
  DELETE FROM public.bank_statement_allocations WHERE id=p_allocation_id;
  PERFORM public.sync_bank_line_allocation_owner(v_a.bank_statement_line_id);
  PERFORM public.refresh_bank_statement_allocation_status(v_a.bank_statement_line_id);
  IF v_a.document_type='expense' THEN PERFORM public.recalculate_expense_payment_state(v_a.document_id); END IF;
  RETURN jsonb_build_object('success',true,'bank_line_id',v_a.bank_statement_line_id,
    'allocation_id',p_allocation_id,'reversal_journal_id',v_reversal_id);
END;
$$;


--
-- Name: update_approval_workflows_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_approval_workflows_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
NEW.updated_at = now();
RETURN NEW;
END;
$$;


--
-- Name: update_batch_stock_from_transactions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_batch_stock_from_transactions"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_batch_id uuid;
v_total_stock numeric;
BEGIN
-- Determine which batch to update
IF TG_OP = 'DELETE' THEN
v_batch_id := OLD.batch_id;
ELSE
v_batch_id := NEW.batch_id;
END IF;

-- Calculate total stock from all transactions for this batch
SELECT COALESCE(SUM(quantity), 0)
INTO v_total_stock
FROM inventory_transactions
WHERE batch_id = v_batch_id;

-- Update the batch current_stock
UPDATE batches
SET current_stock = v_total_stock,
updated_at = now()
WHERE id = v_batch_id;

IF TG_OP = 'DELETE' THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END;
$$;


--
-- Name: update_container_bpom_fees(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_container_bpom_fees"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_container_id uuid;
v_total_bpom_fees numeric;
v_is_bpom_fees boolean := false;
BEGIN
-- Check if this expense is 'bpom_ski_fees' category
IF TG_OP = 'DELETE' THEN
v_is_bpom_fees := (OLD.expense_category = 'bpom_ski_fees');
v_container_id := OLD.import_container_id;
ELSIF TG_OP = 'UPDATE' THEN
v_is_bpom_fees := (NEW.expense_category = 'bpom_ski_fees' OR OLD.expense_category = 'bpom_ski_fees');
v_container_id := NEW.import_container_id;
ELSE -- INSERT
v_is_bpom_fees := (NEW.expense_category = 'bpom_ski_fees');
v_container_id := NEW.import_container_id;
END IF;

-- Skip if not 'bpom_ski_fees' category
IF NOT v_is_bpom_fees THEN
IF TG_OP = 'DELETE' THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END IF;

-- Skip if no container linked
IF v_container_id IS NULL AND (TG_OP != 'UPDATE' OR OLD.import_container_id IS NULL) THEN
IF TG_OP = 'DELETE' THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END IF;

-- Calculate total of all 'bpom_ski_fees' expenses for this container
IF v_container_id IS NOT NULL THEN
SELECT COALESCE(SUM(amount), 0) 
INTO v_total_bpom_fees
FROM finance_expenses
WHERE import_container_id = v_container_id
AND expense_category = 'bpom_ski_fees';

-- Update the container's bpom_ski_fees field
UPDATE import_containers
SET bpom_ski_fees = v_total_bpom_fees
WHERE id = v_container_id;
END IF;

-- If updating and container changed, also update the old container
IF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL 
AND (NEW.import_container_id IS NULL OR OLD.import_container_id != NEW.import_container_id) THEN
SELECT COALESCE(SUM(amount), 0) 
INTO v_total_bpom_fees
FROM finance_expenses
WHERE import_container_id = OLD.import_container_id
AND expense_category = 'bpom_ski_fees';

UPDATE import_containers
SET bpom_ski_fees = v_total_bpom_fees
WHERE id = OLD.import_container_id;
END IF;

IF TG_OP = 'DELETE' THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END;
$$;


--
-- Name: update_container_other_costs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_container_other_costs"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_container_id uuid;
v_total_other_costs numeric;
v_is_other_import boolean := false;
BEGIN
-- Check if this expense is 'other_import' category
IF TG_OP = 'DELETE' THEN
v_is_other_import := (OLD.expense_category = 'other_import');
v_container_id := OLD.import_container_id;
ELSIF TG_OP = 'UPDATE' THEN
v_is_other_import := (NEW.expense_category = 'other_import' OR OLD.expense_category = 'other_import');
v_container_id := NEW.import_container_id;
ELSE -- INSERT
v_is_other_import := (NEW.expense_category = 'other_import');
v_container_id := NEW.import_container_id;
END IF;

-- Skip if not 'other_import' category
IF NOT v_is_other_import THEN
IF TG_OP = 'DELETE' THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END IF;

-- Skip if no container linked
IF v_container_id IS NULL AND (TG_OP != 'UPDATE' OR OLD.import_container_id IS NULL) THEN
IF TG_OP = 'DELETE' THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END IF;

-- Calculate total of all 'other_import' expenses for this container
IF v_container_id IS NOT NULL THEN
SELECT COALESCE(SUM(amount), 0) 
INTO v_total_other_costs
FROM finance_expenses
WHERE import_container_id = v_container_id
AND expense_category = 'other_import';

-- Update the container's other_import_costs field
UPDATE import_containers
SET other_import_costs = v_total_other_costs
WHERE id = v_container_id;
END IF;

-- If updating and container changed, also update the old container
IF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL 
AND (NEW.import_container_id IS NULL OR OLD.import_container_id != NEW.import_container_id) THEN
SELECT COALESCE(SUM(amount), 0) 
INTO v_total_other_costs
FROM finance_expenses
WHERE import_container_id = OLD.import_container_id
AND expense_category = 'other_import';

UPDATE import_containers
SET other_import_costs = v_total_other_costs
WHERE id = OLD.import_container_id;
END IF;

IF TG_OP = 'DELETE' THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END;
$$;


--
-- Name: update_fund_transfer_bank_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_fund_transfer_bank_links"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
-- Handle from_bank_statement_line_id
IF NEW.from_bank_statement_line_id IS NOT NULL THEN
-- If it's different from OLD, update the bank statement
IF (TG_OP = 'INSERT') OR (OLD.from_bank_statement_line_id IS DISTINCT FROM NEW.from_bank_statement_line_id) THEN
UPDATE bank_statement_lines
SET
matched_fund_transfer_id = NEW.id,
reconciliation_status = 'matched',
matched_at = now(),
matched_by = COALESCE(NEW.posted_by, NEW.created_by),
notes = 'Linked to Fund Transfer ' || NEW.transfer_number
WHERE id = NEW.from_bank_statement_line_id;
END IF;
END IF;

-- Handle to_bank_statement_line_id
IF NEW.to_bank_statement_line_id IS NOT NULL THEN
IF (TG_OP = 'INSERT') OR (OLD.to_bank_statement_line_id IS DISTINCT FROM NEW.to_bank_statement_line_id) THEN
UPDATE bank_statement_lines
SET
matched_fund_transfer_id = NEW.id,
reconciliation_status = 'matched',
matched_at = now(),
matched_by = COALESCE(NEW.posted_by, NEW.created_by),
notes = 'Linked to Fund Transfer ' || NEW.transfer_number
WHERE id = NEW.to_bank_statement_line_id;
END IF;
END IF;

RETURN NEW;
END;
$$;


