--
-- Name: update_inventory_on_batch_insert_or_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_inventory_on_batch_insert_or_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (TG_OP = 'INSERT') THEN
    -- Create new inventory transaction for new batch
    INSERT INTO inventory_transactions (
      product_id,
      batch_id,
      transaction_type,
      quantity,
      transaction_date,
      notes
    ) VALUES (
      NEW.product_id,
      NEW.id,
      'batch_import',
      NEW.import_quantity,
      NEW.import_date,
      'Batch import: ' || NEW.batch_number
    );
  ELSIF (TG_OP = 'UPDATE') THEN
    -- Update existing inventory transaction when batch is edited
    UPDATE inventory_transactions
    SET 
      product_id = NEW.product_id,
      quantity = NEW.import_quantity,
      transaction_date = NEW.import_date,
      notes = 'Batch import: ' || NEW.batch_number
    WHERE batch_id = NEW.id 
      AND transaction_type = 'batch_import';
    
    -- If no transaction exists, create one (handles legacy batches)
    IF NOT FOUND THEN
      INSERT INTO inventory_transactions (
        product_id,
        batch_id,
        transaction_type,
        quantity,
        transaction_date,
        notes
      ) VALUES (
        NEW.product_id,
        NEW.id,
        'batch_import',
        NEW.import_quantity,
        NEW.import_date,
        'Batch import: ' || NEW.batch_number
      );
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: update_invoice_payment_status_from_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_invoice_payment_status_from_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_total_paid NUMERIC;
v_invoice_total NUMERIC;
v_invoice_id UUID;
BEGIN
-- Get the invoice ID
IF TG_OP = 'DELETE' THEN
v_invoice_id := OLD.sales_invoice_id;
ELSE
v_invoice_id := NEW.sales_invoice_id;
END IF;

-- Only process if there's an invoice ID and it's a receipt voucher
IF v_invoice_id IS NULL THEN
IF TG_OP = 'DELETE' THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END IF;

-- Only process receipt vouchers
IF TG_OP = 'DELETE' AND OLD.voucher_type != 'receipt' THEN
RETURN OLD;
END IF;

IF TG_OP != 'DELETE' AND NEW.voucher_type != 'receipt' THEN
RETURN NEW;
END IF;

-- Calculate total paid for the invoice
v_total_paid := get_invoice_paid_amount(v_invoice_id);

-- Get invoice total
SELECT total_amount INTO v_invoice_total
FROM sales_invoices
WHERE id = v_invoice_id;

-- Update paid_amount, balance_amount, and payment_status
UPDATE sales_invoices
SET 
paid_amount = v_total_paid,
balance_amount = v_invoice_total - v_total_paid,
payment_status = CASE
WHEN v_total_paid = 0 THEN 'pending'
WHEN v_total_paid >= v_invoice_total THEN 'paid'
ELSE 'partial'
END,
updated_at = NOW()
WHERE id = v_invoice_id;

IF TG_OP = 'DELETE' THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END;
$$;


--
-- Name: update_loan_outstanding_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_loan_outstanding_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_loan_id uuid;
v_loan_type text;
v_principal numeric;
v_total_principal_repaid numeric;
v_total_additional numeric;
v_new_balance numeric;
BEGIN
IF TG_OP = 'DELETE' THEN
v_loan_id := OLD.loan_id;
ELSE
v_loan_id := NEW.loan_id;
END IF;

SELECT loan_type, principal_amount INTO v_loan_type, v_principal FROM loans WHERE id = v_loan_id;

-- Sum all principal repayments
SELECT COALESCE(SUM(principal_amount), 0) INTO v_total_principal_repaid
FROM loan_transactions
WHERE loan_id = v_loan_id AND transaction_type IN ('repayment', 'interest_payment');

-- Sum all additional disbursements
SELECT COALESCE(SUM(amount), 0) INTO v_total_additional
FROM loan_transactions
WHERE loan_id = v_loan_id AND transaction_type = 'additional_disbursement';

-- Calculate new outstanding balance
v_new_balance := v_principal + v_total_additional - v_total_principal_repaid;

-- Update loan outstanding balance and status
UPDATE loans
SET outstanding_balance = GREATEST(v_new_balance, 0),
status = CASE WHEN v_new_balance <= 0 THEN 'closed' ELSE 'active' END
WHERE id = v_loan_id;

IF TG_OP = 'DELETE' THEN
RETURN OLD;
END IF;
RETURN NEW;
END;
$$;


--
-- Name: update_product_current_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_product_current_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_product_id UUID;
BEGIN
IF TG_OP = 'DELETE' THEN
v_product_id := OLD.product_id;
ELSE
v_product_id := NEW.product_id;
END IF;

-- Update the product's current_stock to the sum of all active batch current_stocks
UPDATE products
SET current_stock = COALESCE((
SELECT SUM(b.current_stock)
FROM batches b
WHERE b.product_id = v_product_id
AND b.is_active = true
AND b.current_stock > 0
), 0)
WHERE id = v_product_id;

IF TG_OP = 'DELETE' THEN
RETURN OLD;
ELSE
RETURN NEW;
END IF;
END;
$$;


