--
-- Name: upsert_expense_journal_header_in_place("uuid", "uuid", "date", "text", "text", numeric, "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."upsert_expense_journal_header_in_place"("p_journal_id" "uuid", "p_expense_id" "uuid", "p_entry_date" "date", "p_description" "text", "p_transaction_category" "text", "p_total" numeric, "p_created_by" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_journal_id uuid := p_journal_id;
  v_entry_number text;
  v_period_id uuid;
BEGIN
  SELECT id INTO v_period_id
    FROM public.accounting_periods
   WHERE start_date<=p_entry_date AND end_date>=p_entry_date
   ORDER BY start_date DESC LIMIT 1;
  IF v_journal_id IS NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext('expense-je-number:' || to_char(p_entry_date,'YYMM')));
    SELECT 'JE' || to_char(p_entry_date,'YYMM') || '-' ||
           lpad((COALESCE(max(CAST(substring(entry_number FROM '-([0-9]+)$') AS integer)),0)+1)::text,4,'0')
      INTO v_entry_number
      FROM public.journal_entries
     WHERE entry_number LIKE 'JE' || to_char(p_entry_date,'YYMM') || '-%';

    INSERT INTO public.journal_entries(
      entry_number,entry_date,period_id,source_module,reference_id,reference_number,
      description,transaction_category,total_debit,total_credit,is_posted,
      posted_at,created_by
    ) VALUES (
      v_entry_number,p_entry_date,v_period_id,'expenses',p_expense_id,'EXP-'||p_expense_id::text,
      p_description,p_transaction_category,p_total,p_total,true,now(),p_created_by
    ) RETURNING id INTO v_journal_id;
  ELSE
    UPDATE public.journal_entries
       SET entry_date=p_entry_date,
           period_id=v_period_id,
           source_module='expenses',
           reference_id=p_expense_id,
           reference_number='EXP-'||p_expense_id::text,
           description=p_description,
           transaction_category=p_transaction_category,
           total_debit=p_total,
           total_credit=p_total,
           is_posted=true
     WHERE id=v_journal_id
       AND is_posted=true
       AND NOT COALESCE(is_reversed,false);
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Effective expense journal is no longer active';
    END IF;
  END IF;
  RETURN v_journal_id;
END;
$_$;


--
-- Name: upsert_notification("uuid", "text", "text", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."upsert_notification"("p_user_id" "uuid", "p_type" "text", "p_title" "text", "p_message" "text", "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_reference_type" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inserted integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)
  VALUES (p_user_id, p_type, p_title, p_message, p_reference_id, p_reference_type, false)
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted > 0;
END;
$$;


--
-- Name: upsert_tax_period(integer, integer, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."upsert_tax_period"("p_fiscal_year" integer, "p_period_month" integer, "p_tax_type" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id       uuid;
  v_start    date;
  v_end      date;
  v_pay_due  date;
  v_file_due date;
BEGIN
  SELECT period_start, period_end, payment_due_date, filing_due_date
  INTO v_start, v_end, v_pay_due, v_file_due
  FROM compute_tax_due_dates(p_tax_type, p_fiscal_year, p_period_month);

  INSERT INTO tax_periods
    (fiscal_year, period_month, tax_type, period_start, period_end,
     payment_due_date, filing_due_date, created_by)
  VALUES
    (p_fiscal_year, p_period_month, p_tax_type, v_start, v_end,
     v_pay_due, v_file_due, auth.uid())
  ON CONFLICT (fiscal_year, period_month, tax_type)
  DO UPDATE SET
    payment_due_date = EXCLUDED.payment_due_date,
    filing_due_date  = EXCLUDED.filing_due_date,
    updated_at       = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END $$;


--
-- Name: uuid_from_text("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."uuid_from_text"("p_key" "text") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT (
    substr(md5(p_key), 1, 8) || '-' ||
    substr(md5(p_key), 9, 4) || '-' ||
    substr(md5(p_key), 13, 4) || '-' ||
    substr(md5(p_key), 17, 4) || '-' ||
    substr(md5(p_key), 21, 12)
  )::uuid;
$$;


--
-- Name: validate_bank_allocation_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_bank_allocation_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_line public.bank_statement_lines%rowtype;
  v_je public.journal_entries%rowtype;
  v_bank_coa uuid;
  v_bank_currency text;
  v_total numeric;
  v_allocated numeric;
  v_journal_debit numeric;
  v_journal_credit numeric;
  v_tx_debit numeric;
  v_tx_credit numeric;
  v_is_statement_debit boolean;
BEGIN
  SELECT * INTO v_line FROM public.bank_statement_lines
   WHERE id = NEW.bank_statement_line_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line % not found', NEW.bank_statement_line_id; END IF;
  SELECT * INTO v_je FROM public.journal_entries
   WHERE id = NEW.journal_entry_id FOR UPDATE;
  IF NOT FOUND OR NOT v_je.is_posted OR COALESCE(v_je.is_reversed, false) THEN
    RAISE EXCEPTION 'Allocation requires an active posted journal';
  END IF;
  SELECT coa_id, upper(currency) INTO v_bank_coa, v_bank_currency
    FROM public.bank_accounts WHERE id = v_line.bank_account_id;
  IF v_bank_coa IS NULL THEN RAISE EXCEPTION 'Bank account has no COA'; END IF;
  IF upper(COALESCE(v_line.currency, '')) <> v_bank_currency THEN
    RAISE EXCEPTION 'Statement/account currency mismatch';
  END IF;
  v_total := COALESCE(NULLIF(v_line.debit_amount, 0), v_line.credit_amount, 0);
  SELECT COALESCE(sum(a.allocation_amount), 0) INTO v_allocated
    FROM public.bank_statement_allocations a
   WHERE a.bank_statement_line_id = NEW.bank_statement_line_id
     AND (TG_OP <> 'UPDATE' OR a.id <> NEW.id);
  IF v_allocated + NEW.allocation_amount > v_total + 0.01 THEN
    RAISE EXCEPTION 'Bank allocations exceed statement amount';
  END IF;
  SELECT COALESCE(sum(l.debit), 0), COALESCE(sum(l.credit), 0),
         COALESCE(sum(l.transaction_debit), 0), COALESCE(sum(l.transaction_credit), 0)
    INTO v_journal_debit, v_journal_credit, v_tx_debit, v_tx_credit
    FROM public.journal_entry_lines l
   WHERE l.journal_entry_id = NEW.journal_entry_id AND l.account_id = v_bank_coa;
  IF v_journal_debit = 0 AND v_journal_credit = 0 THEN
    RAISE EXCEPTION 'Allocated journal has no bank COA movement';
  END IF;
  v_is_statement_debit := COALESCE(v_line.debit_amount, 0) > 0;
  IF v_is_statement_debit AND v_journal_credit <= 0 THEN
    RAISE EXCEPTION 'Statement debit requires a journal bank credit';
  ELSIF NOT v_is_statement_debit AND v_journal_debit <= 0 THEN
    RAISE EXCEPTION 'Statement credit requires a journal bank debit';
  END IF;
  -- Journal headers are historically inconsistent (some valid USD bank
  -- postings carry IDR at header level).  Validate the linked bank COA lines,
  -- which are the canonical bank-side currency evidence, instead.
  IF v_bank_currency = 'USD' AND NOT EXISTS (
    SELECT 1
    FROM public.journal_entry_lines l
    WHERE l.journal_entry_id = NEW.journal_entry_id
      AND l.account_id = v_bank_coa
      AND l.transaction_currency = 'USD'
      AND l.functional_currency = 'IDR'
      AND COALESCE(l.exchange_rate, 0) > 0
      AND ((l.debit > 0 AND COALESCE(l.transaction_debit, 0) > 0)
        OR (l.credit > 0 AND COALESCE(l.transaction_credit, 0) > 0))
  ) THEN
    RAISE EXCEPTION 'USD bank allocation requires valid USD metadata on the bank COA line';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "validate_bank_allocation_integrity"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."validate_bank_allocation_integrity"() IS 'Canonical bank allocation guard: active posted journal, currency/side validation, and no over-allocation.';


--
-- Name: validate_bank_statement_line_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_bank_statement_line_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_currency text;
BEGIN
  SELECT upper(currency) INTO v_currency
    FROM public.bank_accounts WHERE id = NEW.bank_account_id;
  IF v_currency IS NULL THEN
    RAISE EXCEPTION 'Bank statement line requires an active bank account';
  END IF;
  IF upper(COALESCE(NEW.currency, '')) <> v_currency THEN
    RAISE EXCEPTION 'Bank statement currency % does not match bank account currency %', NEW.currency, v_currency
      USING ERRCODE = 'check_violation';
  END IF;
  IF COALESCE(NEW.debit_amount, 0) < 0 OR COALESCE(NEW.credit_amount, 0) < 0
     OR (COALESCE(NEW.debit_amount, 0) > 0 AND COALESCE(NEW.credit_amount, 0) > 0)
     OR (COALESCE(NEW.debit_amount, 0) = 0 AND COALESCE(NEW.credit_amount, 0) = 0) THEN
    RAISE EXCEPTION 'Bank statement line must have exactly one positive debit or credit amount'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_broker_items("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_broker_items"("p_expense_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_amount        NUMERIC;
  v_ppn_amount    NUMERIC;
  v_items_total   NUMERIC;
  v_ppn_items_sum NUMERIC;
  v_ppn_present   BOOLEAN;
BEGIN
  SELECT
    amount,
    COALESCE(ppn_amount, 0),
    -- For 'included' lines, item.amount is gross (DPP+PPN); parent.amount stores
    -- DPP-only (matches client roll-up and prevents GL trigger double-count).
    (SELECT SUM((item->>'amount')::NUMERIC
                - CASE WHEN item->>'ppn_treatment' = 'included'
                       THEN COALESCE((item->>'ppn_amount')::NUMERIC, 0)
                       ELSE 0 END)
       FROM jsonb_array_elements(broker_items) AS item),
    (SELECT SUM(COALESCE((item->>'ppn_amount')::NUMERIC, 0))
       FROM jsonb_array_elements(broker_items) AS item),
    EXISTS (
      SELECT 1 FROM jsonb_array_elements(broker_items) AS item
       WHERE (item ? 'ppn_amount') AND (item->>'ppn_amount') IS NOT NULL
    )
  INTO v_amount, v_ppn_amount, v_items_total, v_ppn_items_sum, v_ppn_present
  FROM finance_expenses
  WHERE id = p_expense_id;

  -- No broker_items → always valid (unchanged behaviour)
  IF v_items_total IS NULL THEN
    RETURN TRUE;
  END IF;

  -- Existing invariant: sum of line amounts = parent amount
  IF v_items_total <> v_amount THEN
    RETURN FALSE;
  END IF;

  -- New guard: if any line carries ppn_amount, the roll-up must match parent
  IF v_ppn_present AND ABS(COALESCE(v_ppn_items_sum, 0) - v_ppn_amount) > 1 THEN
    RETURN FALSE;
  END IF;

  RETURN TRUE;
END $$;


--
-- Name: validate_dc_item_product_reservation_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_dc_item_product_reservation_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_dc record; v_reserved numeric; v_pending numeric; v_so_make uuid; v_batch_make uuid;
BEGIN
  SELECT dc.sales_order_id,dc.approval_status INTO v_dc FROM public.delivery_challans dc WHERE dc.id=NEW.challan_id;
  IF NOT FOUND OR NEW.sales_order_item_id IS NULL THEN RAISE EXCEPTION 'DC item requires a canonical SO item'; END IF;
  SELECT soi.make_id INTO v_so_make FROM public.sales_order_items soi
   WHERE soi.id=NEW.sales_order_item_id AND soi.sales_order_id=v_dc.sales_order_id AND soi.product_id=NEW.product_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'DC product does not match its SO item'; END IF;
  SELECT b.make_id INTO v_batch_make FROM public.batches b
   WHERE b.id=NEW.batch_id AND b.product_id=NEW.product_id AND b.is_active
     AND (b.expiry_date IS NULL OR b.expiry_date>CURRENT_DATE);
  IF NOT FOUND THEN RAISE EXCEPTION 'Selected DC batch is not eligible for this product'; END IF;
  -- NULL Make preserves historical records; known Make must match exactly.
  IF v_so_make IS NOT NULL AND v_batch_make IS DISTINCT FROM v_so_make THEN
    RAISE EXCEPTION 'Selected DC batch Make does not match the Sales Order Make';
  END IF;
  SELECT COALESCE(reserved_quantity,0) INTO v_reserved FROM public.so_product_reservations
    WHERE sales_order_item_id=NEW.sales_order_item_id AND status='active';
  SELECT COALESCE(sum(dci.quantity),0) INTO v_pending
  FROM public.delivery_challan_items dci JOIN public.delivery_challans dc ON dc.id=dci.challan_id
  WHERE dci.sales_order_item_id=NEW.sales_order_item_id AND dc.approval_status='pending_approval'
    AND dci.id IS DISTINCT FROM NEW.id;
  IF v_pending+NEW.quantity>v_reserved THEN RAISE EXCEPTION 'DC quantities exceed remaining SO product reservation'; END IF;
  RETURN NEW;
END; $$;


--
-- Name: validate_delivery_challan_complete_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_delivery_challan_complete_source"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.sales_order_id IS NOT NULL AND NEW.customer_id IS DISTINCT FROM (SELECT customer_id FROM public.sales_orders WHERE id=NEW.sales_order_id) THEN
    RAISE EXCEPTION 'Delivery Challan customer must match Sales Order customer';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_delivery_challan_source_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_delivery_challan_source_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_dc public.delivery_challans%rowtype; v_soi public.sales_order_items%rowtype; v_remaining numeric;
BEGIN
  SELECT * INTO v_dc FROM public.delivery_challans WHERE id=NEW.challan_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Delivery Challan does not exist'; END IF;
  IF v_dc.sales_order_id IS NULL THEN
    IF NEW.sales_order_item_id IS NOT NULL THEN RAISE EXCEPTION 'Unlinked Delivery Challan cannot reference a Sales Order item'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.sales_order_item_id IS NULL THEN
    SELECT soi.id INTO NEW.sales_order_item_id
    FROM public.sales_order_items soi
    WHERE soi.sales_order_id=v_dc.sales_order_id AND soi.product_id=NEW.product_id;
    IF NEW.sales_order_item_id IS NULL THEN RAISE EXCEPTION 'Delivery Challan product is not present on the selected Sales Order'; END IF;
    IF (SELECT count(*) FROM public.sales_order_items soi WHERE soi.sales_order_id=v_dc.sales_order_id AND soi.product_id=NEW.product_id) > 1 THEN
      RAISE EXCEPTION 'Delivery Challan item source is ambiguous; select the exact Sales Order item';
    END IF;
  END IF;
  IF NEW.sales_order_item_id IS NULL THEN RAISE EXCEPTION 'Sales Order-linked Delivery Challan item requires sales_order_item_id'; END IF;
  SELECT * INTO v_soi FROM public.sales_order_items WHERE id=NEW.sales_order_item_id AND sales_order_id=v_dc.sales_order_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Delivery Challan item is not from the selected Sales Order'; END IF;
  IF NEW.product_id IS DISTINCT FROM v_soi.product_id THEN RAISE EXCEPTION 'Delivery Challan product must match the Sales Order item'; END IF;
  v_remaining:=v_soi.quantity-COALESCE(v_soi.delivered_quantity,0);
  IF TG_OP='UPDATE' THEN v_remaining:=v_remaining+COALESCE(OLD.quantity,0); END IF;
  IF NEW.quantity<=0 OR NEW.quantity>v_remaining+0.0001 THEN RAISE EXCEPTION 'Delivery quantity exceeds remaining Sales Order quantity'; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_expense_bank_allocation_against_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_expense_bank_allocation_against_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_payable numeric; v_allocated numeric; v_journal_cash numeric;
BEGIN
  IF NEW.document_type<>'expense' THEN RETURN NEW; END IF;
  v_payable:=CASE WHEN NEW.payment_kind='pph23'
    THEN COALESCE((SELECT pph_amount FROM public.finance_expenses WHERE id=NEW.document_id),0)
    ELSE COALESCE(public.calculate_finance_expense_payable(NEW.document_id),0) END;
  SELECT COALESCE(sum(allocation_amount),0)+NEW.allocation_amount INTO v_allocated
    FROM public.bank_statement_allocations
   WHERE document_type='expense' AND document_id=NEW.document_id
     AND payment_kind=NEW.payment_kind AND (TG_OP<>'UPDATE' OR id<>NEW.id);
  IF v_allocated>v_payable+0.01 THEN RAISE EXCEPTION 'Allocation exceeds document outstanding amount'; END IF;
  IF (SELECT source_module FROM public.journal_entries WHERE id=NEW.journal_entry_id)='expense_payment' THEN
    SELECT COALESCE(sum(l.credit),0) INTO v_journal_cash
      FROM public.journal_entry_lines l JOIN public.bank_accounts ba ON ba.coa_id=l.account_id
     WHERE l.journal_entry_id=NEW.journal_entry_id;
    IF abs(v_journal_cash-NEW.allocation_amount)>0.01 THEN
      RAISE EXCEPTION 'Expense payment journal bank credit must equal the confirmed allocation amount';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_expense_category_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_expense_category_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_category public.expense_categories%ROWTYPE;
  v_coa public.chart_of_accounts%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.expense_category = 'utilities'
     AND NEW.expense_category = 'utilities' THEN
    RETURN NEW;
  END IF;

  IF NULLIF(btrim(NEW.expense_category), '') IS NULL THEN
    RAISE EXCEPTION 'Expense category is required.' USING ERRCODE = '23514';
  END IF;

  SELECT * INTO v_category
    FROM public.expense_categories
   WHERE category_key = NEW.expense_category;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense category "%" does not exist in Expense Category Master.',
      NEW.expense_category USING ERRCODE = '23514';
  END IF;
  IF NOT v_category.is_active THEN
    RAISE EXCEPTION 'Expense category "%" is inactive.', v_category.name
      USING ERRCODE = '23514';
  END IF;
  IF NOT v_category.is_posting_category THEN
    RAISE EXCEPTION 'Expense category "%" is a grouping category. Select an active posting leaf.',
      v_category.name USING ERRCODE = '23514';
  END IF;
  IF v_category.coa_account_id IS NULL THEN
    RAISE EXCEPTION 'Expense category "%" has no configured Chart of Account.',
      v_category.name USING ERRCODE = '23514';
  END IF;

  SELECT * INTO v_coa
    FROM public.chart_of_accounts
   WHERE id = v_category.coa_account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense category "%" references a missing Chart of Account.',
      v_category.name USING ERRCODE = '23514';
  END IF;
  IF NOT v_coa.is_active OR v_coa.is_header THEN
    RAISE EXCEPTION 'Expense category "%" must use an active non-header Chart of Account.',
      v_category.name USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_expense_category_master(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_expense_category_master"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_account record;
BEGIN
  IF NEW.parent_id = NEW.id THEN
    RAISE EXCEPTION 'An expense category cannot be its own parent';
  END IF;

  IF NOT NEW.is_posting_category THEN
    NEW.coa_account_id := NULL;
  ELSE
    SELECT is_active, is_header INTO v_account
    FROM public.chart_of_accounts WHERE id=NEW.coa_account_id;
    IF NOT FOUND OR NOT v_account.is_active OR v_account.is_header THEN
      RAISE EXCEPTION 'Each posting expense category must use an active posting Chart of Account';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: validate_expense_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_expense_context"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_category_type text;
  v_requires_container boolean;
BEGIN
  SELECT category_type, requires_container
    INTO v_category_type, v_requires_container
    FROM public.expense_categories
   WHERE category_key = NEW.expense_category;

  NEW.expense_type := CASE v_category_type
    WHEN 'import' THEN 'import'
    WHEN 'sales' THEN 'sales'
    ELSE 'general'
  END;

  IF COALESCE(v_requires_container, false) AND NEW.import_container_id IS NULL THEN
    RAISE EXCEPTION 'Expense category "%" requires an Import Container.',
      NEW.expense_category USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_fund_transfer_bank_statement_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_fund_transfer_bank_statement_link"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ft public.fund_transfers%rowtype;
  v_ba public.bank_accounts%rowtype;
  v_expected numeric;
  v_amount numeric;
begin
  if new.matched_fund_transfer_id is null then return new; end if;
  select * into v_ft from public.fund_transfers where id=new.matched_fund_transfer_id;
  if not found then raise exception 'Invalid fund transfer link'; end if;
  select * into v_ba from public.bank_accounts where id=new.bank_account_id;
  if not found then raise exception 'Invalid bank account on statement line'; end if;
  if new.transaction_date is distinct from v_ft.transfer_date then
    raise exception 'Fund transfer % date % does not match bank statement date %',v_ft.transfer_number,v_ft.transfer_date,new.transaction_date;
  end if;
  if new.bank_account_id=v_ft.from_bank_account_id then
    v_expected:=v_ft.from_amount;
    v_amount:=coalesce(nullif(new.debit_amount,0),new.credit_amount);
  elsif new.bank_account_id=v_ft.to_bank_account_id then
    v_expected:=v_ft.to_amount;
    v_amount:=coalesce(nullif(new.credit_amount,0),new.debit_amount);
  else
    raise exception 'Bank statement account is not a fund transfer side';
  end if;
  if abs(coalesce(v_amount,0)-coalesce(v_expected,0))>0.01 then
    raise exception 'Fund transfer % amount %.2f does not match bank statement amount %.2f',v_ft.transfer_number,v_expected,v_amount;
  end if;
  if v_ft.journal_entry_id is not null and new.matched_entry_id is not null and new.matched_entry_id<>v_ft.journal_entry_id then
    raise exception 'Fund transfer % must link to its canonical journal entry',v_ft.transfer_number;
  end if;
  if v_ft.journal_entry_id is null and new.matched_entry_id is not null then
    raise exception 'Fund transfer % has no canonical journal entry',v_ft.transfer_number;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION "validate_fund_transfer_bank_statement_link"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."validate_fund_transfer_bank_statement_link"() IS 'Prevents false fund-transfer reconciliation: linked statement must be the correct transfer side, exact amount, exact transfer date, and canonical journal.';


--
-- Name: validate_fund_transfer_fx(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_fund_transfer_fx"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      DECLARE
        v_from numeric;
        v_to   numeric;
        v_rate numeric;
        v_expected numeric;
      BEGIN
        IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;

        v_from := COALESCE(NEW.from_amount, 0);
        v_to   := COALESCE(NEW.to_amount, 0);
        v_rate := COALESCE(NEW.exchange_rate, 1);

        IF v_from <= 0 OR v_to <= 0 THEN
          RAISE EXCEPTION 'Fund transfer amounts must be positive';
        END IF;
        IF v_rate <= 0 THEN
          RAISE EXCEPTION 'exchange_rate must be positive';
        END IF;

        v_expected := v_from * v_rate;
        IF abs(v_to - v_expected) / GREATEST(v_to, 1) > 0.02 THEN
          RAISE EXCEPTION 'FX inconsistency: to_amount % differs from from_amount % * rate % by more than 2%%',
            v_to, v_from, v_rate;
        END IF;

        RETURN NEW;
      END $$;


--
-- Name: validate_historical_pph_payment_exception(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_historical_pph_payment_exception"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.historical_source_status = 'missing_source_verified' THEN
    IF NEW.tax_type NOT IN ('PPh21','PPh22','PPh23','PPh4(2)')
       OR NULLIF(btrim(COALESCE(NEW.historical_source_reference,'')), '') IS NULL
       OR NEW.journal_entry_id IS NULL
       OR NOT EXISTS (
         SELECT 1 FROM public.journal_entries je
          WHERE je.id=NEW.journal_entry_id AND je.is_posted AND NOT COALESCE(je.is_reversed,false)
       )
       OR NOT EXISTS (
         SELECT 1
           FROM public.bank_statement_allocations a
           JOIN public.bank_statement_lines bsl ON bsl.id=a.bank_statement_line_id
          WHERE a.document_type='tax_payment' AND a.document_id=NEW.id
            AND a.journal_entry_id=NEW.journal_entry_id
            AND bsl.matched_tax_payment_id=NEW.id
            AND abs(COALESCE(a.allocation_amount,0)-NEW.amount)<0.01
       ) THEN
      RAISE EXCEPTION 'Historical PPh exception requires matching posted journal, full canonical bank allocation, and source reference';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_invoice_dc_items("jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_invoice_dc_items"("p_items" "jsonb", "p_exclude_invoice_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("is_valid" boolean, "error_message" "text", "invalid_items" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_item JSONB;
v_dc_item_id UUID;
v_requested_quantity NUMERIC;
v_available_quantity NUMERIC;
v_errors JSONB := '[]'::JSONB;
v_has_errors BOOLEAN := FALSE;
BEGIN
-- Loop through each item to validate
FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
LOOP
v_dc_item_id := (v_item->>'dc_item_id')::UUID;
v_requested_quantity := (v_item->>'quantity')::NUMERIC;

-- Skip validation for manual items (no dc_item_id)
IF v_dc_item_id IS NULL THEN
CONTINUE;
END IF;

-- Get available quantity for this DC item
SELECT 
dis.original_quantity - dis.invoiced_quantity +
-- Add back quantity from the invoice being edited (if any)
COALESCE(
(SELECT SUM(sii.quantity) 
FROM sales_invoice_items sii 
WHERE sii.delivery_challan_item_id = v_dc_item_id 
AND sii.invoice_id = p_exclude_invoice_id),
0
)
INTO v_available_quantity
FROM dc_item_invoice_status dis
WHERE dis.dc_item_id = v_dc_item_id;

-- Check if requested quantity exceeds available
IF v_requested_quantity > v_available_quantity THEN
v_has_errors := TRUE;
v_errors := v_errors || jsonb_build_object(
'dc_item_id', v_dc_item_id,
'product_name', v_item->>'product_name',
'batch_number', v_item->>'batch_number',
'requested_quantity', v_requested_quantity,
'available_quantity', v_available_quantity,
'error', format('Requested quantity %s exceeds available quantity %s', 
v_requested_quantity, v_available_quantity)
);
END IF;
END LOOP;

-- Return results
RETURN QUERY SELECT 
NOT v_has_errors,
CASE 
WHEN v_has_errors THEN 'Some DC items have insufficient quantity available'
ELSE 'All items validated successfully'
END,
v_errors;
END;
$$;


--
-- Name: FUNCTION "validate_invoice_dc_items"("p_items" "jsonb", "p_exclude_invoice_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."validate_invoice_dc_items"("p_items" "jsonb", "p_exclude_invoice_id" "uuid") IS 'Validates that requested DC item quantities do not exceed available quantities. Prevents over-invoicing of DC items.';


--
-- Name: validate_non_permanent_employee_fee(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_non_permanent_employee_fee"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_pph21_code uuid;
BEGIN
  IF NEW.expense_category = 'non_permanent_employee_fee' THEN
    IF NEW.supplier_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.suppliers s
      WHERE s.id = NEW.supplier_id
        AND lower(COALESCE(s.supplier_type,'')) IN (
          'employee','non-permanent individual','freelancer','casual worker','honorarium recipient'
        )
    ) THEN
      RAISE EXCEPTION 'Non-Permanent Employee Fee is intended for an individual subject to PPh 21, not a company supplier';
    END IF;

    -- Default only. An explicit accountant-selected tax code is preserved.
    IF NEW.pph_code_id IS NULL THEN
      SELECT id INTO v_pph21_code FROM public.tax_codes
      WHERE tax_type = 'PPh21' AND is_withholding = true
      ORDER BY (code = 'PPH21') DESC, code LIMIT 1;
      IF v_pph21_code IS NULL THEN
        RAISE EXCEPTION 'PPh21 tax code is not configured';
      END IF;
      NEW.pph_code_id := v_pph21_code;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "validate_non_permanent_employee_fee"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."validate_non_permanent_employee_fee"() IS 'Defaults Non-Permanent Employee Fee expenses to PPh21 while preserving accountant tax-code overrides.';


--
-- Name: validate_petty_cash_chain_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_petty_cash_chain_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ft public.fund_transfers%rowtype;
  v_je public.journal_entries%rowtype;
  v_pc_account uuid;
  v_pc_debit numeric := 0;
  v_pc_credit numeric := 0;
  v_expense_account uuid;
BEGIN
  IF NEW.fund_transfer_id IS NOT NULL THEN
    SELECT * INTO v_ft FROM public.fund_transfers WHERE id=NEW.fund_transfer_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Petty Cash % references missing fund transfer',NEW.id; END IF;
    IF NEW.transaction_type <> 'withdraw' OR v_ft.to_account_type <> 'petty_cash'
       OR abs(NEW.amount-COALESCE(v_ft.to_amount,v_ft.amount)) > 0.01 THEN
      RAISE EXCEPTION 'Petty Cash % amount/direction does not match Fund Transfer %',NEW.id,v_ft.transfer_number USING ERRCODE='check_violation';
    END IF;
  END IF;

  SELECT id INTO v_pc_account FROM public.chart_of_accounts WHERE code='1102' AND is_header=false AND is_active=true LIMIT 1;
  IF NEW.approval_status='approved' AND COALESCE(NEW.source,'') NOT LIKE 'historical_expense:%'
     AND NEW.transaction_type='expense' THEN
    SELECT je.* INTO v_je FROM public.journal_entries je
     WHERE je.source_module='petty_cash' AND je.reference_id=NEW.id AND je.is_posted AND NOT COALESCE(je.is_reversed,false);
    IF NOT FOUND THEN RAISE EXCEPTION 'Approved Petty Cash expense % has no active canonical journal',NEW.transaction_number; END IF;
    SELECT COALESCE(sum(l.debit),0),COALESCE(sum(l.credit),0) INTO v_pc_debit,v_pc_credit
      FROM public.journal_entry_lines l WHERE l.journal_entry_id=v_je.id AND l.account_id=v_pc_account;
    IF abs(v_pc_credit-NEW.amount)>0.01 OR v_pc_debit>0.01 THEN
      RAISE EXCEPTION 'Petty Cash expense % journal amount/direction mismatch',NEW.transaction_number USING ERRCODE='check_violation';
    END IF;
    v_expense_account:=public.get_expense_account_id(NEW.expense_category);
    IF NOT EXISTS (SELECT 1 FROM public.journal_entry_lines l WHERE l.journal_entry_id=v_je.id AND l.account_id=v_expense_account AND abs(l.debit-NEW.amount)<=0.01 AND l.credit=0) THEN
      RAISE EXCEPTION 'Petty Cash expense % journal account/category mismatch',NEW.transaction_number USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "validate_petty_cash_chain_integrity"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."validate_petty_cash_chain_integrity"() IS 'Deferred Petty Cash amount, direction, canonical journal and category guard; historical_expense rows are explicitly legacy.';


--
-- Name: validate_petty_cash_journal_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_petty_cash_journal_reference"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.source_module='petty_cash' AND NEW.is_posted AND NEW.reference_id IS NULL THEN
    RAISE EXCEPTION 'Posted Petty Cash journal requires a canonical transaction reference' USING ERRCODE='check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_petty_cash_transfer_commit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_petty_cash_transfer_commit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status='posted' AND NEW.to_account_type='petty_cash'
     AND NOT EXISTS (SELECT 1 FROM public.petty_cash_transactions pc WHERE pc.fund_transfer_id=NEW.id) THEN
    RAISE EXCEPTION 'Posted Fund Transfer % to Petty Cash requires one canonical Petty Cash transaction',NEW.transfer_number USING ERRCODE='check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "validate_petty_cash_transfer_commit"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."validate_petty_cash_transfer_commit"() IS 'Deferred guard requiring a canonical Petty Cash transaction for newly posted transfers into Petty Cash.';


--
-- Name: validate_salary_advance_payment_purpose(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_salary_advance_payment_purpose"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.payment_purpose = 'salary_advance' THEN
    IF NEW.staff_id IS NULL OR NEW.supplier_id IS NOT NULL THEN
      RAISE EXCEPTION 'Salary Advance payments require a staff payee';
    END IF;
    IF NEW.payment_method = 'advance_adjustment' THEN
      RAISE EXCEPTION 'Salary Advance cash payments cannot use advance_adjustment';
    END IF;
  ELSIF NEW.payment_purpose = 'salary_advance_settlement'
    AND NEW.payment_method <> 'advance_adjustment' THEN
    RAISE EXCEPTION 'Salary Advance settlement must use advance_adjustment';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_sales_invoice_so_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_sales_invoice_so_link"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_so_customer uuid;
  v_so_created_by uuid;
  v_role text;
  v_is_dc_sourced boolean := false;
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
  IF NEW.sales_order_id IS NULL THEN RETURN NEW; END IF;
  IF auth.role() = 'service_role' THEN RETURN NEW; END IF;

  SELECT customer_id, created_by
    INTO v_so_customer, v_so_created_by
  FROM public.sales_orders
  WHERE id = NEW.sales_order_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales order % not found', NEW.sales_order_id;
  END IF;

  IF NEW.customer_id IS DISTINCT FROM v_so_customer THEN
    RAISE EXCEPTION 'Invoice customer_id must match linked sales order customer_id';
  END IF;

  SELECT role INTO v_role
  FROM public.user_profiles
  WHERE id = auth.uid();

  IF v_role IN ('admin','accounts') OR v_so_created_by = auth.uid() THEN
    RETURN NEW;
  END IF;

  IF v_role = 'warehouse' AND COALESCE(array_length(NEW.linked_challan_ids, 1), 0) > 0 THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.delivery_challans dc
      WHERE dc.id = ANY(NEW.linked_challan_ids::uuid[])
        AND dc.sales_order_id = NEW.sales_order_id
    ) INTO v_is_dc_sourced;

    IF v_is_dc_sourced THEN
      RETURN NEW;
    END IF;
  END IF;

  RAISE EXCEPTION 'Only admin/accounts, warehouse staff creating an invoice from its source Delivery Challan, or the SO owner may link this sales order';
END;
$$;


--
-- Name: validate_usd_bank_journal_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."validate_usd_bank_journal_line"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_is_usd boolean;
  v_rate numeric;
BEGIN
  SELECT upper(ba.currency) = 'USD' INTO v_is_usd
    FROM public.bank_accounts ba WHERE ba.coa_id = NEW.account_id AND ba.is_active = true
    LIMIT 1;
  IF NOT COALESCE(v_is_usd, false) THEN RETURN NEW; END IF;
  -- Canonical posters insert lines before the document-row synchronization
  -- trigger fills their currency metadata.  Enforce strictly once bank
  -- evidence is allocated, and on every later mutation of that bank line.
  IF NOT EXISTS (
    SELECT 1 FROM public.bank_statement_allocations a
    WHERE a.journal_entry_id = NEW.journal_entry_id
  ) THEN
    RETURN NEW;
  END IF;
  v_rate := COALESCE(NEW.exchange_rate, 0);
  IF NEW.transaction_currency IS DISTINCT FROM 'USD'
     OR NEW.functional_currency IS DISTINCT FROM 'IDR'
     OR v_rate <= 0
     OR (COALESCE(NEW.transaction_debit, 0) = 0 AND COALESCE(NEW.transaction_credit, 0) = 0)
     OR abs(COALESCE(NEW.debit, 0) - COALESCE(NEW.transaction_debit, 0) * v_rate) > 0.01
     OR abs(COALESCE(NEW.credit, 0) - COALESCE(NEW.transaction_credit, 0) * v_rate) > 0.01
     OR (NEW.debit > 0 AND NEW.transaction_credit > 0)
     OR (NEW.credit > 0 AND NEW.transaction_debit > 0) THEN
    RAISE EXCEPTION 'USD bank journal line has inconsistent transaction/functional currency metadata'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "validate_usd_bank_journal_line"(); Type: COMMENT; Schema: public; Owner: -
--

