--
-- Name: verify_dc_has_items_before_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."verify_dc_has_items_before_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
v_item_count integer;
BEGIN
-- Only check when approval_status is being changed to 'approved'
IF NEW.approval_status = 'approved' AND (OLD.approval_status IS NULL OR OLD.approval_status != 'approved') THEN
-- Check if DC has items
SELECT COUNT(*) INTO v_item_count
FROM delivery_challan_items
WHERE challan_id = NEW.id;

IF v_item_count = 0 THEN
RAISE EXCEPTION 'Cannot approve Delivery Challan %. It has no items. Please add items before approving.',
NEW.challan_number;
END IF;
END IF;

RETURN NEW;
END;
$$;


