--
-- Name: TABLE "batches"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE "public"."batches" IS 'Stock can go negative to handle oversold/backorder scenarios. Double deduction fixed by using approval-based flow only.';


--
-- Name: COLUMN "batches"."import_quantity"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."import_quantity" IS 'Total quantity imported in this batch. This is the maximum stock that can ever be available. 
Can be adjusted upward if more stock is imported under the same batch, but cannot be reduced below the quantity already sold.';


--
-- Name: COLUMN "batches"."current_stock"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."current_stock" IS 'Current available stock for this batch. Must be between 0 and import_quantity. 
Calculated as: import_quantity - total_sold_quantity. 
Only decreases through sales, never increases unless import_quantity is adjusted.';


--
-- Name: COLUMN "batches"."import_price"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."import_price" IS 'Import price in Indonesian Rupiah (IDR)';


--
-- Name: COLUMN "batches"."calculated_packs"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."calculated_packs" IS 'Automatically calculated as import_quantity / per_pack_weight';


--
-- Name: COLUMN "batches"."cost_per_pack"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."cost_per_pack" IS 'Total cost (import + duty + freight + other) / calculated_packs';


--
-- Name: COLUMN "batches"."import_price_usd"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."import_price_usd" IS 'Import price in US Dollars (USD)';


--
-- Name: COLUMN "batches"."exchange_rate_usd_to_idr"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."exchange_rate_usd_to_idr" IS 'Exchange rate from USD to IDR at time of import';


--
-- Name: COLUMN "batches"."duty_charge_type"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."duty_charge_type" IS 'Type of duty charge: percentage (of import price) or fixed (absolute amount in IDR)';


--
-- Name: COLUMN "batches"."freight_charge_type"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."freight_charge_type" IS 'Type of freight charge: percentage (of import price) or fixed (absolute amount in IDR)';


--
-- Name: COLUMN "batches"."other_charge_type"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."other_charge_type" IS 'Type of other charge: percentage (of import price) or fixed (absolute amount in IDR)';


--
-- Name: COLUMN "batches"."import_cost_allocated"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."import_cost_allocated" IS 'Proportional share of container costs allocated to this batch';


--
-- Name: COLUMN "batches"."final_landed_cost"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."final_landed_cost" IS 'Total landed cost in USD = import_price + import_cost_allocated (updated by reallocate_container_costs function)';


--
-- Name: COLUMN "batches"."duty_percent"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."duty_percent" IS 'Import duty % (Form A1) - auto-filled from product, manual override allowed';


--
-- Name: COLUMN "batches"."landed_cost_per_unit"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."landed_cost_per_unit" IS 'Landed cost per unit in USD = (import_price + import_cost_allocated) / import_quantity';


--
-- Name: COLUMN "batches"."import_price_per_unit"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."import_price_per_unit" IS 'Import price per unit (USD per KG) = import_price / import_quantity';


--
-- Name: COLUMN "batches"."make_id"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."batches"."make_id" IS 'Optional link to product_sources; NULL means historical make not recorded.';


