    CONSTRAINT "purchase_invoices_purchase_type_check" CHECK ((("purchase_type")::"text" = ANY ((ARRAY['inventory'::character varying, 'fixed_asset'::character varying, 'expense'::character varying, 'import'::character varying])::"text"[]))),
    CONSTRAINT "purchase_invoices_receiving_approval_status_check" CHECK (("receiving_approval_status" = ANY (ARRAY['draft'::"text", 'pending_approval'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "purchase_invoices_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['draft'::character varying, 'unpaid'::character varying, 'partial'::character varying, 'paid'::character varying, 'cancelled'::character varying])::"text"[])))
);


