--
-- Name: finance_historical_repair_exception_details; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."finance_historical_repair_exception_details" WITH ("security_invoker"='true') AS
 WITH "exceptions" AS (
         SELECT "e"."id",
            "e"."run_id",
            "e"."document_type",
            "e"."document_id",
            "e"."document_number",
            "e"."inconsistent_fields",
            "e"."reason",
            "e"."manual_information_required",
            "e"."status",
            "e"."created_at",
                CASE
                    WHEN (("e"."reason" ~~* '%USD%rate%'::"text") OR ("e"."reason" ~~* '%USD-source Contra%'::"text") OR ("e"."reason" ~~* '%does not use the Expense bank account%'::"text") OR ("e"."reason" ~~* '%does not post to this bank account%'::"text") OR ("e"."reason" ~~* '%without an accrued payable%'::"text")) THEN 'Historical accounting decision required'::"text"
                    WHEN (("e"."reason" ~~* '%multiple typed%'::"text") OR ("e"."reason" ~~* '%no provable active journal%'::"text")) THEN 'Manual relink required'::"text"
                    WHEN (("e"."reason" ~~* '%Approved expense has no active journal%'::"text") OR ("e"."reason" ~~* '%Journal metadata cannot be derived%'::"text")) THEN 'Missing source document'::"text"
                    WHEN (("e"."reason" ~~* '%No unique authoritative relationship%'::"text") OR ("e"."reason" ~~* '%metadata conflicts%'::"text") OR ("e"."reason" ~~* '%missing Faktur Pajak%'::"text")) THEN 'Manual edit required'::"text"
                    ELSE 'Investigate further'::"text"
                END AS "classification"
           FROM "public"."finance_historical_repair_exceptions" "e"
          WHERE ("e"."status" = 'manual_review'::"text")
        ), "details" AS (
         SELECT "e"."run_id",
            "e"."document_type",
            COALESCE("e"."document_number", NULLIF("bsl"."reference", ''::"text")) AS "document_number",
            "e"."document_id" AS "database_id",
            COALESCE("fe"."expense_date", "rv"."voucher_date", "pv"."voucher_date", "ft"."transfer_date", "l"."loan_date", "lt"."transaction_date", "cc"."voucher_date", "pc"."transaction_date", "tp"."payment_date", "si"."invoice_date", "pi"."invoice_date", "je"."entry_date", "bsl"."transaction_date") AS "document_date",
            COALESCE("fe"."amount", "rv"."amount", "pv"."amount", "ft"."amount", "l"."principal_amount", "lt"."amount", "cc"."amount", "pc"."amount", "tp"."amount", "si"."total_amount", "pi"."total_amount", "je"."total_debit", NULLIF("bsl"."debit_amount", (0)::numeric), "bsl"."credit_amount") AS "amount",
            COALESCE("fe"."transaction_currency", "fe"."currency_code", "fe"."payment_currency", "fe"."bank_account_currency", "rv"."transaction_currency", "rv"."currency_code", "rv"."payment_currency", "rv"."bank_account_currency", "pv"."transaction_currency", "pv"."currency_code", ("pv"."payment_currency")::"text", "pv"."bank_account_currency", "l"."transaction_currency", "l"."currency", "l"."bank_account_currency", "lt"."transaction_currency", "lt"."bank_account_currency", "cc"."transaction_currency", "cc"."bank_account_currency", ("pi"."currency")::"text", "je"."transaction_currency", "je"."functional_currency", "bsl"."currency", "ba"."currency",
                CASE
                    WHEN (("ft"."id" IS NOT NULL) AND ("fba"."currency" = "tba"."currency")) THEN "fba"."currency"
                    ELSE NULL::"text"
                END, 'IDR'::"text") AS "currency",
            COALESCE("expense_supplier"."company_name", ("receipt_customer"."company_name")::character varying, "payment_supplier"."company_name", ("sales_customer"."company_name")::character varying, "purchase_supplier"."company_name", ("l"."counterparty_name")::character varying, ("parent_loan"."counterparty_name")::character varying, (NULLIF(("pc"."paid_to")::"text", ''::"text"))::character varying) AS "customer_supplier",
                CASE
                    WHEN ("ft"."id" IS NOT NULL) THEN "concat_ws"(' -> '::"text", "concat_ws"(' · '::"text", "fba"."bank_name", "fba"."account_number", "fba"."currency"), "concat_ws"(' · '::"text", "tba"."bank_name", "tba"."account_number", "tba"."currency"))
                    ELSE "concat_ws"(' · '::"text", "ba"."bank_name", "ba"."account_number", "ba"."currency")
                END AS "bank_account",
            "source_je"."entry_number" AS "journal_number",
            "e"."inconsistent_fields",
            "e"."reason",
            "e"."manual_information_required",
            "e"."classification",
            "e"."created_at"
           FROM ((((((((((((((((((((((("exceptions" "e"
             LEFT JOIN "public"."finance_expenses" "fe" ON ((("e"."document_type" = 'expense'::"text") AND ("fe"."id" = "e"."document_id"))))
             LEFT JOIN "public"."receipt_vouchers" "rv" ON ((("e"."document_type" = 'receipt'::"text") AND ("rv"."id" = "e"."document_id"))))
             LEFT JOIN "public"."payment_vouchers" "pv" ON ((("e"."document_type" = 'payment'::"text") AND ("pv"."id" = "e"."document_id"))))
             LEFT JOIN "public"."fund_transfers" "ft" ON ((("e"."document_type" = 'fund_transfer'::"text") AND ("ft"."id" = "e"."document_id"))))
             LEFT JOIN "public"."loans" "l" ON ((("e"."document_type" = 'loan'::"text") AND ("l"."id" = "e"."document_id"))))
             LEFT JOIN "public"."loan_transactions" "lt" ON ((("e"."document_type" = ANY (ARRAY['loan_transaction'::"text", 'loan_repayment'::"text"])) AND ("lt"."id" = "e"."document_id"))))
             LEFT JOIN "public"."loans" "parent_loan" ON (("parent_loan"."id" = "lt"."loan_id")))
             LEFT JOIN "public"."capital_contributions" "cc" ON ((("e"."document_type" = 'capital_contribution'::"text") AND ("cc"."id" = "e"."document_id"))))
             LEFT JOIN "public"."petty_cash_transactions" "pc" ON ((("e"."document_type" = 'petty_cash'::"text") AND ("pc"."id" = "e"."document_id"))))
             LEFT JOIN "public"."tax_payments" "tp" ON ((("e"."document_type" = 'tax_payment'::"text") AND ("tp"."id" = "e"."document_id"))))
             LEFT JOIN "public"."sales_invoices" "si" ON ((("e"."document_type" = 'sales_invoice'::"text") AND ("si"."id" = "e"."document_id"))))
             LEFT JOIN "public"."purchase_invoices" "pi" ON ((("e"."document_type" = 'purchase_invoice'::"text") AND ("pi"."id" = "e"."document_id"))))
             LEFT JOIN "public"."journal_entries" "je" ON ((("e"."document_type" = 'journal'::"text") AND ("je"."id" = "e"."document_id"))))
             LEFT JOIN "public"."bank_statement_lines" "bsl" ON ((("e"."document_type" = 'bank_reconciliation'::"text") AND ("bsl"."id" = "e"."document_id"))))
             LEFT JOIN "public"."suppliers" "expense_supplier" ON (("expense_supplier"."id" = "fe"."supplier_id")))
             LEFT JOIN "public"."customers" "receipt_customer" ON (("receipt_customer"."id" = "rv"."customer_id")))
             LEFT JOIN "public"."suppliers" "payment_supplier" ON (("payment_supplier"."id" = "pv"."supplier_id")))
             LEFT JOIN "public"."customers" "sales_customer" ON (("sales_customer"."id" = "si"."customer_id")))
             LEFT JOIN "public"."suppliers" "purchase_supplier" ON (("purchase_supplier"."id" = "pi"."supplier_id")))
             LEFT JOIN "public"."bank_accounts" "fba" ON (("fba"."id" = "ft"."from_bank_account_id")))
             LEFT JOIN "public"."bank_accounts" "tba" ON (("tba"."id" = "ft"."to_bank_account_id")))
             LEFT JOIN "public"."bank_accounts" "ba" ON (("ba"."id" = COALESCE("fe"."bank_account_id", "rv"."bank_account_id", "pv"."bank_account_id", "l"."bank_account_id", "lt"."bank_account_id", "cc"."bank_account_id", "pc"."bank_account_id", "tp"."bank_account_id", "bsl"."bank_account_id"))))
             LEFT JOIN LATERAL ( SELECT "j"."entry_number"
                   FROM "public"."journal_entries" "j"
                  WHERE ((("e"."document_type" = 'journal'::"text") AND ("j"."id" = "je"."id")) OR (("e"."document_type" = 'expense'::"text") AND (("j"."source_module")::"text" = ANY ((ARRAY['expense'::character varying, 'expenses'::character varying])::"text"[])) AND (("j"."reference_id" = "fe"."id") OR (("j"."reference_number")::"text" = ('EXP-'::"text" || ("fe"."id")::"text")))) OR (("e"."document_type" = 'receipt'::"text") AND ("j"."id" = "rv"."journal_entry_id")) OR (("e"."document_type" = 'payment'::"text") AND ("j"."id" = "pv"."journal_entry_id")) OR (("e"."document_type" = 'fund_transfer'::"text") AND ("j"."id" = "ft"."journal_entry_id")) OR (("e"."document_type" = 'loan'::"text") AND ("j"."id" = "l"."journal_entry_id")) OR (("e"."document_type" = ANY (ARRAY['loan_transaction'::"text", 'loan_repayment'::"text"])) AND ("j"."id" = "lt"."journal_entry_id")) OR (("e"."document_type" = 'capital_contribution'::"text") AND ("j"."id" = "cc"."journal_entry_id")) OR (("e"."document_type" = 'petty_cash'::"text") AND (("j"."source_module")::"text" = 'petty_cash'::"text") AND ("j"."reference_id" = "pc"."id")) OR (("e"."document_type" = 'tax_payment'::"text") AND ("j"."id" = "tp"."journal_entry_id")) OR (("e"."document_type" = 'sales_invoice'::"text") AND ("j"."id" = "si"."journal_entry_id")) OR (("e"."document_type" = 'purchase_invoice'::"text") AND ("j"."id" = "pi"."journal_entry_id")) OR (("e"."document_type" = 'bank_reconciliation'::"text") AND ("j"."id" = "bsl"."matched_entry_id")))
                  ORDER BY "j"."is_posted" DESC, COALESCE("j"."is_reversed", false), "j"."created_at" DESC
                 LIMIT 1) "source_je" ON (true))
        )
 SELECT "run_id",
    "document_type",
    COALESCE("document_number", '(none)'::"text") AS "document_number",
    "database_id",
    "document_date" AS "date",
    "amount",
    COALESCE("currency", 'Unknown'::"text") AS "currency",
    "customer_supplier",
    "bank_account",
    "journal_number",
    "array_to_string"("inconsistent_fields", ', '::"text") AS "exact_problem_fields",
    "reason" AS "exact_problem",
    "reason" AS "why_cannot_repair_automatically",
    "classification",
        CASE "classification"
            WHEN 'Historical accounting decision required'::"text" THEN "manual_information_required"
            WHEN 'Manual relink required'::"text" THEN "manual_information_required"
            WHEN 'Missing source document'::"text" THEN "manual_information_required"
            WHEN 'Manual edit required'::"text" THEN "manual_information_required"
            ELSE 'Investigate the source document, journal, bank line, and audit trail before making any change'::"text"
        END AS "recommended_action",
    false AS "safe_to_delete_and_recreate",
    'Keep — deletion/recreation could remove audit evidence or rewrite posted history; resolve through an authorised manual correction'::"text" AS "disposition",
    "created_at"
   FROM "details";


--
-- Name: finance_historical_repair_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."finance_historical_repair_items" (
    "id" bigint NOT NULL,
    "run_id" "uuid" NOT NULL,
    "document_type" "text" NOT NULL,
    "document_id" "uuid" NOT NULL,
    "document_number" "text",
    "repaired_fields" "text"[] NOT NULL,
    "old_metadata" "jsonb" NOT NULL,
    "new_metadata" "jsonb" NOT NULL,
    "repair_reason" "text" NOT NULL,
    "repaired_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: finance_historical_repair_verification; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."finance_historical_repair_verification" WITH ("security_invoker"='true') AS
 WITH "repaired" AS (
         SELECT "finance_historical_repair_items"."run_id",
            "finance_historical_repair_items"."document_type",
            "finance_historical_repair_items"."document_id",
            "bool_or"((("finance_historical_repair_items"."repair_reason" ~~* '%Bank Reconciliation%'::"text") OR ("finance_historical_repair_items"."document_type" = 'bank_reconciliation'::"text"))) AS "reconciliation_expected"
           FROM "public"."finance_historical_repair_items"
          GROUP BY "finance_historical_repair_items"."run_id", "finance_historical_repair_items"."document_type", "finance_historical_repair_items"."document_id"
        ), "resolved" AS (
         SELECT "r"."run_id",
            "r"."document_type",
            "r"."document_id",
            "r"."reconciliation_expected",
            "fe"."voucher_number" AS "document_number",
            true AS "source_exists",
            ("fe"."approval_status" = 'approved'::"text") AS "posting_expected",
            "je"."id" AS "active_journal_id",
            ("fe"."bank_account_id" IS NOT NULL) AS "bank_expected",
            false AS "party_expected",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."bank_statement_lines" "b"
                  WHERE (("b"."matched_expense_id" = "fe"."id") OR (("je"."id" IS NOT NULL) AND ("b"."matched_entry_id" = "je"."id")))) AS "bank_link_count"
           FROM (("repaired" "r"
             JOIN "public"."finance_expenses" "fe" ON ((("r"."document_type" = 'expense'::"text") AND ("fe"."id" = "r"."document_id"))))
             LEFT JOIN LATERAL ( SELECT "j"."id"
                   FROM "public"."journal_entries" "j"
                  WHERE ((("j"."source_module")::"text" = 'expenses'::"text") AND (("j"."reference_id" = "fe"."id") OR (("j"."reference_number")::"text" = ('EXP-'::"text" || ("fe"."id")::"text"))) AND ("j"."is_posted" = true) AND (COALESCE("j"."is_reversed", false) = false))
                  ORDER BY "j"."created_at" DESC
                 LIMIT 1) "je" ON (true))
        UNION ALL
         SELECT "r"."run_id",
            "r"."document_type",
            "r"."document_id",
            "r"."reconciliation_expected",
            "rv"."voucher_number",
            true,
            COALESCE("rv"."is_posted", false) AS "coalesce",
                CASE
                    WHEN (("je"."is_posted" = true) AND (COALESCE("je"."is_reversed", false) = false)) THEN "je"."id"
                    ELSE NULL::"uuid"
                END AS "case",
            ("rv"."bank_account_id" IS NOT NULL),
            ("rv"."customer_id" IS NOT NULL),
            ( SELECT "count"(*) AS "count"
                   FROM "public"."bank_statement_lines" "b"
                  WHERE (("b"."matched_receipt_id" = "rv"."id") OR ("b"."matched_entry_id" = "rv"."journal_entry_id"))) AS "count"
           FROM (("repaired" "r"
             JOIN "public"."receipt_vouchers" "rv" ON ((("r"."document_type" = 'receipt'::"text") AND ("rv"."id" = "r"."document_id"))))
             LEFT JOIN "public"."journal_entries" "je" ON (("je"."id" = "rv"."journal_entry_id")))
        UNION ALL
         SELECT "r"."run_id",
            "r"."document_type",
            "r"."document_id",
            "r"."reconciliation_expected",
            "pv"."voucher_number",
            true,
            COALESCE("pv"."is_posted", false) AS "coalesce",
                CASE
                    WHEN (("je"."is_posted" = true) AND (COALESCE("je"."is_reversed", false) = false)) THEN "je"."id"
                    ELSE NULL::"uuid"
                END AS "case",
            ("pv"."bank_account_id" IS NOT NULL),
            (("pv"."supplier_id" IS NOT NULL) OR ("pv"."staff_id" IS NOT NULL)),
            ( SELECT "count"(*) AS "count"
                   FROM "public"."bank_statement_lines" "b"
                  WHERE (("b"."matched_payment_id" = "pv"."id") OR ("b"."matched_entry_id" = "pv"."journal_entry_id"))) AS "count"
           FROM (("repaired" "r"
             JOIN "public"."payment_vouchers" "pv" ON ((("r"."document_type" = 'payment'::"text") AND ("pv"."id" = "r"."document_id"))))
             LEFT JOIN "public"."journal_entries" "je" ON (("je"."id" = "pv"."journal_entry_id")))
        UNION ALL
         SELECT "r"."run_id",
            "r"."document_type",
            "r"."document_id",
            "r"."reconciliation_expected",
            "ft"."transfer_number",
            true,
            ("ft"."status" = 'posted'::"text"),
                CASE
                    WHEN (("je"."is_posted" = true) AND (COALESCE("je"."is_reversed", false) = false)) THEN "je"."id"
                    ELSE NULL::"uuid"
                END AS "case",
            (("ft"."from_bank_account_id" IS NOT NULL) OR ("ft"."to_bank_account_id" IS NOT NULL)),
            false,
            ( SELECT "count"(*) AS "count"
                   FROM "public"."bank_statement_lines" "b"
                  WHERE (("b"."matched_fund_transfer_id" = "ft"."id") OR ("b"."matched_entry_id" = "ft"."journal_entry_id"))) AS "count"
           FROM (("repaired" "r"
             JOIN "public"."fund_transfers" "ft" ON ((("r"."document_type" = 'fund_transfer'::"text") AND ("ft"."id" = "r"."document_id"))))
             LEFT JOIN "public"."journal_entries" "je" ON (("je"."id" = "ft"."journal_entry_id")))
        UNION ALL
         SELECT "r"."run_id",
            "r"."document_type",
            "r"."document_id",
            "r"."reconciliation_expected",
            "je"."entry_number",
            true,
            (("je"."is_posted" = true) AND (COALESCE("je"."is_reversed", false) = false)),
                CASE
                    WHEN (("je"."is_posted" = true) AND (COALESCE("je"."is_reversed", false) = false)) THEN "je"."id"
                    ELSE NULL::"uuid"
                END AS "case",
            (EXISTS ( SELECT 1
                   FROM ("public"."journal_entry_lines" "l"
                     JOIN "public"."bank_accounts" "ba" ON (("ba"."coa_id" = "l"."account_id")))
                  WHERE ("l"."journal_entry_id" = "je"."id"))) AS "exists",
            false,
            ( SELECT "count"(*) AS "count"
                   FROM "public"."bank_statement_lines" "b"
                  WHERE ("b"."matched_entry_id" = "je"."id")) AS "count"
           FROM ("repaired" "r"
             JOIN "public"."journal_entries" "je" ON ((("r"."document_type" = 'journal'::"text") AND ("je"."id" = "r"."document_id"))))
        UNION ALL
         SELECT "r"."run_id",
            "r"."document_type",
            "r"."document_id",
            "r"."reconciliation_expected",
            "b"."reference",
            true,
            ("b"."reconciliation_status" = ANY (ARRAY['matched'::"text", 'recorded'::"text"])),
                CASE
                    WHEN (("je"."is_posted" = true) AND (COALESCE("je"."is_reversed", false) = false)) THEN "je"."id"
                    ELSE NULL::"uuid"
                END AS "case",
            true,
            false,
            (1)::bigint AS "int8"
           FROM (("repaired" "r"
             JOIN "public"."bank_statement_lines" "b" ON ((("r"."document_type" = 'bank_reconciliation'::"text") AND ("b"."id" = "r"."document_id"))))
             LEFT JOIN "public"."journal_entries" "je" ON (("je"."id" = "b"."matched_entry_id")))
        ), "checked" AS (
         SELECT "x"."run_id",
            "x"."document_type",
            "x"."document_id",
            "x"."reconciliation_expected",
            "x"."document_number",
            "x"."source_exists",
            "x"."posting_expected",
            "x"."active_journal_id",
            "x"."bank_expected",
            "x"."party_expected",
            "x"."bank_link_count",
            ((NOT "x"."posting_expected") OR ("x"."active_journal_id" IS NOT NULL)) AS "journal_ok",
            ((NOT "x"."posting_expected") OR (EXISTS ( SELECT 1
                   FROM "public"."journal_entry_lines" "l"
                  WHERE ("l"."journal_entry_id" = "x"."active_journal_id")))) AS "lines_ok",
            ((NOT "x"."bank_expected") OR (NOT "x"."posting_expected") OR (EXISTS ( SELECT 1
                   FROM ("public"."journal_entry_lines" "l"
                     JOIN "public"."bank_accounts" "ba" ON (("ba"."coa_id" = "l"."account_id")))
                  WHERE ("l"."journal_entry_id" = "x"."active_journal_id")))) AS "bank_ok",
            ((NOT "x"."reconciliation_expected") OR ("x"."bank_link_count" > 0)) AS "reconciliation_ok"
           FROM "resolved" "x"
        )
 SELECT "run_id",
    "document_number",
    "document_type",
    "document_id" AS "database_id",
    "source_exists" AS "source_module",
    "journal_ok" AS "journal_register",
    "journal_ok" AS "journal_viewer",
    ("journal_ok" AND "lines_ok") AS "account_ledger",
    "bank_ok" AS "bank_ledger",
    ((NOT "party_expected") OR (NOT "posting_expected") OR ("journal_ok" AND "lines_ok")) AS "party_ledger",
    ("journal_ok" AND "lines_ok") AS "trial_balance",
    ("journal_ok" AND "lines_ok") AS "balance_sheet",
    ("journal_ok" AND "lines_ok") AS "profit_and_loss",
    ("journal_ok" AND "lines_ok") AS "dashboard",
    "reconciliation_ok" AS "bank_reconciliation",
    ("source_exists" AND "journal_ok" AND "lines_ok" AND "bank_ok" AND ((NOT "party_expected") OR (NOT "posting_expected") OR ("journal_ok" AND "lines_ok")) AND "reconciliation_ok") AS "verification_passed"
   FROM "checked";


--
-- Name: finance_historical_repair_verification_failures; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."finance_historical_repair_verification_failures" WITH ("security_invoker"='true') AS
 SELECT "run_id",
    "document_number",
    "document_type",
    "database_id",
    "source_module",
    "journal_register",
    "journal_viewer",
    "account_ledger",
    "bank_ledger",
    "party_ledger",
    "trial_balance",
    "balance_sheet",
    "profit_and_loss",
    "dashboard",
    "bank_reconciliation",
    "verification_passed"
   FROM "public"."finance_historical_repair_verification"
  WHERE (NOT "verification_passed");


--
-- Name: finance_exception_accountant_review_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."finance_exception_accountant_review_dashboard" WITH ("security_invoker"='true') AS
 WITH "unresolved" AS (
         SELECT ('exception:'::"text" || ("e"."id")::"text") AS "row_id",
            "e"."id" AS "exception_id",
            "e"."run_id",
            "e"."document_type",
            "e"."document_id",
            "d"."date",
            "d"."document_number" AS "voucher_number",
            "d"."journal_number",
            "d"."amount",
            "d"."currency",
            "d"."bank_account" AS "bank",
            "d"."customer_supplier",
            "d"."classification",
            "e"."reason",
            "e"."manual_information_required",
            "d"."recommended_action",
            "e"."inconsistent_fields"
           FROM ("public"."finance_historical_repair_exceptions" "e"
             JOIN "public"."finance_historical_repair_exception_details" "d" ON ((("d"."run_id" = "e"."run_id") AND ("d"."document_type" = "e"."document_type") AND ("d"."database_id" = "e"."document_id") AND ("d"."exact_problem" = "e"."reason"))))
          WHERE ("e"."status" = 'manual_review'::"text")
        ), "enriched" AS (
         SELECT "u"."row_id",
            "u"."exception_id",
            "u"."run_id",
            "u"."document_type",
            "u"."document_id",
            "u"."date",
            "u"."voucher_number",
            "u"."journal_number",
            "u"."amount",
            "u"."currency",
            "u"."bank",
            "u"."customer_supplier",
            "u"."classification",
            "u"."reason",
            "u"."manual_information_required",
            "u"."recommended_action",
            "u"."inconsistent_fields",
            COALESCE("fe"."expense_category", ("pc"."expense_category")::"text", "je"."transaction_category", "l"."loan_type", ("cc"."contribution_type")::"text", "tp"."tax_type", ("pi"."purchase_type")::"text", "bsl"."payment_kind") AS "current_category",
            COALESCE("fe"."bank_account_id", "rv"."bank_account_id", "pv"."bank_account_id", "l"."bank_account_id", "lt"."bank_account_id", "cc"."bank_account_id", "pc"."bank_account_id", "tp"."bank_account_id", "bsl"."bank_account_id") AS "current_bank_account_id",
            "source_je"."id" AS "journal_entry_id",
            "current_line"."id" AS "journal_line_id",
            "current_line"."account_id" AS "current_account_id",
            "concat_ws"(' · '::"text", "coa"."code", "coa"."name") AS "current_gl_account",
            "fe"."exchange_rate" AS "expense_exchange_rate",
            COALESCE("fe"."pph_code_id", "pv"."pph_code_id") AS "current_tax_code_id",
            COALESCE("fe"."payment_method", "rv"."payment_method", "pv"."payment_method", ("bsl"."payment_kind")::character varying) AS "current_payment_type",
            "source_je"."source_module" AS "current_document_classification",
            COALESCE("si"."faktur_pajak_number", "pi"."faktur_pajak_number") AS "current_faktur_pajak_number"
           FROM (((((((((((((((("unresolved" "u"
             LEFT JOIN "public"."finance_expenses" "fe" ON ((("u"."document_type" = 'expense'::"text") AND ("fe"."id" = "u"."document_id"))))
             LEFT JOIN "public"."receipt_vouchers" "rv" ON ((("u"."document_type" = 'receipt'::"text") AND ("rv"."id" = "u"."document_id"))))
             LEFT JOIN "public"."payment_vouchers" "pv" ON ((("u"."document_type" = 'payment'::"text") AND ("pv"."id" = "u"."document_id"))))
             LEFT JOIN "public"."fund_transfers" "ft" ON ((("u"."document_type" = 'fund_transfer'::"text") AND ("ft"."id" = "u"."document_id"))))
             LEFT JOIN "public"."loans" "l" ON ((("u"."document_type" = 'loan'::"text") AND ("l"."id" = "u"."document_id"))))
             LEFT JOIN "public"."loan_transactions" "lt" ON ((("u"."document_type" = ANY (ARRAY['loan_transaction'::"text", 'loan_repayment'::"text"])) AND ("lt"."id" = "u"."document_id"))))
             LEFT JOIN "public"."capital_contributions" "cc" ON ((("u"."document_type" = 'capital_contribution'::"text") AND ("cc"."id" = "u"."document_id"))))
             LEFT JOIN "public"."petty_cash_transactions" "pc" ON ((("u"."document_type" = 'petty_cash'::"text") AND ("pc"."id" = "u"."document_id"))))
             LEFT JOIN "public"."tax_payments" "tp" ON ((("u"."document_type" = 'tax_payment'::"text") AND ("tp"."id" = "u"."document_id"))))
             LEFT JOIN "public"."sales_invoices" "si" ON ((("u"."document_type" = 'sales_invoice'::"text") AND ("si"."id" = "u"."document_id"))))
             LEFT JOIN "public"."purchase_invoices" "pi" ON ((("u"."document_type" = 'purchase_invoice'::"text") AND ("pi"."id" = "u"."document_id"))))
             LEFT JOIN "public"."journal_entries" "je" ON ((("u"."document_type" = 'journal'::"text") AND ("je"."id" = "u"."document_id"))))
             LEFT JOIN "public"."bank_statement_lines" "bsl" ON ((("u"."document_type" = 'bank_reconciliation'::"text") AND ("bsl"."id" = "u"."document_id"))))
             LEFT JOIN LATERAL ( SELECT "j"."id",
                    "j"."entry_number",
                    "j"."entry_date",
                    "j"."period_id",
                    "j"."source_module",
                    "j"."reference_id",
                    "j"."reference_number",
                    "j"."description",
                    "j"."total_debit",
                    "j"."total_credit",
                    "j"."is_posted",
                    "j"."is_reversed",
                    "j"."reversed_by_id",
                    "j"."posted_by",
                    "j"."posted_at",
                    "j"."created_by",
                    "j"."created_at",
                    "j"."transaction_category",
                    "j"."transaction_currency",
                    "j"."functional_currency",
                    "j"."exchange_rate",
                    "j"."amounts_are_functional"
                   FROM "public"."journal_entries" "j"
                  WHERE ((("u"."document_type" = 'journal'::"text") AND ("j"."id" = "u"."document_id")) OR (("u"."document_type" = 'expense'::"text") AND (("j"."source_module")::"text" = ANY ((ARRAY['expense'::character varying, 'expenses'::character varying])::"text"[])) AND (("j"."reference_id" = "u"."document_id") OR (("j"."reference_number")::"text" = ('EXP-'::"text" || ("u"."document_id")::"text")))) OR (("u"."document_type" = 'receipt'::"text") AND ("j"."id" = "rv"."journal_entry_id")) OR (("u"."document_type" = 'payment'::"text") AND ("j"."id" = "pv"."journal_entry_id")) OR (("u"."document_type" = 'fund_transfer'::"text") AND ("j"."id" = "ft"."journal_entry_id")) OR (("u"."document_type" = 'loan'::"text") AND ("j"."id" = "l"."journal_entry_id")) OR (("u"."document_type" = ANY (ARRAY['loan_transaction'::"text", 'loan_repayment'::"text"])) AND ("j"."id" = "lt"."journal_entry_id")) OR (("u"."document_type" = 'capital_contribution'::"text") AND ("j"."id" = "cc"."journal_entry_id")) OR (("u"."document_type" = 'petty_cash'::"text") AND (("j"."source_module")::"text" = 'petty_cash'::"text") AND ("j"."reference_id" = "u"."document_id")) OR (("u"."document_type" = 'tax_payment'::"text") AND ("j"."id" = "tp"."journal_entry_id")) OR (("u"."document_type" = 'sales_invoice'::"text") AND ("j"."id" = "si"."journal_entry_id")) OR (("u"."document_type" = 'purchase_invoice'::"text") AND ("j"."id" = "pi"."journal_entry_id")) OR (("u"."document_type" = 'bank_reconciliation'::"text") AND ("j"."id" = "bsl"."matched_entry_id")))
                  ORDER BY "j"."is_posted" DESC, COALESCE("j"."is_reversed", false), "j"."created_at" DESC
                 LIMIT 1) "source_je" ON (true))
             LEFT JOIN LATERAL ( SELECT "jl"."id",
                    "jl"."journal_entry_id",
                    "jl"."line_number",
                    "jl"."account_id",
                    "jl"."description",
                    "jl"."debit",
                    "jl"."credit",
                    "jl"."tax_code_id",
                    "jl"."customer_id",
                    "jl"."supplier_id",
                    "jl"."batch_id",
                    "jl"."created_at",
                    "jl"."transaction_currency",
                    "jl"."transaction_debit",
                    "jl"."transaction_credit",
                    "jl"."functional_currency",
                    "jl"."exchange_rate"
                   FROM "public"."journal_entry_lines" "jl"
                  WHERE ("jl"."journal_entry_id" = "source_je"."id")
                  ORDER BY
                        CASE
                            WHEN (("u"."document_type" = 'bank_reconciliation'::"text") AND (((COALESCE("bsl"."credit_amount", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF("jl"."transaction_debit", (0)::numeric), "jl"."debit") = "bsl"."credit_amount")) OR ((COALESCE("bsl"."debit_amount", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF("jl"."transaction_credit", (0)::numeric), "jl"."credit") = "bsl"."debit_amount")))) THEN 0
                            WHEN ("jl"."account_id" = COALESCE("l"."coa_id", "rv"."coa_account_id", "pv"."coa_account_id", "fe"."fixed_asset_account_id")) THEN 0
                            ELSE 1
                        END, "jl"."line_number"
                 LIMIT 1) "current_line" ON (true))
             LEFT JOIN "public"."chart_of_accounts" "coa" ON (("coa"."id" = "current_line"."account_id")))
        ), "business_rows" AS (
         SELECT "e"."row_id",
            "e"."exception_id",
            "e"."run_id",
            "e"."document_type",
            "e"."document_id",
            "e"."date",
            "e"."voucher_number",
            "e"."journal_number",
            "e"."amount",
            "e"."currency",
            "e"."bank",
            "e"."customer_supplier",
            "e"."classification",
            "e"."reason",
            "e"."manual_information_required",
            "e"."recommended_action",
            "e"."inconsistent_fields",
            "e"."current_category",
            "e"."current_bank_account_id",
            "e"."journal_entry_id",
            "e"."journal_line_id",
            "e"."current_account_id",
            "e"."current_gl_account",
            "e"."expense_exchange_rate",
            "e"."current_tax_code_id",
            "e"."current_payment_type",
            "e"."current_document_classification",
            "e"."current_faktur_pajak_number",
                CASE
                    WHEN ("e"."reason" ~~* 'No unique authoritative relationship%'::"text") THEN 'The historical record is missing a confirmed payment method, bank, currency, or exchange rate.'::"text"
                    WHEN (("e"."reason" ~~* '%no historical transaction-date rate%'::"text") OR ("e"."reason" ~~* '%no authoritative historical rate%'::"text")) THEN 'The transaction is confirmed as foreign currency, but its original exchange rate is missing.'::"text"
                    WHEN ("e"."reason" ~~* '%USD-source Contra%'::"text") THEN 'The transfer used an older foreign-currency treatment that cannot be corrected without an accountant decision.'::"text"
                    WHEN (("e"."reason" ~~* '%does not post to this bank account%'::"text") OR ("e"."reason" ~~* '%does not use the Expense bank account%'::"text")) THEN 'The voucher and bank transaction are linked, but the journal uses a different account.'::"text"
                    WHEN ("e"."reason" ~~* '%amount or direction does not match%'::"text") THEN 'The amount or money-in/money-out direction differs between the bank transaction and journal.'::"text"
                    WHEN ("e"."reason" ~~* '%missing Faktur Pajak%'::"text") THEN 'A taxed invoice is missing its Faktur Pajak number.'::"text"
                    WHEN ("e"."reason" ~~* '%without an accrued payable%'::"text") THEN 'A tax payment exists without the earlier tax amount being recorded as payable.'::"text"
                    WHEN (("e"."reason" ~~* '%no active journal%'::"text") OR ("e"."reason" ~~* '%no provable active journal%'::"text")) THEN 'The document does not have a confirmed active journal.'::"text"
                    WHEN ("e"."reason" ~~* '%metadata conflicts%'::"text") THEN 'The voucher details conflict with the linked bank transaction.'::"text"
                    WHEN ("e"."reason" ~~* '%Journal metadata cannot be derived%'::"text") THEN 'The journal source or classification cannot be confirmed from the historical record.'::"text"
                    WHEN ("e"."reason" ~~* '%no native Loan source document%'::"text") THEN 'The journal is loan-related, but its original loan document is missing.'::"text"
                    ELSE 'The historical record needs an accountant to confirm its correct classification.'::"text"
                END AS "problem",
                CASE
                    WHEN (("e"."reason" ~~* '%no historical transaction-date rate%'::"text") OR ("e"."reason" ~~* '%no authoritative historical rate%'::"text")) THEN 'The application must not guess a historical exchange rate.'::"text"
                    WHEN (("e"."reason" ~~* '%USD-source Contra%'::"text") OR ("e"."reason" ~~* '%amount or direction does not match%'::"text")) THEN 'Correcting it automatically could change the meaning of posted accounting amounts.'::"text"
                    WHEN (("e"."reason" ~~* '%no active journal%'::"text") OR ("e"."reason" ~~* '%no native Loan source document%'::"text")) THEN 'No existing source-to-journal relationship proves a safe automatic correction.'::"text"
                    WHEN ("e"."reason" ~~* '%without an accrued payable%'::"text") THEN 'Only an accountant can confirm whether an accrual or reclassification is appropriate.'::"text"
                    ELSE 'More than one correction is possible from the available historical information.'::"text"
                END AS "why_not_automatic"
           FROM "enriched" "e"
        )
 SELECT "business_rows"."row_id",
    "business_rows"."exception_id",
    "business_rows"."run_id",
    "business_rows"."document_type",
    "business_rows"."document_id",
    "business_rows"."date",
    "business_rows"."voucher_number",
    "business_rows"."journal_number",
    "business_rows"."amount",
    "business_rows"."currency",
    "business_rows"."bank",
    "business_rows"."customer_supplier",
    "business_rows"."current_category",
    "business_rows"."current_gl_account",
    'Needs accountant review'::"text" AS "status",
    "business_rows"."problem",
    "business_rows"."why_not_automatic",
    "business_rows"."recommended_action",
    "business_rows"."current_bank_account_id",
    "business_rows"."journal_entry_id",
    "business_rows"."journal_line_id",
    "business_rows"."current_account_id",
    "business_rows"."current_tax_code_id",
    "business_rows"."current_payment_type",
    "business_rows"."current_document_classification",
    "business_rows"."current_faktur_pajak_number",
    "business_rows"."expense_exchange_rate"
   FROM "business_rows"
UNION ALL
 SELECT ((('verification:'::"text" || "vf"."document_type") || ':'::"text") || ("vf"."database_id")::"text") AS "row_id",
    NULL::bigint AS "exception_id",
    "vf"."run_id",
    "vf"."document_type",
    "vf"."database_id" AS "document_id",
    NULL::"date" AS "date",
    COALESCE("vf"."document_number", '(none)'::"text") AS "voucher_number",
    NULL::"text" AS "journal_number",
    NULL::numeric AS "amount",
    'Unknown'::"text" AS "currency",
    NULL::"text" AS "bank",
    NULL::"text" AS "customer_supplier",
    NULL::"text" AS "current_category",
    NULL::"text" AS "current_gl_account",
    'Verification failed'::"text" AS "status",
    'A Finance verification check still fails for this record.'::"text" AS "problem",
    'The current Finance data does not yet satisfy every report check.'::"text" AS "why_not_automatic",
    'Review the source document, journal and linked bank transaction, then save the confirmed classifications.'::"text" AS "recommended_action",
    NULL::"uuid" AS "current_bank_account_id",
    NULL::"uuid" AS "journal_entry_id",
    NULL::"uuid" AS "journal_line_id",
    NULL::"uuid" AS "current_account_id",
    NULL::"uuid" AS "current_tax_code_id",
    NULL::"text" AS "current_payment_type",
    NULL::"text" AS "current_document_classification",
    NULL::"text" AS "current_faktur_pajak_number",
    NULL::numeric AS "expense_exchange_rate"
   FROM "public"."finance_historical_repair_verification_failures" "vf"
  WHERE (NOT (EXISTS ( SELECT 1
           FROM "unresolved" "u"
          WHERE (("u"."run_id" = "vf"."run_id") AND ("u"."document_type" = "vf"."document_type") AND ("u"."document_id" = "vf"."database_id")))));


--
-- Name: finance_historical_repair_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."finance_historical_repair_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "total_records_scanned" bigint DEFAULT 0 NOT NULL,
    "records_repaired" bigint DEFAULT 0 NOT NULL,
    "records_partially_repaired" bigint DEFAULT 0 NOT NULL,
    "records_manual_review" bigint DEFAULT 0 NOT NULL,
    "records_skipped" bigint DEFAULT 0 NOT NULL,
    "notes" "text"
);


--
-- Name: finance_historical_repair_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."finance_historical_repair_summary" WITH ("security_invoker"='true') AS
 SELECT "id" AS "run_id",
    "started_at",
    "completed_at",
    "total_records_scanned",
    "records_repaired",
    "records_partially_repaired",
    "records_manual_review",
    "records_skipped",
    "notes"
   FROM "public"."finance_historical_repair_runs";


--
-- Name: finance_legacy_accepted_documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."finance_legacy_accepted_documents" (
    "document_type" "text" NOT NULL,
    "document_id" "uuid" NOT NULL,
    "classification" "text" NOT NULL,
    "acceptance_reason" "text" NOT NULL,
    "accepted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "finance_legacy_accepted_documents_classification_check" CHECK (("classification" = 'legacy_accepted'::"text")),
    CONSTRAINT "finance_legacy_accepted_documents_document_type_check" CHECK (("document_type" = 'fund_transfer'::"text"))
);


--
-- Name: unbalanced_journal_entries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."unbalanced_journal_entries" WITH ("security_invoker"='true') AS
 SELECT "id",
    "entry_number",
    "entry_date",
    "total_debit",
    "total_credit",
    ("total_debit" - "total_credit") AS "difference",
    "description",
    "created_at"
   FROM "public"."journal_entries"
  WHERE (("abs"(("total_debit" - "total_credit")) >= 0.01) AND (NOT (("total_debit" = (0)::numeric) AND ("total_credit" = (0)::numeric))))
  ORDER BY "created_at" DESC;


--
-- Name: finance_live_verification_failures; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."finance_live_verification_failures" WITH ("security_invoker"='true') AS
 WITH "bank_failures" AS (
         SELECT "b"."id",
            "b"."upload_id",
            "b"."bank_account_id",
            "b"."transaction_date",
            "b"."description",
            "b"."reference",
            "b"."branch_code",
            "b"."debit_amount",
            "b"."credit_amount",
            "b"."running_balance",
            "b"."currency",
            "b"."reconciliation_status",
            "b"."matched_entry_id",
            "b"."matched_expense_id",
            "b"."matched_receipt_id",
            "b"."matched_at",
            "b"."matched_by",
            "b"."notes",
            "b"."created_by",
            "b"."created_at",
            "b"."statement_balance",
            "b"."transaction_hash",
            "b"."matched_petty_cash_id",
            "b"."matched_fund_transfer_id",
            "b"."paid_by",
            "b"."matching_status",
            "b"."manually_unlinked",
            "b"."payment_kind",
            "b"."matched_tax_payment_id",
            "b"."matched_payment_id",
            "ba"."coa_id" AS "bank_coa_id",
            "ba"."bank_name",
            "ba"."account_name",
            "ba"."account_number",
            "ba"."currency" AS "bank_currency",
            "je"."id" AS "active_journal_id",
            "je"."entry_number",
                CASE
                    WHEN ("ba"."coa_id" IS NULL) THEN 'The selected bank is missing its posting account.'::"text"
                    WHEN ("je"."id" IS NULL) THEN 'The linked bank transaction has no active journal.'::"text"
                    WHEN (NOT (EXISTS ( SELECT 1
                       FROM "public"."journal_entry_lines" "x"
                      WHERE (("x"."journal_entry_id" = "je"."id") AND ("x"."account_id" = "ba"."coa_id"))))) THEN 'The linked journal uses a different account from the Bank Master.'::"text"
                    ELSE 'The amount or money-in/money-out direction differs between the bank transaction and journal.'::"text"
                END AS "problem"
           FROM (("public"."bank_statement_lines" "b"
             LEFT JOIN "public"."bank_accounts" "ba" ON (("ba"."id" = "b"."bank_account_id")))
             LEFT JOIN "public"."journal_entries" "je" ON ((("je"."id" = "b"."matched_entry_id") AND ("je"."is_posted" = true) AND (COALESCE("je"."is_reversed", false) = false))))
          WHERE ((("b"."reconciliation_status" = ANY (ARRAY['matched'::"text", 'recorded'::"text"])) OR ("b"."matched_entry_id" IS NOT NULL)) AND (("ba"."coa_id" IS NULL) OR ("je"."id" IS NULL) OR (NOT (EXISTS ( SELECT 1
                   FROM "public"."journal_entry_lines" "x"
                  WHERE (("x"."journal_entry_id" = "je"."id") AND ("x"."account_id" = "ba"."coa_id") AND (((COALESCE("b"."credit_amount", (0)::numeric) > (0)::numeric) AND (COALESCE("b"."debit_amount", (0)::numeric) = (0)::numeric) AND (COALESCE(NULLIF("x"."transaction_debit", (0)::numeric), "x"."debit") = "b"."credit_amount")) OR ((COALESCE("b"."debit_amount", (0)::numeric) > (0)::numeric) AND (COALESCE("b"."credit_amount", (0)::numeric) = (0)::numeric) AND (COALESCE(NULLIF("x"."transaction_credit", (0)::numeric), "x"."credit") = "b"."debit_amount")))))))))
        ), "bank_rows" AS (
         SELECT ('live:bank_reconciliation:'::"text" || ("b"."id")::"text") AS "row_id",
            NULL::bigint AS "exception_id",
            ( SELECT "finance_historical_repair_summary"."run_id"
                   FROM "public"."finance_historical_repair_summary"
                  ORDER BY "finance_historical_repair_summary"."started_at" DESC
                 LIMIT 1) AS "run_id",
            'bank_reconciliation'::"text" AS "document_type",
            "b"."id" AS "document_id",
            "b"."transaction_date" AS "date",
            COALESCE(NULLIF("b"."reference", ''::"text"), 'Bank transaction'::"text") AS "voucher_number",
            ("b"."entry_number")::"text" AS "journal_number",
            (COALESCE(NULLIF("b"."debit_amount", (0)::numeric), "b"."credit_amount"))::numeric AS "amount",
            COALESCE("b"."currency", "b"."bank_currency", 'Unknown'::"text") AS "currency",
            "concat_ws"(' · '::"text", "b"."bank_name", "b"."account_name", "b"."account_number", "b"."bank_currency") AS "bank",
            COALESCE("c"."company_name", ("s"."company_name")::"text") AS "customer_supplier",
            "b"."payment_kind" AS "current_category",
            "concat_ws"(' · '::"text", "coa"."code", "coa"."name") AS "current_gl_account",
            'Verification failed'::"text" AS "status",
            "b"."problem",
            'The current bank link does not satisfy the Bank Master, amount and direction checks.'::"text" AS "why_not_automatic",
            'Review the original bank transaction and source document, then select the confirmed bank and account. If the amounts differ, ask the accountant whether a formal correction is required.'::"text" AS "recommended_action",
            "b"."bank_account_id" AS "current_bank_account_id",
            "b"."active_journal_id" AS "journal_entry_id",
            "current_line"."id" AS "journal_line_id",
            "current_line"."account_id" AS "current_account_id",
            NULL::"uuid" AS "current_tax_code_id",
            "b"."payment_kind" AS "current_payment_type",
            ("je"."source_module")::"text" AS "current_document_classification",
            NULL::"text" AS "current_faktur_pajak_number",
            NULL::numeric AS "expense_exchange_rate"
           FROM (((((((("bank_failures" "b"
             LEFT JOIN "public"."journal_entries" "je" ON (("je"."id" = "b"."active_journal_id")))
             LEFT JOIN "public"."receipt_vouchers" "rv" ON (("rv"."id" = "b"."matched_receipt_id")))
             LEFT JOIN "public"."payment_vouchers" "pv" ON (("pv"."id" = "b"."matched_payment_id")))
             LEFT JOIN "public"."finance_expenses" "fe" ON (("fe"."id" = "b"."matched_expense_id")))
             LEFT JOIN "public"."customers" "c" ON (("c"."id" = "rv"."customer_id")))
             LEFT JOIN "public"."suppliers" "s" ON (("s"."id" = COALESCE("pv"."supplier_id", "fe"."supplier_id"))))
             LEFT JOIN LATERAL ( SELECT "x"."id",
                    "x"."account_id"
                   FROM "public"."journal_entry_lines" "x"
                  WHERE ("x"."journal_entry_id" = "b"."active_journal_id")
                  ORDER BY
                        CASE
                            WHEN (((COALESCE("b"."credit_amount", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF("x"."transaction_debit", (0)::numeric), "x"."debit") = "b"."credit_amount")) OR ((COALESCE("b"."debit_amount", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF("x"."transaction_credit", (0)::numeric), "x"."credit") = "b"."debit_amount"))) THEN 0
                            ELSE 1
                        END, "x"."line_number"
                 LIMIT 1) "current_line" ON (true))
             LEFT JOIN "public"."chart_of_accounts" "coa" ON (("coa"."id" = "current_line"."account_id")))
        ), "journal_rows" AS (
         SELECT ('live:journal:'::"text" || ("u"."id")::"text") AS "?column?",
            NULL::bigint AS "int8",
            ( SELECT "finance_historical_repair_summary"."run_id"
                   FROM "public"."finance_historical_repair_summary"
                  ORDER BY "finance_historical_repair_summary"."started_at" DESC
                 LIMIT 1) AS "run_id",
            'journal'::"text" AS "text",
            "u"."id",
            "u"."entry_date",
            ("u"."entry_number")::"text" AS "entry_number",
            ("u"."entry_number")::"text" AS "entry_number",
            ("u"."total_debit")::numeric AS "total_debit",
            'IDR'::"text" AS "text",
            NULL::"text" AS "text",
            NULL::"text" AS "text",
            "u"."description",
            NULL::"text" AS "text",
            'Verification failed'::"text" AS "text",
            'This posted journal is not balanced.'::"text" AS "text",
            'Finance reports require every posted journal to have equal debits and credits.'::"text" AS "text",
            'Review the source document and journal with the accountant. Do not change historical amounts without an authorised correction.'::"text" AS "text",
            NULL::"uuid" AS "uuid",
            "u"."id",
            NULL::"uuid" AS "uuid",
            NULL::"uuid" AS "uuid",
            NULL::"uuid" AS "uuid",
            NULL::"text" AS "text",
            NULL::"text" AS "text",
            NULL::"text" AS "text",
            NULL::numeric AS "numeric"
           FROM "public"."unbalanced_journal_entries" "u"
        ), "faktur_rows" AS (
         SELECT ('live:sales_invoice:'::"text" || ("si"."id")::"text") AS "?column?",
            NULL::bigint AS "int8",
            ( SELECT "finance_historical_repair_summary"."run_id"
                   FROM "public"."finance_historical_repair_summary"
                  ORDER BY "finance_historical_repair_summary"."started_at" DESC
                 LIMIT 1) AS "run_id",
            'sales_invoice'::"text" AS "text",
            "si"."id",
            "si"."invoice_date",
            "si"."invoice_number",
            ("je"."entry_number")::"text" AS "entry_number",
            ("si"."total_amount")::numeric AS "total_amount",
            'IDR'::"text" AS "text",
            NULL::"text" AS "text",
            "c"."company_name",
            'Taxed Sale'::"text" AS "text",
            NULL::"text" AS "text",
            'Verification failed'::"text" AS "text",
            'A taxed invoice is missing its Faktur Pajak number.'::"text" AS "text",
            'Tax reporting cannot complete the invoice without the official number.'::"text" AS "text",
            'Confirm and enter the issued Faktur Pajak number.'::"text" AS "text",
            NULL::"uuid" AS "uuid",
            "si"."journal_entry_id",
            NULL::"uuid" AS "uuid",
            NULL::"uuid" AS "uuid",
            NULL::"uuid" AS "uuid",
            NULL::"text" AS "text",
            ("je"."source_module")::"text" AS "source_module",
            ("si"."faktur_pajak_number")::"text" AS "faktur_pajak_number",
            NULL::numeric AS "numeric"
           FROM (("public"."sales_invoices" "si"
             LEFT JOIN "public"."customers" "c" ON (("c"."id" = "si"."customer_id")))
             LEFT JOIN "public"."journal_entries" "je" ON (("je"."id" = "si"."journal_entry_id")))
          WHERE (("si"."tax_amount" > (0)::numeric) AND ("si"."tax_period_id" IS NOT NULL) AND (NULLIF("btrim"(("si"."faktur_pajak_number")::"text"), ''::"text") IS NULL))
        )
 SELECT "bank_rows"."row_id",
    "bank_rows"."exception_id",
    "bank_rows"."run_id",
    "bank_rows"."document_type",
    "bank_rows"."document_id",
    "bank_rows"."date",
    "bank_rows"."voucher_number",
    "bank_rows"."journal_number",
    "bank_rows"."amount",
    "bank_rows"."currency",
    "bank_rows"."bank",
    "bank_rows"."customer_supplier",
    "bank_rows"."current_category",
    "bank_rows"."current_gl_account",
    "bank_rows"."status",
    "bank_rows"."problem",
    "bank_rows"."why_not_automatic",
    "bank_rows"."recommended_action",
    "bank_rows"."current_bank_account_id",
    "bank_rows"."journal_entry_id",
    "bank_rows"."journal_line_id",
    "bank_rows"."current_account_id",
    "bank_rows"."current_tax_code_id",
    "bank_rows"."current_payment_type",
    "bank_rows"."current_document_classification",
    "bank_rows"."current_faktur_pajak_number",
    "bank_rows"."expense_exchange_rate"
   FROM "bank_rows"
UNION ALL
 SELECT "journal_rows"."?column?" AS "row_id",
    "journal_rows"."int8" AS "exception_id",
    "journal_rows"."run_id",
    "journal_rows"."text" AS "document_type",
    "journal_rows"."id" AS "document_id",
    "journal_rows"."entry_date" AS "date",
    "journal_rows"."entry_number" AS "voucher_number",
    "journal_rows"."entry_number_1" AS "journal_number",
    "journal_rows"."total_debit" AS "amount",
    "journal_rows"."text_1" AS "currency",
    "journal_rows"."text_2" AS "bank",
    "journal_rows"."text_3" AS "customer_supplier",
    "journal_rows"."description" AS "current_category",
    "journal_rows"."text_4" AS "current_gl_account",
    "journal_rows"."text_5" AS "status",
    "journal_rows"."text_6" AS "problem",
    "journal_rows"."text_7" AS "why_not_automatic",
    "journal_rows"."text_8" AS "recommended_action",
    "journal_rows"."uuid" AS "current_bank_account_id",
    "journal_rows"."id_1" AS "journal_entry_id",
    "journal_rows"."uuid_1" AS "journal_line_id",
    "journal_rows"."uuid_2" AS "current_account_id",
    "journal_rows"."uuid_3" AS "current_tax_code_id",
    "journal_rows"."text_9" AS "current_payment_type",
    "journal_rows"."text_10" AS "current_document_classification",
    "journal_rows"."text_11" AS "current_faktur_pajak_number",
    "journal_rows"."numeric" AS "expense_exchange_rate"
   FROM "journal_rows" "journal_rows"("?column?", "int8", "run_id", "text", "id", "entry_date", "entry_number", "entry_number_1", "total_debit", "text_1", "text_2", "text_3", "description", "text_4", "text_5", "text_6", "text_7", "text_8", "uuid", "id_1", "uuid_1", "uuid_2", "uuid_3", "text_9", "text_10", "text_11", "numeric")
UNION ALL
 SELECT "faktur_rows"."?column?" AS "row_id",
    "faktur_rows"."int8" AS "exception_id",
    "faktur_rows"."run_id",
    "faktur_rows"."text" AS "document_type",
    "faktur_rows"."id" AS "document_id",
    "faktur_rows"."invoice_date" AS "date",
    "faktur_rows"."invoice_number" AS "voucher_number",
    "faktur_rows"."entry_number" AS "journal_number",
    "faktur_rows"."total_amount" AS "amount",
    "faktur_rows"."text_1" AS "currency",
    "faktur_rows"."text_2" AS "bank",
    "faktur_rows"."company_name" AS "customer_supplier",
    "faktur_rows"."text_3" AS "current_category",
    "faktur_rows"."text_4" AS "current_gl_account",
    "faktur_rows"."text_5" AS "status",
    "faktur_rows"."text_6" AS "problem",
    "faktur_rows"."text_7" AS "why_not_automatic",
    "faktur_rows"."text_8" AS "recommended_action",
    "faktur_rows"."uuid" AS "current_bank_account_id",
    "faktur_rows"."journal_entry_id",
    "faktur_rows"."uuid_1" AS "journal_line_id",
    "faktur_rows"."uuid_2" AS "current_account_id",
    "faktur_rows"."uuid_3" AS "current_tax_code_id",
    "faktur_rows"."text_9" AS "current_payment_type",
    "faktur_rows"."source_module" AS "current_document_classification",
    "faktur_rows"."faktur_pajak_number" AS "current_faktur_pajak_number",
    "faktur_rows"."numeric" AS "expense_exchange_rate"
   FROM "faktur_rows" "faktur_rows"("?column?", "int8", "run_id", "text", "id", "invoice_date", "invoice_number", "entry_number", "total_amount", "text_1", "text_2", "company_name", "text_3", "text_4", "text_5", "text_6", "text_7", "text_8", "uuid", "journal_entry_id", "uuid_1", "uuid_2", "uuid_3", "text_9", "source_module", "faktur_pajak_number", "numeric");


--
-- Name: finance_exception_correction_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."finance_exception_correction_dashboard" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "review"."row_id",
            "review"."exception_id",
            "review"."run_id",
            "review"."document_type",
            "review"."document_id",
            "review"."date",
            "review"."voucher_number",
            "review"."journal_number",
            "review"."amount",
            "review"."currency",
            "review"."bank",
            "review"."customer_supplier",
            "review"."current_category",
            "review"."current_gl_account",
            "review"."status",
            "review"."problem",
            "review"."why_not_automatic",
            "review"."recommended_action",
            "review"."current_bank_account_id",
            "review"."journal_entry_id",
            "review"."journal_line_id",
            "review"."current_account_id",
            "review"."current_tax_code_id",
            "review"."current_payment_type",
            "review"."current_document_classification",
            "review"."current_faktur_pajak_number",
            "review"."expense_exchange_rate"
           FROM "public"."finance_exception_accountant_review_dashboard" "review"
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM "public"."finance_legacy_accepted_documents" "accepted"
                  WHERE (("accepted"."document_type" = "review"."document_type") AND ("accepted"."document_id" = "review"."document_id")))))
        UNION ALL
         SELECT "live"."row_id",
            "live"."exception_id",
            "live"."run_id",
            "live"."document_type",
            "live"."document_id",
            "live"."date",
            "live"."voucher_number",
            "live"."journal_number",
            "live"."amount",
            "live"."currency",
            "live"."bank",
            "live"."customer_supplier",
            "live"."current_category",
            "live"."current_gl_account",
            "live"."status",
            "live"."problem",
            "live"."why_not_automatic",
            "live"."recommended_action",
            "live"."current_bank_account_id",
            "live"."journal_entry_id",
            "live"."journal_line_id",
            "live"."current_account_id",
            "live"."current_tax_code_id",
            "live"."current_payment_type",
            "live"."current_document_classification",
            "live"."current_faktur_pajak_number",
            "live"."expense_exchange_rate"
           FROM "public"."finance_live_verification_failures" "live"
          WHERE ((NOT (EXISTS ( SELECT 1
                   FROM "public"."finance_exception_accountant_review_dashboard" "open_item"
                  WHERE (("open_item"."document_type" = "live"."document_type") AND ("open_item"."document_id" = "live"."document_id"))))) AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."finance_legacy_accepted_documents" "accepted"
                  WHERE (("accepted"."document_type" = "live"."document_type") AND ("accepted"."document_id" = "live"."document_id"))))))
        )
 SELECT "b"."row_id",
    "b"."exception_id",
    "b"."run_id",
    "b"."document_type",
    "b"."document_id",
    "b"."date",
    "b"."voucher_number",
    "b"."journal_number",
    "b"."amount",
    "b"."currency",
    "b"."bank",
    "b"."customer_supplier",
    "b"."current_category",
    "b"."current_gl_account",
    "b"."status",
    "b"."problem",
    "b"."why_not_automatic",
    "b"."recommended_action",
    "b"."current_bank_account_id",
    "b"."journal_entry_id",
    "b"."journal_line_id",
    "b"."current_account_id",
    "b"."current_tax_code_id",
    "b"."current_payment_type",
    "b"."current_document_classification",
    "b"."current_faktur_pajak_number",
    "b"."expense_exchange_rate",
    ("fe"."expense_type")::"text" AS "current_subcategory",
    (COALESCE("fe"."invoice_number", "rv"."reference_number", "pv"."reference_number", ("bsl"."reference")::character varying, "je"."reference_number"))::"text" AS "current_reference",
    COALESCE("fe"."supplier_id", "pv"."supplier_id", "pi"."supplier_id", "jel"."supplier_id") AS "current_supplier_id",
    COALESCE("rv"."customer_id", "si"."customer_id", "jel"."customer_id") AS "current_customer_id",
    "ft"."from_bank_account_id",
    "ft"."to_bank_account_id",
    COALESCE("from_bank"."alias", "from_bank"."account_name", "from_bank"."bank_name") AS "from_bank_alias",
    COALESCE("to_bank"."alias", "to_bank"."account_name", "to_bank"."bank_name") AS "to_bank_alias",
    COALESCE("current_bank"."alias", "current_bank"."account_name", "current_bank"."bank_name") AS "bank_alias",
    COALESCE(
        CASE
            WHEN ("b"."document_type" = 'bank_reconciliation'::"text") THEN "b"."document_id"
            ELSE NULL::"uuid"
        END, "linked_bank_line"."id") AS "bank_statement_line_id",
    (COALESCE("fe"."invoice_number", "rv"."voucher_number", "pv"."voucher_number", ("ft"."transfer_number")::character varying, ("l"."loan_number")::character varying, ("lt"."transaction_number")::character varying, "cc"."voucher_number", ("tp"."billing_code")::character varying, ("si"."invoice_number")::character varying, "pi"."invoice_number", "je"."reference_number", ("b"."voucher_number")::character varying))::"text" AS "current_source_document",
    COALESCE("l"."loan_type", ("cc"."contribution_type")::"text") AS "current_finance_classification"
   FROM ((((((((((((((((("base" "b"
     LEFT JOIN "public"."finance_expenses" "fe" ON ((("b"."document_type" = 'expense'::"text") AND ("fe"."id" = "b"."document_id"))))
     LEFT JOIN "public"."receipt_vouchers" "rv" ON ((("b"."document_type" = 'receipt'::"text") AND ("rv"."id" = "b"."document_id"))))
     LEFT JOIN "public"."payment_vouchers" "pv" ON ((("b"."document_type" = 'payment'::"text") AND ("pv"."id" = "b"."document_id"))))
     LEFT JOIN "public"."fund_transfers" "ft" ON ((("b"."document_type" = 'fund_transfer'::"text") AND ("ft"."id" = "b"."document_id"))))
     LEFT JOIN "public"."loans" "l" ON ((("b"."document_type" = 'loan'::"text") AND ("l"."id" = "b"."document_id"))))
     LEFT JOIN "public"."loan_transactions" "lt" ON ((("b"."document_type" = ANY (ARRAY['loan_transaction'::"text", 'loan_repayment'::"text"])) AND ("lt"."id" = "b"."document_id"))))
     LEFT JOIN "public"."capital_contributions" "cc" ON ((("b"."document_type" = 'capital_contribution'::"text") AND ("cc"."id" = "b"."document_id"))))
     LEFT JOIN "public"."tax_payments" "tp" ON ((("b"."document_type" = 'tax_payment'::"text") AND ("tp"."id" = "b"."document_id"))))
     LEFT JOIN "public"."sales_invoices" "si" ON ((("b"."document_type" = 'sales_invoice'::"text") AND ("si"."id" = "b"."document_id"))))
     LEFT JOIN "public"."purchase_invoices" "pi" ON ((("b"."document_type" = 'purchase_invoice'::"text") AND ("pi"."id" = "b"."document_id"))))
     LEFT JOIN "public"."bank_statement_lines" "bsl" ON ((("b"."document_type" = 'bank_reconciliation'::"text") AND ("bsl"."id" = "b"."document_id"))))
     LEFT JOIN "public"."journal_entries" "je" ON (("je"."id" = "b"."journal_entry_id")))
     LEFT JOIN "public"."journal_entry_lines" "jel" ON (("jel"."id" = "b"."journal_line_id")))
     LEFT JOIN "public"."bank_accounts" "current_bank" ON (("current_bank"."id" = "b"."current_bank_account_id")))
     LEFT JOIN "public"."bank_accounts" "from_bank" ON (("from_bank"."id" = "ft"."from_bank_account_id")))
     LEFT JOIN "public"."bank_accounts" "to_bank" ON (("to_bank"."id" = "ft"."to_bank_account_id")))
     LEFT JOIN LATERAL ( SELECT "x"."id"
           FROM "public"."bank_statement_lines" "x"
          WHERE ((("b"."document_type" = 'expense'::"text") AND ("x"."matched_expense_id" = "b"."document_id")) OR (("b"."document_type" = 'receipt'::"text") AND ("x"."matched_receipt_id" = "b"."document_id")) OR (("b"."document_type" = 'payment'::"text") AND ("x"."matched_payment_id" = "b"."document_id")) OR (("b"."document_type" = 'fund_transfer'::"text") AND ("x"."matched_fund_transfer_id" = "b"."document_id")) OR (("b"."document_type" = 'petty_cash'::"text") AND ("x"."matched_petty_cash_id" = "b"."document_id")) OR (("b"."document_type" = 'tax_payment'::"text") AND ("x"."matched_tax_payment_id" = "b"."document_id")) OR (("x"."matched_entry_id" = "b"."journal_entry_id") AND ("b"."journal_entry_id" IS NOT NULL)))
          ORDER BY "x"."transaction_date" DESC
         LIMIT 1) "linked_bank_line" ON (true));


--
-- Name: finance_historical_repair_commands; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."finance_historical_repair_commands" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "document_type" "text" NOT NULL,
    "document_id" "uuid" NOT NULL,
    "bank_statement_line_id" "uuid",
    "payment_kind" "text" DEFAULT 'supplier'::"text" NOT NULL,
    "operation" "text" DEFAULT 'allocate_existing_cash_event'::"text" NOT NULL,
    "requested_by" "uuid",
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "before_state" "jsonb" NOT NULL,
    "after_state" "jsonb" NOT NULL,
    "created_allocation_id" "uuid",
    "status" "text" DEFAULT 'committed'::"text" NOT NULL,
    CONSTRAINT "finance_historical_repair_commands_document_type_check" CHECK (("document_type" = ANY (ARRAY['expense'::"text", 'payment'::"text", 'receipt'::"text", 'tax_payment'::"text", 'fund_transfer'::"text", 'petty_cash'::"text", 'journal'::"text"]))),
    CONSTRAINT "finance_historical_repair_commands_operation_check" CHECK (("operation" = ANY (ARRAY['allocate_existing_cash_event'::"text", 'create_cash_correction'::"text", 'reclassify_cash_recognition_to_ap'::"text", 'restate_salary_net_of_advance'::"text", 'restate_partial_supplier_cash'::"text", 'restate_evidenced_bank_charge'::"text"]))),
    CONSTRAINT "finance_historical_repair_commands_payment_kind_check" CHECK (("payment_kind" = ANY (ARRAY['supplier'::"text", 'pph23'::"text"]))),
    CONSTRAINT "finance_historical_repair_commands_status_check" CHECK (("status" = 'committed'::"text"))
);


