    "supplier_id" "uuid",
    "import_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "import_invoice_value" numeric(18,2) DEFAULT 0 NOT NULL,
    "currency" character varying(10) DEFAULT 'USD'::character varying,
    "exchange_rate" numeric(18,6) DEFAULT 1 NOT NULL,
    "allocated_expenses" numeric(18,2) DEFAULT 0,
    "allocation_method" character varying(20) DEFAULT 'invoice_value'::character varying,
    "status" character varying(20) DEFAULT 'draft'::character varying,
    "locked_at" timestamp with time zone,
    "locked_by" "uuid",
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "duty_bm" numeric(18,2) DEFAULT 0,
    "ppn_import" numeric(18,2) DEFAULT 0,
    "pph_import" numeric(18,2) DEFAULT 0,
    "freight_charges" numeric(18,2) DEFAULT 0,
    "clearing_forwarding" numeric(18,2) DEFAULT 0,
    "port_charges" numeric(18,2) DEFAULT 0,
    "container_handling" numeric(18,2) DEFAULT 0,
    "transportation" numeric(18,2) DEFAULT 0,
    "other_import_costs" numeric(18,2) DEFAULT 0,
    "loading_import" numeric DEFAULT 0,
    "bpom_ski_fees" numeric(15,2) DEFAULT 0,
    "total_import_expenses" numeric GENERATED ALWAYS AS (((((((((COALESCE("duty_bm", (0)::numeric) + COALESCE("freight_charges", (0)::numeric)) + COALESCE("clearing_forwarding", (0)::numeric)) + COALESCE("port_charges", (0)::numeric)) + COALESCE("container_handling", (0)::numeric)) + COALESCE("transportation", (0)::numeric)) + COALESCE("loading_import", (0)::numeric)) + COALESCE("bpom_ski_fees", (0)::numeric)) + COALESCE("other_import_costs", (0)::numeric))) STORED,
    CONSTRAINT "import_containers_allocation_method_check" CHECK ((("allocation_method")::"text" = ANY ((ARRAY['invoice_value'::character varying, 'quantity'::character varying])::"text"[]))),
    CONSTRAINT "import_containers_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['draft'::character varying, 'allocated'::character varying, 'locked'::character varying])::"text"[]))),
    CONSTRAINT "positive_invoice_value" CHECK (("import_invoice_value" >= (0)::numeric))
);


