--
-- Name: journal_voucher_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."journal_voucher_view" WITH ("security_invoker"='true') AS
 SELECT "id" AS "journal_entry_id",
    "entry_date" AS "date",
    "entry_number" AS "voucher_no",
        CASE
            WHEN (("source_module")::"text" = 'sales_invoice'::"text") THEN 'Sales Invoice'::character varying
            WHEN (("source_module")::"text" = 'sales_invoice_cogs'::"text") THEN 'COGS Entry'::character varying
            WHEN (("source_module")::"text" = 'purchase_invoice'::"text") THEN 'Purchase Invoice'::character varying
            WHEN (("source_module")::"text" = 'receipt'::"text") THEN 'Receipt'::character varying
            WHEN (("source_module")::"text" = 'payment'::"text") THEN 'Payment'::character varying
            WHEN (("source_module")::"text" = 'petty_cash'::"text") THEN 'Petty Cash'::character varying
            WHEN (("source_module")::"text" = 'expense'::"text") THEN 'Expense'::character varying
            WHEN (("source_module")::"text" = 'expenses'::"text") THEN 'Expense'::character varying
            WHEN (("source_module")::"text" = 'fund_transfer'::"text") THEN 'Fund Transfer'::character varying
            WHEN (("source_module")::"text" = 'batch'::"text") THEN 'Batch'::character varying
            WHEN (("source_module")::"text" = 'manual'::"text") THEN 'Manual Entry'::character varying
            ELSE "source_module"
        END AS "voucher_type",
    ( SELECT ((("coa"."code")::"text" || ' - '::"text") || ("coa"."name")::"text")
           FROM ("public"."journal_entry_lines" "jel"
             LEFT JOIN "public"."chart_of_accounts" "coa" ON (("coa"."id" = "jel"."account_id")))
          WHERE (("jel"."journal_entry_id" = "je"."id") AND ("jel"."debit" > (0)::numeric))
          ORDER BY "jel"."line_number"
         LIMIT 1) AS "debit_account",
    ( SELECT ((("coa"."code")::"text" || ' - '::"text") || ("coa"."name")::"text")
           FROM ("public"."journal_entry_lines" "jel"
             LEFT JOIN "public"."chart_of_accounts" "coa" ON (("coa"."id" = "jel"."account_id")))
          WHERE (("jel"."journal_entry_id" = "je"."id") AND ("jel"."credit" > (0)::numeric))
          ORDER BY "jel"."line_number"
         LIMIT 1) AS "credit_account",
    "total_debit" AS "amount",
    COALESCE(( SELECT "petty_cash_transactions"."description"
           FROM "public"."petty_cash_transactions"
          WHERE ("petty_cash_transactions"."id" = "je"."reference_id")
         LIMIT 1), ( SELECT "finance_expenses"."description"
           FROM "public"."finance_expenses"
          WHERE ("finance_expenses"."id" = "je"."reference_id")
         LIMIT 1), ( SELECT "fund_transfers"."description"
           FROM "public"."fund_transfers"
          WHERE ("fund_transfers"."id" = "je"."reference_id")
         LIMIT 1), ( SELECT ((('Sales to '::"text" || "c"."company_name") || ' - Inv: '::"text") || "si"."invoice_number")
           FROM ("public"."sales_invoices" "si"
             LEFT JOIN "public"."customers" "c" ON (("c"."id" = "si"."customer_id")))
          WHERE ("si"."id" = "je"."reference_id")
         LIMIT 1), ( SELECT ((('Receipt from '::"text" || "c"."company_name") || ' - '::"text") || ("rv"."voucher_number")::"text")
           FROM ("public"."receipt_vouchers" "rv"
             LEFT JOIN "public"."customers" "c" ON (("c"."id" = "rv"."customer_id")))
          WHERE ("rv"."id" = "je"."reference_id")
         LIMIT 1), ( SELECT ((('Payment to '::"text" || ("s"."company_name")::"text") || ' - '::"text") || ("pv"."voucher_number")::"text")
           FROM ("public"."payment_vouchers" "pv"
             LEFT JOIN "public"."suppliers" "s" ON (("s"."id" = "pv"."supplier_id")))
          WHERE ("pv"."id" = "je"."reference_id")
         LIMIT 1), "description", '-'::"text") AS "narration",
    "reference_number",
    "source_module",
    ( SELECT "count"(*) AS "count"
           FROM "public"."journal_entry_lines"
          WHERE ("journal_entry_lines"."journal_entry_id" = "je"."id")) AS "line_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."journal_entry_lines"
          WHERE ("journal_entry_lines"."journal_entry_id" = "je"."id")) > 2) AS "is_multi_line",
    "created_at"
   FROM "public"."journal_entries" "je"
  WHERE ("is_posted" = true)
  ORDER BY "entry_date" DESC, "entry_number" DESC;


