--
-- Name: so_delivery_invoice_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."so_delivery_invoice_status" WITH ("security_invoker"='true') AS
 WITH "ordered" AS (
         SELECT "soi"."sales_order_id" AS "so_id",
            COALESCE("sum"("soi"."quantity"), (0)::numeric) AS "ordered_qty"
           FROM "public"."sales_order_items" "soi"
          GROUP BY "soi"."sales_order_id"
        ), "approved_delivery" AS (
         SELECT "dc"."sales_order_id" AS "so_id",
            COALESCE("sum"("dci"."quantity"), (0)::numeric) AS "approved_delivered_qty",
            "count"(DISTINCT "dc"."id") AS "approved_dc_count"
           FROM ("public"."delivery_challans" "dc"
             JOIN "public"."delivery_challan_items" "dci" ON (("dci"."challan_id" = "dc"."id")))
          WHERE (("dc"."approval_status" = 'approved'::"public"."dc_approval_status") AND ("dc"."sales_order_id" IS NOT NULL))
          GROUP BY "dc"."sales_order_id"
        ), "invoice_items_by_so" AS (
         SELECT DISTINCT "sii"."id" AS "invoice_item_id",
            COALESCE("si"."sales_order_id", "dc"."sales_order_id") AS "so_id",
            "sii"."quantity"
           FROM ((("public"."sales_invoice_items" "sii"
             JOIN "public"."sales_invoices" "si" ON (("si"."id" = "sii"."invoice_id")))
             LEFT JOIN "public"."delivery_challan_items" "dci" ON (("dci"."id" = "sii"."delivery_challan_item_id")))
             LEFT JOIN "public"."delivery_challans" "dc" ON (("dc"."id" = "dci"."challan_id")))
          WHERE ((COALESCE("si"."is_draft", false) = false) AND ("si"."invoice_number" !~~* 'TEST-COGS-%'::"text") AND (COALESCE("si"."sales_order_id", "dc"."sales_order_id") IS NOT NULL))
        ), "invoiced" AS (
         SELECT "i_1"."so_id",
            COALESCE("sum"("i_1"."quantity"), (0)::numeric) AS "invoiced_qty",
            "count"(DISTINCT "i_1"."invoice_item_id") AS "invoice_count"
           FROM "invoice_items_by_so" "i_1"
          GROUP BY "i_1"."so_id"
        )
 SELECT "so"."id" AS "so_id",
    "so"."so_number",
    "so"."customer_id",
    "so"."status" AS "so_status",
        CASE
            WHEN (COALESCE("ad"."approved_delivered_qty", (0)::numeric) = (0)::numeric) THEN 'pending'::"text"
            WHEN ((COALESCE("ad"."approved_delivered_qty", (0)::numeric) >= COALESCE("o"."ordered_qty", (0)::numeric)) AND (COALESCE("o"."ordered_qty", (0)::numeric) > (0)::numeric)) THEN 'completed'::"text"
            ELSE 'partial'::"text"
        END AS "delivery_status",
        CASE
            WHEN (COALESCE("i"."invoiced_qty", (0)::numeric) = (0)::numeric) THEN 'pending'::"text"
            WHEN ((COALESCE("i"."invoiced_qty", (0)::numeric) >= COALESCE("o"."ordered_qty", (0)::numeric)) AND (COALESCE("o"."ordered_qty", (0)::numeric) > (0)::numeric)) THEN 'completed'::"text"
            ELSE 'partial'::"text"
        END AS "invoice_status",
        CASE
            WHEN ((COALESCE("i"."invoiced_qty", (0)::numeric) > (0)::numeric) AND (COALESCE("ad"."approved_delivered_qty", (0)::numeric) = (0)::numeric)) THEN 'invoice_done_delivery_pending'::"text"
            ELSE NULL::"text"
        END AS "special_status",
    COALESCE("ad"."approved_dc_count", (0)::bigint) AS "approved_dc_count",
    COALESCE("i"."invoice_count", (0)::bigint) AS "invoice_count",
    COALESCE("o"."ordered_qty", (0)::numeric) AS "ordered_qty",
    COALESCE("ad"."approved_delivered_qty", (0)::numeric) AS "approved_delivered_qty",
    COALESCE("i"."invoiced_qty", (0)::numeric) AS "invoiced_qty"
   FROM ((("public"."sales_orders" "so"
     LEFT JOIN "ordered" "o" ON (("o"."so_id" = "so"."id")))
     LEFT JOIN "approved_delivery" "ad" ON (("ad"."so_id" = "so"."id")))
     LEFT JOIN "invoiced" "i" ON (("i"."so_id" = "so"."id")));


--
-- Name: so_product_reservation_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."so_product_reservation_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "reservation_id" "uuid" NOT NULL,
    "sales_order_id" "uuid" NOT NULL,
    "sales_order_item_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "quantity_delta" numeric NOT NULL,
    "quantity_after" numeric NOT NULL,
    "delivery_challan_item_id" "uuid",
    "reason" "text" NOT NULL,
    "actor_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "so_product_reservation_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['created'::"text", 'increased'::"text", 'decreased'::"text", 'released'::"text", 'consumed'::"text"]))),
    CONSTRAINT "so_product_reservation_events_quantity_after_check" CHECK (("quantity_after" >= (0)::numeric)),
    CONSTRAINT "so_product_reservation_events_quantity_delta_check" CHECK (("quantity_delta" <> (0)::numeric))
);


--
-- Name: so_product_reservation_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."so_product_reservation_status" AS
 SELECT "soi"."id" AS "sales_order_item_id",
    "soi"."sales_order_id",
    "soi"."product_id",
    "soi"."quantity" AS "ordered_quantity",
    COALESCE(( SELECT "sum"("dci"."quantity") AS "sum"
           FROM ("public"."delivery_challan_items" "dci"
             JOIN "public"."delivery_challans" "dc" ON (("dc"."id" = "dci"."challan_id")))
          WHERE (("dci"."sales_order_item_id" = "soi"."id") AND ("dc"."approval_status" = 'approved'::"public"."dc_approval_status"))), (0)::numeric) AS "delivered_quantity",
    COALESCE("r"."reserved_quantity", (0)::numeric) AS "reserved_quantity",
    GREATEST(("soi"."quantity" - COALESCE(( SELECT "sum"("dci"."quantity") AS "sum"
           FROM ("public"."delivery_challan_items" "dci"
             JOIN "public"."delivery_challans" "dc" ON (("dc"."id" = "dci"."challan_id")))
          WHERE (("dci"."sales_order_item_id" = "soi"."id") AND ("dc"."approval_status" = 'approved'::"public"."dc_approval_status"))), (0)::numeric)), (0)::numeric) AS "remaining_quantity"
   FROM ("public"."sales_order_items" "soi"
     LEFT JOIN "public"."so_product_reservations" "r" ON ((("r"."sales_order_item_id" = "soi"."id") AND ("r"."status" = 'active'::"text"))));


