--
-- Name: trial_balance_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."trial_balance_view" WITH ("security_invoker"='true') AS
 WITH "active_balances" AS (
         SELECT "l"."account_id",
            COALESCE("sum"("l"."debit"), (0)::numeric) AS "total_debit",
            COALESCE("sum"("l"."credit"), (0)::numeric) AS "total_credit"
           FROM ("public"."journal_entry_lines" "l"
             JOIN "public"."journal_entries" "j" ON ((("j"."id" = "l"."journal_entry_id") AND ("j"."is_posted" = true) AND (NOT COALESCE("j"."is_reversed", false)))))
          GROUP BY "l"."account_id"
        )
 SELECT "coa"."code",
    "coa"."name",
    "coa"."name_id",
    "coa"."account_type",
    "coa"."account_group",
    "coa"."normal_balance",
    COALESCE("b"."total_debit", (0)::numeric) AS "total_debit",
    COALESCE("b"."total_credit", (0)::numeric) AS "total_credit",
    (COALESCE("b"."total_debit", (0)::numeric) - COALESCE("b"."total_credit", (0)::numeric)) AS "balance"
   FROM ("public"."chart_of_accounts" "coa"
     LEFT JOIN "active_balances" "b" ON (("b"."account_id" = "coa"."id")))
  WHERE (("coa"."is_header" = false) AND ("coa"."is_active" = true))
  ORDER BY "coa"."code";


