--
-- Name: inventory_v1_conservation_reconciliation _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW "public"."inventory_v1_conservation_reconciliation" WITH ("security_invoker"='true') AS
 SELECT "b"."id" AS "batch_id",
    "b"."batch_number",
    "b"."import_quantity",
    "b"."current_stock",
    "b"."reserved_stock",
    "sum"("l"."effective_quantity") AS "effective_ledger_quantity",
    ("sum"("l"."effective_quantity") - "b"."current_stock") AS "conservation_error",
    (COALESCE("b"."current_stock", (0)::numeric) < (0)::numeric) AS "negative_stock",
    (COALESCE("b"."reserved_stock", (0)::numeric) > COALESCE("b"."current_stock", (0)::numeric)) AS "reserved_exceeds_current"
   FROM ("public"."batches" "b"
     JOIN "public"."inventory_v1_effective_ledger" "l" ON ((("l"."batch_id" = "b"."id") AND "l"."is_effective")))
  GROUP BY "b"."id";


--
-- Name: product_sources_with_stats _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW "public"."product_sources_with_stats" WITH ("security_invoker"='true') AS
 SELECT "ps"."id",
    "ps"."product_id",
    "ps"."supplier_id",
    "ps"."supplier_name",
    "ps"."grade",
    "ps"."country",
    "ps"."remarks",
    "ps"."created_by",
    "ps"."created_at",
    "ps"."updated_at",
    "s"."company_name" AS "supplier_company_name",
    "count"(DISTINCT "psd"."id") AS "document_count",
    "array_agg"(DISTINCT "psd"."doc_type") FILTER (WHERE ("psd"."doc_type" IS NOT NULL)) AS "available_doc_types"
   FROM (("public"."product_sources" "ps"
     LEFT JOIN "public"."suppliers" "s" ON (("ps"."supplier_id" = "s"."id")))
     LEFT JOIN "public"."product_source_documents" "psd" ON (("ps"."id" = "psd"."source_id")))
  GROUP BY "ps"."id", "s"."company_name";


--
-- Name: vw_input_ppn_report _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW "public"."vw_input_ppn_report" WITH ("security_invoker"='true') AS
 WITH "tax_lines" AS (
         SELECT "je"."id" AS "journal_id",
            "je"."entry_date",
            "je"."source_module",
            "je"."reference_id",
            "je"."reference_number",
            "je"."description",
            "je"."created_at",
            "je"."total_debit",
            "sum"(("jel"."debit" - "jel"."credit")) AS "ppn_amount"
           FROM (("public"."journal_entries" "je"
             JOIN "public"."journal_entry_lines" "jel" ON (("jel"."journal_entry_id" = "je"."id")))
             JOIN "public"."chart_of_accounts" "coa" ON (("coa"."id" = "jel"."account_id")))
          WHERE (("je"."is_posted" = true) AND (COALESCE("je"."is_reversed", false) = false) AND (("coa"."code")::"text" = '1150'::"text"))
          GROUP BY "je"."id"
         HAVING ("sum"(("jel"."debit" - "jel"."credit")) > (0)::numeric)
        )
 SELECT "date_trunc"('month'::"text", ("t"."entry_date")::timestamp with time zone) AS "month",
    "t"."entry_date" AS "expense_date",
        CASE
            WHEN (("t"."source_module")::"text" = 'purchase_invoice'::"text") THEN 'Purchase Invoice'::"text"
            WHEN ("fe"."expense_category" = 'pib_import'::"text") THEN 'PIB Import'::"text"
            WHEN ("fe"."expense_category" = 'ppn_import'::"text") THEN 'PPN Import (Legacy)'::"text"
            ELSE 'Supplier Invoice'::"text"
        END AS "document_type",
    COALESCE("pi"."invoice_number", "fe"."invoice_number", ("fe"."voucher_number")::character varying, "t"."reference_number", (("t"."journal_id")::"text")::character varying) AS "reference",
    COALESCE("s"."company_name", '-'::character varying) AS "supplier",
    COALESCE("s"."npwp", '-'::character varying) AS "supplier_npwp",
        CASE
            WHEN ("fe"."expense_category" = 'import_broker'::"text") THEN (COALESCE("fe"."dpp_amount", (0)::numeric) + COALESCE(( SELECT "sum"(COALESCE((NULLIF(("item"."value" ->> 'dpp_amount'::"text"), ''::"text"))::numeric, (0)::numeric)) AS "sum"
               FROM "jsonb_array_elements"(COALESCE("fe"."broker_items", '[]'::"jsonb")) "item"("value")), (0)::numeric))
            ELSE GREATEST(("t"."total_debit" - "t"."ppn_amount"), (0)::numeric)
        END AS "dpp_amount",
    "t"."ppn_amount",
    COALESCE("fe"."description", "pi"."notes", "t"."description") AS "description",
    "t"."created_at",
    COALESCE("fe"."tax_period_id", "pi"."tax_period_id", "date_period"."id") AS "tax_period_id"
   FROM (((("tax_lines" "t"
     LEFT JOIN "public"."finance_expenses" "fe" ON (((("t"."source_module")::"text" = ANY ((ARRAY['expense'::character varying, 'expenses'::character varying])::"text"[])) AND ("fe"."id" = "t"."reference_id"))))
     LEFT JOIN "public"."purchase_invoices" "pi" ON (((("t"."source_module")::"text" = 'purchase_invoice'::"text") AND ("pi"."id" = "t"."reference_id"))))
     LEFT JOIN "public"."suppliers" "s" ON (("s"."id" = COALESCE("fe"."supplier_id", "pi"."supplier_id"))))
     LEFT JOIN "public"."tax_periods" "date_period" ON ((("date_period"."tax_type" = 'PPN'::"text") AND (("t"."entry_date" >= "date_period"."period_start") AND ("t"."entry_date" <= "date_period"."period_end")))))
  ORDER BY "t"."entry_date" DESC;


--
-- Name: vw_output_ppn_report _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW "public"."vw_output_ppn_report" WITH ("security_invoker"='true') AS
 WITH "tax_lines" AS (
         SELECT "je"."id" AS "journal_id",
            "je"."entry_date",
            "je"."source_module",
            "je"."reference_id",
            "je"."reference_number",
            "je"."description",
            "je"."created_at",
            "je"."total_credit",
            "sum"(("jel"."credit" - "jel"."debit")) AS "ppn_amount"
           FROM (("public"."journal_entries" "je"
             JOIN "public"."journal_entry_lines" "jel" ON (("jel"."journal_entry_id" = "je"."id")))
             JOIN "public"."chart_of_accounts" "coa" ON (("coa"."id" = "jel"."account_id")))
          WHERE (("je"."is_posted" = true) AND (COALESCE("je"."is_reversed", false) = false) AND (("coa"."code")::"text" = '2130'::"text"))
          GROUP BY "je"."id"
         HAVING ("sum"(("jel"."credit" - "jel"."debit")) > (0)::numeric)
        )
 SELECT "date_trunc"('month'::"text", ("t"."entry_date")::timestamp with time zone) AS "month",
    "t"."entry_date" AS "invoice_date",
    COALESCE("si"."invoice_number", ("t"."reference_number")::"text", ("t"."journal_id")::"text") AS "invoice_number",
        CASE
            WHEN (("t"."source_module")::"text" = 'correction'::"text") THEN 'Correction'::"text"
            ELSE 'Sales Invoice'::"text"
        END AS "document_type",
    COALESCE("c"."company_name", '-'::"text") AS "customer",
    COALESCE("c"."npwp", '-'::"text") AS "customer_npwp",
    GREATEST(("t"."total_credit" - "t"."ppn_amount"), (0)::numeric) AS "subtotal",
    "t"."ppn_amount",
    ("t"."total_credit")::numeric AS "total_amount",
    "si"."payment_status",
    "t"."created_at",
    COALESCE("si"."tax_period_id", "date_period"."id") AS "tax_period_id"
   FROM ((("tax_lines" "t"
     LEFT JOIN "public"."sales_invoices" "si" ON (("si"."id" = "t"."reference_id")))
     LEFT JOIN "public"."customers" "c" ON (("c"."id" = "si"."customer_id")))
     LEFT JOIN "public"."tax_periods" "date_period" ON ((("date_period"."tax_type" = 'PPN'::"text") AND (("t"."entry_date" >= "date_period"."period_start") AND ("t"."entry_date" <= "date_period"."period_end")))));


--
-- Name: finance_expenses a_post_customs_broker_canonical_insert; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER "a_post_customs_broker_canonical_insert" AFTER INSERT ON "public"."finance_expenses" FOR EACH ROW WHEN ((("new"."expense_category" = 'import_broker'::"text") AND ("new"."approval_status" = 'approved'::"text"))) EXECUTE FUNCTION "public"."post_customs_broker_canonical"();


--
-- Name: finance_expenses a_post_customs_broker_canonical_update; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER "a_post_customs_broker_canonical_update" AFTER UPDATE ON "public"."finance_expenses" FOR EACH ROW WHEN ((("new"."expense_category" = 'import_broker'::"text") AND ("new"."approval_status" = 'approved'::"text") AND (("old"."expense_category" IS DISTINCT FROM "new"."expense_category") OR ("old"."approval_status" IS DISTINCT FROM "new"."approval_status") OR ("old"."amount" IS DISTINCT FROM "new"."amount") OR ("old"."expense_date" IS DISTINCT FROM "new"."expense_date") OR ("old"."description" IS DISTINCT FROM "new"."description") OR (("old"."payment_method")::"text" IS DISTINCT FROM ("new"."payment_method")::"text") OR ("old"."bank_account_id" IS DISTINCT FROM "new"."bank_account_id") OR ("old"."broker_items" IS DISTINCT FROM "new"."broker_items") OR ("old"."ppn_amount" IS DISTINCT FROM "new"."ppn_amount") OR ("old"."pph_amount" IS DISTINCT FROM "new"."pph_amount") OR ("old"."stamp_duty_amount" IS DISTINCT FROM "new"."stamp_duty_amount") OR ("old"."supplier_id" IS DISTINCT FROM "new"."supplier_id")))) EXECUTE FUNCTION "public"."post_customs_broker_canonical"();


