--
-- Name: finance_expenses trigger_auto_post_expense_accounting_update; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER "trigger_auto_post_expense_accounting_update" AFTER UPDATE ON "public"."finance_expenses" FOR EACH ROW WHEN ((("new"."approval_status" = 'approved'::"text") AND ("new"."expense_category" <> 'import_broker'::"text") AND (COALESCE("current_setting"('app.finance_historical_repair'::"text", true), 'off'::"text") <> 'on'::"text") AND (("old"."approval_status" IS DISTINCT FROM "new"."approval_status") OR ("old"."amount" IS DISTINCT FROM "new"."amount") OR ("old"."expense_category" IS DISTINCT FROM "new"."expense_category") OR (("old"."payment_method")::"text" IS DISTINCT FROM ("new"."payment_method")::"text") OR ("old"."bank_account_id" IS DISTINCT FROM "new"."bank_account_id") OR ("old"."ppn_amount" IS DISTINCT FROM "new"."ppn_amount") OR ("old"."pph_amount" IS DISTINCT FROM "new"."pph_amount") OR ("old"."pph_code_id" IS DISTINCT FROM "new"."pph_code_id") OR ("old"."stamp_duty_amount" IS DISTINCT FROM "new"."stamp_duty_amount") OR ("old"."bank_charges_amount" IS DISTINCT FROM "new"."bank_charges_amount") OR ("old"."fixed_asset_account_id" IS DISTINCT FROM "new"."fixed_asset_account_id") OR ("old"."broker_items" IS DISTINCT FROM "new"."broker_items") OR ("old"."description" IS DISTINCT FROM "new"."description") OR ("old"."expense_date" IS DISTINCT FROM "new"."expense_date")))) EXECUTE FUNCTION "public"."auto_post_expense_accounting"();


