--
-- Name: finance_expenses zzz_sync_expense_pph_account_update; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER "zzz_sync_expense_pph_account_update" AFTER UPDATE ON "public"."finance_expenses" FOR EACH ROW WHEN ((("new"."expense_category" <> 'import_broker'::"text") OR ("old"."expense_category" IS DISTINCT FROM "new"."expense_category") OR ("old"."approval_status" IS DISTINCT FROM "new"."approval_status") OR ("old"."amount" IS DISTINCT FROM "new"."amount") OR ("old"."expense_date" IS DISTINCT FROM "new"."expense_date") OR ("old"."description" IS DISTINCT FROM "new"."description") OR (("old"."payment_method")::"text" IS DISTINCT FROM ("new"."payment_method")::"text") OR ("old"."bank_account_id" IS DISTINCT FROM "new"."bank_account_id") OR ("old"."broker_items" IS DISTINCT FROM "new"."broker_items") OR ("old"."ppn_amount" IS DISTINCT FROM "new"."ppn_amount") OR ("old"."pph_amount" IS DISTINCT FROM "new"."pph_amount") OR ("old"."pph_code_id" IS DISTINCT FROM "new"."pph_code_id") OR ("old"."stamp_duty_amount" IS DISTINCT FROM "new"."stamp_duty_amount") OR ("old"."supplier_id" IS DISTINCT FROM "new"."supplier_id"))) EXECUTE FUNCTION "public"."trg_sync_expense_pph_account"();


