--

CREATE POLICY "CRM roles can insert email activities for accessible inquiries" ON "public"."crm_email_activities" FOR INSERT TO "authenticated" WITH CHECK ((("created_by" = ( SELECT "auth"."uid"() AS "uid")) AND (EXISTS ( SELECT 1
   FROM "public"."user_profiles" "up"
  WHERE (("up"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("up"."is_active" = true) AND ("up"."role" = ANY (ARRAY['admin'::"text", 'manager'::"text", 'sales'::"text"]))))) AND (("inquiry_id" IS NULL) OR (EXISTS ( SELECT 1
   FROM "public"."crm_inquiries" "ci"
  WHERE ("ci"."id" = "crm_email_activities"."inquiry_id"))))));


